#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define SPI_BUS_NUM 0
#define SPI_CHIP_SELECT 0
#define SPI_CHANNEL 0
#define GPIO_CE0 8
#define GPIO_MOSI 10
#define GPIO_MISO 9
#define GPIO_SCLK 11

typedef struct {
    struct gpiod_line *ce_line;
    struct gpiod_line *mosi_line;
    struct gpiod_line *miso_line;
    struct gpiod_line *sclk_line;
    struct gpiod_chip *chip;
    struct spi_device *spi_dev;
    int running;
} spi_context;

void handle_signal(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        printf("\nReceived signal %d, shutting down...\n", sig);
        exit(EXIT_SUCCESS);
    }
}

int init_spi(spi_context *ctx) {
    ctx->chip = gpiod_chip_open("/dev/gpiochip0");
    if (!ctx->chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    ctx->ce_line = gpiod_line_get(ctx->chip, GPIO_CE0);
    if (!ctx->ce_line) {
        perror("Failed to get CE0 line");
        gpiod_chip_close(ctx->chip);
        return -1;
    }

    ctx->mosi_line = gpiod_line_get(ctx->chip, GPIO_MOSI);
    if (!ctx->mosi_line) {
        perror("Failed to get MOSI line");
        gpiod_line_put(ctx->ce_line);
        gpiod_chip_close(ctx->chip);
        return -1;
    }

    ctx->miso_line = gpiod_line_get(ctx->chip, GPIO_MISO);
    if (!ctx->miso_line) {
        perror("Failed to get MISO line");
        gpiod_line_put(ctx->ce_line);
        gpiod_line_put(ctx->mosi_line);
        gpiod_chip_close(ctx->chip);
        return -1;
    }

    ctx->sclk_line = gpiod_line_get(ctx->chip, GPIO_SCLK);
    if (!ctx->sclk_line) {
        perror("Failed to get SCLK line");
        gpiod_line_put(ctx->ce_line);
        gpiod_line_put(ctx->mosi_line);
        gpiod_line_put(ctx->miso_line);
        gpiod_chip_close(ctx->chip);
        return -1;
    }

    gpiod_line_set_value(ctx->ce_line, 1);
    gpiod_line_set_value(ctx->mosi_line, 0);
    gpiod_line_set_value(ctx->miso_line, 0);
    gpiod_line_set_value(ctx->sclk_line, 0);

    ctx->spi_dev = spi_open(SPI_BUS_NUM, SPI_CHIP_SELECT, 0);
    if (!ctx->spi_dev) {
        perror("Failed to open SPI device");
        gpiod_line_put(ctx->ce_line);
        gpiod_line_put(ctx->mosi_line);
        gpiod_line_put(ctx->miso_line);
        gpiod_line_put(ctx->sclk_line);
        gpiod_chip_close(ctx->chip);
        return -1;
    }

    return 0;
}

void deinit_spi(spi_context *ctx) {
    if (ctx->spi_dev) {
        spi_close(ctx->spi_dev);
    }

    gpiod_line_put(ctx->ce_line);
    gpiod_line_put(ctx->mosi_line);
    gpiod_line_put(ctx->miso_line);
    gpiod_line_put(ctx->sclk_line);
    gpiod_chip_close(ctx->chip);
}

int read_adc(spi_context *ctx) {
    uint8_t tx[3] = {0x01, 0x80, 0x00};
    uint8_t rx[3] = {0};

    if (spi_transfer(ctx->spi_dev, tx, rx, 3) < 0) {
        perror("SPI transfer failed");
        return -1;
    }

    uint16_t adc_value = (rx[1] << 8) | rx[2];
    return adc_value;
}

int main() {
    spi_context ctx = {0};
    struct sigaction sa;
    int ret;

    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("Failed to set SIGINT handler");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("Failed to set SIGTERM handler");
        return EXIT_FAILURE;
    }

    if (init_spi(&ctx) != 0) {
        fprintf(stderr, "Failed to initialize SPI\n");
        return EXIT_FAILURE;
    }

    ctx.running = 1;
    while (ctx.running) {
        int adc_value = read_adc(&ctx);
        if (adc_value < 0) {
            fprintf(stderr, "ADC read failed, retrying...\n");
            usleep(100000);
            continue;
        }

        time_t now = time(NULL);
        struct tm *tm_now = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_now);

        printf("%s: ADC Value: %d\n", timestamp, adc_value);
        usleep(1000000); // 1 second delay
    }

    deinit_spi(&ctx);
    return EXIT_SUCCESS;
}

