#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define CE_PIN 8
#define FLAME_PIN 4
#define ADC_CHANNEL 0
#define CSV_FILE "flame_data.csv"
#define INTERVAL 1

typedef struct {
    int spi_fd;
    struct gpiod_line *ce_line;
    struct gpiod_line *flame_line;
    FILE *csv_file;
    int running;
} app_state;

void handle_signal(int sig) {
    if (sig == SIGINT) {
        printf("Received SIGINT, shutting down...\n");
    }
    exit(EXIT_SUCCESS);
}

void init_spi(app_state *state) {
    state->spi_fd = open(SPI_DEVICE, O_RDWR | O_NOCTTY | O_SYNC);
    if (state->spi_fd < 0) {
        perror("Failed to open SPI device");
        exit(EXIT_FAILURE);
    }

    struct spi_ioc_transfer spi;
    memset(&spi, 0, sizeof(spi));
    spi.speed_hz = SPI_SPEED;
    spi.mode = SPI_MODE;
    spi.bits_per_word = SPI_BITS_PER_WORD;

    if (ioctl(state->spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("Failed to set SPI speed");
        close(state->spi_fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(state->spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS_PER_WORD) < 0) {
        perror("Failed to set SPI bits per word");
        close(state->spi_fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(state->spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("Failed to set SPI mode");
        close(state->spi_fd);
        exit(EXIT_FAILURE);
    }

    printf("SPI initialized successfully.\n");
}

void init_gpio(app_state *state) {
    struct gpiod_chip *chip;
    chip = gpiod_chip_open("/dev/gpiochip4");
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    state->ce_line = gpiod_line_get(chip, CE_PIN);
    if (!state->ce_line) {
        perror("Failed to get CE GPIO line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(state->ce_line, "CE", GPIOD_LINE_REQUEST_OUTPUT_ACTIVE_LOW)) {
        perror("Failed to request CE GPIO line");
        gpiod_line_put(state->ce_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    state->flame_line = gpiod_line_get(chip, FLAME_PIN);
    if (!state->flame_line) {
        perror("Failed to get FLAME GPIO line");
        gpiod_line_put(state->ce_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_input(state->flame_line, "FLAME", 0)) {
        perror("Failed to request FLAME GPIO line");
        gpiod_line_put(state->ce_line);
        gpiod_line_put(state->flame_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    gpiod_line_set_value(state->ce_line, 1);
    printf("GPIO initialized successfully.\n");
}

void close_gpio(app_state *state) {
    gpiod_line_set_value(state->ce_line, 1);
    gpiod_line_put(state->ce_line);
    gpiod_line_put(state->flame_line);
    gpiod_chip_close(gpiod_line_get_chip(state->flame_line));
}

void close_spi(app_state *state) {
    close(state->spi_fd);
}

void log_data(app_state *state) {
    if (!state->csv_file) {
        printf("CSV file not open, skipping log.\n");
        return;
    }

    struct spi_ioc_transfer spi;
    memset(&spi, 0, sizeof(spi));
    spi.speed_hz = SPI_SPEED;
    spi.mode = SPI_MODE;
    spi.bits_per_word = SPI_BITS_PER_WORD;
    spi.tx_buf = (unsigned long)(&spi);
    spi.rx_buf = (unsigned long)(&spi);
    spi.len = 1;

    uint8_t tx[3] = {1, (ADC_CHANNEL << 4) | 0x80, 0};
    uint8_t rx[3] = {0};

    gpiod_line_set_value(state->ce_line, 0);
    if (ioctl(state->spi_fd, SPI_IOC_MESSAGE(1), &spi) < 0) {
        perror("SPI transfer failed");
        return;
    }

    gpiod_line_set_value(state->ce_line, 1);

    uint16_t adc_value = (rx[1] << 8) | rx[2];
    double voltage = (adc_value / 1023.0) * 3.3;
    double temperature = (voltage - 0.5) * 100.0;

    int flame_detected = gpiod_line_get_value(state->flame_line);

    time_t now = time(NULL);
    struct tm *tm_now = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_now);

    fprintf(state->csv_file, "%s,%d,%f\n", timestamp, flame_detected, temperature);
    fflush(state->csv_file);
}

void open_csv_file(app_state *state) {
    state->csv_file = fopen(CSV_FILE, "a");
    if (!state->csv_file) {
        perror("Failed to open CSV file");
        exit(EXIT_FAILURE);
    }
    fprintf(state->csv_file, "timestamp,flame_detected,temperature\n");
    fflush(state->csv_file);
}

void close_csv_file(app_state *state) {
    if (state->csv_file) {
        fclose(state->csv_file);
    }
}

int main() {
    app_state state = {0};
    state.running = 1;

    signal(SIGINT, handle_signal);

    init_gpio(&state);
    init_spi(&state);
    open_csv_file(&state);

    while (state.running) {
        log_data(&state);
        sleep(INTERVAL);
    }

    close_csv_file(&state);
    close_gpio(&state);
    close_spi(&state);

    return 0;
}

