#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define FLAME_GPIO 4
#define BUZZER_GPIO 27
#define I2C_BUS 1
#define I2C_ADDR 0x48
#define ADC_CHANNEL 0
#define POLL_INTERVAL_MS 100
#define DEBOUNCE_DELAY_MS 50
#define FIRE_THRESHOLD_TEMP 60
#define BUZZER_DURATION_MS 2000
#define LOG_FILE "fire_log.txt"

typedef struct {
    int i2c_fd;
    struct gpiod_line *flame_line;
    struct gpiod_line *buzzer_line;
    FILE *log_file;
    int running;
} app_state;

void handle_sigint(int sig) {
    app_state *state = (app_state *)malloc(sizeof(app_state));
    if (state) {
        state->running = 0;
        free(state);
    }
}

int init_gpio(app_state *state) {
    int ret;

    state->flame_line = gpiod_line_get("gpio", FLAME_GPIO, "flame");
    if (!state->flame_line) {
        fprintf(stderr, "Failed to get flame GPIO line\n");
        return -1;
    }

    ret = gpiod_line_request_output(state->flame_line, "flame_sensor", 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request flame GPIO as output: %s\n", strerror(errno));
        gpiod_line_put(state->flame_line);
        return -1;
    }

    state->buzzer_line = gpiod_line_get("gpio", BUZZER_GPIO, "buzzer");
