    uint8_t config[2] = {0x84, 0x00}; // 128 samples, 16-bit, single-ended, channel 0
    if (write(state->i2c_fd, config, 2) != 2) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }

    usleep(1000); // Wait for conversion

    uint8_t read_buf[2];
    if (read(state->i2c_fd, read_buf, 2) != 2) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }

    *value = (read_buf[0] << 8) | read_buf[1];
    return 0;
}

