void setup_gpio() {
    char gpio_path[64];
    snprintf(gpio_path, sizeof(gpio_path), "%s/gpio%d", GPIO_CHIP, GPIO_PIN);

    gpio_fd = open(gpio_path, O_RDWR);
    if (gpio_fd < 0) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    if (ioctl(gpio_fd, GPIO_GET_LINEHANDLE_IOCTL, &gpio_fd) < 0) {
        perror("Failed to get GPIO line handle");
        close(gpio_fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(gpio_fd, GPIO_LINE_SET_FLAGS, GPIO_LINE_FLAG_OUTPUT) < 0) {
        perror("Failed to set GPIO line as output");
        close(gpio_fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(gpio_fd, GPIO_LINE_SET_VALUE, 0) < 0) {
        perror("Failed to set GPIO line to LOW");
        close(gpio_fd);
        exit(EXIT_FAILURE);
    }
}

void setup_spi() {
    spi_fd = open(SPI_DEVICE, O_RDWR | O_SYNC);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS) < 0) {
        perror("Failed to set SPI bits per word");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }
}

uint16_t read_adc() {
    uint8_t tx[1] = {0x01};  // Start conversion command
    uint8_t rx[1] = {0};

    struct spi_ioc_transfer spi = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 1,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &spi) < 0) {
        perror("SPI transfer failed");
        return 0;
    }

    // Wait for conversion to complete (approx 100ms)
    usleep(100000);

    tx[0] = 0x00;  // Read data command
    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &spi) < 0) {
        perror("SPI transfer failed");
        return 0;
    }

    return (uint16_t)rx[0];
}

