    FILE *file = fopen(FILE_NAME, "a");
    if (file == NULL) {
        perror("Failed to open log file");
        return;
    }

    if (adc_value == 0 || adc_value == 0xFF) {
        fprintf(file, "%s, sensor absent\n", timestamp);
    } else {
        fprintf(file, "%s, %d\n", timestamp, adc_value);
    }

    fclose(file);
}

void control_fan(uint16_t adc_value) {
    if (adc_value > CURRENT_THRESHOLD) {
        if (ioctl(gpio_fd, GPIO_LINE_SET_VALUE, 1) < 0) {
            perror("Failed to set GPIO line to HIGH");
        }
    } else {
        if (ioctl(gpio_fd, GPIO_LINE_SET_VALUE, 0) < 0) {
            perror("Failed to set GPIO line to LOW");
        }
    }
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    setup_gpio();
    setup_spi();

    while (running) {
        uint16_t adc_value = read_adc();
        log_current(adc_value);
        control_fan(adc_value);
        usleep(1000000);  // 1 second interval
    }

    close_resources();
    return 0;
}

