#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>
#include <time.h>
#include <signal.h>
#include <errno.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define SPI_MODE SPI_MODE_0
#define CS_PIN 8
#define D0_PIN 4
#define SCLK_PIN 11
#define MOSI_PIN 10
#define MISO_PIN 9
#define ADC_CHANNEL 0
#define CSV_FILE "flame_data.csv"
#define INTERVAL 1

typedef struct {
    int spi_fd;
    struct gpiod_line *cs_line;
    struct gpiod_line *d0_line;
} hardware_t;

void handle_error(const char *msg) {
    fprintf(stderr, "%s: %s\n", msg, strerror(errno));
    exit(EXIT_FAILURE);
}

void init_gpio(hardware_t *hw) {
    struct gpiod_chip *chip;
    struct gpiod_line *line;

    chip = gpiod_chip_open("/dev/gpiochip4");
    if (!chip) {
        handle_error("Failed to open GPIO chip");
    }

    line = gpiod_line_get(chip, CS_PIN);
    if (!line) {
        handle_error("Failed to get CS GPIO line");
    }
    gpiod_line_request_output(line, "cs", GPIOD_LINE_REQUEST_FLAG_ACTIVE_LOW);
    hw->cs_line = line;

    line = gpiod_line_get(chip, D0_PIN);
    if (!line) {
        handle_error("Failed to get D0 GPIO line");
    }
    gpiod_line_request_input(line, "d0", 0);
    hw->d0_line = line;
}

void release_gpio(hardware_t *hw) {
    gpiod_line_release(hw->cs_line);
    gpiod_line_release(hw->d0_line);
}

void init_spi(hardware_t *hw) {
    hw->spi_fd = open(SPI_DEVICE, O_RDWR);
    if (hw->spi_fd < 0) {
        handle_error("Failed to open SPI device");
    }

    if (ioctl(hw->spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        handle_error("Failed to set SPI mode");
    }

    if (ioctl(hw->spi_fd, SPI_IOC_WR_SPEED_HZ, &SPI_SPEED) < 0) {
        handle_error("Failed to set SPI speed");
    }
}

void release_spi(hardware_t *hw) {
    close(hw->spi_fd);
}

void cs_low(hardware_t *hw) {
    gpiod_line_set_value(hw->cs_line, 0);
}

void cs_high(hardware_t *hw) {
    gpiod_line_set_value(hw->cs_line, 1);
}

int read_adc(hardware_t *hw) {
    uint8_t tx[3];
    uint8_t rx[3];
    struct spi_ioc_transfer transfer;
    int ret;

    tx[0] = 1 << 7 | (ADC_CHANNEL & 0x0F) << 4;
    tx[1] = 0;
    tx[2] = 0;

    memset(&transfer, 0, sizeof(transfer));
    transfer.tx_buf = (unsigned long)tx;
    transfer.rx_buf = (unsigned long)rx;
    transfer.len = 3;
    transfer.speed_hz = SPI_SPEED;
    transfer.delay_usecs = 0;

    cs_low(hw);
    ret = ioctl(hw->spi_fd, SPI_IOC_MESSAGE(1), &transfer);
    cs_high(hw);

    if (ret < 0) {
        handle_error("SPI transfer failed");
    }

    return (rx[1] << 8 | rx[2]) >> 4;
}

int read_flame(hardware_t *hw) {
    return gpiod_line_get_value(hw->d0_line);
}

void log_data(hardware_t *hw, FILE *fp, time_t timestamp) {
    int flame = read_flame(hw);
    int adc_value = read_adc(hw);

    if (flame == -1 || adc_value == -1) {
        fprintf(stderr, "Sensor error: flame=%d, adc=%d\n", flame, adc_value);
        return;
    }

    fprintf(fp, "%ld,%d,%d\n", timestamp, flame, adc_value);
}

void signal_handler(int sig) {
    printf("\nCaught signal %d, exiting...\n", sig);
    exit(EXIT_SUCCESS);
}

int main() {
    hardware_t hw;
    FILE *fp;
    time_t last_time = 0;
    struct sigaction sa;

    init_gpio(&hw);
    init_spi(&hw);

    fp = fopen(CSV_FILE, "w");
    if (!fp) {
        handle_error("Failed to open CSV file");
    }

    fprintf(fp, "timestamp,flame,temperature\n");
    fclose(fp);
    fp = fopen(CSV_FILE, "a");

    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        handle_error("Failed to set signal handler");
    }

    while (1) {
        time_t current_time = time(NULL);
        if (current_time - last_time >= INTERVAL) {
            last_time = current_time;

            FILE *fp_tmp = fopen(CSV_FILE, "a");
            if (!fp_tmp) {
                handle_error("Failed to open CSV file for appending");
            }

            log_data(&hw, fp_tmp, current_time);
            fclose(fp_tmp);
        }

        usleep(100000); // 100ms delay to prevent CPU overuse
    }

    release_gpio(&hw);
    release_spi(&hw);
    fclose(fp);
    return 0;
}

