#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>
#include <time.h>

#define I2C_BUS "/dev/i2c-1"
#define SENSOR_ADDR 0x28
#define OX_REGISTER 0x00
#define RED_REGISTER 0x02
#define LOG_FILE "co_log.txt"
#define ALERT_FILE "alert_log.txt"
#define ALERT_THRESHOLD 25.0
#define LOG_INTERVAL 5.0

typedef struct {
    int i2c_fd;
    FILE *log_file;
    FILE *alert_file;
    int running;
} app_state;

void handle_signal(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        printf("Received signal, shutting down...\n");
        app_state *state = (app_state *)malloc(sizeof(app_state));
        state->running = 0;
        free(state);
    }
}

void init_i2c(app_state *state) {
    state->i2c_fd = open(I2C_BUS, O_RDWR);
    if (state->i2c_fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    if (ioctl(state->i2c_fd, I2C_SLAVE, SENSOR_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(state->i2c_fd);
        exit(EXIT_FAILURE);
    }
}

void read_sensor_data(app_state *state, uint8_t *data) {
    if (read(state->i2c_fd, data, 4) != 4) {
        perror("I2C read error");
        exit(EXIT_FAILURE);
    }
}

void convert_to_ppm(uint16_t adc_value, double *ppm) {
    *ppm = (double)adc_value * 0.00000125; // Conversion factor based on sensor datasheet
}

void log_co_value(double ppm) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        return;
    }

    time_t t = time(NULL);
    struct tm *tm_info = localtime(&t);
    char buffer[80];
    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(log_file, "%s, %.2f ppm\n", buffer, ppm);
    fclose(log_file);
}

void log_alert(double ppm) {
    FILE *alert_file = fopen(ALERT_FILE, "a");
    if (!alert_file) {
        perror("Failed to open alert log file");
        return;
    }

    time_t t = time(NULL);
    struct tm *tm_info = localtime(&t);
    char buffer[80];
    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(alert_file, "%s, CO concentration %.2f ppm exceeded threshold of 25 ppm\n", buffer, ppm);
    fclose(alert_file);
}

void cleanup(app_state *state) {
    if (state->i2c_fd >= 0) {
        close(state->i2c_fd);
    }

    if (state->log_file) {
        fclose(state->log_file);
    }

    if (state->alert_file) {
        fclose(state->alert_file);
    }
}

int main() {
    app_state state = {0};
    state.running = 1;

    // Set up signal handling
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Initialize I2C
    init_i2c(&state);

    // Open log files
    state.log_file = fopen(LOG_FILE, "a");
    if (!state.log_file) {
        perror("Failed to open log file");
        cleanup(&state);
        exit(EXIT_FAILURE);
    }

    state.alert_file = fopen(ALERT_FILE, "a");
    if (!state.alert_file) {
        perror("Failed to open alert log file");
        cleanup(&state);
        exit(EXIT_FAILURE);
    }

    printf("Starting CO monitoring...\n");

    while (state.running) {
