#define I2C_BUS 1
#define I2C_ADDR_MIC1 0x48
#define I2C_ADDR_MIC2 0x49
#define GPIO_OUT_PIN 2
#define GPIO_IN_PIN 3
#define SAMPLE_INTERVAL_MS 100
#define LOG_FILE "audio_log.txt"
#define ERROR_VALUE -999.0

typedef struct {
    int fd;
    int gpio_out;
    int gpio_in;
} I2C_GPIO_CTX;

void handle_signal(int sig) {
    (void)sig;
    exit(EXIT_SUCCESS);
}

void i2c_gpio_init(I2C_GPIO_CTX *ctx) {
    ctx->fd = open("/dev/i2c-1", O_RDWR);
    if (ctx->fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    if (ioctl(ctx->fd, I2C_SLAVE, I2C_ADDR_MIC1) < 0) {
        perror("Failed to set I2C slave address for MIC1");
        close(ctx->fd);
        exit(EXIT_FAILURE);
    }

    ctx->gpio_out = open("/dev/gpiochip0", O_RDWR);
    if (ctx->gpio_out < 0) {
        perror("Failed to open GPIO chip");
        close(ctx->fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(ctx->gpio_out, GPIO_GET_LINEHANDLE_IOCTL, &ctx->gpio_in) < 0) {
        perror("Failed to get line handle for GPIO_IN_PIN");
        close(ctx->gpio_out);
        close(ctx->fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(ctx->gpio_in.linehandle, GPIO_LINE_SET_FLAGS, GPIO_LINE_FLAG_OUTPUT) < 0) {
        perror("Failed to set GPIO_OUT_PIN as output");
        close(ctx->gpio_in.linehandle);
        close(ctx->gpio_out);
        close(ctx->fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(ctx->gpio_in.linehandle, GPIO_LINE_SET_FLAGS, GPIO_LINE_FLAG_INPUT) < 0) {
        perror("Failed to set GPIO_IN_PIN as input");
        close(ctx->gpio_in.linehandle);
        close(ctx->gpio_out);
        close(ctx->fd);
        exit(EXIT_FAILURE);
    }
}

void i2c_gpio_deinit(I2C_GPIO_CTX *ctx) {
    if (ctx->gpio_in.linehandle > 0) {
        ioctl(ctx->gpio_in.linehandle, GPIO_LINE_SET_FLAGS, 0);
        close(ctx->gpio_in.linehandle);
    }
    close(ctx->gpio_out);
    close(ctx->fd);
}

int read_adc(I2C_GPIO_CTX *ctx, int addr) {
    if (ioctl(ctx->fd, I2C_SLAVE, addr) < 0) {
        perror("Failed to set I2C slave address");
        return -1;
    }

    unsigned char reg = 0x00;
    if (write(ctx->fd, &reg, 1) < 0) {
        perror("Failed to write to I2C register");
        return -1;
    }

    unsigned char buffer[2];
    if (read(ctx->fd, buffer, 2) < 0) {
        perror("Failed to read from I2C");
        return -1;
    }

    int value = (buffer[0] << 8) | buffer[1];
    return value;
}

double convert_to_dB(int adc_value) {
    double v = (adc_value * 3.3) / 4096.0;
    return 20 * log10(v / 0.0005);
}

void log_sample(double mic1_db, double mic2_db) {
    time_t now = time(NULL);
    struct tm *tm_now = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_now);

    FILE *file = fopen(LOG_FILE, "a");
    if (file == NULL) {
        perror("Failed to open log file");
        return;
    }

    fprintf(file, "%s,%.2f,%.2f\n", timestamp, mic1_db, mic2_db);
    fclose(file);
}

int main() {
    I2C_GPIO_CTX ctx;
    i2c_gpio_init(&ctx);

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (1) {
        usleep(SAMPLE_INTERVAL_MS * 1000);

        int mic1_adc = read_adc(&ctx, I2C_ADDR_MIC1);
        int mic2_adc = read_adc(&ctx, I2C_ADDR_MIC2);

        double mic1_db = (mic1_adc == -1) ? ERROR_VALUE : convert_to_dB(mic1_adc);
        double mic2_db = (mic2_adc == -1) ? ERROR_VALUE : convert_to_dB(mic2_adc);

        log_sample(mic1_db, mic2_db);
    }

    i2c_gpio_deinit(&ctx);
    return 0;
}

