#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>
#include <signal.h>
#include <time.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_SPEED 1000000
#define SPI_BITS 8
#define SPI_DELAY 0

#define MIC1_CS_PIN 8
#define MIC2_CS_PIN 9
#define LED_PIN 27
#define HIGH_THRESHOLD 1000
#define SAMPLE_WINDOW_MS 100
#define SAMPLE_RATE_MS 1
#define LED_ON_DURATION_MS 500

typedef struct {
    int spi_fd;
    struct gpiod_line *mic1_cs;
    struct gpiod_line *mic2_cs;
    struct gpiod_line *led;
    FILE *csv_file;
    int running;
} app_state;

void handle_sigint(int sig) {
    app_state *state = (app_state *)malloc(sizeof(app_state));
    if (state) {
        state->running = 0;
    }
}

void init_gpio(app_state *state) {
    int err;

    state->mic1_cs = gpiod_line_get("bcm2835gpio", MIC1_CS_PIN, "mic1_cs");
    if (!state->mic1_cs) {
        fprintf(stderr, "Failed to get mic1_cs line\n");
        exit(EXIT_FAILURE);
    }
    err = gpiod_line_request_output(state->mic1_cs, "mic1_cs", 1);
    if (err) {
        fprintf(stderr, "Failed to request mic1_cs output\n");
        exit(EXIT_FAILURE);
    }

    state->mic2_cs = gpiod_line_get("bcm2835gpio", MIC2_CS_PIN, "mic2_cs");
    if (!state->mic2_cs) {
        fprintf(stderr, "Failed to get mic2_cs line\n");
        exit(EXIT_FAILURE);
    }
    err = gpiod_line_request_output(state->mic2_cs, "mic2_cs", 1);
    if (err) {
        fprintf(stderr, "Failed to request mic2_cs output\n");
        exit(EXIT_FAILURE);
    }

    state->led = gpiod_line_get("bcm2835gpio", LED_PIN, "led");
    if (!state->led) {
        fprintf(stderr, "Failed to get led line\n");
        exit(EXIT_FAILURE);
    }
    err = gpiod_line_request_output(state->led, "led", 0);
    if (err) {
        fprintf(stderr, "Failed to request led output\n");
        exit(EXIT_FAILURE);
    }
}

void deinit_gpio(app_state *state) {
    if (state->led) {
        gpiod_line_release(state->led);
    }
    if (state->mic2_cs) {
        gpiod_line_release(state->mic2_cs);
    }
    if (state->mic1_cs) {
        gpiod_line_release(state->mic1_cs);
    }
}

void init_spi(app_state *state) {
    state->spi_fd = open(SPI_DEVICE, O_RDWR | O_NOCTTY | O_NDELAY);
    if (state->spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device\n");
        exit(EXIT_FAILURE);
    }

    struct spi_ioc_transfer spi;
    memset(&spi, 0, sizeof(spi));
    spi.speed_hz = SPI_SPEED;
    spi.bits_per_word = SPI_BITS;
    spi.delay_usecs = SPI_DELAY;
    spi.mode = SPI_MODE;

    if (ioctl(state->spi_fd, SPI_IOC_MESSAGE(1), &spi) < 0) {
        fprintf(stderr, "SPI initialization failed\n");
        close(state->spi_fd);
        exit(EXIT_FAILURE);
    }
}

void deinit_spi(app_state *state) {
    close(state->spi_fd);
}

void write_cs_line(app_state *state, int pin, int value) {
    if (value) {
        gpiod_line_set_value(state->mic1_cs, 1);
        gpiod_line_set_value(state->mic2_cs, 1);
    } else {
        gpiod_line_set_value(state->mic1_cs, 0);
        gpiod_line_set_value(state->mic2_cs, 0);
    }
}

uint16_t read_adc(app_state *state, int cs_pin) {
    int cs_line;
    if (cs_pin == MIC1_CS_PIN) {
        cs_line = 0;
    } else {
        cs_line = 1;
    }

    write_cs_line(state, cs_line, 0);

    uint8_t tx[1] = {0x01};
    uint8_t rx[2] = {0};

    struct spi_ioc_transfer spi;
    memset(&spi, 0, sizeof(spi));
    spi.tx_buf = (unsigned long)tx;
    spi.rx_buf = (unsigned long)rx;
    spi.len = 1;
    spi.delay_usecs = SPI_DELAY;
    spi.speed_hz = SPI_SPEED;
    spi.bits_per_word = SPI_BITS;

    if (ioctl(state->spi_fd, SPI_IOC_MESSAGE(1), &spi) < 0) {
        fprintf(stderr, "SPI read failed\n");
        return 0;
    }

    write_cs_line(state, cs_line, 1);

    return (rx[0] << 8) | rx[1];
}

void log_data(app_state *state, double mic1_rms, double mic2_rms) {
    if (!state->csv_file) {
        return;
    }

    time_t now = time(NULL);
    struct tm *tm_now = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_now);

    fprintf(state->csv_file, "%s,%.2f,%.2f\n", timestamp, mic1_rms, mic2_rms);
    fflush(state->csv_file);
}

void trigger_led(app_state *state, int on) {
    if (on) {
        gpiod_line_set_value(state->led, 1);
    } else {
        gpiod_line_set_value(state->led, 0);
    }
}

void compute_rms(int16_t *samples, int count) {
    double sum = 0.0;
    for (int i = 0; i < count; i++) {
        sum += (double)samples[i] * (double)samples[i];
    }
    double rms = sqrt(sum / count);
    printf("RMS: %.2f\n", rms);
}

int main() {
    app_state state = {0};

    signal(SIGINT, handle_sigint);

    init_gpio(&state);
    init_spi(&state);

    state.csv_file = fopen("audio_events.csv", "w");
    if (!state.csv_file) {
        fprintf(stderr, "Failed to open CSV file\n");
        deinit_gpio(&state);
        deinit_spi(&state);
        exit(EXIT_FAILURE);
    }

    fprintf(state.csv_file, "timestamp,mic1_rms,mic2_rms\n");
    fflush(state.csv_file);

    int sample_count = 0;
    int sample_window = 100;
    int high_threshold = HIGH_THRESHOLD;
    int led_on = 0;

    while (state.running) {
        int16_t mic1_samples[sample_window];
        int16_t mic2_samples[sample_window];

        for (int i = 0; i < sample_window; i++) {
            mic1_samples[i] = read_adc(&state, MIC1_CS_PIN);
            mic2_samples[i] = read_adc(&state, MIC2_CS_PIN);
            usleep(SAMPLE_RATE_MS * 1000);
        }

        double mic1_rms = 0.0;
        double mic2_rms = 0.0;

        for (int i = 0; i < sample_window; i++) {
            mic1_rms += (double)mic1_samples[i] * (double)mic1_samples[i];
            mic2_rms += (double)mic2_samples[i] * (double)mic2_samples[i];
        }

        mic1_rms = sqrt(mic1_rms / sample_window);
        mic2_rms = sqrt(mic2_rms / sample_window);

        log_data(&state, mic1_rms, mic2_rms);

        if (mic1_rms > high_threshold || mic2_rms > high_threshold) {
            if (!led_on) {
                trigger_led(&state, 1);
                led_on = 1;
            }
        } else {
            if (led_on) {
                trigger_led(&state, 0);
                led_on = 0;
            }
        }

        usleep(SAMPLE_RATE_MS * 1000);
    }

    trigger_led(&state, 0);
    fclose(state.csv_file);
    deinit_gpio(&state);
    deinit_spi(&state);

    return 0;
}

