#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS 1
#define I2C_ADDR 0x29
#define TCS34725_ID_REGISTER 0x12
#define TCS34725_ID_VALUE 0x44
#define MAX_CONSECUTIVE_FAILURES 3
#define LOG_FILE "color_log.csv"

typedef struct {
    int i2c_fd;
    int consecutive_failures;
    int running;
} app_state;

void handle_signal(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        app_state *state = (app_state *)malloc(sizeof(app_state));
        if (state) {
            state->running = 0;
            free(state);
        }
    }
}

void cleanup(app_state *state) {
    if (state->i2c_fd >= 0) {
        close(state->i2c_fd);
    }
    if (state->running) {
        FILE *log_file = fopen(LOG_FILE, "a");
        if (log_file) {
            fclose(log_file);
        }
    }
    free(state);
}

void log_data(FILE *log_file, int clear, int red, int green, int blue) {
    time_t now;
    struct tm *timeinfo;
    char buffer[80];

    time(&now);
    timeinfo = localtime(&now);
    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(log_file, "%s,%d,%d,%d,%d\n", buffer, clear, red, green, blue);
}

int i2c_read_word(int fd, uint8_t reg) {
    uint8_t buffer[2];
    int ret;

    buffer[0] = reg;
    ret = write(fd, buffer, 1);
    if (ret != 1) {
        fprintf(stderr, "I2C write failed: %d\n", ret);
        return -1;
    }

    usleep(100); // Wait for data to be ready

    ret = read(fd, buffer, 2);
    if (ret != 2) {
        fprintf(stderr, "I2C read failed: %d\n", ret);
        return -1;
    }

    return (buffer[0] << 8) | buffer[1];
}

int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buffer[2];
    buffer[0] = reg;
    buffer[1] = value;
    int ret = write(fd, buffer, 2);
    if (ret != 2) {
        fprintf(stderr, "I2C write failed: %d\n", ret);
        return -1;
    }
    return 0;
}

int init_sensor(int fd) {
    int id = i2c_read_word(fd, TCS34725_ID_REGISTER);
    if (id != TCS34725_ID_VALUE) {
        fprintf(stderr, "Sensor ID mismatch: expected 0x%02X, got 0x%02X\n", TCS34725_ID_VALUE, id);
        return -1;
    }

    // Enable the sensor
    i2c_write_byte(fd, 0x80, 0x03); // Power On
    usleep(3000); // Wait at least 3ms after power-on

    // Set integration time to 2.4ms and gain to 1x
    i2c_write_byte(fd, 0x81, 0x00); // 2.4ms, 1x gain
    i2c_write_byte(fd, 0x82, 0x00); // 2.4ms, 1x gain

    return 0;
}

int main() {
    app_state *state = (app_state *)malloc(sizeof(app_state));
    if (!state) {
        fprintf(stderr, "Memory allocation failed\n");
        return 1;
    }

    state->i2c_fd = -1;
    state->consecutive_failures = 0;
    state->running = 1;

    // Open I2C bus
    char i2c_bus_path[32];
    snprintf(i2c_bus_path, sizeof(i2c_bus_path), "/dev/i2c-%d", I2C_BUS);
    state->i2c_fd = open(i2c_bus_path, O_RDWR);
    if (state->i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %d: %s\n", I2C_BUS, strerror(errno));
        cleanup(state);
        return 1;
    }

    // Set I2C address
    if (ioctl(state->i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C address: %s\n", strerror(errno));
        cleanup(state);
        return 1;
    }

    // Initialize sensor
    if (init_sensor(state->i2c_fd) < 0) {
        cleanup(state);
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        cleanup(state);
        return 1;
    }

    // Write header if file is empty
    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "YYYY-MM-DD HH:MM:SS,clear,red,green,blue\n");
    }

    // Main loop
    while (state->running) {
        int clear, red, green, blue;
        int failures = 0;

        // Read clear channel
        clear = i2c_read_word(state->i2c_fd, 0x14);
        if (clear < 0) {
            failures++;
        }

        // Read red channel
        red = i2c_read_word(state->i2c_fd, 0x16);
        if (red < 0) {
            failures++;
        }

        // Read green channel
        green = i2c_read_word(state->i2c_fd, 0x18);
        if (green < 0) {
            failures++;
        }

        // Read blue channel
        blue = i2c_read_word(state->i2c_fd, 0x1A);
        if (blue < 0) {
            failures++;
        }

        if (failures > 0) {
            state->consecutive_failures++;
            if (state->consecutive_failures >= MAX_CONSECUTIVE_FAILURES) {
