#define ADC_TO_AMPERES 0.015625

typedef struct {
    int spi_fd;
    struct gpiod_line *ce_line;
    struct gpiod_line *shutdown_line;
    FILE *log_file;
    int log_initialized;
} app_state;

void handle_signal(int signum, siginfo_t *info, void *context) {
    (void)info;
    (void)context;
    if (signum == SIGINT || signum == SIGTERM) {
        printf("Caught signal %d, shutting down...\n", signum);
        exit(EXIT_SUCCESS);
    }
}

void init_gpio(app_state *state) {
    int ret;

    state->ce_line = gpiod_line_get("bcm2708", GPIO_CE, "ce");
    if (!state->ce_line) {
        fprintf(stderr, "Failed to get CE GPIO line\n");
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_request_output(state->ce_line, "ce", 1);
    if (ret < 0) {
        fprintf(stderr, "Failed to request CE GPIO line: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    state->shutdown_line = gpiod_line_get("bcm2708", GPIO_SHUTDOWN_PIN, "shutdown");
    if (!state->shutdown_line) {
        fprintf(stderr, "Failed to get shutdown GPIO line\n");
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_request_output(state->shutdown_line, "shutdown", 1);
    if (ret < 0) {
        fprintf(stderr, "Failed to request shutdown GPIO line: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    gpiod_line_set_value(state->shutdown_line, 1);
}

void release_gpio(app_state *state) {
    gpiod_line_release(state->ce_line);
    gpiod_line_release(state->shutdown_line);
}

void init_spi(app_state *state) {
    state->spi_fd = open(SPI_DEVICE, O_RDWR | O_NOCTTY | O_SYNC);
    if (state->spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    if (ioctl(state->spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        fprintf(stderr, "Failed to set SPI mode: %s\n", strerror(errno));
        close(state->spi_fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(state->spi_fd, SPI_IOC_WR_SPEED_HZ, &SPI_SPEED) < 0) {
        fprintf(stderr, "Failed to set SPI speed: %s\n", strerror(errno));
        close(state->spi_fd);
        exit(EXIT_FAILURE);
    }
}

void release_spi(app_state *state) {
    close(state->spi_fd);
}

void init_log(app_state *state) {
    state->log_file = fopen("current_log.csv", "a");
    if (!state->log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    state->log_initialized = 0;
}

void release_log(app_state *state) {
    if (state->log_file) {
        fclose(state->log_file);
    }
}

int read_adc(app_state *state) {
    int ret;
    unsigned char tx[3];
    unsigned char rx[3];
    struct spi_ioc_transfer spi;
    int retries = 0;

    tx[0] = 1 << 7; // Start bit
    tx[1] = (ADC_CHANNEL << 4) | 0x01; // Channel and single-ended
    tx[2] = 0;

    do {
        memset(&spi, 0, sizeof(spi));
        spi.tx_buf = (unsigned long)tx;
        spi.rx_buf = (unsigned long)rx;
        spi.len = 3;
        spi.speed_hz = SPI_SPEED;
        spi.delay_usecs = 0;
        spi.bits_per_word = 8;

        ret = ioctl(state->spi_fd, SPI_IOC_MESSAGE(1), &spi);
        if (ret < 0) {
            fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
            retries++;
            if (retries >= MAX_RETRIES) {
                return -1;
            }
            usleep(100000); // 100ms delay
        }
    } while (ret < 0 && retries < MAX_RETRIES);

    if (ret < 0) {
        return -1;
    }

    int adc_value = (rx[1] << 8) | rx[2];
    return adc_value;
}

double adc_to_ampers(app_state *state, int adc_value) {
    double voltage = (adc_value * ADC_REF_VOLTAGE) / ADC_RESOLUTION;
    return voltage * ADC_TO_AMPERES;
}

void log_current(app_state *state, double current) {
    struct timeval tv;
    char timestamp[30];

    gettimeofday(&tv, NULL);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&tv.tv_sec));

    if (!state->log_initialized) {
        fprintf(state->log_file, "Timestamp,Current (A)\n");
        state->log_initialized = 1;
    }

    fprintf(state->log_file, "%s,%.6f\n", timestamp, current);
    fflush(state->log_file);
}

void handle_over_current(app_state *state, double current) {
    if (current > MAX_CURRENT) {
        gpiod_line_set_value(state->shutdown_line, 0);
        fprintf(stderr, "Over-current detected: %.2f A. Disabling motor.\n", current);
        log_current(state, current);

        usleep(1000000); // Wait 1 second
        gpiod_line_set_value(state->shutdown_line, 1);
        fprintf(stderr, "Motor re-enabled after over-current event.\n");
    }
}

int main() {
    app_state state = {0};
    struct sigaction sa;
    int adc_value;
    double current;
    int ret;

    // Set up signal handling
    sa.sa_flags = SA_SIGINFO;
    sa.sa_sigaction = handle_signal;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set up signal handler: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    init_gpio(&state);
    init_spi(&state);
    init_log(&state);

    while (1) {
        adc_value = read_adc(&state);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value, retrying...\n");
            continue;
        }

        current = adc_to_ampers(&state, adc_value);
        handle_over_current(&state, current);
        log_current(&state, current);

        usleep(1000000); // 1 second delay
    }

    release_log(&state);
    release_spi(&state);
    release_gpio(&state);

    return 0;
}
