    STATE_I2C_ERROR,
    STATE_FILE_ERROR
} state_t;

typedef struct {
    int i2c_fd;
    FILE *log_file;
    state_t state;
} app_context_t;

void handle_signal(int signum) {
    // Clean up and exit
    if (signum == SIGINT || signum == SIGTERM) {
        printf("Caught signal %d, cleaning up...\n", signum);
        exit(EXIT_SUCCESS);
    }
}

void log_error(const char *message, int error_code) {
    fprintf(stderr, "%s: error %d\n", message, error_code);
}

void close_i2c_handle(app_context_t *ctx) {
    if (ctx->i2c_fd >= 0) {
        close(ctx->i2c_fd);
        ctx->i2c_fd = -1;
    }
}

void close_log_file(app_context_t *ctx) {
    if (ctx->log_file != NULL) {
        fclose(ctx->log_file);
        ctx->log_file = NULL;
    }
}

void cleanup(app_context_t *ctx) {
    close_i2c_handle(ctx);
    close_log_file(ctx);
}

int open_i2c_bus(int bus) {
    char i2c_bus_path[32];
    snprintf(i2c_bus_path, sizeof(i2c_bus_path), "/dev/i2c-%d", bus);

    int fd = open(i2c_bus_path, O_RDWR);
    if (fd < 0) {
        log_error("Failed to open I2C bus", errno);
        return -1;
    }

    if (ioctl(fd, I2C_TEN, 0) < 0) {
        log_error("Failed to set I2C to 10-bit addressing", errno);
        close(fd);
        return -1;
    }

    return fd;
}

int read_i2c_register(int fd, uint8_t reg, uint16_t *value) {
    uint8_t buffer[2];
    buffer[0] = reg;
    if (write(fd, buffer, 1) < 0) {
        log_error("Failed to write I2C register", errno);
        return -1;
    }

    if (read(fd, buffer, 2) < 0) {
        log_error("Failed to read I2C register", errno);
        return -1;
    }

    *value = (buffer[0] << 8) | buffer[1];
    return 0;
}

void write_csv_line(FILE *file, const char *timestamp, double kpa) {
    if (fprintf(file, "%s,%f\n", timestamp, kpa) < 0) {
        log_error("Failed to write CSV line", errno);
    }
}

void generate_timestamp(char *buffer, size_t size) {
    time_t now = time(NULL);
    struct tm *tm_info = gmtime(&now);
    if (tm_info == NULL) {
        snprintf(buffer, size, "ERROR");
        return;
    }
    strftime(buffer, size, "%Y-%m-%dT%H:%M:%S", tm_info);
}

int main() {
    app_context_t ctx = { .i2c_fd = -1, .log_file = NULL, .state = STATE_OK };

    // Set up signal handling
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Open I2C bus
    ctx.i2c_fd = open_i2c_bus(I2C_BUS);
    if (ctx.i2c_fd < 0) {
        log_error("I2C bus open failed", errno);
        cleanup(&ctx);
        return EXIT_FAILURE;
    }

    // Open log file
    ctx.log_file = fopen(LOG_FILE, "a");
    if (ctx.log_file == NULL) {
        log_error("Failed to open log file", errno);
        cleanup(&ctx);
        return EXIT_FAILURE;
    }

    // Write header if file is empty
    if (fseek(ctx.log_file, 0, SEEK_SET) == 0) {
        if (fgetc(ctx.log_file) != EOF) {
            // File is not empty, skip header
            fseek(ctx.log_file, 0, SEEK_END);
        }
    }

    if (fputs(CSV_HEADER, ctx.log_file) < 0) {
        log_error("Failed to write CSV header", errno);
        cleanup(&ctx);
        return EXIT_FAILURE;
    }

    // Main loop
    while (1) {
        uint16_t pout = 0;
        if (read_i2c_register(ctx.i2c_fd, MLX90817_REGISTER_POUT, &pout) < 0) {
            ctx.state = STATE_I2C_ERROR;
            log_error("I2C read failed", errno);
            // Continue without logging
            usleep(1000000); // 1 second
            continue;
        }

        // Convert pressure to kPa
        double kpa = (double)pout * 0.001; // Assuming 1 LSB = 1 kPa

        // Generate timestamp
        char timestamp[30];
        generate_timestamp(timestamp, sizeof(timestamp));

        // Write to log
        write_csv_line(ctx.log_file, timestamp, kpa);

        // Flush log file
        if (fflush(ctx.log_file) < 0) {
            log_error("Failed to flush log file", errno);
        }

        // Sleep for 1 second
        usleep(1000000);
    }

    // Cleanup on exit
    cleanup(&ctx);
    return EXIT_SUCCESS;
}

