#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS "/dev/i2c-1"
#define ADS1115_ADDR 0x48
#define MLX90834_ADDR 0x1D
#define ADS1115_CONFIG 0x01
#define ADS1115_MUX 0x00
#define ADS1115_GAIN 0x00
#define ADS1115_MODE 0x00
#define ADS1115_DATA 0x00
#define ADS1115_CONVERSION_DELAY 100000 // 100ms in microseconds

#define LED_PIN 17
#define PRESSURE_THRESHOLD 105.0f
#define MAX_RETRIES 3
#define UPDATE_INTERVAL 1000 // 1 second in milliseconds

typedef struct {
    int i2c_fd;
    struct gpiod_line *led_line;
} app_state;

void handle_signal(int sig) {
    (void)sig;
    printf("\nCleaning up...\n");
    if (app_state.i2c_fd >= 0) {
        close(app_state.i2c_fd);
    }
    if (app_state.led_line) {
        gpiod_line_release(app_state.led_line);
    }
    exit(EXIT_SUCCESS);
}

int i2c_read_retries(int fd, uint8_t reg, uint16_t *value, int max_retries) {
    int retries = 0;
    int ret;
    uint8_t buf[2];

    do {
        ret = ioctl(fd, I2C_RDWR, (struct i2c_msg *) & (struct i2c_msg) {
            .flags = 0,
            .addr = ADS1115_ADDR,
            .len = 1,
            .buf = &reg
        });
        if (ret < 0) {
            perror("I2C write");
            return -1;
        }

        ret = ioctl(fd, I2C_RDWR, (struct i2c_msg *) & (struct i2c_msg) {
            .flags = I2C_M_RD,
            .addr = ADS1115_ADDR,
            .len = 2,
            .buf = buf
        });
        if (ret < 0) {
            perror("I2C read");
            return -1;
        }

        *value = (buf[0] << 8) | buf[1];
        usleep(ADS1115_CONVERSION_DELAY);
        retries++;
    } while (retries < max_retries && ret < 0);

    return 0;
}

void read_ads1115(int fd, uint16_t *ain0, uint16_t *ain1) {
    uint16_t val0, val1;

    if (i2c_read_retries(fd, ADS1115_MUX | 0x80, &val0, MAX_RETRIES) < 0) {
        fprintf(stderr, "Failed to read AIN0\n");
        exit(EXIT_FAILURE);
    }

    if (i2c_read_retries(fd, ADS1115_MUX | 0xC0, &val1, MAX_RETRIES) < 0) {
        fprintf(stderr, "Failed to read AIN1\n");
        exit(EXIT_FAILURE);
    }

    *ain0 = val0;
    *ain1 = val1;
}

void read_mlx90834(int fd, float *pressure, float *temperature) {
    uint16_t raw_pressure, raw_temperature;

    if (i2c_read_retries(fd, 0x00, &raw_pressure, MAX_RETRIES) < 0) {
        fprintf(stderr, "Failed to read MLX90834 pressure\n");
        exit(EXIT_FAILURE);
    }

    if (i2c_read_retries(fd, 0x02, &raw_temperature, MAX_RETRIES) < 0) {
        fprintf(stderr, "Failed to read MLX90834 temperature\n");
        exit(EXIT_FAILURE);
    }

    *pressure = (float)(raw_pressure - 2048) * 0.00006103515625f;
    *temperature = (float)(raw_temperature - 2048) * 0.00390625f;
}

void setup_gpio() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;

    chip = gpiod_chip_open("/dev/gpiochip4");
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    line = gpiod_line_request(chip, "gpio17", "pressure_led", GPIOD_LINE_DIRECTION_OUTPUT, 0, 0);
    if (!line) {
        perror("Failed to request GPIO line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    app_state.led_line = line;
}

void cleanup_gpio() {
    if (app_state.led_line) {
        gpiod_line_release(app_state.led_line);
    }
}

int main() {
    int i2c_fd;
    uint16_t ain0, ain1;
    float pressure, temperature;
    struct sigaction sa;

    // Initialize signal handling
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        exit(EXIT_FAILURE);
    }

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Configure ADS1115
    uint16_t config = (ADS1115_CONFIG | ADS1115_MUX | ADS1115_GAIN | ADS1115_MODE);
    if (i2c_read_retries(i2c_fd, ADS1115_CONFIG, &config, MAX_RETRIES) < 0) {
        fprintf(stderr, "Failed to read ADS1115 config\n");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Setup GPIO
    setup_gpio();

    while (1) {
        read_ads1115(i2c_fd, &ain0, &ain1);
        read_mlx90834(MLX90834_ADDR, &pressure, &temperature);

        printf("Pressure: %.2f kPa, Temperature: %.2f °C\n", pressure, temperature);

        if (pressure > PRESSURE_THRESHOLD) {
            gpiod_line_set_value(app_state.led_line, 1);
        } else {
            gpiod_line_set_value(app_state.led_line, 0);
        }

        usleep(UPDATE_INTERVAL * 1000);
    }

    cleanup_gpio();
    close(i2c_fd);
    return 0;
}

