#define SPI_CHIP 0
#define SPI_SPEED 1000000
#define SPI_MODE SPI_MODE_0
#define SPI_MAX_TRANSFER_SIZE 8
#define CHANNEL 0
#define CS_PIN 8
#define LOG_FILE "methane_log.txt"
#define THRESHOLD_PPM 1000

typedef struct {
    int spi_fd;
    struct gpiod_line *cs_line;
    FILE *log_file;
    int running;
} app_state;

void handle_signal(int sig) {
    app_state *state = (app_state *)malloc(sizeof(app_state));
    if (state) {
        state->running = 0;
        free(state);
    }
}

void close_spi(app_state *state) {
    if (state->spi_fd >= 0) {
        close(state->spi_fd);
        state->spi_fd = -1;
    }
}

void close_cs_line(app_state *state) {
