        gpiod_line_release(state->cs_line);
        state->cs_line = NULL;
    }
}

void close_log_file(app_state *state) {
    if (state->log_file) {
        fclose(state->log_file);
        state->log_file = NULL;
    }
}

void init_spi(app_state *state) {
    state->spi_fd = open("/dev/spidev0.0", O_RDWR | O_NOCTTY | O_NDELAY);
    if (state->spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    struct spi_ioc_transfer spi;
    memset(&spi, 0, sizeof(spi));
    spi.speed_hz = SPI_SPEED;
    spi.mode = SPI_MODE;
    spi.bits_per_word = 8;

    if (ioctl(state->spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        fprintf(stderr, "Failed to set SPI mode: %s\n", strerror(errno));
        close_spi(state);
        exit(EXIT_FAILURE);
    }

    if (ioctl(state->spi_fd, SPI_IOC_WR_SPEED_HZ, &SPI_SPEED) < 0) {
        fprintf(stderr, "Failed to set SPI speed: %s\n", strerror(errno));
        close_spi(state);
        exit(EXIT_FAILURE);
    }

    if (ioctl(state->spi_fd, SPI_IOC_WR_BITS_PER_WORD, &8) < 0) {
        fprintf(stderr, "Failed to set SPI bits per word: %s\n", strerror(errno));
        close_spi(state);
        exit(EXIT_FAILURE);
    }
}

void init_cs_line(app_state *state) {
    struct gpiod_chip *chip;
    chip = gpiod_chip_open(CS_PIN);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    state->cs_line = gpiod_line_get(chip, "gpio", CS_PIN);
    if (!state->cs_line) {
        fprintf(stderr, "Failed to get GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(state->cs_line, "cs", 1) < 0) {
        fprintf(stderr, "Failed to request GPIO line: %s\n", strerror(errno));
