        exit(EXIT_FAILURE);
    }
}

void read_adc(app_state *state) {
    uint8_t tx[1] = {1 << CHANNEL};
    uint8_t rx[1] = {0};

    if (gpiod_line_set_value(state->cs_line, 0) < 0) {
        fprintf(stderr, "Failed to set CS low: %s\n", strerror(errno));
        return;
    }

    if (ioctl(state->spi_fd, SPI_IOC_MESSAGE(1), &tx) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        if (gpiod_line_set_value(state->cs_line, 1) < 0) {
            fprintf(stderr, "Failed to set CS high: %s\n", strerror(errno));
        }
        return;
    }

    if (ioctl(state->spi_fd, SPI_IOC_MESSAGE(1), &rx) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        if (gpiod_line_set_value(state->cs_line, 1) < 0) {
            fprintf(stderr, "Failed to set CS high: %s\n", strerror(errno));
        }
        return;
    }

    if (gpiod_line_set_value(state->cs_line, 1) < 0) {
        fprintf(stderr, "Failed to set CS high: %s\n", strerror(errno));
    }

    uint16_t adc_value = (rx[0] << 8) | rx[0];
    double voltage = (adc_value * 3.3) / 4096.0;
    double ppm = (voltage * 1000000.0) / 0.001; // Assuming 0.001V = 1000ppm

    if (ppm > THRESHOLD_PPM) {
        fprintf(stderr, "Methane leak detected: %.2f ppm\n", ppm);
    }

    char timestamp[30];
    time_t now;
    struct tm tm;
    time(&now);
    localtime_r(&now, &tm);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(state->log_file, "%s, %.2f ppm\n", timestamp, ppm);
    fflush(state->log_file);
}

int main() {
    app_state state = {0};

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    init_spi(&state);
    init_cs_line(&state);
    init_log_file(&state);

    state.running = 1;

    while (state.running) {
        read_adc(&state);
        sleep(1);
    }

    close_spi(&state);
    close_cs_line(&state);
    close_log_file(&state);

    return 0;
}

