void log_pressure(double pressure) {
    FILE *file = fopen(LOG_FILE, "a");
    if (!file) {
        perror("Failed to open log file");
        return;
    }

    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", tm_info);

    fprintf(file, "%s,%f\n", timestamp, pressure);
    fclose(file);
}

int i2c_init(int bus) {
    char filename[20];
    snprintf(filename, sizeof(filename), "/dev/i2c-%d", bus);
    int file = open(filename, O_RDWR);
    if (file < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    int addr = I2C_ADDR_ADS1115;
    if (ioctl(file, I2C_SLAVE, addr) < 0) {
        perror("Failed to set I2C slave address");
        close(file);
        return -1;
    }

    return file;
}

int ads1115_configure(int file) {
    unsigned int config = ADS1115_CONFIG_DEFAULT;
