        return -1.0;
    }

    usleep(1000000); // Wait for 1 second for 1Hz sampling

    unsigned char buffer[2];
    if (read(file, buffer, 2) != 2) {
        perror("Failed to read ADC result");
        return -1.0;
    }

    int16_t result = (buffer[0] << 8) | buffer[1];
    return (double)result * 4083.0 / 32768.0; // 6.144V / 32768 = 0.0001887V per LSB
