    if (i2c_file < 0) {
        fprintf(stderr, "I2C initialization failed\n");
        return 1;
    }

    // Initialize ADS1115
    if (ads1115_configure(i2c_file) < 0) {
        fprintf(stderr, "ADS1115 configuration failed\n");
        cleanup(i2c_file);
        return 1;
    }

    // Initialize MLX90830
    mlx90830_file = open("/dev/i2c-1", O_RDWR);
    if (mlx90830_file < 0) {
        perror("Failed to open MLX90830 I2C bus");
        cleanup(i2c_file);
        return 1;
    }

    if (ioctl(mlx90830_file, I2C_SLAVE, I2C_ADDR_MLX90830) < 0) {
        perror("Failed to set MLX90830 I2C slave address");
        cleanup(i2c_file);
        cleanup(mlx90830_file);
        return 1;
    }

    if (mlx90830_check_presence(mlx90830_file) < 0) {
        cleanup(i2c_file);
        cleanup(mlx90830_file);
        return 1;
    }

    printf("Pressure sensor initialized and ready.\n");

    while (running) {
        double pressure = ads1115_read_adc(i2c_file);
        if (pressure < 0) {
            fprintf(stderr, "ADC read failed, skipping.\n");
            usleep(1000000);
            continue;
        }

        if (pressure >= PRESSURE_MIN && pressure <= PRESSURE_MAX) {
            log_pressure(pressure);
            printf("Valid pressure: %.2f kPa\n", pressure / 1000.0);
        } else {
            fprintf(stderr, "Invalid pressure: %.2f kPa (out of range)\n", pressure / 1000.0);
        }

        usleep(1000000); // 1 Hz sampling
    }

    cleanup(i2c_file);
    cleanup(mlx90830_file);

    printf("Program exited gracefully.\n");
    return 0;
}

