#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <sys/time.h>
#include <signal.h>
#include <gpiod.h>
#include <errno.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_MAX_SPEED_HZ 1000000
#define ADC_CHANNEL 0
#define GPIO_CHIP "gpiochip4"
#define GPIO_CE_PIN 8
#define GPIO_SCLK_PIN 11
#define GPIO_MOSI_PIN 10
#define GPIO_MISO_PIN 9
#define ADC_VREF 3300.0
#define ADC_RESOLUTION 4096.0
#define TEMP_OFFSET 500.0
#define TEMP_SCALE 100.0
#define TEMP_MIN -40.0
#define TEMP_MAX 125.0

typedef enum {
    STATE_IDLE,
    STATE_RUNNING,
    STATE_EXITING
} state_t;

typedef struct {
    int spi_fd;
    struct gpiod_line *ce_line;
    FILE *log_file;
    state_t state;
} app_context_t;

void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        printf("Caught signal %d, shutting down...\n", signum);
        app_context_t *ctx = (app_context_t *)malloc(sizeof(app_context_t));
        ctx->state = STATE_EXITING;
        free(ctx);
    }
}

int init_gpio(app_context_t *ctx) {
    int ret;
    struct gpiod_chip *chip;

    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip %s: %s\n", GPIO_CHIP, strerror(errno));
        return -1;
    }

    ctx->ce_line = gpiod_line_get(chip, GPIO_CE_PIN);
    if (!ctx->ce_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", GPIO_CE_PIN, strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(ctx->ce_line, "adc_ce", 1)) {
        fprintf(stderr, "Failed to request GPIO line %d as output: %s\n", GPIO_CE_PIN, strerror(errno));
        gpiod_line_put(ctx->ce_line);
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

void release_gpio(app_context_t *ctx) {
    if (ctx->ce_line) {
        gpiod_line_put(ctx->ce_line);
    }
}

int init_spi(app_context_t *ctx) {
    int ret;
    struct spi_ioc_transfer spi;

    ctx->spi_fd = open(SPI_DEVICE, O_RDWR | O_NOCTTY | O_SYNC);
    if (ctx->spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device %s: %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    if (ioctl(ctx->spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        fprintf(stderr, "Failed to set SPI mode: %s\n", strerror(errno));
        close(ctx->spi_fd);
        return -1;
    }

    if (ioctl(ctx->spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS_PER_WORD) < 0) {
        fprintf(stderr, "Failed to set SPI bits per word: %s\n", strerror(errno));
        close(ctx->spi_fd);
        return -1;
    }

    if (ioctl(ctx->spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_MAX_SPEED_HZ) < 0) {
        fprintf(stderr, "Failed to set SPI max speed: %s\n", strerror(errno));
        close(ctx->spi_fd);
        return -1;
    }

    return 0;
}

void release_spi(app_context_t *ctx) {
    if (ctx->spi_fd >= 0) {
        close(ctx->spi_fd);
    }
}

int read_adc(app_context_t *ctx) {
    unsigned char tx[3] = {0x01, (unsigned char)(ADC_CHANNEL << 4), 0x00};
    unsigned char rx[3] = {0};
    struct spi_ioc_transfer spi;
    int ret;

    memset(&spi, 0, sizeof(spi));
    spi.tx_buf = (unsigned long)tx;
    spi.rx_buf = (unsigned long)rx;
    spi.len = 3;
    spi.speed_hz = SPI_MAX_SPEED_HZ;
    spi.delay_usecs = 0;
    spi.bits_per_word = SPI_BITS_PER_WORD;

    ctx->ce_line->bias = GPIOD_LINE_BIAS_PULL_UP;
    gpiod_line_set_value(ctx->ce_line, 0);

    ret = ioctl(ctx->spi_fd, SPI_IOC_MESSAGE(1), &spi);
    if (ret < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }

    ctx->ce_line->bias = GPIOD_LINE_BIAS_DISABLE;
    gpiod_line_set_value(ctx->ce_line, 1);

    unsigned int adc_value = (rx[1] << 8) | rx[2];
    return adc_value;
}

double adc_to_celsius(int adc_value) {
    double voltage = (adc_value * ADC_VREF) / ADC_RESOLUTION;
    double temperature = (voltage - TEMP_OFFSET) / TEMP_SCALE;
    return temperature;
}

int validate_adc(int adc_value) {
    if (adc_value < 0 || adc_value > ADC_RESOLUTION) {
        fprintf(stderr, "Invalid ADC value: %d\n", adc_value);
        return -1;
    }
    return 0;
}

void log_temperature(app_context_t *ctx, double temperature) {
    struct timeval tv;
    char timestamp[30];

    gettimeofday(&tv, NULL);
    snprintf(timestamp, sizeof(timestamp), "%ld.%06ld", tv.tv_sec, tv.tv_usec);

    if (ctx->log_file == NULL) {
        ctx->log_file = fopen("temperature_log.csv", "w");
        if (!ctx->log_file) {
            fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
            return;
        }
        fprintf(ctx->log_file, "timestamp,temperature_celsius\n");
    }

    fprintf(ctx->log_file, "%s,%f\n", timestamp, temperature);
    fflush(ctx->log_file);
}

int main() {
    app_context_t ctx = {0};
    int ret;
    double temperature;
    struct sigaction sa;

    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set SIGINT handler: %s\n", strerror(errno));
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set SIGTERM handler: %s\n", strerror(errno));
        return -1;
    }

    if (init_gpio(&ctx) < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return -1;
    }

    if (init_spi(&ctx) < 0) {
        fprintf(stderr, "Failed to initialize SPI\n");
        release_gpio(&ctx);
        return -1;
    }

    ctx.state = STATE_RUNNING;

    while (ctx.state == STATE_RUNNING) {
        int adc_value = read_adc(&ctx);
        if (adc_value < 0) {
            fprintf(stderr, "SPI read failed\n");
            break;
        }

        if (validate_adc(adc_value) < 0) {
            fprintf(stderr, "ADC value out of range\n");
            break;
        }

        temperature = adc_to_celsius(adc_value);

        if (temperature < TEMP_MIN || temperature > TEMP_MAX) {
            fprintf(stderr, "Temperature out of valid range: %.2f°C\n", temperature);
            break;
        }

        log_temperature(&ctx, temperature);

        sleep(1);
    }

    if (ctx.state == STATE_EXITING) {
        printf("Shutting down gracefully...\n");
    }

    release_gpio(&ctx);
    release_spi(&ctx);

    if (ctx.log_file) {
        fclose(ctx.log_file);
    }

    return 0;
}

