#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>
#include <errno.h>

#define I2C_BUS 1
#define I2C_ADDR 0x5C
#define I2C_DEVICE "/dev/i2c-%d"
#define LOG_FILE "biometric_log.csv"
#define HEADER "timestamp,ir_adc,red_adc,error_flag\n"

typedef enum {
    ERROR_OK = 0,
    ERROR_READ = 1,
    ERROR_SENSOR_ABSENT = 2
} error_flag_t;

typedef struct {
    int fd;
    FILE *log_file;
    int running;
} app_state_t;

void handle_signal(int signal) {
    if (signal == SIGINT) {
        printf("Received SIGINT, shutting down...\n");
        app_state_t *state = (app_state_t *)malloc(sizeof(app_state_t));
        state->running = 0;
        // Free resources here if needed
        exit(EXIT_SUCCESS);
    }
}

int open_i2c_bus(int bus) {
    char device[32];
    snprintf(device, sizeof(device), I2C_DEVICE, bus);
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }
    if (ioctl(fd, I2C_TEN, 0) < 0) {
        perror("Failed to set I2C to 10-bit addressing");
        close(fd);
        return -1;
    }
    return fd;
}

int i2c_read(int fd, uint8_t reg, uint16_t *value) {
    uint8_t buffer[2];
    buffer[0] = reg;
    if (write(fd, buffer, 1) < 0) {
        perror("I2C write failed");
        return -1;
    }
    if (read(fd, buffer, 2) < 0) {
        perror("I2C read failed");
        return -1;
    }
    *value = (buffer[0] << 8) | buffer[1];
    return 0;
}

void log_data(FILE *log_file, time_t timestamp, uint16_t ir_adc, uint16_t red_adc, error_flag_t error_flag) {
    fprintf(log_file, "%lu,%d,%d,%d\n", (long unsigned int)timestamp, ir_adc, red_adc, error_flag);
    fflush(log_file);
}

int main() {
    app_state_t state;
    state.fd = -1;
    state.log_file = NULL;
    state.running = 1;

    // Set up signal handler
    signal(SIGINT, handle_signal);

    // Open I2C bus
    state.fd = open_i2c_bus(I2C_BUS);
    if (state.fd < 0) {
        fprintf(stderr, "Failed to open I2C bus, exiting.\n");
        return EXIT_FAILURE;
    }

    // Check if sensor is present
    if (ioctl(state.fd, I2C_SLAVE, I2C_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address, sensor absent or uninitialized.\n");
        close(state.fd);
        return EXIT_FAILURE;
    }

    // Open log file
    state.log_file = fopen(LOG_FILE, "w");
    if (!state.log_file) {
        fprintf(stderr, "Failed to open log file, exiting.\n");
        close(state.fd);
        return EXIT_FAILURE;
    }

    // Write header
    if (fprintf(state.log_file, HEADER) < 0) {
        fprintf(stderr, "Failed to write header to log file, exiting.\n");
        fclose(state.log_file);
        close(state.fd);
        return EXIT_FAILURE;
    }
    fflush(state.log_file);

    // Main loop
    while (state.running) {
        time_t timestamp = time(NULL);
        uint16_t ir_adc = 0, red_adc = 0;
        error_flag_t error_flag = ERROR_OK;

        // Read IR ADC
        if (i2c_read(state.fd, 0x00, &ir_adc) < 0) {
            error_flag = ERROR_READ;
        }

        // Read RED ADC
        if (i2c_read(state.fd, 0x01, &red_adc) < 0) {
            error_flag = ERROR_READ;
        }

        // Log data
        log_data(state.log_file, timestamp, ir_adc, red_adc, error_flag);

        // Sleep for 1 second
        usleep(1000000);
    }

    // Cleanup
    fclose(state.log_file);
    close(state.fd);

    return EXIT_SUCCESS;
}

