int spi_fd = -1;
struct gpiod_line *cs_line = NULL;
FILE *log_file = NULL;

void log_error(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
}

void log_warning(const char *message) {
    fprintf(stderr, "Warning: %s\n", message);
}

void cleanup_and_exit(int status) {
    if (log_file) {
        fclose(log_file);
    }
    if (cs_line) {
        gpiod_line_release(cs_line);
    }
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    exit(status);
}

int init_spi() {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        log_error("Failed to open SPI device");
        return -1;
    }

    struct spi_ioc_transfer spi;
    memset(&spi, 0, sizeof(spi));
    spi.speed_hz = SPI_SPEED;
    spi.bits_per_word = SPI_BITS;
    spi.delay_usecs = SPI_DELAY;

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        log_error("Failed to set SPI mode");
        close(spi_fd);
        return -1;
    }

    return 0;
}

int init_cs_line() {
    struct gpiod_chip *chip;
    chip = gpiod_chip_open("/dev/gpiochip8");
    if (!chip) {
        log_error("Failed to open GPIO chip");
        return -1;
    }

    cs_line = gpiod_line_get(chip, 8);
    if (!cs_line) {
        log_error("Failed to get CS line");
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(cs_line, "spi_cs", 1) < 0) {
        log_error("Failed to request CS line as output");
        gpiod_line_release(cs_line);
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

