             ts.tv_sec / 3600 / 24 + 1970,
             ts.tv_sec / 3600 % 24,
             ts.tv_sec / 60 % 60,
             ts.tv_sec % 60,
             ts.tv_nsec / 1000000,
             ts.tv_nsec % 1000000);

    fprintf(log_file, "%s,%f\n", timestamp, flow_rate);
    fflush(log_file);
}

