        cleanup_and_exit(EXIT_FAILURE);
    }

    log_file = fopen("flow_log.csv", "a");
    if (!log_file) {
        log_error("Failed to open log file");
        cleanup_and_exit(EXIT_FAILURE);
    }

    fprintf(log_file, "Timestamp,Flow Rate (L/min)\n");
    fflush(log_file);

    while (1) {
        int adc_value = read_adc();
        if (adc_value < 0) {
            log_warning("ADC read failed");
            usleep(1000000);
            continue;
        }

        if (adc_value == ADC_MIN || adc_value == ADC_MAX) {
            log_warning("Sensor absent or full-scale");
            usleep(1000000);
            continue;
