        double flow_rate = adc_value * FLOW_TO_ADC;
        if (flow_rate < FLOW_MIN || flow_rate > FLOW_MAX) {
            log_warning("Flow rate out of range");
            usleep(1000000);
            continue;
        }

        log_flow_rate(flow_rate);
        usleep(1000000);
    }

    cleanup_and_exit(EXIT_SUCCESS);
}

