#define MIC_CHANNELS 2
#define SAMPLE_RATE 1000
#define BUFFER_SIZE 1024

typedef struct {
    int fd;
    struct gpiod_line *cs_line;
} SpiContext;

typedef struct {
    int gain;
    int sample_rate;
    int buffer_size;
} Config;

void handle_signal(int sig);
void cleanup(SpiContext *spi, Config *config);
int init_spi(SpiContext *spi);
int read_adc(SpiContext *spi, uint16_t *adc_values, int num_channels);
void apply_noise_cancellation(uint16_t *left, uint16_t *right, int size);
void print_csv(uint16_t *left, uint16_t *right, int size);

int main(int argc, char *argv[]) {
    Config config = {0};
    SpiContext spi = {0};
    int running = 1;
    int samples = 0;

    if (argc != 3) {
        fprintf(stderr, "Usage: %s <gain> <sample_rate>\n", argv[0]);
        exit(EXIT_FAILURE);
    }

    config.gain = atoi(argv[1]);
    config.sample_rate = atoi(argv[2]);
    config.buffer_size = BUFFER_SIZE;

    signal(SIGINT, handle_signal);

    if (init_spi(&spi) != 0) {
        fprintf(stderr, "Failed to initialize SPI\n");
        exit(EXIT_FAILURE);
    }

    while (running) {
        uint16_t left[MIC_CHANNELS];
        uint16_t right[MIC_CHANNELS];

        if (read_adc(&spi, left, MIC_CHANNELS) != 0) {
            fprintf(stderr, "SPI read error\n");
            cleanup(&spi, &config);
            exit(EXIT_FAILURE);
        }

        apply_noise_cancellation(left, right, MIC_CHANNELS);
        print_csv(left, right, MIC_CHANNELS);

        samples++;
        usleep(1000000 / config.sample_rate);
    }

    cleanup(&spi, &config);
    return 0;
}

void handle_signal(int sig) {
    if (sig == SIGINT) {
        printf("\nCaught SIGINT, cleaning up...\n");
        exit(EXIT_FAILURE);
    }
}

void cleanup(SpiContext *spi, Config *config) {
    if (spi->cs_line) {
        gpiod_line_release(spi->cs_line);
    }
    if (spi->fd >= 0) {
        close(spi->fd);
    }
}

int init_spi(SpiContext *spi) {
    int fd;
    struct gpiod_line *cs_line;

    spi->fd = open(SPI_DEVICE, O_RDWR | O_NOCTTY | O_SYNC);
    if (spi->fd < 0) {
        fprintf(stderr, "Failed to open SPI device: %s\n", strerror(errno));
        return -1;
    }

    if (ioctl(spi->fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_MAX_SPEED_HZ) < 0) {
        fprintf(stderr, "Failed to set SPI max speed: %s\n", strerror(errno));
        close(spi->fd);
        return -1;
    }

    if (ioctl(spi->fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS_PER_WORD) < 0) {
        fprintf(stderr, "Failed to set SPI bits per word: %s\n", strerror(errno));
        close(spi->fd);
        return -1;
    }

    if (ioctl(spi->fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        fprintf(stderr, "Failed to set SPI mode: %s\n", strerror(errno));
        close(spi->fd);
        return -1;
    }

    cs_line = gpiod_line_get("gpiochip8", 8);
    if (!cs_line) {
        fprintf(stderr, "Failed to get CS line: %s\n", strerror(errno));
        close(spi->fd);
        return -1;
    }

    if (gpiod_line_request_output(cs_line, "spi_cs", 1) < 0) {
        fprintf(stderr, "Failed to request CS line: %s\n", strerror(errno));
        gpiod_line_release(cs_line);
        close(spi->fd);
        return -1;
    }

    spi->cs_line = cs_line;

    return 0;
}

int read_adc(SpiContext *spi, uint16_t *adc_values, int num_channels) {
    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)adc_values,
        .rx_buf = (unsigned long)adc_values,
        .len = num_channels * 2,
        .delay_usecs = SPI_DELAY_US,
        .speed_hz = SPI_MAX_SPEED_HZ,
        .bits_per_word = SPI_BITS_PER_WORD
    };

    gpiod_line_set_value(spi->cs_line, 0);
    if (ioctl(spi->fd, SPI_IOC_MESSAGE(1), &transfer) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }
    gpiod_line_set_value(spi->cs_line, 1);

    return 0;
}

void apply_noise_cancellation(uint16_t *left, uint16_t *right, int size) {
    for (int i = 0; i < size; i++) {
        left[i] = (left[i] - right[i]) / 2;
    }
}

void print_csv(uint16_t *left, uint16_t *right, int size) {
    static int first = 1;
    char buffer[256];

    if (first) {
        printf("Time,Left,Right\n");
        first = 0;
    }

    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    strftime(buffer, sizeof(buffer), "%H:%M:%S", tm_info);

    printf("%s,%d,%d\n", buffer, left[0], right[0]);
}

