#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_SPEED 1000000
#define SPI_BITS 8
#define SPI_DELAY 500000  // 500 ms in microseconds
#define MAX_RETRIES 3
#define BUZZER_PIN 18
#define ADC_CHANNEL 0
#define LOG_FILE "flame_log.txt"
#define AMBIENT_TEMP_FILE "ambient_temp.txt"
#define ADC_MAX 1023
#define ADC_REF_VOLTAGE 3.3
#define FLAME_THRESHOLD 300  // Adjust based on sensor calibration

volatile int running = 1;
int spi_fd = -1;
struct gpiod_line *buzzer_line = NULL;
FILE *log_file = NULL;

void handle_signal(int sig) {
    running = 0;
}

void log_error(const char *message, const char *filename) {
    fprintf(stderr, "%s\n", message);
    if (log_file) {
        fprintf(log_file, "%s\n", message);
        fflush(log_file);
    }
}

void close_resources() {
    if (log_file) {
        fclose(log_file);
    }
    if (buzzer_line) {
        gpiod_line_release(buzzer_line);
    }
    if (spi_fd >= 0) {
        close(spi_fd);
    }
}

int init_spi() {
    spi_fd = open(SPI_DEVICE, O_RDWR | O_NOCTTY | O_SYNC);
    if (spi_fd < 0) {
        log_error("Failed to open SPI device", SPI_DEVICE);
        return -1;
    }

    struct spi_ioc_transfer spi;
    memset(&spi, 0, sizeof(spi));
    spi.speed_hz = SPI_SPEED;
    spi.bits_per_word = SPI_BITS;
    spi.delay_usecs = SPI_DELAY;

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        log_error("Failed to set SPI mode", "");
        close(spi_fd);
        return -1;
    }

    return 0;
}

int read_adc(int channel) {
    uint8_t tx[3] = {1 << 7 | ((channel & 7) << 4), 0, 0};
    uint8_t rx[3];

    for (int retry = 0; retry < MAX_RETRIES; retry++) {
        if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tx) < 0) {
            log_error("SPI transfer failed", "");
            return -1;
        }

        usleep(1000);  // Small delay to ensure data is ready

        if (rx[0] & 0x80) {
            log_error("ADC overflow detected", "");
            return -1;
        }

        int adc_value = (rx[0] << 8) | rx[1];
        if (adc_value < 0 || adc_value > ADC_MAX) {
            log_error("ADC value out of range", "");
            continue;
        }

        return adc_value;
    }

    log_error("ADC read failed after retries", "");
    return -1;
}

double calculate_voltage(int adc_value) {
    return (adc_value * ADC_REF_VOLTAGE) / ADC_MAX;
}

