    buzzer_line = gpiod_line_get(chip, BUZZER_PIN);
    if (!buzzer_line) {
        log_error("Failed to get GPIO line", "");
        gpiod_chip_close(chip);
        return;
    }

    if (gpiod_line_request_output(buzzer_line, "buzzer", GPIOD_LINE_REQUEST_FLAG_ACTIVE_LOW)) {
        log_error("Failed to request GPIO line", "");
        gpiod_line_release(buzzer_line);
        gpiod_chip_close(chip);
        return;
    }

    gpiod_line_set_value(buzzer_line, 0);  // Turn off buzzer
}

