    if (gpiod_line_request_output(buzzer_line, "buzzer", GPIOD_LINE_REQUEST_FLAG_ACTIVE_LOW)) {
        log_error("Failed to request GPIO line", "");
        gpiod_line_release(buzzer_line);
        gpiod_chip_close(chip);
        return;
    }

    gpiod_line_set_value(buzzer_line, 0);  // Turn off buzzer
}

void log_flame_data(double raw_adc, double voltage, double compensated_voltage, double temperature, int flame_detected) {
    time_t now;
    struct tm *timeinfo;
    char timestamp[20];

    time(&now);
    timeinfo = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%d,%.2f,%.2f,%.1f,%d\n", timestamp, (int)raw_adc, voltage, compensated_voltage, temperature, flame_detected);
    fflush(log_file);
}

int read_ambient_temp() {
    FILE *temp_file = fopen(AMBIENT_TEMP_FILE, "r");
    if (!temp_file) {
        log_error("Ambient temperature file not found or invalid", "");
        return 25.0;
    }

    double temp;
    if (fscanf(temp_file, "%lf", &temp) != 1) {
        log_error("Invalid ambient temperature data", "");
        fclose(temp_file);
        return 25.0;
    }

    fclose(temp_file);
    return temp;
}

int main() {
    signal(SIGINT, handle_signal);

    if (init_spi() < 0) {
        return 1;
    }

    setup_gpio();

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        log_error("Failed to open log file", "");
        close_resources();
        return 1;
    }

    double ambient_temp = read_ambient_temp();

    while (running) {
        int adc_value = read_adc(ADC_CHANNEL);
        if (adc_value < 0) {
            usleep(SPI_DELAY);
            continue;
        }

        double voltage = calculate_voltage(adc_value);
        double compensated_voltage = calculate_compensated_voltage(voltage, ambient_temp);
        int flame_detected = (adc_value > FLAME_THRESHOLD) ? 1 : 0;

        if (flame_detected) {
            gpiod_line_set_value(buzzer_line, 1);  // Turn on buzzer
        } else {
            gpiod_line_set_value(buzzer_line, 0);  // Turn off buzzer
        }

        log_flame_data(adc_value, voltage, compensated_voltage, ambient_temp, flame_detected);

        usleep(SPI_DELAY);
    }

    close_resources();
    return 0;
}
