        app_state *state = (app_state *)malloc(sizeof(app_state));
        state->running = 0;
        free(state);
    }
}

void init_spi(app_state *state) {
    state->spi_fd = open(SPI_DEVICE, O_RDWR | O_NOCTTY | O_SYNC);
    if (state->spi_fd < 0) {
        perror("Failed to open SPI device");
        exit(EXIT_FAILURE);
    }

    struct spi_ioc_transfer spi;
    memset(&spi, 0, sizeof(spi));
    spi.speed_hz = SPI_SPEED;
    spi.bits_per_word = SPI_BITS;
    spi.delay_usecs = SPI_DELAY;

    if (ioctl(state->spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("Failed to set SPI mode");
        close(state->spi_fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(state->spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS) < 0) {
        perror("Failed to set SPI bits per word");
        close(state->spi_fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(state->spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("Failed to set SPI speed");
        close(state->spi_fd);
        exit(EXIT_FAILURE);
    }
}

void init_cs_line(app_state *state) {
    struct gpiod_chip *chip;
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    state->cs_line = gpiod_line_get(chip, 24); // CE0 is GPIO 24
    if (!state->cs_line) {
        perror("Failed to get CS line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(state->cs_line, "cs_line", 1) < 0) {
        perror("Failed to request CS line as output");
        gpiod_line_put(state->cs_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }
}

void release_cs_line(app_state *state) {
    if (state->cs_line) {
        gpiod_line_put(state->cs_line);
    }
}

void release_spi(app_state *state) {
    if (state->spi_fd >= 0) {
        close(state->spi_fd);
    }
}

void init_log_file(app_state *state) {
    state->log_file = fopen(LOG_FILE, "a");
    if (!state->log_file) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
