    uint8_t tx[3];
    uint8_t rx[3];
    int len = 3;

    tx[0] = 1 << 7 | (ADC_CHANNEL & 0x0F); // Start bit + channel
    tx[1] = 0;
    tx[2] = 0;

    gpiod_line_set_value(state->cs_line, 0); // CS low
    if (ioctl(state->spi_fd, SPI_IOC_MESSAGE(1), &tx) < 0) {
        perror("SPI write failed");
        return 0;
    }

    if (ioctl(state->spi_fd, SPI_IOC_MESSAGE(1), &rx) < 0) {
        perror("SPI read failed");
        return 0;
    }

    gpiod_line_set_value(state->cs_line, 1); // CS high

    uint16_t adc_value = (rx[1] << 8) | rx[2];
    return adc_value;
}

double convert_to_lpm(uint16_t adc_value) {
    // Calibration values (example, adjust based on sensor specs)
    double volts = (adc_value / 1023.0) * 3.3;
    double airflow_lpm = volts * 1000.0; // Example conversion, adjust as needed
    return airflow_lpm;
}

void log_reading(app_state *state, double airflow_lpm) {
    char timestamp[30];
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

    fprintf(state->log_file, "%s,%f\n", timestamp, airflow_lpm);
    fflush(state->log_file);
}

void cleanup(app_state *state) {
    release_cs_line(state);
    release_spi(state);
    close_log_file(state);
    printf("Application exited cleanly.\n");
}

int main() {
    app_state state;
    init_spi(&state);
    init_cs_line(&state);
    init_log_file(&state);

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    state.running = 1;
