    // Calibration values (example, adjust based on sensor specs)
    double volts = (adc_value / 1023.0) * 3.3;
    double airflow_lpm = volts * 1000.0; // Example conversion, adjust as needed
    return airflow_lpm;
}

void log_reading(app_state *state, double airflow_lpm) {
    char timestamp[30];
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

    fprintf(state->log_file, "%s,%f\n", timestamp, airflow_lpm);
    fflush(state->log_file);
}

void cleanup(app_state *state) {
    release_cs_line(state);
    release_spi(state);
    close_log_file(state);
    printf("Application exited cleanly.\n");
}

int main() {
    app_state state;
    init_spi(&state);
    init_cs_line(&state);
    init_log_file(&state);

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    state.running = 1;
    while (state.running) {
        uint16_t adc_value = read_adc(&state);
        if (adc_value == 0) {
            fprintf(stderr, "ADC read failed, skipping sample.\n");
            usleep(100000); // 100ms
            continue;
        }

        double airflow_lpm = convert_to_lpm(adc_value);
        log_reading(&state, airflow_lpm);

        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    cleanup(&state);
    return 0;
}
