#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define SPI_MODE SPI_MODE_0
#define SPI_BITS 8
#define SPI_MAX_TRANSFER 1024
#define ADC_CHANNEL 0
#define ADC_READ_CMD 0b10100000
#define ADC_READ_CMD_MASK 0b11100000
#define ADC_READ_CMD_CHANNEL_MASK 0b00011111
#define ADC_READ_CMD_CHANNEL_SHIFT 4

typedef struct {
    int spi_fd;
    FILE *log_file;
    int interval;
    int running;
} app_state;

void handle_signal(int signum) {
    app_state *state = (app_state *)malloc(sizeof(app_state));
    if (state == NULL) {
        fprintf(stderr, "Failed to allocate memory for app_state\n");
        return;
    }

    state->running = 0;
    if (state->log_file != NULL) {
        fflush(state->log_file);
        fclose(state->log_file);
    }

    if (state->spi_fd >= 0) {
        close(state->spi_fd);
    }

    // Clean up ADC (simulated)
    // In a real scenario, you would call the ADC's cleanup function here
    free(state);
    exit(EXIT_SUCCESS);
}

void log_soil_moisture(int adc_value) {
    time_t now;
    struct tm *timeinfo;
    char timestamp[64];

    time(&now);
    timeinfo = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

    double moisture_percent = (adc_value * 100.0) / 1023.0;
    fprintf(stdout, "%s,%d,%.2f\n", timestamp, adc_value, moisture_percent);
}

int read_adc(int spi_fd, int channel) {
    uint8_t tx[3] = {0};
    uint8_t rx[3] = {0};
    int ret;

    tx[0] = ADC_READ_CMD | ((channel & ADC_READ_CMD_CHANNEL_MASK) << ADC_READ_CMD_CHANNEL_SHIFT);
    tx[1] = 0;
    tx[2] = 0;

    struct spi_ioc_transfer spi = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .mode = SPI_MODE,
    };

    ret = ioctl(spi_fd, SPI_IOC_MESSAGE(1), &spi);
    if (ret < 1) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }

    int adc_value = (rx[1] << 8) | rx[2];
    return adc_value;
}

