#define SPI_SPEED 1000000
#define SPI_BITS 8
#define SPI_DELAY 0
#define CE_PIN 8
#define MISO_PIN 9
#define MOSI_PIN 10
#define SCLK_PIN 11

typedef struct {
    int spi_fd;
    struct gpiod_line *ce_line;
    int running;
} spi_context;

void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        printf("\nReceived signal to exit.\n");
        exit(EXIT_SUCCESS);
    }
}

int init_spi(spi_context *ctx) {
    ctx->spi_fd = open(SPI_DEVICE, O_RDWR | O_NOCTTY | O_NDELAY);
    if (ctx->spi_fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    struct spi_ioc_transfer spi;
    memset(&spi, 0, sizeof(spi));
    spi.speed_hz = SPI_SPEED;
    spi.bits_per_word = SPI_BITS;
    spi.delay_usecs = SPI_DELAY;
    spi.mode = SPI_MODE;

    if (ioctl(ctx->spi_fd, SPI_IOC_MESSAGE(1), &spi) < 0) {
        perror("Failed to set SPI parameters");
        close(ctx->spi_fd);
        return -1;
    }

    ctx->ce_line = gpiod_line_get("gpiochip0", CE_PIN);
    if (!ctx->ce_line) {
        perror("Failed to get CE GPIO line");
        close(ctx->spi_fd);
        return -1;
    }

    if (gpiod_line_request_output(ctx->ce_line, "CE", GPIOD_LINE_REQUEST_OUTPUT | GPIOD_LINE_REQUEST_FLAG_ACTIVE_LOW)) {
        perror("Failed to request CE GPIO line");
        gpiod_line_put(ctx->ce_line);
        close(ctx->spi_fd);
        return -1;
    }

    gpiod_line_set_value(ctx->ce_line, 1); // CE high (inactive)
    ctx->running = 1;
    return 0;
}

void deinit_spi(spi_context *ctx) {
    if (ctx->ce_line) {
        gpiod_line_put(ctx->ce_line);
    }
    if (ctx->spi_fd >= 0) {
        close(ctx->spi_fd);
    }
}

int read_adc(spi_context *ctx) {
    uint8_t tx[1] = {0x01}; // Start conversion
    uint8_t rx[3] = {0};

    gpiod_line_set_value(ctx->ce_line, 0); // CE low (active)
    if (ioctl(ctx->spi_fd, SPI_IOC_MESSAGE(1), &tx) < 0) {
        perror("SPI write failed");
        gpiod_line_set_value(ctx->ce_line, 1);
        return -1;
    }

    usleep(1000); // Wait for conversion to complete

    if (ioctl(ctx->spi_fd, SPI_IOC_MESSAGE(1), &rx) < 0) {
        perror("SPI read failed");
        gpiod_line_set_value(ctx->ce_line, 1);
        return -1;
    }

    gpiod_line_set_value(ctx->ce_line, 1); // CE high (inactive)

    // Extract 10-bit value from rx[1] and rx[2]
    uint16_t adc_value = (rx[1] << 8) | rx[2];
    return adc_value;
}

void log_pressure_reading(uint16_t adc_value) {
    time_t now = time(NULL);
    struct tm *tm_now = gmtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", tm_now);

    if (adc_value < 0 || adc_value > 1023) {
        printf("[%s] ADC value out of range: %d\n", timestamp, adc_value);
        return;
    }

    // Assuming 0V = 0, 3.3V = 1023, and pressure is linear
    double voltage = (double)adc_value / 1023.0 * 3.3;
    double pressure = voltage * 100.0; // Example conversion (adjust as needed)

    printf("[%s] ADC: %d | Voltage: %.2f V | Pressure: %.2f Pa\n", timestamp, adc_value, voltage, pressure);
}

int main() {
    spi_context ctx;
    if (init_spi(&ctx) < 0) {
        fprintf(stderr, "Failed to initialize SPI\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (ctx.running) {
        uint16_t adc_value = read_adc(&ctx);
        if (adc_value >= 0) {
            log_pressure_reading(adc_value);
        } else {
            printf("Failed to read ADC value.\n");
        }

        sleep(1);
    }

    deinit_spi(&ctx);
    return EXIT_SUCCESS;
}

