#include <errno.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define SPI_BITS 8
#define SPI_MODE SPI_MODE_0
#define CHANNEL 0
#define DELAY_MS 5000

int spi_fd = -1;

void handle_signal(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        if (spi_fd >= 0) {
            close(spi_fd);
        }
        exit(EXIT_SUCCESS);
    }
}

int spi_init() {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    struct spi_ioc_transfer spi;
    memset(&spi, 0, sizeof(spi));
    spi.fd = spi_fd;
    spi.speed_hz = SPI_SPEED;
    spi.bits_per_word = SPI_BITS;
    spi.mode = SPI_MODE;

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        return -1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS) < 0) {
        perror("Failed to set SPI bits per word");
        close(spi_fd);
        return -1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        return -1;
    }

    return 0;
}

int spi_read_adc() {
    uint8_t tx[3] = {1 << 7, (uint8_t)(0b10100000 | CHANNEL), 0};
    uint8_t rx[3] = {0};

    struct spi_ioc_transfer spi;
    memset(&spi, 0, sizeof(spi));
    spi.fd = spi_fd;
    spi.speed_hz = SPI_SPEED;
    spi.bits_per_word = SPI_BITS;
    spi.mode = SPI_MODE;
    spi.tx_buf = (unsigned long)tx;
    spi.rx_buf = (unsigned long)rx;
    spi.len = 3;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &spi) < 0) {
        perror("SPI transfer failed");
        return -1;
    }

    uint16_t adc_value = (rx[1] << 8) | rx[2];
    return adc_value;
}

float adc_to_percent(uint16_t adc_value) {
    // Assuming 0V = dry, 1.8V = wet (typical for soil moisture sensors)
    // ADC range is 0-1023 for 0-1.8V
    float voltage = (adc_value / 1023.0) * 1.8;
    float moisture_percent = (1.8 - voltage) / 1.8 * 100.0;
    return moisture_percent;
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if (spi_init() < 0) {
        fprintf(stderr, "SPI initialization failed\n");
        return EXIT_FAILURE;
    }

    printf("Soil Moisture Sensor Reader started. Logging every 5 seconds.\n");

    while (1) {
        if (spi_read_adc() < 0) {
            fprintf(stderr, "SPI read failed, retrying...\n");
            sleep(1);
            continue;
        }

        float moisture_percent = adc_to_percent(adc_value);
        moisture_percent = fmaxf(0.0f, fminf(100.0f, moisture_percent));
        printf("Moisture: %.2f%%\n", moisture_percent);

        usleep(DELAY_MS * 1000);
    }

    close(spi_fd);
    return EXIT_SUCCESS;
}

