typedef struct {
    int spi_fd;
    FILE *csv_file;
    int running;
} app_state;

void handle_signal(int sig) {
    (void)sig;
    app_state *state = (app_state *)malloc(sizeof(app_state));
    if (state) {
        state->running = 0;
        free(state);
    }
}

void close_resources(app_state *state) {
    if (state->csv_file) {
        fclose(state->csv_file);
    }
    if (state->spi_fd >= 0) {
        close(state->spi_fd);
    }
    free(state);
}

void log_voltage(int channel, int value) {
    static FILE *csv_file = NULL;
    if (!csv_file) {
        csv_file = fopen(CSV_FILE, "w");
        if (!csv_file) {
            perror("Failed to open CSV file");
            return;
        }
        fprintf(csv_file, "Timestamp,Channel,Voltage(mV)\n");
    }

    time_t now = time(NULL);
    struct tm *tm_now = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_now);

    int voltage = (value * 3300) / 1024;
    fprintf(csv_file, "%s,%d,%d\n", timestamp, channel, voltage);
    fflush(csv_file);
}

int read_adc(int channel) {
    uint8_t tx[3];
    uint8_t rx[3];
    int len = 3;
    int value = 0;

    tx[0] = 0b00100000 | (channel & 0x0F); // 0x00 (single-ended) + channel
    tx[1] = 0;
    tx[2] = 0;

    if (ioctl(state->spi_fd, SPI_IOC_MESSAGE(1), &tx) < 0) {
        perror("SPI read failed");
        return -1;
    }

    value = (rx[1] << 8) | rx[2];
    return value;
}

int init_spi() {
    int spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("SPI mode set failed");
        close(spi_fd);
        return -1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("SPI speed set failed");
        close(spi_fd);
        return -1;
    }

    return spi_fd;
}

int main() {
    app_state *state = (app_state *)malloc(sizeof(app_state));
    if (!state) {
        perror("Memory allocation failed");
        return 1;
    }

    state->running = 1;
    state->spi_fd = -1;
    state->csv_file = NULL;

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    state->spi_fd = init_spi();
    if (state->spi_fd < 0) {
        close_resources(state);
        return 1;
    }

    printf("ADC sampling started. Press Ctrl+C to exit.\n");

    while (state->running) {
        for (int i = 0; i < NUM_CHANNELS; i++) {
            int value = read_adc(i);
            if (value < 0) {
