#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>
#include <errno.h>

#define I2C_BUS 1
#define MAX30102_I2C_ADDR 0x57
#define MAX30102_PART_ID_REGISTER 0x00
#define MAX30102_SPO2_REGISTER 0x14
#define MAX30102_HR_REGISTER 0x15
#define MAX30102_SPO2_BYTES 2
#define MAX30102_HR_BYTES 2
#define LOG_FILE "health_log.txt"
#define SPO2_THRESHOLD 95
#define HR_THRESHOLD 100

typedef struct {
    int i2c_fd;
    FILE *log_file;
    int running;
} app_state;

void log_message(const char *message) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", tm_info);
    fprintf(stderr, "[%s] %s\n", timestamp, message);
    if (app_state.log_file) {
        fprintf(app_state.log_file, "[%s] %s\n", timestamp, message);
        fflush(app_state.log_file);
    }
}

void handle_signal(int signal) {
    app_state.running = 0;
    log_message("Received signal, shutting down...");
}

void close_resources(app_state *state) {
    if (state->i2c_fd >= 0) {
        close(state->i2c_fd);
    }
    if (state->log_file) {
        fclose(state->log_file);
    }
    log_message("Resources released.");
}

int init_i2c(int bus, int addr) {
    char filename[20];
    snprintf(filename, sizeof(filename), "/dev/i2c-%d", bus);
    int fd = open(filename, O_RDWR);
    if (fd < 0) {
        log_message("Failed to open I2C bus.");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        log_message("Failed to set I2C slave address.");
        close(fd);
        return -1;
    }

    return fd;
}

int read_register(int fd, int reg, unsigned char *data, int len) {
    unsigned char buf[1];
    buf[0] = reg;
    if (write(fd, buf, 1) < 0) {
        log_message("I2C write failed.");
        return -1;
    }

    if (read(fd, data, len) < 0) {
        log_message("I2C read failed.");
        return -1;
    }

    return 0;
}

void check_part_id(int fd) {
    unsigned char part_id;
    if (read_register(fd, MAX30102_PART_ID_REGISTER, &part_id, 1) < 0) {
        log_message("Failed to read Part ID register.");
        exit(EXIT_FAILURE);
    }

    if (part_id != 0x12) {
        log_message("Invalid Part ID. Sensor not present.");
        exit(EXIT_FAILURE);
    }
}

void write_register(int fd, int reg, unsigned char *data, int len) {
    unsigned char buf[len + 1];
    buf[0] = reg;
    memcpy(buf + 1, data, len);
    if (write(fd, buf, len + 1) < 0) {
        log_message("I2C write failed.");
        exit(EXIT_FAILURE);
    }
}

void configure_max30102(int fd) {
    unsigned char config[3] = {0x01, 0x02, 0x03}; // Example configuration
    write_register(fd, 0x00, config, 3);
}

void read_spo2_hr(int fd, unsigned short *spo2, unsigned short *hr) {
    unsigned char spo2_data[MAX30102_SPO2_BYTES];
    unsigned char hr_data[MAX30102_HR_BYTES];

    if (read_register(fd, MAX30102_SPO2_REGISTER, spo2_data, MAX30102_SPO2_BYTES) < 0) {
        log_message("Failed to read SpO2 register.");
        exit(EXIT_FAILURE);
    }

    if (read_register(fd, MAX30102_HR_REGISTER, hr_data, MAX30102_HR_BYTES) < 0) {
        log_message("Failed to read Heart Rate register.");
        exit(EXIT_FAILURE);
    }

    *spo2 = (spo2_data[0] << 8) | spo2_data[1];
    *hr = (hr_data[0] << 8) | hr_data[1];
}

int main() {
    app_state state = {0};
    state.running = 1;

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    state.i2c_fd = init_i2c(I2C_BUS, MAX30102_I2C_ADDR);
    if (state.i2c_fd < 0) {
        close_resources(&state);
        return EXIT_FAILURE;
    }

    check_part_id(state.i2c_fd);
    configure_max30102(state.i2c_fd);

    state.log_file = fopen(LOG_FILE, "a");
    if (!state.log_file) {
        log_message("Failed to open log file.");
        close_resources(&state);
        return EXIT_FAILURE;
    }

    while (state.running) {
        unsigned short spo2, hr;
        read_spo2_hr(state.i2c_fd, &spo2, &hr);

        if (spo2 < SPO2_THRESHOLD || hr > HR_THRESHOLD) {
            time_t now = time(NULL);
            struct tm *tm_info = localtime(&now);
            char timestamp[64];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", tm_info);
            fprintf(state.log_file, "[%s] SpO2: %d%%, HR: %d BPM\n", timestamp, spo2, hr);
            fflush(state.log_file);
        }

        sleep(1);
    }

    close_resources(&state);
    return EXIT_SUCCESS;
}

