    int running;
} app_state;

void handle_signal(int sig) {
    if (sig == SIGINT) {
        printf("Received SIGINT, shutting down...\n");
        app_state *state = (app_state *)malloc(sizeof(app_state));
        state->running = 0;
        free(state);
    }
}

int spi_init(int bus, int chip) {
    char path[64];
    snprintf(path, sizeof(path), "/dev/spidev%d.%d", bus, chip);
    int fd = open(path, O_RDWR);
    if (fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("Failed to set SPI mode");
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("Failed to set SPI speed");
        close(fd);
        return -1;
    }

    return fd;
}

void spi_transfer(int fd, uint8_t *tx, uint8_t *rx, size_t len) {
    struct spi_ioc_transfer t = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = len,
        .speed_hz = SPI_SPEED,
        .mode = SPI_MODE
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &t) < 0) {
        perror("SPI transfer failed");
    }
}

uint16_t read_adc(int fd, int channel) {
    uint8_t tx[3] = {1 << 7, (uint8_t)(channel << 4), 0};
    uint8_t rx[3] = {0};

    spi_transfer(fd, tx, rx, 3);

    uint16_t value = (rx[0] << 8) | rx[1];
    return value;
}

void log_data(FILE *csv_file, int channel, uint16_t value) {
    time_t now;
    struct tm *timeinfo;
    char timestamp[30];

    time(&now);
    timeinfo = gmtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(csv_file, "%s,%d,%f\n", timestamp, channel, (double)value / 4096.0 * 3.3);
}

void cleanup(app_state *state) {
    if (state->csv_file) {
        fclose(state->csv_file);
    }
    if (state->spi_fd >= 0) {
        close(state->spi_fd);
    }
}

int main() {
    app_state state = {0};
    state.running = 1;

    signal(SIGINT, handle_signal);

    state.spi_fd = spi_init(SPI_BUS, SPI_CHIP);
    if (state.spi_fd < 0) {
        fprintf(stderr, "SPI initialization failed.\n");
        return 1;
    }

    state.csv_file = fopen(CSV_FILE, "w");
    if (!state.csv_file) {
        perror("Failed to open CSV file");
        cleanup(&state);
        return 1;
    }

    fprintf(state.csv_file, "Timestamp,Channel,Voltage\n");

    while (state.running) {
        for (int ch = 0; ch < CHANNELS; ch++) {
            uint16_t value = 0;
            int retries = 3;
            int success = 0;

            while (retries-- && !success) {
                value = read_adc(state.spi_fd, ch);
                success = 1;
            }

            if (success) {
                log_data(state.csv_file, ch, value);
            } else {
                fprintf(stderr, "SPI read failed for channel %d\n", ch);
            }

            usleep(INTERVAL_MS * 1000);
        }
    }

    cleanup(&state);
    return 0;
}

