#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define SPI_MODE SPI_MODE_0
#define SPI_BITS 8
#define SPI_DELAY 500000  // 500 ms in microseconds

#define BUZZER_PIN 24
#define ADC_CHANNEL 0
#define ADC_THRESHOLD 500

typedef struct {
    int spi_fd;
    struct gpiod_line *buzzer_line;
} app_state;

void handle_sigint(int sig) {
    app_state *state = (app_state *)malloc(sizeof(app_state));
    if (state == NULL) {
        fprintf(stderr, "Failed to allocate memory for app_state\n");
        exit(EXIT_FAILURE);
    }

    if (state->spi_fd >= 0) {
        close(state->spi_fd);
    }

    if (state->buzzer_line) {
        gpiod_line_release(state->buzzer_line);
    }

    printf("\nSIGINT received. Cleaning up...\n");
    exit(EXIT_SUCCESS);
}

uint16_t read_adc(int spi_fd, uint8_t channel) {
    uint8_t tx[3];
    uint8_t rx[3];
    uint16_t adc_value;

    tx[0] = 1 << 7;  // Start bit
    tx[1] = (uint8_t)(channel << 4);  // Channel select
    tx[2] = 0;  // No data

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(3), &tx) < 0) {
        perror("SPI read failed");
        return 0;
    }

    adc_value = (rx[1] << 8) | rx[2];
    return adc_value;
}

int init_spi() {
    int spi_fd = open(SPI_DEVICE, O_RDWR | O_NOCTTY | O_SYNC);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    struct spi_ioc_transfer spi;
    memset(&spi, 0, sizeof(spi));
    spi.fd = spi_fd;
    spi.len = SPI_BITS;
    spi.speed_hz = SPI_SPEED;
    spi.delay_usecs = SPI_DELAY;
    spi.bits_per_word = SPI_BITS;
    spi.mode = SPI_MODE;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &spi) < 0) {
        perror("SPI mode setup failed");
        close(spi_fd);
        return -1;
    }

    return spi_fd;
}

int init_gpio() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;

    chip = gpiod_chip_open("/dev/gpiochip24");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    line = gpiod_line_get(chip, BUZZER_PIN);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(line, "buzzer", GPIOD_LINE_REQUEST_OUTPUT_FLAGS_DEFAULT) < 0) {
        perror("Failed to request GPIO line");
        gpiod_line_put(line);
        gpiod_chip_close(chip);
        return -1;
    }

    gpiod_line_set_value(line, 0);  // Initial state: buzzer off

    return (int)line;
}

void cleanup_gpio(struct gpiod_line *line) {
    if (line) {
        gpiod_line_set_value(line, 0);
        gpiod_line_put(line);
    }
}

int main() {
    app_state state = {0};

    signal(SIGINT, handle_sigint);

    state.spi_fd = init_spi();
    if (state.spi_fd < 0) {
        fprintf(stderr, "SPI initialization failed\n");
        return EXIT_FAILURE;
    }

    state.buzzer_line = (struct gpiod_line *)init_gpio();
    if (!state.buzzer_line) {
        fprintf(stderr, "GPIO initialization failed\n");
        close(state.spi_fd);
        return EXIT_FAILURE;
    }

    while (1) {
        uint16_t adc_value = read_adc(state.spi_fd, ADC_CHANNEL);
        if (adc_value == 0) {
            fprintf(stderr, "ADC read failed\n");
            break;
        }

        if (adc_value >= ADC_THRESHOLD) {
            if (gpiod_line_set_value(state.buzzer_line, 1) < 0) {
                perror("Failed to turn on buzzer");
            }
        } else {
            if (gpiod_line_set_value(state.buzzer_line, 0) < 0) {
                perror("Failed to turn off buzzer");
            }
        }

        usleep(500000);  // 500 ms
    }

    cleanup_gpio(state.buzzer_line);
    close(state.spi_fd);

    return EXIT_SUCCESS;
}

