#define ADS1115_POINTER 0x00
#define ADS1115_GAIN 0x0080  // +/- 6.144V
#define ADS1115_MODE_SINGLE 0x0000
#define ADS1115_MODE_CONTINUOUS 0x0100
#define ADS1115_SAMPLE_RATE 0x0008  // 860 SPS
#define ADS1115_CONFIG_DEFAULT (ADS1115_GAIN | ADS1115_MODE_SINGLE | ADS1115_SAMPLE_RATE)

#define RELAY_PIN 17
#define REED_PIN 27
#define CALIBRATION_SAMPLES 10
#define CALIBRATION_DELAY_MS 50
#define SAMPLE_INTERVAL_MS 200
#define RELAY_DURATION_MS 3000
#define LOG_FILE "/var/log/door_events.log"

typedef struct {
    int i2c_fd;
    int relay_pin;
    int reed_pin;
    int calibration_samples;
    int threshold;
