void setup_gpio(int pin, int direction) {
    char path[64];
    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/direction", pin);
    FILE *fp = fopen(path, "w");
    if (!fp) {
        syslog(LOG_ERR, "Failed to open GPIO direction: %s", strerror(errno));
        return;
