int read_adc(int i2c_fd, int channel) {
    unsigned char config[2];
    config[0] = ADS1115_CONFIG_REGISTER;
    config[1] = ADS1115_CONFIG_DEFAULT | (channel << 6);

    if (ioctl(i2c_fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        syslog(LOG_ERR, "Failed to set I2C slave address: %s", strerror(errno));
        return -1;
    }

    if (write(i2c_fd, config, 2) != 2) {
        syslog(LOG_ERR, "Failed to write to ADC: %s", strerror(errno));
        return -1;
    }

    usleep(1000); // Wait for conversion

    unsigned char data[2];
    if (read(i2c_fd, data, 2) != 2) {
        syslog(LOG_ERR, "Failed to read from ADC: %s", strerror(errno));
        return -1;
    }

    int value = (data[0] << 8) | data[1];
    return value;
}

void calibrate_adc(int i2c_fd, int *threshold) {
    int samples[CALIBRATION_SAMPLES];
    int sum = 0;

    for (int i = 0; i < CALIBRATION_SAMPLES; i++) {
        int value = read_adc(i2c_fd, 0);
        if (value < 0) {
            syslog(LOG_ERR, "ADC read failed during calibration");
            continue;
        }
        samples[i] = value;
        sum += value;
        usleep(CALIBRATION_DELAY_MS * 1000);
    }

    *threshold = sum / CALIBRATION_SAMPLES;
    syslog(LOG_INFO, "Calibrated threshold: %d", *threshold);
