    if (state.i2c_fd < 0) {
        syslog(LOG_ERR, "Failed to open I2C bus: %s", strerror(errno));
        return 1;
    }

    // Calibrate ADC
    calibrate_adc(state.i2c_fd, &state.threshold);

    // Setup GPIO
    setup_gpio(RELAY_PIN, 1);
    setup_gpio(REED_PIN, 0);

    // Main loop
    state.running = 1;
    while (state.running) {
        int value = read_adc(state.i2c_fd, 0);
        if (value < 0) {
            syslog(LOG_ERR, "ADC read failed, continuing...");
            usleep(SAMPLE_INTERVAL_MS * 1000);
            continue;
        }

        if (value < state.threshold) {
            if (!state.relay_active) {
                activate_relay(state.i2c_fd, RELAY_PIN);
                state.relay_active = 1;
                syslog(LOG_INFO, "Relay activated");
            }
        } else {
            if (state.relay_active) {
                deactivate_relay(RELAY_PIN);
                state.relay_active = 0;
                syslog(LOG_INFO, "Relay deactivated");
                read_reed_sensor(REED_PIN);
            }
        }

        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    // Cleanup
    close(state.i2c_fd);
    syslog(LOG_INFO, "Application exiting cleanly");
    return 0;
}

