    gpiod_line_set_value(cs_pins[cs_pin].cs_line, 0);

    uint8_t tx[3] = {1 << 7, (uint8_t)(channel << 4), 0};
    uint8_t rx[3] = {0};

    struct spi_ioc_transfer spi;
    memset(&spi, 0, sizeof(spi));
    spi.tx_buf = (unsigned long)tx;
    spi.rx_buf = (unsigned long)rx;
    spi.len = 3;
    spi.speed_hz = SPI_SPEED;
    spi.mode = SPI_MODE;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &spi) < 0) {
        perror("SPI transfer failed");
        gpiod_line_set_value(cs_pins[cs_pin].cs_line, 1);
        return -1;
    }

    gpiod_line_set_value(cs_pins[cs_pin].cs_line, 1);

    int adc_value = (rx[1] << 8) | rx[2];
    return adc_value;
}

void write_csv_line(int sensor1, int sensor2, int sensor3) {
    char buffer[256];
    struct timeval tv;
    gettimeofday(&tv, NULL);
    long timestamp = tv.tv_sec * 1000 + tv.tv_usec / 1000;

    snprintf(buffer, sizeof(buffer), "%ld,%d,%d,%d\n", timestamp, sensor1, sensor2, sensor3);

    if (write(file_fd, buffer, strlen(buffer)) < 0) {
        perror("Failed to write to CSV file");
    }
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if (init_spi() < 0) {
        fprintf(stderr, "SPI initialization failed\n");
        return -1;
    }

    if (init_cs_pins() < 0) {
        fprintf(stderr, "CS pin initialization failed\n");
        release_spi();
        return -1;
    }

    file_fd = open(CSV_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (file_fd < 0) {
        perror("Failed to open CSV file");
        release_cs_pins();
        release_spi();
        return -1;
    }

    if (lseek(file_fd, 0, SEEK_SET) == 0) {
        if (write(file_fd, "timestamp,sensor1,sensor2,sensor3\n", 34) < 0) {
            perror("Failed to write CSV header");
        }
    }

    while (running) {
        int sensor1 = read_adc(0, CHANNEL);
        int sensor2 = read_adc(1, CHANNEL);
        int sensor3 = read_adc(2, CHANNEL);

        write_csv_line(sensor1, sensor2, sensor3);

        usleep(DELAY_MS * 1000);
    }

    release_cs_pins();
    release_spi();
    release_file();

    return 0;
}
