#include <signal.h>
#include <time.h>
#include <errno.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define SPI_MODE SPI_MODE_0
#define CE_PIN 8
#define RELAY_PIN 18
#define DEFAULT_THRESHOLD 30
#define DEFAULT_PUMP_DURATION 10
#define DEFAULT_SLEEP_INTERVAL 60
#define MAX_RETRIES 3
#define LOG_FILE "irrigation.log"

typedef struct {
    int threshold;
    int pump_duration;
    int sleep_interval;
} Config;

Config config = {DEFAULT_THRESHOLD, DEFAULT_PUMP_DURATION, DEFAULT_SLEEP_INTERVAL};

void parse_arguments(int argc, char *argv[]) {
    int opt;
    while ((opt = getopt(argc, argv, "t:d:s:")) != -1) {
        switch (opt) {
            case 't':
                config.threshold = atoi(optarg);
                break;
            case 'd':
                config.pump_duration = atoi(optarg);
                break;
            case 's':
                config.sleep_interval = atoi(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold] [-d duration] [-s interval]\n", argv[0]);
                exit(EXIT_FAILURE);
        }
    }
}

int open_spi() {
    int fd = open(SPI_DEVICE, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    struct spi_ioc_transfer spi;
    memset(&spi, 0, sizeof(spi));
    spi.speed_hz = SPI_SPEED;
    spi.mode = SPI_MODE;
    spi.bits_per_word = 8;

    if (ioctl(fd, SPI_IOC_WR_MODE, &spi.mode) < 0) {
        perror("Failed to set SPI mode");
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_SPEED_HZ, &spi.speed_hz) < 0) {
        perror("Failed to set SPI speed");
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &spi.bits_per_word) < 0) {
        perror("Failed to set SPI bits per word");
        close(fd);
        return -1;
    }

    return fd;
}

int read_adc(int fd) {
    uint8_t tx[3] = {1, 0, 0};
    uint8_t rx[3];

    for (int retry = 0; retry < MAX_RETRIES; retry++) {
        if (spi_write_read(fd, tx, 3, rx, 3) < 0) {
            fprintf(stderr, "SPI read failed, retrying...\n");
            usleep(100000);
            continue;
        }

        int adc_value = (rx[1] << 8) | rx[0];
        return adc_value;
    }

    fprintf(stderr, "SPI read failed after %d retries, skipping cycle.\n", MAX_RETRIES);
    return -1;
}

void write_relay(int fd, int value) {
    if (value) {
        if (ioctl(fd, GPIO_SET, 1 << RELAY_PIN) < 0) {
            perror("Failed to set relay high");
        }
    } else {
        if (ioctl(fd, GPIO_CLR, 1 << RELAY_PIN) < 0) {
            perror("Failed to set relay low");
        }
    }
}

void log_message(const char *message) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file) {
        time_t now = time(NULL);
        char *timestamp = ctime(&now);
        fprintf(log_file, "%s%s\n", timestamp, message);
        fclose(log_file);
    } else {
        perror("Failed to open log file");
    }
}

void handle_signal(int signal) {
    log_message("Received signal, shutting down...");
    if (config.pump_duration > 0) {
        write_relay(relay_fd, 0);
        log_message("Pump turned off.");
    }

    if (spi_fd >= 0) {
        close(spi_fd);
    }

    if (relay_fd >= 0) {
        gpiod_line_release(relay_line);
    }

    exit(EXIT_SUCCESS);
}

int main(int argc, char *argv[]) {
    parse_arguments(argc, argv);

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Initialize SPI
    spi_fd = open_spi();
    if (spi_fd < 0) {
        log_message("Failed to initialize SPI, exiting.");
        return EXIT_FAILURE;
    }

    // Initialize relay
    const char *chip_name = "gpiochip0";
    struct gpiod_chip *chip = gpiod_chip_open_name(chip_name);
    if (!chip) {
        perror("Failed to open GPIO chip");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    relay_line = gpiod_line_get(chip, RELAY_PIN);
    if (!relay_line) {
        perror("Failed to get relay line");
        gpiod_chip_close(chip);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(relay_line, "pump_relay", 0) < 0) {
        perror("Failed to request relay line");
        gpiod_line_release(relay_line);
        gpiod_chip_close(chip);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    while (1) {
        int adc_value = read_adc(spi_fd);
        if (adc_value < 0) {
            usleep(config.sleep_interval * 1000000);
            continue;
        }

        double voltage = (adc_value * 3.3) / 1023.0;
        double moisture_percent = (voltage / 3.3) * 100.0;

        log_message("Moisture reading: %.2f%%", moisture_percent);

        if (moisture_percent < config.threshold) {
            log_message("Moisture level below threshold, activating pump.");
            write_relay(relay_fd, 1);
            usleep(config.pump_duration * 1000000);
            write_relay(relay_fd, 0);
            log_message("Pump deactivated.");
        }

        usleep(config.sleep_interval * 1000000);
    }

    return EXIT_SUCCESS;
}

