#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>
#include <errno.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define SPI_MODE SPI_MODE_0
#define SPI_BITS 8
#define SPI_DELAY 100000 // 100 microseconds

#define MCP3008_CHANNEL 0
#define GPIO_CE0 8
#define GPIO_CLK 11
#define GPIO_MOSI 10
#define GPIO_MISO 9

typedef struct {
    int spi_fd;
    struct gpiod_line *ce_line;
    FILE *log_file;
    int running;
} app_state;

void handle_signal(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        printf("Received signal, shutting down...\n");
        exit(EXIT_SUCCESS);
    }
}

void log_peak(const char *timestamp, int value) {
    if (!app_state.log_file) {
        fprintf(stderr, "Error: Log file not open.\n");
        return;
    }

    fprintf(app_state.log_file, "%s %d\n", timestamp, value);
    fflush(app_state.log_file);
}

void init_spi(app_state *state) {
    state->spi_fd = open(SPI_DEVICE, O_RDWR | O_NOCTTY | O_SYNC);
    if (state->spi_fd < 0) {
        fprintf(stderr, "Error opening SPI device: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    struct spi_ioc_transfer spi;
    memset(&spi, 0, sizeof(spi));
    spi.speed_hz = SPI_SPEED;
    spi.bits_per_word = SPI_BITS;
    spi.delay_usecs = SPI_DELAY;

    if (ioctl(state->spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(state->spi_fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(state->spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        fprintf(stderr, "Error setting SPI speed: %s\n", strerror(errno));
        close(state->spi_fd);
        exit(EXIT_FAILURE);
    }
}

void init_gpio(app_state *state) {
    struct gpiod_chip *chip;
    struct gpiod_line *line;

    chip = gpiod_chip_open(GPIO_CE0);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    line = gpiod_line_get(chip, GPIO_CE0);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(line, "ce", 1) < 0) {
        fprintf(stderr, "Error requesting GPIO line: %s\n", strerror(errno));
        gpiod_line_put(line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    state->ce_line = line;
}

void init_log_file(app_state *state) {
    state->log_file = fopen("/var/log/sound_events.log", "a");
    if (!state->log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }
}

void deinit_gpio(app_state *state) {
    if (state->ce_line) {
        gpiod_line_put(state->ce_line);
    }
    if (state->ce_line) {
        gpiod_chip_close(state->ce_line->chip);
    }
}

void deinit_spi(app_state *state) {
    if (state->spi_fd >= 0) {
        close(state->spi_fd);
    }
}

void deinit_log_file(app_state *state) {
    if (state->log_file) {
        fclose(state->log_file);
    }
}

int read_adc_value(app_state *state) {
    uint8_t tx[1];
    uint8_t rx[1];
    struct spi_ioc_transfer spi;
    int ret;

    tx[0] = 1 << 7 | (MCP3008_CHANNEL & 0x07) << 4;

    memset(&spi, 0, sizeof(spi));
    spi.tx_buf = (unsigned long)tx;
    spi.rx_buf = (unsigned long)rx;
    spi.len = 1;
    spi.speed_hz = SPI_SPEED;
    spi.bits_per_word = SPI_BITS;
    spi.delay_usecs = SPI_DELAY;

    gpiod_line_set_value(state->ce_line, 1);
    ret = ioctl(state->spi_fd, SPI_IOC_MESSAGE(1), &spi);
    gpiod_line_set_value(state->ce_line, 0);

    if (ret < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }

    return rx[0] & 0xFF;
}

void sample_and_log(app_state *state) {
    int value;
    char timestamp[64];

    value = read_adc_value(state);
    if (value < 0) {
        fprintf(stderr, "ADC read failed.\n");
        return;
    }

    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", tm_info);

    if (value > 800) { // Threshold for peak detection
        log_peak(timestamp, value);
    }
}

int main() {
    app_state state = {0};
    struct sigaction sa;

    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting SIGTERM handler: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    init_gpio(&state);
    init_spi(&state);
    init_log_file(&state);

    state.running = 1;
    while (state.running) {
        sample_and_log(&state);
        usleep(10000); // 10 ms interval
    }

    deinit_log_file(&state);
    deinit_spi(&state);
    deinit_gpio(&state);

    return 0;
}

