#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <syslog.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>
#include <math.h>

#define I2C_BUS 1
#define I2C_ADDR 0x48
#define ADC_REGISTER 0x00
#define SAMPLE_RATE_HZ 1
#define CIRCULAR_BUFFER_SIZE 10
#define THRESHOLD_GAUSS 500.0
#define GPIO_PIN 27
#define GPIO_LINE_NAME "gpio27"

typedef struct {
    float values[CIRCULAR_BUFFER_SIZE];
    int head;
    int tail;
    int count;
} CircularBuffer;

void init_circular_buffer(CircularBuffer *buffer) {
    buffer->head = 0;
    buffer->tail = 0;
    buffer->count = 0;
}

void add_to_buffer(CircularBuffer *buffer, float value) {
    buffer->values[buffer->head] = value;
    buffer->head = (buffer->head + 1) % CIRCULAR_BUFFER_SIZE;
    buffer->count = (buffer->count < CIRCULAR_BUFFER_SIZE) ? buffer->count + 1 : CIRCULAR_BUFFER_SIZE;
}

float get_rolling_average(CircularBuffer *buffer) {
    float sum = 0.0;
    for (int i = 0; i < buffer->count; i++) {
        sum += buffer->values[(buffer->tail + i) % CIRCULAR_BUFFER_SIZE];
    }
    return sum / buffer->count;
}

void log_message(const char *message) {
    syslog(LOG_INFO, "%s", message);
}

void log_error(const char *message, int error_code) {
    syslog(LOG_ERR, "%s: %s", message, strerror(error_code));
}

void handle_signal(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        log_message("Received signal to terminate.");
    }
}

void setup_gpio(gpiod_line *gpio_line) {
    int fd = gpiod_chip_open("/dev/gpiochip0");
    if (fd < 0) {
        log_error("Failed to open GPIO chip", errno);
        exit(EXIT_FAILURE);
    }

    *gpio_line = gpiod_line_get(fd, GPIO_LINE_NAME);
    if (!gpio_line) {
        log_error("Failed to get GPIO line", errno);
        close(fd);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(*gpio_line, "motor_shutdown", 0) < 0) {
        log_error("Failed to request GPIO line as output", errno);
        gpiod_line_put(*gpio_line);
        close(fd);
        exit(EXIT_FAILURE);
    }
}

void cleanup_gpio(gpiod_line *gpio_line) {
    if (gpio_line) {
        gpiod_line_set_value(*gpio_line, 0);
        gpiod_line_put(*gpio_line);
    }
}

void setup_i2c(int *i2c_fd) {
    char i2c_bus_path[32];
    snprintf(i2c_bus_path, sizeof(i2c_bus_path), "/dev/i2c-%d", I2C_BUS);

    *i2c_fd = open(i2c_bus_path, O_RDWR);
    if (*i2c_fd < 0) {
        log_error("Failed to open I2C bus", errno);
        exit(EXIT_FAILURE);
    }

    if (ioctl(*i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        log_error("Failed to set I2C slave address", errno);
        close(*i2c_fd);
        exit(EXIT_FAILURE);
    }
}

void cleanup_i2c(int *i2c_fd) {
    if (*i2c_fd >= 0) {
        close(*i2c_fd);
    }
}

float read_adc_value(int i2c_fd) {
    unsigned char config[2] = {0x84, 0x00}; // 16-bit signed, 128 samples, 1 Hz
    if (write(i2c_fd, config, 2) < 0) {
        log_error("Failed to write ADC configuration", errno);
        return -1.0;
    }

    usleep(100000); // Wait for conversion to complete

    unsigned char data[2];
    if (read(i2c_fd, data, 2) < 0) {
        log_error("Failed to read ADC data", errno);
        return -1.0;
    }

    int raw_value = (data[0] << 8) | data[1];
    float voltage = (raw_value * 3.3) / 32768.0;

    if (voltage < 0.0 || voltage > 3.3) {
        log_message("ADC voltage out of range");
        return -1.0;
    }

    return voltage;
}

float voltage_to_gauss(float voltage) {
    float gauss = (voltage / 3.3) * 1000.0; // Assuming 1V = 1000 Gauss
    return gauss;
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    int i2c_fd = -1;
    setup_i2c(&i2c_fd);

    gpiod_line gpio_line = NULL;
    setup_gpio(&gpio_line);

    CircularBuffer buffer;
    init_circular_buffer(&buffer);

    struct timespec sleep_time = {0, 1000000000 / SAMPLE_RATE_HZ}; // 1 Hz

    while (1) {
        float voltage = read_adc_value(i2c_fd);
        if (voltage < 0.0) {
            log_message("ADC read failed, skipping sample");
            nanosleep(&sleep_time, NULL);
            continue;
        }

        add_to_buffer(&buffer, voltage);
        float average_voltage = get_rolling_average(&buffer);
        float gauss = voltage_to_gauss(average_voltage);

        log_message("Voltage: %.2f V, Gauss: %.2f G", average_voltage, gauss);

        if (gauss > THRESHOLD_GAUSS) {
            log_message("Threshold exceeded: %.2f G", gauss);
            gpiod_line_set_value(gpio_line, 1);
        }

        nanosleep(&sleep_time, NULL);
    }

    cleanup_gpio(&gpio_line);
    cleanup_i2c(&i2c_fd);
    closelog();
    return 0;
}

