#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>
#include <signal.h>
#include <time.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define SPI_MODE SPI_MODE_0
#define ADC_CHANNEL 0
#define RELAY_PIN 18
#define THRESHOLD 300
#define WATERING_DURATION 10
#define LOG_FILE "watering_events.txt"

volatile int running = 1;

void handle_signal(int sig) {
    running = 0;
}

int init_spi() {
    int fd = open(SPI_DEVICE, O_RDWR | O_SYNC);
    if (fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    struct spi_ioc_transfer transfer;
    memset(&transfer, 0, sizeof(transfer));
    transfer.tx_buf = (unsigned long)malloc(1);
    transfer.rx_buf = (unsigned long)malloc(1);
    transfer.len = 1;
    transfer.speed_hz = SPI_SPEED;
    transfer.mode = SPI_MODE;

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &transfer) < 0) {
        perror("SPI_IOC_MESSAGE failed");
        free(transfer.tx_buf);
        free(transfer.rx_buf);
        close(fd);
        return -1;
    }

    free(transfer.tx_buf);
    free(transfer.rx_buf);

    return fd;
}

int read_adc(int fd, int channel) {
    unsigned char tx[3];
    unsigned char rx[3];
    tx[0] = 0b10100000 | (channel & 0x07);
    tx[1] = 0;
    tx[2] = 0;

    struct spi_ioc_transfer transfer;
    memset(&transfer, 0, sizeof(transfer));
    transfer.tx_buf = (unsigned long)tx;
    transfer.rx_buf = (unsigned long)rx;
    transfer.len = 3;
    transfer.speed_hz = SPI_SPEED;
    transfer.mode = SPI_MODE;

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &transfer) < 0) {
        perror("SPI_IOC_MESSAGE failed");
        return -1;
    }

    int value = (rx[1] << 8) | rx[2];
    if (value < 0 || value > 1023) {
        fprintf(stderr, "Invalid ADC value: %d\n", value);
        return -1;
    }

    return value;
}

void init_gpio() {
    struct gpiod_line *relay_line = gpiod_line_get("BCM18", GPIOD_LINE_DIRECTION_OUTPUT, GPIOD_LINE_FLAG_ACTIVE_LOW);
    if (!relay_line) {
        perror("Failed to get GPIO line");
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(relay_line, "Relay", GPIOD_LINE_FLAG_ACTIVE_LOW) < 0) {
        perror("Failed to request GPIO line");
        gpiod_line_put(relay_line);
        exit(EXIT_FAILURE);
    }

    gpiod_line_set_value(relay_line, 1); // Initially off
    gpiod_line_put(relay_line);
}

void activate_pump(int fd) {
    gpiod_line_set_value(fd, 0);
}

void deactivate_pump(int fd) {
    gpiod_line_set_value(fd, 1);
}

void log_event(const char *timestamp, int moisture) {
    FILE *file = fopen(LOG_FILE, "a");
    if (!file) {
        perror("Failed to open log file");
        return;
    }

    fprintf(file, "%s, %d\n", timestamp, moisture);
    fclose(file);
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    int spi_fd = init_spi();
    if (spi_fd < 0) {
        exit(EXIT_FAILURE);
    }

    struct gpiod_line *relay_line = gpiod_line_get("BCM18", GPIOD_LINE_DIRECTION_OUTPUT, GPIOD_LINE_FLAG_ACTIVE_LOW);
    if (!relay_line) {
        perror("Failed to get GPIO line");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(relay_line, "Relay", GPIOD_LINE_FLAG_ACTIVE_LOW) < 0) {
        perror("Failed to request GPIO line");
        gpiod_line_put(relay_line);
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    gpiod_line_set_value(relay_line, 1); // Initially off
    gpiod_line_put(relay_line);

    while (running) {
        int moisture = read_adc(spi_fd, ADC_CHANNEL);
        if (moisture < 0) {
            fprintf(stderr, "ADC read failed, retrying...\n");
            sleep(1);
            continue;
        }

        time_t now = time(NULL);
        struct tm *tm_now = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_now);

        if (moisture < THRESHHOLD) {
            printf("Moisture level low: %d, activating pump...\n", moisture);
            activate_pump(relay_line);
            sleep(WATERING_DURATION);
            deactivate_pump(relay_line);
            log_event(timestamp, moisture);
        }

        sleep(60);
    }

    deactivate_pump(relay_line);
    close(spi_fd);
    gpiod_line_put(relay_line);
    printf("Shutting down cleanly.\n");
    return 0;
}

