#define SPI_BUS 0
#define SPI_CHIP 0
#define SPI_MODE SPI_MODE_0
#define SPI_SPEED 1000000
#define SPI_MAX_TRANSFER_SIZE 2
#define SPI_TRANSFER_COUNT 1
#define SPI_DELAY_MS 1000

#define ADC_CHANNEL 0
#define ADC_VDD 3300
#define ADC_FULL_SCALE 1023

typedef enum {
    RAIN_NONE,
    RAIN_LIGHT,
    RAIN_MEDIUM,
    RAIN_HEAVY
} RainIntensity;

static int spi_fd = -1;
static int initialized = 0;

void handle_signal(int signal) {
    if (signal == SIGINT) {
        if (initialized) {
            close(spi_fd);
            printf("SPI device closed.\n");
        }
        exit(EXIT_SUCCESS);
    }
}

int init_spi() {
    char spi_path[32];
    snprintf(spi_path, sizeof(spi_path), "/dev/spidev%d.%d", SPI_BUS, SPI_CHIP);

    spi_fd = open(spi_path, O_RDWR | O_NOCTTY | O_NDELAY);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    struct spi_ioc_transfer spi;
    memset(&spi, 0, sizeof(spi));
    spi.speed_hz = SPI_SPEED;
    spi.mode = SPI_MODE;
    spi.bits_per_word = 8;
    spi.delay_usecs = 0;
    spi.tx_buf = NULL;
    spi.rx_buf = NULL;
    spi.len = 0;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(SPI_TRANSFER_COUNT), &spi) < 0) {
        perror("Failed to set SPI parameters");
        close(spi_fd);
        return -1;
    }

    initialized = 1;
    return 0;
}

int read_adc() {
    uint8_t tx[SPI_MAX_TRANSFER_SIZE];
    uint8_t rx[SPI_MAX_TRANSFER_SIZE];

    tx[0] = 1 << 7 | (ADC_CHANNEL << 4) | SPI_MODE;
    tx[1] = 0;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(SPI_TRANSFER_COUNT), &spi) < 0) {
        perror("SPI transfer failed");
        return -1;
    }

    uint16_t adc_value = (rx[0] << 8) | rx[1];
    return adc_value;
}

RainIntensity map_adc_to_intensity(uint16_t adc_value) {
    if (adc_value < 200) {
        return RAIN_NONE;
    } else if (adc_value < 500) {
        return RAIN_LIGHT;
    } else if (adc_value < 800) {
        return RAIN_MEDIUM;
    } else {
        return RAIN_HEAVY;
    }
}

void log_rain_data(time_t timestamp, uint16_t adc_value, RainIntensity intensity) {
    char buffer[128];
    struct tm *time_info = localtime(&timestamp);
    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", time_info);
    printf("%s, ADC: %d, Intensity: %s\n", buffer, adc_value, intensity == RAIN_NONE ? "None" : intensity == RAIN_LIGHT ? "Light" : intensity == RAIN_MEDIUM ? "Medium" : "Heavy");
}

int main() {
    signal(SIGINT, handle_signal);

    if (init_spi() < 0) {
        fprintf(stderr, "Failed to initialize SPI\n");
        return EXIT_FAILURE;
    }

    while (1) {
        uint16_t adc_value = 0;
        time_t timestamp = time(NULL);

        if (read_adc() < 0) {
            fprintf(stderr, "SPI transfer failed, skipping this reading.\n");
            usleep(SPI_DELAY_MS * 1000);
            continue;
        }

        adc_value = (rx[0] << 8) | rx[1];
        log_rain_data(timestamp, adc_value, map_adc_to_intensity(adc_value));

        usleep(SPI_DELAY_MS * 1000);
    }

    return EXIT_SUCCESS;
}

