#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/gpio.h>
#include <stdint.h>
#include <time.h>

#define I2C_BUS 1
#define I2C_ADDR 0x48
#define ADC_REGISTER 0x00
#define PGA_GAIN 4096
#define DEFAULT_THRESHOLD 100.0
#define LED_PIN 17
#define BLINK_DURATION_MS 1000
#define BLINK_ON_MS 50
#define BLINK_OFF_MS 50
#define POLL_INTERVAL_MS 100

typedef struct {
    int i2c_fd;
    int gpio_fd;
    double threshold;
    int blink_active;
    int running;
} app_state;

void handle_signal(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        app_state *state = (app_state *)malloc(sizeof(app_state));
        state->running = 0;
        printf("\nReceived signal, shutting down...\n");
        // Turn off LED
        if (state->gpio_fd >= 0) {
            gpio_write(state->gpio_fd, LED_PIN, 0);
            gpio_close(state->gpio_fd);
        }
        if (state->i2c_fd >= 0) {
            close(state->i2c_fd);
        }
        free(state);
        exit(EXIT_SUCCESS);
    }
}

void init_gpio(app_state *state) {
    state->gpio_fd = -1;
    state->gpio_fd = gpio_open(LED_PIN, GPIOHANDLE_REQUEST_OUTPUT);
    if (state->gpio_fd < 0) {
        perror("Failed to open GPIO");
        exit(EXIT_FAILURE);
    }
    gpio_write(state->gpio_fd, LED_PIN, 0);
}

void init_i2c(app_state *state) {
    char i2c_bus_path[32];
    snprintf(i2c_bus_path, sizeof(i2c_bus_path), "/dev/i2c-%d", I2C_BUS);
    state->i2c_fd = open(i2c_bus_path, O_RDWR);
    if (state->i2c_fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    if (ioctl(state->i2c_fd, I2C_TEN, 0) < 0) {
        perror("Failed to set I2C to 10-bit mode");
        close(state->i2c_fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(state->i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(state->i2c_fd);
        exit(EXIT_FAILURE);
    }
}

double read_adc(app_state *state) {
    uint16_t raw_value;
    uint8_t buffer[2];

    if (read(state->i2c_fd, buffer, 2) != 2) {
        perror("I2C read failed");
        return -1.0;
    }

    raw_value = (buffer[0] << 8) | buffer[1];

    double voltage = (raw_value * 1.25) / 32768.0;
    double magnetic_field = (voltage * 1000000.0) / 0.00000125; // Convert to Gauss

    return magnetic_field;
}

void blink_led(app_state *state) {
    state->blink_active = 1;
    struct timespec ts = {0, 0};

    for (int i = 0; i < 20; i++) {
        gpio_write(state->gpio_fd, LED_PIN, 1);
        nanosleep(&ts, NULL);
        nanosleep(&ts, NULL);
        gpio_write(state->gpio_fd, LED_PIN, 0);
        nanosleep(&ts, NULL);
        nanosleep(&ts, NULL);
    }

    state->blink_active = 0;
}

int main(int argc, char *argv[]) {
    app_state state = {0};
    double threshold = DEFAULT_THRESHOLD;
    int opt;

    while ((opt = getopt(argc, argv, "t:")) != -1) {
        switch (opt) {
            case 't':
                threshold = atof(optarg);
                if (threshold < 0.0) {
                    fprintf(stderr, "Threshold must be a positive value.\n");
                    exit(EXIT_FAILURE);
                }
                break;
            default:
                fprintf(stderr, "Usage: %s [-t <threshold>]\n", argv[0]);
                exit(EXIT_FAILURE);
        }
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    init_gpio(&state);
    init_i2c(&state);

    state.running = 1;
    while (state.running) {
        double field = read_adc(&state);
        if (field < 0.0) {
            fprintf(stderr, "ADC communication failed, retrying...\n");
            usleep(100000);
            continue;
        }

        printf("Magnetic Field: %.2f Gauss\n", field);

        if (field > threshold && !state.blink_active) {
            blink_led(&state);
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    if (state.gpio_fd >= 0) {
        gpio_write(state->gpio_fd, LED_PIN, 0);
        gpio_close(state->gpio_fd);
    }

    if (state.i2c_fd >= 0) {
        close(state->i2c_fd);
    }

    return 0;
}

