#define LED_PIN 17
#define BLINK_DURATION_MS 1000
#define BLINK_ON_MS 50
#define BLINK_OFF_MS 50
#define POLL_INTERVAL_MS 100

typedef struct {
    int i2c_fd;
    int gpio_fd;
    double threshold;
    int blink_active;
    int running;
} app_state;

void handle_signal(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        app_state *state = (app_state *)malloc(sizeof(app_state));
        state->running = 0;
        printf("\nReceived signal, shutting down...\n");
        // Turn off LED
        if (state->gpio_fd >= 0) {
            gpio_write(state->gpio_fd, LED_PIN, 0);
            gpio_close(state->gpio_fd);
        }
        if (state->i2c_fd >= 0) {
            close(state->i2c_fd);
        }
        free(state);
        exit(EXIT_SUCCESS);
    }
}

void init_gpio(app_state *state) {
    state->gpio_fd = -1;
    state->gpio_fd = gpio_open(LED_PIN, GPIOHANDLE_REQUEST_OUTPUT);
    if (state->gpio_fd < 0) {
        perror("Failed to open GPIO");
        exit(EXIT_FAILURE);
    }
    gpio_write(state->gpio_fd, LED_PIN, 0);
}

