#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <signal.h>
#include <errno.h>
#include <time.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_MAX_SPEED_HZ 1000000
#define SPI_CHANNEL 0
#define SPI_CS_PIN 8
#define SPI_DELAY_MS 500

int spi_fd = -1;

void handle_sigint(int sig) {
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    exit(EXIT_SUCCESS);
}

void spi_init() {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        exit(EXIT_FAILURE);
    }

    struct spi_ioc_transfer spi;
    memset(&spi, 0, sizeof(spi));
    spi.speed_hz = SPI_MAX_SPEED_HZ;
    spi.bits_per_word = SPI_BITS_PER_WORD;
    spi.mode = SPI_MODE;

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &spi.mode) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &spi.bits_per_word) < 0) {
        perror("Failed to set SPI bits per word");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_SPEED_HZ, &spi.speed_hz) < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    // Set CS pin (GPIO8) as output
    if (ioctl(spi_fd, SPI_IOC_WR_CS_HIGH, &SPI_CS_PIN) < 0) {
        perror("Failed to set CS high");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_CS_LOW, &SPI_CS_PIN) < 0) {
        perror("Failed to set CS low");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }
}

void spi_transfer(unsigned char *tx, unsigned char *rx, size_t len) {
    struct spi_ioc_transfer spi;
    memset(&spi, 0, sizeof(spi));
    spi.tx_buf = (unsigned long)tx;
    spi.rx_buf = (unsigned long)rx;
    spi.len = len;
    spi.speed_hz = SPI_MAX_SPEED_HZ;
    spi.bits_per_word = SPI_BITS_PER_WORD;
    spi.delay_usecs = 0;
    spi.cs_change = 0;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &spi) < 0) {
        perror("SPI transfer failed");
        exit(EXIT_FAILURE);
    }
}

unsigned short read_adc() {
    unsigned char tx[3] = {0b01000000, 0x00, 0x00};
    unsigned char rx[3] = {0};

    // Set CS low
    if (ioctl(spi_fd, SPI_IOC_WR_CS_LOW, &SPI_CS_PIN) < 0) {
        perror("Failed to set CS low");
        exit(EXIT_FAILURE);
    }

    spi_transfer(tx, rx, sizeof(tx));

    // Set CS high
    if (ioctl(spi_fd, SPI_IOC_WR_CS_HIGH, &SPI_CS_PIN) < 0) {
        perror("Failed to set CS high");
        exit(EXIT_FAILURE);
    }

    // Extract 10-bit value from rx[1] and rx[2]
    unsigned short value = (rx[1] << 8) | rx[2];
    return value;
}

void print_adc_value(unsigned short value) {
    double voltage = (double)value * 3.3 / 1023.0;
    printf("ADC Value: %d, Voltage: %.3f V\n", value, voltage);
}

int main() {
    signal(SIGINT, handle_sigint);

    if (spi_init() < 0) {
        exit(EXIT_FAILURE);
    }

    while (1) {
        unsigned short value = read_adc();
        print_adc_value(value);
        usleep(500000); // 500 ms
    }

    return 0;
}

