#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define SPI_MODE SPI_MODE_0
#define CS_PIN 0
#define NUM_CHANNELS 3
#define CSV_FILE "sensor_data.csv"
#define INTERVAL 5

typedef struct {
    int fd;
    struct gpiod_line *cs_line;
} spi_context;

void handle_signal(int signum) {
    printf("Caught signal %d, cleaning up...\n", signum);
    exit(EXIT_FAILURE);
}

int init_spi(spi_context *ctx) {
    ctx->fd = open(SPI_DEVICE, O_RDWR | O_NOCTTY | O_SYNC);
    if (ctx->fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    struct spi_ioc_transfer spi;
    memset(&spi, 0, sizeof(spi));
    spi.speed_hz = SPI_SPEED;
    spi.mode = SPI_MODE;
    spi.bits_per_word = 8;

    if (ioctl(ctx->fd, SPI_IOC_WR_MODE, &spi.mode) < 0) {
        perror("Failed to set SPI mode");
        close(ctx->fd);
        return -1;
    }

    if (ioctl(ctx->fd, SPI_IOC_WR_SPEED_HZ, &spi.speed_hz) < 0) {
        perror("Failed to set SPI speed");
        close(ctx->fd);
        return -1;
    }

    if (ioctl(ctx->fd, SPI_IOC_WR_BITS_PER_WORD, &spi.bits_per_word) < 0) {
        perror("Failed to set SPI bits per word");
        close(ctx->fd);
        return -1;
    }

    ctx->cs_line = gpiod_line_get("gpiochip0", CS_PIN);
    if (!ctx->cs_line) {
        perror("Failed to get CS GPIO line");
        close(ctx->fd);
        return -1;
    }

    if (gpiod_line_request_output(ctx->cs_line, "spi_cs", 1) < 0) {
        perror("Failed to request CS GPIO line");
        gpiod_line_put(ctx->cs_line);
        close(ctx->fd);
        return -1;
    }

    return 0;
}

void release_spi(spi_context *ctx) {
    if (ctx->cs_line) {
        gpiod_line_put(ctx->cs_line);
    }
    if (ctx->fd >= 0) {
        close(ctx->fd);
    }
}

int read_adc(spi_context *ctx, int channel) {
    uint8_t tx[3];
    uint8_t rx[3];
    int ret;

    tx[0] = 1 << 7 | 6 << 4 | channel;
    tx[1] = 0;
    tx[2] = 0;

    gpiod_line_set_value(ctx->cs_line, 0);
    ret = ioctl(ctx->fd, SPI_IOC_MESSAGE(3), &tx);
    if (ret < 0) {
        perror("SPI transfer failed");
        return -1;
    }

    gpiod_line_set_value(ctx->cs_line, 1);

    uint16_t value = (rx[1] << 8) | rx[2];
    return value;
}

void write_csv_line(FILE *fp, int channel, int value) {
    double voltage = (double)value * 3.3 / 1023.0;
    fprintf(fp, "%d,%f\n", channel, voltage);
}

int main() {
    spi_context spi;
    FILE *fp;
    struct timespec ts;
    int channel;
    int value;

    if (init_spi(&spi) < 0) {
        fprintf(stderr, "SPI initialization failed\n");
        return EXIT_FAILURE;
    }

    fp = fopen(CSV_FILE, "a");
    if (!fp) {
        perror("Failed to open CSV file");
        release_spi(&spi);
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (1) {
        clock_gettime(CLOCK_REALTIME, &ts);
        time_t timestamp = ts.tv_sec;

        for (channel = 0; channel < NUM_CHANNELS; channel++) {
            value = read_adc(&spi, channel);
            if (value < 0) {
                fprintf(stderr, "ADC read failed for channel %d\n", channel);
                release_spi(&spi);
                fclose(fp);
                return EXIT_FAILURE;
            }
            write_csv_line(fp, channel, value);
        }

        fprintf(fp, "%ld,", timestamp);
        for (channel = 0; channel < NUM_CHANNELS; channel++) {
            value = read_adc(&spi, channel);
            if (value < 0) {
                fprintf(stderr, "ADC read failed for channel %d\n", channel);
                release_spi(&spi);
                fclose(fp);
                return EXIT_FAILURE;
            }
            write_csv_line(fp, channel, value);
        }

        fflush(fp);

        sleep(INTERVAL);
    }

    release_spi(&spi);
    fclose(fp);
    return EXIT_SUCCESS;
}

