#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define I2C_DEVICE "/dev/i2c-1"
#define BH1750_ADDR 0x23
#define ADC_CHANNEL 0
#define CSV_FILE "tamper_log.csv"
#define LOG_INTERVAL 5
#define I2C_DELAY_MS 180
#define MAX_LOG_LINES 1000

typedef enum {
    ERROR_NONE = 0,
    ERROR_I2C = 1,
    ERROR_ADC = 2,
    ERROR_FILE = 3
} error_code_t;

int spi_fd = -1;
int i2c_fd = -1;
FILE *csv_file = NULL;
volatile int running = 1;

void handle_signal(int sig) {
    running = 0;
}

void close_resources() {
    if (csv_file) {
        fclose(csv_file);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    printf("Resources released.\n");
}

void log_data(double sound_level, double light_level, error_code_t error_code) {
    char timestamp[30];
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(csv_file, "%s,%f,%f,%d\n", timestamp, sound_level, light_level, error_code);
    fflush(csv_file);
}

int init_spi() {
    spi_fd = open(SPI_DEVICE, O_RDWR | O_SYNC);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    struct spi_ioc_transfer spi;
    memset(&spi, 0, sizeof(spi));
    spi.speed_hz = 1000000;
    spi.bits_per_word = 8;
    spi.delay_usecs = 0;
    spi.tx_buf = NULL;
    spi.rx_buf = NULL;
    spi.len = 0;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &spi) < 0) {
        perror("Failed to set SPI parameters");
        close(spi_fd);
        return -1;
    }

    return 0;
}

int init_i2c() {
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return -1;
    }

    return 0;
}

int read_adc() {
    uint8_t tx[1] = {0x01}; // Start measurement command
    uint8_t rx[3] = {0};

    if (write(spi_fd, tx, 1) != 1) {
        perror("ADC write failed");
        return -1;
    }

    usleep(1000); // Wait for conversion

    if (read(spi_fd, rx, 3) != 3) {
        perror("ADC read failed");
        return -1;
    }

    // Extract 10-bit result
    uint16_t adc_value = (rx[1] << 8) | rx[0];
    double sound_level = (adc_value * 3.3) / 1024.0; // Convert to volts
    sound_level = 20 * log10(sound_level / 0.00002); // Convert to dB (approximate)

    return sound_level;
}

int read_bh1750() {
    uint8_t tx[1] = {0x20}; // Power on command
    if (write(i2c_fd, tx, 1) != 1) {
        perror("I2C write failed");
        return -1;
    }

    usleep(I2C_DELAY_MS * 1000);

    uint8_t rx[2] = {0};
    if (read(i2c_fd, rx, 2) != 2) {
        perror("I2C read failed");
        return -1;
    }

    uint16_t light_value = (rx[0] << 8) | rx[1];
    double light_level = light_value * 0.01; // Convert to lux

    return light_level;
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if (init_spi() < 0) {
        fprintf(stderr, "SPI initialization failed.\n");
        return 1;
    }

    if (init_i2c() < 0) {
        fprintf(stderr, "I2C initialization failed.\n");
        close(spi_fd);
        return 1;
    }

    csv_file = fopen(CSV_FILE, "a");
    if (!csv_file) {
        perror("Failed to open CSV file");
        close(spi_fd);
        close(i2c_fd);
        return 1;
    }

    fprintf(csv_file, "timestamp,sound_level_db,light_level_lux,error_code\n");
    fflush(csv_file);

    while (running) {
        double sound_level = 0.0;
        double light_level = 0.0;
        error_code_t error_code = ERROR_NONE;

        // Read sound level
        if (read_adc() < 0) {
            error_code = ERROR_ADC;
        } else {
            sound_level = read_adc();
        }

        // Read light level
        if (error_code == ERROR_NONE && read_bh1750() < 0) {
            error_code = ERROR_I2C;
        } else {
            light_level = read_bh1750();
        }

        log_data(sound_level, light_level, error_code);

        // Sleep for 5 seconds
        usleep(LOG_INTERVAL * 1000000);
    }

    close_resources();
    return 0;
}

