typedef enum {
    SUCCESS,
    ERROR_INIT,
    ERROR_SPI,
    ERROR_GPIO
} status_t;

static int spi_fd = -1;
static struct gpiod_line *pump_line = NULL;
static volatile int running = 1;

void signal_handler(int signum) {
    running = 0;
}

status_t init_spi() {
    spi_fd = open(SPI_DEVICE, O_RDWR | O_NOCTTY | O_NDELAY);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return ERROR_INIT;
    }

    struct spi_ioc_transfer spi;
    memset(&spi, 0, sizeof(spi));
    spi.speed_hz = SPI_SPEED;
    spi.mode = SPI_MODE;
    spi.bits_per_word = 8;

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &spi.mode) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        return ERROR_SPI;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_SPEED_HZ, &spi.speed_hz) < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        return ERROR_SPI;
    }

    return SUCCESS;
}

status_t init_gpio() {
    struct gpiod_chip *chip;
    chip = gpiod_chip_open("/dev/gpiochip1");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return ERROR_GPIO;
    }

    pump_line = gpiod_line_get(chip, PUMP_PIN);
    if (!pump_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return ERROR_GPIO;
    }

    if (gpiod_line_request_output(pump_line, "pump_control", 0) < 0) {
        perror("Failed to request GPIO line");
        gpiod_line_put(pump_line);
        gpiod_chip_close(chip);
        return ERROR_GPIO;
    }

    return SUCCESS;
}

int read_adc() {
    uint8_t tx[3] = {1, 0, 0};
    uint8_t rx[3] = {0};

    for (int i = 0; i < MAX_RETRIES; i++) {
        if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tx) < 0) {
            perror("SPI transfer failed");
            continue;
        }

        if (tx[0] != 1) {
            fprintf(stderr, "Invalid SPI response\n");
            continue;
        }

        rx[0] = tx[0];
        rx[1] = tx[1];
        rx[2] = tx[2];

        int adc_value = (rx[1] << 8) | rx[2];
        return adc_value;
    }

    return -1;
}

void log_reading(int adc_value) {
    double voltage = (adc_value * 3.3) / 1024.0;
    double percentage = (voltage / 3.3) * 100.0;

    printf("Timestamp: %ld, ADC Value: %d, Voltage: %.2f V, Moisture: %.2f%%\n",
           time(NULL), adc_value, voltage, percentage);
}

void control_pump(int adc_value) {
    double voltage = (adc_value * 3.3) / 1024.0;
    double percentage = (voltage / 3.3) * 100.0;

    if (percentage < MOISTURE_THRESHOLD) {
        gpiod_line_set_value(pump_line, 1);
        printf("Pump activated due to low moisture.\n");
    } else {
        gpiod_line_set_value(pump_line, 0);
        printf("Pump deactivated.\n");
    }
}

void cleanup() {
    if (pump_line) {
        gpiod_line_put(pump_line);
    }

    if (spi_fd >= 0) {
        close(spi_fd);
    }

    printf("Cleanup complete.\n");
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (init_spi() != SUCCESS) {
        fprintf(stderr, "SPI initialization failed.\n");
        return EXIT_FAILURE;
    }

    if (init_gpio() != SUCCESS) {
        fprintf(stderr, "GPIO initialization failed.\n");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    while (running) {
        int adc_value = read_adc();
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value.\n");
            sleep(1);
            continue;
        }

        log_reading(adc_value);
        control_pump(adc_value);
        sleep(LOG_INTERVAL);
    }

    cleanup();
    return EXIT_SUCCESS;
}

