#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>
#include <errno.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_SPEED 1000000
#define SPI_BITS 8
#define SPI_DELAY 0
#define ADC_CHANNEL 0
#define SAMPLE_INTERVAL 5
#define CO2_THRESHOLD 700
#define GPIO_FAN_PIN 18
#define LOG_FILE "air_quality.log"

volatile int running = 1;
int spi_fd = -1;
struct gpiod_line *fan_line = NULL;

void handle_signal(int sig) {
    running = 0;
    if (fan_line) {
        gpiod_line_set_value(fan_line, 0);
        gpiod_line_release(fan_line);
        fan_line = NULL;
    }
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
    printf("Signal received, shutting down...\n");
    exit(EXIT_SUCCESS);
}

int init_spi() {
    spi_fd = open(SPI_DEVICE, O_RDWR | O_NOCTTY | O_SYNC);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    struct spi_ioc_transfer spi;
    memset(&spi, 0, sizeof(spi));
    spi.speed_hz = SPI_SPEED;
    spi.bits_per_word = SPI_BITS;
    spi.delay_usecs = SPI_DELAY;
    spi.mode = SPI_MODE;

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        return -1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS) < 0) {
        perror("Failed to set SPI bits per word");
        close(spi_fd);
        return -1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        return -1;
    }

    return 0;
}

int read_adc(int channel) {
    uint8_t tx[3];
    uint8_t rx[3];
    uint16_t adc_value = 0;

    tx[0] = 1 << 7 | ((channel & 0x0F) << 4);
    tx[1] = 0;
    tx[2] = 0;

    struct spi_ioc_transfer spi;
    memset(&spi, 0, sizeof(spi));
    spi.tx_buf = (unsigned long)tx;
    spi.rx_buf = (unsigned long)rx;
    spi.len = 3;
    spi.speed_hz = SPI_SPEED;
    spi.bits_per_word = SPI_BITS;
    spi.delay_usecs = SPI_DELAY;
    spi.mode = SPI_MODE;

    int ret = ioctl(spi_fd, SPI_IOC_MESSAGE(1), &spi);
    if (ret < 0) {
        perror("SPI transfer failed");
        return -1;
    }

    adc_value = (rx[1] << 8) | rx[2];
    if (adc_value < 0 || adc_value > 1023) {
        fprintf(stderr, "Invalid ADC value: %d\n", adc_value);
        return -1;
    }

    return adc_value;
}

int estimate_co2(int adc_value) {
    // Simple linear approximation based on typical MQ-135 calibration
    // This is a placeholder; actual calibration may vary
    double voltage = (adc_value / 1023.0) * 3.3;
    double ppm = (voltage - 0.05) / 0.015; // Example formula
    return (int)ppm;
}

int init_gpio() {
    struct gpiod_chip *chip;
    chip = gpiod_chip_open("/dev/gpiochip4");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    fan_line = gpiod_line_get(chip, GPIO_FAN_PIN);
    if (!fan_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(fan_line, "fan_control", 0) < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_line_release(fan_line);
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

void log_data(double timestamp, int co2_ppm, int fan_state) {
    FILE *file = fopen(LOG_FILE, "a");
    if (!file) {
        perror("Failed to open log file");
        return;
    }

    fprintf(file, "%.6f,%d,%d\n", timestamp, co2_ppm, fan_state);
    fclose(file);
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if (init_spi() < 0) {
        fprintf(stderr, "SPI initialization failed\n");
        return EXIT_FAILURE;
    }

    if (init_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed\n");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    while (running) {
        int adc_value = -1;
        int retries = 3;
        while (retries-- > 0) {
            adc_value = read_adc(ADC_CHANNEL);
            if (adc_value >= 0) {
                break;
            }
            usleep(100000); // 100ms retry delay
        }

        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC after retries\n");
            usleep(500000); // 500ms delay before next attempt
            continue;
        }

        int co2_ppm = estimate_co2(adc_value);
        int fan_state = 0;

        if (co2_ppm > CO2_THRESHOLD) {
            fan_state = 1;
            gpiod_line_set_value(fan_line, 1);
        } else {
            gpiod_line_set_value(fan_line, 0);
        }

        time_t now;
        time(&now);
        log_data(now, co2_ppm, fan_state);

        usleep(SAMPLE_INTERVAL * 1000000); // 5 seconds
    }

    if (fan_line) {
        gpiod_line_set_value(fan_line, 0);
        gpiod_line_release(fan_line);
    }

    if (spi_fd >= 0) {
        close(spi_fd);
    }

    return EXIT_SUCCESS;
}

