#define CE_PIN 8
#define VALVE_PIN 17
#define PWM_FREQ 100
#define LOG_INTERVAL 5
#define LOG_FILE "irrigation.log"

typedef struct {
    int spi_fd;
    struct gpiod_line *valve_line;
    FILE *log_file;
    int running;
} app_state;

void handle_signal(int sig) {
    app_state *state = (app_state *)malloc(sizeof(app_state));
    if (state == NULL) {
        fprintf(stderr, "Failed to allocate memory for app_state\n");
        exit(EXIT_FAILURE);
    }

    state->running = 0;

    // Set valve to 0
    if (state->valve_line) {
        gpiod_line_set_value(state->valve_line, 0);
    }

    // Close SPI
    if (state->spi_fd >= 0) {
        close(state->spi_fd);
    }

    // Close log file
    if (state->log_file) {
        fclose(state->log_file);
    }

    // Terminate gpiod
    gpiod_exit();

    free(state);
    exit(EXIT_SUCCESS);
}

int init_spi() {
    int spi_fd = open(SPI_DEVICE, O_RDWR | O_NOCTTY | O_CLOEXEC);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    struct spi_ioc_transfer spi;
    memset(&spi, 0, sizeof(spi));
    spi.speed_hz = SPI_SPEED;
    spi.mode = SPI_MODE;
    spi.bits_per_word = 8;

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &spi.mode) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        return -1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_SPEED_HZ, &spi.speed_hz) < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        return -1;
    }

    return spi_fd;
}

int init_gpio() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    line = gpiod_line_get(chip, VALVE_PIN);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(line, "valve", GPIOD_LINE_REQUEST_OUTPUT | GPIOD_LINE_REQUEST_FLAG_ACTIVE_LOW)) {
        perror("Failed to request GPIO line");
        gpiod_line_put(line);
        gpiod_chip_close(chip);
        return -1;
    }

    gpiod_line_set_value(line, 0);

    return line;
}

void log_data(FILE *log_file, time_t timestamp, int adc1, int adc2, int adc3, int average, int duty_cycle) {
    char buffer[256];
    struct tm *tm_info = localtime(&timestamp);
    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(log_file, "%s, %d, %d, %d, %d, %d\n", buffer, adc1, adc2, adc3, average, duty_cycle);
    fflush(log_file);
}

int read_adc(int spi_fd) {
    uint8_t tx[1] = {0x01};
    uint8_t rx[2] = {0};

    struct spi_ioc_transfer spi;
    memset(&spi, 0, sizeof(spi));
    spi.tx_buf = (unsigned long)tx;
    spi.rx_buf = (unsigned long)rx;
    spi.len = 1;
    spi.speed_hz = SPI_SPEED;
    spi.mode = SPI_MODE;
    spi.bits_per_word = 8;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &spi) < 0) {
        perror("SPI transfer failed");
        return -1;
    }

    int adc_value = (rx[0] << 8) | rx[1];
    return adc_value;
}

void set_pwm(int duty_cycle) {
    if (duty_cycle < 0 || duty_cycle > 100) {
        fprintf(stderr, "Invalid duty cycle: %d\n", duty_cycle);
        return;
    }

    int period = 1000000 / PWM_FREQ;
    int pulse_width = (duty_cycle * period) / 100;

    // For simplicity, we use a software PWM approach here
    // In a real application, use a hardware PWM library or timer
    while (1) {
        usleep(pulse_width);
        gpiod_line_set_value(state.valve_line, 1);
        usleep(period - pulse_width);
        gpiod_line_set_value(state.valve_line, 0);
        usleep(1000000 / PWM_FREQ - period);
    }
}

int main() {
    app_state state = {0};

    // Initialize signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Initialize GPIO
    state.valve_line = init_gpio();
    if (!state.valve_line) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        exit(EXIT_FAILURE);
    }

    // Initialize SPI
    state.spi_fd = init_spi();
    if (state.spi_fd < 0) {
        fprintf(stderr, "Failed to initialize SPI\n");
        exit(EXIT_FAILURE);
    }

    // Open log file
    state.log_file = fopen(LOG_FILE, "a");
    if (!state.log_file) {
        perror("Failed to open log file");
        close(state.spi_fd);
        gpiod_line_put(state.valve_line);
        gpiod_chip_close(gpiod_chip_get(chip));
        exit(EXIT_FAILURE);
    }

    state.running = 1;

    while (state.running) {
        int adc1 = -1, adc2 = -1, adc3 = -1;
        int count = 0;

        while (count < 3) {
            int value = read_adc(state.spi_fd);
            if (value >= 0) {
                if (count == 0) {
                    adc1 = value;
                } else if (count == 1) {
                    adc2 = value;
                } else {
                    adc3 = value;
                }
                count++;
            }
            usleep(100000); // 100ms delay between samples
        }

        int average = (adc1 + adc2 + adc3) / 3;

        // Map ADC value to duty cycle (assuming 0-1023 range)
        int duty_cycle = (average * 100) / 1023;

        // Log data
        time_t timestamp = time(NULL);
        log_data(state.log_file, timestamp, adc1, adc2, adc3, average, duty_cycle);

        // Set valve position
        set_pwm(duty_cycle);

        // Sleep for 5 seconds
        usleep(LOG_INTERVAL * 1000000);
    }

    // Cleanup
    handle_signal(0);

    return 0;
}

