#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define SPI_MODE SPI_MODE_0
#define CE_PIN 8
#define MAX_RETRIES 5
#define RETRY_DELAY_MS 100
#define CHANNEL 0
#define FILE_NAME "soil_data.txt"

typedef enum {
    SUCCESS,
    SPI_FAILURE,
    FILE_WRITE_FAILURE
} Result;

typedef struct {
    int fd;
    struct gpiod_line *ce_line;
} SpiContext;

void handle_signal(int signum) {
    printf("Caught signal %d, shutting down...\n", signum);
    exit(EXIT_SUCCESS);
}

Result init_spi(SpiContext *ctx) {
    int fd;
    struct gpiod_line *ce_line;

    // Open SPI device
    fd = open(SPI_DEVICE, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd < 0) {
        perror("Failed to open SPI device");
        return SPI_FAILURE;
    }

    // Set SPI mode
    if (ioctl(fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("Failed to set SPI mode");
        close(fd);
        return SPI_FAILURE;
    }

    // Set SPI speed
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("Failed to set SPI speed");
        close(fd);
        return SPI_FAILURE;
    }

    // Initialize CE pin using libgpiod
    const char *chip_name = "gpiochip0";
    struct gpiod_chip *chip;
    chip = gpiod_chip_open(chip_name);
    if (!chip) {
        perror("Failed to open GPIO chip");
        close(fd);
        return SPI_FAILURE;
    }

    ce_line = gpiod_line_get(chip, CE_PIN);
    if (!ce_line) {
        perror("Failed to get CE line");
        gpiod_chip_close(chip);
        close(fd);
        return SPI_FAILURE;
    }

    if (gpiod_line_request_output(ce_line, "CE", 1) < 0) {
        perror("Failed to request CE line");
        gpiod_line_put(ce_line);
        gpiod_chip_close(chip);
        close(fd);
        return SPI_FAILURE;
    }

    ctx->fd = fd;
    ctx->ce_line = ce_line;
    return SUCCESS;
}

void deinit_spi(SpiContext *ctx) {
    if (ctx->ce_line) {
        gpiod_line_put(ctx->ce_line);
    }
    if (ctx->fd >= 0) {
        close(ctx->fd);
    }
}

Result read_adc(SpiContext *ctx, uint16_t *value) {
    uint8_t tx[3];
    uint8_t rx[3];
    int ret;
    int retry = 0;

    // Prepare command byte
    tx[0] = 0b10000000 | (1 << 6) | (CHANNEL & 0x0F); // Start bit, single-ended, channel 0
    tx[1] = 0;
    tx[2] = 0;

    while (retry < MAX_RETRIES) {
        // Set CE low
        gpiod_line_set_value(ctx->ce_line, 0);

        // Transfer data
        ret = ioctl(ctx->fd, SPI_IOC_MESSAGE(3), tx);
        if (ret < 0) {
            perror("SPI transfer failed");
            usleep(RETRY_DELAY_MS * 1000);
            retry++;
            continue;
        }

        // Set CE high
        gpiod_line_set_value(ctx->ce_line, 1);

        // Extract ADC value
        *value = (rx[1] << 8) | rx[2];

        if (*value >= 0 && *value <= 1023) {
            return SUCCESS;
        }

        usleep(RETRY_DELAY_MS * 1000);
        retry++;
    }

    return SPI_FAILURE;
}

Result log_soil_data(FILE *file, uint16_t adc_value) {
    time_t now;
    struct tm *timeinfo;
    char timestamp[20];

    time(&now);
    timeinfo = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(file, "%s, %d\n", timestamp, adc_value);
    return SUCCESS;
}

int main() {
    SpiContext spi;
    FILE *file;
    uint16_t adc_value;
    Result result;
    int retry_count = 0;
    struct sigaction sa;

    // Set up signal handling
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("Failed to set up signal handler");
        return EXIT_FAILURE;
    }

    // Initialize SPI
    if (init_spi(&spi) != SUCCESS) {
        fprintf(stderr, "Failed to initialize SPI\n");
        return EXIT_FAILURE;
    }

    // Open log file
    file = fopen(FILE_NAME, "a");
    if (!file) {
        perror("Failed to open log file");
        deinit_spi(&spi);
        return EXIT_FAILURE;
    }

    while (1) {
        result = read_adc(&spi, &adc_value);
        if (result == SUCCESS) {
            if (log_soil_data(file, adc_value) != SUCCESS) {
                fprintf(stderr, "Failed to write to log file\n");
            }
        } else {
            fprintf(stderr, "SPI communication failed, retrying...\n");
            // Log error
            time_t now;
            struct tm *timeinfo;
            char timestamp[20];
            time(&now);
            timeinfo = localtime(&now);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
            fprintf(file, "%s, SPI communication failed\n", timestamp);
        }

        // Sleep for 5 seconds
        usleep(5000000);

        // Check for signal
        if (signal_pending()) {
            break;
        }
    }

    fclose(file);
    deinit_spi(&spi);
    return EXIT_SUCCESS;
}

