#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define SPI_MODE SPI_MODE_0
#define SPI_BITS 8
#define SPI_DELAY 1000000  // 1 second in microseconds
#define MAX_RETRIES 3
#define AQI_THRESHOLD 100
#define LOG_FILE "air_quality.log"
#define GPIO_FAN_PIN 18  // BCM pin 18

typedef struct {
    int spi_fd;
    struct gpiod_line *fan_line;
    FILE *log_file;
    int running;
} app_state;

void handle_signal(int sig) {
    app_state *state = (app_state *)malloc(sizeof(app_state));
    if (state) {
        state->running = 0;
    }
    if (sig == SIGINT || sig == SIGTERM) {
        printf("Shutting down gracefully...\n");
        if (state->log_file) {
            fclose(state->log_file);
        }
        if (state->fan_line) {
            gpiod_line_set_value(state->fan_line, 0);
            gpiod_line_release(state->fan_line);
        }
        if (state->spi_fd >= 0) {
            close(state->spi_fd);
        }
        free(state);
    }
    exit(EXIT_SUCCESS);
}

int init_spi() {
    int spi_fd = open(SPI_DEVICE, O_RDWR | O_NOCTTY | O_SYNC);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    struct spi_ioc_transfer spi;
    memset(&spi, 0, sizeof(spi));
    spi.speed_hz = SPI_SPEED;
    spi.mode = SPI_MODE;
    spi.bits_per_word = SPI_BITS;

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &spi.mode) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        return -1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &spi.bits_per_word) < 0) {
        perror("Failed to set SPI bits per word");
        close(spi_fd);
        return -1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_SPEED_HZ, &spi.speed_hz) < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        return -1;
    }

    return spi_fd;
}

int read_adc(int spi_fd, int channel) {
    unsigned char tx[1];
    unsigned char rx[1];
    tx[0] = 1 << 7 | ((channel & 0x0F) << 4);
    int ret;

    for (int retry = 0; retry < MAX_RETRIES; retry++) {
        ret = ioctl(spi_fd, SPI_IOC_MESSAGE(1), &spi);
        if (ret < 0) {
            perror("SPI transfer failed");
            usleep(SPI_DELAY);
            continue;
        }
        rx[0] = rx[0] & 0x03;  // Mask to get the 2 least significant bits
        return (rx[0] << 8) | 0xFF;  // Convert to 10-bit value
    }

    perror("Failed to read ADC after retries");
    return -1;
}

int init_gpio() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;

    chip = gpiod_chip_open("/dev/gpiochip4");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    line = gpiod_line_get(chip, GPIO_FAN_PIN);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(line, "fan_control", 0) < 0) {
        perror("Failed to request GPIO line");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return -1;
    }

    return line;
}

void log_aqi(long timestamp, int aqi) {
    if (!app_state.log_file) {
        app_state.log_file = fopen(LOG_FILE, "a");
        if (!app_state.log_file) {
            perror("Failed to open log file");
            return;
        }
    }

    fprintf(app_state.log_file, "%ld,%d\n", timestamp, aqi);
    fflush(app_state.log_file);
}

int compute_aqi(int adc_value) {
    // Simple AQI approximation based on ADC value (0-1023)
    // This is a placeholder; actual AQI calculation requires more detailed calibration
    int aqi = (adc_value * 100) / 1023;
    return aqi;
}

void run_app() {
    int spi_fd = init_spi();
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to initialize SPI\n");
        return;
    }

    struct gpiod_line *fan_line = init_gpio();
    if (!fan_line) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        close(spi_fd);
        return;
    }

    app_state.running = 1;
    app_state.spi_fd = spi_fd;
    app_state.fan_line = fan_line;
    app_state.log_file = NULL;

    while (app_state.running) {
        int adc_value = read_adc(spi_fd, 0);
        if (adc_value < 0) {
            fprintf(stderr, "ADC read failed, retrying...\n");
            usleep(SPI_DELAY);
            continue;
        }

        int aqi = compute_aqi(adc_value);
        log_aqi(time(NULL), aqi);

        if (aqi > AQI_THRESHOLD) {
            gpiod_line_set_value(fan_line, 1);
        } else {
            gpiod_line_set_value(fan_line, 0);
        }

        usleep(5000000);  // 5 seconds
    }
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    app_state state;
    state.running = 1;

    run_app();

    if (state.log_file) {
        fclose(state.log_file);
    }
    if (state.fan_line) {
        gpiod_line_release(state.fan_line);
    }
    if (state.spi_fd >= 0) {
        close(state.spi_fd);
    }

    return 0;
}

