#define LOG_FILE "alcohol_log.txt"

volatile int running = 1;

void handle_signal(int sig) {
    running = 0;
}

void log_error(const char *message, int errnum) {
    fprintf(stderr, "Error: %s: %s\n", message, strerror(errnum));
}

void log_measurement(const char *timestamp, double voltage, const char *classification) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        log_error("Failed to open log file", errno);
