int spi_transfer(int fd, unsigned char *tx, unsigned char *rx, size_t len) {
    struct spi_ioc_transfer tr = {
        .tx_nbytes = len,
        .rx_nbytes = len,
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .delay_usecs = 0,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS
    };

    int ret = ioctl(fd, SPI_IOC_MESSAGE(1), &tr);
    if (ret < 1) {
        log_error("SPI transfer failed", errno);
        return -1;
    }
    return 0;
}

int read_adc(int fd, int channel) {
    unsigned char tx[3] = {1, (unsigned char)(channel << 4 | 0x01), 0};
    unsigned char rx[3] = {0};

    for (int i = 0; i < MAX_RETRIES; i++) {
        if (spi_transfer(fd, tx, rx, 3) == 0) {
            unsigned int adc_value = (rx[1] << 8) | rx[2];
            return adc_value;
        }
        usleep(RETRY_DELAY_MS * 1000);
    }

    log_error("ADC read failed after retries", 0);
    return -1;
}

double adc_to_voltage(int adc_value) {
    return (double)adc_value * ADC_REF_VOLTAGE / ADC_RESOLUTION;
}

void classify_alcohol(double voltage) {
    if (voltage > VOLTAGE_THRESHOLD_HIGH) {
        printf("Alcohol detected! Limit exceeded.\n");
    } else if (voltage < VOLTAGE_THRESHOLD_LOW) {
        printf("Sobriety confirmed.\n");
    } else {
        printf("Alcohol level within acceptable range.\n");
    }
}

void generate_timestamp(char *timestamp, size_t size) {
    struct timeval tv;
    gettimeofday(&tv, NULL);
    struct tm *tm = gmtime(&tv.tv_sec);
    strftime(timestamp, size, "%Y-%m-%dT%H:%M:%S", tm);
}

