    signal(SIGTERM, handle_signal);

    // Open SPI device
    spi_fd = open(SPI_DEVICE, O_RDWR | O_NOCTTY | O_SYNC);
    if (spi_fd < 0) {
        log_error("Failed to open SPI device", errno);
        return 1;
    }

    // Set SPI mode
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        log_error("Failed to set SPI mode", errno);
        close(spi_fd);
        return 1;
    }

    // Set SPI bits per word
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS) < 0) {
        log_error("Failed to set SPI bits per word", errno);
        close(spi_fd);
        return 1;
    }

    // Set SPI speed
    if (ioctl(spi_fd, SPI_IOC_WR_SPEED_HZ, &SPI_SPEED) < 0) {
        log_error("Failed to set SPI speed", errno);
        close(spi_fd);
        return 1;
    }

