    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        log_error("Failed to open log file", errno);
        close(spi_fd);
        return 1;
    }

    // Main loop
    while (running) {
        // Read ADC
        int retries = 0;
        int read_success = 0;
