#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_SPEED 1000000
#define SPI_BITS 8
#define SPI_DELAY 0
#define CHANNEL 0
#define GPIO_RELAY 18
#define GPIO_RELAY_ACTIVE_HIGH 1
#define LOG_FILE "irrigation.log"
#define SAMPLE_INTERVAL 60
#define MOISTURE_THRESHOLD 300

typedef struct {
    int spi_fd;
    struct gpiod_line *relay_line;
    FILE *log_file;
    int running;
} app_state;

void handle_signal(int sig) {
    app_state *state = (app_state *)malloc(sizeof(app_state));
    if (state) {
        state->running = 0;
        free(state);
    }
}

int init_spi() {
    int spi_fd = open(SPI_DEVICE, O_RDWR | O_NOCTTY | O_NDELAY);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    struct spi_ioc_transfer spi;
    memset(&spi, 0, sizeof(spi));
    spi.speed_hz = SPI_SPEED;
    spi.bits_per_word = SPI_BITS;
    spi.delay_usecs = SPI_DELAY;
    spi.mode = SPI_MODE;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &spi) < 0) {
        perror("Failed to set SPI parameters");
        close(spi_fd);
        return -1;
    }

    return spi_fd;
}

int init_gpio() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;

    chip = gpiod_chip_open("/dev/gpiochip4");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    line = gpiod_line_get(chip, GPIO_RELAY);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(line, "Relay", GPIO_RELAY_ACTIVE_HIGH)) {
        perror("Failed to request GPIO line");
        gpiod_line_put(line);
        gpiod_chip_close(chip);
        return -1;
    }

    return line;
}

void log_data(int moisture, int pump_status, time_t timestamp) {
    char buffer[256];
    struct tm *tm_info = localtime(&timestamp);
    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", tm_info);
    fprintf(log_file, "%s, Moisture: %d, Pump: %s\n", buffer, moisture, pump_status ? "ON" : "OFF");
    fflush(log_file);
}

void read_soil_moisture(int spi_fd, int *moisture) {
    uint8_t tx[1];
    uint8_t rx[1];
    tx[0] = 1 << 7 | (CHANNEL << 4);
    if (write(spi_fd, tx, 1) != 1) {
        perror("SPI write failed");
        return;
    }

    if (read(spi_fd, rx, 1) != 1) {
        perror("SPI read failed");
        return;
    }

    *moisture = (rx[0] & 0x0F) << 8;
    *moisture |= (rx[0] >> 4) & 0x0F;
}

void turn_relay_on() {
    if (gpiod_line_set_value(relay_line, 1) < 0) {
        perror("Failed to turn relay on");
    }
}

void turn_relay_off() {
    if (gpiod_line_set_value(relay_line, 0) < 0) {
        perror("Failed to turn relay off");
    }
}

void cleanup(app_state *state) {
    if (state->log_file) {
        fclose(state->log_file);
    }
    if (state->spi_fd >= 0) {
        close(state->spi_fd);
    }
    if (state->relay_line) {
        gpiod_line_put(state->relay_line);
        gpiod_chip_close(gpiod_line_get_chip(state->relay_line));
    }
    free(state);
}

int main() {
    app_state *state = (app_state *)malloc(sizeof(app_state));
    if (!state) {
        perror("Failed to allocate memory");
        return 1;
    }

    state->running = 1;

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    state->spi_fd = init_spi();
    if (state->spi_fd < 0) {
        cleanup(state);
        return 1;
    }

    state->relay_line = init_gpio();
    if (!state->relay_line) {
        cleanup(state);
        return 1;
    }

    state->log_file = fopen(LOG_FILE, "a");
    if (!state->log_file) {
        perror("Failed to open log file");
        cleanup(state);
        return 1;
    }

    time_t last_sample = time(NULL);
    int moisture = 0;
    int pump_status = 0;

    while (state->running) {
        time_t current_time = time(NULL);
        if (current_time - last_sample >= SAMPLE_INTERVAL) {
            last_sample = current_time;

            if (read_soil_moisture(state->spi_fd, &moisture) < 0) {
                fprintf(stderr, "Error reading soil moisture, continuing...\n");
                continue;
            }

            if (moisture < MOISTURE_THRESHOLD) {
                if (!pump_status) {
                    turn_relay_on();
                    pump_status = 1;
                }
            } else {
                if (pump_status) {
                    turn_relay_off();
                    pump_status = 0;
                }
            }

            log_data(moisture, pump_status, current_time);
        }

        usleep(100000); // 100ms delay to prevent CPU overuse
    }

    cleanup(state);
    return 0;
}

