#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define SPI_MODE SPI_MODE_0
#define CS_PIN 8
#define MOSI_PIN 10
#define MISO_PIN 9
#define SCLK_PIN 11
#define LED_PIN 17
#define CALIBRATION_TIME 5
#define DEBOUNCE_DELAY 10

typedef struct {
    int spi_fd;
    struct gpiod_line *cs_line;
    struct gpiod_line *led_line;
    int baseline;
    int threshold;
    int last_state;
    int debounce_count;
} app_state;

void cleanup_app(app_state *state) {
    if (state->cs_line) {
        gpiod_line_release(state->cs_line);
    }
    if (state->led_line) {
        gpiod_line_release(state->led_line);
    }
    if (state->spi_fd >= 0) {
        close(state->spi_fd);
    }
    printf("Cleanup complete.\n");
}

void handle_sigint(int sig) {
    cleanup_app(NULL);
    exit(EXIT_SUCCESS);
}

int init_gpio(app_state *state) {
    int ret;

    state->cs_line = gpiod_line_get("gpio8", "cs");
    if (!state->cs_line) {
        fprintf(stderr, "Failed to get CS GPIO line\n");
        return -1;
    }

    state->led_line = gpiod_line_get("gpio17", "led");
    if (!state->led_line) {
        fprintf(stderr, "Failed to get LED GPIO line\n");
        cleanup_app(state);
        return -1;
    }

    ret = gpiod_line_request_output(state->cs_line, "cs", 1);
    if (ret < 0) {
        fprintf(stderr, "Failed to request CS GPIO line as output\n");
        cleanup_app(state);
        return -1;
    }

    ret = gpiod_line_request_output(state->led_line, "led", 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request LED GPIO line as output\n");
        cleanup_app(state);
        return -1;
    }

    return 0;
}

int init_spi(app_state *state) {
    state->spi_fd = open(SPI_DEVICE, O_RDWR);
    if (state->spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device\n");
        return -1;
    }

    struct spi_ioc_transfer spi;
    memset(&spi, 0, sizeof(spi));
    spi.speed_hz = SPI_SPEED;
    spi.mode = SPI_MODE;
    spi.bits_per_word = 8;

    if (ioctl(state->spi_fd, SPI_IOC_MESSAGE(1), &spi) < 0) {
        fprintf(stderr, "Failed to set SPI parameters\n");
        close(state->spi_fd);
        return -1;
    }

    return 0;
}

int read_adc(app_state *state) {
    uint8_t tx[2] = {0x01, 0x80};
    uint8_t rx[2] = {0};

    gpiod_line_set_value(state->cs_line, 0);
    int ret = ioctl(state->spi_fd, SPI_IOC_MESSAGE(1), &tx);
    if (ret < 0) {
        fprintf(stderr, "SPI write failed\n");
        return -1;
    }

    ret = ioctl(state->spi_fd, SPI_IOC_MESSAGE(1), &rx);
    if (ret < 0) {
        fprintf(stderr, "SPI read failed\n");
        return -1;
    }

    gpiod_line_set_value(state->cs_line, 1);

    uint16_t value = (rx[0] << 8) | rx[1];
    return value;
}

void calibrate_baseline(app_state *state) {
    int sum = 0;
    int samples = 0;

    printf("Calibrating baseline for %d seconds...\n", CALIBRATION_TIME);

    for (int i = 0; i < CALIBRATION_TIME * 100; i++) {
        int value = read_adc(state);
        sum += value;
        samples++;
        usleep(10000);
    }

    state->baseline = sum / samples;
    state->threshold = state->baseline + 50; // Adjust threshold based on baseline
    printf("Calibrated baseline: %d, Threshold: %d\n", state->baseline, state->threshold);
}

void process_sample(app_state *state, int value) {
    if (value > state->threshold) {
        if (state->last_state == 0) {
            state->debounce_count = 0;
            gpiod_line_set_value(state->led_line, 1);
            state->last_state = 1;
        } else {
            state->debounce_count++;
            if (state->debounce_count > 100) {
                gpiod_line_set_value(state->led_line, 1);
                state->debounce_count = 0;
            }
        }
    } else {
        if (state->last_state == 1) {
            state->debounce_count = 0;
            gpiod_line_set_value(state->led_line, 0);
            state->last_state = 0;
        } else {
            state->debounce_count++;
            if (state->debounce_count > 100) {
                gpiod_line_set_value(state->led_line, 0);
                state->debounce_count = 0;
            }
        }
    }
}

int main() {
    app_state state = {0};

    signal(SIGINT, handle_sigint);

    if (init_gpio(&state) < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return EXIT_FAILURE;
    }

    if (init_spi(&state) < 0) {
        fprintf(stderr, "Failed to initialize SPI\n");
        cleanup_app(&state);
        return EXIT_FAILURE;
    }

    calibrate_baseline(&state);

    printf("Starting continuous monitoring...\n");

    while (1) {
        int value = read_adc(&state);
        process_sample(&state, value);
        usleep(10000);
    }

    cleanup_app(&state);
    return EXIT_SUCCESS;
}

