            state->last_state = 1;
        } else {
            state->debounce_count++;
            if (state->debounce_count > 100) {
                gpiod_line_set_value(state->led_line, 1);
                state->debounce_count = 0;
            }
        }
    } else {
        if (state->last_state == 1) {
            state->debounce_count = 0;
            gpiod_line_set_value(state->led_line, 0);
            state->last_state = 0;
        } else {
            state->debounce_count++;
            if (state->debounce_count > 100) {
                gpiod_line_set_value(state->led_line, 0);
                state->debounce_count = 0;
            }
        }
    }
}

int main() {
    app_state state = {0};

    signal(SIGINT, handle_sigint);

    if (init_gpio(&state) < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return EXIT_FAILURE;
    }

    if (init_spi(&state) < 0) {
        fprintf(stderr, "Failed to initialize SPI\n");
        cleanup_app(&state);
        return EXIT_FAILURE;
    }

    calibrate_baseline(&state);

    printf("Starting continuous monitoring...\n");

    while (1) {
        int value = read_adc(&state);
        process_sample(&state, value);
        usleep(10000);
    }

    cleanup_app(&state);
    return EXIT_SUCCESS;
}
