#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define SPI_MODE SPI_MODE_0
#define SPI_BITS 8
#define SPI_DELAY_MS 100
#define LOG_FILE "gas_log.txt"
#define RETRY_COUNT 5
#define POLLING_INTERVAL_MS 1000

typedef struct {
    int spi_fd;
    int retry_count;
    int running;
} AppContext;

void handle_sigint(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    AppContext *ctx = (AppContext *)malloc(sizeof(AppContext));
    ctx->running = 0;
    free(ctx);
    exit(EXIT_SUCCESS);
}

void init_spi(AppContext *ctx) {
    ctx->spi_fd = open(SPI_DEVICE, O_RDWR | O_NOCTTY | O_NDELAY);
    if (ctx->spi_fd < 0) {
        perror("Failed to open SPI device");
        exit(EXIT_FAILURE);
    }

    struct spi_ioc_transfer spi;
    memset(&spi, 0, sizeof(spi));
    spi.speed_hz = SPI_SPEED;
    spi.mode = SPI_MODE;
    spi.bits_per_word = SPI_BITS;

    if (ioctl(ctx->spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("Failed to set SPI mode");
        close(ctx->spi_fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(ctx->spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS) < 0) {
        perror("Failed to set SPI bits per word");
        close(ctx->spi_fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(ctx->spi_fd, SPI_IOC_WR_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("Failed to set SPI speed");
        close(ctx->spi_fd);
        exit(EXIT_FAILURE);
    }
}

void close_spi(AppContext *ctx) {
    if (ctx->spi_fd >= 0) {
        close(ctx->spi_fd);
    }
}

uint16_t read_adc(AppContext *ctx) {
    uint8_t tx[1] = {0x01};
    uint8_t rx[3] = {0};

    for (int i = 0; i < RETRY_COUNT; i++) {
        if (ioctl(ctx->spi_fd, SPI_IOC_MESSAGE(1), &spi) < 0) {
            perror("SPI transfer failed");
            usleep(SPI_DELAY_MS * 1000);
            continue;
        }

        uint16_t adc_value = (rx[1] << 8) | rx[2];
        if (adc_value > 1023) {
            fprintf(stderr, "Invalid ADC value: %d\n", adc_value);
            usleep(SPI_DELAY_MS * 1000);
            continue;
        }

        return adc_value;
    }

    fprintf(stderr, "ADC read failed after %d retries\n", RETRY_COUNT);
    return 0;
}

void log_data(uint16_t adc_value) {
    FILE *file = fopen(LOG_FILE, "a");
    if (!file) {
        perror("Failed to open log file");
        return;
    }

    time_t now = time(NULL);
    struct tm *tm_now = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_now);

    double voltage = (adc_value * 3.3) / 1024.0;
    double ppm = (voltage - 0.1) * 1000.0; // Placeholder PPM calculation

    fprintf(file, "%s, %.3f V, %.1f PPM\n", timestamp, voltage, ppm);
    fclose(file);
}

void run_sensor(AppContext *ctx) {
    while (ctx->running) {
        uint16_t adc_value = read_adc(ctx);
        if (adc_value == 0) {
            usleep(100000); // 100 ms delay
            continue;
        }

        printf("Voltage: %.3f V, PPM: %.1f\n", (adc_value * 3.3) / 1024.0, (adc_value - 0.1) * 1000.0);
        log_data(adc_value);
        usleep(POLLING_INTERVAL_MS * 1000);
    }
}

int main() {
    AppContext ctx = {0};

    signal(SIGINT, handle_sigint);

    init_spi(&ctx);
    ctx.running = 1;

    run_sensor(&ctx);

    close_spi(&ctx);

    return 0;
}

