#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 500000
#define SPI_MODE SPI_MODE_0
#define SPI_BITS 8
#define SPI_DELAY 0

#define GPIO_PIN 17
#define GPIO_ACTIVE_HIGH 1
#define MOISTURE_THRESHOLD 30
#define LOG_FILE "watering.log"
#define LOG_INTERVAL 60

typedef enum {
    PUMP_OFF,
    PUMP_ON
} PumpState;

volatile PumpState current_pump_state = PUMP_OFF;
volatile int running = 1;

int spi_fd = -1;
struct gpiod_line *gpio_line = NULL;

void log_message(const char *message) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("fopen");
        return;
    }

    time_t now;
    struct tm *time_info;
    char timestamp[64];

    time(&now);
    time_info = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", time_info);

    fprintf(log_file, "[%s] %s\n", timestamp, message);
    fclose(log_file);
}

void handle_signal(int signal) {
    running = 0;
    log_message("Received signal to terminate. Turning off pump...");
    if (gpio_line && gpiod_line_get_value(gpio_line) == GPIO_ACTIVE_HIGH) {
        gpiod_line_set_value(gpio_line, 0);
        log_message("Pump turned off.");
    }
    log_message("Program terminating.");
    exit(EXIT_SUCCESS);
}

int init_spi() {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        log_message("Failed to open SPI device.");
        return -1;
    }

    struct spi_ioc_transfer spi;
    memset(&spi, 0, sizeof(spi));
    spi.speed_hz = SPI_SPEED;
    spi.mode = SPI_MODE;
    spi.bits_per_word = SPI_BITS;
    spi.delay_usecs = SPI_DELAY;

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        log_message("Failed to set SPI mode.");
        close(spi_fd);
        return -1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_SPEED_HZ, &SPI_SPEED) < 0) {
        log_message("Failed to set SPI speed.");
        close(spi_fd);
        return -1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS) < 0) {
        log_message("Failed to set SPI bits per word.");
        close(spi_fd);
        return -1;
    }

    return 0;
}

int init_gpio() {
    struct gpiod_chip *chip;
    chip = gpiod_chip_open("/dev/gpiochip4");
    if (!chip) {
        log_message("Failed to open GPIO chip.");
        return -1;
    }

    gpio_line = gpiod_line_request(chip, "gpio17", "pump", GPIOD_LINE_DIRECTION_OUTPUT, 0);
    if (!gpio_line) {
        log_message("Failed to request GPIO line.");
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_set_value(gpio_line, 0) < 0) {
        log_message("Failed to set initial GPIO value.");
        gpiod_line_release(gpio_line);
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

int read_adc(int channel) {
    unsigned char buffer[3];
    buffer[0] = 0b10000000 | ((channel & 0x0F) << 4);
    buffer[1] = 0;
    buffer[2] = 0;

    struct spi_ioc_transfer spi;
    memset(&spi, 0, sizeof(spi));
    spi.tx_buf = (unsigned long)buffer;
    spi.rx_buf = (unsigned long)buffer;
    spi.len = 3;
    spi.speed_hz = SPI_SPEED;
    spi.mode = SPI_MODE;
    spi.bits_per_word = SPI_BITS;
    spi.delay_usecs = SPI_DELAY;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &spi) < 0) {
        log_message("SPI read failed.");
        return -1;
    }

    int adc_value = (buffer[1] << 8) | buffer[2];
    return adc_value;
}

int map_adc_to_percent(int adc_value) {
    int max_adc = 1023;
    int min_adc = 0;
    int moisture_percent = (adc_value - min_adc) * 100 / (max_adc - min_adc);
    return moisture_percent;
}

void check_moisture() {
    int adc_value = read_adc(0);
    if (adc_value < 0) {
        log_message("ADC read failed, skipping moisture check.");
        return;
    }

    int moisture_percent = map_adc_to_percent(adc_value);
    log_message("Moisture level: %d%%", moisture_percent);

    if (moisture_percent < MOISTURE_THRESHOLD) {
        if (current_pump_state == PUMP_OFF) {
            if (gpiod_line_set_value(gpio_line, GPIO_ACTIVE_HIGH) < 0) {
                log_message("Failed to turn on pump.");
            } else {
                current_pump_state = PUMP_ON;
                log_message("Pump turned on.");
            }
        }
    } else {
        if (current_pump_state == PUMP_ON) {
            if (gpiod_line_set_value(gpio_line, 0) < 0) {
                log_message("Failed to turn off pump.");
            } else {
                current_pump_state = PUMP_OFF;
                log_message("Pump turned off.");
            }
        }
    }
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if (init_spi() < 0) {
        log_message("SPI initialization failed.");
        return EXIT_FAILURE;
    }

    if (init_gpio() < 0) {
        log_message("GPIO initialization failed.");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    log_message("Program started.");

    while (running) {
        check_moisture();
        sleep(LOG_INTERVAL);
    }

    if (gpio_line) {
        gpiod_line_release(gpio_line);
    }
    if (spi_fd >= 0) {
        close(spi_fd);
    }

    log_message("Program terminated.");
    return EXIT_SUCCESS;
}

