#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_MAX_SPEED_HZ 1000000
#define CHANNEL_COUNT 3
#define CHANNELS {0, 1, 2}
#define CSV_FILE "sensor_data.csv"

volatile int running = 1;
FILE *csv_file = NULL;

void handle_sigint(int sig) {
    running = 0;
    if (csv_file) {
        fclose(csv_file);
        csv_file = NULL;
    }
    if (ioctl(spi_fd, SPI_IOC_DISABLE, 0) < 0) {
        perror("ioctl SPI_IOC_DISABLE");
    }
    close(spi_fd);
    exit(EXIT_SUCCESS);
}

int spi_init() {
    int fd = open(SPI_DEVICE, O_RDWR);
    if (fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("ioctl SPI_IOC_WR_MODE");
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS_PER_WORD) < 0) {
        perror("ioctl SPI_IOC_WR_BITS_PER_WORD");
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_MAX_SPEED_HZ) < 0) {
        perror("ioctl SPI_IOC_WR_MAX_SPEED_HZ");
        close(fd);
        return -1;
    }

    return fd;
}

void spi_read(int spi_fd, int channel, unsigned char *data, size_t len) {
    unsigned char tx[3] = {0x01, (unsigned char)(channel << 4), 0x00};
    struct spi_ioc_transfer spi = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)data,
        .len = len,
        .speed_hz = SPI_MAX_SPEED_HZ,
        .delay_usecs = 0,
        .bits_per_word = SPI_BITS_PER_WORD
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &spi) < 0) {
        perror("SPI read failed");
        exit(EXIT_FAILURE);
    }
}

void log_data(unsigned char *data) {
    if (csv_file == NULL) {
        csv_file = fopen(CSV_FILE, "w");
        if (csv_file == NULL) {
            perror("Failed to open CSV file");
            exit(EXIT_FAILURE);
        }
        fprintf(csv_file, "Channel0,Channel1,Channel2\n");
    }

    int values[CHANNEL_COUNT];
    for (int i = 0; i < CHANNEL_COUNT; i++) {
        values[i] = (data[1] << 8) | data[0];
    }

    fprintf(csv_file, "%d,%d,%d\n", values[0], values[1], values[2]);
    fflush(csv_file);
}

int main() {
    signal(SIGINT, handle_sigint);

    int spi_fd = spi_init();
    if (spi_fd < 0) {
        exit(EXIT_FAILURE);
    }

    unsigned char rx[3];

    while (running) {
        for (int channel : CHANNELS) {
            spi_read(spi_fd, channel, rx, 3);
            log_data(rx);
        }

        usleep(1000000); // 1 second delay
    }

    if (csv_file) {
        fclose(csv_file);
    }

    if (ioctl(spi_fd, SPI_IOC_DISABLE, 0) < 0) {
        perror("ioctl SPI_IOC_DISABLE");
    }

    close(spi_fd);

    return 0;
}

