#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/time.h>
#include <libjson/json.h>
#include <libmqtte/mqtte.h>

#define LED_PIN 17
#define CLIENT_ID "rpi_led_control"
#define MQTT_BROKER "mqtt.eclipseprojects.io"
#define MQTT_PORT 1883
#define MQTT_TOPIC "home/led_control"
#define MAX_RECONNECT_DELAY 60
#define RECONNECT_DELAY_MULTIPLIER 2

typedef enum {
    STATE_DISCONNECTED,
    STATE_CONNECTED
} ConnectionState;

typedef struct {
    mqtte_client_t client;
    ConnectionState state;
    int reconnect_delay;
    int reconnect_count;
    int led_state;
    int gpio_initialized;
} AppContext;

void log_error(const char *message) {
    struct timeval tv;
    gettimeofday(&tv, NULL);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&tv.tv_sec));
    fprintf(stderr, "[%s] ERROR: %s\n", timestamp, message);
}

void log_info(const char *message) {
    struct timeval tv;
    gettimeofday(&tv, NULL);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&tv.tv_sec));
    fprintf(stderr, "[%s] INFO: %s\n", timestamp, message);
}

void signal_handler(int signal) {
    log_info("Received signal, shutting down...");
    exit(EXIT_SUCCESS);
}

void gpio_init(AppContext *ctx) {
    if (ctx->gpio_initialized) {
        return;
    }

    if (mqtte_gpio_init(LED_PIN) != 0) {
        log_error("Failed to initialize GPIO");
        exit(EXIT_FAILURE);
    }

    if (mqtte_gpio_set_direction(LED_PIN, MQTTE_GPIO_OUTPUT) != 0) {
        log_error("Failed to set GPIO direction");
        exit(EXIT_FAILURE);
    }

    if (mqtte_gpio_set_value(LED_PIN, 0) != 0) {
        log_error("Failed to set initial LED state to OFF");
        exit(EXIT_FAILURE);
    }

    ctx->gpio_initialized = 1;
}

void mqtt_connect(AppContext *ctx) {
    mqtte_options_t options = {
        .host = MQTT_BROKER,
        .port = MQTT_PORT,
        .client_id = CLIENT_ID,
        .keepalive = 60,
        .clean_session = 1,
        .qos = 0
    };

    if (mqtte_connect(&ctx->client, &options) != 0) {
        log_error("Failed to connect to MQTT broker");
        exit(EXIT_FAILURE);
    }

    log_info("Connected to MQTT broker");
    ctx->state = STATE_CONNECTED;
}

void mqtt_subscribe(AppContext *ctx) {
    if (mqtte_subscribe(&ctx->client, MQTT_TOPIC, 0) != 0) {
        log_error("Failed to subscribe to topic");
        exit(EXIT_FAILURE);
    }

    log_info("Subscribed to topic: %s", MQTT_TOPIC);
}

void mqtt_disconnect(AppContext *ctx) {
    if (ctx->state == STATE_CONNECTED) {
        mqtte_disconnect(&ctx->client);
        log_info("Disconnected from MQTT broker");
        ctx->state = STATE_DISCONNECTED;
    }
}

void mqtt_loop(AppContext *ctx) {
    if (mqtte_loop(&ctx->client) != 0) {
        log_error("MQTT loop failed");
        exit(EXIT_FAILURE);
    }
}

