#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_DO_PIN 17
#define GPIO_ALARM_PIN 18
#define DELAY_MS 100
#define ALARM_DURATION_MS 1000

static bool running = true;

void handle_signal(int signal) {
    running = false;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *do_line, *alarm_line;
    int ret;

    // Set up signal handling
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Open the GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    // Request DO line (input)
    do_line = gpiod_line_request_input(chip, GPIO_DO_PIN, "sound_sensor_do");
    if (!do_line) {
        fprintf(stderr, "Failed to request DO line\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request alarm line (output)
    alarm_line = gpiod_line_request_output(chip, GPIO_ALARM_PIN, "alarm_led", 0);
    if (!alarm_line) {
        fprintf(stderr, "Failed to request alarm line\n");
        gpiod_line_release(do_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (running) {
        // Read DO pin
        ret = gpiod_line_get_value(do_line);
        if (ret < 0) {
            fprintf(stderr, "Failed to read DO line: %s\n", strerror(-ret));
            break;
        }

        // Print sound level
        printf("Sound level: %d\n", ret);

        // Check for sound event (DO pin is LOW)
        if (ret == 0) {
            // Turn on alarm LED
            ret = gpiod_line_set_value(alarm_line, 1);
            if (ret < 0) {
                fprintf(stderr, "Failed to set alarm line: %s\n", strerror(-ret));
                break;
            }

            // Wait for 1 second
            usleep(ALARM_DURATION_MS * 1000);

            // Turn off alarm LED
            ret = gpiod_line_set_value(alarm_line, 0);
            if (ret < 0) {
                fprintf(stderr, "Failed to set alarm line: %s\n", strerror(-ret));
                break;
            }
        }

        // Delay between reads
        usleep(DELAY_MS * 1000);
    }

    // Clean up
    gpiod_line_release(alarm_line);
    gpiod_line_release(do_line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

