#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/gpio.h>
#include <signal.h>
#include <time.h>
#include <errno.h>

volatile sig_atomic_t exit_flag = 0;

void handle_signal(int signum) {
    exit_flag = 1;
}

int main() {
    int chip_fd = -1;
    struct gpiohandle_request req = {0};
    struct gpioevent_request event_req = {0};
    struct gpioevent_data event_data;
    int event_fd = -1;
    int log_fd = -1;
    char log_message[256];

    // Set up signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Open the GPIO chip
    chip_fd = open("/dev/gpiochip0", O_RDWR);
    if (chip_fd < 0) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    // Request the GPIO line
    req.line_offset = 17; // BCM GPIO 17
    req.flags = GPIOHANDLE_REQUEST_INPUT | GPIOHANDLE_REQUEST_Falling_EDGE;
    req.consumer_label = "vibration-monitor";
    req.lines = 1;

    int handle_fd = ioctl(chip_fd, GPIO_GET_LINEHANDLE_IOCTL, &req);
    if (handle_fd < 0) {
        perror("Failed to get GPIO line handle");
        close(chip_fd);
        exit(EXIT_FAILURE);
    }

    // Set up event request
    event_req.lineoffset = 17;
    event_req.handle_flags = GPIOEVENT_REQUEST_Falling_EDGE;
    event_req.consumer_label = "vibration-monitor";
    event_req.flags = GPIOEVENT_REQUEST_Falling_EDGE;

    event_fd = ioctl(handle_fd, GPIO_GET_EVENT_IOCTL, &event_req);
    if (event_fd < 0) {
        perror("Failed to get GPIO event file descriptor");
        close(handle_fd);
        close(chip_fd);
        exit(EXIT_FAILURE);
    }

    // Open log file in append mode
    log_fd = open("/var/log/vibration_shutdown.log", O_WRONLY | O_APPEND | O_CREAT, 0644);
    if (log_fd < 0) {
        perror("Failed to open log file");
        close(event_fd);
        close(handle_fd);
        close(chip_fd);
        exit(EXIT_FAILURE);
    }

    // Main loop
    while (!exit_flag) {
        // Wait for an event
        int bytes_read = read(event_fd, &event_data, sizeof(event_data));
        if (bytes_read < 0) {
            perror("Failed to read event");
            break;
        }

        if (event_data.event_type == GPIOEVENT_EVENT_Falling_EDGE) {
            // Generate timestamp
            time_t now = time(NULL);
            struct tm *tm_info = localtime(&now);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

            // Prepare log message
            snprintf(log_message, sizeof(log_message), "[%s] Vibration detected, initiating shutdown\n", timestamp);
            write(log_fd, log_message, strlen(log_message));

            // Print message to stdout
            printf("%s", log_message);

            // Initiate shutdown
            if (system("sudo shutdown -h now") != 0) {
                perror("Failed to initiate shutdown");
            }
        }
    }

    // Clean up resources
    close(log_fd);
    close(event_fd);
    close(handle_fd);
    close(chip_fd);

    return 0;
}

