#include <linux/spi/spidev.h>
#include <gpiod.h>
#include <signal.h>
#include <time.h>
#include <errno.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define SPI_MODE SPI_MODE_0
#define CE_PIN 8
#define BUFFER_SIZE 120
#define SAMPLE_INTERVAL 5
#define FILE_NAME "temp_log.dat"

typedef struct {
    float data[BUFFER_SIZE];
    int head;
    int tail;
    int full;
} CircularBuffer;

void init_buffer(CircularBuffer *buffer) {
    buffer->head = 0;
    buffer->tail = 0;
    buffer->full = 0;
}

float read_lm35_adc(int spi_fd) {
    uint8_t tx[3] = {0b00100000, 0, 0};
    uint8_t rx[3] = {0};

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tx) < 0) {
        perror("SPI transfer failed");
        return -1.0;
    }

    uint16_t adc_value = (rx[1] << 8) | rx[2];
    return (float)adc_value * 0.0625; // 0.0625°C per LSB
}

void write_buffer(CircularBuffer *buffer, float value) {
    if (buffer->full) {
        buffer->tail = (buffer->tail + 1) % BUFFER_SIZE;
    }
    buffer->data[buffer->head] = value;
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    buffer->full = (buffer->head == buffer->tail);
}

void print_temperature(float temp) {
    printf("Temperature: %.2f °C\n", temp);
}

void save_buffer_to_file(CircularBuffer *buffer, const char *filename) {
    FILE *file = fopen(filename, "wb+");
    if (!file) {
        perror("Failed to open file");
        return;
    }

    fwrite(buffer->data, sizeof(float), BUFFER_SIZE, file);
    fclose(file);
}

void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        printf("\nShutting down...\n");
        exit(EXIT_SUCCESS);
    }
}

int main() {
    int spi_fd;
    struct gpiod_line *ce_line;
    CircularBuffer buffer;
    FILE *file;
    int running = 1;
    struct sigaction sa;

    // Initialize signal handler
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Failed to set SIGINT handler");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Failed to set SIGTERM handler");
        return 1;
    }

    // Initialize SPI
    spi_fd = open(SPI_DEVICE, O_RDWR | O_NOCTTY | O_SYNC);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return 1;
    }

    // Set SPI mode and speed
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        return 1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        return 1;
    }

    // Initialize CE pin using libgpiod
    struct gpiod_chip *chip;
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        close(spi_fd);
        return 1;
    }

    ce_line = gpiod_line_get(chip, CE_PIN);
    if (!ce_line) {
        perror("Failed to get CE line");
        gpiod_chip_close(chip);
        close(spi_fd);
        return 1;
    }

    if (gpiod_line_request_output(ce_line, "CE", GPIOD_LINE_REQUEST_OUTPUT_ACTIVE_LOW) < 0) {
        perror("Failed to request CE line");
        gpiod_line_put(ce_line);
        gpiod_chip_close(chip);
        close(spi_fd);
        return 1;
    }

    // Initialize buffer
    init_buffer(&buffer);

    // Open file for logging
    file = fopen(FILE_NAME, "wb+");
    if (!file) {
        perror("Failed to open log file");
    }

    while (running) {
        // Set CE low
        if (gpiod_line_set_value(ce_line, 0) < 0) {
            perror("Failed to set CE low");
            break;
        }

        // Read ADC
        float temp = read_lm35_adc(spi_fd);
        if (temp < 0) {
            printf("SPI transfer failed, skipping sample.\n");
        } else {
            print_temperature(temp);
            write_buffer(&buffer, temp);
        }

        // Set CE high
        if (gpiod_line_set_value(ce_line, 1) < 0) {
            perror("Failed to set CE high");
        }

        // Save buffer to file
        if (file) {
            save_buffer_to_file(&buffer, FILE_NAME);
        }

        // Sleep for 5 seconds
        usleep(SAMPLE_INTERVAL * 1000000);
    }

    // Clean up
    if (file) {
        fclose(file);
    }

    gpiod_line_put(ce_line);
    gpiod_chip_close(chip);
    close(spi_fd);

    return 0;
}
