#define LIGHT_CONTINUOUS_L_RESOLUTION 0x20

#define MAX_ADC_VALUE 1023
#define ADC_CHANNEL 0

volatile int running = 1;

void handle_signal(int sig) {
    running = 0;
}

void i2c_init(int *fd) {
    *fd = open(I2C_BUS, O_RDWR);
    if (*fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    if (ioctl(*fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(*fd);
        exit(EXIT_FAILURE);
    }
}

void spi_init(int *fd) {
    *fd = open(SPI_BUS, O_RDWR | O_NOCTTY | O_NDELAY);
    if (*fd < 0) {
        perror("Failed to open SPI bus");
        exit(EXIT_FAILURE);
    }

    if (ioctl(*fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("Failed to set SPI mode");
        close(*fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(*fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS) < 0) {
        perror("Failed to set SPI bits per word");
        close(*fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(*fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("Failed to set SPI speed");
        close(*fd);
        exit(EXIT_FAILURE);
    }
}

void i2c_read_light(int fd, uint16_t *lux) {
    uint8_t cmd[2] = {LIGHT_COMMAND, LIGHT_CONTINUOUS_H_RESOLUTION};
    if (write(fd, cmd, 2) < 0) {
        perror("I2C write error");
        return;
    }

    usleep(50000); // Wait for measurement to complete

