        return;
    }

    if (ioctl(fd, SPI_IOC_WR_DELAY, &SPI_DELAY) < 0) {
        perror("SPI delay set failed");
        return;
    }

    if (read(fd, rx, 3) < 0) {
        perror("SPI read error");
        return;
    }

    *adc_value = (rx[1] << 8) | rx[2];
}

