        exit(EXIT_FAILURE);
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("Failed to set SIGTERM handler");
        exit(EXIT_FAILURE);
    }

    // Initialize I2C and SPI
    i2c_init(&i2c_fd);
    spi_init(&spi_fd);

    // Open log file
    log_file = fopen("environmental_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        close(i2c_fd);
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    while (running) {
        time_t current_time = time(NULL);
        if (current_time - last_log_time >= 1) {
            last_log_time = current_time;

            uint16_t lux = 0;
            uint16_t adc_value = 0;

            // Read light sensor
            i2c_read_light(i2c_fd, &lux);

            // Read sound sensor
            spi_read_adc(spi_fd, &adc_value);

            // Log data
            log_data(log_file, current_time, lux, adc_value);
        }

        usleep(100000); // Sleep for 100ms to avoid busy-waiting
    }

    // Clean up
    fclose(log_file);
    close(i2c_fd);
    close(spi_fd);

    return 0;
}

