#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define BCM_PIN 17
#define CSV_FILE "flame_events.log"
#define POLL_INTERVAL 1

typedef enum {
    STATE_RUNNING,
    STATE_EXITING
} program_state;

program_state state = STATE_RUNNING;

void handle_signal(int signal) {
    state = STATE_EXITING;
}

void cleanup_gpio(gpiod_line *line) {
    if (line) {
        gpiod_line_release(line);
    }
}

void log_event(FILE *csv_file, time_t timestamp, int pin, int state) {
    char timestamp_str[30];
    struct tm *tm_info = localtime(&timestamp);
    strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(csv_file, "%s,%d,%d\n", timestamp_str, pin, state);
    fflush(csv_file);
}

int main() {
    gpiod_line *line = NULL;
    FILE *csv_file = NULL;
    int result;
    time_t last_poll_time = 0;

    // Set up signal handling
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Open CSV file for appending
    csv_file = fopen(CSV_FILE, "a");
    if (!csv_file) {
        fprintf(stderr, "Failed to open CSV file: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    // Initialize GPIO line
    struct gpiod_line_config config = GPIOD_LINE_CONFIG_DEFAULTS;
    config.direction = GPIOD_LINE_DIRECTION_INPUT;
    config.edge_events = GPIOD_LINE_EDGE_NONE;
    config.consumer = "flame_sensor";

    line = gpiod_line_get("gpiochip4", BCM_PIN, &config);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line: %s\n", strerror(errno));
        fclose(csv_file);
        return EXIT_FAILURE;
    }

    // Set pull-down resistor
    result = gpiod_line_set_pull_mode(line, GPIOD_LINE_PULL_DOWN, GPIOD_LINE_FLAG_ACTIVE);
    if (result < 0) {
        fprintf(stderr, "Failed to set pull mode: %s\n", strerror(errno));
        cleanup_gpio(line);
        fclose(csv_file);
        return EXIT_FAILURE;
    }

    // Main loop
    while (state == STATE_RUNNING) {
        time_t current_time = time(NULL);
        if (current_time - last_poll_time >= POLL_INTERVAL) {
            last_poll_time = current_time;

            int value;
            result = gpiod_line_get_value(line, &value);
            if (result < 0) {
                fprintf(stderr, "Failed to read GPIO line: %s\n", strerror(errno));
                cleanup_gpio(line);
                fclose(csv_file);
                return EXIT_FAILURE;
            }

            log_event(csv_file, current_time, BCM_PIN, value);

            if (value == 1) {
                fprintf(stderr, "ALERT: Flame detected on pin %d!\n", BCM_PIN);
            }
        }

        usleep(100000); // Sleep for 100ms to reduce CPU usage
    }

    // Cleanup
    cleanup_gpio(line);
    fclose(csv_file);

    return EXIT_SUCCESS;
}

