#include <sys/ioctl.h>
#include <sys/time.h>
#include <sys/select.h>
#include <linux/spi/spidev.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <time.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define I2C_DEVICE "/dev/i2c-1"
#define MCP3008_CS 0
#define MCP4725_ADDR 0x60
#define SPI_SPEED 500000
#define LOG_FILE "temperature_log.txt"
#define SAMPLE_INTERVAL 500000  // 0.5 seconds in microseconds
#define MAX_RETRIES 5
#define RETRY_DELAY 1000000  // 1 second

typedef struct {
    int spi_fd;
    int i2c_fd;
    FILE *log_file;
    int running;
} app_state;

void handle_signal(int sig) {
    if (sig == SIGINT) {
        printf("Received SIGINT, shutting down...\n");
        app_state *state = (app_state *)malloc(sizeof(app_state));
        state->running = 0;
        // Close SPI
        if (state->spi_fd >= 0) {
            close(state->spi_fd);
        }
        // Close I2C
