    spi.bits_per_word = 8;

    if (ioctl(fd, SPI_IOC_WR_MODE, &SPI_MODE_0) < 0) {
        perror("SPI mode set failed");
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &spi.bits_per_word) < 0) {
        perror("SPI bits per word set failed");
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &spi.speed_hz) < 0) {
        perror("SPI speed set failed");
        close(fd);
        return -1;
    }

    return fd;
}

int init_i2c() {
    int fd = open(I2C_DEVICE, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C device");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, MCP4725_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

int read_adc(int spi_fd, int channel) {
    unsigned char buffer[3];
    buffer[0] = 0b10100000 | (channel >> 2);  // 8-bit command: 10100000 + channel (4 bits)
    buffer[1] = 0;
    buffer[2] = 0;

    struct spi_ioc_transfer spi;
    memset(&spi, 0, sizeof(spi));
    spi.tx_buf = (unsigned long)buffer;
    spi.len = 3;
    spi.speed_hz = SPI_SPEED;
    spi.bits_per_word = 8;

