} spi_context;

void handle_sigint(int sig) {
    printf("\nReceived SIGINT, cleaning up...\n");
    if (signal(sig, SIG_IGN) == SIG_ERR) {
        perror("Failed to ignore signal");
    }
    if (spi_context.fd >= 0) {
        close(spi_context.fd);
    }
    if (fclose(spi_context.fd) != 0) {
        perror("Failed to close log file");
    }
    printf("Goodbye.\n");
    exit(0);
}

int init_spi() {
    spi_context.fd = open(SPI_DEVICE, O_RDWR | O_NOCTTY | O_NDELAY);
    if (spi_context.fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    if (ioctl(spi_context.fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("Failed to set SPI mode");
        close(spi_context.fd);
        return -1;
    }

    if (ioctl(spi_context.fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS) < 0) {
        perror("Failed to set SPI bits per word");
        close(spi_context.fd);
        return -1;
    }

    if (ioctl(spi_context.fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("Failed to set SPI speed");
        close(spi_context.fd);
        return -1;
    }

    return 0;
}

int read_adc(int channel) {
    unsigned char tx[SPI_MAX_TRANSFER];
    unsigned char rx[SPI_MAX_TRANSFER];
    struct spi_ioc_transfer tr = {
        .tx_nbytes = SPI_BITS,
        .rx_nbytes = SPI_BITS,
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .delay_usecs = 0,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS
    };

    tx[0] = 1 << 7;  // Start bit
    tx[0] |= (channel << 4) & 0x0F;  // Channel address
    tx[1] = 0x00;    // Dummy byte

    if (ioctl(spi_context.fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI transfer failed");
        return -1;
    }

    return (rx[0] << 8) | rx[1];
}

void log_data(int *adc_values) {
    static FILE *log_file = NULL;
    if (log_file == NULL) {
        log_file = fopen("soil_data.txt", "a");
        if (log_file == NULL) {
            perror("Failed to open log file");
            return;
        }
    }

    time_t now;
    struct tm *timeinfo;
    char timestamp[20];

    time(&now);
    timeinfo = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    for (int i = 0; i < NUM_SENSORS; i++) {
        fprintf(log_file, "%s, %d\n", timestamp, adc_values[i]);
    }

    if (fflush(log_file) != 0) {
        perror("Failed to flush log file");
    }
}

int main() {
    if (signal(SIGINT, handle_sigint) == SIG_ERR) {
        perror("Failed to set signal handler");
        return 1;
    }

    if (init_spi() < 0) {
        fprintf(stderr, "SPI initialization failed.\n");
        return 1;
    }

    spi_context.running = 1;

    while (spi_context.running) {
        int adc_values[NUM_SENSORS];
        for (int i = 0; i < NUM_SENSORS; i++) {
            int value = read_adc(CHANNELS[i]);
            if (value < 0) {
                fprintf(stderr, "ADC read failed for channel %d.\n", CHANNELS[i]);
                continue;
            }
            adc_values[i] = value;
        }

        log_data(adc_values);

        sleep(60);
    }

    close(spi_context.fd);
    fclose(log_file);
    printf("Program exited normally.\n");
    return 0;
}

