// Define BCM GPIO pins for relays
#define RELAY_1_PIN 17
#define RELAY_2_PIN 22
#define RELAY_3_PIN 23
#define RELAY_4_PIN 24

// Global variables for GPIO lines
struct gpiod_line *relay_lines[4] = {NULL, NULL, NULL, NULL};

// Function to initialize a GPIO line
int init_gpio_line(int pin) {
    struct gpiod_chip *chip;
    struct gpiod_line *line;

    chip = gpiod_chip_open_by_number(1); // BCM2 (GPIO chip 1)
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return -1;
    }

    line = gpiod_chip_get_line(chip, pin);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line %d\n", pin);
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(line, "relay", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line %d as output\n", pin);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return -1;
    }

    relay_lines[pin - 1] = line;
    return 0;
}

// Function to set a relay state
int set_relay_state(int index, int state) {
    if (!relay_lines[index]) {
        fprintf(stderr, "Relay line %d not initialized\n", index + 1);
        return -1;
    }

    if (gpiod_line_set_value(relay_lines[index], state) < 0) {
        fprintf(stderr, "Failed to set relay %d to %d\n", index + 1, state);
        return -1;
    }

    return 0;
}

