#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_SPEED 1000000
#define SPI_BITS 8
#define SPI_DELAY 10000  // 10 ms
#define LED_PIN 16
#define ADC_CHANNEL 0
#define THRESHOLD 500
#define DEBOUNCE_DELAY 500000  // 500 ms
#define LOG_FILE "sound_events.log"

typedef struct {
    int spi_fd;
    struct gpiod_line *led_line;
    int running;
} app_state;

void handle_sigint(int sig) {
    app_state *state = (app_state *)malloc(sizeof(app_state));
    if (state) {
        state->running = 0;
    }
    printf("Caught signal %d, shutting down...\n", sig);
}

void log_event(const char *timestamp) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return;
    }

    fprintf(log_file, "%s\n", timestamp);
    fclose(log_file);
}

void init_gpio(app_state *state) {
    struct gpiod_chip *chip;
    struct gpiod_line *line;

    chip = gpiod_chip_open("/dev/gpiochip4");
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    line = gpiod_line_get(chip, LED_PIN);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(line, "LED", GPIOD_LINE_REQUEST_OUTPUT_ACTIVE_LOW)) {
        perror("Failed to request GPIO line");
        gpiod_line_put(line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    state->led_line = line;
    gpiod_line_set_value(line, 0);  // Turn off LED initially
}

void init_spi(app_state *state) {
    state->spi_fd = open(SPI_DEVICE, O_RDWR);
    if (state->spi_fd < 0) {
        perror("Failed to open SPI device");
        exit(EXIT_FAILURE);
    }

    if (ioctl(state->spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("Failed to set SPI mode");
        close(state->spi_fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(state->spi_fd, SPI_IOC_WR_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("Failed to set SPI speed");
        close(state->spi_fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(state->spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS) < 0) {
        perror("Failed to set SPI bits per word");
        close(state->spi_fd);
        exit(EXIT_FAILURE);
    }
}

void read_adc_value(int spi_fd, int channel) {
    unsigned char tx[3];
    unsigned char rx[3];
    int len = 3;

    tx[0] = 1 << 7 | ((channel & 0x07) << 4);
    tx[1] = 0;
    tx[2] = 0;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tx) < 0) {
        perror("SPI transfer failed");
        exit(EXIT_FAILURE);
    }

    int adc_value = (rx[1] << 8) | rx[2];
    printf("ADC Value: %d\n", adc_value);
    return adc_value;
}

void trigger_led(app_state *state) {
    gpiod_line_set_value(state->led_line, 1);  // Turn on LED
    usleep(DEBOUNCE_DELAY);
    gpiod_line_set_value(state->led_line, 0);  // Turn off LED
}

void cleanup(app_state *state) {
    if (state->led_line) {
        gpiod_line_put(state->led_line);
    }

    if (state->spi_fd >= 0) {
        close(state->spi_fd);
    }

    printf("Resources released.\n");
}

int main() {
    app_state state = {0};
    struct sigaction sa;
    time_t now;
    struct tm *timeinfo;
    char timestamp[20];

    // Initialize signal handler
    sa.sa_handler = handle_sigint;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("Failed to set signal handler");
        exit(EXIT_FAILURE);
    }

    // Initialize GPIO and SPI
    init_gpio(&state);
    init_spi(&state);

    state.running = 1;

    while (state.running) {
        int adc_value = read_adc_value(state.spi_fd, ADC_CHANNEL);

        if (adc_value > THRESHOLD) {
            time(&now);
            timeinfo = localtime(&now);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
            log_event(timestamp);
            trigger_led(&state);
        }

        usleep(SPI_DELAY);
    }

    cleanup(&state);
    return 0;
}

