#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/time.h>
#include <sys/select.h>
#include <linux/spi/spidev.h>
#include <pthread.h>
#include <signal.h>
#include <errno.h>
#include <time.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define SPI_MODE SPI_MODE_0
#define SPI_BITS 8
#define SPI_DELAY 0

#define GPIO_IN1 17
#define GPIO_IN2 18
#define GPIO_ENA 27

#define RAIN_THRESHOLD 5
#define MOTOR_DURATION 3
#define PWM_DUTY 150
#define PWM_RANGE 255

volatile sig_atomic_t exit_flag = 0;

typedef struct {
    int spi_fd;
    struct gpiod_line *in1;
    struct gpiod_line *in2;
    struct gpiod_line *ena;
    FILE *log_file;
    pthread_mutex_t log_mutex;
} app_state;

void handle_signal(int sig) {
    exit_flag = 1;
}

int init_gpio(app_state *state) {
    int ret;

    state->in1 = gpiod_line_get("BCM", GPIO_IN1, "in");
    if (!state->in1) {
        fprintf(stderr, "Failed to get GPIO %d (IN1)\n", GPIO_IN1);
        return -1;
    }

    state->in2 = gpiod_line_get("BCM", GPIO_IN2, "in");
    if (!state->in2) {
        fprintf(stderr, "Failed to get GPIO %d (IN2)\n", GPIO_IN2);
        gpiod_line_put(state->in1);
        return -1;
    }

    state->ena = gpiod_line_get("BCM", GPIO_ENA, "out");
    if (!state->ena) {
        fprintf(stderr, "Failed to get GPIO %d (ENA)\n", GPIO_ENA);
        gpiod_line_put(state->in1);
        gpiod_line_put(state->in2);
        return -1;
    }

    ret = gpiod_line_request_output(state->ena, "ENA", 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request output for GPIO %d (ENA)\n", GPIO_ENA);
        gpiod_line_put(state->in1);
        gpiod_line_put(state->in2);
        gpiod_line_put(state->ena);
        return -1;
    }

    return 0;
}

int init_spi(app_state *state) {
    int ret;

    state->spi_fd = open(SPI_DEVICE, O_RDWR | O_NOCTTY | O_SYNC);
    if (state->spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device %s: %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    ret = ioctl(state->spi_fd, SPI_IOC_WR_MODE, &SPI_MODE);
    if (ret < 0) {
        fprintf(stderr, "Failed to set SPI mode: %s\n", strerror(errno));
        close(state->spi_fd);
        return -1;
    }

    ret = ioctl(state->spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS);
    if (ret < 0) {
        fprintf(stderr, "Failed to set SPI bits per word: %s\n", strerror(errno));
        close(state->spi_fd);
        return -1;
    }

    ret = ioctl(state->spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED);
    if (ret < 0) {
        fprintf(stderr, "Failed to set SPI speed: %s\n", strerror(errno));
        close(state->spi_fd);
        return -1;
    }

    return 0;
}

int init_log(app_state *state) {
    state->log_file = fopen("rain_log.txt", "a");
    if (!state->log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return -1;
    }

    pthread_mutex_init(&state->log_mutex, NULL);
    return 0;
}

void log_rain_level(app_state *state, int level) {
    struct timeval tv;
    char timestamp[30];
    char log_line[100];

    gettimeofday(&tv, NULL);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&tv.tv_sec));

    snprintf(log_line, sizeof(log_line), "%s, %d\n", timestamp, level);

    pthread_mutex_lock(&state->log_mutex);
    if (fprintf(state->log_file, "%s", log_line) < 0) {
        fprintf(stderr, "Failed to write to log file: %s\n", strerror(errno));
    }
    if (fflush(state->log_file) < 0) {
        fprintf(stderr, "Failed to flush log file: %s\n", strerror(errno));
    }
    pthread_mutex_unlock(&state->log_mutex);
}

int read_rain_sensor(app_state *state) {
    uint8_t tx[1] = {0x01};
    uint8_t rx[2] = {0};
    struct spi_ioc_transfer spi;
    int ret;

    memset(&spi, 0, sizeof(spi));
    spi.tx_buf = (unsigned long)tx;
    spi.rx_buf = (unsigned long)rx;
    spi.len = 1;
    spi.speed_hz = SPI_SPEED;
    spi.delay_usecs = SPI_DELAY;
    spi.bits_per_word = SPI_BITS;

    ret = ioctl(state->spi_fd, SPI_IOC_MESSAGE(1), &spi);
    if (ret < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }

    int level = (rx[0] & 0x0F) * 10;
    return level;
}

void drive_motor(app_state *state, int direction) {
    int ret;

    if (direction == 1) {
        gpiod_line_set(state->in1, 1);
        gpiod_line_set(state->in2, 0);
    } else {
        gpiod_line_set(state->in1, 0);
        gpiod_line_set(state->in2, 1);
    }

    ret = gpiod_line_set_value(state->ena, PWM_DUTY * PWM_RANGE / 255);
    if (ret < 0) {
        fprintf(stderr, "Failed to set PWM duty cycle: %s\n", strerror(errno));
    }
}

void stop_motor(app_state *state) {
    gpiod_line_set(state->in1, 0);
    gpiod_line_set(state->in2, 0);
    gpiod_line_set_value(state->ena, 0);
}

void cleanup(app_state *state) {
    if (state->log_file) {
        fclose(state->log_file);
    }

    if (state->ena) {
        gpiod_line_put(state->ena);
    }

    if (state->in2) {
        gpiod_line_put(state->in2);
    }

    if (state->in1) {
        gpiod_line_put(state->in1);
    }

    if (state->spi_fd >= 0) {
        close(state->spi_fd);
    }

    pthread_mutex_destroy(&state->log_mutex);
}

int main() {
    app_state state = {0};
    int level;
    struct timespec ts;
    int ret;

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if (init_gpio(&state) < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    if (init_spi(&state) < 0) {
        fprintf(stderr, "Failed to initialize SPI\n");
        cleanup(&state);
        return 1;
    }

    if (init_log(&state) < 0) {
        fprintf(stderr, "Failed to initialize log file\n");
        cleanup(&state);
        return 1;
    }

    while (!exit_flag) {
        level = read_rain_sensor(&state);
        if (level < 0) {
            fprintf(stderr, "Failed to read rain sensor\n");
            break;
        }

        log_rain_level(&state, level);

        if (level > RAIN_THRESHOLD) {
            drive_motor(&state, 1);
        } else {
            drive_motor(&state, -1);
        }

        clock_gettime(CLOCK_MONOTONIC, &ts);
        ts.tv_sec += 1;
        nanosleep(&ts, NULL);
    }

    stop_motor(&state);

    cleanup(&state);

    return 0;
}

