#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/gpio.h>
#include <signal.h>
#include <time.h>
#include <errno.h>

#define GPIO_ADC_PIN 26
#define GPIO_LED_PIN 16
#define DEBOUNCE_INTERVAL_MS 50
#define CLAP_DURATION_MS 500
#define ADC_SAMPLE_COUNT 100
#define ADC_SAMPLE_THRESHOLD 1000

typedef enum {
    STATE_IDLE,
    STATE_DEBOUNCING,
    STATE_CLAP_DETECTED
} State;

typedef struct {
    int adc_fd;
    int led_fd;
    int adc_pin;
    int led_pin;
    int sample_count;
    int sample_sum;
    int state;
    struct timespec last_clap_time;
    int debounce_timer;
} AppContext;

void init_gpio(AppContext *ctx) {
    int fd;
    struct gpiohandle_request req;
    struct gpiohandle_data data;

    // Initialize ADC pin (GPIO26) as input
    fd = open("/dev/gpiochip0", O_RDWR);
    if (fd < 0) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    req.lineoffsets[0] = ctx->adc_pin;
    req.flags = GPIOHANDLE_REQUEST_INPUT;
    req.count = 1;
    if (ioctl(fd, GPIO_GET_LINEHANDLE_IOCTL, &req) < 0) {
        perror("Failed to get line handle for ADC pin");
        close(fd);
        exit(EXIT_FAILURE);
    }

    ctx->adc_fd = req.fd;

    // Initialize LED pin (GPIO16) as output
    fd = open("/dev/gpiochip0", O_RDWR);
    if (fd < 0) {
        perror("Failed to open GPIO chip for LED");
        exit(EXIT_FAILURE);
    }

    req.lineoffsets[0] = ctx->led_pin;
    req.flags = GPIOHANDLE_REQUEST_OUTPUT;
    req.count = 1;
    if (ioctl(fd, GPIO_GET_LINEHANDLE_IOCTL, &req) < 0) {
        perror("Failed to get line handle for LED pin");
        close(fd);
        exit(EXIT_FAILURE);
    }

    ctx->led_fd = req.fd;

    // Set LED to off initially
    data.values[0] = 0;
    if (ioctl(ctx->led_fd, GPIOHANDLE_SET_LINE_VALUES_IOCTL, &data) < 0) {
        perror("Failed to set LED pin to off");
        exit(EXIT_FAILURE);
    }

    close(fd);
}

void cleanup_gpio(AppContext *ctx) {
    if (ctx->adc_fd >= 0) {
        close(ctx->adc_fd);
    }
    if (ctx->led_fd >= 0) {
        close(ctx->led_fd);
    }
}

void handle_sigint(int sig) {
    // Turn off LED
    struct gpiohandle_data data;
    data.values[0] = 0;
    if (ioctl(ctx->led_fd, GPIOHANDLE_SET_LINE_VALUES_IOCTL, &data) < 0) {
        perror("Failed to turn off LED on SIGINT");
    }

    // Clean up resources
    cleanup_gpio(ctx);
    printf("\nSIGINT received. Exiting...\n");
    exit(EXIT_SUCCESS);
}

int read_adc_sample(AppContext *ctx) {
    struct gpiohandle_data data;
    int value = 0;

    if (ioctl(ctx->adc_fd, GPIOHANDLE_GET_LINE_VALUES_IOCTL, &data) < 0) {
        perror("Failed to read ADC pin");
        return -1;
    }

    value = data.values[0];
    return value;
}

void detect_clap(AppContext *ctx) {
    ctx->sample_sum = 0;
    ctx->sample_count = 0;

    while (ctx->sample_count < ADC_SAMPLE_COUNT) {
        int sample = read_adc_sample(ctx);
        if (sample < 0) {
            printf("ADC read error, skipping sample\n");
            continue;
        }
        ctx->sample_sum += sample;
        ctx->sample_count++;
        usleep(1000); // 1ms per sample
    }

    double average = (double)ctx->sample_sum / ADC_SAMPLE_COUNT;
    if (average > ADC_SAMPLE_THRESHOLD) {
        ctx->state = STATE_CLAP_DETECTED;
        printf("Clap detected at %ld.%09ld\n", ctx->last_clap_time.tv_sec, ctx->last_clap_time.tv_nsec);
    } else {
        ctx->state = STATE_IDLE;
    }
}

void run_app(AppContext *ctx) {
    struct timespec clap_time;
    clock_gettime(CLOCK_MONOTONIC, &clap_time);
    ctx->last_clap_time = clap_time;

    while (1) {
        switch (ctx->state) {
            case STATE_IDLE:
                detect_clap(ctx);
                break;
            case STATE_DEBOUNCING:
                if (clock_gettime(CLOCK_MONOTONIC, &clap_time) == 0) {
                    if ((clap_time.tv_sec - ctx->last_clap_time.tv_sec) * 1000 +
                        (clap_time.tv_nsec / 1000000) >= DEBOUNCE_INTERVAL_MS) {
                        ctx->state = STATE_IDLE;
                    }
                }
                break;
            case STATE_CLAP_DETECTED:
                // Turn on LED
                struct gpiohandle_data data;
                data.values[0] = 1;
                if (ioctl(ctx->led_fd, GPIOHANDLE_SET_LINE_VALUES_IOCTL, &data) < 0) {
                    perror("Failed to turn on LED");
                }

                // Wait for 500ms
                usleep(CLAP_DURATION_MS * 1000);

                // Turn off LED
                data.values[0] = 0;
                if (ioctl(ctx->led_fd, GPIOHANDLE_SET_LINE_VALUES_IOCTL, &data) < 0) {
                    perror("Failed to turn off LED");
                }

                ctx->state = STATE_IDLE;
                break;
        }

        usleep(1000); // 1ms delay
    }
}

int main() {
    AppContext ctx = {
        .adc_pin = GPIO_ADC_PIN,
        .led_pin = GPIO_LED_PIN,
        .sample_count = 0,
        .sample_sum = 0,
        .state = STATE_IDLE
    };

    // Initialize GPIO
    if (init_gpio(&ctx) < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return EXIT_FAILURE;
    }

    // Set up signal handler
    signal(SIGINT, handle_sigint);

    // Start the main loop
    run_app(&ctx);

    // Cleanup on exit
    cleanup_gpio(&ctx);

    return EXIT_SUCCESS;
}

