#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/gpio.h>
#include <time.h>
#include <signal.h>
#include <errno.h>

#define GPIO_PIN 17
#define GPIO_PATH "/dev/gpiochip0"
#define LOG_FILE "distance_log.txt"
#define DISTANCE_THRESHOLD_MM 200

int gpio_fd = -1;
int running = 1;

void handle_signal(int sig) {
    running = 0;
    if (gpio_fd >= 0) {
        ioctl(gpio_fd, GPIO_UNEXPORT, GPIO_PIN);
        close(gpio_fd);
    }
    exit(EXIT_SUCCESS);
}

void log_distance(int distance_mm) {
    FILE *file = fopen(LOG_FILE, "a");
    if (!file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return;
    }

    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(file, "%s - Distance: %d mm\n", timestamp, distance_mm);
    fclose(file);
}

void read_gpio() {
    int line = GPIO_PIN;
    int value;

    if (ioctl(gpio_fd, GPIO_GET_LINE_VALUES, &value) < 0) {
        fprintf(stderr, "Failed to read GPIO line: %s\n", strerror(errno));
        return;
    }

    if (value == 0) {
        log_distance(0); // Assuming 0 means distance < 200mm
        printf("Feeder Activated\n");
    } else {
        log_distance(1); // Assuming 1 means distance >= 200mm
        printf("Feeder Idle\n");
    }
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (running) {
        gpio_fd = open(GPIO_PATH, O_RDWR);
        if (gpio_fd < 0) {
            fprintf(stderr, "Failed to open GPIO device: %s\n", strerror(errno));
            sleep(1);
            continue;
        }

        if (ioctl(gpio_fd, GPIO_GET_LINE_VALUES_IOCTL, GPIO_PIN) < 0) {
            fprintf(stderr, "Failed to get line values: %s\n", strerror(errno));
            close(gpio_fd);
            sleep(1);
            continue;
        }

        if (ioctl(gpio_fd, GPIO_GET_LINE_IOCTL, GPIO_PIN) < 0) {
            fprintf(stderr, "Failed to get line configuration: %s\n", strerror(errno));
            close(gpio_fd);
            sleep(1);
            continue;
        }

        if (ioctl(gpio_fd, GPIO_LINE_SET_FLAGS, GPIO_PIN | GPIO_LINE_FLAG_ACTIVE_LOW) < 0) {
            fprintf(stderr, "Failed to set line flags: %s\n", strerror(errno));
            close(gpio_fd);
            sleep(1);
            continue;
        }

        if (ioctl(gpio_fd, GPIO_LINE_REQUEST_ACCESS, GPIO_PIN) < 0) {
            fprintf(stderr, "Failed to request line access: %s\n", strerror(errno));
            close(gpio_fd);
            sleep(1);
            continue;
        }

        while (running) {
            read_gpio();
            sleep(1);
        }

        ioctl(gpio_fd, GPIO_LINE_RELEASE_ACCESS, GPIO_PIN);
        close(gpio_fd);
    }

    return 0;
}

