        if (gpio_fd < 0) {
            fprintf(stderr, "Failed to open GPIO device: %s\n", strerror(errno));
            sleep(1);
            continue;
        }

        if (ioctl(gpio_fd, GPIO_GET_LINE_VALUES_IOCTL, GPIO_PIN) < 0) {
            fprintf(stderr, "Failed to get line values: %s\n", strerror(errno));
            close(gpio_fd);
            sleep(1);
            continue;
        }

        if (ioctl(gpio_fd, GPIO_GET_LINE_IOCTL, GPIO_PIN) < 0) {
            fprintf(stderr, "Failed to get line configuration: %s\n", strerror(errno));
            close(gpio_fd);
            sleep(1);
            continue;
        }

        if (ioctl(gpio_fd, GPIO_LINE_SET_FLAGS, GPIO_PIN | GPIO_LINE_FLAG_ACTIVE_LOW) < 0) {
            fprintf(stderr, "Failed to set line flags: %s\n", strerror(errno));
            close(gpio_fd);
            sleep(1);
            continue;
        }

        if (ioctl(gpio_fd, GPIO_LINE_REQUEST_ACCESS, GPIO_PIN) < 0) {
            fprintf(stderr, "Failed to request line access: %s\n", strerror(errno));
            close(gpio_fd);
            sleep(1);
            continue;
        }

        while (running) {
            read_gpio();
            sleep(1);
        }

        ioctl(gpio_fd, GPIO_LINE_RELEASE_ACCESS, GPIO_PIN);
        close(gpio_fd);
    }

    return 0;
}
