int init_spi() {
    int fd = open(SPI_DEVICE, O_RDWR | O_NOCTTY | O_NDELAY);
    if (fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    struct spi_ioc_transfer spi;
    memset(&spi, 0, sizeof(spi));
    spi.speed_hz = SPI_SPEED;
    spi.mode = SPI_MODE;
    spi.bits_per_word = SPI_BITS;
    spi.delay_usecs = SPI_DELAY;

    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("Failed to set SPI speed");
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS) < 0) {
        perror("Failed to set SPI bits per word");
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("Failed to set SPI mode");
        close(fd);
        return -1;
    }

    return fd;
}

int read_adc(int spi_fd, int channel) {
    uint8_t tx[3];
    uint8_t rx[3];
    uint16_t adc_value;

    tx[0] = 1 << 7 | ((channel & 0x07) << 4) | 0x01;  // Start bit, channel, single-ended
    tx[1] = 0;
    tx[2] = 0;

    struct spi_ioc_transfer spi;
    memset(&spi, 0, sizeof(spi));
    spi.tx_buf = (unsigned long)tx;
    spi.rx_buf = (unsigned long)rx;
    spi.len = 3;
    spi.speed_hz = SPI_SPEED;
    spi.delay_usecs = SPI_DELAY;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &spi) < 0) {
        perror("SPI read failed");
        return -1;
    }

    adc_value = (rx[1] << 8) | rx[2];
    return adc_value;
}

int map_adc_to_percentage(int adc_value) {
    // ADC range: 0-1023
    // Moisture range: 0 (dry) to 1023 (wet)
    // Map to 0% (dry) to 100% (wet)
    return (adc_value * 100) / 1023;
