    int spi_fd = -1;
    int relay_line = -1;
    FILE *log_file = NULL;
    time_t last_sample_time = 0;
    int adc_value = 0;
    int moisture_percent = 0;
    PumpStatus pump_status = PUMP_OFF;

    signal(SIGINT, signal_handler);

    if ((log_file = fopen(LOG_FILE, "a")) == NULL) {
        perror("Failed to open log file");
        return 1;
    }

    if ((spi_fd = init_spi()) < 0) {
        fclose(log_file);
        return 1;
    }

    if ((relay_line = setup_gpio()) == -1) {
        fclose(log_file);
        close(spi_fd);
        return 1;
    }

    while (running) {
        time_t current_time = time(NULL);

        if (current_time - last_sample_time >= SAMPLE_INTERVAL) {
            last_sample_time = current_time;

            adc_value = read_adc(spi_fd, ADC_CHANNEL);
            if (adc_value < 0) {
                fprintf(stderr, "ADC read failed, skipping sample.\n");
