                }
            } else {
                if (pump_status == PUMP_ON) {
                    set_pump_status(relay_line, PUMP_OFF);
                    pump_status = PUMP_OFF;
                }
            }

            log_sample(log_file, current_time, moisture_percent, pump_status);
        }

        usleep(100000);  // 100ms delay to prevent CPU overuse
    }

    // Graceful shutdown
    set_pump_status(relay_line, PUMP_OFF);
    gpiod_line_put(relay_line);
    close(spi_fd);
    fclose(log_file);

