#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <linux/gpio.h>
#include <signal.h>
#include <time.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define SPI_MODE SPI_MODE_0
#define SPI_BITS 8
#define SPI_DELAY 500000  // 500 ms in microseconds

#define GPIO_CHIP 0
#define GPIO_LINE 8
#define GPIO_DIN 9
#define GPIO_DOUT 10
#define GPIO_CLK 11
#define GPIO_CS GPIO_LINE

volatile int running = 1;

typedef struct {
    int spi_fd;
    struct gpiohandle_request req;
    struct gpiohandle_data data;
    FILE *log_file;
} app_state;

void handle_signal(int sig) {
    running = 0;
}

int init_gpio(app_state *state) {
    int fd = open("/dev/gpiochip0", O_RDWR);
    if (fd < 0) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    state->req.lineoffset = GPIO_LINE;
    state->req.lines = 1;
    state->req.flags = GPIOHANDLE_REQUEST_OUTPUT;
    state->req.default_value = 1;  // CS high (inactive)

    if (ioctl(fd, GPIO_GET_LINEHANDLE_IOCTL, &state->req) < 0) {
        perror("Failed to get GPIO line handle");
        close(fd);
        return -1;
    }

    state->data.values[0] = 1;
    if (ioctl(state->req.fd, GPIOHANDLE_SET_LINE_VALUES_IOCTL, &state->data) < 0) {
        perror("Failed to set GPIO line values");
        close(state->req.fd);
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

int init_spi(app_state *state) {
    state->spi_fd = open(SPI_DEVICE, O_RDWR);
    if (state->spi_fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    int mode = SPI_MODE_0;
    if (ioctl(state->spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Failed to set SPI mode");
        close(state->spi_fd);
        return -1;
    }

    uint32_t speed = SPI_SPEED;
    if (ioctl(state->spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to set SPI speed");
        close(state->spi_fd);
        return -1;
    }

    uint32_t bits = SPI_BITS;
    if (ioctl(state->spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Failed to set SPI bits per word");
        close(state->spi_fd);
        return -1;
    }

    return 0;
}

int read_adc(app_state *state, uint8_t channel) {
    uint8_t tx[3] = {0b10000000 | (channel & 0x07), 0x00, 0x00};
    uint8_t rx[3] = {0};

    struct spi_ioc_transfer spi = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .delay_usecs = SPI_DELAY,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS
    };

    if (ioctl(state->spi_fd, SPI_IOC_MESSAGE(1), &spi) < 0) {
        perror("SPI transfer failed");
        return -1;
    }

    uint16_t adc_value = (rx[1] << 8) | rx[2];
    return adc_value;
}

void convert_adc_to_b(int adc_value, int *b) {
    // ADC range: 0-1023
    // Vref = 3.3V
    // Vout = (adc_value / 1023) * 3.3V
    // DRV5055-A1: Vout = 1.65V at B = 0, 0.65V at B = 100mT
    // Linear approximation: B = (Vout - 0.65) / (1.65 - 0.65) * 100
    // Vout = (adc_value / 1023) * 3.3
    // B = ((adc_value / 1023) * 3.3 - 0.65) / 1.0 * 100

    int vout = (adc_value * 3300) / 1023;
    int b_int = ((vout - 650) * 100) / 1000;
    *b = b_int;
}

void log_data(app_state *state, int b) {
    time_t now = time(NULL);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
    char line[64];
    snprintf(line, sizeof(line), "%ld,%d\n", (long)now, b);

    if (fprintf(state->log_file, "%s", line) < 0) {
        perror("Failed to write to log file");
    }
}

void cleanup(app_state *state) {
    if (state->log_file) {
        fclose(state->log_file);
    }

    if (state->spi_fd >= 0) {
        close(state->spi_fd);
    }

    if (state->req.fd >= 0) {
        ioctl(state->req.fd, GPIOHANDLE_GET_LINE_VALUES_IOCTL, &state->data);
        ioctl(state->req.fd, GPIOHANDLE_SET_LINE_VALUES_IOCTL, &state->data);
        close(state->req.fd);
    }
}

int main() {
    app_state state = {0};

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if (init_gpio(&state) < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    if (init_spi(&state) < 0) {
        fprintf(stderr, "Failed to initialize SPI\n");
        cleanup(&state);
        return 1;
    }

    state.log_file = fopen("magnetic_log.txt", "a");
    if (!state.log_file) {
        perror("Failed to open log file");
        cleanup(&state);
        return 1;
    }

    while (running) {
        // Set CS low
        state.data.values[0] = 0;
        if (ioctl(state->req.fd, GPIOHANDLE_SET_LINE_VALUES_IOCTL, &state->data) < 0) {
            perror("Failed to set CS low");
            continue;
        }

        int adc_value = read_adc(&state, 0);
        if (adc_value < 0) {
            fprintf(stderr, "ADC read failed, skipping sample\n");
            // Set CS high
            state.data.values[0] = 1;
            if (ioctl(state->req.fd, GPIOHANDLE_SET_LINE_VALUES_IOCTL, &state->data) < 0) {
                perror("Failed to set CS high");
            }
            continue;
        }

        // Set CS high
        state.data.values[0] = 1;
        if (ioctl(state->req.fd, GPIOHANDLE_SET_LINE_VALUES_IOCTL, &state->data) < 0) {
            perror("Failed to set CS high");
            continue;
        }

        int b;
        convert_adc_to_b(adc_value, &b);
        log_data(&state, b);

        usleep(SPI_DELAY);
    }

    cleanup(&state);
    return 0;
}

