        return -1;
    }

    struct spi_ioc_transfer spi;
    memset(&spi, 0, sizeof(spi));
    spi.speed_hz = SPI_SPEED;
    spi.mode = SPI_MODE;
    spi.bits_per_word = SPI_BITS;
    spi.delay_usecs = SPI_DELAY;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &spi) < 0) {
        perror("SPI ioctl failed");
        close(spi_fd);
        return -1;
    }

    return spi_fd;
}

int read_adc(int spi_fd, int channel) {
    uint8_t tx[ADC_READ_BYTES] = {1, (uint8_t)(channel << 4), 0};
    uint8_t rx[ADC_READ_BYTES];

    if (write(spi_fd, tx, ADC_READ_BYTES) != ADC_READ_BYTES) {
        perror("SPI write failed");
        return -1;
    }

    usleep(ADC_READ_DELAY);

    if (read(spi_fd, rx, ADC_READ_BYTES) != ADC_READ_BYTES) {
        perror("SPI read failed");
        return -1;
    }

    uint16_t adc_value = (rx[1] << 8) | rx[2];
    return adc_value;
}

