        gpiod_line_release(state.led_line);
        close(state.spi_fd);
        return EXIT_FAILURE;
    }

    state.running = 1;
    while (state.running) {
        int adc_value = read_adc(state.spi_fd, ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "ADC read failed.\n");
            break;
        }

        float field_strength = adc_to_magnetic_field(adc_value);

        if (field_strength > LED_THRESHOLD) {
            gpiod_line_set_value(state.led_line, 1);
        } else {
            gpiod_line_set_value(state.led_line, 0);
        }

        log_reading(field_strength);

        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    handle_sigint(SIGINT);
    return EXIT_SUCCESS;
