#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_SPEED 1000000
#define SPI_BITS 8
#define SPI_DELAY 0
#define CHANNEL 0
#define LOG_FILE "moisture_log.txt"
#define INTERVAL 60

typedef struct {
    int spi_fd;
    struct gpiod_line *cs_line;
} spi_context;

void handle_sigint(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    exit(EXIT_SUCCESS);
}

int init_spi() {
    int fd;
    struct spi_ioc_transfer spi;
    struct gpiod_line_config config;
    struct gpiod_line *cs_line;

    // Open SPI device
    fd = open(SPI_DEVICE, O_RDWR | O_SYNC);
    if (fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    // Set SPI mode
    if (ioctl(fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("Failed to set SPI mode");
        close(fd);
        return -1;
    }

    // Set SPI speed
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("Failed to set SPI speed");
        close(fd);
        return -1;
    }

    // Set SPI bits per word
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS) < 0) {
        perror("Failed to set SPI bits per word");
        close(fd);
        return -1;
    }

    // Set SPI delay
    if (ioctl(fd, SPI_IOC_WR_DELAY, &SPI_DELAY) < 0) {
        perror("Failed to set SPI delay");
        close(fd);
        return -1;
    }

    // Initialize CS line (GPIO 0)
    config.line_number = 0;
    config.flags = GPIOD_LINE_FLAG_ACTIVE_LOW;
    config.consumer = "soil_moisture";
    cs_line = gpiod_line_get(config);
    if (!cs_line) {
        perror("Failed to get CS line");
        close(fd);
        return -1;
    }

    if (gpiod_line_request_output(cs_line, "cs", GPIOD_LINE_REQUEST_FLAG_ACTIVE_LOW) < 0) {
        perror("Failed to request CS line");
        gpiod_line_put(cs_line);
        close(fd);
        return -1;
    }

    gpiod_line_set_value(cs_line, 1);

    spi_context context = {fd, cs_line};
    return (int)context;
}

void deinit_spi(spi_context *context) {
    if (context->cs_line) {
        gpiod_line_put(context->cs_line);
    }
    if (context->spi_fd >= 0) {
        close(context->spi_fd);
    }
}

int read_adc(spi_context *context, int channel) {
    unsigned char tx[3];
    unsigned char rx[3];
    struct spi_ioc_transfer spi;
    int ret;

    tx[0] = 1 << 7; // Start bit
    tx[1] = (channel << 4) | 0x01; // Single-ended, channel
    tx[2] = 0x00; // Dummy byte

    memset(&spi, 0, sizeof(spi));
    spi.tx_buf = (unsigned long)tx;
    spi.rx_buf = (unsigned long)rx;
    spi.len = 3;
    spi.delay_usecs = 0;
    spi.speed_hz = SPI_SPEED;
    spi.bits_per_word = SPI_BITS;

    gpiod_line_set_value(context->cs_line, 0);
    ret = ioctl(context->spi_fd, SPI_IOC_MESSAGE(1), &spi);
    gpiod_line_set_value(context->cs_line, 1);

    if (ret < 0) {
        perror("SPI read failed");
        return -1;
    }

    // Extract 10-bit value from rx[1] and rx[2]
    int value = ((rx[1] & 0x03) << 8) | rx[2];
    return value;
}

void log_data(const char *timestamp, int value) {
    FILE *file = fopen(LOG_FILE, "a");
    if (!file) {
        perror("Failed to open log file");
        return;
    }

    fprintf(file, "%s %d\n", timestamp, value);
    fclose(file);
}

void log_error(const char *timestamp) {
    FILE *file = fopen(LOG_FILE, "a");
    if (!file) {
        perror("Failed to open log file");
        return;
    }

    fprintf(file, "%s -1\n", timestamp);
    fclose(file);
}

int main() {
    spi_context spi_context;
    int spi_fd;
    int ret;
    struct sigaction sa;
    time_t now;
    struct tm *tm_info;
    char timestamp[20];

    // Initialize signal handling
    sa.sa_handler = handle_sigint;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("Failed to set signal handler");
        return EXIT_FAILURE;
    }

    // Initialize SPI
    spi_fd = init_spi();
    if (spi_fd < 0) {
        return EXIT_FAILURE;
    }

    while (1) {
        time(&now);
        tm_info = localtime(&now);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

        int value = read_adc((spi_context *)spi_fd, CHANNEL);
        if (value < 0) {
            log_error(timestamp);
        } else {
            log_data(timestamp, value);
        }

        sleep(INTERVAL);
    }

    deinit_spi((spi_context *)spi_fd);
    return EXIT_SUCCESS;
}

