    fprintf(file, "%s -1\n", timestamp);
    fclose(file);
}

int main() {
    spi_context spi_context;
    int spi_fd;
    int ret;
    struct sigaction sa;
    time_t now;
    struct tm *tm_info;
    char timestamp[20];

    // Initialize signal handling
    sa.sa_handler = handle_sigint;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
