        return EXIT_FAILURE;
    }

    // Initialize SPI
    spi_fd = init_spi();
    if (spi_fd < 0) {
        return EXIT_FAILURE;
    }

    while (1) {
        time(&now);
        tm_info = localtime(&now);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

        int value = read_adc((spi_context *)spi_fd, CHANNEL);
        if (value < 0) {
            log_error(timestamp);
        } else {
            log_data(timestamp, value);
        }

        sleep(INTERVAL);
    }

    deinit_spi((spi_context *)spi_fd);
    return EXIT_SUCCESS;
