#define SPI_BITS_PER_WORD 8
#define SPI_MAX_SPEED_HZ 1000000
#define CSV_FILE "current_log.txt"
#define SAMPLE_INTERVAL_MS 1000

typedef enum {
    INIT_OK,
    INIT_ERROR
} init_status;

typedef struct {
    int spi_fd;
    struct gpiod_line *gpio_line;
    FILE *log_file;
    int running;
} app_state;

init_status init_spi(int *fd) {
    *fd = open(SPI_DEVICE, O_RDWR | O_NOCTTY | O_NDELAY);
    if (*fd < 0) {
        perror("Failed to open SPI device");
        return INIT_ERROR;
    }

    struct spi_ioc_transfer spi;
    memset(&spi, 0, sizeof(spi));
    spi.speed_hz = SPI_MAX_SPEED_HZ;
    spi.mode = SPI_MODE;
    spi.bits_per_word = SPI_BITS_PER_WORD;

    if (ioctl(*fd, SPI_IOC_MESSAGE(1), &spi) < 0) {
        perror("Failed to set SPI parameters");
        close(*fd);
        return INIT_ERROR;
    }

    return INIT_OK;
}

init_status init_gpio(struct gpiod_line **line) {
    struct gpiod_chip *chip;
    chip = gpiod_chip_open(GPIO_PIN);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return INIT_ERROR;
    }

    *line = gpiod_line_request_output(chip, "power_enable", GPIO_PIN, 1);
    if (!*line) {
        perror("Failed to request GPIO line");
        gpiod_chip_close(chip);
        return INIT_ERROR;
    }

    return INIT_OK;
}

init_status init_log_file(FILE **file) {
    *file = fopen(CSV_FILE, "a");
    if (!*file) {
        perror("Failed to open log file");
        return INIT_ERROR;
    }

    fprintf(*file, "timestamp,current_A\n");
    fflush(*file);
    return INIT_OK;
}

void handle_signal(int sig) {
    app_state *state = (app_state *)malloc(sizeof(app_state));
    if (state) {
        state->running = 0;
        free(state);
    }
}

void cleanup_app(app_state *state) {
    if (state->gpio_line) {
        gpiod_line_release(state->gpio_line);
    }

    if (state->spi_fd >= 0) {
        close(state->spi_fd);
    }

    if (state->log_file) {
        fclose(state->log_file);
    }
}

void read_adc(int spi_fd, int channel, int *adc_value) {
    unsigned char tx[3];
    unsigned char rx[3];
    tx[0] = 1 << 7 | ((channel & 0x07) << 4);
    tx[1] = 0;
    tx[2] = 0;

    if (write(spi_fd, tx, 3) != 3) {
        perror("SPI write failed");
        *adc_value = -1;
        return;
    }

    if (read(spi_fd, rx, 3) != 3) {
        perror("SPI read failed");
        *adc_value = -1;
        return;
    }

    *adc_value = (rx[1] << 8) | rx[2];
}

double adc_to_current(int adc_value) {
    if (adc_value < 0) {
        return -1.0;
    }

    double voltage = (adc_value * 5.0) / 1023.0;
    return voltage / 0.1; // 100 mV/A
}

int main() {
    app_state state = {0};

    if (init_spi(&state.spi_fd) != INIT_OK) {
        fprintf(stderr, "SPI initialization failed\n");
        return 1;
    }

    if (init_gpio(&state.gpio_line) != INIT_OK) {
        fprintf(stderr, "GPIO initialization failed\n");
        cleanup_app(&state);
        return 1;
    }

    if (init_log_file(&state.log_file) != INIT_OK) {
        fprintf(stderr, "Log file initialization failed\n");
        cleanup_app(&state);
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    state.running = 1;

    while (state.running) {
        gpiod_line_set_value(state.gpio_line, 1);

        int adc_value;
        read_adc(state.spi_fd, ADC_CHANNEL, &adc_value);

        if (adc_value < 0) {
            fprintf(stderr, "ADC communication failed\n");
            gpiod_line_set_value(state.gpio_line, 0);
            usleep(1000000);
            continue;
        }

        double current = adc_to_current(adc_value);
        if (current < 0) {
            fprintf(stderr, "Invalid ADC value\n");
            gpiod_line_set_value(state.gpio_line, 0);
            usleep(1000000);
            continue;
        }

        struct timeval tv;
        gettimeofday(&tv, NULL);
        long timestamp = tv.tv_sec * 1000 + tv.tv_usec / 1000;

        fprintf(state.log_file, "%ld,%f\n", timestamp, current);
        fflush(state.log_file);

        gpiod_line_set_value(state.gpio_line, 0);
        usleep(1000000);
    }

    cleanup_app(&state);
    return 0;
}

