void gpio_init(GpioHandle *gpio, int pin) {
    gpio->gpio_pin = pin;
    gpio->fd = open("/dev/gpiochip0", O_RDWR);
    if (gpio->fd < 0) {
        perror("Failed to open GPIO device");
        exit(EXIT_FAILURE);
    }

    if (ioctl(gpio->fd, GPIO_GET_LINEHANDLE_IOCTL, &gpio->gpio_pin) < 0) {
        perror("Failed to get line handle");
        close(gpio->fd);
        exit(EXIT_FAILURE);
    }
}

void gpio_set_direction(GpioHandle *gpio, int direction) {
    struct gpio_line_request req = {
        .lineoffset = gpio->gpio_pin,
        .flags = GPIO_LINE_FLAG_BIAS_PULL_UP
    };

    if (ioctl(gpio->fd, GPIO_GET_LINEHANDLE_IOCTL, &req) < 0) {
        perror("Failed to set line handle");
        close(gpio->fd);
        exit(EXIT_FAILURE);
    }

    struct gpio_line_config config = {
        .lineoffset = gpio->gpio_pin,
        .flags = GPIO_LINE_FLAG_BIAS_PULL_UP
    };

    if (ioctl(gpio->fd, GPIO_LINE_CONFIG_IOCTL, &config) < 0) {
        perror("Failed to configure line");
        close(gpio->fd);
        exit(EXIT_FAILURE);
    }

    struct gpio_line_request req2 = {
        .lineoffset = gpio->gpio_pin,
        .flags = GPIO_LINE_FLAG_OUTPUT
    };

    if (ioctl(gpio->fd, GPIO_GET_LINEHANDLE_IOCTL, &req2) < 0) {
        perror("Failed to get line handle again");
        close(gpio->fd);
        exit(EXIT_FAILURE);
    }

    struct gpio_line_value value = { .value = direction };
    if (ioctl(gpio->fd, GPIO_LINE_SET_VALUE_IOCTL, &value) < 0) {
        perror("Failed to set line value");
        close(gpio->fd);
        exit(EXIT_FAILURE);
    }
}

void gpio_free(GpioHandle *gpio) {
    if (gpio->fd >= 0) {
        close(gpio->fd);
    }
}

