            usleep(DEBOUNCE_DELAY_MS * 1000);
        }

        if (sensor1_state < 0 || sensor2_state < 0) {
            fprintf(stderr, "Debounce failed\n");
            break;
        }

        if (sensor1_state == 0) {
            printf("1");
        } else {
            printf("0");
        }

        if (sensor2_state == 0) {
            printf(" 1");
        } else {
            printf(" 0");
        }

        if (sensor1_state == 0 && sensor2_state == 0) {
            printf(" | ALERT: Both sensors detect object\n");
        } else {
            printf("\n");
        }

        usleep(LOG_INTERVAL_MS * 1000);
    }

    gpio_free(&gpio1);
    gpio_free(&gpio2);
    return 0;
}

