volatile sig_atomic_t running = 1;

typedef struct {
    int channel;
    int baud;
} spi_config_t;

int spi_setup(spi_config_t config) {
    int fd;
    struct spi_ioc_transfer transfer;
    int ret;

    fd = open("/dev/spidev0.0", O_RDWR);
    if (fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_MODE, &SPI_MODE_0) < 0) {
        perror("Failed to set SPI mode");
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &8) < 0) {
        perror("Failed to set bits per word");
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &config.baud) < 0) {
        perror("Failed to set SPI speed");
        close(fd);
        return -1;
    }

    transfer.tx_buf = (unsigned long)malloc(1);
    transfer.rx_buf = (unsigned long)malloc(1);
    transfer.len = 1;
    transfer.delay_usecs = 0;
    transfer.speed_hz = config.baud;
    transfer.bits_per_word = 8;

    ret = ioctl(fd, SPI_IOC_MESSAGE(1), &transfer);
    if (ret < 0) {
        perror("SPI transfer failed");
        free(transfer.tx_buf);
        free(transfer.rx_buf);
        close(fd);
        return -1;
    }

    free(transfer.tx_buf);
    free(transfer.rx_buf);

    return fd;
}

int read_mcp3008(int channel) {
    int fd;
    struct spi_ioc_transfer transfer;
    unsigned char tx[3];
    unsigned char rx[3];
    int ret;

    fd = open("/dev/spidev0.0", O_RDWR);
    if (fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_MODE, &SPI_MODE_0) < 0) {
        perror("Failed to set SPI mode");
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &8) < 0) {
        perror("Failed to set bits per word");
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_BAUD) < 0) {
        perror("Failed to set SPI speed");
        close(fd);
        return -1;
    }

    tx[0] = 1 << 7 | (channel & 0x07) << 4 | 0x01;
    tx[1] = 0x00;
    tx[2] = 0x00;

    transfer.tx_buf = (unsigned long)tx;
    transfer.rx_buf = (unsigned long)rx;
