#define LOG_DIR "/home/pi/security_cam"
#define MAX_FILENAME_LEN 256

volatile int running = 1;
int gpio_fd = -1;
struct gpiod_line *pir_line = NULL;

void log_message(const char *fmt, ...) {
    va_list args;
    va_start(args, fmt);
    vsyslog(LOG_INFO, fmt, args);
    va_end(args);
}

void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        log_message("Received shutdown signal. Stopping motion detection.");
        running = 0;
    }
}

void init_gpio() {
    struct gpiod_chip *chip;
    struct gpiod_line_config config = GPIOD_LINE_CONFIG_DEFAULTS;

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        log_message("Failed to open GPIO chip.");
        exit(EXIT_FAILURE);
    }

    config.consumer = "pir_sensor";
    config.direction = GPIOD_LINE_DIRECTION_INPUT;
    config.flags = GPIOD_LINE_FLAG_ACTIVE_LOW | GPIOD_LINE_FLAG_BIAS_PULL_DOWN;

    pir_line = gpiod_line_request(chip, GPIO_PIN, &config);
    if (!pir_line) {
        log_message("Failed to request GPIO line.");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    gpio_fd = gpiod_line_get_fd(pir_line);
    if (gpio_fd < 0) {
        log_message("Failed to get GPIO file descriptor.");
        gpiod_line_release(pir_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    log_message("GPIO initialized successfully.");
}

void cleanup_gpio() {
    if (pir_line) {
        gpiod_line_release(pir_line);
    }
    if (gpio_fd >= 0) {
        close(gpio_fd);
    }
    log_message("GPIO resources released.");
}

void ensure_directory_exists(const char *path) {
    struct stat st;
    if (stat(path, &st) == 0) {
        if (!S_ISDIR(st.st_mode)) {
            log_message("Target directory is not a directory.");
            exit(EXIT_FAILURE);
        }
        return;
    }

    if (mkdir(path, 0755) != 0) {
        log_message("Failed to create directory: %s", path);
        exit(EXIT_FAILURE);
    }
    log_message("Directory created: %s", path);
}

void capture_image(const char *filename) {
    pid_t pid;
    int status;

    pid = fork();
    if (pid < 0) {
        log_message("Failed to fork process for capture.");
        return;
    } else if (pid == 0) {
        char *const args[] = {
            "libcamera-still",
            "--output", filename,
            "--timeout", "5000",
            "--nopreview",
            NULL
        };

        execvp(args[0], args);
        log_message("Failed to execute libcamera-still.");
        exit(EXIT_FAILURE);
    } else {
        waitpid(pid, &status, 0);
        if (WIFEXITED(status) && WEXITSTATUS(status) == 0) {
            log_message("Image captured successfully: %s", filename);
        } else {
            log_message("Image capture failed: %s", filename);
        }
    }
}

int main() {
    struct timeval last_change_time;
    int last_state = 0;
    int motion_detected = 0;
    char filename[MAX_FILENAME_LEN];

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    openlog("security_cam", LOG_PID | LOG_CONS, LOG_USER);

    init_gpio();

    ensure_directory_exists(LOG_DIR);

    gettimeofday(&last_change_time, NULL);

    log_message("Motion detection started.");

    while (running) {
        usleep(50000); // 50 ms

        int current_state = gpiod_line_get_value(pir_line);
        gettimeofday(&last_change_time, NULL);

        if (current_state != last_state) {
            log_message("State changed: %d", current_state);
            last_state = current_state;
            usleep(200000); // 200 ms debounce delay
        }

        if (current_state != last_state) {
            log_message("State confirmed: %d", current_state);
            motion_detected = 1;
        }

        if (motion_detected) {
            struct timeval now;
            gettimeofday(&now, NULL);
            long seconds = now.tv_sec;
            long microseconds = now.tv_usec;
            char timestamp[30];
            snprintf(timestamp, sizeof(timestamp), "%ld.%06ld", seconds, microseconds);

            snprintf(filename, MAX_FILENAME_LEN, "%s/%s_%s.jpg", LOG_DIR, "motion", timestamp);
            capture_image(filename);
            motion_detected = 0;
        }
    }

    cleanup_gpio();
    closelog();

    log_message("Motion detection stopped.");
    return 0;
}

