#define DEFAULT_DEVICE "/dev/video0"
#define BUFFER_COUNT 1
#define FRAME_WIDTH 640
#define FRAME_HEIGHT 480
#define PGM_HEADER "P5\n# Created by Arducam CSI Grayscale Capture\n%d %d\n255\n"

typedef struct {
    int fd;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;
    void *mapped;
    int buffer_index;
    int frame_count;
    int running;
} CameraContext;

void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        printf("Received signal, stopping capture...\n");
        exit(EXIT_SUCCESS);
    }
}

void init_camera(CameraContext *ctx, const char *device) {
    ctx->fd = open(device, O_RDWR | O_NONBLOCK, 0);
    if (ctx->fd < 0) {
        fprintf(stderr, "Failed to open device %s: %s\n", device, strerror(errno));
        exit(EXIT_FAILURE);
    }

    // Set format to grayscale 8-bit
    memset(&ctx->fmt, 0, sizeof(ctx->fmt));
    ctx->fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    ctx->fmt.fmt.pix.width = FRAME_WIDTH;
    ctx->fmt.fmt.pix.height = FRAME_HEIGHT;
    ctx->fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_GREY;
    ctx->fmt.fmt.pix.field = V4L2_FIELD_NONE;
    ctx->fmt.fmt.pix.bytesperline = FRAME_WIDTH;
    ctx->fmt.fmt.pix.sizeimage = FRAME_WIDTH * FRAME_HEIGHT;

    if (ioctl(ctx->fd, VIDIOC_S_FMT, &ctx->fmt) < 0) {
        fprintf(stderr, "Failed to set format: %s\n", strerror(errno));
        close(ctx->fd);
        exit(EXIT_FAILURE);
    }

    // Request buffer
    memset(&ctx->req, 0, sizeof(ctx->req));
    ctx->req.count = BUFFER_COUNT;
    ctx->req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    ctx->req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(ctx->fd, VIDIOC_REQBUFS, &ctx->req) < 0) {
        fprintf(stderr, "Failed to request buffers: %s\n", strerror(errno));
        close(ctx->fd);
        exit(EXIT_FAILURE);
    }

    // Map buffer
    ctx->buffer_index = 0;
    memset(&ctx->buf, 0, sizeof(ctx->buf));
    ctx->buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    ctx->buf.memory = V4L2_MEMORY_MMAP;
    ctx->buf.index = ctx->buffer_index;

    if (ioctl(ctx->fd, VIDIOC_QUERYBUF, &ctx->buf) < 0) {
        fprintf(stderr, "Failed to query buffer: %s\n", strerror(errno));
        close(ctx->fd);
        exit(EXIT_FAILURE);
    }

    ctx->mapped = mmap(NULL, ctx->buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, ctx->fd, ctx->buf.m.offset);
    if (ctx->mapped == MAP_FAILED) {
        fprintf(stderr, "Failed to map buffer: %s\n", strerror(errno));
        close(ctx->fd);
        exit(EXIT_FAILURE);
    }

    // Queue buffer
    if (ioctl(ctx->fd, VIDIOC_QBUF, &ctx->buf) < 0) {
        fprintf(stderr, "Failed to queue buffer: %s\n", strerror(errno));
        munmap(ctx->mapped, ctx->buf.length);
        close(ctx->fd);
        exit(EXIT_FAILURE);
    }

    // Start streaming
    if (ioctl(ctx->fd, VIDIOC_STREAMON, &ctx->fmt.type) < 0) {
        fprintf(stderr, "Failed to start streaming: %s\n", strerror(errno));
        munmap(ctx->mapped, ctx->buf.length);
        close(ctx->fd);
        exit(EXIT_FAILURE);
    }

    ctx->running = 1;
    ctx->frame_count = 0;
}

void save_frame(CameraContext *ctx) {
    char filename[256];
    snprintf(filename, sizeof(filename), "image_%04d.pgm", ctx->frame_count++);
    FILE *fp = fopen(filename, "wb");
    if (!fp) {
        fprintf(stderr, "Failed to open file %s: %s\n", filename, strerror(errno));
        return;
    }

    // Write PGM header
    fprintf(fp, PGM_HEADER, FRAME_WIDTH, FRAME_HEIGHT);

    // Write image data
    fwrite(ctx->mapped, 1, FRAME_WIDTH * FRAME_HEIGHT, fp);

    fclose(fp);
}

void cleanup_camera(CameraContext *ctx) {
    if (ctx->running) {
        ioctl(ctx->fd, VIDIOC_STREAMOFF, &ctx->fmt.type);
    }

    if (ctx->mapped) {
        munmap(ctx->mapped, ctx->buf.length);
    }

    if (ctx->fd >= 0) {
        close(ctx->fd);
    }
}

int main(int argc, char *argv[]) {
    const char *device = DEFAULT_DEVICE;
    if (argc > 1) {
        device = argv[1];
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    CameraContext ctx;
    init_camera(&ctx, device);

    fd_set read_fds;
    struct timeval timeout;
    int ret;

    while (ctx.running) {
        FD_ZERO(&read_fds);
        FD_SET(ctx.fd, &read_fds);

        timeout.tv_sec = 2;
        timeout.tv_usec = 0;

        ret = select(ctx.fd + 1, &read_fds, NULL, NULL, &timeout);
        if (ret < 0) {
            fprintf(stderr, "select() failed: %s\n", strerror(errno));
            break;
        } else if (ret == 0) {
            fprintf(stderr, "Timeout, no frame available.\n");
            continue;
        }

        // Dequeue buffer
        if (ioctl(ctx.fd, VIDIOC_DQBUF, &ctx->buf) < 0) {
            if (errno == EAGAIN) {
                fprintf(stderr, "EAGAIN, no buffer available.\n");
                continue;
            } else {
                fprintf(stderr, "Failed to dequeue buffer: %s\n", strerror(errno));
                break;
            }
        }

        save_frame(&ctx);

        // Requeue buffer
        if (ioctl(ctx.fd, VIDIOC_QBUF, &ctx->buf) < 0) {
            fprintf(stderr, "Failed to requeue buffer: %s\n", strerror(errno));
            break;
        }
    }

    cleanup_camera(&ctx);
    return 0;
}
