#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/videodev2.h>
#include <sys/mman.h>
#include <arpa/inet.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <signal.h>
#include <errno.h>
#include <stdint.h>

#define MAX_DGRAM_SIZE 65000
#define NUM_BUFFERS 4
#define FRAME_WIDTH 640
#define FRAME_HEIGHT 480
#define FRAME_SIZE (FRAME_WIDTH * FRAME_HEIGHT * 2) // YUYV format

typedef struct {
    uint32_t frame_index;
    uint32_t fragment_index;
    uint32_t total_fragments;
    uint32_t payload_size;
} Header;

volatile sig_atomic_t running = 1;

void handle_signal(int sig) {
    running = 0;
}

int open_video_device(const char *device_path) {
    int fd = open(device_path, O_RDWR | O_NONBLOCK, 0);
    if (fd < 0) {
        perror("Failed to open video device");
        return -1;
    }
    return fd;
}

int configure_video_format(int fd, int width, int height, int pixelformat) {
    struct v4l2_format fmt = {0};
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = width;
    fmt.fmt.pix.height = height;
    fmt.fmt.pix.pixelformat = pixelformat;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("Failed to set video format");
        return -1;
    }
    return 0;
}

int request_buffers(int fd, int num_buffers) {
    struct v4l2_requestbuffers req = {0};
    req.count = num_buffers;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("Failed to request buffers");
        return -1;
    }
    return 0;
}

void* map_buffer(int fd, struct v4l2_buffer *buf) {
    void *ptr = mmap(NULL, buf->length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf->m.offset);
    if (ptr == MAP_FAILED) {
        perror("Failed to map buffer");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

int queue_buffer(int fd, struct v4l2_buffer *buf) {
    if (ioctl(fd, VIDIOC_QBUF, buf) < 0) {
        perror("Failed to queue buffer");
        return -1;
    }
    return 0;
}

int dequeue_buffer(int fd, struct v4l2_buffer *buf) {
    if (ioctl(fd, VIDIOC_DQBUF, buf) < 0) {
        perror("Failed to dequeue buffer");
        return -1;
    }
    return 0;
}

int start_streaming(int fd) {
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        perror("Failed to start streaming");
        return -1;
    }
    return 0;
}

int stop_streaming(int fd) {
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMOFF, &type) < 0) {
        perror("Failed to stop streaming");
        return -1;
    }
    return 0;
}

int create_udp_socket(const char *target_ip, int target_port) {
    int sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sockfd < 0) {
        perror("Failed to create socket");
        return -1;
    }

    struct sockaddr_in server_addr;
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(target_port);
    if (inet_pton(AF_INET, target_ip, &server_addr.sin_addr) <= 0) {
        perror("Invalid address/Address family for target IP");
        close(sockfd);
        return -1;
    }

    return sockfd;
}

void send_udp_packet(int sockfd, const void *data, size_t data_len, const struct sockaddr *dest_addr, socklen_t dest_len) {
    if (sendto(sockfd, data, data_len, 0, dest_addr, dest_len) < 0) {
        perror("Failed to send UDP packet");
    }
}

void cleanup(int fd, int sockfd, void **buffers, struct v4l2_buffer *bufs) {
    for (int i = 0; i < NUM_BUFFERS; i++) {
        munmap(buffers[i], bufs[i].length);
    }
    close(fd);
    close(sockfd);
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <target_ip> <target_port>\n", argv[0]);
        exit(EXIT_FAILURE);
    }

    const char *target_ip = argv[1];
    int target_port = atoi(argv[2]);

    int fd = open_video_device("/dev/video0");
    if (fd < 0) {
        exit(EXIT_FAILURE);
    }

    if (configure_video_format(fd, FRAME_WIDTH, FRAME_HEIGHT, V4L2_PIX_FMT_YUYV) < 0) {
        close(fd);
        exit(EXIT_FAILURE);
    }

    if (request_buffers(fd, NUM_BUFFERS) < 0) {
        close(fd);
        exit(EXIT_FAILURE);
    }

    struct v4l2_buffer bufs[NUM_BUFFERS];
    void *buffers[NUM_BUFFERS];

    for (int i = 0; i < NUM_BUFFERS; i++) {
        bufs[i].type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        bufs[i].memory = V4L2_MEMORY_MMAP;
        bufs[i].index = i;

        if (ioctl(fd, VIDIOC_QUERYBUF, &bufs[i]) < 0) {
            perror("Failed to query buffer");
            cleanup(fd, -1, buffers, bufs);
            exit(EXIT_FAILURE);
        }

        buffers[i] = map_buffer(fd, &bufs[i]);
        if (queue_buffer(fd, &bufs[i]) < 0) {
            cleanup(fd, -1, buffers, bufs);
            exit(EXIT_FAILURE);
        }
    }

    if (start_streaming(fd) < 0) {
        cleanup(fd, -1, buffers, bufs);
        exit(EXIT_FAILURE);
    }

    int sockfd = create_udp_socket(target_ip, target_port);
    if (sockfd < 0) {
        cleanup(fd, -1, buffers, bufs);
        exit(EXIT_FAILURE);
    }

    struct sockaddr_in dest_addr;
    memset(&dest_addr, 0, sizeof(dest_addr));
    dest_addr.sin_family = AF_INET;
    dest_addr.sin_port = htons(target_port);
    if (inet_pton(AF_INET, target_ip, &dest_addr.sin_addr) <= 0) {
        perror("Invalid address/Address family for target IP");
        cleanup(fd, sockfd, buffers, bufs);
        exit(EXIT_FAILURE);
    }

    uint32_t frame_index = 0;
    while (running) {
