void handle_signal(int sig) {
    // Signal handler to stop streaming and clean up
    if (sig == SIGINT || sig == SIGTERM) {
        printf("Signal received, stopping...\n");
        exit(EXIT_SUCCESS);
    }
}

void cleanup(CameraContext *ctx) {
    if (ctx->file) {
        fclose(ctx->file);
    }

    if (ctx->fd >= 0) {
        // Unmap buffers
        for (int i = 0; i < NUM_BUFFERS; i++) {
            if (ctx->buffers[i]) {
                munmap(ctx->buffers[i], ctx->fmt.fmt.pix.sizeimage);
            }
        }

        // Free buffer array
        free(ctx->buffers);

        // Stop streaming
        ioctl(ctx->fd, VIDIOC_STREAMOFF, &ctx->fmt.fmt.pix.pixelformat);

        // Close device
        close(ctx->fd);
    }
}

