    ctx.fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    ctx.fmt.fmt.pix.width = WIDTH;
    ctx.fmt.fmt.pix.height = HEIGHT;
    ctx.fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_MJPEG;
    ctx.fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (ioctl(ctx.fd, VIDIOC_S_FMT, &ctx.fmt) < 0) {
        perror("Failed to set pixel format");
        cleanup(&ctx);
        return EXIT_FAILURE;
    }

    // Request buffers
    ctx.req.count = NUM_BUFFERS;
    ctx.req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    ctx.req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(ctx.fd, VIDIOC_REQBUFS, &ctx.req) < 0) {
        perror("Failed to request buffers");
        cleanup(&ctx);
        return EXIT_FAILURE;
    }

    // Map buffers
    ctx.buffers = calloc(NUM_BUFFERS, sizeof(void *));
    if (!ctx.buffers) {
        perror("Failed to allocate buffer array");
        cleanup(&ctx);
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_BUFFERS; i++) {
        struct v4l2_buffer buf;
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(ctx.fd, VIDIOC_QUERYBUF, &buf) < 0) {
            perror("Failed to query buffer");
            cleanup(&ctx);
            return EXIT_FAILURE;
        }

        ctx.buffers[i] = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, ctx.fd, buf.m.offset);
        if (ctx.buffers[i] == MAP_FAILED) {
            perror("Failed to mmap buffer");
            cleanup(&ctx);
            return EXIT_FAILURE;
        }
    }

    // Queue buffers
    for (int i = 0; i < NUM_BUFFERS; i++) {
        struct v4l2_buffer buf;
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(ctx.fd, VIDIOC_QBUF, &buf) < 0) {
            perror("Failed to queue buffer");
            cleanup(&ctx);
            return EXIT_FAILURE;
        }
    }

    // Start streaming
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(ctx.fd, VIDIOC_STREAMON, &type) < 0) {
        perror("Failed to start streaming");
        cleanup(&ctx);
        return EXIT_FAILURE;
    }

    // Open output file
    ctx.file = fopen(FILE_NAME, "wb");
    if (!ctx.file) {
        perror("Failed to open output file");
        cleanup(&ctx);
        return EXIT_FAILURE;
    }

    // Dequeue a single frame
    if (ioctl(ctx.fd, VIDIOC_DQBUF, &ctx.buf) < 0) {
        perror("Failed to dequeue buffer");
        cleanup(&ctx);
        return EXIT_FAILURE;
    }

    if (ctx.buf.bytesused <= 0) {
        fprintf(stderr, "No data in buffer\n");
        cleanup(&ctx);
        return EXIT_FAILURE;
    }

    // Write raw MJPEG data to file
    if (fwrite(ctx.buffers[ctx.buf.index], 1, ctx.buf.bytesused, ctx.file) != ctx.buf.bytesused) {
        perror("Failed to write image data");
        cleanup(&ctx);
        return EXIT_FAILURE;
    }

    // Requeue the buffer
    if (ioctl(ctx.fd, VIDIOC_QBUF, &ctx.buf) < 0) {
        perror("Failed to requeue buffer");
        cleanup(&ctx);
        return EXIT_FAILURE;
    }

    // Clean up
    cleanup(&ctx);

    return EXIT_SUCCESS;
}

