        .duty_cycle = duty,
        .polarity = PWM_POLARITY_NORMAL
    };

    if (ioctl(fd, PWM_IOCTL_SET_CONFIG, &config) < 0) {
        perror("Failed to set PWM config");
        close(fd);
        return -1;
    }

    if (ioctl(fd, PWM_IOCTL_SET_PIN, gpio) < 0) {
