#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/select.h>
#include <linux/videodev2.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <jpeglib.h>
#include <math.h>

#define DEVICE "/dev/video0"
#define WIDTH 640
#define HEIGHT 480
#define NUM_BUFFERS 4
#define TIMEOUT 2

typedef struct {
    int fd;
    struct v4l2_buffer buf;
    void *mapped;
    struct v4l2_requestbuffers req;
    struct v4l2_format fmt;
} VideoContext;

void error(const char *msg) {
    perror(msg);
    exit(EXIT_FAILURE);
}

void cleanup(VideoContext *ctx) {
    if (ctx->mapped) {
        munmap(ctx->mapped, ctx->fmt.fmt.pix.sizeimage);
    }
    if (ctx->fd >= 0) {
        close(ctx->fd);
    }
    free(ctx);
}

void handle_sigint(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    exit(EXIT_FAILURE);
}

void convert_yuyv_to_rgb(unsigned char *yuyv, unsigned char *rgb, int width, int height) {
    for (int y = 0; y < height; y++) {
        for (int x = 0; x < width; x += 2) {
            unsigned char y0 = yuyv[(y * width + x) * 2];
            unsigned char u = yuyv[(y * width + x) * 2 + 1];
            unsigned char y1 = yuyv[(y * width + x + 1) * 2];
            unsigned char v = yuyv[(y * width + x + 1) * 2 + 1];

            // Convert YUV to RGB for both pixels
            for (int i = 0; i < 2; i++) {
                int x_pixel = x + i;
                int idx = y * width * 3 + x_pixel * 3;

                int r, g, b;

                if (i == 0) {
                    r = (int)(1.164 * (y0 - 16) + 1.596 * (u - 128));
                    g = (int)(1.164 * (y0 - 16) - 0.813 * (v - 128) - 0.391 * (u - 128));
                    b = (int)(1.164 * (y0 - 16) + 1.596 * (v - 128));
                } else {
                    r = (int)(1.164 * (y1 - 16) + 1.596 * (u - 128));
                    g = (int)(1.164 * (y1 - 16) - 0.813 * (v - 128) - 0.391 * (u - 128));
                    b = (int)(1.164 * (y1 - 16) + 1.596 * (v - 128));
                }

                r = (r < 0) ? 0 : (r > 255) ? 255 : r;
                g = (g < 0) ? 0 : (g > 255) ? 255 : g;
                b = (b < 0) ? 0 : (b > 255) ? 255 : b;

                rgb[idx] = b;
                rgb[idx + 1] = g;
                rgb[idx + 2] = r;
            }
        }
    }
}

void apply_blur(unsigned char *rgb, int width, int height) {
    int size = width * height;
    unsigned char *temp = (unsigned char *)malloc(size * 3);
    if (!temp) error("Memory allocation failed");

    for (int y = 0; y < height; y++) {
        for (int x = 0; x < width; x++) {
            int r = 0, g = 0, b = 0;
            int count = 0;

            for (int dy = -1; dy <= 1; dy++) {
                for (int dx = -1; dx <= 1; dx++) {
                    int nx = x + dx;
                    int ny = y + dy;

                    if (nx >= 0 && nx < width && ny >= 0 && ny < height) {
                        r += rgb[(ny * width + nx) * 3];
                        g += rgb[(ny * width + nx) * 3 + 1];
                        b += rgb[(ny * width + nx) * 3 + 2];
                        count++;
                    }
                }
            }

            r /= count;
            g /= count;
            b /= count;

            temp[(y * width + x) * 3] = b;
            temp[(y * width + x) * 3 + 1] = g;
            temp[(y * width + x) * 3 + 2] = r;
        }
    }

    memcpy(rgb, temp, size * 3);
    free(temp);
}

void save_jpeg(const unsigned char *rgb, int width, int height, const char *filename) {
    FILE *outfile = fopen(filename, "wb");
    if (!outfile) error("Failed to open output file");

    struct jpeg_compress_struct cinfo;
    struct jpeg_error_mgr jerr;
    JSAMPROW row_pointer[1];
    int row_stride;

    cinfo.err = jpeg_std_error(&jerr);
    jpeg_create_compress(&cinfo);
    jpeg_stdio_dest(&cinfo, outfile);

    cinfo.image_width = width;
    cinfo.image_height = height;
    cinfo.input_components = 3;
    cinfo.in_color_space = JCS_RGB;

    jpeg_set_defaults(&cinfo);
    jpeg_set_quality(&cinfo, 75, TRUE);

    jpeg_start_compress(&cinfo, TRUE);

    row_stride = width * 3;

    while (cinfo.next_scanline < cinfo.image_height) {
        row_pointer[0] = (JSAMPROW)rgb + cinfo.next_scanline * row_stride;
        jpeg_write_scanlines(&cinfo, row_pointer, 1);
    }

    jpeg_finish_compress(&cinfo);
    fclose(outfile);
    jpeg_destroy_compress(&cinfo);
}

int main() {
    VideoContext *ctx = malloc(sizeof(VideoContext));
    if (!ctx) error("Memory allocation failed");

    ctx->fd = open(DEVICE, O_RDWR | O_NONBLOCK, 0);
    if (ctx->fd < 0) error("Failed to open video device");

    // Request buffers
    ctx->req.count = NUM_BUFFERS;
    ctx->req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    ctx->req.memory = V4L2_MEMORY_MMAP;
    if (ioctl(ctx->fd, VIDIOC_REQBUFS, &ctx->req) < 0) error("Failed to request buffers");

    // Set format
    ctx->fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    ctx->fmt.fmt.pix.width = WIDTH;
    ctx->fmt.fmt.pix.height = HEIGHT;
    ctx->fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    ctx->fmt.fmt.pix.field = V4L2_FIELD_NONE;
    if (ioctl(ctx->fd, VIDIOC_S_FMT, &ctx->fmt) < 0) error("Failed to set format");

    // Map buffers
    ctx->mapped = mmap(NULL, ctx->fmt.fmt.pix.sizeimage, PROT_READ | PROT_WRITE, MAP_SHARED, ctx->fd, 0);
    if (ctx->mapped == MAP_FAILED) error("Failed to map buffer");

    // Queue buffers
    for (int i = 0; i < NUM_BUFFERS; i++) {
        ctx->buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        ctx->buf.memory = V4L2_MEMORY_MMAP;
        ctx->buf.index = i;
        if (ioctl(ctx->fd, VIDIOC_QBUF, &ctx->buf) < 0) error("Failed to queue buffer");
    }

    // Start streaming
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(ctx->fd, VIDIOC_STREAMON, &type) < 0) error("Failed to start streaming");

    fd_set fds;
    struct timeval tv;
    FD_ZERO(&fds);
    FD_SET(ctx->fd, &fds);
    tv.tv_sec = TIMEOUT;
    tv.tv_usec = 0;

    int ret = select(ctx->fd + 1, &fds, NULL, NULL, &tv);
    if (ret < 0) error("Select failed");
    if (ret == 0) {
        fprintf(stderr, "Timeout waiting for frame\n");
        cleanup(ctx);
        return EXIT_FAILURE;
    }

    // Dequeue buffer
    if (ioctl(ctx->fd, VIDIOC_DQBUF, &ctx->buf) < 0) error("Failed to dequeue buffer");

    // Convert YUYV to RGB
    unsigned char *rgb = malloc(WIDTH * HEIGHT * 3);
    if (!rgb) error("Memory allocation failed");
    convert_yuyv_to_rgb(ctx->mapped + ctx->buf.m.offset, rgb, WIDTH, HEIGHT);

    // Apply blur
    apply_blur(rgb, WIDTH, HEIGHT);

    // Generate filename
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char filename[100];
    strftime(filename, sizeof(filename), "capture_%Y%m%d_%H%M%S.jpg", tm_info);

    // Save as JPEG
    save_jpeg(rgb, WIDTH, HEIGHT, filename);

    // Stop streaming
    if (ioctl(ctx->fd, VIDIOC_STREAMOFF, &type) < 0) error("Failed to stop streaming");

    // Cleanup
    cleanup(ctx);
    free(rgb);

    printf("Capture saved as %s\n", filename);
    return EXIT_SUCCESS;
}

