int main() {
    int fd;
    struct v4l2_capability cap;
    struct v4l2_frmsizeenum frmsize;
    struct v4l2_frmivalenum frmival;
    struct v4l2_control ctrl;
    int ret;

    // Check if device exists
    if (access(DEVICE_PATH, F_OK) != 0) {
        fprintf(stderr, "Error: Device %s does not exist.\n", DEVICE_PATH);
        return 1;
    }

    // Open device
    fd = open(DEVICE_PATH, O_RDWR | O_NONBLOCK, 0);
    if (fd < 0) {
        perror("Error opening device");
        return 1;
    }

    // Query device capabilities
    ret = ioctl(fd, VIDIOC_QUERYCAP, &cap);
    if (ret < 0) {
        perror("Error querying device capabilities");
        close(fd);
        return 1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture.\n");
        close(fd);
        return 1;
    }

    printf("Camera Device: %s\n", DEVICE_PATH);
    printf("Driver: %s\n", cap.driver);
    printf("Card: %s\n", cap.card);
    printf("Bus Info: %s\n", cap.bus_info);
    printf("Capabilities: ");
    if (cap.capabilities & V4L2_CAP_VIDEO_CAPTURE) printf("Video Capture ");
    if (cap.capabilities & V4L2_CAP_STREAMING) printf("Streaming ");
    if (cap.capabilities & V4L2_CAP_READWRITE) printf("Read/Write ");
    printf("\n");

    // Enumerate frame sizes
    printf("\nSupported Frame Sizes:\n");
    frmsize.index = 0;
    while (ioctl(fd, VIDIOC_ENUM_FRAMESIZES, &frmsize) == 0) {
        if (frmsize.type == V4L2_FRMSIZE_TYPE_DISCRETE) {
            printf("  %dx%d", frmsize.discrete.width, frmsize.discrete.height);
            frmival.pixel_format = V4L2_PIX_FMT_YUYV;
            frmival.width = frmsize.discrete.width;
            frmival.height = frmsize.discrete.height;
            frmival.index = 0;
            while (ioctl(fd, VIDIOC_ENUM_FRAMEINTERVALS, &frmival) == 0) {
                if (frmival.type == V4L2_FRMIVAL_TYPE_DISCRETE) {
                    printf(" (%d fps)", 1000000000 / (frmival.discrete.numerator * frmival.discrete.denominator));
                }
                frmival.index++;
            }
            printf("\n");
        }
        frmsize.index++;
    }

    if (frmsize.index == 0) {
        fprintf(stderr, "Device does not support frame size enumeration.\n");
    }

    // Check for autofocus support
    ctrl.id = V4L2_CID_FOCUS_AUTO;
    ret = ioctl(fd, VIDIOC_QUERYCTRL, &ctrl);
    if (ret < 0) {
        fprintf(stderr, "Autofocus control not found.\n");
    } else {
        if (ctrl.flags & V4L2_CTRL_FLAG_DISABLED) {
            printf("Autofocus: Not supported\n");
        } else {
            printf("Autofocus: Supported\n");
        }
    }

    // Close device
    close(fd);
    return 0;
}

