#define PAN_PIN 4
#define TILT_PIN 5
#define UP_PIN 6
#define DOWN_PIN 7
#define LEFT_PIN 8
#define RIGHT_PIN 9

#define PWM_FREQ 50
#define PWM_MIN 1000
#define PWM_MAX 2000
#define PWM_CENTER 1500
#define STEP 10
#define DELAY_MS 50

struct gpiod_line *pan_line = NULL;
struct gpiod_line *tilt_line = NULL;
struct gpiod_line *up_line = NULL;
struct gpiod_line *down_line = NULL;
struct gpiod_line *left_line = NULL;
struct gpiod_line *right_line = NULL;

int pan_pwm = PWM_CENTER;
int tilt_pwm = PWM_CENTER;

void cleanup(int signal) {
    if (pan_line) {
        gpiod_line_release(pan_line);
    }
    if (tilt_line) {
        gpiod_line_release(tilt_line);
    }
    if (up_line) {
        gpiod_line_release(up_line);
    }
    if (down_line) {
        gpiod_line_release(down_line);
    }
    if (left_line) {
        gpiod_line_release(left_line);
    }
    if (right_line) {
        gpiod_line_release(right_line);
    }
    gpiod_chip_close(pan_line->chip);
    gpiod_chip_close(tilt_line->chip);
    gpiod_chip_close(up_line->chip);
    gpiod_chip_close(down_line->chip);
    gpiod_chip_close(left_line->chip);
    gpiod_chip_close(right_line->chip);
    exit(EXIT_SUCCESS);
}

void setup_gpio() {
    struct gpiod_chip *chip;
    struct gpiod_line_config config;

    chip = gpiod_chip_open("/dev/gpiochip4");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        exit(EXIT_FAILURE);
    }

    config = gpiod_line_config_default();
    config.direction = GPIOD_LINE_DIRECTION_OUTPUT;
    config.consumer = "pan_servo";
    config.flags = GPIOD_LINE_FLAG_ACTIVE_LOW;

    pan_line = gpiod_chip_get_line(chip, PAN_PIN);
    if (!pan_line) {
        fprintf(stderr, "Failed to get pan line\n");
        exit(EXIT_FAILURE);
    }
    if (gpiod_line_request_output(pan_line, &config) < 0) {
        fprintf(stderr, "Failed to request pan line\n");
        exit(EXIT_FAILURE);
    }

    tilt_line = gpiod_chip_get_line(chip, TILT_PIN);
    if (!tilt_line) {
        fprintf(stderr, "Failed to get tilt line\n");
        exit(EXIT_FAILURE);
    }
    if (gpiod_line_request_output(tilt_line, &config) < 0) {
        fprintf(stderr, "Failed to request tilt line\n");
        exit(EXIT_FAILURE);
    }

    chip = gpiod_chip_open("/dev/gpiochip4");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip for buttons\n");
        exit(EXIT_FAILURE);
    }

    config = gpiod_line_config_default();
    config.direction = GPIOD_LINE_DIRECTION_INPUT;
    config.consumer = "button_inputs";
    config.flags = GPIOD_LINE_FLAG_ACTIVE_LOW | GPIOD_LINE_FLAG_BIAS_PULL_UP;

    up_line = gpiod_chip_get_line(chip, UP_PIN);
    if (!up_line) {
        fprintf(stderr, "Failed to get up line\n");
        exit(EXIT_FAILURE);
    }
    if (gpiod_line_request_input(up_line, &config) < 0) {
        fprintf(stderr, "Failed to request up line\n");
        exit(EXIT_FAILURE);
    }

    down_line = gpiod_chip_get_line(chip, DOWN_PIN);
    if (!down_line) {
        fprintf(stderr, "Failed to get down line\n");
        exit(EXIT_FAILURE);
    }
    if (gpiod_line_request_input(down_line, &config) < 0) {
        fprintf(stderr, "Failed to request down line\n");
        exit(EXIT_FAILURE);
    }

    left_line = gpiod_chip_get_line(chip, LEFT_PIN);
    if (!left_line) {
        fprintf(stderr, "Failed to get left line\n");
        exit(EXIT_FAILURE);
    }
    if (gpiod_line_request_input(left_line, &config) < 0) {
        fprintf(stderr, "Failed to request left line\n");
        exit(EXIT_FAILURE);
    }

    right_line = gpiod_chip_get_line(chip, RIGHT_PIN);
    if (!right_line) {
        fprintf(stderr, "Failed to get right line\n");
        exit(EXIT_FAILURE);
    }
    if (gpiod_line_request_input(right_line, &config) < 0) {
        fprintf(stderr, "Failed to request right line\n");
        exit(EXIT_FAILURE);
    }
}

void set_pwm(struct gpiod_line *line, int pulse_width) {
    if (pulse_width < PWM_MIN) pulse_width = PWM_MIN;
    if (pulse_width > PWM_MAX) pulse_width = PWM_MAX;

    gpiod_line_set_value(line, pulse_width);
}

void handle_buttons() {
    int up = gpiod_line_get_value(up_line);
    int down = gpiod_line_get_value(down_line);
    int left = gpiod_line_get_value(left_line);
    int right = gpiod_line_get_value(right_line);

    if (up == 0) {
        tilt_pwm += STEP;
        if (tilt_pwm > PWM_MAX) tilt_pwm = PWM_MAX;
    }
    if (down == 0) {
        tilt_pwm -= STEP;
        if (tilt_pwm < PWM_MIN) tilt_pwm = PWM_MIN;
    }
    if (left == 0) {
        pan_pwm += STEP;
        if (pan_pwm > PWM_MAX) pan_pwm = PWM_MAX;
    }
    if (right == 0) {
        pan_pwm -= STEP;
        if (pan_pwm < PWM_MIN) pan_pwm = PWM_MIN;
    }
}

int main() {
    setup_gpio();

    printf("Camera Pan-Tilt Controller\n");
    printf("Pan: GPIO4 (BCM), Tilt: GPIO5 (BCM)\n");
    printf("UP: GPIO6, DOWN: GPIO7, LEFT: GPIO8, RIGHT: GPIO9\n");
    printf("Center position: 1500us\n");

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    while (1) {
        handle_buttons();
        set_pwm(pan_line, pan_pwm);
        set_pwm(tilt_line, tilt_pwm);
        usleep(DELAY_MS * 1000);
    }

    return 0;
}

