    }
}

size_t write_callback(void *ptr, size_t size, size_t nmemb, void *userdata) {
    FILE *fp = (FILE *)userdata;
    size_t written = fwrite(ptr, size, nmemb, fp);
    return written;
}

void capture_jpeg(const char *filename) {
    char cmd[256];
    snprintf(cmd, sizeof(cmd), "raspistill -o %s -q %d", filename, JPEG_QUALITY);
    int result = system(cmd);
    if (result != 0) {
        fprintf(stderr, "Failed to capture JPEG: %s\n", strerror(errno));
    }
}

void create_directory(const char *dir) {
    struct stat st;
    if (stat(dir, &st) == 0) {
        if (!S_ISDIR(st.st_mode)) {
            fprintf(stderr, "Directory %s exists but is not a directory\n", dir);
        }
    } else {
        if (mkdir(dir, 0777) != 0) {
            fprintf(stderr, "Failed to create directory %s: %s\n", dir, strerror(errno));
        }
    }
}

