    upload_url = malloc(MAX_URL_LEN);
    if (!upload_url) {
        fprintf(stderr, "Memory allocation failed for URL\n");
        exit(EXIT_FAILURE);
    }
    snprintf(upload_url, MAX_URL_LEN, "http://%s:%s/upload", ip_address, port);
}

void send_data(const char *filename, const char *timestamp, int motion_status) {
    CURLcode res;
    struct curl_slist *headers = NULL;
    FILE *fp = fopen(filename, "rb");
    if (!fp) {
        fprintf(stderr, "Failed to open file %s for reading\n", filename);
        return;
    }

    curl = curl_easy_init();
    if (!curl) {
        fprintf(stderr, "Failed to initialize CURL\n");
        fclose(fp);
        return;
    }

    curl_easy_setopt(curl, CURLOPT_URL, upload_url);
    curl_easy_setopt(curl, CURLOPT_READDATA, fp);
    curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_callback);
    curl_easy_setopt(curl, CURLOPT_WRITEDATA, stdout);
    curl_easy_setopt(curl, CURLOPT_POST, 1L);
