    if (res != CURLE_OK) {
        fprintf(stderr, "CURL error: %s\n", curl_easy_strerror(res));
    }

    curl_easy_cleanup(curl);
    fclose(fp);
}

void poll_sensor() {
    int value;
    gpiod_line_get_value(pir_line, &value);
    if (value == 1) {
        static time_t last_motion = 0;
        time_t now = time(NULL);
        if (now - last_motion > DEBOUNCE_DELAY) {
            last_motion = now;
            char filename[MAX_FILENAME_LEN];
            time_t t = time(NULL);
            struct tm *tm = localtime(&t);
            strftime(filename, MAX_FILENAME_LEN, "motion_captures/motion_%Y%m%d_%H%M%S_%f.jpg", tm);
            create_directory("motion_captures");
            capture_jpeg(filename);
            snprintf(filename, MAX_FILENAME_LEN, "motion_captures/motion_%Y%m%d_%H%M%S_%f.jpg", tm);
            char timestamp[30];
            strftime(timestamp, 30, "%Y-%m-%dT%H:%M:%S.%f", tm);
            send_data(filename, timestamp, 1);
        }
    }
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <IP> <PORT>\n", argv[0]);
        exit(EXIT_FAILURE);
    }

    ip_address = strdup(argv[1]);
    port = strdup(argv[2]);
    build_upload_url();

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    struct gpiod_chip *chip;
    struct gpiod_line_config config = GPIOD_LINE_CONFIG_INPUT;
    config.flags = GPIOD_LINE_FLAG_BIAS_PULL_DOWN;

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    pir_line = gpiod_line_request(chip, "pir", GPIO_PIN, "pir", &config);
    if (!pir_line) {
        fprintf(stderr, "Failed to request GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    initialized = TRUE;

    while (running) {
        poll_sensor();
        usleep(POLL_INTERVAL * 1000);
    }

    cleanup();
    return 0;
}

