#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/gpio.h>
#include <time.h>
#include <signal.h>
#include <sys/time.h>
#include <sys/types.h>
#include <unistd.h>
#include <errno.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 17
#define DEBOUNCE_TIMEOUT_MS 50
#define CAPTURE_TIMEOUT_MS 2000
#define LOG_FILE "/home/pi/motion_capture.log"
#define IMAGES_DIR "/home/pi/images"
#define CMD_TEMPLATE "raspistill -o %s -w 640 -h 480 -q 85 -t %d -n"

typedef struct {
    int gpio_fd;
    int log_fd;
    int capture_timeout;
    int debounce_timeout;
} app_state_t;

void log_message(const char *message) {
    time_t now;
    struct tm *timeinfo;
    char timestamp[64];

    time(&now);
    timeinfo = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(stderr, "[%s] %s\n", timestamp, message);
}

void log_to_file(const char *message) {
    if (app_state_t.log_fd < 0) {
        log_message("Failed to open log file");
        return;
    }

    time_t now;
    struct tm *timeinfo;
    char timestamp[64];

    time(&now);
    timeinfo = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    char log_line[256];
    snprintf(log_line, sizeof(log_line), "[%s] %s\n", timestamp, message);

    if (write(app_state_t.log_fd, log_line, strlen(log_line)) < 0) {
        log_message("Failed to write to log file");
    }
}

void handle_signal(int signal) {
    log_message("Received signal, cleaning up...");
    if (app_state_t.gpio_fd >= 0) {
        close(app_state_t.gpio_fd);
    }
    if (app_state_t.log_fd >= 0) {
        close(app_state_t.log_fd);
    }
    exit(EXIT_SUCCESS);
}

void setup_gpio() {
    int chip_fd;
    struct gpiochip_info chip_info;
    struct gpio_desc desc;

    chip_fd = open("/dev/gpiochip0", O_RDWR);
    if (chip_fd < 0) {
        log_message("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    if (ioctl(chip_fd, GPIO_GET_CHIPINFO, &chip_info) < 0) {
        log_message("Failed to get GPIO chip info");
        close(chip_fd);
        exit(EXIT_FAILURE);
    }

    if (chip_info.ngpio <= GPIO_PIN) {
        log_message("GPIO pin out of range");
        close(chip_fd);
        exit(EXIT_FAILURE);
    }

    memset(&desc, 0, sizeof(desc));
    desc.line = GPIO_PIN;
    desc.flags = GPIO_LINE_FLAG_EDGE_FALLING;

    if (ioctl(chip_fd, GPIO_GET_LINE, &desc) < 0) {
        log_message("Failed to get GPIO line");
        close(chip_fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(chip_fd, GPIO_LINE_REQUEST, &desc) < 0) {
        log_message("Failed to request GPIO line");
        close(chip_fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(chip_fd, GPIO_LINE_SET_FLAGS, &desc) < 0) {
        log_message("Failed to set GPIO line flags");
        close(chip_fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(chip_fd, GPIO_LINE_GET_VALUES, &desc) < 0) {
        log_message("Failed to get GPIO line value");
        close(chip_fd);
        exit(EXIT_FAILURE);
    }

    app_state_t.gpio_fd = chip_fd;
}

void setup_logging() {
    app_state_t.log_fd = open(LOG_FILE, O_WRONLY | O_APPEND | O_CREAT, 0644);
    if (app_state_t.log_fd < 0) {
        log_message("Failed to open log file");
        exit(EXIT_FAILURE);
    }
}

void capture_image() {
    time_t now;
    struct tm *timeinfo;
    char timestamp[20];
    char filename[100];
    char command[256];
    int result;

    time(&now);
    timeinfo = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y%m%d_%H%M%S", timeinfo);

    snprintf(filename, sizeof(filename), "%s/%s_000.jpg", IMAGES_DIR, timestamp);

    snprintf(command, sizeof(command), CMD_TEMPLATE, filename, CAPTURE_TIMEOUT_MS);

    result = system(command);
    if (result != 0) {
        log_to_file("Failed to capture image");
    } else {
        log_to_file("Image captured successfully");
    }
}

void wait_for_edge(int gpio_fd, int timeout_ms) {
    struct gpio_event_request req;
    struct gpio_event_response resp;
    struct timespec timeout;
    int ret;

    req.line = GPIO_PIN;
    req.type = GPIO_EVENT_TYPE_EDGE_FALLING;

    if (ioctl(gpio_fd, GPIO_GET_LINEEVENT_IOCTL, &req) < 0) {
        log_message("Failed to get line event");
        return;
    }

    clock_gettime(CLOCK_REALTIME, &timeout);
    timeout.tv_nsec += timeout_ms * 1000000;
    if (timeout.tv_nsec >= 1000000000) {
        timeout.tv_sec++;
        timeout.tv_nsec -= 1000000000;
    }

    ret = read(gpio_fd, &resp, sizeof(resp));
    if (ret < 0) {
        log_message("Failed to read GPIO event");
        return;
    }

    if (resp.type != GPIO_EVENT_TYPE_EDGE_FALLING) {
        log_message("Unexpected GPIO event type");
        return;
    }
}

int main() {
    struct sigaction sa;
    int ret;

    app_state_t.gpio_fd = -1;
    app_state_t.log_fd = -1;

    setup_logging();
    setup_gpio();

    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        log_message("Failed to set up SIGINT handler");
        exit(EXIT_FAILURE);
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        log_message("Failed to set up SIGTERM handler");
        exit(EXIT_FAILURE);
    }

    while (1) {
        wait_for_edge(app_state_t.gpio_fd, DEBOUNCE_TIMEOUT_MS);
        capture_image();
    }

    return 0;
}

