    timeinfo = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y%m%d_%H%M%S", timeinfo);

    snprintf(filename, sizeof(filename), "%s/%s_000.jpg", IMAGES_DIR, timestamp);

    snprintf(command, sizeof(command), CMD_TEMPLATE, filename, CAPTURE_TIMEOUT_MS);

    result = system(command);
    if (result != 0) {
        log_to_file("Failed to capture image");
    } else {
        log_to_file("Image captured successfully");
    }
}

void wait_for_edge(int gpio_fd, int timeout_ms) {
    struct gpio_event_request req;
    struct gpio_event_response resp;
    struct timespec timeout;
    int ret;

    req.line = GPIO_PIN;
    req.type = GPIO_EVENT_TYPE_EDGE_FALLING;

    if (ioctl(gpio_fd, GPIO_GET_LINEEVENT_IOCTL, &req) < 0) {
        log_message("Failed to get line event");
        return;
    }

    clock_gettime(CLOCK_REALTIME, &timeout);
    timeout.tv_nsec += timeout_ms * 1000000;
    if (timeout.tv_nsec >= 1000000000) {
        timeout.tv_sec++;
        timeout.tv_nsec -= 1000000000;
    }

    ret = read(gpio_fd, &resp, sizeof(resp));
    if (ret < 0) {
        log_message("Failed to read GPIO event");
        return;
    }

    if (resp.type != GPIO_EVENT_TYPE_EDGE_FALLING) {
        log_message("Unexpected GPIO event type");
        return;
    }
}

int main() {
    struct sigaction sa;
    int ret;

    app_state_t.gpio_fd = -1;
    app_state_t.log_fd = -1;

    setup_logging();
    setup_gpio();

    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        log_message("Failed to set up SIGINT handler");
        exit(EXIT_FAILURE);
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        log_message("Failed to set up SIGTERM handler");
        exit(EXIT_FAILURE);
    }

    while (1) {
        wait_for_edge(app_state_t.gpio_fd, DEBOUNCE_TIMEOUT_MS);
        capture_image();
    }

    return 0;
}
