#include <signal.h>
#include <sys/select.h>
#include <time.h>

#define DEVICE "/dev/video0"
#define WIDTH 640
#define HEIGHT 480
#define FORMAT V4L2_PIX_FMT_YUYV
#define BUFFER_COUNT 1
#define CROP_WIDTH 200
#define CROP_HEIGHT 150
#define CROP_BYTES (CROP_WIDTH * CROP_HEIGHT * 2)
#define FILE_NAME "cropped.yuv"

typedef struct {
    int fd;
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;
    void *mapped;
    FILE *file;
    int running;
} CameraContext;

void handle_signal(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        CameraContext *ctx = (CameraContext *)malloc(sizeof(CameraContext));
        if (ctx) {
            ctx->running = 0;
        }
    }
}

void cleanup(CameraContext *ctx) {
    if (ctx->file) {
        fclose(ctx->file);
    }
    if (ctx->mapped) {
        munmap(ctx->mapped, ctx->fmt.fmt.pix.sizeimage);
    }
    if (ctx->fd >= 0) {
        close(ctx->fd);
    }
    free(ctx);
}

int open_camera() {
    int fd = open(DEVICE, O_RDWR | O_NONBLOCK, 0);
    if (fd < 0) {
        perror("Failed to open camera device");
        return -1;
    }
    return fd;
}

int query_capability(int fd) {
    if (ioctl(fd, VIDIOC_QUERYCAP, &g_cap) < 0) {
        perror("Failed to query camera capability");
        return -1;
    }
    if (!(g_cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture\n");
        return -1;
    }
    if (!(g_cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device does not support streaming\n");
        return -1;
    }
    return 0;
}

int set_format(int fd, int width, int height, int pixfmt) {
    struct v4l2_format *fmt = &g_fmt;
    fmt->type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt->fmt.pix.width = width;
    fmt->fmt.pix.height = height;
    fmt->fmt.pix.pixelformat = pixfmt;
    fmt->fmt.pix.field = V4L2_FIELD_NONE;
    if (ioctl(fd, VIDIOC_S_FMT, fmt) < 0) {
        perror("Failed to set format");
        return -1;
    }
    return 0;
}

int request_buffers(int fd) {
    struct v4l2_requestbuffers *req = &g_req;
    req->count = BUFFER_COUNT;
    req->type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req->memory = V4L2_MEMORY_MMAP;
    if (ioctl(fd, VIDIOC_REQBUFS, req) < 0) {
        perror("Failed to request buffers");
        return -1;
    }
    return 0;
}

int mmap_buffer(int fd) {
    struct v4l2_buffer *buf = &g_buf;
    buf->type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf->memory = V4L2_MEMORY_MMAP;
    buf->index = 0;
    if (ioctl(fd, VIDIOC_QUERYBUF, buf) < 0) {
        perror("Failed to query buffer");
        return -1;
    }
    g_mapped = mmap(NULL, buf->length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf->m.offset);
    if (g_mapped == MAP_FAILED) {
        perror("Failed to mmap buffer");
        return -1;
    }
    return 0;
}

int start_streaming(int fd) {
    if (ioctl(fd, VIDIOC_STREAMON, &V4L2_BUF_TYPE_VIDEO_CAPTURE) < 0) {
        perror("Failed to start streaming");
        return -1;
    }
    return 0;
}

int wait_for_frame(int fd) {
    fd_set fds;
    struct timeval tv;
    int ret;

    FD_ZERO(&fds);
    FD_SET(fd, &fds);

    tv.tv_sec = 2;
    tv.tv_usec = 0;

    do {
        ret = select(fd + 1, &fds, NULL, NULL, &tv);
    } while (ret < 0 && errno == EINTR);

    if (ret < 0) {
        perror("select failed");
        return -1;
    } else if (ret == 0) {
        fprintf(stderr, "Timeout waiting for frame\n");
        return -1;
    }

    if (ioctl(fd, VIDIOC_DQBUF, &g_buf) < 0) {
        perror("Failed to dequeue buffer");
        return -1;
    }

    if (ioctl(fd, VIDIOC_QBUF, &g_buf) < 0) {
        perror("Failed to queue buffer");
        return -1;
    }

    return 0;
}

int check_frame(CameraContext *ctx) {
    struct v4l2_format *fmt = &ctx->fmt;
    if (fmt->fmt.pix.width != WIDTH || fmt->fmt.pix.height != HEIGHT || fmt->fmt.pix.pixelformat != FORMAT) {
        fprintf(stderr, "Frame format mismatch: width=%d, height=%d, format=0x%x\n",
                fmt->fmt.pix.width, fmt->fmt.pix.height, fmt->fmt.pix.pixelformat);
        return -1;
    }
    return 0;
}

int crop_and_save(CameraContext *ctx) {
    unsigned char *frame = (unsigned char *)ctx->mapped;
    unsigned char *cropped = (unsigned char *)malloc(CROP_BYTES);
    if (!cropped) {
        perror("Failed to allocate memory for cropped frame");
        return -1;
    }

    int src_y = (fmt->fmt.pix.height - CROP_HEIGHT) / 2;
    int src_x = (fmt->fmt.pix.width - CROP_WIDTH) / 2;

    for (int y = 0; y < CROP_HEIGHT; y++) {
        for (int x = 0; x < CROP_WIDTH; x++) {
            int src_idx = (src_y + y) * fmt->fmt.pix.bytesperline + (src_x + x) * 2;
            int dst_idx = y * CROP_WIDTH * 2 + x * 2;
            cropped[dst_idx] = frame[src_idx];
            cropped[dst_idx + 1] = frame[src_idx + 1];
        }
    }

    if (fwrite(cropped, 1, CROP_BYTES, ctx->file) != CROP_BYTES) {
        perror("Failed to write cropped frame to file");
        free(cropped);
        return -1;
    }

    free(cropped);
    return 0;
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    CameraContext *ctx = (CameraContext *)malloc(sizeof(CameraContext));
    if (!ctx) {
        perror("Failed to allocate context");
        return EXIT_FAILURE;
    }

    ctx->fd = open_camera();
    if (ctx->fd < 0) {
        cleanup(ctx);
        return EXIT_FAILURE;
    }

    if (query_capability(ctx->fd) < 0) {
        cleanup(ctx);
        return EXIT_FAILURE;
    }

    if (set_format(ctx->fd, WIDTH, HEIGHT, FORMAT) < 0) {
        cleanup(ctx);
        return EXIT_FAILURE;
    }

    if (request_buffers(ctx->fd) < 0) {
        cleanup(ctx);
        return EXIT_FAILURE;
    }

    if (mmap_buffer(ctx->fd) < 0) {
        cleanup(ctx);
        return EXIT_FAILURE;
    }

    if (start_streaming(ctx->fd) < 0) {
        cleanup(ctx);
        return EXIT_FAILURE;
    }

    ctx->file = fopen(FILE_NAME, "wb");
    if (!ctx->file) {
        cleanup(ctx);
        return EXIT_FAILURE;
    }

    ctx->running = 1;

    while (ctx->running) {
        if (wait_for_frame(ctx->fd) < 0) {
            cleanup(ctx);
            return EXIT_FAILURE;
        }

        if (check_frame(ctx) < 0) {
            cleanup(ctx);
            return EXIT_FAILURE;
        }

        if (crop_and_save(ctx) < 0) {
            cleanup(ctx);
            return EXIT_FAILURE;
        }

        break;
    }

    cleanup(ctx);
    return EXIT_SUCCESS;
}

