code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/time.h>
#include <sys/types.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define SERVO_PIN_PAN 17
#define SERVO_PIN_TILT 18
#define PWM_FREQUENCY 50
#define PWM_RESOLUTION 1024
#define NEUTRAL_ANGLE 90
#define STEP_ANGLE 5
#define MIN_ANGLE 0
#define MAX_ANGLE 180
#define DELAY_MS 100

typedef struct {
    struct gpiod_line *pan_line;
    struct gpiod_line *tilt_line;
    int pan_angle;
    int tilt_angle;
    int running;
} ServoContext;

void handle_signal(int sig) {
    if (sig == SIGINT) {
        printf("\nReceived SIGINT, shutting down...\n");
    } else if (sig == SIGTERM) {
        printf("\nReceived SIGTERM, shutting down...\n");
    }
    exit(1);
}

void set_servo_angle(struct gpiod_line *line, int angle) {
    if (angle < MIN_ANGLE || angle > MAX_ANGLE) {
        fprintf(stderr, "Error: Angle out of range (0-180)\n");
        return;
    }

    double duty_cycle = (double)angle / 180.0 * PWM_RESOLUTION;
    int pulse_width = (int)(duty_cycle * 1000000.0 / PWM_FREQUENCY); // microseconds

    if (pulse_width < 0 || pulse_width > 20000) {
        fprintf(stderr, "Error: Invalid pulse width for angle %d\n", angle);
        return;
    }

    int fd = gpiod_line_get_fd(line);
    if (fd < 0) {
        fprintf(stderr, "Error: Failed to get file descriptor for line\n");
        return;
    }

    if (ioctl(fd, GPIO_LINE_SET_PWMSERVO, &pulse_width) < 0) {
        fprintf(stderr, "Error: Failed to set PWM duty cycle: %s\n", strerror(errno));
    }
}

void init_servos(ServoContext *ctx) {
    ctx->pan_angle = NEUTRAL_ANGLE;
    ctx->tilt_angle = NEUTRAL_ANGLE;
    ctx->running = 1;

    // Initialize pan servo
    ctx->pan_line = gpiod_line_get("BCM17", "pwm", 0);
    if (!ctx->pan_line) {
        fprintf(stderr, "Error: Failed to get pan servo line\n");
        exit(1);
    }

    if (gpiod_line_request_output(ctx->pan_line, "pan_servo", 0) < 0) {
        fprintf(stderr, "Error: Failed to request pan servo line\n");
        exit(1);
    }

    // Initialize tilt servo
    ctx->tilt_line = gpiod_line_get("BCM18", "pwm", 0);
    if (!ctx->tilt_line) {
        fprintf(stderr, "Error: Failed to get tilt servo line\n");
        exit(1);
    }

    if (gpiod_line_request_output(ctx->tilt_line, "tilt_servo", 0) < 0) {
        fprintf(stderr, "Error: Failed to request tilt servo line\n");
        exit(1);
    }

    // Set PWM configuration
    int fd_pan = gpiod_line_get_fd(ctx->pan_line);
    int fd_tilt = gpiod_line_get_fd(ctx->tilt_line);

    if (fd_pan < 0 || fd_tilt < 0) {
        fprintf(stderr, "Error: Failed to get file descriptors for lines\n");
        exit(1);
    }

    struct pwm_config config = {
        .frequency = PWM_FREQUENCY,
        .duty_cycle = 0
    };

    if (ioctl(fd_pan, GPIO_LINE_SET_PWM_CONFIG, &config) < 0) {
        fprintf(stderr, "Error: Failed to set PWM config for pan line: %s\n", strerror(errno));
        exit(1);
    }

    if (ioctl(fd_tilt, GPIO_LINE_SET_PWM_CONFIG, &config) < 0) {
        fprintf(stderr, "Error: Failed to set PWM config for tilt line: %s\n", strerror(errno));
        exit(1);
    }

    set_servo_angle(ctx->pan_line, NEUTRAL_ANGLE);
    set_servo_angle(ctx->tilt_line, NEUTRAL_ANGLE);
}

void cleanup_servos(ServoContext *ctx) {
    if (ctx->pan_line) {
        gpiod_line_release(ctx->pan_line);
    }
    if (ctx->tilt_line) {
        gpiod_line_release(ctx->tilt_line);
    }
    gpiod_exit();
}

void handle_input(ServoContext *ctx) {
    char c;
    while (ctx->running) {
        if (read(STDIN_FILENO, &c, 1) < 0) {
            if (errno == EAGAIN || errno == EWOULDBLOCK) {
                usleep(10000);
                continue;
            } else {
                fprintf(stderr, "Error reading input: %s\n", strerror(errno));
                break;
            }
        }

        switch (c) {
            case 'q':
                ctx->running = 0;
                break;
            case 'w':
                ctx->tilt_angle += STEP_ANGLE;
                if (ctx->tilt_angle > MAX_ANGLE) {
                    ctx->tilt_angle = MAX_ANGLE;
                }
                set_servo_angle(ctx->tilt_line, ctx->tilt_angle);
                break;
            case 's':
                ctx->tilt_angle -= STEP_ANGLE;
                if (ctx->tilt_angle < MIN_ANGLE) {
                    ctx->tilt_angle = MIN_ANGLE;
                }
                set_servo_angle(ctx->tilt_line, ctx->tilt_angle);
                break;
            case 'a':
                ctx->pan_angle -= STEP_ANGLE;
                if (ctx->pan_angle < MIN_ANGLE) {
                    ctx->pan_angle = MIN_ANGLE;
                }
                set_servo_angle(ctx->pan_line, ctx->pan_angle);
                break;
            case 'd':
                ctx->pan_angle += STEP_ANGLE;
                if (ctx->pan_angle > MAX_ANGLE) {
                    ctx->pan_angle = MAX_ANGLE;
                }
                set_servo_angle(ctx->pan_line, ctx->pan_angle);
                break;
            default:
                break;
        }

        usleep(DELAY_MS * 1000);
    }
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    ServoContext ctx;
    if (gpiod_init() < 0) {
        fprintf(stderr, "Error: Failed to initialize libgpiod\n");
        exit(1);
    }

    init_servos(&ctx);

    handle_input(&ctx);

    cleanup_servos(&ctx);
    exit(0);
}

