#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/gpio.h>
#include <libgpiod.h>
#include <linux/i2c-dev.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <errno.h>

#define GPIO_PIN 17
#define I2C_BUS 1
#define I2C_ADDR 0x27
#define LCD_WIDTH 16
#define LCD_HEIGHT 2
#define UPDATE_INTERVAL 1
#define LCD_UPDATE_INTERVAL 10

typedef struct {
    int fd;
    int flow_count;
    double total_volume;
    double last_time;
    double flow_rate;
    int running;
} app_state;

void handle_signal(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        printf("\nShutting down...\n");
        exit(EXIT_SUCCESS);
    }
}

void init_gpio(app_state *state) {
    struct gpiod_line *line;
    struct gpiod_line_request_config req_config;
    int ret;

    state->fd = gpiod_open(GPIO_PIN, GPIOD_LINE_DIRECTION_INPUT);
    if (state->fd < 0) {
        fprintf(stderr, "Failed to open GPIO: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    memset(&req_config, 0, sizeof(req_config));
    req_config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;
    req_config.consumer = "flow_sensor";
    req_config.flags = GPIOD_LINE_REQUEST_FLAG_ACTIVE_LOW;

    line = gpiod_line_request(state->fd, &req_config);
    if (!line) {
        fprintf(stderr, "Failed to request GPIO line: %s\n", strerror(errno));
        gpiod_close(state->fd);
        exit(EXIT_FAILURE);
    }

    state->flow_count = 0;
    state->total_volume = 0.0;
    state->last_time = 0.0;
    state->flow_rate = 0.0;
    state->running = 1;
}

void init_i2c(app_state *state) {
    int fd;
    char filename[256];

    snprintf(filename, sizeof(filename), "/dev/i2c-%d", I2C_BUS);
    fd = open(filename, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    if (ioctl(fd, I2C_SLAVE, I2C_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address: %s\n", strerror(errno));
        close(fd);
        exit(EXIT_FAILURE);
    }

    state->fd = fd;
}

void lcd_init(int fd) {
    char buffer[16];
    unsigned char cmd[4];

    // Function set: 2 lines, 5x7 dots, 8 bits
    cmd[0] = 0x33;
    cmd[1] = 0x32;
    cmd[2] = 0x28;
    cmd[3] = 0x0C; // Display on, cursor off, blink off
    for (int i = 0; i < 4; i++) {
        write(fd, &cmd[i], 1);
        usleep(1000);
    }

    // Clear display
    write(fd, 0x01, 1);
    usleep(2000);

    // Entry mode set: increment, no shift
    write(fd, 0x06, 1);
    usleep(1000);
}

void lcd_set_cursor(int fd, int row, int col) {
    int offset = 0;
    if (row == 1) offset = 0x40;
    if (col == 0) offset += 0x00;
    else if (col == 1) offset += 0x01;
    else if (col == 2) offset += 0x02;
    else if (col == 3) offset += 0x03;
    else if (col == 4) offset += 0x04;
    else if (col == 5) offset += 0x05;
    else if (col == 6) offset += 0x06;
    else if (col == 7) offset += 0x07;
    else if (col == 8) offset += 0x08;
    else if (col == 9) offset += 0x09;
    else if (col == 10) offset += 0x0A;
    else if (col == 11) offset += 0x0B;
    else if (col == 12) offset += 0x0C;
    else if (col == 13) offset += 0x0D;
    else if (col == 14) offset += 0x0E;
    else if (col == 15) offset += 0x0F;

    write(fd, 0x80 | offset, 1);
}

void lcd_print(int fd, const char *str) {
    write(fd, str, strlen(str));
}

void update_flow_rate(app_state *state) {
    struct gpiod_line *line = gpiod_line_get(state->fd);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line: %s\n", strerror(errno));
        return;
    }

    int current_state = gpiod_line_get_value(line);
    gpiod_line_put(line);

    if (current_state == 0) {
        state->flow_count++;
    }
}

void calculate_flow(app_state *state) {
    double current_time = (double)time(NULL);
    double delta_time = current_time - state->last_time;
    if (delta_time > 0) {
        state->flow_rate = (state->flow_count / delta_time) * 0.01; // 1 pulse = 1 liter per minute
        state->total_volume += state->flow_rate * delta_time;
        state->last_time = current_time;
        state->flow_count = 0;
    }
}

void log_flow(app_state *state) {
    calculate_flow(state);
    printf("Flow Rate: %.2f L/min | Total Volume: %.2f L\n", state->flow_rate, state->total_volume);
}

void update_lcd(app_state *state) {
    char buffer[LCD_WIDTH + 1];
    snprintf(buffer, LCD_WIDTH, "%.2f L/min", state->flow_rate);
    lcd_set_cursor(state->fd, 0, 0);
    lcd_print(state->fd, buffer);

    snprintf(buffer, LCD_WIDTH, "%.2f L", state->total_volume);
    lcd_set_cursor(state->fd, 1, 0);
    lcd_print(state->fd, buffer);
}

int main() {
    app_state state = {0};
    struct sigaction sa;
    int ret;

    // Set up signal handling
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set SIGINT handler: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set SIGTERM handler: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    // Initialize GPIO
    init_gpio(&state);

    // Initialize I2C
    init_i2c(&state);
    lcd_init(state.fd);

    state.last_time = (double)time(NULL);

    while (state.running) {
        update_flow_rate(&state);
        log_flow(&state);
        usleep(UPDATE_INTERVAL * 1000000);

        if ((int)(time(NULL) - state.last_time) >= LCD_UPDATE_INTERVAL) {
            update_lcd(&state);
            state.last_time = (double)time(NULL);
        }
    }

    // Cleanup
    gpiod_close(state.fd);
    close(state.fd);

    return 0;
}

