#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <linux/i2c-dev.h>
#include <sys/time.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

#define GPIO_PIN 17
#define SPI_BUS 0
#define SPI_CHIP_SELECT 0
#define SPI_MODE 0
#define SPI_SPEED 1000000
#define I2C_BUS 1
#define I2C_ADDR 0x27
#define LCD_ADDR 0x27
#define LCD_LINES 2
#define LCD_CHARS 16
#define SAMPLE_WINDOW_MS 500
#define LCD_DELAY_MS 500

typedef struct {
    int spi_fd;
    int i2c_fd;
    gpiod_line *gpio_line;
    int pulse_count;
    struct timeval start_time;
    int last_display_time;
    int direction;
} app_state;

void handle_signal(int sig) {
    printf("Caught signal %d, shutting down...\n", sig);
    exit(EXIT_SUCCESS);
}

int spi_init(int bus, int cs, int mode, int speed) {
    char path[32];
    snprintf(path, sizeof(path), "/dev/spidev%d.%d", bus, cs);
    int fd = open(path, O_RDWR);
    if (fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Failed to set SPI mode");
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_SPEED_HZ, &speed) < 0) {
        perror("Failed to set SPI speed");
        close(fd);
        return -1;
    }

    return fd;
}

int i2c_init(int bus, int addr) {
    char path[32];
    snprintf(path, sizeof(path), "/dev/i2c-%d", bus);
    int fd = open(path, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C device");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Failed to set I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

void lcd_init(int fd) {
    char buffer[16];
    buffer[0] = 0x38; // Function set: 2 lines, 5x7 dots, 8 bits
    buffer[1] = 0x0C; // Display on, cursor off, blink off
    buffer[2] = 0x06; // Entry mode: increment, no shift
    buffer[3] = 0x02; // Return home
    if (write(fd, buffer, 4) != 4) {
        perror("Failed to initialize LCD");
    }
}

void lcd_set_cursor(int fd, int line, int pos) {
    char buffer[2];
    buffer[0] = 0x80;
    buffer[1] = 0x40 * line + pos;
    if (write(fd, buffer, 2) != 2) {
        perror("Failed to set LCD cursor");
    }
}

void lcd_print(int fd, const char *str) {
    if (write(fd, str, strlen(str)) != strlen(str)) {
        perror("Failed to print to LCD");
    }
}

int read_adc(int fd) {
    unsigned char buffer[3];
    buffer[0] = 0b10000000; // Start bit, single-ended, channel 0
    buffer[1] = 0b00000000; // 8-bit data
    buffer[2] = 0b00000000;

    if (write(fd, buffer, 3) != 3) {
        perror("Failed to write to ADC");
        return -1;
    }

    usleep(100); // Wait for conversion

    if (read(fd, buffer, 3) != 3) {
        perror("Failed to read from ADC");
        return -1;
    }

    int value = (buffer[1] << 8) | buffer[2];
    if (value < 1 || value > 1023) {
        fprintf(stderr, "ADC reading out of range: %d\n", value);
        return -1;
    }

    return value;
}

void gpio_init(int pin) {
    struct gpiod_line *line;
    struct gpiod_line_request_config req = {
        .consumer = "anemometer",
        .line_offset = pin,
        .flags = GPIOD_LINE_REQUEST_FLAG_ACTIVE_LOW,
        .flags |= GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP,
        .flags |= GPIOD_LINE_REQUEST_FLAG_OUTPUT,
