#define GPIO_PIN 17
#define I2C_BUS 1
#define I2C_ADDR 0x27
#define LCD_LINE1 "Flow Rate:"
#define LCD_LINE2 "X.XX L/min"
#define PULSE_COUNT_INTERVAL 1
#define LITERS_PER_PULSE 0.001
#define MAX_NO_PULSE_TIME 10  // seconds
#define LCD_WIDTH 16
#define LCD_HEIGHT 2

typedef struct {
    int i2c_fd;
    struct gpiod_line *gpio_line;
    int pulse_count;
    int last_pulse_time;
    int no_pulse_count;
    int flow_rate;
    int running;
} app_state;

void init_lcd(int fd) {
    char cmd[2];
    cmd[0] = 0x00; // Function set
    cmd[1] = 0x20 | 0x08; // 4-bit, 2 lines, 5x7 dots
    if (write(fd, cmd, 2) != 2) {
        perror("LCD init: Function set");
        exit(EXIT_FAILURE);
    }

    usleep(4000);
    cmd[0] = 0x00; // Function set
    cmd[1] = 0x20 | 0x08; // 4-bit, 2 lines, 5x7 dots
    if (write(fd, cmd, 2) != 2) {
        perror("LCD init: Function set");
        exit(EXIT_FAILURE);
    }

    usleep(4000);
    cmd[0] = 0x00; // Function set
    cmd[1] = 0x20 | 0x08; // 4-bit, 2 lines, 5x7 dots
    if (write(fd, cmd, 2) != 2) {
        perror("LCD init: Function set");
        exit(EXIT_FAILURE);
    }

    usleep(100);
    cmd[0] = 0x00; // Display on/off control
    cmd[1] = 0x0C; // Display on, cursor off, blink off
    if (write(fd, cmd, 2) != 2) {
        perror("LCD init: Display on/off");
        exit(EXIT_FAILURE);
    }

    usleep(100);
    cmd[0] = 0x00; // Entry mode set
    cmd[1] = 0x06; // Increment cursor, no shift
    if (write(fd, cmd, 2) != 2) {
        perror("LCD init: Entry mode");
        exit(EXIT_FAILURE);
    }

    usleep(100);
    cmd[0] = 0x00; // Clear display
    cmd[1] = 0x01;
    if (write(fd, cmd, 2) != 2) {
        perror("LCD init: Clear display");
        exit(EXIT_FAILURE);
    }

    usleep(2000);
}

void set_cursor(int fd, int line, int pos) {
    char cmd[2];
    cmd[0] = 0x00;
    cmd[1] = 0x80 | (line * 0x40) + pos;
    if (write(fd, cmd, 2) != 2) {
        perror("LCD set cursor");
        exit(EXIT_FAILURE);
    }
}

void write_string(int fd, const char *str) {
    for (int i = 0; i < strlen(str); i++) {
        if (write(fd, &str[i], 1) != 1) {
            perror("LCD write string");
            exit(EXIT_FAILURE);
        }
    }
}

void handle_signal(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        printf("\nShutting down...\n");
        exit(EXIT_SUCCESS);
    }
}

void cleanup(app_state *state) {
    if (state->gpio_line) {
        gpiod_line_release(state->gpio_line);
    }
    if (state->i2c_fd >= 0) {
        close(state->i2c_fd);
    }
    printf("Resources released.\n");
}

int main() {
    app_state state = {0};
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int i2c_fd;
    char i2c_dev[20];
    int pulse_count = 0;
    int last_pulse_time = 0;
    int no_pulse_count = 0;
    int flow_rate = 0;
    int running = 1;

    snprintf(i2c_dev, sizeof(i2c_dev), "/dev/i2c-%d", I2C_BUS);
    if ((i2c_fd = open(i2c_dev, O_RDWR)) < 0) {
        perror("I2C open failed");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("I2C slave address set failed");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    init_lcd(i2c_fd);

    if ((chip = gpiod_chip_open("/dev/gpiochip0")) == NULL) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    if ((line = gpiod_line_get(chip, GPIO_PIN)) == NULL) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(line, "flow_sensor", GPIOD_LINE_REQUEST_OUTPUT) < 0) {
        perror("Failed to request GPIO line");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_set_value(line, 1) < 0) {
        perror("Failed to set GPIO line high");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_set_edge(line, GPIOD_LINE_EDGE_RISING) < 0) {
        perror("Failed to set GPIO edge");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_set_debounce(line, 20000) < 0) {
        perror("Failed to set GPIO debounce");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (running) {
        struct gpiod_line_event event;
        int event_count = 0;

        while (gpiod_line_event_read(line, &event, 0) == 0) {
            if (event.type == GPIOD_LINE_EVENT_RISING_EDGE) {
                pulse_count++;
                last_pulse_time = time(NULL);
                no_pulse_count = 0;
                event_count++;
            } else if (event.type == GPIOD_LINE_EVENT_FALLING_EDGE) {
                // Ignore falling edge
            }
        }

        if (event_count > 0) {
            // Calculate flow rate
            int current_time = time(NULL);
            int elapsed = current_time - last_pulse_time;
            if (elapsed > 0) {
                flow_rate = (pulse_count * LITERS_PER_PULSE * 60) / elapsed;
            }
        } else {
            no_pulse_count++;
            if (no_pulse_count > MAX_NO_PULSE_TIME) {
                printf("No pulses detected for %d seconds. Sensor may be disconnected.\n", MAX_NO_PULSE_TIME);
                no_pulse_count = 0;
            }
        }

        set_cursor(i2c_fd, 0, 0);
        write_string(i2c_fd, LCD_LINE1);

        char flow_str[10];
        snprintf(flow_str, sizeof(flow_str), "%0.2d", flow_rate);
        set_cursor(i2c_fd, 1, 0);
        write_string(i2c_fd, flow_str);

        usleep(100000); // 100ms delay
    }

    cleanup(&state);
    return 0;
}

