#include <signal.h>
#include <errno.h>

#define ROW_COUNT 8
#define COL_COUNT 8
#define DELAY_US 800
#define FRAME_DELAY_MS 100

// GPIO pin numbers (BCM)
int row_pins[ROW_COUNT] = {17, 18, 27, 22, 23, 24, 25, 4};
int col_pins[COL_COUNT] = {5, 6, 12, 13, 19, 16, 26, 20};

// Global variables for GPIO access
int *gpio_map;
int gpio_fd;
int row_gpio_fd[ROW_COUNT];
int col_gpio_fd[COL_COUNT];

// Animation patterns
int pattern_left[ROW_COUNT][COL_COUNT];
int pattern_right[ROW_COUNT][COL_COUNT];

// Signal handler for graceful shutdown
volatile int running = 1;

void handle_signal(int sig) {
    running = 0;
}

void init_gpio(int pin, int direction) {
    int fd;
    struct gpiohandle_request req;
    struct gpiohandle_data data;

    fd = open("/dev/gpiochip0", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    req.lineoffsets = &pin;
    req.lines = 1;
    req.flags = GPIOHANDLE_REQUEST_OUTPUT;
    req.consumer_label = "led_matrix";

    if (ioctl(fd, GPIO_GET_LINEHANDLE_IOCTL, &req) < 0) {
        fprintf(stderr, "Failed to get GPIO line handle: %s\n", strerror(errno));
        close(fd);
        exit(EXIT_FAILURE);
    }

    gpio_map = req.handle;
    data.values[0] = direction;
    if (ioctl(req.handle, GPIOHANDLE_SET_LINE_VALUES_IOCTL, &data) < 0) {
        fprintf(stderr, "Failed to set GPIO line value: %s\n", strerror(errno));
        close(req.handle);
        close(fd);
        exit(EXIT_FAILURE);
    }

    close(fd);
}

void set_gpio(int pin, int value) {
    struct gpiohandle_data data;
    data.values[0] = value;
    if (ioctl(gpio_map, GPIOHANDLE_SET_LINE_VALUES_IOCTL, &data) < 0) {
        fprintf(stderr, "Failed to set GPIO line value: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }
}

void cleanup_gpio() {
    for (int i = 0; i < ROW_COUNT; i++) {
        set_gpio(row_pins[i], 0);
    }
    for (int i = 0; i < COL_COUNT; i++) {
        set_gpio(col_pins[i], 1);
    }
    close(gpio_map);
}

void init_patterns() {
    for (int r = 0; r < ROW_COUNT; r++) {
        for (int c = 0; c < COL_COUNT; c++) {
            pattern_left[r][c] = 0;
            pattern_right[r][c] = 0;
        }
    }

    for (int i = 0; i < COL_COUNT; i++) {
        pattern_left[0][i] = 1;
        pattern_right[0][COL_COUNT - 1 - i] = 1;
    }
}

void render_frame(int *pattern) {
    for (int r = 0; r < ROW_COUNT; r++) {
        set_gpio(row_pins[r], 1);
        for (int c = 0; c < COL_COUNT; c++) {
            if (pattern[r][c]) {
                set_gpio(col_pins[c], 0);
            } else {
                set_gpio(col_pins[c], 1);
            }
        }
        usleep(DELAY_US);
        set_gpio(row_pins[r], 0);
    }
}

void animate() {
    int frame = 0;
    while (running) {
        for (int i = 0; i < COL_COUNT; i++) {
            for (int r = 0; r < ROW_COUNT; r++) {
                pattern_left[r][i] = 0;
            }
            pattern_left[0][i] = 1;
            pattern_left[ROW_COUNT - 1][i] = 1;
            render_frame(pattern_left);
        }

        for (int i = 0; i < COL_COUNT; i++) {
            for (int r = 0; r < ROW_COUNT; r++) {
                pattern_right[r][i] = 0;
            }
            pattern_right[0][i] = 1;
            pattern_right[ROW_COUNT - 1][i] = 1;
            render_frame(pattern_right);
        }

        usleep(FRAME_DELAY_MS * 1000);
    }
}

int main() {
    signal(SIGINT, handle_signal);

    // Initialize GPIO
    for (int i = 0; i < ROW_COUNT; i++) {
        init_gpio(row_pins[i], 0);
    }
    for (int i = 0; i < COL_COUNT; i++) {
        init_gpio(col_pins[i], 1);
    }

    init_patterns();

    animate();

    cleanup_gpio();

    return 0;
}

