#include <gpiod.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <fcntl.h>
#include <errno.h>

#define I2C_BUS 1
#define I2C_ADDR 0x29
#define I2C_DEVICE "/dev/i2c-%d"
#define MODEL_ID_REGISTER 0x00
#define MODEL_ID_EXPECTED 0x3C3C

#define POLLING_INTERVAL_MS 100
#define MAX_TARGETS 10
#define TARGET_DATA_SIZE 16

typedef struct {
    uint16_t distance_mm;
    uint16_t confidence;
    uint16_t status;
} TargetData;

volatile int running = 1;

void handle_signal(int sig) {
    running = 0;
}

void i2c_init(int *fd) {
    char device_path[32];
    snprintf(device_path, sizeof(device_path), I2C_DEVICE, I2C_BUS);

    *fd = open(device_path, O_RDWR);
    if (*fd < 0) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }

    if (ioctl(*fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(*fd);
        exit(EXIT_FAILURE);
    }
}

void i2c_write(int fd, uint8_t reg, uint8_t *data, size_t len) {
    uint8_t buffer[len + 1];
    buffer[0] = reg;
    memcpy(buffer + 1, data, len);

    if (write(fd, buffer, len + 1) != len + 1) {
        perror("I2C write failed");
        exit(EXIT_FAILURE);
    }
}

void i2c_read(int fd, uint8_t reg, uint8_t *data, size_t len) {
    if (ioctl(fd, I2C_RDWR, (struct i2c_msg *)data) < 0) {
        perror("I2C read failed");
        exit(EXIT_FAILURE);
    }
}

void verify_model_id(int fd) {
    uint8_t model_id[2];
    i2c_read(fd, MODEL_ID_REGISTER, model_id, 2);

    if (model_id[0] != (MODEL_ID_EXPECTED >> 8) || model_id[1] != (MODEL_ID_EXPECTED & 0xFF)) {
        fprintf(stderr, "Sensor model ID mismatch. Expected 0x%04X, got 0x%02X%02X\n",
                MODEL_ID_EXPECTED, model_id[0], model_id[1]);
        exit(EXIT_FAILURE);
    }
    printf("Sensor model ID verified: 0x%04X\n", MODEL_ID_EXPECTED);
}

void init_sensor(int fd) {
    // Stub for proprietary firmware download and initialization sequence
    // In a real implementation, this would include complex initialization steps
    // as per the VL53L3CX datasheet and firmware documentation.
    printf("Initializing VL53L3CX sensor...\n");
    // Example: Reset the sensor
    i2c_write(fd, 0x0100, (uint8_t[]){0x01}, 1);
    usleep(100000); // 100ms delay
    verify_model_id(fd);
    printf("Sensor initialized successfully.\n");
}

void read_targets(int fd, TargetData *targets, size_t *num_targets) {
    uint8_t data[TARGET_DATA_SIZE * MAX_TARGETS];
    size_t data_len = sizeof(data);

    i2c_read(fd, 0x0000, data, data_len);

    *num_targets = 0;
    for (size_t i = 0; i < MAX_TARGETS; i++) {
        if (data[i * TARGET_DATA_SIZE + 0] == 0x00 && data[i * TARGET_DATA_SIZE + 1] == 0x00) {
            break;
        }
        TargetData *target = &targets[*num_targets];
        target->distance_mm = (data[i * TARGET_DATA_SIZE + 2] << 8) | data[i * TARGET_DATA_SIZE + 3];
        target->confidence = (data[i * TARGET_DATA_SIZE + 4] << 8) | data[i * TARGET_DATA_SIZE + 5];
        target->status = (data[i * TARGET_DATA_SIZE + 6] << 8) | data[i * TARGET_DATA_SIZE + 7];
        (*num_targets)++;
    }
}

void print_timestamped_distances(TargetData *targets, size_t num_targets) {
    time_t now;
    struct tm *timeinfo;
    char timestamp[64];

    time(&now);
    timeinfo = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S.%03dZ", timeinfo);

    printf("%s", timestamp);
    for (size_t i = 0; i < num_targets; i++) {
        printf(" Target %zu: Distance=%u mm, Confidence=%u, Status=0x%04X",
               i + 1, targets[i].distance_mm, targets[i].confidence, targets[i].status);
    }
    printf("\n");
}

void cleanup(int fd) {
    close(fd);
    printf("Sensor resources released.\n");
}

int main() {
    int i2c_fd = -1;
    TargetData targets[MAX_TARGETS];
    size_t num_targets = 0;

    signal(SIGINT, handle_signal);

    i2c_init(&i2c_fd);
    init_sensor(i2c_fd);

    while (running) {
        read_targets(i2c_fd, targets, &num_targets);
        print_timestamped_distances(targets, num_targets);
        usleep(POLLING_INTERVAL_MS * 1000);
    }

    cleanup(i2c_fd);
    return 0;
}

