#define CSV_HEADER "timestamp,distance\n"

typedef struct {
    int i2c_fd;
    FILE *log_file;
    int running;
} app_state;

void handle_signal(int sig) {
    if (sig == SIGINT) {
        printf("Received SIGINT, shutting down...\n");
        app_state *state = (app_state *)malloc(sizeof(app_state));
        state->running = 0;
        free(state);
    }
}

void log_error(const char *msg, int err) {
    fprintf(stderr, "Error: %s: %s\n", msg, strerror(err));
}

void close_i2c(int *fd) {
    if (*fd >= 0) {
        close(*fd);
        *fd = -1;
    }
}

void close_log_file(FILE **file) {
    if (*file != NULL) {
        fclose(*file);
        *file = NULL;
    }
}

int open_i2c(int bus) {
    int fd = -1;
    char filename[20];
    snprintf(filename, sizeof(filename), "/dev/i2c-%d", bus);
    fd = open(filename, O_RDWR);
    if (fd < 0) {
        log_error("Opening I2C bus", errno);
        return -1;
    }

    int addr = I2C_ADDR;
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        log_error("Setting I2C slave address", errno);
        close(fd);
        return -1;
    }

    return fd;
}

int read_register(int fd, uint8_t reg, uint8_t *val) {
    if (fd < 0) {
        log_error("Invalid I2C file descriptor", EINVAL);
        return -1;
    }

    uint8_t buf[1];
    buf[0] = reg;
    if (write(fd, buf, 1) < 0) {
        log_error("Writing to I2C register", errno);
        return -1;
    }

    if (read(fd, buf, 1) < 0) {
        log_error("Reading from I2C register", errno);
        return -1;
    }

    *val = buf[0];
    return 0;
}

int read_distance(int fd, int *distance) {
    uint8_t status;
    if (read_register(fd, MLX75031_REGISTER_STATUS, &status) < 0) {
        return -1;
    }

    if ((status & 0x01) == 0) {
        return -1;
    }

    uint8_t data[2];
    if (read_register(fd, MLX75031_REGISTER_DISTANCE, &data[0]) < 0) {
        return -1;
    }

    if (read_register(fd, MLX75031_REGISTER_DISTANCE + 1, &data[1]) < 0) {
        return -1;
    }

    *distance = (data[0] << 8) | data[1];
    return 0;
}

int open_log_file(const char *filename, FILE **file) {
    *file = fopen(filename, "a");
    if (*file == NULL) {
        log_error("Opening log file", errno);
        return -1;
    }

    return 0;
}

int write_csv_row(FILE *file, const char *timestamp, int distance) {
    if (file == NULL) {
        log_error("Invalid log file pointer", EINVAL);
        return -1;
    }

    if (fprintf(file, "%s,%d\n", timestamp, distance) < 0) {
        log_error("Writing to log file", errno);
        return -1;
    }

    return 0;
}

int main() {
    app_state state = {0};
    state.running = 1;

    signal(SIGINT, handle_signal);

    state.i2c_fd = open_i2c(I2C_BUS);
    if (state.i2c_fd < 0) {
        log_error("Failed to initialize I2C interface", errno);
        return 1;
    }

    state.log_file = NULL;
    if (open_log_file("depth_log.csv", &state.log_file) < 0) {
        log_error("Failed to open log file", errno);
        close_i2c(&state.i2c_fd);
        return 1;
    }

    while (state.running) {
        char timestamp[30];
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

        int distance = -1;
        if (read_distance(state.i2c_fd, &distance) < 0) {
            printf("I2C read failed, logging -1 and retrying...\n");
            write_csv_row(state.log_file, timestamp, -1);
        } else {
            write_csv_row(state.log_file, timestamp, distance);
        }

        sleep(100 / 1000); // 100 ms
    }

    close_i2c(&state.i2c_fd);
    close_log_file(&state.log_file);

    return 0;
}

