typedef struct {
    int fd;
    FILE *log_file;
    int running;
} sensor_context;

void handle_sigint(int sig) {
    if (sig == SIGINT) {
        sensor_context *ctx = (sensor_context *)malloc(sizeof(sensor_context));
        if (ctx) {
            ctx->running = 0;
            if (ctx->log_file) {
                fflush(ctx->log_file);
                fclose(ctx->log_file);
            }
            if (ctx->fd >= 0) {
                close(ctx->fd);
            }
            free(ctx);
        }
        exit(EXIT_SUCCESS);
    }
}

int i2c_init(int bus, int addr) {
    char filename[20];
    snprintf(filename, sizeof(filename), "/dev/i2c-%d", bus);
    int fd = open(filename, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Failed to set I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

int i2c_read(int fd, uint8_t reg, uint8_t *data, size_t len) {
    uint8_t buf[1];
    buf[0] = reg;
    if (write(fd, buf, 1) < 0) {
        perror("I2C write failed");
        return -1;
    }

    if (read(fd, data, len) < 0) {
        perror("I2C read failed");
        return -1;
    }

    return 0;
}

void log_data(sensor_context *ctx, uint16_t proximity, uint16_t ambient) {
    char timestamp[30];
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

    fprintf(ctx->log_file, "%s,%d,%d\n", timestamp, proximity, ambient);
    fflush(ctx->log_file);
}

void init_log_file(sensor_context *ctx) {
    ctx->log_file = fopen(LOG_FILE, "a");
    if (!ctx->log_file) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }
}

void cleanup(sensor_context *ctx) {
    if (ctx->log_file) {
        fflush(ctx->log_file);
        fclose(ctx->log_file);
    }
    if (ctx->fd >= 0) {
        close(ctx->fd);
    }
    free(ctx);
}

int main() {
    sensor_context *ctx = (sensor_context *)malloc(sizeof(sensor_context));
    if (!ctx) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    ctx->fd = i2c_init(I2C_BUS, I2C_ADDR);
    if (ctx->fd < 0) {
        fprintf(stderr, "I2C initialization failed\n");
        cleanup(ctx);
        exit(EXIT_FAILURE);
    }

    init_log_file(ctx);

    signal(SIGINT, handle_sigint);

    ctx->running = 1;
    while (ctx->running) {
        uint8_t prox_data[2];
        uint8_t amb_data[2];

        if (i2c_read(ctx->fd, CMD_GET_PROX, prox_data, sizeof(prox_data)) < 0) {
            fprintf(stderr, "Failed to read proximity data\n");
        } else {
            uint16_t proximity = (prox_data[0] << 8) | prox_data[1];
            log_data(ctx, proximity, 0);
        }

        if (i2c_read(ctx->fd, CMD_GET_AMBIENT, amb_data, sizeof(amb_data)) < 0) {
            fprintf(stderr, "Failed to read ambient light data\n");
        } else {
            uint16_t ambient = (amb_data[0] << 8) | amb_data[1];
            log_data(ctx, 0, ambient);
        }

        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    cleanup(ctx);
    return 0;
}

