#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define GPIO_PIN_SENSOR 4
#define GPIO_PIN_LED 17
#define POLL_INTERVAL_MS 100
#define LED_BLINK_DURATION_MS 100
#define LOG_FILE "proximity.log"

typedef enum {
    STATE_IDLE,
    STATE_DETECTED
} state_t;

static gpiod_line *sensor_line = NULL;
static gpiod_line *led_line = NULL;
static gpiod_chip *chip = NULL;
static state_t state = STATE_IDLE;

void handle_signal(int signum) {
    if (sensor_line) {
        gpiod_line_release(sensor_line);
        sensor_line = NULL;
    }
    if (led_line) {
        gpiod_line_release(led_line);
        led_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    exit(EXIT_SUCCESS);
}

void log_detection() {
    time_t now;
    struct tm *tm_info;
    char timestamp[30];

    time(&now);
    tm_info = gmtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm_info);

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        return;
    }

    fprintf(log_file, "%s Object detected\n", timestamp);
    fclose(log_file);
}

void blink_led() {
    if (!led_line) return;

    int ret = gpiod_line_set_value(led_line, 1);
    if (ret < 0) {
        perror("Failed to set LED high");
        return;
    }

    usleep(LED_BLINK_DURATION_MS * 1000);

    ret = gpiod_line_set_value(led_line, 0);
    if (ret < 0) {
        perror("Failed to set LED low");
        return;
    }
}

void init_gpio() {
    const char *chip_name = "gpiochip0";
    chip = gpiod_chip_open_by_name(chip_name);
    if (!chip) {
        perror("Failed to open default GPIO chip");
        fprintf(stderr, "Falling back to 'gpiochip0'...\n");
        chip = gpiod_chip_open_by_name("gpiochip0");
        if (!chip) {
            fprintf(stderr, "Failed to open GPIO chip\n");
            exit(EXIT_FAILURE);
        }
    }

    sensor_line = gpiod_chip_get_line(chip, GPIO_PIN_SENSOR);
    if (!sensor_line) {
        perror("Failed to get sensor line");
        exit(EXIT_FAILURE);
    }

    led_line = gpiod_chip_get_line(chip, GPIO_PIN_LED);
    if (!led_line) {
        perror("Failed to get LED line");
        exit(EXIT_FAILURE);
    }

    int ret = gpiod_line_request_output(sensor_line, "sensor", GPIOD_LINE_REQUEST_OUTPUT_ACTIVE_LOW);
    if (ret < 0) {
        perror("Failed to request sensor line");
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_request_output(led_line, "led", GPIOD_LINE_REQUEST_OUTPUT_ACTIVE_LOW);
    if (ret < 0) {
        perror("Failed to request LED line");
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_set_value(sensor_line, 1);
    if (ret < 0) {
        perror("Failed to set sensor line high");
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_set_value(led_line, 0);
    if (ret < 0) {
        perror("Failed to set LED line low");
        exit(EXIT_FAILURE);
    }
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if (init_gpio() != 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        exit(EXIT_FAILURE);
    }

    int last_state = 1; // Assume initial state is HIGH
    struct timespec ts = {0, 0};

    while (1) {
        nanosleep(&ts, &ts);

        int current_state = gpiod_line_get_value(sensor_line);
        if (current_state < 0) {
            perror("Failed to read sensor line");
            break;
        }

        if (current_state == 0 && last_state == 1) {
            // Falling edge detected
            log_detection();
            blink_led();
            state = STATE_DETECTED;
        }

        last_state = current_state;

        ts.tv_sec = 0;
        ts.tv_nsec = POLL_INTERVAL_MS * 1000000;
    }

    handle_signal(0);
    return 0;
}

