typedef struct {
    int i2c_fd;
    FILE *log_file;
} sensor_context;

void handle_sigint(int sig) {
    if (sig == SIGINT) {
        if (context.log_file) {
            fclose(context.log_file);
            context.log_file = NULL;
        }
        if (context.i2c_fd >= 0) {
            close(context.i2c_fd);
            context.i2c_fd = -1;
        }
        // Call sensor API for cleanup
        // Replace with actual cleanup function
        printf("Cleanup performed.\n");
        exit(EXIT_SUCCESS);
    }
}

int i2c_write(int fd, uint8_t reg, uint8_t val) {
    uint8_t buffer[2];
    buffer[0] = reg;
    buffer[1] = val;
    if (write(fd, buffer, 2) != 2) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

int i2c_read(int fd, uint8_t reg, uint8_t *val) {
    uint8_t buffer[1];
    buffer[0] = reg;
    if (write(fd, buffer, 1) != 1) {
        perror("I2C write failed");
        return -1;
    }
    if (read(fd, buffer, 1) != 1) {
        perror("I2C read failed");
        return -1;
    }
    *val = buffer[0];
    return 0;
}

int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) {
        perror("I2C write failed");
        return -1;
    }
    if (read(fd, buf, len) != len) {
        perror("I2C read failed");
        return -1;
    }
    return 0;
}

int verify_part_id(int fd) {
    uint8_t part_id;
    if (i2c_read(fd, PART_ID_REGISTER, &part_id) != 0) {
        fprintf(stderr, "Failed to read PART_ID register.\n");
        return -1;
    }
    if (part_id != 0x01) {
        fprintf(stderr, "Invalid PART_ID: 0x%02X. Expected 0x01.\n", part_id);
        return -1;
    }
    return 0;
}

void log_data(const char *timestamp, int proximity, int ambient) {
    if (context.log_file) {
        fprintf(context.log_file, "%s,%d,%d\n", timestamp, proximity, ambient);
        fflush(context.log_file);
    }
}

void get_iso_timestamp(char *timestamp, size_t size) {
    time_t now;
    struct tm *tm_info;
    time(&now);
    tm_info = gmtime(&now);
    strftime(timestamp, size, "%Y-%m-%dT%H:%M:%SZ", tm_info);
}

int main() {
    int i2c_fd;
    char i2c_bus_path[32];
    snprintf(i2c_bus_path, sizeof(i2c_bus_path), "/dev/i2c-%d", I2C_BUS);

    context.i2c_fd = open(i2c_bus_path, O_RDWR);
    if (context.i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(context.i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(context.i2c_fd);
        return EXIT_FAILURE;
    }

    if (verify_part_id(context.i2c_fd) != 0) {
        close(context.i2c_fd);
        return EXIT_FAILURE;
    }

    context.log_file = fopen("biometric_data.log", "a");
    if (!context.log_file) {
        perror("Failed to open log file");
        close(context.i2c_fd);
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_sigint);

    while (1) {
        uint8_t proximity_data[2];
        uint8_t ambient_data[2];

        if (i2c_read_block(context.i2c_fd, PROXIMITY_REGISTER, proximity_data, 2) != 0) {
            fprintf(stderr, "Failed to read proximity data.\n");
            sleep(1);
            continue;
        }

        if (i2c_read_block(context.i2c_fd, AMBIENT_REGISTER, ambient_data, 2) != 0) {
            fprintf(stderr, "Failed to read ambient data.\n");
            sleep(1);
            continue;
        }

        int proximity = (proximity_data[0] << 8) | proximity_data[1];
        int ambient = (ambient_data[0] << 8) | ambient_data[1];

        char timestamp[30];
        get_iso_timestamp(timestamp, sizeof(timestamp));
        log_data(timestamp, proximity, ambient);

        sleep(1);
    }

    return EXIT_SUCCESS;
}

