double measure_distance(SensorContext *ctx) {
    double distance_cm = -1.0;
    int echo_state = 0;
    int echo_rise_time = 0;
    int echo_pulse_time = 0;
    int echo_rise_timeout = 0;
    int echo_pulse_timeout = 0;
    int echo_high = 0;

