void read_sensor_data(int fd, SensorData *data) {
    unsigned char reg = 0x96; // APDS9960 RGB data register
    unsigned char buffer[4] = {0};

    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write to I2C device");
        return;
