    int file;
    if ((file = open(bus_path, O_RDWR)) < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    if (ioctl(file, I2C_SLAVE, device_addr) < 0) {
        perror("Failed to set I2C slave address");
        close(file);
        return -1;
