#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/gpio.h>
#include <signal.h>
#include <time.h>
#include <string.h>

#define GPIO_PIN_17 17
#define GPIO_PIN_18 18
#define LOG_FILE "obstacle_log.txt"
#define INTERVAL_MS 100
#define MAX_LOG_LINE 128

typedef struct {
    int fd1;
    int fd2;
    int running;
} gpio_state;

void handle_signal(int sig) {
    if (sig == SIGINT) {
        printf("Received SIGINT, shutting down...\n");
        exit(EXIT_SUCCESS);
    }
}

void log_sensor_data(int sensor1, int sensor2) {
    char log_line[MAX_LOG_LINE];
    time_t now = time(NULL);
    struct tm *tm_now = localtime(&now);

    strftime(log_line, sizeof(log_line), "%Y-%m-%d %H:%M:%S", tm_now);
    snprintf(log_line + strlen(log_line), sizeof(log_line) - strlen(log_line),
             ", %d, %d\n", sensor1, sensor2);

    FILE *file = fopen(LOG_FILE, "a");
    if (file) {
        fwrite(log_line, 1, strlen(log_line), file);
        fclose(file);
    } else {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
    }
}

int setup_gpio(int pin) {
    int fd = open("/dev/gpiochip0", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    if (ioctl(fd, GPIO_GET_LINEHANDLE_IOCTL, &pin) < 0) {
        fprintf(stderr, "Failed to get line handle for GPIO %d: %s\n", pin, strerror(errno));
        close(fd);
        return -1;
    }

    if (ioctl(fd, GPIO_LINE_SET_FLAGS, GPIO_LINE_FLAG_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output: %s\n", pin, strerror(errno));
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

int read_gpio(int pin) {
    int fd = open("/dev/gpiochip0", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        return -1;
