#include <gpiod.h>

#define I2C_BUS 1
#define I2C_ADDR 0x20
#define LED_PIN 17
#define LOG_FILE "distance_log.txt"
#define DISTANCE_THRESHOLD_CM 20
#define SAMPLE_INTERVAL_MS 100

typedef enum {
    SENSOR_OK,
    SENSOR_NOT_FOUND,
    I2C_ERROR,
    FILE_ERROR
} sensor_status;

typedef struct {
    int i2c_fd;
    struct gpiod_line *led_line;
    FILE *log_file;
    int running;
} app_state;

void handle_signal(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        app_state *state = (app_state *)malloc(sizeof(app_state));
        state->running = 0;
        free(state);
    }
}

void log_error(const char *message, sensor_status status) {
    fprintf(stderr, "Error: %s\n", message);
    switch (status) {
        case SENSOR_OK:
            break;
        case SENSOR_NOT_FOUND:
            fprintf(stderr, "Sensor not found on I2C bus.\n");
            break;
        case I2C_ERROR:
            fprintf(stderr, "I2C communication error.\n");
            break;
        case FILE_ERROR:
            fprintf(stderr, "File operation error.\n");
            break;
    }
}

void close_resources(app_state *state) {
    if (state->i2c_fd >= 0) {
        close(state->i2c_fd);
    }
    if (state->led_line) {
        gpiod_line_release(state->led_line);
    }
    if (state->log_file) {
        fclose(state->log_file);
    }
}

int init_i2c(int bus, int addr) {
    char filename[20];
    snprintf(filename, sizeof(filename), "/dev/i2c-%d", bus);
    int fd = open(filename, O_RDWR);
    if (fd < 0) {
        log_error("Failed to open I2C bus", I2C_ERROR);
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        log_error("Failed to set I2C slave address", I2C_ERROR);
        close(fd);
        return -1;
    }

    return fd;
}

int read_distance(int i2c_fd) {
    unsigned char cmd[2] = {0x00, 0x00}; // Command to read distance
    if (write(i2c_fd, cmd, 2) != 2) {
        log_error("I2C write error", I2C_ERROR);
        return -1;
    }

    usleep(1000); // Wait for response

    unsigned char data[2];
    if (read(i2c_fd, data, 2) != 2) {
        log_error("I2C read error", I2C_ERROR);
        return -1;
    }

    // Convert to distance in cm
    int distance = (data[0] << 8) | data[1];
    distance = distance / 58; // Convert to cm
    return distance;
}

int init_gpio(int pin) {
    struct gpiod_chip *chip;
    struct gpiod_line *line;

    chip = gpiod_chip_open_by_number(4); // BCM2835 uses chip 4
    if (!chip) {
        log_error("Failed to open GPIO chip", I2C_ERROR);
        return -1;
    }

    line = gpiod_line_get(chip, pin);
    if (!line) {
        log_error("Failed to get GPIO line", I2C_ERROR);
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(line, "led", 0) < 0) {
        log_error("Failed to request GPIO line", I2C_ERROR);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return -1;
    }

    return line;
}

void log_distance(int distance) {
    time_t now;
    struct tm *timeinfo;
    char timestamp[64];

    time(&now);
    timeinfo = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

    fprintf(stdout, "Logged distance: %d cm at %s\n", distance, timestamp);

    if (app_state.log_file) {
        fprintf(app_state.log_file, "%s,%d\n", timestamp, distance);
        fflush(app_state.log_file);
    }
}

int main() {
    app_state state = {0};

    // Initialize signal handling
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Initialize I2C
    state.i2c_fd = init_i2c(I2C_BUS, I2C_ADDR);
    if (state.i2c_fd < 0) {
        close_resources(&state);
        return 1;
    }

    // Initialize GPIO
    state.led_line = init_gpio(LED_PIN);
    if (!state.led_line) {
        close_resources(&state);
        return 1;
    }

    // Initialize log file
    state.log_file = fopen(LOG_FILE, "a");
    if (!state.log_file) {
        log_error("Failed to open log file", FILE_ERROR);
        close_resources(&state);
        return 1;
    }

    state.running = 1;

    while (state.running) {
        int distance = read_distance(state.i2c_fd);
        if (distance < 0) {
            log_error("Failed to read distance", I2C_ERROR);
            break;
        }

        log_distance(distance);

        if (distance < DISTANCE_THRESHOLD_CM) {
            gpiod_line_set_value(state.led_line, 1);
        } else {
            gpiod_line_set_value(state.led_line, 0);
        }

        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    close_resources(&state);
    return 0;
}

