#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>

#define I2C_BUS 1
#define I2C_ADDR 0x60
#define MAX_RETRIES 3
#define LOG_FILE "biometric_log.txt"

typedef struct {
    int fd;
    FILE *log_file;
    int retry_count;
} i2c_context;

void handle_sigint(int sig) {
    if (sig == SIGINT) {
        printf("\nCaught SIGINT, cleaning up...\n");
        if (i2c_context.fd >= 0) {
            close(i2c_context.fd);
        }
        if (i2c_context.log_file) {
            fclose(i2c_context.log_file);
        }
        exit(EXIT_SUCCESS);
    }
}

int i2c_read(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    int ret;
    uint8_t buffer[1 + len];

    buffer[0] = reg;
    ret = write(fd, buffer, 1);
    if (ret != 1) {
        fprintf(stderr, "I2C write error: %d\n", ret);
        return -1;
    }

    ret = read(fd, buffer + 1, len);
    if (ret != len) {
        fprintf(stderr, "I2C read error: %d\n", ret);
        return -1;
    }

    memcpy(buf, buffer + 1, len);
    return 0;
}

int i2c_write(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    uint8_t buffer[len + 1];
    buffer[0] = reg;
    memcpy(buffer + 1, buf, len);

    int ret = write(fd, buffer, len + 1);
    if (ret != len + 1) {
        fprintf(stderr, "I2C write error: %d\n", ret);
        return -1;
    }
    return 0;
}

int i2c_init(int bus, int addr) {
    char filename[20];
    snprintf(filename, sizeof(filename), "/dev/i2c-%d", bus);
    int fd = open(filename, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Failed to set I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

void log_data(uint16_t proximity, uint16_t ambient) {
    time_t now = time(NULL);
    struct tm *tm_now = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_now);

    fprintf(i2c_context.log_file, "%s, %d, %d\n", timestamp, proximity, ambient);
    fflush(i2c_context.log_file);
}

int main() {
    i2c_context.context = (i2c_context){0};

    // Initialize I2C
    i2c_context.fd = i2c_init(I2C_BUS, I2C_ADDR);
    if (i2c_context.fd < 0) {
        fprintf(stderr, "Failed to initialize I2C\n");
        return EXIT_FAILURE;
    }

    // Open log file
    i2c_context.log_file = fopen(LOG_FILE, "a");
    if (!i2c_context.log_file) {
        perror("Failed to open log file");
        close(i2c_context.fd);
        return EXIT_FAILURE;
    }

    // Set up signal handler
    signal(SIGINT, handle_sigint);

    uint8_t reg = 0x00;
    uint8_t data[2];
    uint16_t proximity, ambient;

    while (1) {
        int retries = 0;
        int success = 0;

        while (retries < MAX_RETRIES && !success) {
            // Read proximity data
            if (i2c_read(i2c_context.fd, 0x00, data, 2) == 0) {
                proximity = (data[0] << 8) | data[1];
                success = 1;
            } else {
                retries++;
                usleep(100000); // 100ms delay
            }
        }

        if (!success) {
            fprintf(stderr, "Failed to read proximity data after %d retries\n", MAX_RETRIES);
            usleep(500000); // 500ms delay
            continue;
        }

        retries = 0;
        success = 0;

        while (retries < MAX_RETRIES && !success) {
            // Read ambient light data
            if (i2c_read(i2c_context.fd, 0x02, data, 2) == 0) {
                ambient = (data[0] << 8) | data[1];
                success = 1;
            } else {
                retries++;
                usleep(100000); // 100ms delay
            }
        }

        if (!success) {
            fprintf(stderr, "Failed to read ambient light data after %d retries\n", MAX_RETRIES);
            usleep(500000); // 500ms delay
            continue;
        }

        log_data(proximity, ambient);
        usleep(500000); // 500ms delay
    }

    // This point is unreachable due to the infinite loop
    fclose(i2c_context.log_file);
    close(i2c_context.fd);
    return EXIT_SUCCESS;
}

