#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define SENSOR_ADDR 0x29
#define CMD_HEADER 0x55
#define CMD_SIZE 4
#define RESP_SIZE 15
#define MAX_DISTANCE_MM 1000
#define SAMPLE_COUNT 10
#define CYCLE_DELAY_MS 100
#define LOG_FILE "intrusion_log.txt"

typedef struct {
    int fd;
    FILE *log_file;
    int running;
} app_state;

void handle_signal(int sig) {
    app_state *state = (app_state *)malloc(sizeof(app_state));
    if (state) {
        state->running = 0;
        free(state);
    }
}

void close_resources(app_state *state) {
    if (state->log_file) {
        fclose(state->log_file);
    }
    if (state->fd >= 0) {
        close(state->fd);
    }
    free(state);
}

void log_intrusion(const char *timestamp, int avg_distance_mm) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file) {
        fprintf(log_file, "%s,%d\n", timestamp, avg_distance_mm);
        fclose(log_file);
    }
}

int i2c_write(int fd, uint8_t *cmd, size_t len) {
    if (write(fd, cmd, len) != len) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

int i2c_read(int fd, uint8_t *buf, size_t len) {
    if (read(fd, buf, len) != len) {
        perror("I2C read failed");
        return -1;
    }
    return 0;
}

void send_command(int fd) {
    uint8_t cmd[CMD_SIZE] = {0x55, 0x00, 0x00, 0x00};
    if (i2c_write(fd, cmd, CMD_SIZE) != 0) {
        fprintf(stderr, "Failed to send command\n");
    }
}

void read_response(int fd, uint8_t *response) {
    if (i2c_read(fd, response, RESP_SIZE) != 0) {
        fprintf(stderr, "Failed to read response\n");
    }
}

int main() {
    app_state *state = (app_state *)malloc(sizeof(app_state));
    if (!state) {
        fprintf(stderr, "Memory allocation failed\n");
        return 1;
    }

    state->fd = -1;
    state->log_file = NULL;
    state->running = 1;

    // Set up signal handler
    signal(SIGINT, handle_signal);

    // Open I2C bus
    state->fd = open(I2C_BUS, O_RDWR);
    if (state->fd < 0) {
        perror("Failed to open I2C bus");
        close_resources(state);
        return 1;
    }

    // Set I2C slave address
    if (ioctl(state->fd, I2C_SLAVE, SENSOR_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close_resources(state);
        return 1;
    }

    // Open log file
    state->log_file = fopen(LOG_FILE, "a");
    if (!state->log_file) {
        perror("Failed to open log file");
        close_resources(state);
        return 1;
    }

    while (state->running) {
        uint8_t response[RESP_SIZE];
        int distances[SAMPLE_COUNT];
        int total_distance = 0;

        for (int i = 0; i < SAMPLE_COUNT; i++) {
            send_command(state->fd);
            usleep(10000); // Wait 10 ms
            read_response(state->fd, response);

            if (response[0] != CMD_HEADER) {
                fprintf(stderr, "Invalid response header\n");
                continue;
            }

            uint16_t distance = (response[11] << 8) | response[12];
            if (distance > 0) {
                distances[i] = distance;
                total_distance += distance;
            } else {
                fprintf(stderr, "Invalid distance value\n");
            }
        }

        int avg_distance = total_distance / SAMPLE_COUNT;
        if (avg_distance < MAX_DISTANCE_MM) {
            char timestamp[20];
            time_t now = time(NULL);
            struct tm *tm_info = localtime(&now);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);
            log_intrusion(timestamp, avg_distance);
        }

        usleep(CYCLE_DELAY_MS * 1000); // 100 ms delay
    }

    close_resources(state);
    return 0;
}

