        fprintf(stderr, "Failed to set I2C slave address: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    if (ioctl(fd, I2C_TIMEOUT, I2C_TIMEOUT_MS) < 0) {
        fprintf(stderr, "Failed to set I2C timeout: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    if (write(fd, &reg, sizeof(reg)) != sizeof(reg)) {
        fprintf(stderr, "Failed to write register address: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    if (read(fd, buf, len) != len) {
        fprintf(stderr, "Failed to read from I2C device: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }
}

void i2c_write_register(int fd, uint16_t reg, uint8_t *buf, size_t len) {
    if (ioctl(fd, I2C_SLAVE, I2C_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    if (ioctl(fd, I2C_TIMEOUT, I2C_TIMEOUT_MS) < 0) {
        fprintf(stderr, "Failed to set I2C timeout: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    uint8_t reg_buf[2];
    reg_buf[0] = reg >> 8;
    reg_buf[1] = reg & 0xFF;

    if (write(fd, reg_buf, sizeof(reg_buf)) != sizeof(reg_buf)) {
        fprintf(stderr, "Failed to write register address: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    if (write(fd, buf, len) != len) {
        fprintf(stderr, "Failed to write to I2C device: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }
}

