    if (fd < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    if (ioctl(fd, I2C_TIMEOUT, I2C_TIMEOUT_MS) < 0) {
        fprintf(stderr, "Failed to set I2C timeout: %s\n", strerror(errno));
        close(fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(fd, I2C_SLAVE, I2C_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address: %s\n", strerror(errno));
        close(fd);
        exit(EXIT_FAILURE);
    }

    return fd;
}

void check_model_id(int fd) {
    uint16_t model_id;
    uint8_t model_id_buf[2];

    i2c_read_register(fd, MODEL_ID_REGISTER, model_id_buf, sizeof(model_id_buf));
    model_id = (model_id_buf[0] << 8) | model_id_buf[1];

    if (model_id != MODEL_ID_VALUE) {
        fprintf(stderr, "Sensor model ID mismatch: expected 0xEA00, got 0x%04X\n", model_id);
        exit(EXIT_FAILURE);
    }
}

