    uint8_t status;
    i2c_read_register(fd, RESULT_INTERRUPT_STATUS_REGISTER, &status, sizeof(status));

    if (status & 0x01) {
        uint16_t distance;
        uint8_t distance_buf[2];

        i2c_read_register(fd, 0x001C, distance_buf, sizeof(distance_buf));
        distance = (distance_buf[0] << 8) | distance_buf[1];

        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

        printf("Distance: %d mm\n", distance);
    }
}

int main() {
    app_state state = {0};
    state.running = 1;

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    int i2c_fd = i2c_init();
    check_model_id(i2c_fd);

    while (state.running) {
        poll_result_interrupt_status(i2c_fd);

        usleep(500000); // 500 ms
    }

    close(i2c_fd);
    return 0;
}

