#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

#define I2C_BUS 1
#define I2C_ADDR 0x60
#define PROX_DATA_REGISTER 0x0C
#define PROX_DATA_LENGTH 2
#define POLL_INTERVAL_MS 500
#define MAX_RETRIES 3

typedef struct {
    int fd;
    int retry_count;
} i2c_context;

void i2c_init(i2c_context *ctx) {
    char bus_path[20];
    snprintf(bus_path, sizeof(bus_path), "/dev/i2c-%d", I2C_BUS);

    ctx->fd = open(bus_path, O_RDWR);
    if (ctx->fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    if (ioctl(ctx->fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(ctx->fd);
        exit(EXIT_FAILURE);
    }

    ctx->retry_count = 0;
}

void i2c_read_proximity(i2c_context *ctx, uint16_t *data) {
    uint8_t buffer[PROX_DATA_LENGTH];
    ssize_t bytes_read;

    for (int i = 0; i < MAX_RETRIES; i++) {
        bytes_read = read(ctx->fd, buffer, PROX_DATA_LENGTH);
        if (bytes_read == PROX_DATA_LENGTH) {
            *data = (buffer[0] << 8) | buffer[1];
            return;
        } else if (bytes_read < 0) {
            if (errno == EAGAIN || errno == EIO) {
                fprintf(stderr, "I2C read error (EAGAIN/EIO), retrying...\n");
                usleep(100000);  // 100ms delay
                continue;
            } else {
                fprintf(stderr, "I2C read error: %s\n", strerror(errno));
                exit(EXIT_FAILURE);
            }
        } else {
            fprintf(stderr, "I2C read returned %zd bytes, expected %d\n", bytes_read, PROX_DATA_LENGTH);
            exit(EXIT_FAILURE);
        }
    }

    fprintf(stderr, "Failed to read proximity data after %d retries\n", MAX_RETRIES);
    exit(EXIT_FAILURE);
}

void i2c_close(i2c_context *ctx) {
    if (ctx->fd >= 0) {
        close(ctx->fd);
    }
}

void handle_sigint(int sig) {
    printf("\nCaught SIGINT, cleaning up...\n");
    i2c_close(&ctx);
    exit(EXIT_SUCCESS);
}

int main() {
    i2c_context ctx;
    uint16_t proximity_data;
    struct sigaction sa;

    // Initialize signal handler
    sa.sa_handler = handle_sigint;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("Failed to set SIGINT handler");
        exit(EXIT_FAILURE);
    }

    // Initialize I2C
    if (i2c_init(&ctx) < 0) {
        exit(EXIT_FAILURE);
    }

    printf("Starting I2C proximity sensor read loop...\n");

    while (1) {
        // Check for sensor presence by attempting a write
        if (ioctl(ctx.fd, I2C_SLAVE, I2C_ADDR) < 0) {
            if (errno == ENOTCONN) {
                fprintf(stderr, "Sensor not connected (NACK on write), exiting...\n");
                break;
            } else {
                fprintf(stderr, "Failed to re-establish I2C connection: %s\n", strerror(errno));
                break;
            }
        }

        // Read proximity data
        i2c_read_proximity(&ctx, &proximity_data);
        printf("Proximity data: 0x%04X (%d)\n", proximity_data, proximity_data);

        // Sleep for 500ms
        usleep(POLL_INTERVAL_MS * 1000);
    }

    i2c_close(&ctx);
    return 0;
}

