#include <string.h>
#include <signal.h>
#include <time.h>
#include <errno.h>

#define I2C_BUS 1
#define I2C_ADDR 0x40
#define I2C_REGISTER 0x00
#define I2C_READ_LENGTH 2

int i2c_fd = -1;

void handle_signal(int sig) {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

void i2c_init() {
    char i2c_bus_path[32];
    snprintf(i2c_bus_path, sizeof(i2c_bus_path), "/dev/i2c-%d", I2C_BUS);

    i2c_fd = open(i2c_bus_path, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        exit(1);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        exit(1);
    }

    // Verify device presence
    unsigned char buffer[2];
    if (read(i2c_fd, buffer, I2C_READ_LENGTH) < 0) {
        fprintf(stderr, "I2C device not responding: %s\n", strerror(errno));
        close(i2c_fd);
        exit(1);
    }
}

void read_distance() {
    unsigned char buffer[2];
    if (read(i2c_fd, buffer, I2C_READ_LENGTH) < 0) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return;
    }

    // Extract distance value (assuming 12-bit measurement)
    int distance = (buffer[0] << 8) | buffer[1];
    distance = (distance >> 4) & 0x0FFF; // Mask to 12 bits
    printf("Distance: %d mm\n", distance);
}

int main() {
    // Set up signal handler
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    i2c_init();

    struct timespec sleep_time = {0, 500000000}; // 500 ms

    while (1) {
        read_distance();
        nanosleep(&sleep_time, NULL);
    }

    return 0;
}

