#define CMD_GET_INTERRUPT_STATUS 0xFE
#define CMD_GET_INTERRUPT_MASK 0xFF

typedef struct {
    uint16_t distance;
    uint16_t ambient;
    uint8_t error_flags;
} sensor_data_t;

int i2c_fd = -1;
volatile int running = 1;

void signal_handler(int sig) {
    running = 0;
}

void i2c_init() {
    char device_path[32];
    snprintf(device_path, sizeof(device_path), I2C_DEVICE, I2C_BUS);

    i2c_fd = open(device_path, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
}

void i2c_close() {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
}

int i2c_read_register(uint8_t reg, uint8_t *buf, size_t len) {
    if (i2c_fd < 0) {
        return -1;
    }

    if (write(i2c_fd, &reg, 1) < 0) {
        perror("Failed to write register address");
        return -1;
    }

    if (read(i2c_fd, buf, len) < 0) {
        perror("Failed to read from I2C device");
        return -1;
    }

    return 0;
}

int i2c_write_register(uint8_t reg, uint8_t *buf, size_t len) {
    if (i2c_fd < 0) {
        return -1;
    }

    if (write(i2c_fd, &reg, 1) < 0) {
        perror("Failed to write register address");
        return -1;
    }

    if (write(i2c_fd, buf, len) < 0) {
        perror("Failed to write to I2C device");
        return -1;
    }

    return 0;
}

void read_sensor_data(sensor_data_t *data) {
    uint8_t status[2];
    uint8_t ambient[2];
    uint8_t distance[2];
    uint8_t config[2];
    uint8_t interrupt[2];

    if (i2c_read_register(CMD_GET_STATUS, status, 2) < 0) {
        fprintf(stderr, "Error reading status register\n");
        return;
    }

    if (i2c_read_register(CMD_GET_AMBIENT, ambient, 2) < 0) {
        fprintf(stderr, "Error reading ambient light register\n");
        return;
    }

    if (i2c_read_register(CMD_GET_DISTANCE, distance, 2) < 0) {
        fprintf(stderr, "Error reading distance register\n");
        return;
    }

    if (i2c_read_register(CMD_GET_CONFIG, config, 2) < 0) {
        fprintf(stderr, "Error reading config register\n");
        return;
    }

    if (i2c_read_register(CMD_GET_INTERRUPT, interrupt, 2) < 0) {
        fprintf(stderr, "Error reading interrupt register\n");
        return;
    }

    data->distance = (distance[0] << 8) | distance[1];
    data->ambient = (ambient[0] << 8) | ambient[1];
    data->error_flags = status[0] | status[1];
}

void log_sensor_data(const sensor_data_t *data) {
    printf("Distance: %u mm, Ambient: %u lux, Error Flags: 0x%02X\n",
           data->distance, data->ambient, data->error_flags);
}

int main() {
    signal(SIGINT, signal_handler);

    if (i2c_init() < 0) {
        fprintf(stderr, "Failed to initialize I2C\n");
        return EXIT_FAILURE;
    }

    while (running) {
        sensor_data_t data;
        read_sensor_data(&data);
        log_sensor_data(&data);
        usleep(500000); // 500 ms
    }

    i2c_close();
    return EXIT_SUCCESS;
}
