#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define TRIGGER_DURATION_US 10
#define MAX_ECHO_WAIT_US 200000000
#define MAX_PULSE_DURATION_US 38000
#define POLLING_INTERVAL_MS 1000

typedef enum {
    STATE_IDLE,
    STATE_TRIGGERING,
    STATE_WAITING_RISING,
    STATE_WAITING_FALLING
} state_t;

typedef struct {
    gpiod_line *trigger_line;
    gpiod_line *echo_line;
    state_t state;
    uint64_t start_time;
    uint64_t pulse_duration;
    int running;
} sensor_context_t;

void handle_signal(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        printf("\nShutting down...\n");
        exit(EXIT_SUCCESS);
    }
}

void cleanup(sensor_context_t *context) {
    if (context->trigger_line) {
        gpiod_line_release(context->trigger_line);
    }
    if (context->echo_line) {
        gpiod_line_release(context->echo_line);
    }
    free(context);
}

void trigger_pulse(sensor_context_t *context) {
    gpiod_line_set_value(context->trigger_line, 1);
    usleep(TRIGGER_DURATION_US);
    gpiod_line_set_value(context->trigger_line, 0);
}

uint64_t get_current_time_us() {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return (uint64_t)ts.tv_sec * 1000000 + (uint64_t)ts.tv_nsec / 1000;
}

void wait_for_edge(sensor_context_t *context, int edge, uint64_t timeout_us) {
    uint64_t start_time = get_current_time_us();
    while (get_current_time_us() - start_time < timeout_us) {
        int value = gpiod_line_get_value(context->echo_line);
        if (value == edge) {
            context->start_time = get_current_time_us();
            return;
        }
        usleep(100);
    }
    context->state = STATE_IDLE;
    fprintf(stderr, "Timeout waiting for %s edge on echo pin\n", edge == 1 ? "rising" : "falling");
}

void measure_distance(sensor_context_t *context) {
    context->state = STATE_TRIGGERING;
    trigger_pulse(context);

    context->state = STATE_WAITING_RISING;
    wait_for_edge(context, 1, MAX_ECHO_WAIT_US);

    if (context->state != STATE_IDLE) {
        context->state = STATE_WAITING_FALLING;
        wait_for_edge(context, 0, MAX_ECHO_WAIT_US);

        if (context->state != STATE_IDLE) {
            context->pulse_duration = get_current_time_us() - context->start_time;
            if (context->pulse_duration > 0 && context->pulse_duration <= MAX_PULSE_DURATION_US) {
                double distance_cm = (double)context->pulse_duration * 0.0343 / 2;
                time_t now = time(NULL);
                struct tm *tm_info = localtime(&now);
                char timestamp[20];
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);
                printf("[%s] Distance: %.2f cm\n", timestamp, distance_cm);
            } else {
                fprintf(stderr, "Invalid pulse duration: %llu us\n", context->pulse_duration);
            }
        }
    }
}

int main() {
    sensor_context_t *context = malloc(sizeof(sensor_context_t));
    if (!context) {
        fprintf(stderr, "Failed to allocate memory for context\n");
        return EXIT_FAILURE;
    }

    context->running = 1;
    context->state = STATE_IDLE;

    // Initialize trigger line
    context->trigger_line = gpiod_line_get("gpiochip4", TRIGGER_PIN);
    if (!context->trigger_line) {
        fprintf(stderr, "Failed to get trigger line %d\n", TRIGGER_PIN);
        cleanup(context);
        return EXIT_FAILURE;
    }

    // Initialize echo line
    context->echo_line = gpiod_line_get("gpiochip4", ECHO_PIN);
    if (!context->echo_line) {
        fprintf(stderr, "Failed to get echo line %d\n", ECHO_PIN);
        cleanup(context);
        return EXIT_FAILURE;
    }

    // Set trigger line as output
    if (gpiod_line_request_output(context->trigger_line, "trigger", 0) < 0) {
        fprintf(stderr, "Failed to request trigger line as output\n");
        cleanup(context);
        return EXIT_FAILURE;
    }

    // Set echo line as input
    if (gpiod_line_request_input(context->echo_line, "echo", 0) < 0) {
        fprintf(stderr, "Failed to request echo line as input\n");
        cleanup(context);
        return EXIT_FAILURE;
    }

    // Set echo line to pull up
    if (gpiod_line_set_config(context->echo_line, GPIOD_LINE_REQUEST_FLAG_ACTIVE_LOW, 0) < 0) {
        fprintf(stderr, "Failed to set echo line configuration\n");
        cleanup(context);
        return EXIT_FAILURE;
    }

    // Set up signal handling
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Note: HC-SR04 operates at 5V and Pi GPIO is 3.3V tolerant. A 1kΩ resistor must be used on the echo line.
    // This is handled by the library's API call() with microsecond precision.

    while (context->running) {
        measure_distance(context);
        usleep(POLLING_INTERVAL_MS * 1000);
    }

    cleanup(context);
    return EXIT_SUCCESS;
}

