void uart_deinit(UART_HandleTypeDef *uart);
void led_init(LED_HandleTypeDef *led);
void led_deinit(LED_HandleTypeDef *led);
void led_on(LED_HandleTypeDef *led);
void led_off(LED_HandleTypeDef *led);
void log_intrusion(const char *timestamp, double distance);
int read_uart_data(UART_HandleTypeDef *uart, uint8_t *buffer, size_t size);
void decode_range_profile(const uint8_t *data, double *distances);
int is_target_detected(const double *distances, double threshold);

int main() {
    UART_HandleTypeDef uart;
    LED_HandleTypeDef led;
    uint8_t buffer[RANGE_PROFILE_SIZE + MAGIC_WORD_SIZE];
    int bytes_read;
    double distances[BIN_COUNT];
    char timestamp[30];

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if (uart_init(&uart) != 0) {
        fprintf(stderr, "UART initialization failed.\n");
        return 1;
    }

    if (led_init(&led) != 0) {
        fprintf(stderr, "LED initialization failed.\n");
        uart_deinit(&uart);
        return 1;
    }

    while (1) {
        bytes_read = read_uart_data(&uart, buffer, sizeof(buffer));
        if (bytes_read < MAGIC_WORD_SIZE) {
            fprintf(stderr, "Incomplete magic word received.\n");
            continue;
        }

        if (memcmp(buffer, MAGIC_WORD, MAGIC_WORD_SIZE) != 0) {
            fprintf(stderr, "Invalid magic word.\n");
            continue;
        }

        if (bytes_read < MAGIC_WORD_SIZE + RANGE_PROFILE_SIZE) {
            fprintf(stderr, "Incomplete range profile data.\n");
            continue;
        }

        decode_range_profile(buffer + MAGIC_WORD_SIZE, distances);
        if (is_target_detected(distances, DISTANCE_THRESHOLD)) {
            time_t now = time(NULL);
            struct tm *tm_info = localtime(&now);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

            log_intrusion(timestamp, distances[0]);
            led_on(&led);
            sleep(LED_DURATION);
            led_off(&led);
        }
    }

    led_deinit(&led);
    uart_deinit(&uart);
    return 0;
}

void handle_signal(int sig) {
    printf("Received signal %d, exiting...\n", sig);
    exit(EXIT_SUCCESS);
}

void uart_init(UART_HandleTypeDef *uart) {
    int fd = open(UART_DEVICE, O_RDWR | O_NOCTTY | O_NDELAY);
    if (fd < 0) {
        perror("Failed to open UART device");
        return -1;
    }

    uart->fd = fd;

    struct termios tty;
    if (tcgetattr(uart->fd, &tty) != 0) {
        perror("Failed to get terminal attributes");
        close(uart->fd);
        return -1;
    }

    cfsetospeed(&tty, UART_BAUD_RATE);
    cfsetispeed(&tty, UART_BAUD_RATE);

    tty.c_cflag &= ~PARENB; // No parity
    tty.c_cflag &= ~CSTOPB; // 1 stop bit
    tty.c_cflag &= ~CSIZE;
    tty.c_cflag |= CS8;     // 8 bits per byte

    tty.c_cflag &= ~CRTSCTS; // No hardware flow control
    tty.c_cflag |= CREAD | CLOCAL; // Enable receiver, ignore modem control lines

    tty.c_lflag &= ~(ICANON | ECHO | ECHOE | ISIG); // Non-canonical mode
    tty.c_oflag &= ~OPOST;

    tty.c_cc[VTIME] = 0;    // Wait indefinitely for input
    tty.c_cc[VMIN] = 1;     // Read at least 1 byte

    if (tcsetattr(uart->fd, TCSAFLUSH, &tty) != 0) {
        perror("Failed to set terminal attributes");
        close(uart->fd);
        return -1;
    }

    return 0;
}

void uart_deinit(UART_HandleTypeDef *uart) {
    if (uart->fd >= 0) {
        close(uart->fd);
    }
}

void led_init(LED_HandleTypeDef *led) {
    const char *chip_name = "gpiochip0";
    int chip_fd = gpiod_chip_open(chip_name);
    if (chip_fd < 0) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    led->led_config.line_offset = LED_PIN;
    led->led_config.request_type = GPIOD_LINE_REQUEST_OUTPUT;
    led->led_config.flags = GPIOD_LINE_FLAG_ACTIVE_LOW;
    led->led_config.consumer = "intrusion_led";

    led->led_line = gpiod_line_request(chip_fd, &led->led_config);
    if (!led->led_line) {
        perror("Failed to request GPIO line");
        gpiod_chip_close(chip_fd);
        return -1;
    }

    return 0;
}

void led_deinit(LED_HandleTypeDef *led) {
    if (led->led_line) {
        gpiod_line_release(led->led_line);
    }
    if (led->led_config.consumer) {
        free((void *)led->led_config.consumer);
    }
}

void led_on(LED_HandleTypeDef *led) {
    if (gpiod_line_set_value(led->led_line, 1) < 0) {
        perror("Failed to set LED high");
    }
}

void led_off(LED_HandleTypeDef *led) {
    if (gpiod_line_set_value(led->led_line, 0) < 0) {
        perror("Failed to set LED low");
    }
}

void log_intrusion(const char *timestamp, double distance) {
    FILE *file = fopen("intrusion_log.csv", "a");
    if (!file) {
        perror("Failed to open log file");
        return;
    }

    fprintf(file, "%s,%f\n", timestamp, distance);
    fclose(file);
}

int read_uart_data(UART_HandleTypeDef *uart, uint8_t *buffer, size_t size) {
    int bytes_read = read(uart->fd, buffer, size);
    if (bytes_read < 0) {
        perror("UART read error");
        return -1;
    }

    return bytes_read;
}

void decode_range_profile(const uint8_t *data, double *distances) {
    for (int i = 0; i < BIN_COUNT; i++) {
        uint16_t raw = (data[i * 2] << 8) | data[i * 2 + 1];
        distances[i] = (double)raw / 1000.0; // Assuming 1 unit = 1 mm
    }
}

int is_target_detected(const double *distances, double threshold) {
    for (int i = 0; i < BIN_COUNT; i++) {
        if (distances[i] < threshold) {
            return 1;
        }
    }
    return 0;
}
