    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", tm_info);

    fprintf(log_file, "%s - Sensor: %d, Buzzer: %d\n", timestamp, sensor_state, buzzer_state);
    fclose(log_file);
}

