    state->chip = gpiod_chip_open("/dev/gpiochip4");
    if (!state->chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    state->sensor_line = gpiod_line_request_output(state->chip, "gpio17", "sensor", 1, 0);
    if (!state->sensor_line) {
        perror("Failed to request sensor line");
        gpiod_chip_close(state->chip);
        return -1;
    }

    state->buzzer_line = gpiod_line_request_output(state->chip, "gpio18", "buzzer", 1, 0);
    if (!state->buzzer_line) {
        perror("Failed to request buzzer line");
        gpiod_line_release(state->sensor_line);
        gpiod_chip_close(state->chip);
        return -1;
    }

    state->sensor_state = gpiod_line_get_value(state->sensor_line);
    state->buzzer_state = gpiod_line_get_value(state->buzzer_line);

    return 0;
}

