    if (state->buzzer_line) {
        gpiod_line_release(state->buzzer_line);
    }
    if (state->sensor_line) {
        gpiod_line_release(state->sensor_line);
    }
    if (state->chip) {
        gpiod_chip_close(state->chip);
    }
}

int main() {
    app_state state = {0};
    int ret;

    // Set up signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if ((ret = init_gpio(&state)) != 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return EXIT_FAILURE;
    }

    state.running = 1;
    while (state.running) {
        // Poll sensor
        int current_sensor_state = gpiod_line_get_value(state.sensor_line);
        if (current_sensor_state != state.sensor_state) {
            log_state_transition(current_sensor_state, state.buzzer_state);

            if (current_sensor_state == 0) {
                // Obstacle detected
                if (state.buzzer_state != 0) {
                    gpiod_line_set_value(state.buzzer_line, 1);
                    state.buzzer_state = 1;
                }
            } else {
                // No obstacle
                if (state.buzzer_state != 0) {
                    gpiod_line_set_value(state.buzzer_line, 0);
                    state.buzzer_state = 0;
                }
            }

            state.sensor_state = current_sensor_state;
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    cleanup_gpio(&state);
    return EXIT_SUCCESS;
}

