#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>
#include <errno.h>

#define I2C_BUS 1
#define I2C_ADDR 0x40
#define GPIO_PIN 17
#define GPIO_LINE 17
#define LOG_FILE "distance_log.txt"
#define POLL_INTERVAL_MS 100
#define DISTANCE_THRESHOLD_CM 10.0

typedef struct {
    int i2c_fd;
    struct gpiod_line *gpio_line;
    FILE *log_file;
    int running;
} app_state;

void handle_signal(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        printf("Received signal, shutting down...\n");
        app_state *state = (app_state *)malloc(sizeof(app_state));
        state->running = 0;
        free(state);
        exit(EXIT_SUCCESS);
    }
}

void log_distance(double distance) {
    time_t now = time(NULL);
    struct tm *tm_now = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_now);

    fprintf(stderr, "[%s] Distance: %.2f cm\n", timestamp, distance);
}

void log_to_file(double distance) {
    if (!app_state.log_file) {
        fprintf(stderr, "Error: Log file not open.\n");
        return;
    }

    time_t now = time(NULL);
    struct tm *tm_now = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_now);

    fprintf(app_state.log_file, "[%s] %.2f\n", timestamp, distance);
    fflush(app_state.log_file);
}

int i2c_read_distance(int fd) {
    unsigned char buffer[2];
    int bytes_read;

    if (ioctl(fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        return -1;
    }

    buffer[0] = 0x00; // Command to read distance
    if (write(fd, buffer, 1) != 1) {
        perror("Failed to write to I2C device");
        return -1;
    }

    usleep(10000); // Wait for measurement to complete

    if (read(fd, buffer, 2) != 2) {
        perror("Failed to read from I2C device");
        return -1;
    }

    // Convert to distance in cm
    int distance_mm = (buffer[0] << 8) | buffer[1];
    double distance_cm = distance_mm / 10.0;

    return distance_cm;
}

void setup_gpio() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;

    chip = gpiod_chip_open(GPIO_PIN);
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    line = gpiod_line_request_output(chip, "alert", GPIO_LINE, 0);
    if (!line) {
        perror("Failed to request GPIO line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    app_state.gpio_line = line;
}

void release_gpio() {
    if (app_state.gpio_line) {
        gpiod_line_release(app_state.gpio_line);
        app_state.gpio_line = NULL;
    }
}

void setup_i2c() {
    char i2c_bus_path[32];
    snprintf(i2c_bus_path, sizeof(i2c_bus_path), "/dev/i2c-%d", I2C_BUS);

    app_state.i2c_fd = open(i2c_bus_path, O_RDWR);
    if (app_state.i2c_fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }
}

void release_i2c() {
    if (app_state.i2c_fd >= 0) {
        close(app_state.i2c_fd);
        app_state.i2c_fd = -1;
    }
}

void setup_logging() {
    app_state.log_file = fopen(LOG_FILE, "a");
    if (!app_state.log_file) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }
}

void release_logging() {
    if (app_state.log_file) {
        fclose(app_state.log_file);
        app_state.log_file = NULL;
    }
}

int main() {
    app_state state = {0};

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    setup_i2c();
    setup_gpio();
    setup_logging();

    state.running = 1;

    while (state.running) {
        double distance = i2c_read_distance(state.i2c_fd);
        if (distance < 0) {
            fprintf(stderr, "I2C read failed, retrying...\n");
            usleep(100000);
            continue;
        }

        log_distance(distance);
        log_to_file(distance);

        if (distance < DISTANCE_THRESHOLD_CM) {
            gpiod_line_set_value(state.gpio_line, 1);
            fprintf(stderr, "Distance below threshold, alert triggered.\n");
        } else {
            gpiod_line_set_value(state.gpio_line, 0);
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    release_logging();
    release_gpio();
    release_i2c();

    return 0;
}

