#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS 1
#define I2C_ADDR 0x20
#define LED_PIN 18
#define LED_DELAY_MS 10
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10
#define SAMPLE_INTERVAL_MS 100

typedef struct {
    int i2c_fd;
    struct gpiod_line *led_line;
    int running;
} app_state;

void handle_signal(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        app_state *state = (app_state *)malloc(sizeof(app_state));
        if (state) {
            state->running = 0;
            free(state);
        }
    }
}

void i2c_read_retry(int fd, unsigned char *buf, int len) {
    int retries = 0;
    int ret;

    while (retries < MAX_RETRIES) {
        ret = read(fd, buf, len);
        if (ret == len) {
            return;
        } else if (ret < 0) {
            if (errno == EAGAIN || errno == EIO) {
                usleep(RETRY_DELAY_MS * 1000);
                retries++;
                continue;
            } else {
                fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
                return;
            }
        } else {
            fprintf(stderr, "I2C read incomplete: %d bytes read\n", ret);
            return;
        }
    }
}

void i2c_write_retry(int fd, unsigned char *buf, int len) {
    int retries = 0;
    int ret;

    while (retries < MAX_RETRIES) {
        ret = write(fd, buf, len);
        if (ret == len) {
            return;
        } else if (ret < 0) {
            if (errno == EAGAIN || errno == EIO) {
                usleep(RETRY_DELAY_MS * 1000);
                retries++;
                continue;
            } else {
                fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
                return;
            }
        } else {
            fprintf(stderr, "I2C write incomplete: %d bytes written\n", ret);
            return;
        }
    }
}

void close_i2c_and_led(app_state *state) {
    if (state->i2c_fd >= 0) {
        close(state->i2c_fd);
    }
    if (state->led_line) {
        gpiod_line_release(state->led_line);
    }
    free(state);
}

int main() {
    app_state *state = (app_state *)malloc(sizeof(app_state));
    if (!state) {
        fprintf(stderr, "Failed to allocate memory for app_state\n");
        return 1;
    }

    state->running = 1;

    // Set up signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Initialize LED
    struct gpiod_chip *chip;
    struct gpiod_line *led_line;
    int ret;

    chip = gpiod_chip_open("/dev/gpiochip4");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        close_i2c_and_led(state);
        return 1;
    }

    led_line = gpiod_line_request(chip, "gpio18", "led", GPIOD_LINE_DIRECTION_OUTPUT, 0, 0);
    if (!led_line) {
        fprintf(stderr, "Failed to request LED GPIO line\n");
        gpiod_chip_close(chip);
        close_i2c_and_led(state);
        return 1;
    }

    state->led_line = led_line;

    // Open I2C bus
    char i2c_bus_path[32];
    snprintf(i2c_bus_path, sizeof(i2c_bus_path), "/dev/i2c-%d", I2C_BUS);
    state->i2c_fd = open(i2c_bus_path, O_RDWR);
    if (state->i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        close_i2c_and_led(state);
        return 1;
    }

    // Set I2C slave address
    if (ioctl(state->i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address: %s\n", strerror(errno));
        close(state->i2c_fd);
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        close_i2c_and_led(state);
        return 1;
    }

    // Initialize sensor (example command, adjust as needed)
    unsigned char init_cmd[] = {0x01, 0x00, 0x00, 0x00};
    i2c_write_retry(state->i2c_fd, init_cmd, sizeof(init_cmd));

    // Main loop
    while (state->running) {
        unsigned char read_cmd[] = {0x02};
        unsigned char response[2];
        i2c_write_retry(state->i2c_fd, read_cmd, sizeof(read_cmd));
        i2c_read_retry(state->i2c_fd, response, sizeof(response));

        // Calculate distance (example, adjust based on sensor datasheet)
        int distance = (response[0] << 8) | response[1];
        if (distance < 0) {
            distance = 0;
        }

        // Calculate blink frequency based on distance
        int blink_freq = 1000; // 1 Hz
        if (distance < 100) {
            blink_freq = 500; // 2 Hz
        } else if (distance < 200) {
            blink_freq = 250; // 4 Hz
        } else if (distance < 300) {
            blink_freq = 125; // 8 Hz
        }

        // Calculate LED state for this sample
        static int blink_state = 0;
        static long last_time = 0;
        long current_time = time(NULL) * 1000;

        if (current_time - last_time >= blink_freq) {
            blink_state = 1 - blink_state;
            last_time = current_time;
        }

        // Set LED state
        if (blink_state) {
            gpiod_line_set_value(led_line, 1);
        } else {
            gpiod_line_set_value(led_line, 0);
        }

        // Log timestamp and distance
        printf("Timestamp: %ld, Distance: %d mm, Blink Frequency: %d Hz\n", current_time, distance, blink_freq);

        // Sleep for sample interval
        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    // Clean up
    close_i2c_and_led(state);

    return 0;
}

