void handle_signal(int sig) {
    running = 0;
}

void log_error(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
}

void log_error_errno(const char *message) {
    fprintf(stderr, "Error: %s: %s\n", message, strerror(errno));
}

int i2c_write(int fd, uint8_t reg, uint8_t value) {
    uint8_t buffer[2];
    buffer[0] = reg;
    buffer[1] = value;
    int ret = write(fd, buffer, 2);
    if (ret != 2) {
        log_error_errno("I2C write failed");
        return -1;
    }
    return 0;
}

int i2c_read(int fd, uint8_t reg, uint8_t *value) {
    uint8_t buffer[1];
    buffer[0] = reg;
    int ret = write(fd, buffer, 1);
    if (ret != 1) {
        log_error_errno("I2C write failed");
        return -1;
    }

    ret = read(fd, buffer, 1);
    if (ret != 1) {
        log_error_errno("I2C read failed");
        return -1;
    }

    *value = buffer[0];
    return 0;
}

int i2c_read_distance(int fd, uint16_t *distance) {
    uint8_t high, low;
    int retries = 0;

    do {
        if (i2c_write(fd, MLX75030_COMMAND, 0x01) < 0) {
            log_error("Failed to trigger measurement");
            return -1;
        }

        usleep(10000); // Wait for measurement to complete

        if (i2c_read(fd, MLX75030_DATA_REGISTER, &high) < 0) {
            log_error("Failed to read high byte");
            return -1;
        }

        if (i2c_read(fd, MLX75030_DATA_REGISTER, &low) < 0) {
            log_error("Failed to read low byte");
            return -1;
        }

        *distance = (high << 8) | low;

        if (*distance > 0x7FFF) {
            log_error("Invalid distance value");
            return -1;
        }

        return 0;
    } while (retries++ < MAX_RETRIES);

    log_error("Max retries exceeded for I2C read");
    return -1;
}

void write_log_entry(FILE *fp, time_t timestamp, uint16_t distance) {
    char timestamp_str[30];
    strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", localtime(&timestamp));
    fprintf(fp, "%s,%d\n", timestamp_str, distance);
}

int main() {
    int i2c_fd = -1;
    FILE *log_file = NULL;
    struct timespec sleep_time = {0, 100000000}; // 100 ms

    // Set up signal handling
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Open I2C bus
    char i2c_bus_path[32];
    snprintf(i2c_bus_path, sizeof(i2c_bus_path), "/dev/i2c-%d", I2C_BUS);
    i2c_fd = open(i2c_bus_path, O_RDWR);
    if (i2c_fd < 0) {
        log_error_errno("Failed to open I2C bus");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_TEN, 0) < 0) {
        log_error_errno("I2C set 10-bit addressing failed");
        close(i2c_fd);
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        log_error_errno("I2C set slave address failed");
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        log_error_errno("Failed to open log file");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (running) {
        time_t timestamp;
        uint16_t distance = 0;
        int ret;

        time(&timestamp);

        ret = i2c_read_distance(i2c_fd, &distance);
        if (ret < 0) {
            // Retry on transient error
            if (ret == -1) {
                log_error("Transient I2C error, retrying...");
                usleep(100000);
                continue;
            } else {
                log_error("I2C communication failed");
                break;
            }
        }

        write_log_entry(log_file, timestamp, distance);

        nanosleep(&sleep_time, NULL);
    }

    // Clean up
    if (log_file) {
        fclose(log_file);
    }

    if (i2c_fd >= 0) {
        close(i2c_fd);
    }

    return 0;
}

