#define GPIO_PIN_2 27
#define LOG_FILE "proximity_log.txt"
#define DEBOUNCE_DELAY_MS 50
#define POLL_INTERVAL_MS 10

typedef enum {
    SENSOR_1,
    SENSOR_2
} Sensor;

typedef struct {
    int pin;
    int last_state;
    int debounce_count;
    int active;
} SensorState;

void log_event(const char *timestamp, int sensor_id, const char *event_type) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return;
    }

    fprintf(log_file, "%s, %d, %s\n", timestamp, sensor_id, event_type);
    fclose(log_file);
}

void handle_signal(int signal) {
    printf("Caught signal %d, exiting...\n", signal);
    exit(EXIT_SUCCESS);
}

void setup_gpio(gpiod_line **lines, int pin1, int pin2) {
    int ret;

    // Initialize GPIO line for sensor 1
    *lines = gpiod_chip_open_by_label("gpiochip0");
    if (!*lines) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    (*lines)[0] = gpiod_line_get_by_offset(*lines, pin1);
    if (!(*lines)[0]) {
        perror("Failed to get GPIO line for sensor 1");
        gpiod_chip_close(*lines);
        exit(EXIT_FAILURE);
    }

    (*lines)[1] = gpiod_line_get_by_offset(*lines, pin2);
    if (!(*lines)[1]) {
        perror("Failed to get GPIO line for sensor 2");
        gpiod_line_put((*lines)[0]);
        gpiod_chip_close(*lines);
        exit(EXIT_FAILURE);
    }

    // Set line to input mode
    ret = gpiod_line_request_input((*lines)[0], "sensor1");
    if (ret < 0) {
        perror("Failed to request input for sensor 1");
        gpiod_line_put((*lines)[0]);
        gpiod_line_put((*lines)[1]);
        gpiod_chip_close(*lines);
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_request_input((*lines)[1], "sensor2");
    if (ret < 0) {
        perror("Failed to request input for sensor 2");
        gpiod_line_put((*lines)[0]);
        gpiod_line_put((*lines)[1]);
        gpiod_chip_close(*lines);
        exit(EXIT_FAILURE);
    }
}

void cleanup_gpio(gpiod_line *lines, int num_lines) {
    if (lines[0]) {
        gpiod_line_put(lines[0]);
    }
    if (lines[1]) {
        gpiod_line_put(lines[1]);
    }
    if (lines[0] || lines[1]) {
        gpiod_chip_close(lines[0]);
    }
}

int main() {
    gpiod_line lines[2];
    SensorState sensor_states[2] = {
        {GPIO_PIN_1, 0, 0, 0},
        {GPIO_PIN_2, 0, 0, 0}
    };

    setup_gpio(lines, GPIO_PIN_1, GPIO_PIN_2);

    // Set up signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (1) {
        struct timespec ts = {0, 0};
        nanosleep(&ts, NULL);

        for (int i = 0; i < 2; i++) {
            int current_state = gpiod_line_get_value(lines[i]);
            if (current_state < 0) {
                perror("Failed to read GPIO line");
                cleanup_gpio(lines, 2);
                exit(EXIT_FAILURE);
            }

            if (current_state != sensor_states[i].last_state) {
                sensor_states[i].debounce_count = 0;
                sensor_states[i].last_state = current_state;
            } else {
                sensor_states[i].debounce_count++;
            }

            if (sensor_states[i].debounce_count >= DEBOUNCE_DELAY_MS / POLL_INTERVAL_MS) {
                if (sensor_states[i].active == 0 && current_state == 1) {
                    // CLEARED
                    char timestamp[64];
                    time_t now = time(NULL);
                    struct tm *tm = gmtime(&now);
                    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm);
                    log_event(timestamp, i + 1, "CLEARED");
                    sensor_states[i].active = 1;
                } else if (sensor_states[i].active == 1 && current_state == 0) {
                    // DETECTED
                    char timestamp[64];
                    time_t now = time(NULL);
                    struct tm *tm = gmtime(&now);
                    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm);
                    log_event(timestamp, i + 1, "DETECTED");
                    sensor_states[i].active = 0;
                }
            }
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    cleanup_gpio(lines, 2);
    return 0;
}

