#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <sys/time.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_SLAVE_ADDR 0x20
#define MEAS_STATUS_REGISTER 0x00
#define MEASUREMENT_REGISTER 0x01
#define I2C_TIMEOUT_MS 50
#define SAMPLE_INTERVAL_MS 500
#define CSV_FILE "distance_log.csv"

int i2c_fd = -1;
FILE *csv_file = NULL;

void handle_signal(int sig) {
    if (i2c_fd != -1) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    if (csv_file != NULL) {
        fclose(csv_file);
        csv_file = NULL;
    }
    exit(EXIT_SUCCESS);
}

void log_distance(double distance_mm) {
    struct timeval tv;
    char timestamp[30];

    gettimeofday(&tv, NULL);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&tv.tv_sec));
    fprintf(csv_file, "%s.%06ld,%f\n", timestamp, tv.tv_usec, distance_mm);
    fflush(csv_file);
}

int i2c_read_measurement() {
    unsigned char write_buf[1] = {MEAS_STATUS_REGISTER};
    unsigned char read_buf[2] = {0};

    if (write(i2c_fd, write_buf, 1) < 0) {
        fprintf(stderr, "I2C write error: %s\n", strerror(errno));
        return -1;
    }

    struct timeval timeout;
    fd_set read_fds;
    int ret;

    timeout.tv_sec = 0;
    timeout.tv_usec = I2C_TIMEOUT_MS * 1000;
    FD_ZERO(&read_fds);
    FD_SET(i2c_fd, &read_fds);

    ret = select(i2c_fd + 1, &read_fds, NULL, NULL, &timeout);
    if (ret <= 0) {
        fprintf(stderr, "I2C read timeout: %s\n", strerror(errno));
        return -1;
    }

    if (read(i2c_fd, read_buf, 2) < 0) {
        fprintf(stderr, "I2C read error: %s\n", strerror(errno));
        return -1;
    }

    if ((read_buf[0] & 0x01) == 0) {
        fprintf(stderr, "Measurement not ready\n");
        return -1;
    }

    if (read(i2c_fd, read_buf, 2) < 0) {
        fprintf(stderr, "I2C read error: %s\n", strerror(errno));
        return -1;
    }

    double distance_mm = (double)(read_buf[0] << 8 | read_buf[1]) / 100.0;
    return (int)distance_mm;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_SLAVE_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    csv_file = fopen(CSV_FILE, "a");
    if (csv_file == NULL) {
        fprintf(stderr, "Failed to open CSV file: %s\n", strerror(errno));
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    fprintf(csv_file, "timestamp,distance_mm\n");
    fflush(csv_file);

    while (1) {
        usleep(SAMPLE_INTERVAL_MS * 1000);

        int result = i2c_read_measurement();
        if (result >= 0) {
            log_distance((double)result);
        }
    }

    return EXIT_SUCCESS;
}

