#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS 1
#define I2C_ADDR 0x29
#define INT_STATUS_REGISTER 0x00
#define MEASUREMENT_REGISTER 0x14
#define MAX_RETRIES 3
#define POLL_INTERVAL_MS 500

typedef struct {
    int i2c_fd;
    struct gpiod_line *int_line;
    struct timespec ts;
} sensor_state_t;

void handle_signal(int signum) {
    (void)signum;
    // Close I2C handle
    if (close(sensor_state_t.i2c_fd) < 0) {
        perror("Failed to close I2C device");
    }
    // Release GPIO line
    if (sensor_state_t.int_line) {
        gpiod_line_release(sensor_state_t.int_line);
    }
    exit(0);
}

void init_i2c(int bus, int addr) {
    char i2c_bus_path[32];
    snprintf(i2c_bus_path, sizeof(i2c_bus_path), "/dev/i2c-%d", bus);

    sensor_state_t.i2c_fd = open(i2c_bus_path, O_RDWR);
    if (sensor_state_t.i2c_fd < 0) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }

    if (ioctl(sensor_state_t.i2c_fd, I2C_SLAVE, addr) < 0) {
        perror("Failed to set I2C slave address");
        close(sensor_state_t.i2c_fd);
        exit(EXIT_FAILURE);
    }
}

void init_gpio() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    line = gpiod_line_get(chip, 27); // Example GPIO pin for interrupt (change as needed)
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(line, "interrupt", 0) < 0) {
        perror("Failed to request GPIO line");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    sensor_state_t.int_line = line;
}

void poll_interrupt() {
    int retries = MAX_RETRIES;
    int status;

    while (retries--) {
        status = gpiod_line_get_value(sensor_state_t.int_line);
        if (status < 0) {
            perror("Failed to read GPIO line");
            return;
        }

        if (status == 1) {
            return;
        }
    }

    fprintf(stderr, "Transient I2C communication failure, skipping cycle.\n");
}

void read_measurement() {
    uint8_t reg = MEASUREMENT_REGISTER;
    uint8_t buffer[2];

    if (write(sensor_state_t.i2c_fd, &reg, 1) < 0) {
        perror("Failed to write register address");
        return;
    }

    if (read(sensor_state_t.i2c_fd, buffer, 2) < 0) {
        perror("Failed to read measurement data");
        return;
    }

    uint16_t distance = (buffer[0] << 8) | buffer[1];
    printf("Timestamp: %04d-%02d-%02d %02d:%02d:%02d.%06ld, Distance: %u mm\n",
           sensor_state_t.ts.tv_sec / 3600 / 24 + 1970,
           (sensor_state_t.ts.tv_sec / 3600) % 24,
           (sensor_state_t.ts.tv_sec / 60) % 60,
           sensor_state_t.ts.tv_sec % 60,
           sensor_state_t.ts.tv_nsec / 1000000,
           sensor_state_t.ts.tv_nsec % 1000000,
           distance);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("Failed to install signal handler");
        exit(EXIT_FAILURE);
    }

    init_i2c(I2C_BUS, I2C_ADDR);
    init_gpio();

    while (1) {
        clock_gettime(CLOCK_MONOTONIC, &sensor_state_t.ts);

        poll_interrupt();

        read_measurement();

        usleep(500000); // 500 ms
    }

    return 0;
}

