void cleanup_gpio() {
    if (trigger_line) {
        gpiod_line_release(trigger_line);
        trigger_line = NULL;
    }
    if (echo_line) {
        gpiod_line_release(echo_line);
        echo_line = NULL;
    }
    if (servo_line) {
        gpiod_line_release(servo_line);
        servo_line = NULL;
    }
}

void set_servo_angle(int angle) {
    if (!servo_line) {
        fprintf(stderr, "Servo line not initialized\n");
        return;
    }

    if (angle < MIN_ANGLE) {
        angle = MIN_ANGLE;
    } else if (angle > MAX_ANGLE) {
        angle = MAX_ANGLE;
    }

    int duty_cycle = (angle - MIN_ANGLE) * 100 / (MAX_ANGLE - MIN_ANGLE);
    int pulse_width_us = 500 + duty_cycle * 1500; // 500-2000 us for -90 to +90 degrees

    if (gpiod_line_set_value(servo_line, 1) != 0) {
        fprintf(stderr, "Failed to set servo high\n");
        return;
    }
    usleep(pulse_width_us);
    if (gpiod_line_set_value(servo_line, 0) != 0) {
        fprintf(stderr, "Failed to set servo low\n");
    }
}

int measure_distance() {
    if (!trigger_line || !echo_line) {
        return SENSOR_TIMEOUT;
    }

    if (gpiod_line_set_value(trigger_line, 1) != 0) {
        return SENSOR_TIMEOUT;
    }
    usleep(10); // 10 us trigger pulse
    if (gpiod_line_set_value(trigger_line, 0) != 0) {
        return SENSOR_TIMEOUT;
    }

    struct timespec start, end;
    int64_t duration_us = 0;

    if (clock_gettime(CLOCK_MONOTONIC, &start) != 0) {
        return SENSOR_TIMEOUT;
    }

    int echo_state = 0;
    if (gpiod_line_get_value(echo_line, &echo_state) != 0) {
        return SENSOR_TIMEOUT;
    }

    if (echo_state == 0) {
        return SENSOR_TIMEOUT;
    }

    int timeout = 0;
    while (echo_state == 1) {
        if (clock_gettime(CLOCK_MONOTONIC, &end) != 0) {
            return SENSOR_TIMEOUT;
        }
        duration_us = (end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000;
        if (duration_us > SENSOR_TIMEOUT_MS * 1000) {
            return SENSOR_TIMEOUT;
        }
        if (gpiod_line_get_value(echo_line, &echo_state) != 0) {
            return SENSOR_TIMEOUT;
        }
