#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/time.h>
#include <sys/msg.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <gpiod.h>

#define I2C_BUS 1
#define I2C_ADDR 0x29
#define I2C_TIMEOUT 1000
#define MSG_QUEUE_KEY 0x1234
#define BUZZER_PIN 23
#define DISTANCE_THRESHOLD 100
#define POLL_INTERVAL_MS 50

typedef struct {
    long mtype;
    double distance;
} msg_queue_data;

volatile int running = 1;

void handle_sigint(int sig) {
    running = 0;
}

int init_i2c(int bus) {
    char filename[20];
    snprintf(filename, sizeof(filename), "/dev/i2c-%d", bus);
    int fd = open(filename, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

int read_distance(int fd) {
    uint8_t cmd[2] = {0x80, 0x00}; // Start measurement command
    if (write(fd, cmd, 2) != 2) {
        perror("I2C write error");
        return -1;
    }

    usleep(10000); // Wait for measurement to complete

    uint8_t data[8];
    if (read(fd, data, 8) != 8) {
        perror("I2C read error");
        return -1;
    }

    // Extract distance in mm
    uint16_t distance = (data[1] << 8) | data[0];
    return (int)distance;
}

int create_message_queue() {
    key_t key = MSG_QUEUE_KEY;
    int msgid = msgget(key, IPC_CREAT | 0666);
    if (msgid < 0) {
        perror("Failed to create message queue");
        return -1;
    }
    return msgid;
}

void send_message(int msgid, double distance) {
    msg_queue_data msg;
    msg.mtype = 1;
    msg.distance = distance;
    if (msgsnd(msgid, &msg, sizeof(msg.distance), 0) < 0) {
        perror("Failed to send message");
    }
}

void setup_gpio() {
    struct gpiod_line *buzzer_line;
    int gpio_fd = gpiod_chip_open("/dev/gpiochip4");
    if (gpio_fd < 0) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    buzzer_line = gpiod_line_get(gpio_fd, BUZZER_PIN);
    if (!buzzer_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(gpio_fd);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(buzzer_line, "buzzer", GPIOD_LINE_REQUEST_OUTPUT_FLAGS_NONE) < 0) {
        perror("Failed to request GPIO line");
        gpiod_line_put(buzzer_line);
        gpiod_chip_close(gpio_fd);
        exit(EXIT_FAILURE);
    }

    gpiod_line_set_value(buzzer_line, 0); // Initially off
    gpiod_line_put(buzzer_line);
    gpiod_chip_close(gpio_fd);
}

void trigger_buzzer() {
    struct gpiod_line *buzzer_line;
    int gpio_fd = gpiod_chip_open("/dev/gpiochip4");
    if (gpio_fd < 0) {
        perror("Failed to open GPIO chip");
        return;
    }

    buzzer_line = gpiod_line_get(gpio_fd, BUZZER_PIN);
    if (!buzzer_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(gpio_fd);
        return;
    }

    if (gpiod_line_request_output(buzzer_line, "buzzer", GPIOD_LINE_REQUEST_OUTPUT_FLAGS_NONE) < 0) {
        perror("Failed to request GPIO line");
        gpiod_line_put(buzzer_line);
        gpiod_chip_close(gpio_fd);
        return;
    }

    gpiod_line_set_value(buzzer_line, 1); // Turn on buzzer
    usleep(100000); // Buzzer on for 100ms
    gpiod_line_set_value(buzzer_line, 0); // Turn off buzzer
    gpiod_line_put(buzzer_line);
    gpiod_chip_close(gpio_fd);
}

int main() {
    signal(SIGINT, handle_sigint);

    int i2c_fd = init_i2c(I2C_BUS);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to initialize I2C\n");
        exit(EXIT_FAILURE);
    }

    setup_gpio();

    int msgid = create_message_queue();
    if (msgid < 0) {
        fprintf(stderr, "Failed to create message queue\n");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    while (running) {
        int distance = read_distance(i2c_fd);
        if (distance < 0) {
            fprintf(stderr, "I2C communication failed, retrying...\n");
            usleep(100000); // Wait before retrying
            continue;
        }

        double distance_mm = (double)distance / 1000.0; // Convert to mm

        printf("Measured distance: %.2f mm\n", distance_mm);

        send_message(msgid, distance_mm);

        if (distance_mm < DISTANCE_THRESHOLD) {
            trigger_buzzer();
        }

        usleep(50000); // 50 ms
    }

    close(i2c_fd);
    msgctl(msgid, IPC_RMID, NULL);
    printf("Program exited cleanly.\n");

    return 0;
}

