#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <stdint.h>
#include <libgpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 27
#define BUZZER_PIN 22
#define TIMEOUT_MS 100
#define VALID_MIN_CM 2
#define VALID_MAX_CM 400
#define BUZZER_THRESHOLD_CM 30

typedef struct {
    struct gpiod_line *trigger_line;
    struct gpiod_line *echo_line;
    struct gpiod_line *buzzer_line;
    struct gpiod_chip *chip;
    int64_t last_echo_time;
    int64_t last_print_time;
    int running;
} sensor_state;

void handle_signal(int sig) {
    if (sig == SIGINT) {
        sensor_state *state = (sensor_state *)malloc(sizeof(sensor_state));
        if (state) {
            state->running = 0;
            gpiod_line_release(state->trigger_line);
            gpiod_line_release(state->echo_line);
            gpiod_line_release(state->buzzer_line);
            gpiod_chip_close(state->chip);
            free(state);
        }
        exit(EXIT_SUCCESS);
    }
}

void setup_gpio(sensor_state *state) {
    state->chip = gpiod_chip_open("/dev/gpiochip0");
    if (!state->chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        exit(EXIT_FAILURE);
    }

    state->trigger_line = gpiod_chip_get_line(state->chip, TRIGGER_PIN);
    if (!state->trigger_line) {
        fprintf(stderr, "Failed to get trigger line\n");
        gpiod_chip_close(state->chip);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(state->trigger_line, "trigger", GPIOD_LINE_REQUEST_FLAG_ACTIVE_LOW)) {
        fprintf(stderr, "Failed to request trigger line\n");
        gpiod_line_release(state->trigger_line);
        gpiod_chip_close(state->chip);
        exit(EXIT_FAILURE);
    }

    state->echo_line = gpiod_chip_get_line(state->chip, ECHO_PIN);
    if (!state->echo_line) {
        fprintf(stderr, "Failed to get echo line\n");
        gpiod_line_release(state->trigger_line);
        gpiod_chip_close(state->chip);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_input(state->echo_line, "echo", GPIOD_LINE_REQUEST_FLAG_ACTIVE_LOW)) {
        fprintf(stderr, "Failed to request echo line\n");
        gpiod_line_release(state->trigger_line);
        gpiod_chip_close(state->chip);
        exit(EXIT_FAILURE);
    }

    state->buzzer_line = gpiod_chip_get_line(state->chip, BUZZER_PIN);
    if (!state->buzzer_line) {
        fprintf(stderr, "Failed to get buzzer line\n");
        gpiod_line_release(state->trigger_line);
        gpiod_line_release(state->echo_line);
        gpiod_chip_close(state->chip);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(state->buzzer_line, "buzzer", GPIOD_LINE_REQUEST_FLAG_ACTIVE_LOW)) {
        fprintf(stderr, "Failed to request buzzer line\n");
        gpiod_line_release(state->trigger_line);
        gpiod_line_release(state->echo_line);
        gpiod_chip_close(state->chip);
        exit(EXIT_FAILURE);
    }

    state->last_echo_time = 0;
    state->last_print_time = 0;
    state->running = 1;
}

void trigger_pulse(sensor_state *state) {
    gpiod_line_set_value(state->trigger_line, 1);
    usleep(10); // 10 microseconds
    gpiod_line_set_value(state->trigger_line, 0);
}

