#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>
#include <pthread.h>

#define I2C_BUS 1
#define I2C_ADDR 0x29
#define VL53L1X_SOFT_RESET 0x00
#define VL53L1X_START_RANGING 0x01
#define VL53L1X_GET_DISTANCE 0x02
#define VL53L1X_MAX_RETRIES 5
#define DISTANCE_THRESHOLD 2000  // 20 cm in mm
#define SERVO_PIN 18
#define SERVO_MIN_US 500
#define SERVO_MAX_US 2500
#define SERVO_MID_US 1500
#define LOG_FILE "gate_log.txt"

typedef enum {
    STATE_IDLE,
    STATE_OPENING,
    STATE_OPEN,
    STATE_CLOSING,
    STATE_CLOSED
} GateState;

typedef struct {
    int i2c_fd;
    int servo_fd;
    GateState state;
    int open_count;
    int close_count;
    pthread_mutex_t log_mutex;
    pthread_cond_t event_cond;
    int event_available;
    int force_open;
    int force_close;
    int status_request;
} GateController;

void log_event(GateController *controller, const char *message) {
    pthread_mutex_lock(&controller->log_mutex);
    FILE *file = fopen(LOG_FILE, "a");
    if (file) {
        time_t t = time(NULL);
        struct tm *tm = localtime(&t);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
        fprintf(file, "[%s] %s\n", timestamp, message);
        fclose(file);
    }
    pthread_mutex_unlock(&controller->log_mutex);
}

int i2c_read_word(int fd, uint8_t reg) {
    uint8_t buf[2];
    buf[0] = reg;
    if (ioctl(fd, I2C_RDWR, (struct i2c_rdwr_ioctl_data *)&(struct i2c_msg[0])) < 0) {
        perror("i2c_read_word: ioctl");
        return -1;
    }
    if (ioctl(fd, I2C_RDWR, (struct i2c_rdwr_ioctl_data *)&(struct i2c_msg[1])) < 0) {
        perror("i2c_read_word: ioctl");
        return -1;
    }
    return (buf[1] << 8) | buf[0];
}

int i2c_write_word(int fd, uint8_t reg, uint16_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value & 0xFF;
    if (ioctl(fd, I2C_RDWR, (struct i2c_rdwr_ioctl_data *)&(struct i2c_msg[0])) < 0) {
        perror("i2c_write_word: ioctl");
        return -1;
    }
    return 0;
}

int init_vl53l1x(int fd) {
    int retries = 0;
    while (retries < VL53L1X_MAX_RETRIES) {
        if (i2c_write_word(fd, VL53L1X_SOFT_RESET, 0x01) < 0) {
            fprintf(stderr, "Failed to write soft reset to VL53L1X\n");
            return -1;
        }
        usleep(100000);  // Wait for boot

        if (i2c_write_word(fd, 0x00, 0x01) < 0) {
            fprintf(stderr, "Failed to write start ranging\n");
            return -1;
        }
        usleep(100000);

        if (i2c_read_word(fd, 0x00) != 0x01) {
            fprintf(stderr, "VL53L1X not responding\n");
            return -1;
        }

        if (i2c_write_word(fd, VL53L1X_START_RANGING, 0x01) < 0) {
            fprintf(stderr, "Failed to start ranging\n");
            return -1;
        }
        usleep(100000);

        if (i2c_read_word(fd, VL53L1X_GET_DISTANCE) != 0x02) {
            fprintf(stderr, "Failed to read distance\n");
            return -1;
        }

        return 0;
    }
    fprintf(stderr, "VL53L1X initialization failed after %d retries\n", VL53L1X_MAX_RETRIES);
    return -1;
}

void set_servo_position(int fd, int us) {
    int duty_cycle = (us * 1000000) / 19200000;  // 19.2 MHz clock
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > 1023) duty_cycle = 1023;
    gpiod_line_set_value(fd, duty_cycle);
}

void init_servo() {
    struct gpiod_line *line;
    int fd = gpiod_chip_open("/dev/gpiochip1");
    if (fd < 0) {
        perror("gpiod_chip_open");
        exit(EXIT_FAILURE);
    }

    line = gpiod_line_get(fd, SERVO_PIN);
    if (!line) {
        perror("gpiod_line_get");
        close(fd);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(line, "servo", 0) < 0) {
        perror("gpiod_line_request_output");
        gpiod_line_put(line);
        close(fd);
        exit(EXIT_FAILURE);
    }

    set_servo_position(line, SERVO_MID_US);
    gpiod_line_put(line);
    close(fd);
}

void handle_force_open(GateController *controller) {
    if (controller->state != STATE_IDLE) {
        log_event(controller, "Force open command received while not idle");
        return;
    }
    controller->state = STATE_OPENING;
    set_servo_position(controller->servo_fd, SERVO_MIN_US);
    log_event(controller, "Forced open initiated");
}

void handle_force_close(GateController *controller) {
    if (controller->state != STATE_IDLE) {
        log_event(controller, "Force close command received while not idle");
        return;
    }
    controller->state = STATE_CLOSING;
    set_servo_position(controller->servo_fd, SERVO_MAX_US);
    log_event(controller, "Forced close initiated");
}

void handle_status_request(GateController *controller) {
    char status[100];
    snprintf(status, sizeof(status), "Gate state: %d, Open count: %d, Close count: %d",
             controller->state, controller->open_count, controller->close_count);
    log_event(controller, status);
}

void signal_handler(int signum) {
    // Clean up resources
    // This is a simplified version; in a real application, you'd use a proper cleanup function
    printf("Received signal %d, exiting...\n", signum);
    exit(EXIT_SUCCESS);
}

void* event_loop(void* arg) {
    GateController *controller = (GateController*)arg;
    int distance;
    int retry_count = 0;

    while (1) {
        if (controller->force_open) {
            handle_force_open(controller);
            controller->force_open = 0;
            continue;
        }

        if (controller->force_close) {
            handle_force_close(controller);
            controller->force_close = 0;
            continue;
        }

        if (controller->status_request) {
            handle_status_request(controller);
            controller->status_request = 0;
            continue;
        }

        if (controller->state == STATE_IDLE) {
            if (i2c_read_word(controller->i2c_fd, VL53L1X_GET_DISTANCE) != 0x02) {
                retry_count++;
                if (retry_count >= VL53L1X_MAX_RETRIES) {
                    log_event(controller, "VL53L1X communication error, retrying...");
                    retry_count = 0;
                }
                continue;
            }

            distance = i2c_read_word(controller->i2c_fd, 0x02);
            if (distance < DISTANCE_THRESHOLD) {
                if (controller->state != STATE_OPENING) {
                    controller->state = STATE_OPENING;
                    set_servo_position(controller->servo_fd, SERVO_MIN_US);
                    log_event(controller, "Object detected, opening gate");
                }
            } else {
                if (controller->state != STATE_CLOSING) {
                    controller->state = STATE_CLOSING;
                    set_servo_position(controller->servo_fd, SERVO_MAX_US);
                    log_event(controller, "Path clear, closing gate");
                }
            }
        } else if (controller->state == STATE_OPENING) {
            if (distance < DISTANCE_THRESHOLD) {
                controller->state = STATE_OPEN;
                controller->open_count++;
                log_event(controller, "Gate opened");
            } else {
                controller->state = STATE_IDLE;
                log_event(controller, "Gate opening stopped due to object");
            }
        } else if (controller->state == STATE_CLOSING) {
            if (distance >= DISTANCE_THRESHOLD) {
                controller->state = STATE_CLOSED;
                controller->close_count++;
                log_event(controller, "Gate closed");
            } else {
                controller->state = STATE_IDLE;
                log_event(controller, "Gate closing stopped due to object");
            }
        }
    }
}

int main() {
    GateController controller;
    int i2c_fd;
    int servo_fd;
    pthread_t event_thread;

    // Initialize signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    char i2c_bus_path[20];
    snprintf(i2c_bus_path, sizeof(i2c_bus_path), "/dev/i2c-%d", I2C_BUS);
    i2c_fd = open(i2c_bus_path, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    if (init_vl53l1x(i2c_fd) < 0) {
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Initialize servo
    init_servo();

    // Initialize controller
    controller.i2c_fd = i2c_fd;
    controller.state = STATE_IDLE;
    controller.open_count = 0;
    controller.close_count = 0;
    pthread_mutex_init(&controller.log_mutex, NULL);
    pthread_cond_init(&controller.event_cond, NULL);
    controller.event_available = 0;
    controller.force_open = 0;
    controller.force_close = 0;
    controller.status_request = 0;

    // Start event loop
    if (pthread_create(&event_thread, NULL, event_loop, &controller) != 0) {
        perror("Failed to create event loop thread");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Main loop to handle remote commands
    while (1) {
        // In a real application, this would be replaced with a command parser
        // For demonstration, we just wait for signals
        sleep(1);
    }

    // Cleanup
    pthread_cancel(event_thread);
    pthread_join(event_thread, NULL);
    close(i2c_fd);
    pthread_mutex_destroy(&controller.log_mutex);
    pthread_cond_destroy(&controller.event_cond);

    return 0;
}
