#define TRIG_PIN 23
#define ECHO_PIN 24
#define TRIG_DURATION_US 10
#define SAMPLE_INTERVAL_MS 200
#define MAX_PULSE_WIDTH_US 30000
#define MIN_PULSE_WIDTH_US 100
#define TIMEOUT_MS 60
#define LOG_FILE "distance_log.txt"

typedef struct {
    uint64_t rising_tick;
    uint64_t falling_tick;
    int valid;
} echo_event_t;

static struct gpiod_line *trig_line;
static struct gpiod_line *echo_line;
static struct gpiod_line *echo_line_in;
static struct gpiod_line *echo_line_out;
static FILE *log_file;
static volatile int running = 1;

static void handle_signal(int sig) {
    running = 0;
    if (log_file) {
        fclose(log_file);
    }
    if (trig_line) {
        gpiod_line_release(trig_line);
    }
    if (echo_line) {
        gpiod_line_release(echo_line);
    }
    exit(EXIT_SUCCESS);
}

static void trigger_pulse(void) {
    gpiod_line_set_value(trig_line, 1);
    usleep(TRIG_DURATION_US);
    gpiod_line_set_value(trig_line, 0);
}

static void callback_handler(struct gpiod_line *line, const struct gpiod_line_event *event, void *data) {
    echo_event_t *event_data = (echo_event_t *)data;
    if (event->type == GPIOD_LINE_EVENT_RISING_EDGE) {
        event_data->rising_tick = gpiod_line_get_timestamp(line);
        event_data->valid = 1;
    } else if (event->type == GPIOD_LINE_EVENT_FALLING_EDGE) {
        event_data->falling_tick = gpiod_line_get_timestamp(line);
        event_data->valid = 0;
    }
}

static void log_distance(uint64_t pulse_width_us) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&ts.tv_sec));
    snprintf(timestamp + 19, sizeof(timestamp) - 19, ".%09ldZ", ts.tv_nsec / 1000);

    double distance_cm = (double)pulse_width_us * 0.0343 / 2;
    fprintf(stdout, "[%s] Distance: %.2f cm\n", timestamp, distance_cm);
    fprintf(log_file, "[%s] Distance: %.2f cm\n", timestamp, distance_cm);
    fflush(log_file);
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *echo_line;
    echo_event_t event = {0};
    int ret;

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    trig_line = gpiod_chip_get_line(chip, TRIG_PIN);
    if (!trig_line) {
        fprintf(stderr, "Failed to get TRIG line\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(trig_line, "trig", GPIOD_LINE_REQUEST_FLAG_ACTIVE_LOW);
    if (ret < 0) {
        fprintf(stderr, "Failed to request TRIG line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo_line) {
        fprintf(stderr, "Failed to get ECHO line\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_input(echo_line, "echo", GPIOD_LINE_REQUEST_FLAG_ACTIVE_LOW);
    if (ret < 0) {
        fprintf(stderr, "Failed to request ECHO line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_set_flags(echo_line, GPIOD_LINE_FLAG_BIAS_PULL_DOWN);
    if (ret < 0) {
        fprintf(stderr, "Failed to set ECHO line bias: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpiod_line_release(echo_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_event_register(echo_line, GPIOD_LINE_EVENT_RISING_EDGE | GPIOD_LINE_EVENT_FALLING_EDGE, callback_handler, &event);
    if (ret < 0) {
        fprintf(stderr, "Failed to register event handler: %s\n", strerror(errno));
        fclose(log_file);
        gpiod_line_release(echo_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (running) {
        trigger_pulse();
        usleep(SAMPLE_INTERVAL_MS * 1000);

        uint64_t start_time = gpiod_line_get_timestamp(echo_line);
        uint64_t end_time = start_time;
        int timeout = 0;

        while (running && !event.valid && !timeout) {
            usleep(1000);
            end_time = gpiod_line_get_timestamp(echo_line);
            timeout = (end_time - start_time) > TIMEOUT_MS * 1000;
        }

        if (event.valid) {
            uint64_t pulse_width_us = (event.falling_tick - event.rising_tick) / 1000;
            if (pulse_width_us < MIN_PULSE_WIDTH_US || pulse_width_us > MAX_PULSE_WIDTH_US) {
                fprintf(stderr, "Invalid pulse width: %llu us (rejected)\n", pulse_width_us);
            } else {
                log_distance(pulse_width_us);
            }
        } else {
            fprintf(stderr, "No echo received within %d ms (timeout)\n", TIMEOUT_MS);
        }

        event.valid = 0;
    }

    gpiod_line_event_unregister(echo_line);
    gpiod_line_release(echo_line);
    gpiod_line_release(trig_line);
    gpiod_chip_close(chip);

    if (log_file) {
        fclose(log_file);
    }

    return EXIT_SUCCESS;
}

