#include <pthread.h>

#define I2C_BUS 1
#define I2C_ADDR 0x29
#define SHUTDOWN_PIN 23
#define INT_PIN 24
#define SERVO_PIN 18
#define LOG_FILE "parking_log.txt"
#define DISTANCE_THRESHOLD_CLOSE 50
#define DISTANCE_THRESHOLD_FAR 60
#define SERVO_MIN 500
#define SERVO_MAX 2500
#define SERVO_CENTER 1500
#define SERVO_DELAY 500000 // 500ms in microseconds

typedef struct {
    int i2c_fd;
    struct gpiod_line *shutdown_line;
    struct gpiod_line *int_line;
    struct gpiod_line *servo_line;
    int gate_open;
    int last_state;
    pthread_mutex_t log_mutex;
} parking_system_t;

void handle_signal(int sig) {
