#define I2C_BUS 1
#define I2C_ADDR 0x29
#define GPIO_OPEN_PIN 18
#define GPIO_CLOSE_PIN 19
#define LOG_FILE "gate_events.log"
#define DISTANCE_THRESHOLD 200  // in mm
#define POLL_INTERVAL_MS 500

typedef struct {
    int i2c_fd;
    struct gpiod_line *open_line;
    struct gpiod_line *close_line;
    FILE *log_file;
    int running;
} SensorContext;

void handle_signal(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        SensorContext *ctx = (SensorContext *)malloc(sizeof(SensorContext));
        if (ctx) {
            ctx->running = 0;
        }
    }
}

void init_gpio(SensorContext *ctx) {
    const char *chip_name_open = "gpiochip0";
    const char *chip_name_close = "gpiochip0";

    ctx->open_line = gpiod_line_get(chip_name_open, GPIO_OPEN_PIN);
    if (!ctx->open_line) {
        fprintf(stderr, "Failed to get GPIO %d line\n", GPIO_OPEN_PIN);
        exit(EXIT_FAILURE);
    }

    ctx->close_line = gpiod_line_get(chip_name_close, GPIO_CLOSE_PIN);
    if (!ctx->close_line) {
        fprintf(stderr, "Failed to get GPIO %d line\n", GPIO_CLOSE_PIN);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(ctx->open_line, "open_gate", 0)) {
        fprintf(stderr, "Failed to request GPIO %d as output\n", GPIO_OPEN_PIN);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(ctx->close_line, "close_gate", 0)) {
        fprintf(stderr, "Failed to request GPIO %d as output\n", GPIO_CLOSE_PIN);
        exit(EXIT_FAILURE);
    }
}

void release_gpio(SensorContext *ctx) {
    if (ctx->open_line) {
        gpiod_line_release(ctx->open_line);
    }
    if (ctx->close_line) {
        gpiod_line_release(ctx->close_line);
    }
}

void init_i2c(SensorContext *ctx) {
    char i2c_bus_path[32];
    snprintf(i2c_bus_path, sizeof(i2c_bus_path), "/dev/i2c-%d", I2C_BUS);

    ctx->i2c_fd = open(i2c_bus_path, O_RDWR);
    if (ctx->i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %d: %s\n", I2C_BUS, strerror(errno));
        exit(EXIT_FAILURE);
    }

    if (ioctl(ctx->i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address: %s\n", strerror(errno));
        close(ctx->i2c_fd);
        exit(EXIT_FAILURE);
    }
}

void close_i2c(SensorContext *ctx) {
    if (ctx->i2c_fd >= 0) {
        close(ctx->i2c_fd);
    }
}

void log_event(FILE *log_file, const char *event) {
    time_t now;
    struct tm *tm_info;
    char timestamp[64];

    time(&now);
    tm_info = gmtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", tm_info);

    fprintf(log_file, "%s: %s\n", timestamp, event);
    fflush(log_file);
}

void soft_reset_sensor(int fd) {
    unsigned char cmd[2] = {0x00, 0x00};
    if (write(fd, cmd, 2) != 2) {
        fprintf(stderr, "Failed to send soft reset command\n");
    }
    usleep(100000);  // Wait for reset to complete
}

void configure_timing_budget(int fd) {
    unsigned char cmd[2] = {0x80, 0x00};  // Timing Budget register
    if (write(fd, cmd, 2) != 2) {
        fprintf(stderr, "Failed to write to Timing Budget register\n");
        return;
    }
    usleep(10000);  // Wait for configuration to take effect
}

void read_distance(int fd, unsigned short *distance) {
    unsigned char cmd[2] = {0x8F, 0x00};  // Device ID register
    if (write(fd, cmd, 2) != 2) {
        fprintf(stderr, "Failed to write to Device ID register\n");
        return;
    }

    unsigned char rx_data[2];
    if (read(fd, rx_data, 2) != 2) {
        fprintf(stderr, "Failed to read from Device ID register\n");
        return;
    }

    if (rx_data[0] != 0xEE || rx_data[1] != 0x00) {
        fprintf(stderr, "Invalid device ID, sensor not responding\n");
        return;
    }

    cmd[0] = 0x90;  // Distance register
    if (write(fd, cmd, 1) != 1) {
        fprintf(stderr, "Failed to write to Distance register\n");
        return;
    }

    if (read(fd, rx_data, 2) != 2) {
        fprintf(stderr, "Failed to read distance data\n");
        return;
    }

    *distance = (rx_data[0] << 8) | rx_data[1];
}

void open_gate(SensorContext *ctx) {
    gpiod_line_set_value(ctx->open_line, 1);
    gpiod_line_set_value(ctx->close_line, 0);
    log_event(ctx->log_file, "Gate opened");
}

void close_gate(SensorContext *ctx) {
    gpiod_line_set_value(ctx->open_line, 0);
    gpiod_line_set_value(ctx->close_line, 1);
    log_event(ctx->log_file, "Gate closed");
}

void init_log_file(FILE **log_file) {
    *log_file = fopen(LOG_FILE, "a");
    if (!*log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }
}

void close_log_file(FILE *log_file) {
    if (log_file) {
        fclose(log_file);
    }
}

int main() {
    SensorContext ctx = {0};

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    init_gpio(&ctx);
    init_i2c(&ctx);
    init_log_file(&ctx.log_file);
    ctx.running = 1;

    soft_reset_sensor(ctx.i2c_fd);
    configure_timing_budget(ctx.i2c_fd);

    while (ctx.running) {
        unsigned short distance = 0;
        read_distance(ctx.i2c_fd, &distance);

        if (distance <= DISTANCE_THRESHOLD) {
            open_gate(&ctx);
        } else {
            close_gate(&ctx);
        }

        usleep(500000);  // 500 ms
    }

    close_log_file(ctx.log_file);
    release_gpio(&ctx);
    close_i2c(&ctx);

    return 0;
}

