    if (gpioSetMode(ctx->gpio_forward, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", ctx->gpio_forward);
        exit(EXIT_FAILURE);
    }

    if (gpioSetMode(ctx->gpio_backward, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", ctx->gpio_backward);
        exit(EXIT_FAILURE);
    }

    if (gpioSetMode(ctx->gpio_trigger, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", ctx->gpio_trigger);
        exit(EXIT_FAILURE);
    }

    if (gpioSetPullUpDown(ctx->gpio_trigger, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO %d\n", ctx->gpio_trigger);
        exit(EXIT_FAILURE);
    }

    ctx->motor_state = 0;
    ctx->sensor_present = 1;
    ctx->is_running = 1;
}

void cleanup_gpio(AppContext *ctx) {
    if (ctx->is_running) {
        gpioWrite(ctx->gpio_forward, PI_OFF);
        gpioWrite(ctx->gpio_backward, PI_OFF);
        gpioTerminate();
    }
}

void setup_i2c(AppContext *ctx) {
    char i2c_bus_path[32];
    snprintf(i2c_bus_path, sizeof(i2c_bus_path), "/dev/i2c-%d", I2C_BUS);

    ctx->i2c_fd = open(i2c_bus_path, O_RDWR);
    if (ctx->i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %d\n", I2C_BUS);
        exit(EXIT_FAILURE);
    }

    if (ioctl(ctx->i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address %02X\n", I2C_ADDR);
        close(ctx->i2c_fd);
        exit(EXIT_FAILURE);
    }

    ctx->sensor_present = 1;
}

void cleanup_i2c(AppContext *ctx) {
    if (ctx->i2c_fd >= 0) {
        close(ctx->i2c_fd);
    }
}

