    uint8_t buffer[2];
    buffer[0] = reg;
    buffer[1] = value;
    if (write(ctx->i2c_fd, buffer, 2) != 2) {
        fprintf(stderr, "I2C write failed\n");
        ctx->sensor_present = 0;
    }
}

void i2c_read_byte(AppContext *ctx, uint8_t reg, uint8_t *value) {
    uint8_t buffer[1];
    buffer[0] = reg;
    if (write(ctx->i2c_fd, buffer, 1) != 1) {
        fprintf(stderr, "I2C write failed\n");
        ctx->sensor_present = 0;
        return;
    }

    if (read(ctx->i2c_fd, buffer, 1) != 1) {
        fprintf(stderr, "I2C read failed\n");
        ctx->sensor_present = 0;
        return;
    }

    *value = buffer[0];
}

void i2c_read_word(AppContext *ctx, uint8_t reg, uint16_t *value) {
    uint8_t buffer[2];
    buffer[0] = reg;
    if (write(ctx->i2c_fd, buffer, 1) != 1) {
        fprintf(stderr, "I2C write failed\n");
        ctx->sensor_present = 0;
        return;
    }

    if (read(ctx->i2c_fd, buffer, 2) != 2) {
        fprintf(stderr, "I2C read failed\n");
        ctx->sensor_present = 0;
        return;
    }

    *value = (buffer[0] << 8) | buffer[1];
}

void vl53l1x_soft_reset(AppContext *ctx) {
    i2c_write_byte(ctx, 0x00, 0x00); // Soft reset
    usleep(1000); // 1ms delay
}

void vl53l1x_start_measurement(AppContext *ctx) {
    i2c_write_byte(ctx, 0x01, 0x01); // Start measurement
}

void vl53l1x_check_status(AppContext *ctx) {
    uint8_t status;
    i2c_read_byte(ctx, 0x00, &status);
    return (status & 0x01) != 0;
}

