    uint16_t distance = 0;
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (vl53l1x_check_status(ctx)) {
            i2c_read_word(ctx, 0x14, &distance);
            break;
        }
        usleep(RETRY_DELAY_MS * 1000);
        retries++;
    }

    if (retries >= MAX_RETRIES) {
        fprintf(stderr, "Failed to read distance after %d retries\n", MAX_RETRIES);
        ctx->sensor_present = 0;
    }

    return distance;
}

