    if (ctx->motor_state == direction) {
        return;
    }

    if (direction == 0) {
        gpioWrite(ctx->gpio_forward, PI_OFF);
        gpioWrite(ctx->gpio_backward, PI_OFF);
    } else if (direction == 1) {
        gpioWrite(ctx->gpio_forward, PI_ON);
        gpioWrite(ctx->gpio_backward, PI_OFF);
    } else if (direction == -1) {
        gpioWrite(ctx->gpio_forward, PI_OFF);
        gpioWrite(ctx->gpio_backward, PI_ON);
    }

    ctx->motor_state = direction;
