    while (ctx.is_running) {
        if (!ctx.sensor_present) {
            printf("Sensor not present or bus error. Stopping motor.\n");
            motor_control(&ctx, 0);
            break;
        }

        usleep(100000); // 100ms delay
    }

    cleanup_gpio(&ctx);
    cleanup_i2c(&ctx);

    return 0;
}

