#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define I2C_BUS "/dev/i2c-1"
#define MPR121_ADDR 0x5A
#define MPR121_TCH_STATUS 0x00
#define MPR121_FILTR 0x04
#define MPR121_CONFIG1 0x0A
#define MPR121_CONFIG2 0x0B
#define MPR121_SOFT_RESET 0x6B
#define MPR121_TOUCH_BIT_MASK 0x0F

#define LED_GPIO_0 17
#define LED_GPIO_1 18
#define LED_GPIO_2 27
#define LED_GPIO_3 22

#define LED_PATTERN_SIZE 4
#define LOG_FILE "proximity_log.txt"
#define POLL_INTERVAL_MS 50

typedef struct {
    int i2c_fd;
    struct gpiod_line *leds[LED_PATTERN_SIZE];
    FILE *log_file;
    int running;
} app_state;

void handle_signal(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        app_state *state = (app_state *)malloc(sizeof(app_state));
        state->running = 0;
        free(state);
    }
}

void init_gpio(app_state *state) {
    const char *led_pins[] = { "gpio17", "gpio18", "gpio27", "gpio22" };
    for (int i = 0; i < LED_PATTERN_SIZE; i++) {
        state->leds[i] = gpiod_line_get("gpiochip0", led_pins[i]);
        if (!state->leds[i]) {
            fprintf(stderr, "Failed to get GPIO line %s\n", led_pins[i]);
            exit(EXIT_FAILURE);
        }
        if (gpiod_line_set_direction(state->leds[i], GPIOD_LINE_DIRECTION_OUTPUT)) {
            fprintf(stderr, "Failed to set direction for GPIO %s\n", led_pins[i]);
            exit(EXIT_FAILURE);
        }
    }
}

void deinit_gpio(app_state *state) {
    for (int i = 0; i < LED_PATTERN_SIZE; i++) {
        gpiod_line_release(state->leds[i]);
    }
}

void init_i2c(app_state *state) {
    state->i2c_fd = open(I2C_BUS, O_RDWR | O_CLOEXEC);
    if (state->i2c_fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    if (ioctl(state->i2c_fd, I2C_SLAVE, MPR121_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(state->i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Soft reset
    unsigned char reset_cmd = MPR121_SOFT_RESET;
    if (write(state->i2c_fd, &reset_cmd, 1) != 1) {
        perror("Failed to send soft reset command");
        close(state->i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Verify sensor presence by reading config register
    unsigned char config1;
    if (read(state->i2c_fd, &config1, 1) != 1) {
        perror("Failed to read config register");
        close(state->i2c_fd);
        exit(EXIT_FAILURE);
    }

    if (config1 != 0x00) {
        fprintf(stderr, "MPR121 not responding or not properly initialized\n");
        close(state->i2c_fd);
        exit(EXIT_FAILURE);
    }
}

void deinit_i2c(app_state *state) {
    close(state->i2c_fd);
}

void init_logging(app_state *state) {
    state->log_file = fopen(LOG_FILE, "a");
    if (!state->log_file) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }
}

void deinit_logging(app_state *state) {
    if (state->log_file) {
        fclose(state->log_file);
    }
}

void log_proximity_event(int electrode) {
    time_t now = time(NULL);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
    fprintf(stdout, "[%s] Proximity detected on electrode %d\n", timestamp, electrode);
    fprintf(state->log_file, "[%s] Proximity detected on electrode %d\n", timestamp, electrode);
    fflush(stdout);
    fflush(state->log_file);
}

void update_leds(int touch_status) {
    for (int i = 0; i < LED_PATTERN_SIZE; i++) {
        gpiod_line_set_value(state->leds[i], (touch_status >> i) & 1);
    }
}

void poll_mpr121(app_state *state) {
    unsigned char touch_status;
    if (read(state->i2c_fd, &touch_status, 1) != 1) {
        perror("I2C read failed");
        return;
    }

    if (touch_status & MPR121_TOUCH_BIT_MASK) {
        for (int i = 0; i < 4; i++) {
            if (touch_status & (1 << i)) {
                log_proximity_event(i);
            }
        }
        update_leds(touch_status);
    } else {
        // No touch detected, turn off LEDs
        for (int i = 0; i < LED_PATTERN_SIZE; i++) {
            gpiod_line_set_value(state->leds[i], 0);
        }
    }
}

int main() {
    app_state state = {0};

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    init_gpio(&state);
    init_i2c(&state);
    init_logging(&state);

    state.running = 1;
    while (state.running) {
        poll_mpr121(&state);
        usleep(50000); // 50 ms
    }

    deinit_gpio(&state);
    deinit_i2c(&state);
    deinit_logging(&state);

    return 0;
}
