void monitor_proximity(int fd) {
    while (1) {
        uint8_t proximity_status = i2c_read_byte(fd, 0x0C);
        if (proximity_status & 0x01) {
            // Proximity detected
            printf("Proximity detected!\n");
            FILE *log_file = fopen(PROXIMITY_LOG, "a");
            if (log_file == NULL) {
                perror("Failed to open log file");
                continue;
            }
            time_t now = time(NULL);
            char timestamp[26];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
            fprintf(log_file, "%s - Proximity event detected\n", timestamp);
            fclose(log_file);

            // Turn LED on
            gpiod_line_set_value(app_state->led_line, 1);
            sleep(1);
            gpiod_line_set_value(app_state->led_line, 0);
        }
        usleep(100000); // 100ms delay
    }
