    int i2c_fd = open(i2c_bus_path, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_TEN, 0) < 0) {
        perror("I2C ioctl error");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("I2C slave address set error");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Initialize LED
    struct gpiod_chip *chip = gpiod_chip_open_by_number(1); // BCM GPIOs are on chip 1
    if (!chip) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
