void monitor_proximity(int fd) {
    while (1) {
        uint8_t proximity_status = i2c_read_byte(fd, 0x0C);
        if (proximity_status & 0x01) {
            // Proximity detected
            printf("Proximity detected!\n");
            FILE *log_file = fopen(PROXIMITY_LOG, "a");
            if (log_file == NULL) {
                perror("Failed to open log file");
                continue;
            }
            time_t now = time(NULL);
            char timestamp[26];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
            fprintf(log_file, "%s - Proximity event detected\n", timestamp);
            fclose(log_file);

            // Turn LED on
            gpiod_line_set_value(app_state->led_line, 1);
            sleep(1);
            gpiod_line_set_value(app_state->led_line, 0);
        }
        usleep(100000); // 100ms delay
    }
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Open I2C bus
    char i2c_bus_path[20];
    snprintf(i2c_bus_path, sizeof(i2c_bus_path), "/dev/i2c-%d", I2C_BUS);
    int i2c_fd = open(i2c_bus_path, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_TEN, 0) < 0) {
        perror("I2C ioctl error");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("I2C slave address set error");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Initialize LED
    struct gpiod_chip *chip = gpiod_chip_open_by_number(1); // BCM GPIOs are on chip 1
    if (!chip) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    struct gpiod_line *led_line = gpiod_line_get(chip, LED_PIN, "led");
    if (!led_line) {
        perror("Failed to get LED line");
        gpiod_chip_close(chip);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(led_line, "proximity_led", GPIOD_LINE_REQUEST_OUTPUT_ACTIVE_LOW)) {
        perror("Failed to request LED line");
        gpiod_line_put(led_line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    app_state state;
    state.i2c_fd = i2c_fd;
    state.led_line = led_line;
    state.running = 1;

    configure_mpr121(state.i2c_fd);
    monitor_proximity(state.i2c_fd);

    // Cleanup
    gpiod_line_put(state.led_line);
    gpiod_chip_close(chip);
    close(state.i2c_fd);

    return 0;
}
