int init_gpio(int pin, int direction) {
    int fd;
    struct gpiohandle_request req;
    struct gpiohandle_data data;

    fd = open("/dev/gpiochip0", O_RDWR);
    if (fd < 0) {
        perror("Failed to open gpiochip0");
        return -1;
    }

    req.lineoffset = pin;
    req.flags = GPIOHANDLE_REQUEST_OUTPUT;
    req.lines = 1;
    req.consumer_label = "hc-sr04";

    if (ioctl(fd, GPIO_HANDLE_GET, &req) < 0) {
        perror("Failed to get GPIO handle");
        close(fd);
        return -1;
    }

    data.values[0] = direction;
    if (ioctl(fd, GPIOHANDLE_SET_LINE_VALUES, &data) < 0) {
        perror("Failed to set GPIO line value");
        close(fd);
        return -1;
    }

    close(fd);
    return req.handle;
}

void trigger_pulse(int trigger_fd) {
    struct gpiohandle_data data;
    data.values[0] = 1;
    if (ioctl(trigger_fd, GPIOHANDLE_SET_LINE_VALUES, &data) < 0) {
        perror("Failed to set trigger high");
    }
    usleep(10);
    data.values[0] = 0;
    if (ioctl(trigger_fd, GPIOHANDLE_SET_LINE_VALUES, &data) < 0) {
        perror("Failed to set trigger low");
    }
}

int wait_for_echo(int echo_fd, int timeout_ms) {
    struct gpiohandle_data data;
    int start_time = time(NULL);
    int timeout = timeout_ms;

    while (timeout > 0) {
        if (ioctl(echo_fd, GPIOHANDLE_GET_LINE_VALUES, &data) < 0) {
            perror("Failed to get echo line value");
            return -1;
        }

        if (data.values[0] == 1) {
            return 0; // Echo rising edge detected
        }

        usleep(1000); // Poll every 1 ms
        timeout -= 1;
    }

    return -1; // Timeout
}

int measure_pulse_width(int echo_fd, int timeout_ms) {
    struct gpiohandle_data data;
    int start_time = time(NULL);
    int timeout = timeout_ms;
    int pulse_start = -1;

    while (timeout > 0) {
        if (ioctl(echo_fd, GPIOHANDLE_GET_LINE_VALUES, &data) < 0) {
            perror("Failed to get echo line value");
            return -1;
        }

        if (data.values[0] == 1) {
            pulse_start = time(NULL);
            break;
        }

        usleep(1000);
        timeout -= 1;
    }

    if (pulse_start == -1) {
        return -1; // No rising edge
    }

    timeout = timeout_ms;
    while (timeout > 0) {
        if (ioctl(echo_fd, GPIOHANDLE_GET_LINE_VALUES, &data) < 0) {
            perror("Failed to get echo line value");
            return -1;
        }

        if (data.values[0] == 0) {
            int pulse_duration = time(NULL) - pulse_start;
            return pulse_duration;
        }

        usleep(1000);
        timeout -= 1;
    }

    return -1; // Timeout
