static struct gpiod_line *trig_line = NULL;
static struct gpiod_line *echo_line = NULL;
static FILE *log_file = NULL;
static volatile int running = 1;
static int echo_edge = 0;
static uint64_t last_echo_time = 0;
static uint64_t last_log_time = 0;

void handle_signal(int signum) {
    running = 0;
}

void trigger_pulse() {
    gpiod_line_set_value(trig_line, 1);
    usleep(TRIG_PULSE_US);
    gpiod_line_set_value(trig_line, 0);
}

void echo_callback(struct gpiod_line *line, const struct gpiod_line_event *event, void *data) {
    if (event->type == GPIOD_LINE_EVENT_RISING_EDGE) {
        echo_edge = 1;
        clock_gettime(CLOCK_MONOTONIC, &last_echo_time);
    } else if (event->type == GPIOD_LINE_EVENT_FALLING_EDGE) {
        echo_edge = 0;
        clock_gettime(CLOCK_MONOTONIC, &last_echo_time);
    }
}

void measure_distance() {
    if (!running) return;

    trigger_pulse();

    // Wait for echo to start
    int timeout = 0;
    while (gpiod_line_get_value(echo_line) == 0 && timeout < ECHO_TIMEOUT_US / 1000) {
        usleep(1000);
        timeout++;
    }

    if (timeout >= ECHO_TIMEOUT_US / 1000) {
        return;
    }

    // Wait for echo to end
    timeout = 0;
    while (gpiod_line_get_value(echo_line) == 1 && timeout < ECHO_TIMEOUT_US / 1000) {
        usleep(1000);
        timeout++;
    }

    if (timeout >= ECHO_TIMEOUT_US / 1000) {
        return;
    }

    struct timespec start, end;
    clock_gettime(CLOCK_MONOTONIC, &start);
    while (gpiod_line_get_value(echo_line) == 1) {
        usleep(1000);
        clock_gettime(CLOCK_MONOTONIC, &end);
        if ((end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000 > ECHO_TIMEOUT_US) {
            return;
        }
    }

    clock_gettime(CLOCK_MONOTONIC, &end);
    uint64_t pulse_width_us = (end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000;

    if (pulse_width_us > MIN_PULSE_US && pulse_width_us < MAX_PULSE_US) {
        struct timespec now;
        clock_gettime(CLOCK_MONOTONIC, &now);
        uint64_t timestamp = (now.tv_sec * 1000000000 + now.tv_nsec) / 1000000;

        measurement_t m = { .start = start, .end = end, .pulse_width_us = pulse_width_us, .timestamp = timestamp };

        fprintf(log_file, "%lu,%lu,%lu\n", m.timestamp, m.pulse_width_us, (double)m.pulse_width_us / 58.0 / 1000000);
        fflush(log_file);
    }
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Initialize GPIO
    struct gpiod_chip *chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return 1;
