    if (!trig_line) {
        fprintf(stderr, "Failed to get TRIG line\n");
        gpiod_chip_close(chip);
        return 1;
    }

    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo_line) {
        fprintf(stderr, "Failed to get ECHO line\n");
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_output(trig_line, "trig", GPIOD_LINE_REQUEST_FLAG_ACTIVE_LOW)) {
        fprintf(stderr, "Failed to request TRIG line\n");
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_input(echo_line, "echo", GPIOD_LINE_REQUEST_FLAG_ACTIVE_LOW)) {
        fprintf(stderr, "Failed to request ECHO line\n");
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_set_config(echo_line, GPIOD_LINE_CONFIG_FLAGS_OUTPUT, 0)) {
        fprintf(stderr, "Failed to configure ECHO line\n");
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_set_config(echo_line, GPIOD_LINE_CONFIG_FLAGS_INPUT, 0)) {
        fprintf(stderr, "Failed to configure ECHO line\n");
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_set_edge_event(echo_line, GPIOD_LINE_EVENT_BOTH_EDGES)) {
        fprintf(stderr, "Failed to set edge event on ECHO line\n");
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_event_register(echo_line, echo_callback, NULL)) {
        fprintf(stderr, "Failed to register event callback on ECHO line\n");
        gpiod_chip_close(chip);
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpiod_line_event_unregister(echo_line);
        gpiod_line_set_config(echo_line, 0, 0);
        gpiod_line_release(echo_line);
        gpiod_line_release(trig_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (running) {
        measure_distance();
        usleep(1000000); // 1 second interval
    }

    // Cleanup
    gpiod_line_event_unregister(echo_line);
    gpiod_line_set_config(echo_line, 0, 0);
    gpiod_line_release(echo_line);
    gpiod_line_release(trig_line);
    gpiod_chip_close(chip);

    if (log_file) {
        fclose(log_file);
    }

    return 0;
}

