#define RETRY_DELAY_MS 500

typedef struct {
    int i2c_fd;
    struct gpiod_line *xshut_line;
    int running;
} sensor_state_t;

void log_message(int priority, const char *fmt, ...) {
    va_list args;
    va_start(args, fmt);
    vsyslog(priority, fmt, args);
    va_end(args);
}

void handle_signal(int sig) {
    sensor_state_t *state = (sensor_state_t *)malloc(sizeof(sensor_state_t));
    if (state) {
        state->running = 0;
        free(state);
    }
    syslog(LOG_INFO, "Received signal %d, shutting down...", sig);
}

void init_gpio(sensor_state_t *state) {
    struct gpiod_chip *chip;
    struct gpiod_line *line;

    chip = gpiod_chip_open("/dev/gpiochip27");
    if (!chip) {
        log_message(LOG_ERR, "Failed to open GPIO chip for XSHUT pin");
        exit(EXIT_FAILURE);
    }

    line = gpiod_line_request_output(chip, "XSHUT", "XSHUT", 1, 0);
    if (!line) {
        log_message(LOG_ERR, "Failed to request XSHUT GPIO line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    state->xshut_line = line;
    gpiod_line_set_value(line, 1); // Set high to enable sensor
}

void close_gpio(sensor_state_t *state) {
    if (state->xshut_line) {
        gpiod_line_release(state->xshut_line);
    }
}

void init_i2c(sensor_state_t *state) {
    char i2c_bus_path[32];
    snprintf(i2c_bus_path, sizeof(i2c_bus_path), "/dev/i2c-%d", I2C_BUS);

    state->i2c_fd = open(i2c_bus_path, O_RDWR);
    if (state->i2c_fd < 0) {
        log_message(LOG_ERR, "Failed to open I2C bus %d: %s", I2C_BUS, strerror(errno));
        exit(EXIT_FAILURE);
    }

