#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <errno.h>
#include <time.h>

#define I2C_BUS 1
#define I2C_ADDR 0x29
#define LED_PIN 17
#define BUFFER_SIZE 10
#define MIN_DISTANCE_MM 200
#define POLL_INTERVAL_MS 50

typedef struct {
    int buffer[BUFFER_SIZE];
    int head;
    int tail;
    int full;
} CircularBuffer;

void init_buffer(CircularBuffer *cb) {
    cb->head = 0;
    cb->tail = 0;
    cb->full = 0;
}

void write_buffer(CircularBuffer *cb, int value) {
    if (cb->full) {
        cb->tail = (cb->tail + 1) % BUFFER_SIZE;
    }
    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    cb->full = (cb->head == cb->tail);
}

int read_buffer(CircularBuffer *cb, int *value) {
    if (!cb->full && cb->head == cb->tail) {
        return -1; // buffer empty
    }
    *value = cb->buffer[cb->tail];
    cb->tail = (cb->tail + 1) % BUFFER_SIZE;
    cb->full = (cb->head == cb->tail);
    return 0;
}

void sigint_handler(int sig) {
    // Turn off LED
    gpiod_line_set_value(led_line, 0);
    // Close I2C device
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    // Release GPIO line
    gpiod_line_release(led_line);
    // Exit program
    exit(EXIT_SUCCESS);
}

int i2c_write(int fd, const void *buf, size_t len) {
    int ret;
    do {
        ret = write(fd, buf, len);
    } while (ret < 0 && errno == EINTR);
    if (ret < 0) {
        fprintf(stderr, "I2C write error: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int i2c_read(int fd, void *buf, size_t len) {
    int ret;
    do {
        ret = read(fd, buf, len);
    } while (ret < 0 && errno == EINTR);
    if (ret < 0) {
        fprintf(stderr, "I2C read error: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int vl53l1x_init(int i2c_fd) {
    // Default configuration
    uint8_t default_config[] = {
        0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
        0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
        0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
        0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00
    };

    if (i2c_write(i2c_fd, default_config, sizeof(default_config)) < 0) {
        fprintf(stderr, "Failed to set default configuration\n");
        return -1;
    }

    // Enable signal-rate checking
    uint8_t signal_rate_check[] = {0x00, 0x01};
    if (i2c_write(i2c_fd, signal_rate_check, sizeof(signal_rate_check)) < 0) {
        fprintf(stderr, "Failed to enable signal-rate checking\n");
        return -1;
    }

    // Configure cross-talk compensation
    uint8_t cross_talk_comp[] = {0x00, 0x01};
    if (i2c_write(i2c_fd, cross_talk_comp, sizeof(cross_talk_comp)) < 0) {
        fprintf(stderr, "Failed to configure cross-talk compensation\n");
        return -1;
    }

    // Start ranging
    uint8_t start_ranging[] = {0x00, 0x01};
    if (i2c_write(i2c_fd, start_ranging, sizeof(start_ranging)) < 0) {
        fprintf(stderr, "Failed to start ranging\n");
        return -1;
    }

    return 0;
}

int main() {
    int i2c_fd = -1;
    struct gpiod_line *led_line = NULL;
    CircularBuffer cb;
    int distance = 0;
    int last_distance = 0;
    int i;
    struct sigaction sa;
    int ret;

    // Initialize circular buffer
    init_buffer(&cb);

    // Open I2C device
    char i2c_dev[20];
