#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <pthread.h>
#include <signal.h>
#include <gpiod.h>
#include <errno.h>

#define I2C_BUS 1
#define I2C_ADDR_DEFAULT 0x60
#define GPIO_PIN 27
#define LOG_FILE "proximity.log"
#define DEFAULT_THRESHOLD 1000

typedef struct {
    int i2c_fd;
    int threshold;
    FILE *log_file;
    int interrupt_flag;
    pthread_mutex_t log_mutex;
    pthread_t interrupt_thread;
    gpiod_line *gpio_line;
} sensor_state_t;

void usage(char *progname) {
    fprintf(stderr, "Usage: %s [-t <threshold>] [-a <i2c_address>]\n", progname);
    fprintf(stderr, "  -t <threshold>   Set threshold (default: %d)\n", DEFAULT_THRESHOLD);
    fprintf(stderr, "  -a <i2c_address> Set I2C address (hex or decimal, default: 0x60)\n");
    exit(EXIT_FAILURE);
}

void handle_signal(int sig) {
    if (sig == SIGINT) {
        printf("Shutting down...\n");
        exit(EXIT_SUCCESS);
    }
}

void log_proximity(sensor_state_t *state, int proximity) {
    time_t now;
    struct tm *tm_info;
    char timestamp[20];

    time(&now);
    tm_info = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    pthread_mutex_lock(&state->log_mutex);
    fprintf(state->log_file, "%s %d %s\n", timestamp, proximity, (proximity <= state->threshold) ? "SAFE" : "ALERT");
    fflush(state->log_file);
    pthread_mutex_unlock(&state->log_mutex);
}

void *interrupt_handler(void *arg) {
    sensor_state_t *state = (sensor_state_t *)arg;

    while (1) {
        pthread_mutex_lock(&state->log_mutex);
        if (state->interrupt_flag) {
            state->interrupt_flag = 0;
            pthread_mutex_unlock(&state->log_mutex);

            int proximity = 0;
            unsigned char reg[2] = {0x00, 0x00};

            // Read proximity value from Si1102
            if (ioctl(state->i2c_fd, I2C_SLAVE, state->i2c_addr) < 0) {
                perror("Failed to set I2C slave address");
                continue;
            }

            if (write(state->i2c_fd, reg, 1) != 1) {
                perror("Failed to write to I2C");
                continue;
            }

            if (read(state->i2c_fd, reg, 2) != 2) {
                perror("Failed to read from I2C");
                continue;
            }

            proximity = (reg[0] << 8) | reg[1];

            log_proximity(state, proximity);
        } else {
            pthread_mutex_unlock(&state->log_mutex);
        }

        usleep(10000); // Small delay to prevent busy-waiting
    }

    return NULL;
}

int init_i2c(int bus, int addr) {
    char i2c_bus_path[32];
    snprintf(i2c_bus_path, sizeof(i2c_bus_path), "/dev/i2c-%d", bus);

    int fd = open(i2c_bus_path, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Failed to set I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

int init_gpio(int pin) {
    struct gpiod_line *line;
    struct gpiod_line_request_config req_config;
    struct gpiod_line_request_config *config = &req_config;

    memset(config, 0, sizeof(*config));
    config->line = pin;
    config->flags = GPIOD_LINE_REQUEST_FLAG_ACTIVE_LOW;
    config->consumer = "proximity_interrupt";
    config->direction = GPIOD_LINE_DIRECTION_INPUT;
    config->flags |= GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP;

    line = gpiod_line_request(config);
    if (!line) {
        perror("Failed to request GPIO line");
        return -1;
    }

    if (gpiod_line_get_value(line) < 0) {
        perror("Failed to get initial GPIO value");
        gpiod_line_release(line);
        return -1;
    }

    return line;
}

void cleanup(sensor_state_t *state) {
    if (state->i2c_fd >= 0) {
        close(state->i2c_fd);
    }

    if (state->log_file) {
        fclose(state->log_file);
    }

    if (state->gpio_line) {
        gpiod_line_release(state->gpio_line);
    }

    pthread_mutex_destroy(&state->log_mutex);
    pthread_cancel(state->interrupt_thread);
    pthread_join(state->interrupt_thread, NULL);
}

int main(int argc, char *argv[]) {
    int opt;
    int threshold = DEFAULT_THRESHOLD;
    int i2c_addr = I2C_ADDR_DEFAULT;
    sensor_state_t state = {0};

    while ((opt = getopt(argc, argv, "t:a:")) != -1) {
        switch (opt) {
            case 't':
                threshold = atoi(optarg);
                break;
            case 'a':
                if (sscanf(optarg, "%x", &i2c_addr) == 1 || sscanf(optarg, "%d", &i2c_addr) == 1) {
                    break;
                } else {
                    fprintf(stderr, "Invalid I2C address: %s\n", optarg);
                    usage(argv[0]);
                }
                break;
            default:
                usage(argv[0]);
        }
    }

    if (signal(SIGINT, handle_signal) == SIG_ERR) {
        perror("Failed to set signal handler");
        return EXIT_FAILURE;
    }

    state.i2c_fd = init_i2c(I2C_BUS, i2c_addr);
    if (state.i2c_fd < 0) {
        return EXIT_FAILURE;
    }

    state.gpio_line = init_gpio(GPIO_PIN);
    if (!state.gpio_line) {
        cleanup(&state);
        return EXIT_FAILURE;
    }

    state.threshold = threshold;

    state.log_file = fopen(LOG_FILE, "a");
    if (!state.log_file) {
        perror("Failed to open log file");
        cleanup(&state);
        return EXIT_FAILURE;
    }

    pthread_mutex_init(&state.log_mutex, NULL);

    state.interrupt_flag = 0;
    pthread_create(&state.interrupt_thread, NULL, interrupt_handler, &state);

    // Set up GPIO interrupt
    struct gpiod_line_event event;
    struct gpiod_line_event_config event_config;
    struct gpiod_line_request_config req_config;
    struct gpiod_line_request_config *config = &req_config;

    memset(config, 0, sizeof(*config));
    config->line = GPIO_PIN;
    config->flags = GPIOD_LINE_REQUEST_FLAG_ACTIVE_LOW;
    config->consumer = "proximity_interrupt";
    config->direction = GPIOD_LINE_DIRECTION_INPUT;
    config->flags |= GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP;

    if (gpiod_line_request(config) < 0) {
        perror("Failed to request GPIO line");
        cleanup(&state);
        return EXIT_FAILURE;
    }

    memset(&event_config, 0, sizeof(event_config));
    event_config.line = GPIO_PIN;
    event_config.flags = GPIOD_LINE_EVENT_FLAG_RISING_EDGE;
    event_config.consumer = "proximity_interrupt";

    if (gpiod_line_event_request(state.gpio_line, &event_config) < 0) {
        perror("Failed to request GPIO event");
        cleanup(&state);
        return EXIT_FAILURE;
    }

    while (1) {
        if (gpiod_line_event_read(state.gpio_line, &event) < 0) {
            perror("Failed to read GPIO event");
            break;
        }

        if (event.type == GPIOD_LINE_EVENT_TYPE_RISING_EDGE) {
            pthread_mutex_lock(&state.log_mutex);
            state.interrupt_flag = 1;
            pthread_mutex_unlock(&state.log_mutex);
        }
    }

    cleanup(&state);
    return EXIT_SUCCESS;
}

