#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/gpio.h>
#include <libgpiod.h>

#define BCM_GPIO_TRIGGER 23
#define BCM_GPIO_ECHO 24
#define BCM_GPIO_BUZZER 18
#define PWM_CHANNEL 0
#define PWM_PERIOD_US 1000000
#define PWM_DUTY_CYCLE 500000
#define ECHO_TIMEOUT_MS 100
#define MIN_DISTANCE_CM 5
#define MAX_DISTANCE_CM 50
#define MIN_FREQUENCY_HZ 200
#define MAX_FREQUENCY_HZ 2000
#define READ_INTERVAL_MS 10

typedef struct {
    struct gpiod_line *trigger_line;
    struct gpiod_line *echo_line;
    struct gpiod_line *buzzer_line;
    struct gpiod_pwm *pwm;
    int pwm_fd;
    int last_valid_distance;
    int last_valid_frequency;
    int running;
} sensor_state;

void handle_sigint(int sig) {
    sensor_state *state = (sensor_state *)malloc(sizeof(sensor_state));
    if (state) {
        state->running = 0;
    }
    printf("\nSIGINT received. Shutting down...\n");
    // Stop PWM
    if (state->pwm) {
        gpiod_pwm_set_frequency(state->pwm, 0);
        gpiod_pwm_set_duty_cycle(state->pwm, 0);
    }
    // Close lines
    if (state->trigger_line) {
        gpiod_line_release(state->trigger_line);
    }
    if (state->echo_line) {
        gpiod_line_release(state->echo_line);
    }
    if (state->buzzer_line) {
        gpiod_line_release(state->buzzer_line);
    }
    // Close PWM
    if (state->pwm_fd >= 0) {
        close(state->pwm_fd);
    }
    free(state);
    exit(0);
}

int init_gpio(sensor_state *state) {
    int ret;

    // Initialize trigger line
    state->trigger_line = gpiod_line_get("BCM", BCM_GPIO_TRIGGER, "trigger");
    if (!state->trigger_line) {
        fprintf(stderr, "Failed to get trigger line\n");
        return -1;
    }
    if (gpiod_line_set_direction(state->trigger_line, GPIOD_LINE_DIRECTION_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set trigger line direction\n");
        gpiod_line_release(state->trigger_line);
        return -1;
    }

    // Initialize echo line
    state->echo_line = gpiod_line_get("BCM", BCM_GPIO_ECHO, "echo");
    if (!state->echo_line) {
        fprintf(stderr, "Failed to get echo line\n");
        gpiod_line_release(state->trigger_line);
        return -1;
    }
    if (gpiod_line_set_direction(state->echo_line, GPIOD_LINE_DIRECTION_INPUT) < 0) {
        fprintf(stderr, "Failed to set echo line direction\n");
        gpiod_line_release(state->trigger_line);
        gpiod_line_release(state->echo_line);
        return -1;
    }

    // Initialize buzzer line
    state->buzzer_line = gpiod_line_get("BCM", BCM_GPIO_BUZZER, "buzzer");
    if (!state->buzzer_line) {
        fprintf(stderr, "Failed to get buzzer line\n");
        gpiod_line_release(state->trigger_line);
        gpiod_line_release(state->echo_line);
        return -1;
    }
    if (gpiod_line_set_direction(state->buzzer_line, GPIOD_LINE_DIRECTION_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set buzzer line direction\n");
        gpiod_line_release(state->trigger_line);
        gpiod_line_release(state->echo_line);
        gpiod_line_release(state->buzzer_line);
        return -1;
    }

    // Initialize PWM
    state->pwm_fd = open("/dev/pwm", O_RDWR);
    if (state->pwm_fd < 0) {
        fprintf(stderr, "Failed to open PWM device\n");
        gpiod_line_release(state->trigger_line);
        gpiod_line_release(state->echo_line);
        gpiod_line_release(state->buzzer_line);
        return -1;
    }

    state->pwm = gpiod_pwm_get(state->pwm_fd, BCM_GPIO_BUZZER, PWM_CHANNEL);
    if (!state->pwm) {
        fprintf(stderr, "Failed to get PWM line\n");
        close(state->pwm_fd);
        gpiod_line_release(state->trigger_line);
        gpiod_line_release(state->echo_line);
        gpiod_line_release(state->buzzer_line);
        return -1;
    }

    // Set PWM period and duty cycle
