#define LOOP_INTERVAL_MS 500
#define MIN_DISTANCE_CM 2
#define MAX_DISTANCE_CM 400
#define TOO_CLOSE_DISTANCE_CM 10

volatile int exit_flag = 0;

void signal_handler(int signum) {
    exit_flag = 1;
}

int measure_distance(gpiod_line *trigger_line, gpiod_line *echo_line) {
    int duration_us = 0;
    int ret;

    // Trigger the sensor
    ret = gpiod_line_set_value(trigger_line, 1);
    if (ret < 0) {
        fprintf(stderr, "Failed to set trigger high: %s\n", strerror(-ret));
        return -1;
    }

    usleep(10); // 10 microseconds pulse

    ret = gpiod_line_set_value(trigger_line, 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to set trigger low: %s\n", strerror(-ret));
        return -1;
    }

    // Wait for echo to go high
    struct timespec start, end;
    clock_gettime(CLOCK_MONOTONIC, &start);

    while (1) {
        int value;
        ret = gpiod_line_get_value(echo_line, &value);
        if (ret < 0) {
            fprintf(stderr, "Failed to read echo pin: %s\n", strerror(-ret));
            return -1;
        }

        if (value == 1) {
            break;
        }

        // Check for timeout
        clock_gettime(CLOCK_MONOTONIC, &end);
        if ((end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000 > TIMEOUT_MS * 1000) {
            return -1; // Timeout
        }

        usleep(100); // Poll every 100 microseconds
    }

    // Wait for echo to go low
    while (1) {
        int value;
        ret = gpiod_line_get_value(echo_line, &value);
        if (ret < 0) {
            fprintf(stderr, "Failed to read echo pin: %s\n", strerror(-ret));
            return -1;
        }

        if (value == 0) {
            break;
        }

        // Check for timeout
        clock_gettime(CLOCK_MONOTONIC, &end);
        if ((end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000 > TIMEOUT_MS * 1000) {
            return -1; // Timeout
        }

        usleep(100); // Poll every 100 microseconds
    }

    // Calculate duration
    duration_us = ((end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000);

    // Convert to centimeters
    double distance_cm = duration_us * 0.034 / 2;

    return (int)distance_cm;
}

int main() {
    gpiod_line *trigger_line = NULL;
    gpiod_line *echo_line = NULL;
    int ret;

    // Initialize the GPIO library
    struct gpiod_chip *chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        return 1;
    }

    // Configure trigger pin (BCM 17)
    trigger_line = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trigger_line) {
        fprintf(stderr, "Failed to get trigger line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    ret = gpiod_line_request_output(trigger_line, "trigger", GPIOD_LINE_REQUEST_FLAG_ACTIVE_LOW);
    if (ret < 0) {
        fprintf(stderr, "Failed to request trigger line: %s\n", strerror(-ret));
        gpiod_line_release(trigger_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Configure echo pin (BCM 18)
    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo_line) {
        fprintf(stderr, "Failed to get echo line: %s\n", strerror(errno));
        gpiod_line_release(trigger_line);
        gpiod_chip_close(chip);
        return 1;
    }

    ret = gpiod_line_request_input(echo_line, "echo", GPIOD_LINE_REQUEST_FLAG_ACTIVE_LOW);
    if (ret < 0) {
        fprintf(stderr, "Failed to request echo line: %s\n", strerror(-ret));
        gpiod_line_release(trigger_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    while (!exit_flag) {
        int distance = measure_distance(trigger_line, echo_line);

        if (distance < 0) {
            printf("Invalid reading\n");
        } else {
            double distance_cm = (double)distance;
            if (distance_cm < MIN_DISTANCE_CM || distance_cm > MAX_DISTANCE_CM) {
                printf("Invalid reading\n");
            } else {
                printf("Distance: %.2f cm\n", distance_cm);
                if (distance_cm < TOO_CLOSE_DISTANCE_CM) {
                    printf("Too close!\n");
                }
            }
        }

        usleep(LOOP_INTERVAL_MS * 1000);
    }

    // Clean up
    gpiod_line_release(trigger_line);
    gpiod_line_release(echo_line);
    gpiod_chip_close(chip);

    return 0;
}

