        if (state->cs_line) {
            gpiod_line_release(state->cs_line);
        }
        free(state);
    }
}

void log_error(const char *msg) {
    fprintf(stderr, "Error: %s\n", msg);
}

int init_spi(app_state *state) {
    state->spi_fd = open(SPI_DEVICE, O_RDWR | O_NOCTTY | O_SYNC);
    if (state->spi_fd < 0) {
        log_error("Failed to open SPI device");
        return -1;
    }

    struct spi_ioc_transfer spi;
    memset(&spi, 0, sizeof(spi));
    spi.speed_hz = SPI_SPEED;
    spi.mode = SPI_MODE;
    spi.bits_per_word = 8;

    if (ioctl(state->spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        log_error("Failed to set SPI mode");
        close(state->spi_fd);
        return -1;
    }

    if (ioctl(state->spi_fd, SPI_IOC_WR_BITS_PER_WORD, &spi.bits_per_word) < 0) {
        log_error("Failed to set SPI bits per word");
        close(state->spi_fd);
        return -1;
    }

    if (ioctl(state->spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        log_error("Failed to set SPI speed");
        close(state->spi_fd);
        return -1;
    }

    return 0;
}

int init_cs_gpio(app_state *state) {
    struct gpiod_chip *chip;
    chip = gpiod_chip_open(CS_GPIO_LINE);
    if (!chip) {
        log_error("Failed to open GPIO chip");
        return -1;
    }

    state->cs_line = gpiod_line_get(chip, CS_GPIO_LINE);
    if (!state->cs_line) {
        log_error("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(state->cs_line, "cs", 1) < 0) {
        log_error("Failed to request GPIO line as output");
        gpiod_line_release(state->cs_line);
        gpiod_chip_close(chip);
        return -1;
    }

    gpiod_line_set_value(state->cs_line, 1);
    gpiod_chip_close(chip);
    return 0;
}

int read_distance(app_state *state) {
    unsigned char tx[2] = {0x00, 0x00};
    unsigned char rx[4] = {0};

    gpiod_line_set_value(state->cs_line, 0);
    int ret = ioctl(state->spi_fd, SPI_IOC_MESSAGE(1), &tx);
    if (ret < 0) {
        log_error("SPI write error");
        return -1;
    }

    ret = ioctl(state->spi_fd, SPI_IOC_MESSAGE(1), &rx);
    if (ret < 0) {
        log_error("SPI read error");
        return -1;
    }

    gpiod_line_set_value(state->cs_line, 1);

    // Extract distance from rx[1] and rx[2]
    int distance = (rx[1] << 8) | rx[2];
    if (distance < MIN_DISTANCE_MM || distance > MAX_DISTANCE_MM) {
        log_error("Distance out of valid range");
        return -1;
    }

    return distance;
}

void log_distance(app_state *state, int distance) {
    time_t now = time(NULL);
    struct tm *tm_now = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_now);

    fprintf(state->log_file, "%s,%d\n", timestamp, distance);
    fflush(state->log_file);
}

int init_log_file(app_state *state) {
    state->log_file = fopen(LOG_FILE, "a");
    if (!state->log_file) {
        log_error("Failed to open log file");
        return -1;
    }
    return 0;
}

void cleanup(app_state *state) {
    if (state->log_file) {
        fprintf(state->log_file, "\n");
        fflush(state->log_file);
        fclose(state->log_file);
    }
    if (state->spi_fd >= 0) {
        close(state->spi_fd);
    }
    if (state->cs_line) {
        gpiod_line_release(state->cs_line);
    }
}

int main() {
    app_state state = {0};

    if (signal(SIGINT, handle_signal) == SIG_ERR || signal(SIGTERM, handle_signal) == SIG_ERR) {
        log_error("Failed to install signal handler");
        return 1;
    }

    if (init_spi(&state) < 0) {
        return 1;
    }

    if (init_cs_gpio(&state) < 0) {
        close(state.spi_fd);
        return 1;
    }

    if (init_log_file(&state) < 0) {
        cleanup(&state);
        return 1;
    }

    state.running = 1;
    while (state.running) {
        int distance = read_distance(&state);
        if (distance >= 0) {
            log_distance(&state, distance);
        }
        usleep(DELAY_MS * 1000);
    }

    cleanup(&state);
    return 0;
}

