#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <errno.h>
#include <signal.h>
#include <gpiod.h>

#define I2C_BUS 1
#define I2C_ADDR 0x60
#define SI1120_RESET_REGISTER 0x8000
#define SI1120_PART_ID_REGISTER 0x0000
#define SI1120_PART_ID_VALUE 0x0001
#define SI1120_ALS_REGISTER 0x0001
#define SI1120_PROX_REGISTER 0x0002
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10
#define LOG_FILE "si1120_log.txt"
#define SAMPLE_INTERVAL_MS 500

typedef struct {
    int i2c_fd;
    FILE *log_file;
    gpiod_line *reset_line;
} sensor_context;

void handle_error(const char *msg, int fd, FILE *log_file, sensor_context *ctx) {
    fprintf(stderr, "%s: %s\n", msg, strerror(errno));
    if (log_file) {
        fprintf(log_file, "%s: %s\n", msg, strerror(errno));
        fclose(log_file);
    }
    if (fd >= 0) {
        close(fd);
    }
    if (ctx->i2c_fd >= 0) {
        close(ctx->i2c_fd);
    }
    if (ctx->reset_line) {
        gpiod_line_release(ctx->reset_line);
    }
    exit(EXIT_FAILURE);
}

void reset_sensor(sensor_context *ctx) {
    int retries = 0;
    int result;
    while (retries < MAX_RETRIES) {
        result = gpiod_line_set_value(ctx->reset_line, 0);
        if (result == 0) {
            usleep(10000); // 10ms
            result = gpiod_line_set_value(ctx->reset_line, 1);
            if (result == 0) {
                usleep(10000); // 10ms
                break;
            }
        }
        retries++;
        usleep(RETRY_DELAY_MS * 1000);
    }
    if (retries >= MAX_RETRIES) {
        handle_error("Failed to reset sensor", ctx->i2c_fd, ctx->log_file, ctx);
    }
}

int read_register(sensor_context *ctx, uint16_t reg, uint8_t *data) {
    int retries = 0;
    while (retries < MAX_RETRIES) {
        uint8_t buf[2];
        buf[0] = reg >> 8;
        buf[1] = reg & 0xFF;
        if (write(ctx->i2c_fd, buf, 2) != 2) {
            handle_error("Failed to write register address", ctx->i2c_fd, ctx->log_file, ctx);
        }
        if (read(ctx->i2c_fd, data, 2) != 2) {
            handle_error("Failed to read register data", ctx->i2c_fd, ctx->log_file, ctx);
        }
        if (data[0] == (reg >> 8) && data[1] == (reg & 0xFF)) {
            return 0;
        }
        retries++;
        usleep(RETRY_DELAY_MS * 1000);
    }
    handle_error("Failed to read register after retries", ctx->i2c_fd, ctx->log_file, ctx);
    return -1;
}

void verify_part_id(sensor_context *ctx) {
    uint8_t part_id[2];
    if (read_register(ctx, SI1120_PART_ID_REGISTER, part_id) != 0) {
        handle_error("Failed to read part ID", ctx->i2c_fd, ctx->log_file, ctx);
    }
    if ((part_id[0] << 8) | part_id[1] != SI1120_PART_ID_VALUE) {
        handle_error("Invalid part ID", ctx->i2c_fd, ctx->log_file, ctx);
    }
}

void read_sensor_data(sensor_context *ctx, uint16_t *als, uint16_t *prox) {
    uint8_t als_data[2];
    uint8_t prox_data[2];
    if (read_register(ctx, SI1120_ALS_REGISTER, als_data) != 0) {
        handle_error("Failed to read ALS data", ctx->i2c_fd, ctx->log_file, ctx);
    }
    if (read_register(ctx, SI1120_PROX_REGISTER, prox_data) != 0) {
        handle_error("Failed to read proximity data", ctx->i2c_fd, ctx->log_file, ctx);
    }
    *als = (als_data[0] << 8) | als_data[1];
    *prox = (prox_data[0] << 8) | prox_data[1];
}

void log_data(FILE *log_file, time_t timestamp, uint16_t als, uint16_t prox) {
    struct tm *tm_info = localtime(&timestamp);
    char buffer[20];
    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", tm_info);
    fprintf(log_file, "%s,%04x,%04x\n", buffer, als, prox);
    fflush(log_file);
}

void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Received SIGINT, exiting...\n");
        exit(EXIT_SUCCESS);
    }
}

int main() {
    sensor_context ctx = {0};

    // Open I2C bus
    char i2c_bus_path[32];
    snprintf(i2c_bus_path, sizeof(i2c_bus_path), "/dev/i2c-%d", I2C_BUS);
    ctx.i2c_fd = open(i2c_bus_path, O_RDWR);
    if (ctx.i2c_fd < 0) {
        handle_error("Failed to open I2C bus", ctx.i2c_fd, NULL, &ctx);
    }

    // Set I2C address
    if (ioctl(ctx.i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        handle_error("Failed to set I2C address", ctx.i2c_fd, NULL, &ctx);
    }

    // Initialize GPIO for reset line
    const char *reset_line_name = "gpio25";
    struct gpiod_line *reset_line;
    ctx.reset_line = gpiod_line_get(reset_line_name, "gpio");
    if (!ctx.reset_line) {
        handle_error("Failed to get GPIO line", ctx.i2c_fd, NULL, &ctx);
    }

    // Open log file
    ctx.log_file = fopen(LOG_FILE, "a");
    if (!ctx.log_file) {
        handle_error("Failed to open log file", ctx.i2c_fd, NULL, &ctx);
    }

    // Reset sensor
    reset_sensor(&ctx);
    verify_part_id(&ctx);

    // Set up signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        uint16_t als, prox;
        time_t timestamp = time(NULL);
