typedef struct {
    int fd;
    int retry_count;
} i2c_handle;

void log_message(const char *message, FILE *log_file) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);
    fprintf(log_file, "[%s] %s\n", timestamp, message);
    fflush(log_file);
}

int i2c_init(i2c_handle *handle) {
    handle->fd = open(I2C_BUS, O_RDWR);
    if (handle->fd < 0) {
        log_message("Failed to open I2C bus", stdout);
        return -1;
    }

    if (ioctl(handle->fd, I2C_SLAVE, I2C_ADDR) < 0) {
        log_message("Failed to set I2C slave address", stdout);
        close(handle->fd);
        return -1;
    }

    handle->retry_count = 0;
    return 0;
}

int i2c_read_register(i2c_handle *handle, uint8_t reg, uint8_t *value) {
    uint8_t buffer[1];
    buffer[0] = reg;
    if (write(handle->fd, buffer, 1) < 0) {
        log_message("I2C write error", stdout);
        return -1;
    }

    if (read(handle->fd, value, 1) < 0) {
        log_message("I2C read error", stdout);
        return -1;
    }

    return 0;
}

uint16_t get_proximity_value(i2c_handle *handle) {
    uint8_t data0, data1;
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (i2c_read_register(handle, PS1_DATA0, &data0) == 0 &&
            i2c_read_register(handle, PS1_DATA1, &data1) == 0) {
            return (uint16_t)(data1 << 8 | data0);
        }

        log_message("I2C communication failed, retrying...", stdout);
        retries++;
        usleep(100000); // 100ms delay
    }

    log_message("I2C communication failed after maximum retries", stdout);
    return 0;
}

void handle_signal(int signal) {
    log_message("Received signal, shutting down...", stdout);
    // Clean up here if needed
    exit(EXIT_SUCCESS);
}

int main() {
    i2c_handle i2c;
    FILE *log_file;
    int result;

    // Initialize signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

