    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        log_message("Failed to open log file", stdout);
        return EXIT_FAILURE;
    }

    // Initialize I2C
    if (i2c_init(&i2c) < 0) {
        log_message("I2C initialization failed", stdout);
        fclose(log_file);
        return EXIT_FAILURE;
    }

    // Main loop
    while (1) {
        uint16_t proximity = get_proximity_value(&i2c);
        if (proximity == 0) {
            log_message("Failed to read proximity data", log_file);
            continue;
