        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);
        fprintf(log_file, "%s,%u\n", timestamp, proximity);
        fflush(log_file);
        usleep(100000); // 100ms delay
    }

    // Close resources
    fclose(log_file);
    close(i2c.fd);
    return EXIT_SUCCESS;
}

