#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/gpio.h>
#include <time.h>

#define BCM_TRIGGER_PIN 17
#define BCM_ECHO_PIN 18
#define BCM_BUZZER_PIN 27
#define MIN_DISTANCE_CM 20.0
#define TRIGGER_PULSE_US 10
#define POLLING_INTERVAL_MS 1000

typedef struct {
    int trigger_fd;
    int echo_fd;
    int buzzer_fd;
    int echo_line;
    int echo_edge;
    struct timespec start_time;
    struct timespec end_time;
    double distance_cm;
    int running;
} sensor_data_t;

void cleanup(sensor_data_t *data) {
    if (data->running) {
        if (data->echo_fd >= 0) {
            gpio_line_release(data->echo_fd);
            close(data->echo_fd);
        }
        if (data->trigger_fd >= 0) {
            gpio_line_release(data->trigger_fd);
            close(data->trigger_fd);
        }
        if (data->buzzer_fd >= 0) {
            gpio_line_release(data->buzzer_fd);
            close(data->buzzer_fd);
        }
    }
}

void signal_handler(int signum) {
    if (signum == SIGINT) {
        printf("\nCaught SIGINT, cleaning up...\n");
        cleanup(NULL);
        exit(EXIT_SUCCESS);
    }
}

void trigger_pulse(int trigger_fd) {
    int ret;
    struct gpio_line_request req = {
        .lineoffset = BCM_TRIGGER_PIN,
        .flags = GPIO_LINE_FLAG_OUTPUT
    };

    ret = gpio_line_request(trigger_fd, &req);
    if (ret < 0) {
        fprintf(stderr, "Failed to request trigger line: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    gpio_line_set_value(trigger_fd, BCM_TRIGGER_PIN, 1);
    usleep(TRIGGER_PULSE_US);
    gpio_line_set_value(trigger_fd, BCM_TRIGGER_PIN, 0);
}

void echo_callback(int line_fd, unsigned int event, void *data) {
    sensor_data_t *sensor = (sensor_data_t *)data;

    if (event == GPIO_LINE_EVENT_RISING_EDGE) {
        clock_gettime(CLOCK_MONOTONIC, &sensor->start_time);
    } else if (event == GPIO_LINE_EVENT_FALLING_EDGE) {
        clock_gettime(CLOCK_MONOTONIC, &sensor->end_time);
        long long duration_us = (sensor->end_time.tv_sec - sensor->start_time.tv_sec) * 1000000LL +
                               (sensor->end_time.tv_nsec - sensor->start_time.tv_nsec) / 1000LL;

        sensor->distance_cm = (double)duration_us * 0.0343 / 2.0;
        printf("Distance: %.2f cm\n", sensor->distance_cm);

        if (sensor->distance_cm < MIN_DISTANCE_CM) {
            gpio_line_set_value(sensor->buzzer_fd, BCM_BUZZER_PIN, 1);
        } else {
            gpio_line_set_value(sensor->buzzer_fd, BCM_BUZZER_PIN, 0);
        }
    }
}

int main() {
    sensor_data_t sensor = {0};
    struct gpio_line_request echo_req = {
        .lineoffset = BCM_ECHO_PIN,
        .flags = GPIO_LINE_FLAG_INPUT | GPIO_LINE_FLAG_ACTIVE_LOW
    };
    struct gpio_line_request buzzer_req = {
        .lineoffset = BCM_BUZZER_PIN,
        .flags = GPIO_LINE_FLAG_OUTPUT
    };

    signal(SIGINT, signal_handler);

    // Initialize trigger line
    sensor.trigger_fd = open("/dev/gpiochip0", O_RDWR);
    if (sensor.trigger_fd < 0) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    if (gpio_line_request(sensor.trigger_fd, &echo_req) < 0) {
        fprintf(stderr, "Failed to request echo line: %s\n", strerror(errno));
        cleanup(&sensor);
        exit(EXIT_FAILURE);
    }

    if (gpio_line_request(sensor.trigger_fd, &buzzer_req) < 0) {
        fprintf(stderr, "Failed to request buzzer line: %s\n", strerror(errno));
        cleanup(&sensor);
        exit(EXIT_FAILURE);
    }

    // Initialize echo line
    sensor.echo_fd = open("/dev/gpiochip0", O_RDWR);
    if (sensor.echo_fd < 0) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        cleanup(&sensor);
        exit(EXIT_FAILURE);
    }

    if (gpio_line_request(sensor.echo_fd, &echo_req) < 0) {
        fprintf(stderr, "Failed to request echo line: %s\n", strerror(errno));
        cleanup(&sensor);
        exit(EXIT_FAILURE);
    }

    // Set up edge detection on echo line
    struct gpio_line_event_config event_config = {
        .events = GPIO_LINE_EVENT_RISING_EDGE | GPIO_LINE_EVENT_FALLING_EDGE
    };

    if (ioctl(sensor.echo_fd, GPIO_LINE_SET_EVENT_CONFIG, &event_config) < 0) {
        fprintf(stderr, "Failed to set event config on echo line: %s\n", strerror(errno));
        cleanup(&sensor);
        exit(EXIT_FAILURE);
    }

    if (gpio_line_event_register(sensor.echo_fd, echo_callback, &sensor) < 0) {
        fprintf(stderr, "Failed to register echo event callback: %s\n", strerror(errno));
        cleanup(&sensor);
        exit(EXIT_FAILURE);
    }

    // Initialize buzzer line
    sensor.buzzer_fd = open("/dev/gpiochip0", O_RDWR);
    if (sensor.buzzer_fd < 0) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        cleanup(&sensor);
        exit(EXIT_FAILURE);
    }

    if (gpio_line_request(sensor.buzzer_fd, &buzzer_req) < 0) {
        fprintf(stderr, "Failed to request buzzer line: %s\n", strerror(errno));
        cleanup(&sensor);
        exit(EXIT_FAILURE);
    }

    sensor.running = 1;
    while (sensor.running) {
        trigger_pulse(sensor.trigger_fd);
        usleep(100000); // 100ms delay between measurements
    }

    cleanup(&sensor);
    return 0;
}

