        .lineoffset = BCM_BUZZER_PIN,
        .flags = GPIO_LINE_FLAG_OUTPUT
    };

    signal(SIGINT, signal_handler);

    // Initialize trigger line
    sensor.trigger_fd = open("/dev/gpiochip0", O_RDWR);
    if (sensor.trigger_fd < 0) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    if (gpio_line_request(sensor.trigger_fd, &echo_req) < 0) {
        fprintf(stderr, "Failed to request echo line: %s\n", strerror(errno));
        cleanup(&sensor);
        exit(EXIT_FAILURE);
    }

    if (gpio_line_request(sensor.trigger_fd, &buzzer_req) < 0) {
        fprintf(stderr, "Failed to request buzzer line: %s\n", strerror(errno));
        cleanup(&sensor);
        exit(EXIT_FAILURE);
    }

    // Initialize echo line
    sensor.echo_fd = open("/dev/gpiochip0", O_RDWR);
    if (sensor.echo_fd < 0) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        cleanup(&sensor);
        exit(EXIT_FAILURE);
    }

    if (gpio_line_request(sensor.echo_fd, &echo_req) < 0) {
        fprintf(stderr, "Failed to request echo line: %s\n", strerror(errno));
        cleanup(&sensor);
        exit(EXIT_FAILURE);
    }

    // Set up edge detection on echo line
    struct gpio_line_event_config event_config = {
        .events = GPIO_LINE_EVENT_RISING_EDGE | GPIO_LINE_EVENT_FALLING_EDGE
    };

    if (ioctl(sensor.echo_fd, GPIO_LINE_SET_EVENT_CONFIG, &event_config) < 0) {
        fprintf(stderr, "Failed to set event config on echo line: %s\n", strerror(errno));
        cleanup(&sensor);
        exit(EXIT_FAILURE);
    }

    if (gpio_line_event_register(sensor.echo_fd, echo_callback, &sensor) < 0) {
        fprintf(stderr, "Failed to register echo event callback: %s\n", strerror(errno));
        cleanup(&sensor);
        exit(EXIT_FAILURE);
    }

    // Initialize buzzer line
    sensor.buzzer_fd = open("/dev/gpiochip0", O_RDWR);
    if (sensor.buzzer_fd < 0) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        cleanup(&sensor);
        exit(EXIT_FAILURE);
    }

    if (gpio_line_request(sensor.buzzer_fd, &buzzer_req) < 0) {
        fprintf(stderr, "Failed to request buzzer line: %s\n", strerror(errno));
        cleanup(&sensor);
        exit(EXIT_FAILURE);
    }

    sensor.running = 1;
    while (sensor.running) {
        trigger_pulse(sensor.trigger_fd);
        usleep(100000); // 100ms delay between measurements
    }

    cleanup(&sensor);
    return 0;
}
