double measure_distance(sensor_data *data) {
    send_trigger_pulse(data);

    struct gpio_line_value value = {
        .lineoffset = GPIO_ECHO,
        .value = 0
    };
    int ret = ioctl(data->echo_fd, GPIO_LINE_GET_VALUE, &value);
    if (ret < 0) {
        perror("Failed to get echo line value");
        return -1.0;
    }

    if (value.value != 1) {
        return -1.0;
    }

    struct timespec start, end;
    clock_gettime(CLOCK_MONOTONIC, &start);

    while (1) {
        ret = ioctl(data->echo_fd, GPIO_LINE_GET_VALUE, &value);
