#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <signal.h>
#include <time.h>

#define I2C_BUS 1
#define I2C_ADDR 0x29
#define MODEL_ID_REGISTER 0x000C
#define TIMING_BUDGET_REGISTER 0x0088
#define TIMING_BUDGET_VALUE 0x00000008
#define DISTANCE_REGISTER 0x0062
#define GPIO_PIN 18
#define PWM_FREQ 50
#define PULSE_WIDTH_FAR 1000
#define PULSE_WIDTH_CLOSE 2000
#define DISTANCE_FAR_THRESHOLD 250
#define DISTANCE_CLOSE_THRESHOLD 200
#define LOG_FILE "gate_log.txt"

typedef struct {
    int i2c_fd;
    struct gpiod_line *pwm_line;
    FILE *log_file;
    int running;
} app_state;

void handle_signal(int sig) {
    app_state *state = (app_state *)malloc(sizeof(app_state));
    if (state) {
        state->running = 0;
        free(state);
    }
}

void init_i2c(app_state *state) {
    char i2c_bus_path[32];
    snprintf(i2c_bus_path, sizeof(i2c_bus_path), "/dev/i2c-%d", I2C_BUS);
    state->i2c_fd = open(i2c_bus_path, O_RDWR);
    if (state->i2c_fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    if (ioctl(state->i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(state->i2c_fd);
        exit(EXIT_FAILURE);
    }
}

void init_pwm(app_state *state) {
    struct gpiod_line_config config;
    memset(&config, 0, sizeof(config));
    config.line = GPIO_PIN;
    config.direction = GPIOD_LINE_DIRECTION_OUTPUT;
    config.output = 1;
    config.consumer = "gate_pwm";

    state->pwm_line = gpiod_line_get(NULL, &config);
    if (!state->pwm_line) {
        perror("Failed to get PWM line");
        exit(EXIT_FAILURE);
    }

    gpiod_line_request_output(state->pwm_line, "gate_pwm", 0);
}

void init_log(app_state *state) {
    state->log_file = fopen(LOG_FILE, "a");
    if (!state->log_file) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }
}

void write_log(app_state *state, const char *message) {
    fprintf(state->log_file, "%s\n", message);
    fflush(state->log_file);
}

void close_i2c(app_state *state) {
    if (state->i2c_fd >= 0) {
        close(state->i2c_fd);
    }
}

void close_pwm(app_state *state) {
    if (state->pwm_line) {
        gpiod_line_release(state->pwm_line);
    }
}

void close_log(app_state *state) {
    if (state->log_file) {
        fclose(state->log_file);
    }
}

void set_pwm_pulse_width(app_state *state, int pulse_width) {
    int duty_cycle = (pulse_width * 1000000) / (1000000 / PWM_FREQ);
    gpiod_line_set_value(state->pwm_line, duty_cycle);
}

void read_distance(app_state *state, int *distance) {
    unsigned char reg[2];
    reg[0] = (DISTANCE_REGISTER >> 8) & 0xFF;
    reg[1] = DISTANCE_REGISTER & 0xFF;

    if (write(state->i2c_fd, reg, 2) < 0) {
        perror("I2C write error");
        return;
    }

    usleep(100);

    if (read(state->i2c_fd, reg, 2) < 0) {
