#include <sys/mman.h>
#include <linux/gpio.h>

#define GPIO_TRIGGER 23
#define GPIO_ECHO 24
#define GPIO_SERVO 18

#define TRIGGER_DURATION_US 10
#define ECHO_TIMEOUT_US 50000
#define MEASUREMENT_INTERVAL_MS 100
#define SERVO_MIN_US 500
#define SERVO_MAX_US 2500
#define MIN_DISTANCE_CM 2
#define MAX_DISTANCE_CM 400
#define MIN_DISTANCE_THRESHOLD_CM 20
#define MAX_DISTANCE_THRESHOLD_CM 200

typedef struct {
    int trigger_fd;
    int echo_fd;
    int servo_fd;
    int gpio_line_trigger;
    int gpio_line_echo;
    int gpio_line_servo;
    int is_running;
} SensorDriver;

void init_driver(SensorDriver *driver) {
    driver->trigger_fd = -1;
    driver->echo_fd = -1;
    driver->servo_fd = -1;
    driver->gpio_line_trigger = -1;
    driver->gpio_line_echo = -1;
    driver->gpio_line_servo = -1;
    driver->is_running = 1;
}

int open_gpio_line(int gpio_num) {
    int fd = open("/dev/gpiochip0", O_RDWR);
    if (fd < 0) {
        perror("Failed to open gpiochip0");
        return -1;
    }

    struct gpiohandle_request req = {
        .flags = GPIOHANDLE_REQUEST_OUTPUT,
        .lineoffset = gpio_num,
        .count = 1
    };

    int handle = ioctl(fd, GPIO_GET_LINEHANDLE_IOCTL, &req);
    if (handle < 0) {
        perror("Failed to get line handle");
        close(fd);
        return -1;
    }

    struct gpiohandle_data data = { .bits = 0 };
    if (ioctl(fd, GPIOHANDLE_SET_LINE_VALUES_IOCTL, &data) < 0) {
        perror("Failed to set line values");
        close(fd);
        return -1;
    }

    close(fd);
    return handle;
}

int set_gpio_value(int handle, int gpio_num, int value) {
    struct gpiohandle_data data = { .bits = 0 };
    data.b[0] = value ? 1 : 0;

    if (ioctl(handle, GPIOHANDLE_SET_LINE_VALUES_IOCTL, &data) < 0) {
        perror("Failed to set line value");
        return -1;
    }

    return 0;
}

int get_gpio_value(int handle, int gpio_num) {
    struct gpiohandle_data data = { .bits = 0 };

    if (ioctl(handle, GPIOHANDLE_GET_LINE_VALUES_IOCTL, &data) < 0) {
        perror("Failed to get line value");
        return -1;
    }

    return (data.b[0] != 0);
}

void close_gpio_line(int handle) {
    close(handle);
}

int measure_distance() {
    int trigger_handle = open_gpio_line(GPIO_TRIGGER);
    if (trigger_handle < 0) {
        return -1;
    }

    if (set_gpio_value(trigger_handle, GPIO_TRIGGER, 1) < 0) {
        close_gpio_line(trigger_handle);
        return -1;
    }

    usleep(TRIGGER_DURATION_US);

    if (set_gpio_value(trigger_handle, GPIO_TRIGGER, 0) < 0) {
        close_gpio_line(trigger_handle);
        return -1;
    }

    close_gpio_line(trigger_handle);

    int echo_handle = open_gpio_line(GPIO_ECHO);
    if (echo_handle < 0) {
        return -1;
    }

    int rising_edge = 0;
    int falling_edge = 0;
    long start_time = 0;
    long end_time = 0;
    long duration = 0;

    while (get_gpio_value(echo_handle, GPIO_ECHO) == 0 && rising_edge == 0) {
        usleep(1);
    }

    if (get_gpio_value(echo_handle, GPIO_ECHO) == 1) {
        rising_edge = 1;
        start_time = gettimeofday_us();
    }

    while (get_gpio_value(echo_handle, GPIO_ECHO) == 1 && falling_edge == 0) {
        usleep(1);
    }

    if (get_gpio_value(echo_handle, GPIO_ECHO) == 0) {
        falling_edge = 1;
        end_time = gettimeofday_us();
    }

    close_gpio_line(echo_handle);

    if (rising_edge && falling_edge) {
        duration = end_time - start_time;
        return (duration * 0.0343) / 2; // Convert microseconds to centimeters
    } else {
        return -1; // Timeout
    }
}

void set_servo_angle(int angle) {
    int servo_handle = open_gpio_line(GPIO_SERVO);
    if (servo_handle < 0) {
        return;
    }

    int pulse_width_us = SERVO_MIN_US + (angle * (SERVO_MAX_US - SERVO_MIN_US) / 180);
    if (pulse_width_us < SERVO_MIN_US) pulse_width_us = SERVO_MIN_US;
    if (pulse_width_us > SERVO_MAX_US) pulse_width_us = SERVO_MAX_US;

    int duration = pulse_width_us / 1000; // Convert microseconds to milliseconds
    int period = 20; // 50 Hz

    int duty_cycle = (pulse_width_us * 1000) / (period * 1000); // Convert to percentage

    if (duty_cycle < 0 || duty_cycle > 100) {
        duty_cycle = 0;
    }

    if (ioctl(servo_handle, GPIOHANDLE_SET_LINE_VALUES_IOCTL, &duty_cycle) < 0) {
        perror("Failed to set servo duty cycle");
    }

    close_gpio_line(servo_handle);
}

void handle_sigint(int sig) {
    set_servo_angle(0);
    printf("\nSIGINT received. Stopping servo and exiting.\n");
    exit(EXIT_SUCCESS);
}

void cleanup(SensorDriver *driver) {
    if (driver->is_running) {
        set_servo_angle(0);
        close_gpio_line(driver->gpio_line_trigger);
        close_gpio_line(driver->gpio_line_echo);
        close_gpio_line(driver->gpio_line_servo);
        driver->is_running = 0;
    }
}

int main() {
    SensorDriver driver;
    init_driver(&driver);

    if (signal(SIGINT, handle_sigint) == SIG_ERR) {
        perror("Failed to set SIGINT handler");
        return EXIT_FAILURE;
    }

    driver.gpio_line_trigger = open_gpio_line(GPIO_TRIGGER);
    if (driver.gpio_line_trigger < 0) {
        fprintf(stderr, "Failed to initialize trigger GPIO\n");
        cleanup(&driver);
        return EXIT_FAILURE;
    }

    driver.gpio_line_echo = open_gpio_line(GPIO_ECHO);
    if (driver.gpio_line_echo < 0) {
        fprintf(stderr, "Failed to initialize echo GPIO\n");
        cleanup(&driver);
        return EXIT_FAILURE;
    }

    driver.gpio_line_servo = open_gpio_line(GPIO_SERVO);
    if (driver.gpio_line_servo < 0) {
        fprintf(stderr, "Failed to initialize servo GPIO\n");
        cleanup(&driver);
        return EXIT_FAILURE;
    }

    while (driver.is_running) {
        int distance = measure_distance();
        double angle = 0.0;

        if (distance >= MIN_DISTANCE_CM && distance <= MAX_DISTANCE_CM) {
            if (distance < MIN_DISTANCE_THRESHOLD_CM) {
                angle = 0.0;
            } else if (distance > MAX_DISTANCE_THRESHOLD_CM) {
                angle = 180.0;
            } else {
                double range = MAX_DISTANCE_THRESHOLD_CM - MIN_DISTANCE_THRESHOLD_CM;
                double dist_range = distance - MIN_DISTANCE_THRESHOLD_CM;
                angle = (dist_range / range) * 180.0;
            }
        } else {
            angle = -1.0;
        }

        printf("Distance: %.2f cm, Angle: %.2f degrees\n", distance, angle);

        if (angle >= 0.0 && angle <= 180.0) {
            set_servo_angle(angle);
        }

        usleep(MEASUREMENT_INTERVAL_MS * 1000);
    }

    cleanup(&driver);
    return EXIT_SUCCESS;
}

