    driver.gpio_line_trigger = open_gpio_line(GPIO_TRIGGER);
    if (driver.gpio_line_trigger < 0) {
        fprintf(stderr, "Failed to initialize trigger GPIO\n");
        cleanup(&driver);
        return EXIT_FAILURE;
    }

    driver.gpio_line_echo = open_gpio_line(GPIO_ECHO);
    if (driver.gpio_line_echo < 0) {
        fprintf(stderr, "Failed to initialize echo GPIO\n");
        cleanup(&driver);
        return EXIT_FAILURE;
    }

    driver.gpio_line_servo = open_gpio_line(GPIO_SERVO);
    if (driver.gpio_line_servo < 0) {
        fprintf(stderr, "Failed to initialize servo GPIO\n");
        cleanup(&driver);
        return EXIT_FAILURE;
    }

    while (driver.is_running) {
        int distance = measure_distance();
        double angle = 0.0;

        if (distance >= MIN_DISTANCE_CM && distance <= MAX_DISTANCE_CM) {
            if (distance < MIN_DISTANCE_THRESHOLD_CM) {
                angle = 0.0;
            } else if (distance > MAX_DISTANCE_THRESHOLD_CM) {
                angle = 180.0;
            } else {
                double range = MAX_DISTANCE_THRESHOLD_CM - MIN_DISTANCE_THRESHOLD_CM;
                double dist_range = distance - MIN_DISTANCE_THRESHOLD_CM;
                angle = (dist_range / range) * 180.0;
            }
        } else {
            angle = -1.0;
        }

        printf("Distance: %.2f cm, Angle: %.2f degrees\n", distance, angle);

        if (angle >= 0.0 && angle <= 180.0) {
            set_servo_angle(angle);
        }

        usleep(MEASUREMENT_INTERVAL_MS * 1000);
    }

    cleanup(&driver);
    return EXIT_SUCCESS;
}
