#include <errno.h>

#define I2C_BUS 1
#define I2C_ADDR 0x40
#define CONFIG_REGISTER 0x01
#define MEASURE_REGISTER 0x00
#define MEASURE_DELAY_MS 10
#define READ_DELAY_MS 10
#define LOG_INTERVAL_MS 2000
#define RECOVERY_DELAY_MS 1000

typedef struct {
    int fd;
    int i2c_bus;
    int i2c_addr;
} I2C_HandleTypeDef;

void i2c_init(I2C_HandleTypeDef *handle) {
    char path[256];
    snprintf(path, sizeof(path), "/dev/i2c-%d", handle->i2c_bus);

    handle->fd = open(path, O_RDWR);
    if (handle->fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    if (ioctl(handle->fd, I2C_TEN, 0) < 0) {
        perror("Failed to set I2C to 10-bit addressing");
        close(handle->fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(handle->fd, I2C_SLAVE, handle->i2c_addr) < 0) {
        perror("Failed to set I2C slave address");
        close(handle->fd);
        exit(EXIT_FAILURE);
    }
}

void i2c_close(I2C_HandleTypeDef *handle) {
    if (handle->fd >= 0) {
        close(handle->fd);
        handle->fd = -1;
    }
}

int i2c_write_register(I2C_HandleTypeDef *handle, uint8_t reg, uint8_t value) {
    uint8_t buffer[2];
    buffer[0] = reg;
    buffer[1] = value;

    if (write(handle->fd, buffer, 2) != 2) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

int i2c_read_register(I2C_HandleTypeDef *handle, uint8_t reg, uint8_t *value) {
    if (ioctl(handle->fd, I2C_SLAVE, handle->i2c_addr) < 0) {
        perror("Failed to set I2C slave address");
        return -1;
    }

    if (write(handle->fd, &reg, 1) != 1) {
        perror("I2C write failed");
        return -1;
    }

    if (read(handle->fd, value, 1) != 1) {
        perror("I2C read failed");
        return -1;
    }

    return 0;
}

void handle_signal(int sig) {
    if (sig == SIGINT) {
        printf("\nReceived SIGINT, shutting down...\n");
        i2c_close(&i2c_handle);
        exit(EXIT_SUCCESS);
    }
}

void recover_i2c(I2C_HandleTypeDef *handle) {
    printf("I2C error detected, attempting recovery...\n");
    i2c_close(handle);
    sleep(1);
    i2c_init(handle);
    printf("I2C recovery successful.\n");
}

int main() {
    I2C_HandleTypeDef i2c_handle = {0};
    i2c_handle.i2c_bus = I2C_BUS;
    i2c_handle.i2c_addr = I2C_ADDR;

    if (i2c_init(&i2c_handle) < 0) {
        fprintf(stderr, "Failed to initialize I2C\n");
        exit(EXIT_FAILURE);
    }

    signal(SIGINT, handle_signal);

    uint8_t config = 0x01; // 0b00000001 - 12-bit humidity measurement
    if (i2c_write_register(&i2c_handle, CONFIG_REGISTER, config) < 0) {
        fprintf(stderr, "Failed to write configuration register\n");
        recover_i2c(&i2c_handle);
    }

    uint8_t humidity;
    uint8_t temperature;
    time_t last_log_time = time(NULL);

    while (1) {
        // Write configuration register
        if (i2c_write_register(&i2c_handle, CONFIG_REGISTER, config) < 0) {
            fprintf(stderr, "Failed to write configuration register\n");
            recover_i2c(&i2c_handle);
            continue;
        }

        usleep(MEASURE_DELAY_MS * 1000);
        // Write measure register
        if (i2c_write_register(&i2c_handle, MEASURE_REGISTER, 0x00) < 0) {
            fprintf(stderr, "Failed to write measure register\n");
            recover_i2c(&i2c_handle);
            continue;
        }

        usleep(READ_DELAY_MS * 1000);

        // Read humidity
        if (i2c_read_register(&i2c_handle, MEASURE_REGISTER, &humidity) < 0) {
            fprintf(stderr, "Failed to read humidity register\n");
            recover_i2c(&i2c_handle);
            continue;
        }

        // Read temperature
        if (i2c_read_register(&i2c_handle, MEASURE_REGISTER, &temperature) < 0) {
            fprintf(stderr, "Failed to read temperature register\n");
            recover_i2c(&i2c_handle);
            continue;
        }

        time_t current_time = time(NULL);
        if (current_time - last_log_time >= LOG_INTERVAL_MS / 1000) {
            last_log_time = current_time;
            printf("Humidity: 0x%02X (%.2f%%), Temperature: 0x%02X (%.2f°C)\n",
                   humidity, (humidity * 125.0) / 65536.0 - 6.0, temperature,
                   (temperature * 175.72) / 65536.0 - 46.85);
        }

        usleep(1000); // Small delay to prevent excessive CPU usage
    }

    i2c_close(&i2c_handle);
    return 0;
}

