#define I2C_BUS 1
#define I2C_ADDR 0x68
#define WHO_AM_I_REGISTER 0x75
#define ACCEL_GYRO_REGISTER 0x3B
#define DATA_SIZE 14
#define POLL_INTERVAL_MS 100

typedef struct {
    int16_t ax;
    int16_t ay;
    int16_t az;
    int16_t temp;
    int16_t gx;
    int16_t gy;
    int16_t gz;
} sensor_data_t;

int i2c_fd = -1;
bool running = true;

void signal_handler(int signal) {
    running = false;
}

void i2c_init() {
    char bus_path[32];
    snprintf(bus_path, sizeof(bus_path), "/dev/i2c-%d", I2C_BUS);

    i2c_fd = open(bus_path, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
}

void i2c_cleanup() {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
}

void read_who_am_i() {
    uint8_t reg = WHO_AM_I_REGISTER;
    uint8_t buffer[1];

    if (write(i2c_fd, &reg, 1) < 0) {
        perror("Failed to write WHO_AM_I register");
        exit(EXIT_FAILURE);
    }

    if (read(i2c_fd, buffer, 1) < 0) {
        perror("Failed to read WHO_AM_I register");
        exit(EXIT_FAILURE);
    }

    if (buffer[0] != 0x68) {
        fprintf(stderr, "MPU-6050 not found or not responding (WHO_AM_I = 0x%02X)\n", buffer[0]);
        exit(EXIT_FAILURE);
    }
}

void read_sensor_data(sensor_data_t *data) {
    uint8_t buffer[DATA_SIZE];

    if (write(i2c_fd, &ACCEL_GYRO_REGISTER, 1) < 0) {
        perror("Failed to write register address");
        exit(EXIT_FAILURE);
    }

    if (read(i2c_fd, buffer, DATA_SIZE) < 0) {
        perror("Failed to read sensor data");
        exit(EXIT_FAILURE);
    }

    data->ax = (int16_t)(buffer[0] << 8 | buffer[1]);
    data->ay = (int16_t)(buffer[2] << 8 | buffer[3]);
    data->az = (int16_t)(buffer[4] << 8 | buffer[5]);
    data->temp = (int16_t)(buffer[6] << 8 | buffer[7]);
    data->gx = (int16_t)(buffer[8] << 8 | buffer[9]);
    data->gy = (int16_t)(buffer[10] << 8 | buffer[11]);
    data->gz = (int16_t)(buffer[12] << 8 | buffer[13]);
}

void print_sensor_data(const sensor_data_t *data) {
    printf("AX: %5d  AY: %5d  AZ: %5d  TEMP: %5d  GX: %5d  GY: %5d  GZ: %5d\n",
           data->ax, data->ay, data->az, data->temp, data->gx, data->gy, data->gz);
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Starting MPU-6050 data logger...\n");

    i2c_init();
    read_who_am_i();

    sensor_data_t data;

    while (running) {
        read_sensor_data(&data);
        print_sensor_data(&data);
        usleep(100000); // 100 ms
    }

    i2c_cleanup();
    printf("MPU-6050 data logger stopped.\n");

    return 0;
}

