#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>
#include <time.h>

#define I2C_BUS 1
#define I2C_ADDR 0x49
#define CMD_TRIGGER_HIGH_REPEATABILTY 0x27
#define CRC_POLY 0x31
#define CRC_INIT 0x00

typedef struct {
    int fd;
    int i2c_bus;
    int i2c_addr;
} i2c_handle;

void handle_signal(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        printf("Shutting down...\n");
        if (close(i2c_handle.fd) < 0) {
            perror("close");
        }
        exit(EXIT_SUCCESS);
    }
}

int i2c_init(int bus, int addr) {
    char filename[20];
    snprintf(filename, sizeof(filename), "/dev/i2c-%d", bus);
    int fd = open(filename, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Failed to set I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

int i2c_write(int fd, const uint8_t *data, size_t len) {
    if (write(fd, data, len) != len) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

int i2c_read(int fd, uint8_t *data, size_t len) {
    if (read(fd, data, len) != len) {
        perror("I2C read failed");
        return -1;
    }
    return 0;
}

uint8_t crc8(const uint8_t *data, size_t len) {
    uint8_t crc = CRC_INIT;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLY;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

void log_readings(float temp, float humidity) {
    time_t now = time(NULL);
    char *time_str = ctime(&now);
    printf("[%s] Temperature: %.2f°C, Humidity: %.2f%%\n", time_str, temp, humidity);
}

int main() {
    i2c_handle i2c;
    i2c.i2c_bus = I2C_BUS;
    i2c.i2c_addr = I2C_ADDR;
    i2c.fd = -1;

    if (signal(SIGINT, handle_signal) == SIG_ERR) {
        perror("signal");
        return EXIT_FAILURE;
    }
    if (signal(SIGTERM, handle_signal) == SIG_ERR) {
        perror("signal");
        return EXIT_FAILURE;
    }

    while (1) {
        if (i2c.fd < 0) {
            i2c.fd = i2c_init(i2c.i2c_bus, i2c.i2c_addr);
            if (i2c.fd < 0) {
                fprintf(stderr, "Failed to initialize I2C bus, retrying...\n");
                sleep(1);
                continue;
            }
        }

        uint8_t cmd[1] = {CMD_TRIGGER_HIGH_REPEATABILTY};
        if (i2c_write(i2c.fd, cmd, sizeof(cmd)) < 0) {
            fprintf(stderr, "I2C write error, reopening bus...\n");
            close(i2c.fd);
            i2c.fd = -1;
            continue;
        }

        usleep(10000); // Wait at least 10 ms

        uint8_t response[6];
        if (i2c_read(i2c.fd, response, sizeof(response)) < 0) {
            fprintf(stderr, "I2C read error, reopening bus...\n");
            close(i2c.fd);
            i2c.fd = -1;
            continue;
        }

        uint8_t crc_temp = crc8(response, 2);
        uint8_t crc_hum = crc8(response + 3, 2);

        if (response[2] != crc_temp || response[5] != crc_hum) {
