        i2c_fd = -1;
    }
    exit(EXIT_SUCCESS);
}

int i2c_init() {
    int retries = 0;
    while (retries < MAX_RETRIES) {
        i2c_fd = open(I2C_BUS, O_RDWR);
        if (i2c_fd < 0) {
