    int ret;

    if (i2c_fd < 0) {
        return -1;
    }

    buf[0] = reg;
    ret = write(i2c_fd, buf, 1);
    if (ret != 1) {
        return -1;
    }

    ret = read(i2c_fd, buf, 2);
    if (ret != 2) {
        return -1;
    }

    *temp = (buf[0] << 8 | buf[1]) * 0.02;
    return 0;
}

void log_temperature(double ambient, double object) {
    time_t now;
    struct tm *timeinfo;
    char timestamp[20];

    time(&now);
    timeinfo = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file) {
        fprintf(log_file, "%s,%f,%f\n", timestamp, ambient, object);
        fflush(log_file);
    } else {
        fprintf(stderr, "Log file not open, cannot log temperature.\n");
    }
}

int main() {
    if (signal(SIGINT, handle_signal) == SIG_ERR) {
        perror("Failed to set SIGINT handler");
        return EXIT_FAILURE;
    }

    if (i2c_init() < 0) {
        fprintf(stderr, "I2C initialization failed.\n");
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    fprintf(log_file, "Timestamp,Ambient Temperature,Object Temperature\n");
    fflush(log_file);

    while (running) {
        double ambient = 0.0;
        double object = 0.0;
        int retries = 0;

        while (retries < MAX_RETRIES) {
            if (read_temperature(MLX90614_AMBIENT_REGISTER, &ambient) == 0 &&
                read_temperature(MLX90614_OBJECT_REGISTER, &object) == 0) {
                log_temperature(ambient, object);
                break;
            } else {
                fprintf(stderr, "Failed to read temperature, retrying...\n");
                sleep(1);
                retries++;
            }
        }

        if (retries >= MAX_RETRIES) {
            fprintf(stderr, "Failed to read temperature after multiple retries.\n");
        }

        sleep(INTERVAL);
    }

    if (log_file) {
        fclose(log_file);
    }

    if (i2c_fd >= 0) {
        close(i2c_fd);
    }

    return EXIT_SUCCESS;
}

