        fprintf(error_file, "%s%s\n", timestamp, message);
        fclose(error_file);
    }
}

void log_temperature(double temperature) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file) {
        time_t now = time(NULL);
        char *timestamp = ctime(&now);
        fprintf(log_file, "%s%.2f\n", timestamp, temperature);
        fclose(log_file);
    }
