        log_error("Failed to open I2C bus", errno);
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, address) < 0) {
        log_error("Failed to set I2C slave address", errno);
        close(fd);
        return -1;
    }

    return fd;
}

int i2c_read(int fd, uint8_t *buffer, size_t len) {
    if (read(fd, buffer, len) != len) {
        log_error("I2C read failed", errno);
        return -1;
    }
    return 0;
}

double read_temperature(int fd) {
    uint8_t cmd[2] = {0x24, 0x00}; // Start measurement command
    if (i2c_write(fd, cmd, 2) < 0) {
        return -1.0;
    }

    usleep(20000); // Wait for measurement to complete

    uint8_t result[2];
    if (i2c_read(fd, result, 2) < 0) {
        return -1.0;
    }

    uint16_t raw = (result[0] << 8) | result[1];
    double temp = (double)raw * 0.01;
    return temp;
}

void signal_handler(int signal) {
    printf("Received signal %d, exiting...\n", signal);
    exit(EXIT_SUCCESS);
}

void cleanup(i2c_context *ctx) {
    if (ctx->fd >= 0) {
        close(ctx->fd);
    }
}

