#define CMD_GET_CALIBRATION_DATA_170 0xEC
#define CMD_GET_CALIBRATION_DATA_171 0xED
#define CMD_GET_CALIBRATION_DATA_172 0xEE
#define CMD_GET_CALIBRATION_DATA_173 0xEF
#define CMD_GET_CALIBRATION_DATA_174 0xF0
#define CMD_GET_CALIBRATION_DATA_175 0xF1
#define CMD_GET_CALIBRATION_DATA_176 0xF2
#define CMD_GET_CALIBRATION_DATA_177 0xF3
#define CMD_GET_CALIBRATION_DATA_178 0xF4
#define CMD_GET_CALIBRATION_DATA_179 0xF5
#define CMD_GET_CALIBRATION_DATA_180 0xF6
#define CMD_GET_CALIBRATION_DATA_181 0xF7
#define CMD_GET_CALIBRATION_DATA_182 0xF8
#define CMD_GET_CALIBRATION_DATA_183 0xF9
#define CMD_GET_CALIBRATION_DATA_184 0xFA
#define CMD_GET_CALIBRATION_DATA_185 0xFB
#define CMD_GET_CALIBRATION_DATA_186 0xFC
#define CMD_GET_CALIBRATION_DATA_187 0xFD
#define CMD_GET_CALIBRATION_DATA_188 0xFE
#define CMD_GET_CALIBRATION_DATA_189 0xFF

#define CRC8_POLY 0x07
#define CRC8_INIT 0x00

typedef struct {
    int16_t pressure;
    int16_t temperature;
    int16_t pressure_scale;
    int16_t temperature_scale;
} measurement_t;

int i2c_fd = -1;
FILE *log_file = NULL;
int running = 1;

void signal_handler(int sig) {
    running = 0;
}

void close_resources() {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (log_file) {
        fclose(log_file);
    }
}

void write_log(const char *timestamp, double pressure, double temperature) {
    if (!log_file) {
        return;
    }
    fprintf(log_file, "%s,%f,%f\n", timestamp, pressure, temperature);
    fflush(log_file);
}

void i2c_init() {
    char i2c_bus_path[32];
    snprintf(i2c_bus_path, sizeof(i2c_bus_path), "/dev/i2c-%d", I2C_BUS);

    i2c_fd = open(i2c_bus_path, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
}

void send_command(uint8_t cmd) {
    uint8_t buffer[1];
    buffer[0] = cmd;

    if (write(i2c_fd, buffer, 1) != 1) {
        perror("Failed to send command");
        close_resources();
        exit(EXIT_FAILURE);
    }
}

void reset_sensor() {
    send_command(CMD_RESET);
    usleep(100000); // 100ms delay
}

void configure_sensor() {
    send_command(CMD_START_CONTINUOUS_MEASUREMENT);
    usleep(100000); // 100ms delay
}

int read_measurement(uint8_t *buffer, size_t size) {
    if (read(i2c_fd, buffer, size) != size) {
        perror("Failed to read measurement");
        return -1;
    }
    return 0;
}

int validate_crc8(const uint8_t *data, size_t len, uint8_t expected_crc) {
    uint8_t crc = CRC8_INIT;
    for (size_t i = 0; i < len; i++) {
        crc = crc8_update(crc, data[i]);
    }
    return (crc == expected_crc);
}

void process_measurement(measurement_t *meas, const uint8_t *data) {
    // Differential pressure (2 bytes + CRC-8)
    uint16_t pressure_raw = (data[0] << 8) | data[1];
    uint8_t pressure_crc = data[2];
    if (!validate_crc8(data, 3, pressure_crc)) {
        fprintf(stderr, "Invalid pressure CRC\n");
        return;
    }
    meas->pressure = (int16_t)pressure_raw;

    // Temperature (2 bytes + CRC-8)
    uint16_t temperature_raw = (data[3] << 8) | data[4];
    uint8_t temperature_crc = data[5];
    if (!validate_crc8(data + 3, 3, temperature_crc)) {
        fprintf(stderr, "Invalid temperature CRC\n");
        return;
    }
    meas->temperature = (int16_t)temperature_raw;

    // Pressure scale factor (2 bytes + CRC-8)
    uint16_t pressure_scale_raw = (data[6] << 8) | data[7];
    uint8_t pressure_scale_crc = data[8];
    if (!validate_crc8(data + 6, 3, pressure_scale_crc)) {
        fprintf(stderr, "Invalid pressure scale CRC\n");
        return;
    }
    meas->pressure_scale = (int16_t)pressure_scale_raw;

    // Temperature scale factor (2 bytes + CRC-8)
    uint16_t temperature_scale_raw = (data[9] << 8) | data[10];
    uint8_t temperature_scale_crc = data[11];
    if (!validate_crc8(data + 9, 3, temperature_scale_crc)) {
        fprintf(stderr, "Invalid temperature scale CRC\n");
        return;
    }
    meas->temperature_scale = (int16_t)temperature_scale_raw;
}

void log_data(measurement_t *meas) {
    char timestamp[30];
    time_t now = time(NULL);
    struct tm *tm = gmtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm);

    double pressure_pa = (double)meas->pressure / (double)meas->pressure_scale;
    double temperature_c = (double)meas->temperature / (double)meas->temperature_scale;

    write_log(timestamp, pressure_pa, temperature_c);
}

void open_log_file() {
    log_file = fopen("pressure_log.csv", "a");
    if (!log_file) {
        perror("Failed to open log file");
        close_resources();
        exit(EXIT_FAILURE);
    }

    // Check if file is new and write header
    if (fseek(log_file, 0, SEEK_SET) == 0 && ftell(log_file) == 0) {
        fprintf(log_file, "timestamp,pressure_pa,temperature_c\n");
        fflush(log_file);
    }
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    i2c_init();
    reset_sensor();
    configure_sensor();
    open_log_file();

    while (running) {
        send_command(CMD_MEASURE);
        usleep(1000); // Wait at least 1ms

        uint8_t buffer[12];
        if (read_measurement(buffer, sizeof(buffer)) < 0) {
            continue;
        }

        measurement_t meas;
        process_measurement(&meas, buffer);
        if (meas.pressure_scale != 0 && meas.temperature_scale != 0) {
            log_data(&meas);
        }

        usleep(1000000); // 1 second interval
    }

    close_resources();
    return 0;
}
