#define LOG_FILE "sensor_data.txt"

typedef struct {
    int i2c_fd;
    FILE *log_file;
    int running;
} sensor_state_t;

void handle_signal(int sig) {
    if (sig == SIGINT) {
        printf("Caught SIGINT, cleaning up...\n");
        sensor_state_t *state = (sensor_state_t *)malloc(sizeof(sensor_state_t));
        state->running = 0;
        free(state);
        exit(EXIT_SUCCESS);
    }
}

int open_i2c_bus(int bus) {
    char filename[20];
    snprintf(filename, sizeof(filename), "/dev/i2c-%d", bus);
    int fd = open(filename, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

int i2c_write(int fd, uint8_t reg) {
    uint8_t buffer[1];
    buffer[0] = reg;
    if (write(fd, buffer, 1) != 1) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

int i2c_read(int fd, uint8_t *data, int len) {
    if (read(fd, data, len) != len) {
        perror("I2C read failed");
        return -1;
    }
    return 0;
}

int read_sensor(int fd, uint8_t cmd, uint16_t *value) {
    int retries = 0;
    while (retries < MAX_RETRIES) {
        if (i2c_write(fd, cmd) < 0) {
            fprintf(stderr, "I2C write failed, retrying...\n");
            usleep(100000); // 100ms delay
            retries++;
            continue;
        }

        uint8_t buffer[2];
        if (i2c_read(fd, buffer, 2) < 0) {
            fprintf(stderr, "I2C read failed, retrying...\n");
            usleep(100000);
            retries++;
            continue;
        }

        *value = (buffer[0] << 8) | buffer[1];
        return 0;
    }

    fprintf(stderr, "Failed to read sensor after %d retries\n", MAX_RETRIES);
    return -1;
}

void log_data(FILE *log_file, time_t timestamp, double temp, double humid) {
    char time_str[64];
    struct tm *tm_info = localtime(&timestamp);
    strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(log_file, "%s, %.2f, %.2f\n", time_str, temp, humid);
    fflush(log_file);
}

void print_data(time_t timestamp, double temp, double humid) {
    char time_str[64];
    struct tm *tm_info = localtime(&timestamp);
    strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm_info);

    printf("%s, Temp: %.2f°C, Humid: %.2f%%\n", time_str, temp, humid);
}

int main() {
    signal(SIGINT, handle_signal);

    sensor_state_t state;
    state.running = 1;

    int i2c_fd = open_i2c_bus(I2C_BUS);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus, exiting.\n");
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    while (state.running) {
        time_t now = time(NULL);
        double temp = 0.0, humid = 0.0;

        // Measure temperature
        if (read_sensor(i2c_fd, CMD_MEASURE_TEMP | CMD_NO_HOLD_MASTER, &temp) < 0) {
            fprintf(stderr, "Failed to read temperature, exiting.\n");
            break;
        }

        // Measure humidity
        if (read_sensor(i2c_fd, CMD_MEASURE_HUMID | CMD_NO_HOLD_MASTER, &humid) < 0) {
            fprintf(stderr, "Failed to read humidity, exiting.\n");
            break;
        }

        // Convert to actual values
        temp = (temp * 175.0 / 65535.0) - 46.85;
        humid = (humid * 125.0 / 65535.0) - 6.0;

        log_data(log_file, now, temp, humid);
        print_data(now, temp, humid);

        // Sleep for 5 seconds
        sleep(SAMPLE_INTERVAL);
    }

    // Cleanup
    fclose(log_file);
    close(i2c_fd);
    printf("Sensor program terminated.\n");

    return EXIT_SUCCESS;
}
