#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define SHT40_ADDR 0x40
#define MEASUREMENT_COMMAND 0x27
#define CRC_POLY 0x31
#define CRC_INIT 0xFF
#define LOG_FILE "sht40_log.txt"
#define LOG_INTERVAL 5000000  // 5 seconds in microseconds

typedef struct {
    uint8_t t_msb;
    uint8_t t_lsb;
    uint8_t t_crc;
    uint8_t rh_msb;
    uint8_t rh_lsb;
    uint8_t rh_crc;
} sht40_response_t;

// CRC-8 calculation using Sensirion polynomial
uint8_t calculate_crc(const uint8_t *data, size_t len) {
    uint8_t crc = CRC_INIT;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x01) {
                crc = (crc >> 1) ^ CRC_POLY;
            } else {
                crc >>= 1;
            }
        }
    }
    return crc;
}

// Validate CRC for temperature and humidity
int validate_crc(const sht40_response_t *response) {
    uint8_t t_crc = calculate_crc(&response->t_msb, 2);
    uint8_t rh_crc = calculate_crc(&response->rh_msb, 2);
    return (response->t_crc == t_crc && response->rh_crc == rh_crc);
}

// Convert temperature from 16-bit data to degrees Celsius
float convert_temperature(const sht40_response_t *response) {
    int16_t t = (response->t_msb << 8) | response->t_lsb;
    return (float)t / 1000.0;
}

// Convert humidity from 16-bit data to %RH
float convert_humidity(const sht40_response_t *response) {
    int16_t rh = (response->rh_msb << 8) | response->rh_lsb;
    return (float)rh / 1000.0;
}

// Log a timestamped reading to the log file
void log_reading(FILE *log_file, float temperature, float humidity) {
    time_t now = time(NULL);
    struct tm *tm_now = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_now);
    fprintf(log_file, "%s, %.3f, %.3f\n", timestamp, temperature, humidity);
    fflush(log_file);
}

// Signal handler to clean up resources
void handle_signal(int sig) {
    if (sig == SIGINT) {
        printf("Caught SIGINT, cleaning up...\n");
        if (log_file) {
            fclose(log_file);
        }
        if (i2c_fd >= 0) {
            close(i2c_fd);
        }
        exit(EXIT_SUCCESS);
    }
}

int main() {
    int i2c_fd = -1;
    FILE *log_file = NULL;
    struct i2c_msg msgs[2];
    struct i2c_ioctl_data ioctl_data;
    uint8_t write_buf[2];
    uint8_t read_buf[6];
    sht40_response_t response;
    int ret;
    struct timespec sleep_time = {LOG_INTERVAL / 1000000, 0};

    // Initialize signal handling
    signal(SIGINT, handle_signal);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, SHT40_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Main loop
    while (1) {
        // Issue measurement command
        write_buf[0] = MEASUREMENT_COMMAND;
        write_buf[1] = 0x00;  // No heater enable

        msgs[0].addr = SHT40_ADDR;
        msgs[0].flags = 0;
        msgs[0].len = 2;
        msgs[0].buf = write_buf;

        ioctl_data.msgs = msgs;
        ioctl_data.nmsgs = 1;

        if (ioctl(i2c_fd, I2C_RDWR, &ioctl_data) < 0) {
            perror("I2C write failed");
            continue;
        }

        // Wait for measurement to complete (minimum 8.5ms)
        nanosleep(&sleep_time, NULL);

        // Read response
        msgs[0].addr = SHT40_ADDR;
        msgs[0].flags = I2C_M_RD;
        msgs[0].len = 6;
        msgs[0].buf = read_buf;

        ioctl_data.msgs = msgs;
        ioctl_data.nmsgs = 1;

        if (ioctl(i2c_fd, I2C_RDWR, &ioctl_data) < 0) {
            perror("I2C read failed");
            continue;
        }

        // Parse response
        response.t_msb = read_buf[0];
        response.t_lsb = read_buf[1];
        response.t_crc = read_buf[2];
        response.rh_msb = read_buf[3];
        response.rh_lsb = read_buf[4];
        response.rh_crc = read_buf[5];

        // Validate CRC
        if (!validate_crc(&response)) {
            fprintf(stderr, "CRC validation failed\n");
            continue;
        }

        // Convert and log data
        float temperature = convert_temperature(&response);
        float humidity = convert_humidity(&response);
        log_reading(log_file, temperature, humidity);
    }

    // Clean up (should not reach here normally)
    handle_signal(SIGINT);
    return EXIT_SUCCESS;
}

