    struct i2c_msg msgs[2];
    struct i2c_ioctl_data ioctl_data;
    uint8_t write_buf[2];
    uint8_t read_buf[6];
    sht40_response_t response;
    int ret;
    struct timespec sleep_time = {LOG_INTERVAL / 1000000, 0};

    // Initialize signal handling
    signal(SIGINT, handle_signal);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, SHT40_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Main loop
    while (1) {
        // Issue measurement command
        write_buf[0] = MEASUREMENT_COMMAND;
        write_buf[1] = 0x00;  // No heater enable

        msgs[0].addr = SHT40_ADDR;
        msgs[0].flags = 0;
        msgs[0].len = 2;
        msgs[0].buf = write_buf;

        ioctl_data.msgs = msgs;
        ioctl_data.nmsgs = 1;

        if (ioctl(i2c_fd, I2C_RDWR, &ioctl_data) < 0) {
            perror("I2C write failed");
            continue;
        }

        // Wait for measurement to complete (minimum 8.5ms)
        nanosleep(&sleep_time, NULL);

        // Read response
        msgs[0].addr = SHT40_ADDR;
        msgs[0].flags = I2C_M_RD;
        msgs[0].len = 6;
        msgs[0].buf = read_buf;

        ioctl_data.msgs = msgs;
        ioctl_data.nmsgs = 1;

        if (ioctl(i2c_fd, I2C_RDWR, &ioctl_data) < 0) {
            perror("I2C read failed");
            continue;
        }

        // Parse response
        response.t_msb = read_buf[0];
        response.t_lsb = read_buf[1];
        response.t_crc = read_buf[2];
        response.rh_msb = read_buf[3];
        response.rh_lsb = read_buf[4];
        response.rh_crc = read_buf[5];

        // Validate CRC
        if (!validate_crc(&response)) {
            fprintf(stderr, "CRC validation failed\n");
            continue;
        }

        // Convert and log data
        float temperature = convert_temperature(&response);
        float humidity = convert_humidity(&response);
        log_reading(log_file, temperature, humidity);
    }

    // Clean up (should not reach here normally)
    handle_signal(SIGINT);
    return EXIT_SUCCESS;
