#define CMD_GET_CALIBRATION 0x3023
#define CMD_GET_STATUS 0x3024
#define CMD_GET_TEMPERATURE 0x2410
#define CMD_GET_PRESSURE 0x2411
#define CMD_GET_PRESSURE_AND_TEMPERATURE 0x2412

#define CRC8_POLY 0x07
#define CRC8_INIT 0x00

typedef struct {
    uint16_t pressure_msb;
    uint16_t pressure_lsb;
    uint8_t pressure_crc;
    uint16_t temperature_msb;
    uint16_t temperature_lsb;
    uint8_t temperature_crc;
