// CRC8 calculation
uint8_t calculate_crc8(const uint8_t *data, size_t len) {
    uint8_t crc = CRC8_INIT;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLY;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Validate CRC8
int validate_crc8(const uint8_t *data, size_t len, uint8_t expected_crc) {
    uint8_t calculated_crc = calculate_crc8(data, len);
    return calculated_crc == expected_crc;
}

// I2C write function
int i2c_write(int fd, uint8_t reg, const uint8_t *data, size_t len) {
    uint8_t buffer[len + 1];
    buffer[0] = reg;
    memcpy(buffer + 1, data, len);
    if (ioctl(fd, I2C_RDWR, &buffer) < 0) {
        perror("I2C write error");
        return -1;
    }
    return 0;
}

// I2C read function
int i2c_read(int fd, uint8_t reg, uint8_t *data, size_t len) {
    uint8_t buffer[1];
    buffer[0] = reg;
    if (ioctl(fd, I2C_RDWR, &buffer) < 0) {
        perror("I2C write error");
        return -1;
    }

    if (ioctl(fd, I2C_RDWR, data) < 0) {
        perror("I2C read error");
        return -1;
    }
    return 0;
}

