double convert_pressure(uint16_t pressure_msb, uint16_t pressure_lsb) {
    uint32_t pressure = (uint32_t)pressure_msb << 16 | pressure_lsb;
    return (double)pressure * 0.001; // 1 LSB = 0.001 Pa
}

