double convert_temperature(uint16_t temperature_msb, uint16_t temperature_lsb) {
    int32_t temp = (int32_t)temperature_msb << 16 | temperature_lsb;
    return (double)temp * 0.001; // 1 LSB = 0.001 °C
}

