    if (!file) {
        perror("Failed to open log file");
        close(i2c_fd);
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize sensor
    uint8_t init_cmd[2] = {CMD_CONTINUOUS_MEASUREMENT >> 8, CMD_CONTINUOUS_MEASUREMENT & 0xFF};
    if (i2c_write(i2c_fd, 0x00, init_cmd, 2) < 0) {
        fprintf(stderr, "Failed to initialize sensor\n");
        cleanup(i2c_fd, file);
        return 1;
    }

    // Main loop
    while (running) {
        // Wait 1 ms
        nanosleep(&ts, NULL);

        // Read data
        uint8_t data[6];
        if (i2c_read(i2c_fd, 0x00, data, 6) < 0) {
            fprintf(stderr, "I2C read error, skipping sample\n");
            continue;
        }

        // Validate CRCs
        if (!validate_crc8(data, 3, data[5]) || !validate_crc8(data + 3, 3, data[6])) {
            fprintf(stderr, "CRC check failed, skipping sample\n");
            continue;
        }

        // Convert data
        sensor_data_t sensor_data;
        sensor_data.pressure_msb = (uint16_t)(data[0] << 8 | data[1]);
        sensor_data.pressure_lsb = (uint16_t)(data[2] << 8 | data[3]);
        sensor_data.temperature_msb = (uint16_t)(data[4] << 8 | data[5]);

