        // Get timestamp
        struct timespec ts;
        clock_gettime(CLOCK_MONOTONIC, &ts);
        long long timestamp = ts.tv_sec * 1000 + ts.tv_nsec / 1000000;

        // Write to file
        fprintf(file, "%lld,%.6f,%.6f\n", timestamp, pressure_pa, temperature_c);
        fflush(file);
    }

