#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS 1
#define I2C_ADDR 0x40
#define FAN_PIN 18
#define BUFFER_SIZE 60
#define MAX_RETRIES 3
#define TEMP_THRESHOLD_ON 28.0
#define TEMP_THRESHOLD_OFF 27.0
#define FAN_DELAY_MS 10

typedef struct {
    double temperature;
    time_t timestamp;
} SensorReading;

typedef struct {
    SensorReading buffer[BUFFER_SIZE];
    int head;
    int tail;
    int full;
} CircularBuffer;

void init_circular_buffer(CircularBuffer *cb) {
    cb->head = 0;
    cb->tail = 0;
    cb->full = 0;
}

void add_to_buffer(CircularBuffer *cb, double temp) {
    if (cb->full) {
        cb->tail = (cb->tail + 1) % BUFFER_SIZE;
    }
    cb->buffer[cb->head].temperature = temp;
    cb->buffer[cb->head].timestamp = time(NULL);
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    cb->full = (cb->head == cb->tail);
}

void print_buffer(CircularBuffer *cb) {
    int i;
    for (i = 0; i < BUFFER_SIZE; i++) {
        int index = (cb->tail + i) % BUFFER_SIZE;
        printf("[%ld] %.2f°C\n", (long)cb->buffer[index].timestamp, cb->buffer[index].temperature);
    }
}

double read_temperature(int fd) {
    unsigned char cmd[2] = {0xF3, 0x00}; // Start measurement command
    unsigned char data[2] = {0, 0};

    int retries = 0;
    int result;

    while (retries < MAX_RETRIES) {
        result = write(fd, cmd, 2);
        if (result != 2) {
            fprintf(stderr, "I2C write failed: %d\n", result);
            retries++;
            usleep(100000); // 100ms delay
            continue;
        }

        usleep(100000); // Wait for measurement to complete

        result = read(fd, data, 2);
        if (result != 2) {
            fprintf(stderr, "I2C read failed: %d\n", result);
            retries++;
            usleep(100000);
            continue;
        }

        // Convert to temperature in Celsius
        int raw = (data[0] << 8) | data[1];
        double temp = (raw * 175.0) / 65536.0 - 46.85;
        return temp;
    }

    fprintf(stderr, "Failed to read temperature after %d retries\n", MAX_RETRIES);
    return -1.0;
}

void handle_sigint(int sig) {
    printf("\nCaught SIGINT, shutting down...\n");

    // Turn off fan
    gpio_line_set(fan_line, 0);

    // Close I2C device
    close(i2c_fd);

    // Call library's call() function (assuming it's a function to clean up)
    // For example, if using libgpiod, this might be unnecessary
    // If using pigpio, call pigpio_stop()

    exit(EXIT_SUCCESS);
}

int main() {
    int i2c_fd;
    struct i2c_msg msgs[1];
    struct i2c_ioctl_data ioctl_data;
    struct gpiod_line *fan_line;
    CircularBuffer buffer;
    init_circular_buffer(&buffer);
    double last_temp = -1.0;
    int fan_state = 0;

    // Open I2C bus
    char i2c_bus_path[32];
    snprintf(i2c_bus_path, sizeof(i2c_bus_path), "/dev/i2c-%d", I2C_BUS);
    i2c_fd = open(i2c_bus_path, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    // Set I2C address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Initialize GPIO for fan
    struct gpiod_chip *chip;
    chip = gpiod_chip_open("/dev/gpiochip4");
    if (!chip) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    fan_line = gpiod_line_get(chip, FAN_PIN);
    if (!fan_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    gpiod_line_request_output(fan_line, "fan", 0); // Initial state: off

    // Set up signal handler
    signal(SIGINT, handle_sigint);

    while (1) {
        double temp = read_temperature(i2c_fd);
        if (temp < 0) {
            fprintf(stderr, "Sensor not detected, degrading gracefully.\n");
            break;
        }

        // Print to stdout
        printf("[%ld] %.2f°C\n", (long)time(NULL), temp);

        // Add to buffer
        add_to_buffer(&buffer, temp);

        // Print buffer
        print_buffer(&buffer);

        // Fan control logic
        if (temp > TEMP_THRESHOLD_ON && !fan_state) {
            gpio_line_set(fan_line, 1);
            fan_state = 1;
        } else if (temp < TEMP_THRESHOLD_OFF && fan_state) {
            gpio_line_set(fan_line, 0);
            fan_state = 0;
        }

        // Wait 2 seconds
        usleep(2000000);

        // If fan is on, wait 10ms before next read
        if (fan_state) {
            usleep(10000);
        }
    }

    // Clean up
    gpiod_line_release(fan_line);
    gpiod_chip_close(chip);
    close(i2c_fd);

    return EXIT_SUCCESS;
}

