#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define GPIO_PIN 4
#define BCM_PIN GPIO_PIN
#define SAMPLE_INTERVAL 5000000  // 5 seconds in microseconds
#define EDGE_TIMEOUT 50000       // 50 ms in microseconds
#define VALID_MIN_TEMP -40.0
#define VALID_MAX_TEMP 150.0
#define CONSECUTIVE_FAILURES 3

typedef struct {
    FILE *log_file;
    int consecutive_errors;
    gpiod_line *line;
    int initialized;
} AppContext;

void handle_signal(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        if (context.log_file) {
            fclose(context.log_file);
            context.log_file = NULL;
        }
        if (context.line) {
            gpiod_line_release(context.line);
            context.line = NULL;
        }
        context.initialized = 0;
        exit(EXIT_SUCCESS);
    }
}

void log_error(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
}

void log_temperature(double temp) {
    char timestamp[30];
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);
    fprintf(context.log_file, "%s %.2f\n", timestamp, temp);
}

void log_malfunction() {
    char timestamp[30];
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);
    fprintf(context.log_file, "%s SENSOR MALFUNCTION\n", timestamp);
    fflush(context.log_file);
}

int init_gpio() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int ret;

    chip = gpiod_chip_open("/dev/gpiochip4");
    if (!chip) {
        log_error("Failed to open GPIO chip");
        return -1;
    }

    line = gpiod_chip_get_line(chip, BCM_PIN);
    if (!line) {
        log_error("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    ret = gpiod_line_request_output(line, "tmp05", 0);
    if (ret < 0) {
        log_error("Failed to request GPIO line for output");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return -1;
    }

    ret = gpiod_line_set_value(line, 1);
    if (ret < 0) {
        log_error("Failed to set GPIO line high");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return -1;
    }

    context.line = line;
    context.initialized = 1;
    return 0;
}

double read_temperature() {
    struct timespec start, end;
    long high_time, low_time;
    int ret;

    // Wait for falling edge
    ret = gpiod_line_wait_for_edge(context.line, GPIOD_LINE_EVENT_FALLING, EDGE_TIMEOUT);
    if (ret < 0) {
        log_error("Timeout waiting for falling edge");
        return -1;
    }

    clock_gettime(CLOCK_MONOTONIC, &start);

    // Wait for rising edge
    ret = gpiod_line_wait_for_edge(context.line, GPIOD_LINE_EVENT_RISING, EDGE_TIMEOUT);
    if (ret < 0) {
        log_error("Timeout waiting for rising edge");
        return -1;
    }

    clock_gettime(CLOCK_MONOTONIC, &end);

    high_time = (end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000;
    low_time = 0;

    // Wait for falling edge again to get full cycle
    ret = gpiod_line_wait_for_edge(context.line, GPIOD_LINE_EVENT_FALLING, EDGE_TIMEOUT);
    if (ret < 0) {
        log_error("Timeout waiting for falling edge");
        return -1;
    }

    clock_gettime(CLOCK_MONOTONIC, &end);

    low_time = (end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000;

    if (low_time == 0) {
        log_error("Low time is zero, cannot compute temperature");
        return -1;
    }

    double cycle_time = (double)(high_time + low_time) / 1000000.0;
    double temp = (cycle_time - 0.000001) * 1000000.0 / 1000000.0;

    if (temp < VALID_MIN_TEMP || temp > VALID_MAX_TEMP) {
        log_error("Temperature out of valid range");
        return -1;
    }

    return temp;
}

int main() {
    struct sigaction sa;
    FILE *log_file;
    double temp;
    int i;

    context.log_file = NULL;
    context.line = NULL;
    context.initialized = 0;
    context.consecutive_errors = 0;

    // Set up signal handlers
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        log_error("Failed to set up signal handlers");
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen("temperature_log.txt", "a");
    if (!log_file) {
        log_error("Failed to open log file");
        return EXIT_FAILURE;
    }

    context.log_file = log_file;

    // Initialize GPIO
    if (init_gpio() < 0) {
        log_error("Failed to initialize GPIO");
        fclose(context.log_file);
        return EXIT_FAILURE;
    }

    // Main loop
    while (1) {
        temp = read_temperature();
        if (temp < 0) {
            context.consecutive_errors++;
            if (context.consecutive_errors >= CONSECUTIVE_FAILURES) {
                log_malfunction();
                context.consecutive_errors = 0;
            }
        } else {
            log_temperature(temp);
            context.consecutive_errors = 0;
        }

        usleep(SAMPLE_INTERVAL);
    }

    // Clean up
    if (context.log_file) {
        fclose(context.log_file);
    }
    if (context.line) {
        gpiod_line_release(context.line);
    }

    return EXIT_SUCCESS;
}

