void crc8(const unsigned char *data, size_t len, unsigned char *crc) {
    *crc = CRC8_INIT;
    for (size_t i = 0; i < len; i++) {
        *crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (*crc & 0x80) {
                *crc = (*crc << 1) ^ CRC8_POLY;
            } else {
                *crc <<= 1;
            }
        }
    }
}

int i2c_write(int fd, unsigned char *buf, size_t len) {
    if (write(fd, buf, len) != len) {
        perror("i2c write failed");
        return -1;
    }
    return 0;
}

int i2c_read(int fd, unsigned char *buf, size_t len) {
    if (read(fd, buf, len) != len) {
        perror("i2c read failed");
        return -1;
    }
    return 0;
}

