#define CMD_MEASURE_HIGH_REPEATABILTY 0x2C82
#define CMD_STOP_MEASUREMENT 0x3041
#define CMD_RESET 0x3000
#define CMD_SOFT_RESET 0x3001
#define CMD_READ_SERIAL 0x3061
#define CMD_WRITE_USER_REGISTER 0x3043
#define CMD_READ_USER_REGISTER 0x3042
#define CMD_GET_FIRMWARE_VERSION 0x3044

#define MEASUREMENT_DELAY_MS 15
#define SAMPLE_INTERVAL_S 5
#define CRC8_POLY 0x31
#define CRC8_INIT 0x00

typedef struct {
    uint16_t temp;
    uint16_t humidity;
    uint8_t crc;
} measurement_t;

// CRC8 calculation
uint8_t crc8(const uint8_t *data, size_t len) {
    uint8_t crc = CRC8_INIT;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLY;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// I2C write function
int i2c_write(int fd, uint8_t reg, const uint8_t *data, size_t len) {
    uint8_t buf[len + 1];
    buf[0] = reg;
    memcpy(buf + 1, data, len);
    if (ioctl(fd, I2C_RDWR, &buf) < 0) {
        perror("i2c_write");
        return -1;
    }
    return 0;
}

// I2C read function
int i2c_read(int fd, uint8_t reg, uint8_t *data, size_t len) {
    uint8_t buf[1];
    buf[0] = reg;
    if (ioctl(fd, I2C_RDWR, &buf) < 0) {
        perror("i2c_read");
        return -1;
    }
    if (ioctl(fd, I2C_RDWR, data) < 0) {
        perror("i2c_read");
        return -1;
    }
    return 0;
}

// Check if file exists
int file_exists(const char *filename) {
    FILE *file = fopen(filename, "r");
    if (file) {
        fclose(file);
        return 1;
    }
    return 0;
}

// Write CSV header
void write_csv_header(FILE *file) {
    fprintf(file, "timestamp,temp,humidity\n");
}

// Write CSV row
void write_csv_row(FILE *file, const char *timestamp, double temp, double humidity) {
    fprintf(file, "%s,%.2f,%.2f\n", timestamp, temp, humidity);
}

// Signal handler
void signal_handler(int signum) {
    printf("Caught signal %d, shutting down...\n", signum);
    // Clean up here if needed
    exit(EXIT_SUCCESS);
}

int main() {
    int i2c_fd = -1;
    int ret;
    FILE *csv_file = NULL;
    char timestamp[30];
    struct timespec ts;
    char filename[] = "environment.csv";

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    char i2c_bus_path[32];
    snprintf(i2c_bus_path, sizeof(i2c_bus_path), "/dev/i2c-%d", I2C_BUS);
    i2c_fd = open(i2c_bus_path, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Initialize CSV file
    csv_file = fopen(filename, "a");
    if (!csv_file) {
        perror("Failed to open CSV file");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (!file_exists(filename)) {
        write_csv_header(csv_file);
    }

    // Initialize sensor
    uint8_t cmd[2] = {CMD_SOFT_RESET, 0x00};
    if (i2c_write(i2c_fd, 0x00, cmd, 2) < 0) {
        fprintf(stderr, "Failed to reset sensor\n");
        fclose(csv_file);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Wait for reset
    usleep(100000);

    // Set clock stretching disabled
    uint8_t user_reg = 0x00;
    if (i2c_read(i2c_fd, CMD_READ_USER_REGISTER, &user_reg, 1) < 0) {
        fprintf(stderr, "Failed to read user register\n");
        fclose(csv_file);
        close(i2c_fd);
        return EXIT_FAILURE;
    }
    user_reg &= ~0x04; // Disable clock stretching
    if (i2c_write(i2c_fd, CMD_WRITE_USER_REGISTER, &user_reg, 1) < 0) {
        fprintf(stderr, "Failed to write user register\n");
        fclose(csv_file);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Main loop
    while (1) {
        // Start measurement
        if (i2c_write(i2c_fd, CMD_MEASURE_HIGH_REPEATABILTY, NULL, 0) < 0) {
            fprintf(stderr, "Failed to start measurement\n");
            fclose(csv_file);
            close(i2c_fd);
            return EXIT_FAILURE;
        }

        // Wait for measurement to complete
        usleep(MEASUREMENT_DELAY_MS * 1000);

        // Read measurement
        uint8_t data[6];
        if (i2c_read(i2c_fd, 0x00, data, 6) < 0) {
            fprintf(stderr, "Failed to read measurement data\n");
            continue;
        }

        // Validate CRC
        uint8_t crc = crc8(data, 5);
        if (data[5] != crc) {
            fprintf(stderr, "CRC validation failed\n");
            continue;
        }

        // Extract temperature and humidity
        uint16_t temp = (data[0] << 8) | data[1];
        uint16_t humidity = (data[2] << 8) | data[3];

        // Convert to Celsius and percent
        double temp_c = (double)temp * 175000.0 / 65536.0 - 45.0;
        double humidity_p = (double)humidity * 100.0 / 65536.0;

        // Get timestamp
        clock_gettime(CLOCK_REALTIME, &ts);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", gmtime(&ts.tv_sec));

        // Write to CSV
        write_csv_row(csv_file, timestamp, temp_c, humidity_p);

        // Sleep for sample interval
        usleep(SAMPLE_INTERVAL_S * 1000000);
    }

    // Clean up
    fclose(csv_file);
    close(i2c_fd);
    return EXIT_SUCCESS;
}

