    unsigned char data[3];

    // Read data from sensor
    ret = ioctl(fd, I2C_RDWR, (struct i2c_rdwr_ioctl_data *)&(struct i2c_msg[0]));
    if (ret < 0) {
        perror("I2C read failed");
        return -1;
    }

    // Check if data was read
    if (ret != 1) {
        fprintf(stderr, "I2C read returned unexpected number of messages\n");
        return -1;
    }

    // Copy data into buffer
    memcpy(data, buf, len);

    // Check CRC
    unsigned char crc = crc8(data, len - 1);
    if (crc != data[len - 1]) {
        fprintf(stderr, "CRC check failed for sensor data\n");
        return -1;
    }

    return 0;
}

// Sensor reset command
void reset_sensor(int fd) {
    unsigned char cmd[1] = {0xFE};
    struct i2c_msg msg = {
        .addr = I2C_ADDR,
        .flags = 0,
        .len = 1,
        .buf = cmd
    };

    struct i2c_rdwr_ioctl_data rdwr = {
        .msgs = &msg,
        .nmsgs = 1
    };

    if (ioctl(fd, I2C_RDWR, &rdwr) < 0) {
        perror("Sensor reset failed");
    }
}

// Signal handler
void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        printf("Caught signal %d, exiting...\n", signum);
        // Clean up here if needed
        exit(EXIT_SUCCESS);
    }
}

// Log to CSV
void log_data(const char *timestamp, double temperature, double humidity) {
    FILE *file = fopen(CSV_FILE, "a");
    if (!file) {
        perror("Failed to open CSV file");
        return;
    }

    fprintf(file, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
    fclose(file);
}

// Generate ISO 8601 timestamp
void get_iso_timestamp(char *timestamp, size_t size) {
    time_t now;
    struct tm *tm_info;
    time(&now);
    tm_info = gmtime(&now);
    strftime(timestamp, size, "%Y-%m-%dT%H:%M:%SZ", tm_info);
}

