#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <libgpiod.h>

#define I2C_BUS 1
#define I2C_ADDR 0x28
#define CMD_CONTINUOUS_MEASUREMENT 0x24
#define CRC_POLY 0x07
#define LOG_FILE "pressure_log.txt"
#define LOG_INTERVAL 5000  // 5 seconds in milliseconds
#define CRC_DATA_SIZE 9
#define CRC_BYTES 1
#define DATA_BYTES 8

typedef struct {
    uint16_t pressure;
    uint8_t crc;
} PressureData;

// CRC-8 calculation using polynomial 0x07
uint8_t calculate_crc8(const uint8_t *data, size_t length) {
    uint8_t crc = 0;
    for (size_t i = 0; i < length; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLY;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Check if CRC is valid
int validate_crc(const uint8_t *data, size_t length) {
    uint8_t calculated_crc = calculate_crc8(data, length - CRC_BYTES);
    return (data[length - CRC_BYTES] == calculated_crc);
}

// I2C write function
int i2c_write(int fd, uint8_t reg, const uint8_t *data, size_t len) {
    uint8_t buffer[len + 1];
    buffer[0] = reg;
    memcpy(buffer + 1, data, len);
    if (write(fd, buffer, len + 1) != len + 1) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

// I2C read function
int i2c_read(int fd, uint8_t reg, uint8_t *data, size_t len) {
    if (write(fd, &reg, 1) != 1) {
        perror("I2C write failed");
        return -1;
    }
    if (read(fd, data, len) != len) {
        perror("I2C read failed");
        return -1;
    }
    return 0;
}

// Log pressure data with timestamp
void log_pressure(FILE *log_file, uint16_t pressure) {
    time_t now = time(NULL);
    struct tm *tm_now = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_now);
    fprintf(log_file, "%s, %u Pa\n", timestamp, pressure);
    fflush(log_file);
}

// Signal handler to clean up
void handle_signal(int signo) {
    if (signo == SIGINT || signo == SIGTERM) {
        printf("Received signal, cleaning up...\n");
        exit(0);
    }
}

int main() {
    int i2c_fd = -1;
    FILE *log_file = NULL;
    struct gpiod_line *line = NULL;
    struct gpiod_line_request_config req_config;
    struct timespec ts;
    int ret;

    // Initialize signal handling
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Open I2C bus
    char i2c_bus_path[32];
    snprintf(i2c_bus_path, sizeof(i2c_bus_path), "/dev/i2c-%d", I2C_BUS);
    i2c_fd = open(i2c_bus_path, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Set I2C address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        close(i2c_fd);
        return 1;
    }

    // Send continuous measurement command
    uint8_t cmd[1] = {CMD_CONTINUOUS_MEASUREMENT};
    if (i2c_write(i2c_fd, 0x00, cmd, 1) < 0) {
        fprintf(stderr, "Failed to send continuous measurement command\n");
        fclose(log_file);
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        // Wait for conversion time
        ts.tv_sec = 0;
        ts.tv_nsec = 45000000000;  // 45 ms
        nanosleep(&ts, NULL);

        // Read response
        uint8_t response[CRC_DATA_SIZE];
        if (i2c_read(i2c_fd, 0x00, response, CRC_DATA_SIZE) < 0) {
            fprintf(stderr, "I2C read failed\n");
            break;
        }

        // Validate CRC
        if (!validate_crc(response, CRC_DATA_SIZE)) {
            fprintf(stderr, "CRC validation failed\n");
            continue;
        }

        // Extract pressure data
        uint16_t pressure = (response[0] << 8) | response[1];

        // Log pressure
        log_pressure(log_file, pressure);

        // Sleep for log interval
        ts.tv_sec = LOG_INTERVAL / 1000;
        ts.tv_nsec = (LOG_INTERVAL % 1000) * 1000000;
        nanosleep(&ts, NULL);
    }

    // Clean up
    fclose(log_file);
    close(i2c_fd);

    return 0;
}

