        fclose(log_file);
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        // Wait for conversion time
        ts.tv_sec = 0;
        ts.tv_nsec = 45000000000;  // 45 ms
        nanosleep(&ts, NULL);

