#define LPS33HW_CTRL_REG3 0x22
#define LPS33HW_STATUS_REG 0x27
#define LPS33HW_PRESS_OUT_XL 0x28
#define LPS33HW_PRESS_OUT_L 0x29
#define LPS33HW_PRESS_OUT_H 0x2A
#define LPS33HW_TEMP_OUT_L 0x2B
#define LPS33HW_TEMP_OUT_H 0x2C

volatile sig_atomic_t running = 1;

void handle_sigint(int sig) {
    running = 0;
}

void log_error(const char *fmt, ...) {
    va_list args;
    char buffer[256];
    time_t now;
    struct tm *tm_info;

    time(&now);
    tm_info = localtime_r(&now, NULL);
    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", tm_info);

    va_start(args, fmt);
    vsnprintf(buffer + strlen(buffer) + 1, sizeof(buffer) - strlen(buffer) - 1, fmt, args);
    va_end(args);

    fprintf(stderr, "%s: %s\n", buffer, "Error occurred");
    FILE *log_file = fopen("environmental_data.txt", "a");
    if (log_file) {
        fprintf(log_file, "%s: %s\n", buffer, "Error occurred");
        fclose(log_file);
    }
}

int i2c_init(int bus) {
    int file;
    if ((file = open(bus, O_RDWR)) < 0) {
        log_error("Failed to open I2C bus");
        return -1;
    }

    if (ioctl(file, I2C_SLAVE, LPS33HW_ADDR) < 0) {
        log_error("Failed to set I2C slave address");
        close(file);
        return -1;
    }

    return file;
}

void i2c_write(int fd, uint8_t reg, uint8_t val) {
    uint8_t buffer[2];
    buffer[0] = reg;
    buffer[1] = val;
    if (write(fd, buffer, 2) != 2) {
        log_error("I2C write failed");
    }
}

void i2c_read(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (ioctl(fd, I2C_RDWR, (struct i2c_msg *)buf) < 0) {
        log_error("I2C read failed");
    }
}

void configure_sensor(int fd) {
    i2c_write(fd, LPS33HW_CTRL_REG1, 0x00); // Reset
    usleep(100000); // Wait for reset
    i2c_write(fd, LPS33HW_CTRL_REG1, 0x07); // Enable pressure and temperature, 125 Hz
    i2c_write(fd, LPS33HW_CTRL_REG2, 0x00); // No interrupts
    i2c_write(fd, LPS33HW_CTRL_REG3, 0x00); // No FIFO
}

void read_sensor(int fd, float *pressure, float *temperature) {
    uint8_t status;
    i2c_read(fd, LPS33HW_STATUS_REG, &status, 1);

    if (status & 0x01) {
        uint8_t pressure_data[3];
        i2c_read(fd, LPS33HW_PRESS_OUT_XL, pressure_data, 3);

        int32_t pressure_raw = (int32_t)(pressure_data[0] | (pressure_data[1] << 8) | (pressure_data[2] << 16));
        *pressure = (float)pressure_raw / 4096.0;

        uint8_t temp_data[2];
        i2c_read(fd, LPS33HW_TEMP_OUT_L, temp_data, 2);

        int16_t temp_raw = (int16_t)(temp_data[0] | (temp_data[1] << 8));
        *temperature = (float)temp_raw / 16.0;
    } else {
        *pressure = 0.0;
        *temperature = 0.0;
    }
}

void log_data(float pressure, float temperature) {
    time_t now;
    struct tm *tm_info;
    char timestamp[20];
    char log_line[128];

    time(&now);
    tm_info = localtime_r(&now, NULL);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    snprintf(log_line, sizeof(log_line), "%s, Pressure: %.2f hPa, Temperature: %.2f °C\n", timestamp, pressure, temperature);

    FILE *log_file = fopen("environmental_data.txt", "a");
    if (log_file) {
        fprintf(log_file, "%s", log_line);
        fclose(log_file);
    } else {
        log_error("Failed to open log file");
    }
}

int main() {
    int i2c_fd = -1;
    FILE *log_file = NULL;

    signal(SIGINT, handle_sigint);

    i2c_fd = i2c_init(I2C_BUS);
    if (i2c_fd < 0) {
        return 1;
    }

    configure_sensor(i2c_fd);

    while (running) {
        float pressure = 0.0;
        float temperature = 0.0;
        read_sensor(i2c_fd, &pressure, &temperature);
        log_data(pressure, temperature);
        sleep(1);
    }

    if (i2c_fd >= 0) {
        close(i2c_fd);
    }

    if (log_file) {
        fclose(log_file);
    }

    return 0;
}

