    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLY;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int i2c_read_bytes(unsigned char reg, unsigned char *buf, size_t len) {
    unsigned char cmd[2];
    cmd[0] = reg;
    cmd[1] = 0x00;

    if (ioctl(i2c_fd, I2C_RDWR, &cmd) < 0) {
        perror("ioctl I2C_RDWR");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_RDWR, buf) < 0) {
        perror("ioctl I2C_RDWR");
        return -1;
    }

    return 0;
}

int i2c_write_bytes(unsigned char reg, unsigned char *buf, size_t len) {
    unsigned char cmd[2];
    cmd[0] = reg;
    cmd[1] = 0x00;

    if (ioctl(i2c_fd, I2C_RDWR, &cmd) < 0) {
        perror("ioctl I2C_RDWR");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_RDWR, buf) < 0) {
        perror("ioctl I2C_RDWR");
        return -1;
    }

    return 0;
}

void print_error_and_exit(const char *msg) {
    fprintf(stderr, "Error: %s\n", msg);
    exit(EXIT_FAILURE);
}

void print_diag_and_exit(const char *msg) {
    fprintf(stderr, "Diagnostic: %s\n", msg);
    exit(EXIT_FAILURE);
}

int main(int argc, char *argv[]) {
    int interval = 1000;
    int opt;

    while ((opt = getopt(argc, argv, "i:")) != -1) {
        switch (opt) {
            case 'i':
                interval = atoi(optarg);
                if (interval <= 0) {
                    print_diag_and_exit("Invalid interval value");
                }
                break;
            default:
                print_diag_and_exit("Usage: sdp32_reader [-i <interval>]");
        }
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        print_error_and_exit("Failed to set SIGINT handler");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        print_error_and_exit("Failed to set SIGTERM handler");
    }

    char i2c_bus_path[32];
    snprintf(i2c_bus_path, sizeof(i2c_bus_path), "/dev/i2c-%d", I2C_BUS);

    i2c_fd = open(i2c_bus_path, O_RDWR);
    if (i2c_fd < 0) {
        print_error_and_exit("Failed to open I2C bus");
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        print_error_and_exit("Failed to set I2C slave address");
    }

    // Soft reset
    unsigned char reset_cmd[1] = {CMD_SOFT_RESET};
    if (i2c_write_bytes(0x00, reset_cmd, 1) < 0) {
        print_error_and_exit("Failed to send soft reset command");
    }

    // Wait for reset
    usleep(100000);

    // Check if sensor is present
    unsigned char test_cmd[1] = {0x00};
    if (i2c_write_bytes(0x00, test_cmd, 1) < 0) {
        print_error_and_exit("Failed to send test command");
    }

    unsigned char response[1];
    if (i2c_read_bytes(0x00, response, 1) < 0) {
        print_error_and_exit("Failed to read response");
    }

    if (response[0] != 0x00) {
        print_diag_and_exit("Sensor not connected or not responding");
    }

    while (running) {
        unsigned char cmd[1] = {CMD_MEASURE};
        if (i2c_write_bytes(0x00, cmd, 1) < 0) {
            print_error_and_exit("Failed to send measurement command");
        }

        usleep(100000);

        unsigned char data[9];
        if (i2c_read_bytes(0x00, data, 9) < 0) {
            print_error_and_exit("Failed to read measurement data");
        }

        // Check CRCs
        if (crc8(data, 3) != data[2]) {
            print_error_and_exit("Pressure CRC8 check failed");
        }

        if (crc8(data + 3, 3) != data[5]) {
            print_error_and_exit("Temperature CRC8 check failed");
        }

        if (crc8(data + 6, 3) != data[8]) {
            print_error_and_exit("Scale factor CRC8 check failed");
        }

        // Format and print
        time_t now = time(NULL);
        struct tm *tm_now = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_now);

        printf("%s: ", timestamp);
        for (int i = 0; i < 9; i++) {
            printf("%02X ", data[i]);
        }
        printf("\n");

        usleep(interval * 1000);
    }

    close(i2c_fd);
    return 0;
