#include <gpiod.h>

#define I2C_BUS 1
#define I2C_ADDR 0x40
#define I2C_SDA_PIN 2
#define I2C_SCL_PIN 3
#define I2C_DEVICE "/dev/i2c-%d"
#define I2C_TIMEOUT 1000000 /* microseconds */
#define LOG_INTERVAL 1000 /* milliseconds */
#define CRC8_POLY 0x07
#define CRC8_INIT 0x00

typedef struct {
    uint16_t pressure;
    uint16_t temperature;
    uint16_t pressure_scale;
    uint16_t temperature_scale;
} sensor_data_t;

// CRC-8 calculation
uint8_t crc8(const uint8_t *data, size_t len) {
    uint8_t crc = CRC8_INIT;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLY;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Check CRC-8 for 3-byte word
int validate_crc(const uint8_t *data, size_t len) {
    if (len != 3) {
        return -1;
    }
    uint8_t crc = crc8(data, 2);
    if (crc != data[2]) {
        return -1;
    }
    return 0;
}

// Read 9-byte data from I2C
int read_sensor_data(int fd, uint8_t *buffer) {
    if (ioctl(fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        return -1;
    }

    if (read(fd, buffer, 9) != 9) {
        perror("Failed to read from I2C device");
        return -1;
    }

    return 0;
}

// Parse sensor data
int parse_sensor_data(const uint8_t *buffer, sensor_data_t *data) {
    if (buffer == NULL || data == NULL) {
        return -1;
    }

    // Pressure data (bytes 0-2)
    data->pressure = (buffer[0] << 8) | buffer[1];
    if (validate_crc(buffer, 3) != 0) {
        fprintf(stderr, "CRC error in pressure data\n");
        return -1;
    }

    // Temperature data (bytes 3-5)
    data->temperature = (buffer[3] << 8) | buffer[4];
    if (validate_crc(buffer + 3, 3) != 0) {
        fprintf(stderr, "CRC error in temperature data\n");
        return -1;
    }

    // Pressure scale factor (bytes 6-7)
    data->pressure_scale = (buffer[6] << 8) | buffer[7];
    if (validate_crc(buffer + 6, 3) != 0) {
        fprintf(stderr, "CRC error in pressure scale factor\n");
        return -1;
    }

    // Temperature scale factor (bytes 8-9)
    data->temperature_scale = (buffer[8] << 8) | buffer[9];
    if (validate_crc(buffer + 8, 3) != 0) {
        fprintf(stderr, "CRC error in temperature scale factor\n");
        return -1;
    }

    return 0;
}

// Signal handler
void handle_signal(int signo) {
    if (signo == SIGINT || signo == SIGTERM) {
        printf("\nReceived signal, exiting...\n");
        exit(EXIT_SUCCESS);
    }
}

int main() {
    int i2c_fd = -1;
    char i2c_path[32];
    uint8_t buffer[9];
    sensor_data_t data;
    struct sigaction sa;
    int ret;

    // Initialize signal handling
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Failed to set SIGINT handler");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Failed to set SIGTERM handler");
        return EXIT_FAILURE;
    }

    // Open I2C bus
    snprintf(i2c_path, sizeof(i2c_path), I2C_DEVICE, I2C_BUS);
    i2c_fd = open(i2c_path, O_RDWR | O_NOCTTY | O_CLOEXEC);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    // Verify I2C device is present
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Main loop
    while (1) {
        // Wait for conversion to complete (at least 45ms)
        usleep(45000);

        // Read sensor data
        if (read_sensor_data(i2c_fd, buffer) != 0) {
            fprintf(stderr, "I2C read failed, retrying...\n");
            usleep(100000); // 100ms delay before retry
            continue;
        }

        // Parse data
        if (parse_sensor_data(buffer, &data) != 0) {
            fprintf(stderr, "Data parsing failed, retrying...\n");
            usleep(100000); // 100ms delay before retry
            continue;
        }

        // Log data
        printf("Pressure: %d Pa (scale: %d)\n", data.pressure, data.pressure_scale);
        printf("Temperature: %d C (scale: %d)\n", data.temperature, data.temperature_scale);
        printf("-------------------------------\n");

        // Sleep for 1 second
        usleep(LOG_INTERVAL * 1000);
    }

    // Cleanup
    close(i2c_fd);
    return EXIT_SUCCESS;
}

