#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <time.h>

#define I2C_BUS 1
#define HDC1000_ADDR 0x40
#define HDC1000_CONFIG 0x01
#define HDC1000_HUMIDITY 0x02
#define HDC1000_TEMP 0x03
#define HDC1000_RESET 0x06
#define HDC1000_MANUFACTURER_ID 0xFE
#define HDC1000_DEVICE_ID 0xFF

#define CONVERSION_DELAY_MS 20
#define LOG_INTERVAL_MS 5000

int i2c_fd = -1;

void handle_signal(int sig) {
    if (i2c_fd != -1) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    exit(EXIT_SUCCESS);
}

void log_temperature_and_humidity(float temp, float humidity) {
    printf("Temperature: %.2f C, Humidity: %.2f %%\n", temp, humidity);
}

void read_hdc1000(float *temp, float *humidity) {
    uint16_t temp_raw, humidity_raw;

    // Read temperature
    if (ioctl(i2c_fd, I2C_SLAVE, HDC1000_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address: %s\n", strerror(errno));
        return;
    }

    if (write(i2c_fd, &HDC1000_TEMP, 1) < 0) {
        fprintf(stderr, "Failed to write to I2C: %s\n", strerror(errno));
        return;
    }

    usleep(CONVERSION_DELAY_MS * 1000);

    if (read(i2c_fd, &temp_raw, 2) < 0) {
        fprintf(stderr, "Failed to read temperature: %s\n", strerror(errno));
        return;
    }

    // Read humidity
    if (write(i2c_fd, &HDC1000_HUMIDITY, 1) < 0) {
        fprintf(stderr, "Failed to write to I2C: %s\n", strerror(errno));
        return;
    }

    usleep(CONVERSION_DELAY_MS * 1000);

    if (read(i2c_fd, &humidity_raw, 2) < 0) {
        fprintf(stderr, "Failed to read humidity: %s\n", strerror(errno));
        return;
    }

    // Convert to Celsius and %RH
    *temp = (float)(temp_raw * 175.0 / 65535.0 - 45.0);
    *humidity = (float)(humidity_raw * 100.0 / 65535.0);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    char i2c_bus_path[32];
    snprintf(i2c_bus_path, sizeof(i2c_bus_path), "/dev/i2c-%d", I2C_BUS);

    i2c_fd = open(i2c_bus_path, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    // Check if HDC1000 is present
    if (ioctl(i2c_fd, I2C_SLAVE, HDC1000_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    uint8_t manufacturer_id, device_id;
    if (read(i2c_fd, &manufacturer_id, 1) < 0) {
        fprintf(stderr, "Failed to read manufacturer ID: %s\n", strerror(errno));
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (read(i2c_fd, &device_id, 1) < 0) {
        fprintf(stderr, "Failed to read device ID: %s\n", strerror(errno));
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (manufacturer_id != HDC1000_MANUFACTURER_ID || device_id != HDC1000_DEVICE_ID) {
        fprintf(stderr, "HDC1000 sensor not found or invalid device ID.\n");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Configure sensor for 14-bit resolution
    uint16_t config = 0x0000; // 14-bit resolution for both
    if (write(i2c_fd, &config, 2) < 0) {
        fprintf(stderr, "Failed to write configuration: %s\n", strerror(errno));
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Start conversion
    if (write(i2c_fd, &HDC1000_CONFIG, 1) < 0) {
        fprintf(stderr, "Failed to start conversion: %s\n", strerror(errno));
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    while (1) {
        float temp, humidity;
        read_hdc1000(&temp, &humidity);
        log_temperature_and_humidity(temp, humidity);
        usleep(LOG_INTERVAL_MS * 1000);
    }

    close(i2c_fd);
    return EXIT_SUCCESS;
}

