    snprintf(device_path, sizeof(device_path), I2C_DEVICE, bus);

    int file_desc = open(device_path, O_RDWR);
    if (file_desc < 0) {
        perror("Failed to open I2C device");
        return -1;
    }

    if (ioctl(file_desc, I2C_TIMEOUT, I2C_TIMEOUT) < 0) {
        perror("Failed to set I2C timeout");
        close(file_desc);
        return -1;
    }

    if (ioctl(file_desc, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(file_desc);
        return -1;
    }

    return file_desc;
}

int i2c_read(int file_desc, uint8_t *rx_buffer, size_t len) {
    ssize_t bytes_read = read(file_desc, rx_buffer, len);
    if (bytes_read < 0) {
