    ssize_t bytes_written = write(file_desc, tx_buffer, len);
    if (bytes_written < 0) {
        perror("I2C write error");
        return -1;
    } else if ((size_t)bytes_written != len) {
        fprintf(stderr, "I2C write timeout or incomplete write\n");
        return -1;
    }
    return 0;
}

