    if (i2c_write(file_desc, &cmd, 1) < 0) {
        return -1.0;
    }

    usleep(10000);  // Wait for measurement to complete

    uint8_t rx_buffer[2];
    if (i2c_read(file_desc, rx_buffer, 2) < 0) {
        return -1.0;
    }

    int16_t raw = (rx_buffer[0] << 8) | rx_buffer[1];
    float temp = (float)raw / 128.0;
    return temp;
}

void log_temperature(float temp) {
    printf("Temperature: %.2f°C\n", temp);
}

