    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("Failed to set up signal handler");
        return EXIT_FAILURE;
    }

    // Initialize I2C
    while (retry_count < MAX_RETRIES) {
        file_desc = i2c_init(I2C_BUS);
        if (file_desc >= 0) {
            break;
        }
        fprintf(stderr, "I2C initialization failed, retrying... (%d/%d)\n", retry_count + 1, MAX_RETRIES);
        retry_count++;
        usleep(100000);  // 100ms delay between retries
    }

    if (file_desc < 0) {
        fprintf(stderr, "Failed to initialize I2C after %d retries\n", MAX_RETRIES);
        return EXIT_FAILURE;
    }

    // Main loop
    while (1) {
        float temp = read_temperature(file_desc);
        if (temp >= 0.0) {
            log_temperature(temp);
        } else {
            fprintf(stderr, "Failed to read temperature from sensor\n");
        }

        usleep(LOG_INTERVAL);
    }

    // Cleanup
    close(file_desc);
    return EXIT_SUCCESS;
}

