#define CRC8_POLY 0x31
#define CRC8_INIT 0x00

typedef struct {
    int fd;
    struct gpiod_line *sda_line;
    struct gpiod_line *scl_line;
    FILE *log_file;
} i2c_context;

void handle_signal(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        printf("Received signal, exiting...\n");
        exit(EXIT_SUCCESS);
    }
}

void i2c_init(i2c_context *ctx) {
    ctx->fd = -1;
    ctx->sda_line = NULL;
    ctx->scl_line = NULL;
    ctx->log_file = NULL;

    // Initialize GPIO lines for SDA and SCL
    const char *sda_chip = "gpiochip0";
    const char *scl_chip = "gpiochip0";

    ctx->sda_line = gpiod_line_get(sda_chip, I2C_SDA_PIN);
    if (!ctx->sda_line) {
        perror("Failed to get SDA GPIO line");
        exit(EXIT_FAILURE);
    }

    ctx->scl_line = gpiod_line_get(scl_chip, I2C_SCL_PIN);
    if (!ctx->scl_line) {
        perror("Failed to get SCL GPIO line");
        exit(EXIT_FAILURE);
    }

    // Set SDA and SCL as output
    if (gpiod_line_request_output(ctx->sda_line, "SDA", 0) < 0) {
        perror("Failed to request SDA GPIO as output");
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(ctx->scl_line, "SCL", 0) < 0) {
        perror("Failed to request SCL GPIO as output");
        exit(EXIT_FAILURE);
    }

    // Open I2C bus
    char i2c_bus_path[32];
    snprintf(i2c_bus_path, sizeof(i2c_bus_path), "/dev/i2c-%d", I2C_BUS);
    ctx->fd = open(i2c_bus_path, O_RDWR);
    if (ctx->fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    if (ioctl(ctx->fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(ctx->fd);
        exit(EXIT_FAILURE);
    }
}

void i2c_deinit(i2c_context *ctx) {
    if (ctx->log_file) {
        fclose(ctx->log_file);
    }

    if (ctx->sda_line) {
        gpiod_line_release(ctx->sda_line);
    }

    if (ctx->scl_line) {
        gpiod_line_release(ctx->scl_line);
    }

    if (ctx->fd >= 0) {
        close(ctx->fd);
    }
}

void i2c_write_byte(i2c_context *ctx, uint8_t byte) {
    if (write(ctx->fd, &byte, 1) != 1) {
        perror("I2C write error");
        exit(EXIT_FAILURE);
    }
}

void i2c_read_bytes(i2c_context *ctx, uint8_t *buffer, size_t length) {
    if (read(ctx->fd, buffer, length) != length) {
        perror("I2C read error");
        exit(EXIT_FAILURE);
    }
}

uint8_t crc8(const uint8_t *data, size_t length) {
    uint8_t crc = CRC8_INIT;
    for (size_t i = 0; i < length; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLY;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

void log_sample(FILE *log_file, time_t timestamp, int16_t pressure, float temperature) {
    char timestamp_str[32];
    struct tm *tm_info = localtime(&timestamp);
    strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(log_file, "%s,%d,%f\n", timestamp_str, pressure, temperature);
    fflush(log_file);
}

void perform_measurement(i2c_context *ctx) {
    uint8_t cmd[1] = {0x21}; // Start measurement command
    uint8_t response[9] = {0};

    i2c_write_byte(ctx, cmd[0]);

    usleep(MEASUREMENT_DELAY_MS * 1000);

    i2c_read_bytes(ctx, response, sizeof(response));

    if (response[0] != 0x00 || response[1] != 0x00) {
        fprintf(stderr, "Invalid response header\n");
        return;
    }

    int16_t pressure = (response[2] << 8) | response[3];
    int16_t temperature = (response[4] << 8) | response[5];

    uint8_t crc = crc8(response, 6);
    if (crc != response[6]) {
        fprintf(stderr, "CRC8 mismatch for pressure word\n");
        return;
    }

    uint8_t crc2 = crc8(&response[6], 3);
    if (crc2 != response[8]) {
        fprintf(stderr, "CRC8 mismatch for temperature word\n");
        return;
    }

    log_sample(ctx->log_file, time(NULL), pressure, temperature);
}

int main() {
    i2c_context ctx;
    i2c_init(&ctx);

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    ctx.log_file = fopen("pressure_log.txt", "a");
    if (!ctx.log_file) {
        perror("Failed to open log file");
        i2c_deinit(&ctx);
        exit(EXIT_FAILURE);
    }

    fprintf(ctx.log_file, "Timestamp,Pressure(Pa),Temperature(C)\n");
    fflush(ctx.log_file);

    while (1) {
        perform_measurement(&ctx);
        usleep(1000000); // 1 second interval
    }

    i2c_deinit(&ctx);
    return 0;
}

