#include <gpiod.h>

#define I2C_BUS "/dev/i2c-1"
#define SDP800_I2C_ADDR 0x40
#define CMD_MEASURE 0x20
#define CMD_SOFT_RESET 0x80
#define CMD_GET_SERIAL 0x90
#define CMD_GET_FIRMWARE 0xA0
#define CMD_GET_CALIBRATION 0xB0
#define CMD_GET_CONFIGURATION 0xC0
#define CMD_SET_CONFIGURATION 0xD0
#define CMD_GET_STATUS 0xE0
#define CMD_GET_ERROR 0xF0
#define CMD_GET_DATA 0x00

#define MEASUREMENT_DELAY_MS 8
#define CRC8_POLY 0x31
#define CRC8_INIT 0x00

typedef struct {
    uint16_t pressure;
    uint8_t crc;
} measurement_t;

// CRC-8 calculation
uint8_t calculate_crc8(const uint8_t *data, size_t len) {
    uint8_t crc = CRC8_INIT;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLY;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// I2C write function with error handling
int i2c_write(int fd, uint8_t reg, const uint8_t *data, size_t len) {
    uint8_t buffer[len + 1];
    buffer[0] = reg;
    memcpy(buffer + 1, data, len);

    if (ioctl(fd, I2C_RDWR, &buffer) < 0) {
        perror("i2c_write");
        return -1;
    }

    return 0;
}

// I2C read function with error handling
int i2c_read(int fd, uint8_t reg, uint8_t *data, size_t len) {
    if (ioctl(fd, I2C_SLAVE, SDP800_I2C_ADDR) < 0) {
        perror("i2c_set_slave");
        return -1;
    }

    if (ioctl(fd, I2C_RDWR, &reg) < 0) {
        perror("i2c_write_reg");
        return -1;
    }

    if (ioctl(fd, I2C_RDWR, data) < 0) {
        perror("i2c_read_data");
        return -1;
    }

    return 0;
}

// Check if file exists
int file_exists(const char *filename) {
    struct stat buffer;
    return (stat(filename, &buffer) == 0);
}

// Signal handler
void handle_signal(int signum) {
    printf("\nCaught signal %d, exiting...\n", signum);
    exit(EXIT_SUCCESS);
}

int main() {
    int i2c_fd;
    uint8_t cmd[1] = {CMD_MEASURE};
    uint8_t response[3];
    FILE *log_file = NULL;
    char log_filename[] = "airflow_log.csv";
    struct timespec ts;
    int ret;

    // Open I2C bus
    if ((i2c_fd = open(I2C_BUS, O_RDWR | O_NONBLOCK)) < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    // Initialize signal handling
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Initialize log file
    if (!file_exists(log_filename)) {
        log_file = fopen(log_filename, "w");
        if (!log_file) {
            perror("Failed to create log file");
            close(i2c_fd);
            return EXIT_FAILURE;
        }
        fprintf(log_file, "timestamp,pressure\n");
        fclose(log_file);
    } else {
        log_file = fopen(log_filename, "a");
        if (!log_file) {
            perror("Failed to open log file");
            close(i2c_fd);
            return EXIT_FAILURE;
        }
    }

    // Soft reset
    if (i2c_write(i2c_fd, CMD_SOFT_RESET, NULL, 0) < 0) {
        close(i2c_fd);
        fclose(log_file);
        return EXIT_FAILURE;
    }

    // Wait for sensor to stabilize
    usleep(100000);

