#define SAFE_MAX_PRESSURE 250.0

typedef struct {
    int i2c_fd;
    FILE *log_file;
    int retry_count;
} sensor_state;

void handle_signal(int sig) {
    (void)sig;
    if (sensor_state.i2c_fd != -1) {
        close(sensor_state.i2c_fd);
        sensor_state.i2c_fd = -1;
    }
    if (sensor_state.log_file != NULL) {
