void log_pressure(double pressure) {
    time_t now = time(NULL);
    struct tm *tm_now = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_now);
    fprintf(sensor_state.log_file, "%s,%f\n", timestamp, pressure);
    fflush(sensor_state.log_file);
}

void read_pressure() {
    uint8_t buffer[3];
    int ret;

    // Read pressure data
    buffer[0] = MLX90821_REG_PRES_MSB;
    ret = ioctl(sensor_state.i2c_fd, I2C_RDWR, (struct i2c_msg *) &buffer);
    if (ret < 0) {
        perror("I2C read failed");
        return;
    }

    // Read pressure data
    buffer[0] = MLX90821_REG_PRES_LSB;
    ret = ioctl(sensor_state.i2c_fd, I2C_RDWR, (struct i2c_msg *) &buffer);
    if (ret < 0) {
        perror("I2C read failed");
        return;
    }

    // Read pressure data
    buffer[0] = MLX90821_REG_PRES_XLSB;
    ret = ioctl(sensor_state.i2c_fd, I2C_RDWR, (struct i2c_msg *) &buffer);
    if (ret < 0) {
        perror("I2C read failed");
        return;
    }

    // Calculate pressure
    int32_t pressure = (int32_t) (buffer[0] << 16 | buffer[1] << 8 | buffer[2]);
    double kPa = (double) pressure / 1000.0;

