void log_message(const char *fmt, ...) {
    va_list args;
    char buffer[1024];
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    strftime(buffer, sizeof(buffer), "%Y-%m-%dT%H:%M:%SZ", tm);
    va_start(args, fmt);
    vsnprintf(buffer + strlen(buffer) + 1, sizeof(buffer) - strlen(buffer) - 1, fmt, args);
    va_end(args);

    fprintf(stderr, "%s: %s\n", buffer, fmt);
}

void log_to_file(const char *fmt, ...) {
    if (!app_state.log_file) return;

    va_list args;
    char buffer[1024];
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    strftime(buffer, sizeof(buffer), "%Y-%m-%dT%H:%M:%SZ", tm);
    va_start(args, fmt);
    vsnprintf(buffer + strlen(buffer) + 1, sizeof(buffer) - strlen(buffer) - 1, fmt, args);
    va_end(args);

    fprintf(app_state.log_file, "%s: %s\n", buffer, fmt);
