#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/gpio.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_PIN 4
#define MAX_TICKS 271
#define SYNC_TICKS 56
#define NIBBLE_TICKS_MIN 12
#define NIBBLE_TICKS_MAX 271
#define NIBBLE_TICKS_SYNC 56

typedef enum {
    STATE_IDLE,
    STATE_SYNC,
    STATE_NIBBLE,
    STATE_DATA,
    STATE_CHECKSUM
} state_t;

typedef struct {
    int fd;
    struct gpiod_line *line;
    state_t state;
    int ticks;
    int current_nibble;
    int data[4];
    int checksum;
    int error;
} sensor_t;

void handle_signal(int sig) {
    exit(EXIT_SUCCESS);
}

void log_pressure(const char *timestamp, int pressure) {
    FILE *fp = fopen("pressure_log.txt", "a");
    if (fp == NULL) {
        perror("fopen");
        return;
    }

    fprintf(fp, "%s, Pressure: %04.2f Pa\n", timestamp, (double)pressure);
    fclose(fp);
}

void log_error(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
}

void init_sensor(sensor_t *sensor) {
    sensor->state = STATE_IDLE;
    sensor->ticks = 0;
    sensor->current_nibble = 0;
    sensor->error = 0;
}

int read_gpio_level(sensor_t *sensor) {
    int level;
    int ret = gpiod_line_get_value(sensor->line, &level);
    if (ret < 0) {
        log_error("Failed to read GPIO line");
        return -1;
    }
    return level;
}

int wait_for_gpio_edge(sensor_t *sensor, int expected_level, int timeout_ms) {
    struct timespec ts;
    ts.tv_sec = 0;
    ts.tv_nsec = timeout_ms * 1000000;

    int start_time = clock_gettime(CLOCK_MONOTONIC, NULL);
    int elapsed = 0;

    while (elapsed < timeout_ms) {
        int level = read_gpio_level(sensor);
        if (level == expected_level) {
            return 0;
        }
        nanosleep(&ts, NULL);
        clock_gettime(CLOCK_MONOTONIC, &ts);
        elapsed = (ts.tv_sec - start_time.tv_sec) * 1000 + (ts.tv_nsec - start_time.tv_nsec) / 1000000;
    }

    log_error("Timeout waiting for GPIO edge");
    return -1;
}

int read_nibble(sensor_t *sensor) {
    int level = read_gpio_level(sensor);
    if (level < 0) return -1;

    if (level == 0) {
        return 0;
    } else {
        return 1;
    }
}

int read_nibble_ticks(sensor_t *sensor, int expected_level) {
    int ticks = 0;
    int level = read_gpio_level(sensor);
    if (level < 0) return -1;

    if (level != expected_level) {
        log_error("Unexpected level during nibble");
        return -1;
    }

    while (level == expected_level) {
        ticks++;
        usleep(100); // 100 microseconds
        level = read_gpio_level(sensor);
        if (level < 0) return -1;
    }

    if (ticks < NIBBLE_TICKS_MIN || ticks > NIBBLE_TICKS_MAX) {
        log_error("Invalid nibble pulse width");
        return -1;
    }

    return ticks;
}

int read_sync_pulse(sensor_t *sensor) {
    int ticks = 0;
    int level = read_gpio_level(sensor);
    if (level < 0) return -1;

    if (level != 1) {
        log_error("Unexpected level during sync");
        return -1;
    }

    while (level == 1) {
        ticks++;
        usleep(100);
        level = read_gpio_level(sensor);
        if (level < 0) return -1;
    }

    if (ticks != NIBBLE_TICKS_SYNC) {
        log_error("Invalid sync pulse width");
        return -1;
    }

    return 0;
}

int read_data(sensor_t *sensor) {
    int ticks = 0;
    int level = read_gpio_level(sensor);
    if (level < 0) return -1;

    if (level != 1) {
        log_error("Unexpected level during data");
        return -1;
    }

    while (level == 1) {
        ticks++;
        usleep(100);
        level = read_gpio_level(sensor);
        if (level < 0) return -1;
    }

    if (ticks < NIBBLE_TICKS_MIN || ticks > NIBBLE_TICKS_MAX) {
        log_error("Invalid data nibble pulse width");
        return -1;
    }

    return ticks;
}

int read_check_sum(sensor_t *sensor) {
    int ticks = 0;
    int level = read_gpio_level(sensor);
    if (level < 0) return -1;

    if (level != 1) {
        log_error("Unexpected level during checksum");
        return -1;
    }

    while (level == 1) {
        ticks++;
        usleep(100);
        level = read_gpio_level(sensor);
        if (level < 0) return -1;
    }

    if (ticks < NIBBLE_TICKS_MIN || ticks > NIBBLE_TICKS_MAX) {
        log_error("Invalid checksum pulse width");
        return -1;
    }

    return ticks;
}

int read_pressure(sensor_t *sensor) {
    int level = read_gpio_level(sensor);
    if (level < 0) return -1;

    if (level != 1) {
        log_error("Unexpected level during start");
        return -1;
    }

    if (wait_for_gpio_edge(sensor, 0, 100) < 0) {
        return -1;
    }

    if (read_sync_pulse(sensor) < 0) {
        return -1;
    }

    for (int i = 0; i < 4; i++) {
        int ticks = read_nibble_ticks(sensor, 1);
        if (ticks < 0) {
            return -1;
        }
        sensor->data[i] = ticks;
    }

    int checksum_ticks = read_check_sum(sensor);
    if (checksum_ticks < 0) {
        return -1;
    }

    int checksum = 0;
    for (int i = 0; i < 4; i++) {
        checksum += sensor->data[i];
    }

    if (checksum_ticks != checksum) {
        log_error("Checksum mismatch");
        return -1;
    }

    int pressure = 0;
    for (int i = 0; i < 4; i++) {
        pressure = (pressure << 4) | sensor->data[i];
    }

    return pressure;
}

void cleanup_sensor(sensor_t *sensor) {
    if (sensor->line) {
        gpiod_line_release(sensor->line);
    }
    if (sensor->fd >= 0) {
        close(sensor->fd);
    }
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    sensor_t sensor;
    sensor.fd = open("/dev/gpiochip4", O_RDWR);
    if (sensor.fd < 0) {
        log_error("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    struct gpiod_line *line = gpiod_chip_get_line(sensor.fd, GPIO_PIN);
    if (!line) {
        log_error("Failed to get GPIO line");
        close(sensor.fd);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(line, "pressure_sensor", GPIO_LINE_FLAG_ACTIVE_LOW) < 0) {
        log_error("Failed to request GPIO line");
        gpiod_line_release(line);
        close(sensor.fd);
        return EXIT_FAILURE;
    }

    sensor.line = line;
    init_sensor(&sensor);

    while (1) {
        int pressure = read_pressure(&sensor);
        if (pressure < 0) {
            log_error("Failed to read pressure");
            continue;
        }

        time_t now = time(NULL);
        struct tm *tm = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

        log_pressure(timestamp, pressure);
        usleep(1000000); // 1 second
    }

    cleanup_sensor(&sensor);
    return EXIT_SUCCESS;
}

