#define LOG_FILE "greenhouse_temps.dat"
#define LOG_INTERVAL 60  // seconds
#define TMP117_REGISTER_TEMP 0x00
#define TMP117_REGISTER_ID 0x0F

typedef enum {
    STATUS_OK,
    STATUS_I2C_ERROR,
    STATUS_FILE_ERROR,
    STATUS_DEVICE_ID_MISMATCH
} status_t;

static int i2c_fd = -1;
static FILE *log_file = NULL;
static volatile int running = 1;

void handle_signal(int sig) {
    running = 0;
}

status_t read_device_id(int fd) {
    uint8_t reg = TMP117_REGISTER_ID;
    uint8_t id;
    ssize_t bytes_read;

    if (ioctl(fd, I2C_SLAVE, TMP117_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        return STATUS_I2C_ERROR;
    }

    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return STATUS_I2C_ERROR;
    }

    if ((bytes_read = read(fd, &id, 1)) != 1) {
        perror("Failed to read device ID");
        return STATUS_I2C_ERROR;
    }

    if (id != TMP117_DEVICE_ID) {
        fprintf(stderr, "Device ID mismatch: expected 0x%02X, got 0x%02X\n", TMP117_DEVICE_ID, id);
        return STATUS_DEVICE_ID_MISMATCH;
    }

    return STATUS_OK;
}

status_t read_temperature(float *temp) {
    uint8_t reg = TMP117_REGISTER_TEMP;
    uint16_t data;
    ssize_t bytes_read;

    if (ioctl(i2c_fd, I2C_SLAVE, TMP117_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        return STATUS_I2C_ERROR;
    }

    if (write(i2c_fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return STATUS_I2C_ERROR;
    }

    if ((bytes_read = read(i2c_fd, &data, 2)) != 2) {
        perror("Failed to read temperature data");
        return STATUS_I2C_ERROR;
    }

    *temp = (float)(data & 0xFFF) * 0.00125f - 273.15f;
    return STATUS_OK;
}

void log_temperature(float temp) {
    uint32_t temp_int = *(uint32_t *)&temp;
    if (fwrite(&temp_int, sizeof(temp_int), 1, log_file) != 1) {
        perror("Failed to write to log file");
    }
}

void cleanup() {
    if (log_file) {
        fclose(log_file);
    }

    if (i2c_fd >= 0) {
        close(i2c_fd);
    }

    printf("Cleanup complete.\n");
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Failed to set signal handler");
        return EXIT_FAILURE;
    }

    // Open I2C bus
    if ((i2c_fd = open(I2C_BUS, O_RDWR)) < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    // Verify device ID
    if (read_device_id(i2c_fd) != STATUS_OK) {
        cleanup();
        return EXIT_FAILURE;
    }

    // Open log file
    if ((log_file = fopen(LOG_FILE, "wb")) == NULL) {
        perror("Failed to open log file");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Starting temperature logging...\n");

    while (running) {
        float temp = 0.0f;
        status_t status = read_temperature(&temp);
        if (status == STATUS_OK) {
            log_temperature(temp);
            printf("Logged temperature: %.2f°C\n", temp);
        } else {
            printf("I2C communication failed, retrying...\n");
        }

        sleep(LOG_INTERVAL);
    }

    cleanup();
    return EXIT_SUCCESS;
}

