#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <libgpiod/libgpiod.h>

#define SHT40_I2C_ADDR 0x40
#define SHT40_MEASURE_CMD 0x27
#define SHT40_RESET_CMD 0x30
#define SHT40_CRC_POLY 0x31
#define SHT40_CRC_INIT 0x00

typedef struct {
    uint16_t temp;
    uint16_t humidity;
    uint8_t crc_temp;
    uint8_t crc_humid;
} sht40_data_t;

// CRC-8 calculation using SHT40 polynomial
uint8_t calculate_crc8(const uint8_t *data, size_t len) {
    uint8_t crc = SHT40_CRC_INIT;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x01) {
                crc = (crc >> 1) ^ SHT40_CRC_POLY;
            } else {
                crc >>= 1;
            }
        }
    }
    return crc;
}

// Validate CRC for a given data buffer
int validate_crc(const uint8_t *data, size_t len, uint8_t expected_crc) {
    uint8_t calculated_crc = calculate_crc8(data, len);
    return (calculated_crc == expected_crc);
}

// I2C write function with error checking
int i2c_write(int fd, uint8_t reg, const uint8_t *data, size_t len) {
    uint8_t buf[len + 1];
    buf[0] = reg;
    memcpy(buf + 1, data, len);

    if (write(fd, buf, len + 1) != len + 1) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

// I2C read function with error checking
int i2c_read(int fd, uint8_t reg, uint8_t *data, size_t len) {
    if (ioctl(fd, I2C_SLAVE, SHT40_I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        return -1;
    }

    if (write(fd, &reg, 1) != 1) {
        perror("I2C write failed");
        return -1;
    }

    if (read(fd, data, len) != len) {
        perror("I2C read failed");
        return -1;
    }
    return 0;
}

// Signal handler to clean up resources
void handle_sigint(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    exit(EXIT_SUCCESS);
}

int main() {
    int i2c_fd = -1;
    FILE *log_file = NULL;
    struct timespec ts;
    char log_line[256];

    // Initialize signal handler
    signal(SIGINT, handle_sigint);

    // Open I2C device
    const char *i2c_dev = "/dev/i2c-1";
    i2c_fd = open(i2c_dev, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, SHT40_I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Initialize log file
    log_file = fopen("environmental_data.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Reset the sensor
    if (i2c_write(i2c_fd, SHT40_RESET_CMD, NULL, 0) < 0) {
        fclose(log_file);
        close(i2c_fd);
        return EXIT_FAILURE;
    }
    usleep(10000); // Wait 10ms for reset to complete

    while (1) {
        // Send measurement command
        if (i2c_write(i2c_fd, SHT40_MEASURE_CMD, NULL, 0) < 0) {
            fclose(log_file);
            close(i2c_fd);
            return EXIT_FAILURE;
        }

        // Wait for conversion to complete (minimum 8.5ms)
        usleep(8500);

        // Read 6 bytes from the sensor
        uint8_t data[6];
        if (i2c_read(i2c_fd, 0x00, data, 6) < 0) {
            fclose(log_file);
            close(i2c_fd);
            return EXIT_FAILURE;
        }

        // Extract temperature and humidity data
        uint16_t temp = (data[0] << 8) | data[1];
        uint16_t humidity = (data[3] << 8) | data[4];

        // Validate CRCs
        if (!validate_crc(data, 3, data[2]) || !validate_crc(data + 3, 3, data[5])) {
            fprintf(stderr, "CRC validation failed\n");
            usleep(500000); // Wait 0.5s before next attempt
            continue;
        }

        // Format timestamp
        clock_gettime(CLOCK_REALTIME, &ts);
        struct tm *tm_info = localtime(&ts.tv_sec);
        char timestamp[30];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

        // Format log line
        snprintf(log_line, sizeof(log_line), "%s, %.2f°C, %.2f%%RH\n", timestamp, (float)temp / 65536 * 175.72 - 46.85, (float)humidity / 65536 * 125.0 - 6.0);

        // Write to log file
        if (fprintf(log_file, "%s", log_line) < 0) {
            perror("Failed to write to log file");
            fclose(log_file);
            close(i2c_fd);
            return EXIT_FAILURE;
        }

        // Flush the file
        if (fflush(log_file) != 0) {
            perror("Failed to flush log file");
            fclose(log_file);
            close(i2c_fd);
            return EXIT_FAILURE;
        }

        // Wait 5 seconds before next reading
        usleep(5000000);
    }

    // Clean up on exit (should not reach here normally)
    fclose(log_file);
    close(i2c_fd);
    return EXIT_SUCCESS;
}

