#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <time.h>
#include <errno.h>

#define I2C_BUS 1
#define TMP117_ADDR 0x48
#define BUFFER_SIZE 100
#define SAMPLE_INTERVAL 5
#define LOG_FILE "temperature_log.dat"

typedef struct {
    double temperatures[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

void init_buffer(CircularBuffer *buffer) {
    buffer->head = 0;
    buffer->count = 0;
    for (int i = 0; i < BUFFER_SIZE; i++) {
        buffer->temperatures[i] = 0.0;
    }
}

void write_to_file(const char *filename, const CircularBuffer *buffer) {
    FILE *file = fopen(filename, "wb");
    if (!file) {
        perror("Failed to open log file");
        return;
    }

    fwrite(&buffer->count, sizeof(int), 1, file);
    fwrite(buffer->temperatures, sizeof(double), buffer->count, file);

    fclose(file);
}

void read_temperature(int fd, double *temp) {
    uint8_t reg = 0x00; // Configuration register
    uint8_t buf[2];
    int ret;

    if (ioctl(fd, I2C_SLAVE, TMP117_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        return;
    }

    ret = read(fd, buf, 2);
    if (ret < 0) {
        perror("I2C read failed");
        return;
    }

    *temp = (buf[0] << 8 | buf[1]) * 0.00125; // Convert to Celsius
}

void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        printf("Shutting down...\n");
        write_to_file(LOG_FILE, &buffer);
        // Additional cleanup can be added here
        exit(EXIT_SUCCESS);
    }
}

int main() {
    int i2c_fd;
    CircularBuffer buffer;
    struct sigaction sa;
    int ret;

    // Initialize circular buffer
    init_buffer(&buffer);

    // Set up signal handler
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Failed to set SIGINT handler");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Failed to set SIGTERM handler");
        return EXIT_FAILURE;
    }

    // Open I2C bus
    char i2c_bus_path[32];
    snprintf(i2c_bus_path, sizeof(i2c_bus_path), "/dev/i2c-%d", I2C_BUS);
    i2c_fd = open(i2c_bus_path, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    // Verify I2C device
    if (ioctl(i2c_fd, I2C_SLAVE, TMP117_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Main loop
    while (1) {
        double temp = 0.0;
        read_temperature(i2c_fd, &temp);

        if (temp != 0.0) {
            buffer.temperatures[buffer.head] = temp;
            buffer.head = (buffer.head + 1) % BUFFER_SIZE;
            buffer.count = (buffer.count + 1) % BUFFER_SIZE;
            if (buffer.count == 0) {
                buffer.count = BUFFER_SIZE;
            }
        } else {
            printf("I2C read failed, skipping sample.\n");
        }

        // Persist buffer to file
        write_to_file(LOG_FILE, &buffer);

        // Sleep for sample interval
        sleep(SAMPLE_INTERVAL);
    }

    // Cleanup
    close(i2c_fd);
    return EXIT_SUCCESS;
}

