#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <time.h>
#include <gpiod.h>

#define I2C_BUS 1
#define I2C_ADDR 0x1E
#define LOG_FILE "mag_temp_log.csv"
#define HEADER "timestamp,rotational_speed,temperature\n"

typedef struct {
    int i2c_fd;
    FILE *log_file;
    int running;
} app_state;

void handle_sigint(int sig) {
    app_state *state = (app_state *)malloc(sizeof(app_state));
    if (state) {
        state->running = 0;
    }
    printf("Caught signal %d, shutting down...\n", sig);
    if (state && state->log_file) {
        fprintf(state->log_file, "\n");
        fflush(state->log_file);
        fclose(state->log_file);
    }
    if (state && state->i2c_fd >= 0) {
        close(state->i2c_fd);
    }
    free(state);
    exit(EXIT_SUCCESS);
}

void log_data(app_state *state, double rotational_speed, double temperature) {
    char timestamp[30];
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(state->log_file, "%s,%.6f,%.6f\n", timestamp, rotational_speed, temperature);
    fflush(state->log_file);
}

void write_nan(app_state *state) {
    char timestamp[30];
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(state->log_file, "%s,NaN,NaN\n", timestamp);
    fflush(state->log_file);
}

int i2c_read_word(int fd, uint8_t reg) {
    uint8_t buf[2];
    int ret;

    buf[0] = reg;
    ret = write(fd, buf, 1);
    if (ret != 1) {
        fprintf(stderr, "I2C write error: %s\n", strerror(errno));
        return -1;
    }

    usleep(1000); // Wait for the sensor to respond

    ret = read(fd, buf, 2);
    if (ret != 2) {
        fprintf(stderr, "I2C read error: %s\n", strerror(errno));
        return -1;
    }

    return (buf[0] << 8) | buf[1];
}

void i2c_init(int *fd) {
    char filename[256];
    snprintf(filename, sizeof(filename), "/dev/i2c-%d", I2C_BUS);

    *fd = open(filename, O_RDWR);
    if (*fd < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    if (ioctl(*fd, I2C_SLAVE, I2C_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address: %s\n", strerror(errno));
        close(*fd);
        exit(EXIT_FAILURE);
    }
}

void log_init(FILE **file) {
    *file = fopen(LOG_FILE, "a");
    if (*file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    // Check if file is empty or needs header
    fseek(*file, 0, SEEK_END);
    if (ftell(*file) == 0) {
        fprintf(*file, "%s", HEADER);
        fflush(*file);
    }
}

int main() {
    app_state state = {0};
    int i2c_fd = -1;
    double rotational_speed = 0.0;
    double temperature = 0.0;
    int read_result;
    int i = 0;

    signal(SIGINT, handle_sigint);

    i2c_init(&i2c_fd);
    log_init(&state.log_file);

    while (state.running) {
        // Read temperature
        read_result = i2c_read_word(i2c_fd, 0x01); // Temperature register
        if (read_result < 0) {
            write_nan(&state);
            usleep(1000000); // 1 second
            continue;
        }

        temperature = (double)(read_result) / 16384.0 - 273.15;

        // Read rotational speed
        read_result = i2c_read_word(i2c_fd, 0x02); // Rotational speed register
        if (read_result < 0) {
            write_nan(&state);
            usleep(1000000); // 1 second
            continue;
        }

        rotational_speed = (double)(read_result) / 16384.0;

        log_data(&state, rotational_speed, temperature);

        usleep(1000000); // 1 second
        i++;
    }

    if (state.log_file) {
        fclose(state.log_file);
    }

    if (i2c_fd >= 0) {
        close(i2c_fd);
    }

    return 0;
}

