#define I2C_BUS "/dev/i2c-1"
#define SENSOR_ADDR 0x28
#define LOG_FILE "flow_log.txt"
#define RECONNECT_DELAY 2
#define SAMPLE_INTERVAL 1

typedef struct {
    int i2c_fd;
    FILE *log_file;
    int running;
} app_state;

void handle_signal(int sig) {
    app_state *state = (app_state *)malloc(sizeof(app_state));
    if (state) {
        state->running = 0;
        free(state);
    }
}

void close_i2c(app_state *state) {
    if (state->i2c_fd >= 0) {
        close(state->i2c_fd);
        state->i2c_fd = -1;
    }
}

void close_log(app_state *state) {
    if (state->log_file) {
        fclose(state->log_file);
        state->log_file = NULL;
    }
}

void init_i2c(app_state *state) {
    state->i2c_fd = open(I2C_BUS, O_RDWR);
    if (state->i2c_fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    if (ioctl(state->i2c_fd, I2C_SLAVE, SENSOR_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close_i2c(state);
        exit(EXIT_FAILURE);
    }
}

void log_measurement(double flow_slpm, double temperature_c, time_t timestamp) {
    char buffer[256];
    struct tm *tm_info = localtime(&timestamp);
    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", tm_info);
    fprintf(stderr, "[%s] Flow: %.2f SLPM, Temperature: %.2f °C\n", buffer, flow_slpm, temperature_c);
    fprintf(stdout, "[%s] Flow: %.2f SLPM, Temperature: %.2f °C\n", buffer, flow_slpm, temperature_c);
    fprintf(state->log_file, "[%s] Flow: %.2f SLPM, Temperature: %.2f °C\n", buffer, flow_slpm, temperature_c);
    fflush(state->log_file);
}

void read_sensor_data(app_state *state) {
    uint8_t buffer[4];
    ssize_t bytes_read;

    bytes_read = read(state->i2c_fd, buffer, sizeof(buffer));
    if (bytes_read != sizeof(buffer)) {
        fprintf(stderr, "I2C read error: %s\n", strerror(errno));
        close_i2c(state);
        sleep(RECONNECT_DELAY);
        init_i2c(state);
        return;
    }

    // Extract 14-bit flow value (bits 15-2) and 12-bit temperature value (bits 11-0)
    uint16_t flow_raw = (buffer[0] << 8) | buffer[1];
    uint16_t temp_raw = (buffer[2] << 8) | buffer[3];

    // Handle overflow for flow (14-bit signed)
    if (flow_raw > 0x3FFF) {
        flow_raw -= 0x4000;
    }

    // Convert to SLPM (assuming 1 LSB = 0.01 SLPM)
    double flow_slpm = (double)flow_raw * 0.01;

    // Convert temperature (12-bit signed)
    if (temp_raw > 0x7FF) {
        temp_raw -= 0x1000;
    }

    // Convert to Celsius (assuming 1 LSB = 0.0625 °C)
    double temperature_c = (double)temp_raw * 0.0625;

    log_measurement(flow_slpm, temperature_c, time(NULL));
}

int main() {
    app_state state = { .i2c_fd = -1, .log_file = NULL, .running = 1 };

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    init_i2c(&state);

    state.log_file = fopen(LOG_FILE, "a");
    if (!state.log_file) {
        perror("Failed to open log file");
        close_i2c(&state);
        exit(EXIT_FAILURE);
    }

    // Skip first two reads after power-up
    for (int i = 0; i < 2 && state.running; i++) {
        read_sensor_data(&state);
        sleep(1);
    }

    while (state.running) {
        read_sensor_data(&state);
        sleep(SAMPLE_INTERVAL);
    }

    close_i2c(&state);
    close_log(&state);

    return 0;
}

