#define CHECKSUM_OFFSET 4
#define HUMIDITY_OFFSET 0
#define TEMPERATURE_OFFSET 2

typedef enum {
    DHT11_OK,
    DHT11_TIMEOUT_START,
    DHT11_TIMEOUT_RESPONSE,
    DHT11_TIMEOUT_DATA_BIT,
    DHT11_CHECKSUM_FAILURE,
    DHT11_SENSOR_ABSENT
} DHT11_STATUS;

typedef struct {
    int humidity;
    int temperature;
    time_t timestamp;
} DHT11_READING;

void handle_signal(int signal) {
    exit(EXIT_SUCCESS);
}

int gpio_set_direction(gpiod_line *line, int direction) {
    int ret;
    if (direction == 0) {
        ret = gpiod_line_set_direction(line, "out");
    } else {
        ret = gpiod_line_set_direction(line, "in");
    }
    if (ret < 0) {
        fprintf(stderr, "Failed to set GPIO direction: %s\n", gpiod_strerror(ret));
        return -1;
    }
    return 0;
}

int gpio_set_value(gpiod_line *line, int value) {
    int ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        fprintf(stderr, "Failed to set GPIO value: %s\n", gpiod_strerror(ret));
        return -1;
    }
    return 0;
}

int gpio_get_value(gpiod_line *line) {
    int value;
    int ret = gpiod_line_get_value(line, &value);
    if (ret < 0) {
        fprintf(stderr, "Failed to get GPIO value: %s\n", gpiod_strerror(ret));
        return -1;
    }
    return value;
}

int wait_for_gpio_low(gpiod_line *line, int timeout_us) {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    ts.tv_nsec += timeout_us * 1000;
    if (ts.tv_nsec >= 1000000000) {
        ts.tv_sec++;
        ts.tv_nsec -= 1000000000;
    }

    while (1) {
        int value = gpio_get_value(line);
        if (value == 0) {
            return 0;
        }
        if (clock_gettime(CLOCK_MONOTONIC, &ts) < 0) {
            fprintf(stderr, "Failed to get time: %s\n", strerror(errno));
            return -1;
        }
        if (ts.tv_nsec >= 1000000000) {
            ts.tv_sec++;
            ts.tv_nsec -= 1000000000;
        }
        if (ts.tv_sec > 0) {
            return -1;
        }
    }
}

int wait_for_gpio_high(gpiod_line *line, int timeout_us) {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    ts.tv_nsec += timeout_us * 1000;
    if (ts.tv_nsec >= 1000000000) {
        ts.tv_sec++;
        ts.tv_nsec -= 1000000000;
    }

    while (1) {
        int value = gpio_get_value(line);
        if (value == 1) {
            return 0;
        }
        if (clock_gettime(CLOCK_MONOTONIC, &ts) < 0) {
            fprintf(stderr, "Failed to get time: %s\n", strerror(errno));
            return -1;
        }
        if (ts.tv_nsec >= 1000000000) {
            ts.tv_sec++;
            ts.tv_nsec -= 1000000000;
        }
        if (ts.tv_sec > 0) {
            return -1;
        }
    }
}

int read_dht11(gpiod_line *line, int *data) {
    int ret;
    int i;
    int checksum;
    int received_data[4];
    int timeout = 0;

    // Set line as output
    ret = gpio_set_direction(line, 0);
    if (ret < 0) {
        return DHT11_SENSOR_ABSENT;
    }

    // Send start signal
    ret = gpio_set_value(line, 0);
    if (ret < 0) {
        return DHT11_SENSOR_ABSENT;
    }

    usleep(START_DELAY_MS * 1000);

    ret = gpio_set_value(line, 1);
    if (ret < 0) {
        return DHT11_SENSOR_ABSENT;
    }

    // Wait for response
    ret = wait_for_gpio_low(line, 1000000);
    if (ret < 0) {
        return DHT11_TIMEOUT_START;
    }

    ret = wait_for_gpio_high(line, 100000);
    if (ret < 0) {
        return DHT11_TIMEOUT_RESPONSE;
    }

    // Set line as input
    ret = gpio_set_direction(line, 1);
    if (ret < 0) {
        return DHT11_SENSOR_ABSENT;
    }

    // Read data
    for (i = 0; i < 40; i++) {
        ret = wait_for_gpio_low(line, 100000);
        if (ret < 0) {
            return DHT11_TIMEOUT_DATA_BIT;
        }

        usleep(DATA_BIT_SAMPLE_DELAY_US);

        if (wait_for_gpio_high(line, 100000) < 0) {
            return DHT11_TIMEOUT_DATA_BIT;
        }

        if (clock_gettime(CLOCK_MONOTONIC, &ts) < 0) {
            fprintf(stderr, "Failed to get time: %s\n", strerror(errno));
            return DHT11_TIMEOUT_DATA_BIT;
        }

        if (ts.tv_nsec >= 1000000000) {
            ts.tv_sec++;
            ts.tv_nsec -= 1000000000;
        }

        if (ts.tv_sec > 0) {
            return DHT11_TIMEOUT_DATA_BIT;
        }

        if (gpio_get_value(line) == 1) {
            received_data[i / 8] |= (1 << (7 - (i % 8)));
        }
    }

    checksum = received_data[0] + received_data[1] + received_data[2];
    if (received_data[3] != checksum) {
        return DHT11_CHECKSUM_FAILURE;
    }

    *data = received_data[0] * 10 + received_data[1];
    return DHT11_OK;
}

void log_error(FILE *file, DHT11_STATUS status) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm);

    switch (status) {
        case DHT11_TIMEOUT_START:
            fprintf(file, "%s - DHT11_TIMEOUT_START\n", timestamp);
            break;
        case DHT11_TIMEOUT_RESPONSE:
            fprintf(file, "%s - DHT11_TIMEOUT_RESPONSE\n", timestamp);
            break;
        case DHT11_TIMEOUT_DATA_BIT:
            fprintf(file, "%s - DHT11_TIMEOUT_DATA_BIT\n", timestamp);
            break;
        case DHT11_CHECKSUM_FAILURE:
            fprintf(file, "%s - DHT11_CHECKSUM_FAILURE\n", timestamp);
            break;
        case DHT11_SENSOR_ABSENT:
            fprintf(file, "%s - DHT11_SENSOR_ABSENT\n", timestamp);
            break;
    }
}

void log_reading(FILE *file, DHT11_READING *reading) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm);

    fprintf(file, "%s - Humidity: %d, Temperature: %d\n", timestamp, reading->humidity, reading->temperature);
}

int main() {
    gpiod_line *line;
    FILE *file;
    DHT11_STATUS status;
    DHT11_READING reading;
    int data;
    int retry = 0;
    struct timespec ts;
    int ret;

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Initialize GPIO
    line = gpiod_line_get(GPIO_LINE, "both");
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line: %s\n", gpiod_strerror(errno));
        exit(EXIT_FAILURE);
    }

    // Open file
    file = fopen(FILE_NAME, "a");
    if (!file) {
        fprintf(stderr, "Failed to open file: %s\n", strerror(errno));
        gpiod_line_put(line);
        exit(EXIT_FAILURE);
    }

    while (1) {
        if (retry > MAX_RETRIES) {
            fprintf(stderr, "Max retries reached. Exiting.\n");
            break;
        }

        // Set line as output
        ret = gpio_set_direction(line, 0);
        if (ret < 0) {
            log_error(file, DHT11_SENSOR_ABSENT);
            retry++;
            continue;
        }

        // Send start signal
        ret = gpio_set_value(line, 0);
        if (ret < 0) {
            log_error(file, DHT11_SENSOR_ABSENT);
            retry++;
            continue;
        }

        usleep(START_DELAY_MS * 1000);

        ret = gpio_set_value(line, 1);
        if (ret < 0) {
            log_error(file, DHT11_SENSOR_ABSENT);
            retry++;
            continue;
        }

        // Wait for response
        ret = wait_for_gpio_low(line, 1000000);
        if (ret < 0) {
            log_error(file, DHT11_TIMEOUT_START);
            retry++;
            continue;
        }

        ret = wait_for_gpio_high(line, 100000);
        if (ret < 0) {
            log_error(file, DHT11_TIMEOUT_RESPONSE);
            retry++;
            continue;
        }

        // Set line as input
        ret = gpio_set_direction(line, 1);
        if (ret < 0) {
            log_error(file, DHT11_SENSOR_ABSENT);
            retry++;
            continue;
        }

        // Read data
        status = read_dht11(line, &data);
        if (status == DHT11_OK) {
            reading.humidity = data;
            reading.temperature = (data >> 8) & 0xFF;
            reading.timestamp = time(NULL);
            log_reading(file, &reading);
            retry = 0;
        } else {
            log_error(file, status);
            retry++;
        }

        // Wait before next reading
        usleep(MIN_INTERVAL * 1000000);
    }

    // Cleanup
    fclose(file);
    gpiod_line_put(line);
    exit(EXIT_SUCCESS);
}
