#define SHT31D_MEASURE_CMD 0x2C
#define SHT31D_REPEATED_MEASURE_CMD 0x26
#define SHT31D_CRC_POLY 0x31
#define SHT31D_CRC_INIT 0x00
#define MAX_RETRIES 3
#define LOG_FILE "sht31d_data.log"
#define LOG_INTERVAL 5
#define MEASURE_DELAY 15

typedef struct {
    int fd;
    struct gpiod_line *sda;
    struct gpiod_line *scl;
    FILE *log_file;
} sht31d_context;

void handle_signal(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        if (context.log_file) {
            fclose(context.log_file);
        }
        if (context.fd >= 0) {
            close(context.fd);
        }
        gpiod_line_release(context.sda);
        gpiod_line_release(context.scl);
        gpiod_chip_close(context.sda->chip);
        gpiod_chip_close(context.scl->chip);
        exit(EXIT_SUCCESS);
    }
}

int i2c_write(int fd, uint8_t reg, uint8_t *data, size_t len) {
    uint8_t buf[len + 1];
    buf[0] = reg;
    memcpy(buf + 1, data, len);
    if (write(fd, buf, len + 1) != len + 1) {
        return -1;
    }
    return 0;
}

int i2c_read(int fd, uint8_t reg, uint8_t *data, size_t len) {
    if (ioctl(fd, I2C_SLAVE, I2C_ADDR) < 0) {
        return -1;
    }
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    if (read(fd, data, len) != len) {
        return -1;
    }
    return 0;
}

int crc8_check(uint8_t *data, size_t len) {
    uint8_t crc = SHT31D_CRC_INIT;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ SHT31D_CRC_POLY;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc == 0;
}

void log_data(const char *timestamp, float temp, float hum) {
    fprintf(context.log_file, "%s,%f,%f\n", timestamp, temp, hum);
    fflush(context.log_file);
}

void sht31d_init(sht31d_context *ctx) {
    ctx->fd = -1;
    ctx->log_file = NULL;
    ctx->sda = NULL;
    ctx->scl = NULL;

    // Initialize I2C
    char i2c_bus_path[32];
    snprintf(i2c_bus_path, sizeof(i2c_bus_path), "/dev/i2c-%d", I2C_BUS);
    ctx->fd = open(i2c_bus_path, O_RDWR);
    if (ctx->fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    // Initialize GPIO for I2C
    struct gpiod_chip *chip;
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    ctx->sda = gpiod_line_get(chip, 2);
    if (!ctx->sda) {
        perror("Failed to get SDA line");
        exit(EXIT_FAILURE);
    }

    ctx->scl = gpiod_line_get(chip, 3);
    if (!ctx->scl) {
        perror("Failed to get SCL line");
        exit(EXIT_FAILURE);
    }

    gpiod_line_request_output(ctx->sda, "sht31d_sda", 0);
    gpiod_line_request_output(ctx->scl, "sht31d_scl", 0);

    // Initialize log file
    ctx->log_file = fopen(LOG_FILE, "a");
    if (!ctx->log_file) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }

    // Set up signal handler
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);
}

void sht31d_measure(sht31d_context *ctx) {
    uint8_t cmd = SHT31D_REPEATED_MEASURE_CMD;
    uint8_t data[6];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (i2c_write(ctx->fd, SHT31D_MEASURE_CMD, &cmd, 1) < 0) {
            fprintf(stderr, "I2C write failed\n");
            retries++;
            continue;
        }

        usleep(MEASURE_DELAY * 1000);

        if (i2c_read(ctx->fd, SHT31D_MEASURE_CMD, data, 6) < 0) {
            fprintf(stderr, "I2C read failed\n");
            retries++;
            continue;
        }

        if (crc8_check(data, 6)) {
            float temp = (data[0] << 8 | data[1]) * 17.0 / 65536.0 - 45.0;
            float hum = (data[3] << 8 | data[4]) * 100.0 / 65536.0;
            char timestamp[30];
            time_t now = time(NULL);
            struct tm *tm = localtime(&now);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
            log_data(timestamp, temp, hum);
            return;
        } else {
            fprintf(stderr, "CRC check failed\n");
            retries++;
        }
    }

    fprintf(stderr, "Sensor failed after %d retries\n", MAX_RETRIES);
    log_data("ERROR,SENSOR_FAILURE", 0.0, 0.0);
}

int main() {
    sht31d_context context;
    sht31d_init(&context);

    while (1) {
        sht31d_measure(&context);
        sleep(LOG_INTERVAL);
    }

    return 0;
}

