#include <time.h>

#define I2C_BUS "/dev/i2c-1"
#define LM75B_ADDR 0x48
#define BUFFER_SIZE 60
#define FAN_PIN 18
#define TEMP_THRESHOLD_ON 28.0
#define TEMP_THRESHOLD_OFF 26.0
#define SAMPLE_INTERVAL 1

typedef struct {
    double temps[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

void init_buffer(CircularBuffer *buffer) {
    buffer->head = 0;
    buffer->count = 0;
    for (int i = 0; i < BUFFER_SIZE; i++) {
        buffer->temps[i] = 0.0;
    }
}

double get_average(CircularBuffer *buffer) {
    double sum = 0.0;
    for (int i = 0; i < buffer->count; i++) {
        sum += buffer->temps[i];
    }
    return sum / buffer->count;
}

void update_buffer(CircularBuffer *buffer, double temp) {
    buffer->temps[buffer->head] = temp;
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    buffer->count = (buffer->count < BUFFER_SIZE) ? buffer->count + 1 : BUFFER_SIZE;
}

int i2c_read_temp(int fd, int addr, double *temp) {
    char buf[2];
    int ret;

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Failed to set I2C slave address");
        return -1;
    }

    if (read(fd, buf, 2) != 2) {
        perror("Failed to read from I2C device");
        return -1;
    }

    *temp = (buf[0] << 8 | buf[1]) * 0.0625;
    return 0;
}

void handle_signal(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        printf("Received signal, cleaning up...\n");
        exit(0);
    }
}

