#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <errno.h>

#define I2C_BUS 1
#define I2C_ADDR 0x30
#define LED_PIN 17
#define TEMP_THRESHOLD_HIGH 28.0
#define TEMP_THRESHOLD_LOW 27.0
#define I2C_RETRY_COUNT 3

typedef struct {
    int i2c_fd;
    struct gpiod_line *led_line;
    int running;
} app_state;

void handle_signal(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        app_state *state = (app_state *)malloc(sizeof(app_state));
        if (state) {
            state->running = 0;
        }
    }
}

void log_error(const char *msg, int err) {
    fprintf(stderr, "%s: %s\n", msg, strerror(err));
}

void close_i2c(int *fd) {
    if (*fd >= 0) {
        close(*fd);
        *fd = -1;
    }
}

void close_gpio(struct gpiod_line **line) {
    if (*line) {
        gpiod_line_release(*line);
        *line = NULL;
    }
}

void cleanup(app_state *state) {
    close_i2c(&state->i2c_fd);
    close_gpio(&state->led_line);
    free(state);
}

int open_i2c(int bus, int addr) {
    char filename[20];
    snprintf(filename, sizeof(filename), "/dev/i2c-%d", bus);
    int fd = open(filename, O_RDWR);
    if (fd < 0) {
        log_error("Failed to open I2C bus", errno);
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        log_error("Failed to set I2C slave address", errno);
        close(fd);
        return -1;
    }

    return fd;
}

int read_temperature(int fd) {
    unsigned char reg = 0x00; // Temperature register
    unsigned char buf[2];

    if (write(fd, &reg, 1) < 0) {
        log_error("I2C write failed", errno);
        return -1;
    }

    usleep(1000); // Wait for conversion

    if (read(fd, buf, 2) < 0) {
        log_error("I2C read failed", errno);
        return -1;
    }

    int temp = (buf[0] << 8) | buf[1];
    double celsius = (double)temp / 256.0;

    return celsius;
}

void set_led_state(struct gpiod_line *line, int state) {
    if (gpiod_line_set_value(line, state) < 0) {
        log_error("Failed to set LED state", errno);
    }
}

int main() {
    app_state state = {0};

    // Set up signal handling
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Initialize GPIO
    struct gpiod_chip *chip = gpiod_chip_open("/dev/gpiochip4");
    if (!chip) {
        log_error("Failed to open GPIO chip", errno);
        return 1;
    }

    state.led_line = gpiod_line_get(chip, LED_PIN, "gpio");
    if (!state.led_line) {
        log_error("Failed to get LED line", errno);
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_output(state.led_line, "temperature_led", 0, GPIOD_LINE_REQUEST_FLAG_ACTIVE_LOW) < 0) {
        log_error("Failed to request LED line", errno);
        gpiod_line_release(state.led_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Initialize I2C
    state.i2c_fd = open_i2c(I2C_BUS, I2C_ADDR);
    if (state.i2c_fd < 0) {
        gpiod_line_release(state.led_line);
        gpiod_chip_close(chip);
        return 1;
    }

    state.running = 1;
    double last_temp = 0.0;
    int led_state = 0;

    while (state.running) {
        int retries = 0;
        double temp = 0.0;
        while (retries < I2C_RETRY_COUNT) {
            temp = read_temperature(state.i2c_fd);
            if (temp >= 0) {
                break;
            }
            retries++;
            usleep(100000); // 100ms delay
        }

        if (retries >= I2C_RETRY_COUNT) {
            log_error("I2C read failed after retries", errno);
            cleanup(&state);
            return 1;
        }

        if (temp > TEMP_THRESHOLD_HIGH) {
            if (led_state != 1) {
                set_led_state(state.led_line, 1);
                led_state = 1;
            }
        } else if (temp < TEMP_THRESHOLD_LOW) {
            if (led_state != 0) {
                set_led_state(state.led_line, 0);
                led_state = 0;
            }
        }

        printf("Temperature: %.2f°C\n", temp);
        fflush(stdout);

        usleep(1000000); // 1 second delay
    }

    cleanup(&state);
    return 0;
}

