// CRC8 calculation function
unsigned char crc8(const unsigned char *data, size_t len) {
    unsigned char crc = CRC8_INIT;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLY;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Check if the CRC is valid
int validate_crc(const unsigned char *data, size_t len, unsigned char expected_crc) {
    unsigned char calculated_crc = crc8(data, len - 1);
    return calculated_crc == expected_crc;
}

// Read data from I2C device
int i2c_read(int fd, unsigned char reg, unsigned char *buf, size_t len) {
    unsigned char buffer[1 + len];
    buffer[0] = reg;
    if (ioctl(fd, I2C_RDWR, &buffer) < 0) {
        perror("i2c_read: ioctl");
        return -1;
    }
    return 0;
}

// Write data to I2C device
int i2c_write(int fd, unsigned char reg, const unsigned char *buf, size_t len) {
    unsigned char buffer[1 + len];
    buffer[0] = reg;
    memcpy(buffer + 1, buf, len);
    if (ioctl(fd, I2C_RDWR, &buffer) < 0) {
        perror("i2c_write: ioctl");
        return -1;
    }
    return 0;
}

// Initialize I2C device
int i2c_init() {
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, SENSOR_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// Clean up I2C device
void i2c_cleanup(int fd) {
    if (fd >= 0) {
        close(fd);
    }
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
