    int i2c_fd = -1;
    FILE *file = NULL;
    unsigned char buffer[9];
    time_t timestamp;
    int pressure, temperature;
    unsigned char pressure_crc, temperature_crc;
    unsigned char scale_factors[3];
    int result;

    // Set up signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    i2c_fd = i2c_init();
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to initialize I2C\n");
        return EXIT_FAILURE;
    }

    // Open log file
    file = fopen("flow_data.txt", "a");
    if (!file) {
        perror("Failed to open log file");
        i2c_cleanup(i2c_fd);
        return EXIT_FAILURE;
    }

    // Soft reset the sensor
    result = i2c_write(i2c_fd, CMD_SOFT_RESET, NULL, 0);
    if (result < 0) {
        fprintf(stderr, "Failed to send soft reset command\n");
        fclose(file);
        i2c_cleanup(i2c_fd);
        return EXIT_FAILURE;
    }

    // Wait for sensor to stabilize
    usleep(100000);

    // Read scale factors
    result = i2c_write(i2c_fd, CMD_GET_SCALE_FACTORS, NULL, 0);
    if (result < 0) {
        fprintf(stderr, "Failed to send get scale factors command\n");
        fclose(file);
        i2c_cleanup(i2c_fd);
        return EXIT_FAILURE;
    }

    usleep(100000);

    // Read scale factors
    result = i2c_read(i2c_fd, CMD_READ, buffer, 9);
    if (result < 0) {
        fprintf(stderr, "Failed to read scale factors\n");
        fclose(file);
        i2c_cleanup(i2c_fd);
        return EXIT_FAILURE;
    }

    // Extract scale factors
    memcpy(scale_factors, buffer, 3);

    // Wait for measurement to complete
    usleep(45000);

    // Start measurement
    result = i2c_write(i2c_fd, CMD_MEASURE, NULL, 0);
    if (result < 0) {
        fprintf(stderr, "Failed to start measurement\n");
        fclose(file);
        i2c_cleanup(i2c_fd);
        return EXIT_FAILURE;
    }

    // Wait for measurement to complete
    usleep(45000);

    // Read measurement data
    result = i2c_read(i2c_fd, CMD_READ, buffer, 9);
    if (result < 0) {
        fprintf(stderr, "Failed to read measurement data\n");
        fclose(file);
        i2c_cleanup(i2c_fd);
        return EXIT_FAILURE;
    }

    // Extract pressure data
    pressure = (buffer[0] << 8) | buffer[1];
    pressure_crc = buffer[2];

    // Extract temperature data
    temperature = (buffer[3] << 8) | buffer[4];
    temperature_crc = buffer[5];

    // Validate CRCs
    if (!validate_crc(buffer, 3, pressure_crc)) {
        fprintf(stderr, "Pressure CRC validation failed\n");
    }

    if (!validate_crc(buffer + 3, 3, temperature_crc)) {
        fprintf(stderr, "Temperature CRC validation failed\n");
    }

    // Log data
    timestamp = time(NULL);
    log_data(file, timestamp, pressure, pressure_crc, temperature, temperature_crc, scale_factors);

    // Close resources
    fclose(file);
    i2c_cleanup(i2c_fd);

    return EXIT_SUCCESS;
}

