#define I2C_BUS 1
#define I2C_ADDR 0x40
#define MAX_RETRIES 3
#define LOG_FILE "environment.log"
#define CMD_RH_NO_HOLD 0xE5
#define CMD_TEMP_NO_HOLD 0xE6
#define CMD_TEMP_PREV_RH 0xE7
#define CMD_EID 0xFE
#define CMD_FIRMWARE 0x81

typedef struct {
    int i2c_fd;
    FILE *log_file;
    int running;
} app_state;

void handle_signal(int sig) {
    app_state *state = (app_state *)malloc(sizeof(app_state));
    state->running = 0;
    free(state);
}

void log_message(const char *fmt, ...) {
    va_list args;
    char buffer[1024];
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", tm);

    va_start(args, fmt);
    vsnprintf(buffer + strlen(buffer) + 1, sizeof(buffer) - strlen(buffer) - 1, fmt, args);
    va_end(args);

    fprintf(stderr, "%s\n", buffer);
    fflush(stderr);
}

void log_to_file(const char *fmt, ...) {
    va_list args;
    char buffer[1024];
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", tm);

    va_start(args, fmt);
    vsnprintf(buffer + strlen(buffer) + 1, sizeof(buffer) - strlen(buffer) - 1, fmt, args);
    va_end(args);

    fprintf(stdout, "%s\n", buffer);
    fprintf(log_file, "%s\n", buffer);
    fflush(log_file);
    fflush(stdout);
}

int i2c_read(int fd, uint8_t cmd, uint8_t *data, size_t len) {
    int retries = 0;
    int result;

    while (retries < MAX_RETRIES) {
        result = ioctl(fd, I2C_SLAVE, I2C_ADDR);
        if (result < 0) {
            log_message("Failed to set I2C slave address: %s", strerror(errno));
            return -1;
        }

        if (write(fd, &cmd, 1) != 1) {
            log_message("I2C write failed: %s", strerror(errno));
            retries++;
            continue;
        }

        usleep(1000); // Wait for the sensor to process the command

        if (read(fd, data, len) != len) {
            log_message("I2C read failed: %s", strerror(errno));
            retries++;
            continue;
        }

        return 0;
    }

    log_message("I2C transaction failed after %d retries", MAX_RETRIES);
    return -1;
}

void check_sensor_presence(int fd) {
    uint8_t eid;
    if (i2c_read(fd, CMD_EID, &eid, 1) < 0) {
        log_message("Failed to read sensor electronic ID");
        log_to_file("Sensor not found. Electronic ID read failed.");
        exit(EXIT_FAILURE);
    }

    if (eid != 0x15) {
        log_message("Invalid sensor electronic ID: 0x%02X", eid);
        log_to_file("Sensor not found. Invalid electronic ID.");
        exit(EXIT_FAILURE);
    }

    uint8_t fw;
    if (i2c_read(fd, CMD_FIRMWARE, &fw, 1) < 0) {
        log_message("Failed to read firmware revision");
        log_to_file("Sensor not found. Firmware revision read failed.");
        exit(EXIT_FAILURE);
    }

    log_to_file("Sensor found. Electronic ID: 0x%02X, Firmware: 0x%02X", eid, fw);
}

void measure_and_log() {
    uint8_t data[3];
    int result;

    // Measure relative humidity, no hold
    result = i2c_read(app_state.i2c_fd, CMD_RH_NO_HOLD, data, 3);
    if (result < 0) {
        log_message("Failed to measure humidity");
        log_to_file("Failed to measure humidity");
        return;
    }

    uint16_t rh = (data[0] << 8) | data[1];
    double humidity = (double)rh / 65536.0 * 100.0;

    // Measure temperature from previous RH measurement
    result = i2c_read(app_state.i2c_fd, CMD_TEMP_PREV_RH, data, 3);
    if (result < 0) {
        log_message("Failed to measure temperature");
        log_to_file("Failed to measure temperature");
        return;
    }

    uint16_t temp = (data[0] << 8) | data[1];
    double temperature = (double)temp / 65536.0 * 175.72 - 46.85;

    log_to_file("%s,%.2f,%.2f", time_str, temperature, humidity);
}

int main() {
    app_state state;
    int i2c_fd;
    char time_str[30];

    // Initialize signal handling
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Open I2C bus
    char i2c_bus_path[32];
    snprintf(i2c_bus_path, sizeof(i2c_bus_path), "/dev/i2c-%d", I2C_BUS);
    i2c_fd = open(i2c_bus_path, O_RDWR);
    if (i2c_fd < 0) {
        log_message("Failed to open I2C bus: %s", strerror(errno));
        log_to_file("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    // Check sensor presence
    check_sensor_presence(i2c_fd);

    // Open log file
    state.log_file = fopen(LOG_FILE, "a");
    if (!state.log_file) {
        log_message("Failed to open log file: %s", strerror(errno));
        log_to_file("Failed to open log file");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Initialize state
    state.i2c_fd = i2c_fd;
    state.running = 1;

    // Main loop
    while (state.running) {
        time_t now = time(NULL);
        struct tm *tm = localtime(&now);
        strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm);

        measure_and_log();

        // Wait 60 seconds
        sleep(60);
    }

    // Cleanup
    fclose(state.log_file);
    close(state.i2c_fd);
    log_message("Application exited normally.");
    log_to_file("Application exited normally.");
    return 0;
}

