#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <gpiod.h>

#define I2C_BUS "/dev/i2c-1"
#define HDC1080_ADDR 0x40
#define HDC1080_CONFIG 0x02
#define HDC1080_HUMIDITY 0x01
#define HDC1080_TEMPERATURE 0x00

typedef struct {
    int fd;
    struct gpiod_line *reset_line;
} hdc1080_dev;

void handle_signal(int sig) {
    (void)sig;
    exit(EXIT_SUCCESS);
}

int init_hdc1080(hdc1080_dev *dev) {
    dev->fd = open(I2C_BUS, O_RDWR);
    if (dev->fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    if (ioctl(dev->fd, I2C_SLAVE, HDC1080_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(dev->fd);
        return -1;
    }

    // Initialize GPIO for reset (optional, depends on hardware setup)
    dev->reset_line = gpiod_line_get("gpiochip4", 27, "hdc1080_reset");
    if (!dev->reset_line) {
        perror("Failed to get GPIO line for reset");
        close(dev->fd);
        return -1;
    }

    if (gpiod_line_set_value(dev->reset_line, 0) < 0) {
        perror("Failed to set GPIO line to low");
        gpiod_line_put(dev->reset_line);
        close(dev->fd);
        return -1;
    }

    usleep(10000); // 10ms
    if (gpiod_line_set_value(dev->reset_line, 1) < 0) {
        perror("Failed to set GPIO line to high");
        gpiod_line_put(dev->reset_line);
        close(dev->fd);
        return -1;
    }

    usleep(10000); // 10ms

    // Configure sensor
    uint16_t config = 0x0000; // Default configuration: 14-bit temp, 12-bit humidity, 1x OSR
    if (write(dev->fd, &config, sizeof(config)) != sizeof(config)) {
        perror("Failed to write configuration register");
        gpiod_line_put(dev->reset_line);
        close(dev->fd);
        return -1;
    }

    return 0;
}

void deinit_hdc1080(hdc1080_dev *dev) {
    if (dev->reset_line) {
        gpiod_line_put(dev->reset_line);
    }
    close(dev->fd);
}

int read_hdc1080(hdc1080_dev *dev, float *temp, float *humidity) {
    // Wait for conversion to complete
    usleep(20000); // 20ms

    // Read humidity
    if (write(dev->fd, &HDC1080_HUMIDITY, sizeof(HDC1080_HUMIDITY)) != sizeof(HDC1080_HUMIDITY)) {
        return -1;
    }

    uint16_t humidity_data;
    if (read(dev->fd, &humidity_data, sizeof(humidity_data)) != sizeof(humidity_data)) {
        return -1;
    }

    *humidity = (float)humidity_data * 0.0405f - 4.094f;

    // Read temperature
    if (write(dev->fd, &HDC1080_TEMPERATURE, sizeof(HDC1080_TEMPERATURE)) != sizeof(HDC1080_TEMPERATURE)) {
        return -1;
    }

    uint16_t temp_data;
    if (read(dev->fd, &temp_data, sizeof(temp_data)) != sizeof(temp_data)) {
        return -1;
    }

    *temp = (float)temp_data * 0.00198f - 46.85f;

    return 0;
}

int main() {
    hdc1080_dev hdc_dev;
    float temperature = 0.0f;
    float humidity = 0.0f;
    FILE *log_file = NULL;
    struct timespec ts;
    int log_interval = 5; // seconds
    int last_log_time = 0;

    // Set up signal handling
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if (init_hdc1080(&hdc_dev) < 0) {
        fprintf(stderr, "Failed to initialize HDC1080 sensor\n");
        return EXIT_FAILURE;
    }

    log_file = fopen("enviro_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        deinit_hdc1080(&hdc_dev);
        return EXIT_FAILURE;
    }

    while (1) {
        // Check if it's time to log
        clock_gettime(CLOCK_MONOTONIC, &ts);
        if (ts.tv_sec - last_log_time >= log_interval) {
            if (read_hdc1080(&hdc_dev, &temperature, &humidity) == 0) {
                char timestamp[30];
                struct tm *tm_info;
                time_t now = time(NULL);
                tm_info = localtime(&now);
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

                fprintf(log_file, "%s,%f,%f\n", timestamp, temperature, humidity);
                fflush(log_file);
                last_log_time = ts.tv_sec;
            } else {
                // Skip log entry on I2C error
                fprintf(stderr, "I2C communication error, skipping log entry\n");
            }
        }

        // Sleep for 1 second to reduce CPU usage
        usleep(100000);
    }

    // Clean up
    fclose(log_file);
    deinit_hdc1080(&hdc_dev);
    return EXIT_SUCCESS;
}

