#define CRC_POLY 0x31
#define CRC_INIT 0xFF
#define CRC_DATA_SIZE 2
#define CRC_BYTE 3
#define SAMPLE_INTERVAL 5000
#define READ_DELAY 10000

typedef struct {
    int fd;
    FILE *log_file;
    int running;
} app_state;

// CRC8 calculation using Sensirion polynomial
unsigned char crc8(const unsigned char *data, size_t len) {
    unsigned char crc = CRC_INIT;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLY;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Write command to the sensor
void write_command(int fd, unsigned char cmd) {
    unsigned char buffer[1];
    buffer[0] = cmd;
    if (write(fd, buffer, 1) != 1) {
        fprintf(stderr, "Error writing command to sensor\n");
    }
}

// Read data from the sensor
int read_data(int fd, unsigned char *data) {
    if (read(fd, data, 3) != 3) {
        fprintf(stderr, "Error reading data from sensor\n");
        return -1;
    }
    return 0;
}

// Check CRC8
int check_crc(const unsigned char *data) {
    unsigned char calculated_crc = crc8(data, CRC_DATA_SIZE);
    if (data[CRC_BYTE] != calculated_crc) {
        fprintf(stderr, "CRC8 mismatch\n");
        return -1;
    }
    return 0;
}

// Convert 16-bit data to temperature in Celsius
float convert_to_celsius(const unsigned char *data) {
    unsigned short raw = (data[0] << 8) | data[1];
    return (float)raw / 16.0f;
}

// Signal handler
void handle_signal(int signum) {
    app_state *state = (app_state *)malloc(sizeof(app_state));
    if (state) {
        state->running = 0;
        if (state->fd != -1) {
            close(state->fd);
        }
        if (state->log_file) {
            fclose(state->log_file);
        }
        free(state);
    }
    exit(EXIT_SUCCESS);
}

