    app_state state = {0};
    state.running = 1;

    // Set up signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Open I2C device
    state.fd = open(I2C_BUS, O_RDWR);
    if (state.fd < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        return 1;
    }

    // Set slave address
    if (ioctl(state.fd, I2C_SLAVE, SENSOR_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address: %s\n", strerror(errno));
        close(state.fd);
        return 1;
    }

    // Open log file
    state.log_file = fopen("temperature_log.txt", "a");
    if (!state.log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        close(state.fd);
        return 1;
    }

    // Main loop
    while (state.running) {
        // Trigger measurement
        write_command(state.fd, 0x24); // Start measurement command

        // Wait for conversion to complete
        usleep(READ_DELAY);

        // Read data
        unsigned char data[3];
        if (read_data(state.fd, data) < 0) {
            continue;
        }

        // Check CRC
        if (check_crc(data) < 0) {
            continue;
        }

        // Convert to Celsius
        float temp = convert_to_celsius(data);

        // Get current time
        time_t now = time(NULL);
        struct tm *timeinfo = localtime(&now);
        char timestamp[64];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

        // Log the reading
        fprintf(state.log_file, "%s,%.2f\n", timestamp, temp);
        fflush(state.log_file);

        // Wait for next sample
        usleep(SAMPLE_INTERVAL * 1000);
    }

    // Clean up
    if (state.fd != -1) {
        close(state.fd);
    }
    if (state.log_file) {
        fclose(state.log_file);
    }

    return 0;
}

