uint8_t crc8(const uint8_t *data, size_t len) {
    uint8_t crc = CRC8_INIT;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLY;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// I2C write function with error checking
int i2c_write(int fd, uint8_t reg, const uint8_t *data, size_t len) {
    if (ioctl(fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        return -1;
    }

    uint8_t buffer[len + 1];
    buffer[0] = reg;
    memcpy(buffer + 1, data, len);

    if (write(fd, buffer, len + 1) != len + 1) {
        perror("I2C write failed");
        return -1;
    }

    return 0;
}

// I2C read function with error checking
int i2c_read(int fd, uint8_t reg, uint8_t *data, size_t len) {
    if (ioctl(fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        return -1;
    }

    if (write(fd, &reg, 1) != 1) {
        perror("I2C write failed");
        return -1;
    }

    if (read(fd, data, len) != len) {
        perror("I2C read failed");
        return -1;
    }

    return 0;
}

