        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Initialize log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Initialize gpiod for GPIO (if needed)
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (chip == NULL) {
        perror("Failed to open GPIO chip");
        fclose(log_file);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Initialize sensor
    uint8_t init_cmd[] = {0x01, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00};
    if (i2c_write(i2c_fd, 0x00, init_cmd, sizeof(init_cmd)) < 0) {
        fprintf(stderr, "Failed to initialize sensor\n");
        fclose(log_file);
        close(i2c_fd);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Main loop
    while (1) {
        // Trigger measurement
        if (i2c_write(i2c_fd, 0x01, NULL, 0) < 0) {
            fprintf(stderr, "Failed to trigger measurement\n");
            continue;
        }

        // Wait for at least 50ms
        usleep(50000);

        // Read data
        if (i2c_read(i2c_fd, 0x00, buffer, sizeof(buffer)) < 0) {
            fprintf(stderr, "I2C read failed\n");
            continue;
