        fprintf(log_file, "%ld,%d,%d\n", timestamp, data.pressure, data.temperature);
        fflush(log_file);

        // Sleep for 1 second
        usleep(MEASUREMENT_INTERVAL_MS * 1000);
    }

    // Should not reach here, but handle cleanup
    fclose(log_file);
    close(i2c_fd);
    gpiod_chip_close(chip);
    return EXIT_SUCCESS;
