#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define I2C_BUS "/dev/i2c-1"
#define SDP810_I2C_ADDR 0x40
#define SDP810_COMMAND_MEASURE 0x20
#define SDP810_MEASUREMENT_SIZE 9
#define CRC8_POLY 0x07
#define CRC8_INIT 0x00

typedef struct {
    uint16_t pressure;
    uint16_t pressure_crc;
    uint16_t temperature;
    uint16_t temperature_crc;
    uint16_t scale_factor;
    uint16_t scale_factor_crc;
} sdp810_measurement_t;

// CRC-8 calculation
uint8_t crc8(const uint8_t *data, size_t len) {
    uint8_t crc = CRC8_INIT;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLY;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Check if CRC matches
int validate_crc(const uint8_t *data, size_t len, uint8_t expected_crc) {
    uint8_t calculated_crc = crc8(data, len);
    return calculated_crc == expected_crc;
}

// Read measurement from SDP810
int read_sdp810(int fd) {
    uint8_t cmd[1] = {SDP810_COMMAND_MEASURE};
    if (write(fd, cmd, sizeof(cmd)) != sizeof(cmd)) {
        perror("I2C write error");
        return -1;
    }

    usleep(45000); // Wait 45 ms for measurement to complete

    uint8_t buffer[SDP810_MEASUREMENT_SIZE];
    if (read(fd, buffer, sizeof(buffer)) != sizeof(buffer)) {
        perror("I2C read error");
        return -1;
    }

    // Extract values
    uint16_t pressure = (buffer[0] << 8) | buffer[1];
    uint16_t pressure_crc = buffer[2];
    uint16_t temperature = (buffer[3] << 8) | buffer[4];
    uint16_t temperature_crc = buffer[5];
    uint16_t scale_factor = (buffer[6] << 8) | buffer[7];
    uint16_t scale_factor_crc = buffer[8];

    // Validate CRCs
    if (!validate_crc(buffer, 3, pressure_crc) ||
        !validate_crc(buffer + 3, 3, temperature_crc) ||
        !validate_crc(buffer + 6, 3, scale_factor_crc)) {
        fprintf(stderr, "CRC validation failed\n");
        return -1;
    }

    sdp810_measurement_t measurement = {
        .pressure = pressure,
        .pressure_crc = pressure_crc,
        .temperature = temperature,
        .temperature_crc = temperature_crc,
        .scale_factor = scale_factor,
        .scale_factor_crc = scale_factor_crc
    };

    return 0;
}

// SIGINT handler
void handle_sigint(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    // Close I2C device
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(EXIT_SUCCESS);
}

int main() {
    int i2c_fd = -1;
    FILE *log_file = NULL;
    struct sigaction sa;

    // Initialize signal handler
    sa.sa_handler = handle_sigint;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    // Open I2C device
    if ((i2c_fd = open(I2C_BUS, O_RDWR)) < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, SDP810_I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen("sdp810_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Main loop
    while (1) {
        // Read measurement
        if (read_sdp810(i2c_fd) == 0) {
            // Get current time
            struct timespec ts;
            clock_gettime(CLOCK_REALTIME, &ts);
            time_t now = ts.tv_sec;
            char timestamp[30];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

            // Log to file
            fprintf(log_file, "%s,%d,%d\n", timestamp, (int)measurement.pressure, (int)measurement.temperature);
            fflush(log_file);
        }

        // Sleep for 1 second
        usleep(1000000);
    }

    // Should not reach here, but just in case
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }

    return EXIT_SUCCESS;
}

