#include <linux/i2c-dev.h>
#include <signal.h>
#include <gpiod.h>
#include <time.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDR 0x27
#define LED_PIN 17
#define LED_DELAY_MS 500
#define WARNING_THRESHOLD_Pa 95000
#define POLLING_INTERVAL_MS 1000
#define LED_ON_TIME_MS 500
#define LED_OFF_TIME_MS 500
#define WARNING_LED_ON_TIME_MS 100
#define WARNING_LED_OFF_TIME_MS 100
#define CRC_POLY 0x131021  // CRC-16/CCITT polynomial

typedef struct {
    uint16_t pressure;
    uint16_t temperature;
    uint16_t crc;
} sensor_data_t;

// CRC-16/CCITT calculation
uint16_t calculate_crc(const uint8_t *data, size_t length) {
    uint16_t crc = 0;
    for (size_t i = 0; i < length; i++) {
        crc ^= (uint16_t)data[i] << 8;
        for (int j = 0; j < 8; j++) {
            if (crc & 0x8000) {
                crc = (crc << 1) ^ CRC_POLY;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Check if CRC is valid
int is_crc_valid(const uint8_t *data, size_t length) {
    uint16_t calculated_crc = calculate_crc(data, length - 2);
    uint16_t received_crc = (data[length - 2] << 8) | data[length - 1];
    return calculated_crc == received_crc;
}

// Read sensor data
int read_sensor_data(int fd, uint8_t *buffer) {
    if (ioctl(fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        return -1;
    }

    if (read(fd, buffer, 6) != 6) {
        perror("I2C read failed");
        return -1;
    }

    if (!is_crc_valid(buffer, 6)) {
        fprintf(stderr, "CRC check failed\n");
        return -1;
    }

    sensor_data_t *data = (sensor_data_t *)buffer;
    data->pressure = (uint16_t)(buffer[0] << 8 | buffer[1]);
    data->temperature = (uint16_t)(buffer[2] << 8 | buffer[3]);
    data->crc = (uint16_t)(buffer[4] << 8 | buffer[5]);

    return 0;
}

// LED control
void set_led_state(gpiod_line *line, int state) {
    if (state) {
        gpiod_line_set_value(line, 1);
    } else {
        gpiod_line_set_value(line, 0);
    }
}

// Signal handler
void signal_handler(int signum) {
    if (signum == SIGINT) {
        printf("\nShutting down...\n");
        // Release GPIO line
        gpiod_line_release(line);
        // Close I2C file descriptor
        close(i2c_fd);
        exit(0);
    }
}

int main() {
    int i2c_fd;
    uint8_t buffer[6];
    gpiod_line *line;
    struct gpiod_line_request_config req_config;
    struct timespec ts;
    int led_state = 0;
    int warning_state = 0;
    int last_toggle_time = 0;

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR | O_NOCTTY | O_CLOEXEC);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Initialize GPIO
    struct gpiod_chip *chip;
    chip = gpiod_chip_open("/dev/gpiochip4");
    if (!chip) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        return 1;
    }

    memset(&req_config, 0, sizeof(req_config));
    req_config.line_offset = LED_PIN;
    req_config.request_type = GPIOD_LINE_REQUEST_TYPE_OPEN_DRAIN;
    req_config.flags = GPIOD_LINE_FLAG_ACTIVE_LOW;
    req_config.consumer = "pressure_sensor_led";

    line = gpiod_line_request(chip, &req_config);
    if (!line) {
        perror("Failed to request GPIO line");
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }

    gpiod_line_set_direction(line, GPIOD_LINE_DIRECTION_OUTPUT);

    // Set up signal handler
    signal(SIGINT, signal_handler);

    while (1) {
        // Read sensor data
        if (read_sensor_data(i2c_fd, buffer) < 0) {
            fprintf(stderr, "Sensor not found or I2C error, retrying...\n");
            usleep(100000); // 100ms delay
            continue;
        }

        // Check pressure
        if (buffer[0] == 0xFF && buffer[1] == 0xFF) {
            fprintf(stderr, "Invalid pressure reading, retrying...\n");
            usleep(100000);
            continue;
        }

        // Convert pressure to Pa
        uint16_t pressure = (uint16_t)(buffer[0] << 8 | buffer[1]);
        pressure *= 25; // Convert from 0.01 hPa to Pa

        // Determine LED pattern
        if (pressure < WARNING_THRESHOLD_Pa) {
            // Warning pattern: 100ms on, 100ms off
            if (clock_gettime(CLOCK_MONOTONIC, &ts) == 0) {
                long current_time = ts.tv_nsec / 1000000;
                if (current_time - last_toggle_time >= 100) {
                    last_toggle_time = current_time;
                    set_led_state(line, !warning_state);
                    warning_state = !warning_state;
                }
            }
        } else {
            // Normal pattern: 500ms on, 500ms off
            if (clock_gettime(CLOCK_MONOTONIC, &ts) == 0) {
                long current_time = ts.tv_nsec / 1000000;
                if (current_time - last_toggle_time >= 500) {
                    last_toggle_time = current_time;
                    set_led_state(line, !led_state);
                    led_state = !led_state;
                }
            }
        }

        // Delay before next poll
        usleep(POLLING_INTERVAL_MS * 1000);
    }

    // Should not reach here, but just in case
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    close(i2c_fd);
    return 0;
}

