#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define I2C_BUS "/dev/i2c-1"
#define MLX90614_ADDR 0x5A
#define MLX90614_AMBIENT_REGISTER 0x06
#define MLX90614_OBJECT_REGISTER 0x07
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10
#define FAN_PIN 18
#define FAN_ON_THRESHOLD 30.0
#define FAN_OFF_THRESHOLD 28.0

typedef struct {
    int i2c_fd;
    struct gpiod_line *fan_line;
    int fan_state;
} sensor_data_t;

void handle_signal(int sig) {
    (void)sig;
    if (signal(sig, SIG_IGN) == SIG_ERR) {
        perror("signal");
        exit(EXIT_FAILURE);
    }
}

void close_resources(sensor_data_t *data) {
    if (data->i2c_fd >= 0) {
        close(data->i2c_fd);
    }
    if (data->fan_line) {
        gpiod_line_release(data->fan_line);
    }
    gpiod_chip_close(data->fan_line->chip);
    printf("Resources closed.\n");
}

void log_temperature(FILE *log_file, double ambient, double object) {
    time_t now = time(NULL);
    struct tm *tm_now = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_now);
    fprintf(log_file, "%s, %.2f, %.2f\n", timestamp, ambient, object);
    fflush(log_file);
}

int i2c_read_retry(int fd, uint8_t reg, uint16_t *value) {
    uint8_t buffer[2];
    int retries = 0;
    int result;

    do {
        buffer[0] = reg;
        if (ioctl(fd, I2C_SLAVE, MLX90614_ADDR) < 0) {
            perror("ioctl I2C_SLAVE");
            return -1;
        }

        if (write(fd, buffer, 1) != 1) {
            perror("write to I2C");
            return -1;
        }

        if (read(fd, buffer, 2) != 2) {
            perror("read from I2C");
            usleep(RETRY_DELAY_MS * 1000);
            retries++;
            continue;
        }

        *value = (buffer[0] << 8) | buffer[1];
        return 0;
    } while (retries < MAX_RETRIES);

    return -1;
}

double convert_temp(uint16_t raw) {
    double temp = (raw * 0.02) - 128.0;
    return temp;
}

