#define MEASUREMENT_BYTES 6
#define RETRY_COUNT 3
#define HTTP_PORT 8080
#define MAX_RETRIES 3
#define MAX_BUFFER_SIZE 1024

typedef struct {
    int i2c_fd;
    int running;
    pthread_t http_thread;
    char http_response[1024];
} app_state_t;

void handle_signal(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        printf("Received signal, shutting down...\n");
        exit(EXIT_SUCCESS);
    }
}

void i2c_init(int *fd) {
    char filename[20];
    snprintf(filename, sizeof(filename), "/dev/i2c-%d", I2C_BUS);
    *fd = open(filename, O_RDWR);
    if (*fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    if (ioctl(*fd, I2C_TEN, 0) < 0) {
        perror("Failed to set 10-bit addressing");
        close(*fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(*fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(*fd);
        exit(EXIT_FAILURE);
    }
}

void i2c_read(int fd, uint8_t *data, size_t len) {
    int retries = 0;
    while (retries < RETRY_COUNT) {
        if (read(fd, data, len) == len) {
            return;
        }
        usleep(10000); // 10 ms delay
        retries++;
    }
    fprintf(stderr, "I2C read failed after %d retries\n", RETRY_COUNT);
    exit(EXIT_FAILURE);
}

void i2c_write(int fd, uint8_t *data, size_t len) {
    int retries = 0;
    while (retries < RETRY_COUNT) {
        if (write(fd, data, len) == len) {
            return;
        }
        usleep(10000); // 10 ms delay
        retries++;
    }
    fprintf(stderr, "I2C write failed after %d retries\n", RETRY_COUNT);
    exit(EXIT_FAILURE);
}

void i2c_measure(int fd) {
    uint8_t cmd[1] = {MEASUREMENT_COMMAND};
    i2c_write(fd, cmd, 1);
    usleep(10000); // Wait at least 10 ms
    uint8_t data[MEASUREMENT_BYTES];
    i2c_read(fd, data, MEASUREMENT_BYTES);

    // Parse data
    int16_t temp = (int16_t)(data[0] << 8 | data[1]);
    int16_t hum = (int16_t)(data[3] << 8 | data[4]);

    // Convert to actual values
    double temp_c = (double)temp / 1000.0;
    double hum_percent = (double)hum / 1024.0 * 100.0;

    // Clamp humidity to 0-100%
    if (hum_percent < 0.0) hum_percent = 0.0;
    if (hum_percent > 100.0) hum_percent = 100.0;

    printf("Temperature: %.3f°C, Humidity: %.1f%%\n", temp_c, hum_percent);
}

