    CURL *curl;
    CURLcode res;

    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl = curl_easy_init();

    if (curl) {
        struct curl_slist *headers = NULL;
        headers = curl_slist_append(headers, "Content-Type: text/html");
        headers = curl_slist_append(headers, "Connection: close");

        curl_easy_setopt(curl, CURLOPT_URL, "http://localhost:8080");
        curl_easy_setopt(curl, CURLOPT_POSTFIELDS, response);
        curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);
        curl_easy_setopt(curl, CURLOPT_POST, 1L);

        res = curl_easy_perform(curl);
        if (res != CURLE_OK) {
            fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
        }

        curl_easy_cleanup(curl);
    }

    curl_global_cleanup();
}

void *http_server_thread(void *arg) {
    app_state_t *state = (app_state_t *)arg;
    char response[1024];
    time_t now;
    struct tm *tm_info;

    while (state->running) {
        time(&now);
        tm_info = localtime(&now);

        snprintf(response, sizeof(response),
                 "<html><body><h1>SHT40 Sensor Data</h1>"
                 "<p>Temperature: %.3f°C</p><p>Humidity: %.1f%%</p>"
                 "<p>Timestamp: %s</p></body></html>",
                 state->http_response[0], state->http_response[1], asctime(tm_info));

        send_http_response(response);
        usleep(1000000); // 1 second interval
    }

    return NULL;
}

void cleanup(app_state_t *state) {
    if (state->i2c_fd >= 0) {
        close(state->i2c_fd);
    }
    if (state->running) {
        pthread_cancel(state->http_thread);
        pthread_join(state->http_thread, NULL);
    }
}

int main() {
    app_state_t state = {0};
    char http_response[1024];

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    i2c_init(&state.i2c_fd);

    state.running = 1;
    pthread_create(&state.http_thread, NULL, http_server_thread, &state);

    while (state.running) {
        i2c_measure(state.i2c_fd);
        snprintf(http_response, sizeof(http_response), "%.3f,%.1f", 0.0, 0.0);
        usleep(1000000); // 1 second interval
    }

    cleanup(&state);
    return 0;
}

