#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS 1
#define TMP102_ADDR 0x48
#define CSV_FILE "temperature_log.csv"
#define INTERVAL 5
#define MAX_RETRIES 3

typedef struct {
    int fd;
    struct gpiod_line *line;
} i2c_handle;

void handle_sigint(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    // Close I2C device
    if (close(i2c_handle.fd) < 0) {
        perror("close");
    }
    // Terminate libgpiod
    gpiod_chip_close(i2c_handle.line->chip);
    exit(EXIT_SUCCESS);
}

int open_i2c_device(int bus) {
    char filename[20];
    snprintf(filename, sizeof(filename), "/dev/i2c-%d", bus);
    int fd = open(filename, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C device");
        return -1;
    }
    return fd;
}

int i2c_write(int fd, uint8_t reg) {
    uint8_t buf[1];
    buf[0] = reg;
    if (ioctl(fd, I2C_SLAVE, TMP102_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        return -1;
    }
    if (write(fd, buf, 1) < 0) {
        perror("Failed to write to I2C device");
        return -1;
    }
    return 0;
}

int i2c_read(int fd, uint8_t *data, size_t len) {
    if (ioctl(fd, I2C_SLAVE, TMP102_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        return -1;
    }
    if (read(fd, data, len) < 0) {
        perror("Failed to read from I2C device");
        return -1;
    }
    return 0;
}

int read_temperature(int fd, int *temp) {
    uint8_t reg = 0x00; // Configuration register
    if (i2c_write(fd, reg) < 0) {
        return -1;
    }
    usleep(10000); // Wait for conversion to complete

    reg = 0x01; // Temperature register
    if (i2c_write(fd, reg) < 0) {
        return -1;
    }

    uint8_t data[2];
    if (i2c_read(fd, data, 2) < 0) {
        return -1;
    }

    int16_t temp_raw = (data[0] << 8) | data[1];
    *temp = temp_raw / 2; // Convert to Celsius
    return 0;
}

void log_temperature(int temp) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);
    FILE *file = fopen(CSV_FILE, "a");
    if (file == NULL) {
        perror("Failed to open CSV file");
        return;
    }
    fprintf(file, "%s,%d.00\n", timestamp, temp);
    fclose(file);
}

