#define POLL_INTERVAL_MS 5000

volatile sig_atomic_t shutdown_flag = 0;

void signal_handler(int signum) {
    shutdown_flag = 1;
}

int open_i2c_bus(int bus) {
    char filename[20];
    snprintf(filename, sizeof(filename), "/dev/i2c-%d", bus);
    int file = open(filename, O_RDWR);
    if (file < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    int addr = HDC2010_I2C_ADDR;
    if (ioctl(file, I2C_SLAVE, addr) < 0) {
        perror("Failed to set I2C slave address");
        close(file);
        return -1;
    }

    return file;
}

int read_register(int file, uint8_t reg) {
    uint8_t buffer[1];
    buffer[0] = reg;
    if (write(file, buffer, 1) < 0) {
        perror("Failed to write to I2C register");
        return -1;
    }

    if (read(file, buffer, 1) < 0) {
        perror("Failed to read from I2C register");
        return -1;
    }

    return buffer[0];
}

int poll_measurement_config(int file) {
    int retries = 0;
    int result;
    struct pollfd pfd;
    pfd.fd = file;
    pfd.events = POLLOUT;

    while (retries < MAX_RETRIES) {
        result = poll(&pfd, 1, POLL_TIMEOUT_MS);
        if (result < 0) {
            perror("Poll failed");
            return -1;
        }

        if (result == 0) {
            fprintf(stderr, "I2C poll timeout\n");
            return -1;
        }

        uint8_t config = read_register(file, MEASUREMENT_CONFIG_REGISTER);
        if (config < 0) {
            return -1;
        }

        if ((config & MEASUREMENT_CONFIG_BIT_0) == 0) {
            return 0;
        }

        retries++;
    }

    fprintf(stderr, "Measurement configuration bit 0 not cleared after %d retries\n", MAX_RETRIES);
    return -1;
}

int read_hdc2010(int file) {
    int retries = 0;
    int result;

    while (retries < MAX_RETRIES) {
        result = poll_measurement_config(file);
        if (result == 0) {
            break;
        } else if (result < 0) {
            fprintf(stderr, "Failed to poll measurement config\n");
            return -1;
        }

        retries++;
    }

    if (retries >= MAX_RETRIES) {
        fprintf(stderr, "Exceeded maximum retries for measurement config\n");
        return -1;
    }

