    if (write(file, buffer, 0) < 0) {
        perror("Failed to write to I2C");
        return -1;
    }

    if (read(file, buffer, 3) < 0) {
        perror("Failed to read from I2C");
        return -1;
    }

    int humidity = (buffer[0] << 8) | buffer[1];
    int temperature = (buffer[2] << 8) | buffer[3];

    humidity = (humidity * 100) / 65536.0;
    temperature = (temperature * 100) / 65536.0;

    printf("Humidity: %.2f%%, Temperature: %.2f°C\n", humidity, temperature);
    return 0;
}

int main() {
    signal(SIGINT, signal_handler);

    int i2c_file = open_i2c_bus(I2C_BUS);
    if (i2c_file < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        return 1;
    }

    while (!shutdown_flag) {
        if (read_hdc2010(i2c_file) < 0) {
            fprintf(stderr, "Failed to read HDC2010 sensor\n");
            break;
        }

        usleep(5000000); // 5 seconds
    }

    close(i2c_file);
    return 0;
}

