#include <gpiod.h>

#define I2C_BUS 1
#define I2C_ADDR 0x28
#define I2C_DEVICE "/dev/i2c-%d"
#define MEASUREMENT_INTERVAL_MS 500
#define MEASUREMENT_DELAY_MS 45
#define CRC8_POLY 0x07
#define CRC8_INIT 0x00

typedef struct {
    uint16_t pressure;
    uint8_t pressure_crc;
    uint16_t temperature;
    uint8_t temperature_crc;
} sdp800_data_t;

// CRC-8 calculation using Sensirion polynomial
uint8_t calculate_crc8(const uint8_t *data, size_t length) {
    uint8_t crc = CRC8_INIT;
    for (size_t i = 0; i < length; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLY;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Check if CRC is valid
int validate_crc(const uint8_t *data, size_t length, uint8_t expected_crc) {
    uint8_t calculated_crc = calculate_crc8(data, length);
    return calculated_crc == expected_crc;
}

// I2C write function with error checking
int i2c_write(int fd, uint8_t reg, const uint8_t *data, size_t len) {
    uint8_t buffer[len + 1];
    buffer[0] = reg;
    memcpy(buffer + 1, data, len);

    if (ioctl(fd, I2C_RDWR, &buffer) < 0) {
        perror("i2c_write");
        return -1;
    }

    return 0;
}

// I2C read function with error checking
int i2c_read(int fd, uint8_t reg, uint8_t *data, size_t len) {
    if (ioctl(fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("i2c_set_slave_address");
        return -1;
    }

    if (ioctl(fd, I2C_RDWR, &reg) < 0) {
        perror("i2c_write_register");
        return -1;
    }

    if (read(fd, data, len) != len) {
        perror("i2c_read");
        return -1;
    }

    return 0;
}

// Signal handler for clean shutdown
void handle_sigint(int sig) {
    printf("\nReceived SIGINT, shutting down...\n");
    exit(EXIT_SUCCESS);
}

int main() {
    int i2c_fd;
    char i2c_device[32];
    snprintf(i2c_device, sizeof(i2c_device), I2C_DEVICE, I2C_BUS);

    // Open I2C bus
    i2c_fd = open(i2c_device, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    // Set I2C address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Register signal handler
    signal(SIGINT, handle_sigint);

    uint8_t cmd[2] = {0x28, 0x00}; // Start measurement command
    uint8_t rx_data[6]; // 2 bytes pressure, 1 CRC, 2 bytes temperature, 1 CRC

    while (1) {
        // Start measurement
        if (i2c_write(i2c_fd, 0x28, cmd, sizeof(cmd)) < 0) {
            fprintf(stderr, "Failed to start measurement\n");
            break;
        }

        // Wait for measurement to complete
        usleep(MEASUREMENT_DELAY_MS * 1000);

        // Read measurement data
        if (i2c_read(i2c_fd, 0x00, rx_data, sizeof(rx_data)) < 0) {
            fprintf(stderr, "Failed to read measurement data\n");
            break;
        }

        // Validate CRCs
        if (!validate_crc(rx_data, 2, rx_data[2]) ||
            !validate_crc(rx_data + 3, 2, rx_data[5])) {
            fprintf(stderr, "CRC check failed\n");
            continue;
        }

        // Extract and log data
        sdp800_data_t data;
        data.pressure = (rx_data[0] << 8) | rx_data[1];
        data.temperature = (rx_data[3] << 8) | rx_data[4];

        printf("Raw Pressure: 0x%04X (0x%02X) | Raw Temperature: 0x%04X (0x%02X)\n",
               data.pressure, rx_data[2], data.temperature, rx_data[5]);

        // Sleep for 500 ms
        usleep(MEASUREMENT_INTERVAL_MS * 1000);
    }

    // Clean up
    close(i2c_fd);
    return EXIT_SUCCESS;
}

