        perror("Failed to request SSR GPIO line");
        gpiod_line_put(line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    ssr_line = line;

    line = gpiod_line_get(chip, CE_PIN);
    if (!line) {
        perror("Failed to get CE GPIO line");
        gpiod_line_put(ssr_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(line, "CE", GPIOD_LINE_REQUEST_FLAG_ACTIVE_LOW)) {
        perror("Failed to request CE GPIO line");
        gpiod_line_put(ssr_line);
        gpiod_line_put(line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    ce_line = line;
}

void release_gpio() {
    if (ssr_line) {
        gpiod_line_put(ssr_line);
    }
    if (ce_line) {
        gpiod_line_put(ce_line);
    }
}

