#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/time.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <signal.h>
#include <errno.h>
#include <libgpiod.h>
#include <dirent.h>
#include <time.h>

#define GPIO4_PIN 4
#define GPIO17_PIN 17
#define GPIO18_PIN 18
#define PWM_CHANNEL 0
#define LOG_INTERVAL 5
#define LOG_FILE "greenhouse.log"

typedef struct {
    int fd;
    int pwm;
    int relay;
    int sensor_fd;
    char sensor_path[256];
    double setpoint;
    double Kp;
    double Ki;
    double Kd;
    double last_error;
    double integral;
    double prev_error;
    double output;
    FILE *log_file;
    int running;
} greenhouse_t;

void handle_signal(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        printf("Caught signal %d, shutting down...\n", sig);
        exit(EXIT_SUCCESS);
    }
}

void init_gpio(greenhouse_t *g) {
    g->pwm = gpiod_chip_open_by_name("gpiochip4");
    if (g->pwm < 0) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    g->relay = gpiod_line_get_by_number(g->pwm, GPIO17_PIN);
    if (g->relay < 0) {
        perror("Failed to get relay line");
        gpiod_chip_close(g->pwm);
        exit(EXIT_FAILURE);
    }

    g->relay = gpiod_line_request_output(g->relay, "relay", GPIOD_LINE_REQUEST_FLAG_ACTIVE_LOW);
    if (g->relay < 0) {
        perror("Failed to request relay line");
        gpiod_chip_close(g->pwm);
        exit(EXIT_FAILURE);
    }

    g->pwm = gpiod_line_get_by_number(g->pwm, GPIO18_PIN);
    if (g->pwm < 0) {
        perror("Failed to get PWM line");
        gpiod_line_release(g->relay);
        gpiod_chip_close(g->pwm);
        exit(EXIT_FAILURE);
    }

    g->pwm = gpiod_line_request_output(g->pwm, "pwm", GPIOD_LINE_REQUEST_FLAG_ACTIVE_LOW);
    if (g->pwm < 0) {
        perror("Failed to request PWM line");
        gpiod_line_release(g->relay);
        gpiod_chip_close(g->pwm);
        exit(EXIT_FAILURE);
    }

    g->pwm = gpiod_line_get_pwm_range(g->pwm, PWM_CHANNEL);
    if (g->pwm < 0) {
        perror("Failed to get PWM range");
        gpiod_line_release(g->relay);
        gpiod_line_release(g->pwm);
        gpiod_chip_close(g->pwm);
        exit(EXIT_FAILURE);
    }

    if (ioctl(g->pwm, PWM_SET_DUTY_CYCLE, 0) < 0) {
        perror("Failed to set PWM duty cycle");
        gpiod_line_release(g->relay);
        gpiod_line_release(g->pwm);
        gpiod_chip_close(g->pwm);
        exit(EXIT_FAILURE);
    }
}

void init_sensor(greenhouse_t *g) {
    snprintf(g->sensor_path, sizeof(g->sensor_path), "/sys/bus/w1/devices/28-00000568d6ff/w1_slave");
    g->sensor_fd = open(g->sensor_path, O_RDONLY);
    if (g->sensor_fd < 0) {
        perror("Failed to open sensor device");
        exit(EXIT_FAILURE);
    }
}

void close_gpio(greenhouse_t *g) {
    if (g->log_file) {
        fclose(g->log_file);
    }
    if (g->sensor_fd >= 0) {
        close(g->sensor_fd);
    }
    if (g->pwm >= 0) {
        ioctl(g->pwm, PWM_SET_DUTY_CYCLE, 0);
        gpiod_line_release(g->pwm);
    }
    if (g->relay >= 0) {
        gpiod_line_set_value(g->relay, 1);
        gpiod_line_release(g->relay);
    }
    gpiod_chip_close(g->pwm);
}

double read_sensor(greenhouse_t *g) {
    char buffer[256];
    ssize_t bytes_read = read(g->sensor_fd, buffer, sizeof(buffer));
    if (bytes_read < 0) {
        perror("Failed to read sensor");
        return -1.0;
    }

    if (strstr(buffer, "err") != NULL) {
        fprintf(stderr, "Sensor error detected\n");
        return -1.0;
    }

    char *token = strtok(buffer, "\n");
    if (!token) {
        return -1.0;
    }

    token = strtok(NULL, "\n");
    if (!token) {
        return -1.0;
    }

    char *temp_str = strstr(token, "t=");
    if (!temp_str) {
        return -1.0;
    }

    temp_str += 2;
    double temp = atof(temp_str) / 1000.0;
    return temp;
}

void log_data(greenhouse_t *g, double temp) {
    time_t now = time(NULL);
    struct tm *tm_now = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_now);

    fprintf(g->log_file, "%s,%.2f,%.2f,%.2f,%.2f\n", timestamp, temp, g->setpoint, g->output, g->output);
    fflush(g->log_file);
}

void setup_logging(greenhouse_t *g) {
    g->log_file = fopen(LOG_FILE, "a");
    if (!g->log_file) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }
}

void pid_update(greenhouse_t *g, double temp) {
    double error = g->setpoint - temp;
    g->integral += error;
    double derivative = error - g->prev_error;

    g->output = g->Kp * error + g->Ki * g->integral + g->Kd * derivative;

    if (g->output > 100.0) {
        g->output = 100.0;
    } else if (g->output < 0.0) {
        g->output = 0.0;
    }

    g->prev_error = error;
    g->last_error = error;
}

int main(int argc, char *argv[]) {
    if (argc != 5) {
        fprintf(stderr, "Usage: %s <setpoint> <Kp> <Ki> <Kd>\n", argv[0]);
        exit(EXIT_FAILURE);
    }

    greenhouse_t g;
    g.running = 1;

    g.setpoint = atof(argv[1]);
    g.Kp = atof(argv[2]);
    g.Ki = atof(argv[3]);
    g.Kd = atof(argv[4]);

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    init_gpio(&g);
    init_sensor(&g);
    setup_logging(&g);

    double last_log_time = 0.0;
    double temp = 0.0;

    while (g.running) {
        temp = read_sensor(&g);
        if (temp < 0) {
            fprintf(stderr, "Sensor error, retrying...\n");
            usleep(100000);
            continue;
        }

        pid_update(&g, temp);

        if (g.output > 50.0) {
            gpiod_line_set_value(g->relay, 0);
        } else {
            gpiod_line_set_value(g->relay, 1);
        }

        if (ioctl(g->pwm, PWM_SET_DUTY_CYCLE, (int)(g.output * 1024)) < 0) {
            perror("Failed to set PWM duty cycle");
        }

        double current_time = time(NULL);
        if (current_time - last_log_time >= LOG_INTERVAL) {
            log_data(&g, temp);
            last_log_time = current_time;
        }

        usleep(100000);
    }

    close_gpio(&g);
    return 0;
}

