#define I2C_BUS "/dev/i2c-1"
#define AHT20_ADDR 0x38
#define MEASURE_COMMAND 0xAC
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10
#define POLL_INTERVAL_S 5
#define HUMIDITY_THRESHOLD_HIGH 60
#define HUMIDITY_THRESHOLD_LOW 55
#define GPIO_PIN 17
#define GPIO_ACTIVE_HIGH 1

typedef struct {
    int fd;
    struct gpiod_line *relay_line;
} AppContext;

void handle_signal(int signum, void *context) {
    (void)signum;
    (void)context;
    // Clean up and exit
    exit(0);
}

int i2c_read_sensor(int fd, uint8_t *data) {
    int retries = 0;
    int result;

    while (retries < MAX_RETRIES) {
        // Trigger measurement
        result = i2c_smbus_write_byte(fd, MEASURE_COMMAND);
        if (result < 0) {
            fprintf(stderr, "Failed to trigger measurement: %s\n", strerror(errno));
            return -1;
        }

        usleep(80000); // Wait 80 ms

        // Read 6 bytes
        result = i2c_smbus_read_i2c_block_data(fd, AHT20_ADDR, 6, data);
        if (result < 0) {
            fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
            usleep(RETRY_DELAY_MS * 1000);
            retries++;
            continue;
        }

        // Check status byte
        if ((data[0] & 0x80) != 0x00) {
            fprintf(stderr, "Sensor busy or error: status byte 0x%02X\n", data[0]);
            usleep(RETRY_DELAY_MS * 1000);
            retries++;
            continue;
        }

        if ((data[0] & 0x0F) != 0x00) {
            fprintf(stderr, "Sensor not calibrated: status byte 0x%02X\n", data[0]);
            usleep(RETRY_DELAY_MS * 1000);
            retries++;
            continue;
        }

        return 0;
    }

    fprintf(stderr, "Failed to read sensor after %d retries\n", MAX_RETRIES);
    return -1;
}

void calculate_humidity(const uint8_t *data, float *humidity) {
    uint32_t raw = (data[1] << 12) | (data[2] << 4) | (data[3] >> 4);
    *humidity = (float)raw / 65536.0 * 100.0;
}

void log_humidity(float humidity) {
    time_t now = time(NULL);
    char *timestamp = ctime(&now);
    timestamp[strcspn(timestamp, "\n")] = '\0'; // Remove newline
    printf("[%s] Humidity: %.2f%%\n", timestamp, humidity);
}

void control_relay(float humidity, AppContext *ctx) {
    if (humidity > HUMIDITY_THRESHOLD_HIGH) {
        if (gpiod_line_set_value(ctx->relay_line, GPIO_ACTIVE_HIGH) < 0) {
            fprintf(stderr, "Failed to activate relay\n");
        }
    } else if (humidity < HUMIDITY_THRESHOLD_LOW) {
        if (gpiod_line_set_value(ctx->relay_line, 0) < 0) {
            fprintf(stderr, "Failed to deactivate relay\n");
        }
    }
}

void cleanup(AppContext *ctx) {
    if (ctx->relay_line) {
        gpiod_line_release(ctx->relay_line);
    }
    if (ctx->fd >= 0) {
        close(ctx->fd);
    }
}

int main() {
    AppContext app;
    int result;
    uint8_t data[6];
    float humidity;

    // Initialize signal handling
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Initialize GPIO
    struct gpiod_chip *chip;
    chip = gpiod_chip_open("/dev/gpiochip4");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return 1;
    }

    app.relay_line = gpiod_line_get(chip, GPIO_PIN);
    if (!app.relay_line) {
        fprintf(stderr, "Failed to get GPIO line %d\n", GPIO_PIN);
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_output(app.relay_line, "dehumidifier_relay", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line as output\n");
        gpiod_line_release(app.relay_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Initialize I2C
    app.fd = open(I2C_BUS, O_RDWR);
    if (app.fd < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        gpiod_line_release(app.relay_line);
        gpiod_chip_close(chip);
        return 1;
    }

    if (ioctl(app.fd, I2C_SLAVE, AHT20_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address: %s\n", strerror(errno));
        close(app.fd);
        gpiod_line_release(app.relay_line);
        gpiod_chip_close(chip);
        return 1;
    }

    while (1) {
        if (i2c_read_sensor(app.fd, data) < 0) {
            fprintf(stderr, "Sensor not responding, retrying...\n");
            usleep(1000000); // 1 second
            continue;
        }

        calculate_humidity(data, &humidity);
        log_humidity(humidity);
        control_relay(humidity, &app);
        usleep(POLL_INTERVAL_S * 1000000);
    }

    cleanup(&app);
    return 0;
}

