typedef struct {
    int fd;
    struct gpiod_line *reset_line;
} htu21d_dev;

htu21d_status htu21d_init(htu21d_dev *dev) {
    dev->fd = open(I2C_BUS, O_RDWR);
    if (dev->fd < 0) {
        syslog(LOG_ERR, "Failed to open I2C bus: %m");
        return HTU21D_I2C_ERROR;
    }

    if (ioctl(dev->fd, I2C_SLAVE, HTU21D_ADDR) < 0) {
        syslog(LOG_ERR, "Failed to set I2C slave address: %m");
        close(dev->fd);
        return HTU21D_I2C_ERROR;
    }

    return HTU21D_OK;
}

htu21d_status htu21d_reset(htu21d_dev *dev) {
    unsigned char cmd = HTU21D_RESET;
    if (write(dev->fd, &cmd, 1) != 1) {
        syslog(LOG_ERR, "Failed to send reset command: %m");
        return HTU21D_I2C_ERROR;
    }
    usleep(HTU21D_WAIT_TIME);
    return HTU21D_OK;
}

htu21d_status htu21d_measure(htu21d_dev *dev, unsigned char *data, size_t size) {
    if (write(dev->fd, &HTU21D_MEASURE_HUMIDITY, 1) != 1) {
        syslog(LOG_ERR, "Failed to send measurement command: %m");
        return HTU21D_I2C_ERROR;
    }
    usleep(HTU21D_WAIT_TIME);

    if (read(dev->fd, data, size) != size) {
        syslog(LOG_ERR, "Failed to read measurement data: %m");
        return HTU21D_I2C_ERROR;
    }

    if ((data[0] & HTU21D_CRC) != HTU21D_CRC) {
        syslog(LOG_ERR, "CRC error in measurement data");
        return HTU21D_CRC_ERROR;
    }

    return HTU21D_OK;
}

htu21d_status htu21d_get_humidity(htu21d_dev *dev, double *humidity) {
    unsigned char data[3];
    htu21d_status status = htu21d_measure(dev, data, sizeof(data));
    if (status != HTU21D_OK) {
        return status;
    }

    *humidity = (data[0] << 8 | data[1]) * 0.0405 + 4.05;
    return HTU21D_OK;
}

void htu21d_cleanup(htu21d_dev *dev) {
    if (dev->fd >= 0) {
        close(dev->fd);
    }
}

void log_message(const char *message) {
    syslog(LOG_INFO, "%s", message);
}

void handle_signal(int sig) {
    log_message("Received signal, shutting down...");
    exit(EXIT_SUCCESS);
}

int create_http_socket(const char *host, int port) {
    int sockfd;
    struct sockaddr_in server_addr;

    sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0) {
        syslog(LOG_ERR, "Failed to create socket: %m");
        return -1;
    }

    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(port);
    if (inet_pton(AF_INET, host, &server_addr.sin_addr) <= 0) {
        syslog(LOG_ERR, "Invalid address or address family for %s", host);
        close(sockfd);
        return -1;
    }

    if (connect(sockfd, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        syslog(LOG_ERR, "Failed to connect to %s:%d: %m", host, port);
        close(sockfd);
        return -1;
    }

    return sockfd;
}

void send_http_post(int sockfd, const char *json) {
    char request[1024];
    snprintf(request, sizeof(request), "POST /humidity HTTP/1.1\r\n"
                                       "Host: api.example.com\r\n"
                                       "Content-Type: application/json\r\n"
                                       "Content-Length: %zu\r\n"
                                       "\r\n"
                                       "%s", strlen(json), json);

    if (write(sockfd, request, strlen(request)) < 0) {
        syslog(LOG_ERR, "Failed to send HTTP request: %m");
        return;
    }

    if (read(sockfd, request, sizeof(request)) < 0) {
        syslog(LOG_ERR, "Failed to read HTTP response: %m");
    }
}

void send_json(double humidity) {
    char json[MAX_BUFFER_SIZE];
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    snprintf(json, sizeof(json), "{ \"timestamp\": \"%s\", \"humidity\": %.2f }", timestamp, humidity);
    log_message(json);

    int sockfd = create_http_socket("api.example.com", 80);
    if (sockfd >= 0) {
        send_http_post(sockfd, json);
        close(sockfd);
    }
}

int main() {
    htu21d_dev htu;
    double humidity;
    int running = 1;

    // Initialize syslog
    openlog("htu21d", LOG_PID | LOG_CONS, LOG_USER);

    // Initialize I2C
    if (htu21d_init(&htu) != HTU21D_OK) {
        syslog(LOG_ERR, "Failed to initialize HTU21D sensor");
        closelog();
        exit(EXIT_FAILURE);
    }

    // Initialize signal handling
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (running) {
        htu21d_status status = htu21d_get_humidity(&htu, &humidity);
        if (status == HTU21D_OK) {
            send_json(humidity);
        } else {
            syslog(LOG_ERR, "Failed to read humidity: %d", status);
        }

        sleep(POLL_INTERVAL);
    }

    htu21d_cleanup(&htu);
    closelog();
    exit(EXIT_SUCCESS);
}
