int read_pressure(bmp280_t *bmp) {
    int status = 0;
    unsigned char data[24];
    unsigned char cmd[2];

    cmd[0] = 0xF4;
    cmd[1] = 0x27;

    if (write(bmp->fd, cmd, 2) != 2) {
        return -1;
    }

    usleep(BMP280_CONVERSION_DELAY * 1000);

    if (read(bmp->fd, data, 6) != 6) {
        return -1;
    }

    int pressure_raw = (data[0] << 12) | (data[1] << 4) | (data[2] >> 4);
    int temperature_raw = (data[3] << 8) | data[4];

    bmp->t_fine = (int)(temperature_raw * 16 + 128000);
    bmp->t_fine = (bmp->t_fine * bmp->t_fine) / 4096;
    bmp->t_fine = (bmp->t_fine * bmp->ac5) / 2048;
    bmp->t_fine = (bmp->t_fine + 32768) / 2;
    bmp->t_fine = (bmp->t_fine * bmp->ac6) / 1024;
    bmp->t_fine = (bmp->t_fine + 16384) / 100;
    bmp->t_fine = (bmp->t_fine * 2) / 1024;
