    int pressure = (bmp->t_fine * bmp->ac7) / 16384;
    pressure = (pressure + (bmp->t_fine * bmp->ac8) / 16384) / 100;
    pressure = (bmp->t_fine * bmp->ac9) / 16384;
    pressure = (pressure + (bmp->t_fine * bmp->ac10) / 16384) / 100;

    int pressure_final = (pressure * 1000) / 16384;
    pressure_final = (pressure_final + (bmp->mb * 16384) / 1000) / 100;
    pressure_final = (pressure_final + (bmp->mc * 2048) / 1000) / 100;
    pressure_final = (pressure_final + (bmp->md * 16384) / 1000) / 100;

    bmp->pressure = pressure_final;

    return 0;
