#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <gpiod.h>
#include <signal.h>
#include <errno.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <dirent.h>

#define I2C_BUS "/dev/i2c-1"
#define TMP117_ADDR 0x49
#define AHT20_ADDR 0x38
#define PIR_GPIO_LINE "gpiochip4"
#define PIR_GPIO_PIN 17
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10
#define LOG_FILE_NAME "sensor_log_"
#define LOG_FILE_EXT ".csv"
#define LOG_HEADER "Timestamp,Temperature(C),Humidity(%),MotionDetected"
#define LOG_DIR "sensor_logs"

typedef struct {
    int i2c_fd;
    struct gpiod_line *pir_line;
    FILE *log_file;
    char log_filename[256];
    time_t last_midnight;
} LoggerContext;

void log_error(const char *message, int error_code) {
    fprintf(stderr, "Error: %s (%d)\n", message, error_code);
}

void log_warning(const char *message) {
    fprintf(stderr, "Warning: %s\n", message);
}

void close_logger(LoggerContext *ctx) {
    if (ctx->i2c_fd >= 0) {
        close(ctx->i2c_fd);
    }
    if (ctx->pir_line) {
        gpiod_line_release(ctx->pir_line);
    }
    if (ctx->log_file) {
        fclose(ctx->log_file);
    }
    free(ctx);
}

void handle_signal(int signal) {
    close_logger(NULL);
    exit(EXIT_SUCCESS);
}

int open_i2c_bus(const char *bus_path) {
    int fd = open(bus_path, O_RDWR);
    if (fd < 0) {
        log_error("Failed to open I2C bus", errno);
        return -1;
    }
    return fd;
}

int i2c_read_retries(int fd, int addr, unsigned char *buf, int len, int max_retries) {
    int retries = 0;
    while (retries < max_retries) {
        if (ioctl(fd, I2C_SLAVE, addr) < 0) {
            log_error("Failed to set I2C slave address", errno);
            return -1;
        }
        if (read(fd, buf, len) == len) {
            return 0;
        }
        log_error("I2C read failed", errno);
        usleep(RETRY_DELAY_MS * 1000);
        retries++;
    }
    return -1;
}

int read_tmp117(int fd) {
    unsigned char buf[2];
    if (i2c_read_retries(fd, TMP117_ADDR, buf, 2, MAX_RETRIES) < 0) {
        log_warning("Failed to read TMP117");
        return -1;
    }
