        set_gpio_value(ctx->motor_ena_gpio_fd, ctx->motor_ena_gpio, 0);
        ctx->motor_state = STATE_IDLE;
    }
}

void signal_handler(int signum) {
    log_message("Received signal, stopping motor and releasing GPIO...");
    motor_stop(&gpio_context);
    if (gpio_context.rain_gpio_fd >= 0) close(gpio_context.rain_gpio_fd);
    if (gpio_context.motor_ena_gpio_fd >= 0) close(gpio_context.motor_ena_gpio_fd);
    if (gpio_context.motor_in1_gpio_fd >= 0) close(gpio_context.motor_in1_gpio_fd);
    if (gpio_context.motor_in2_gpio_fd >= 0) close(gpio_context.motor_in2_gpio_fd);
    exit(EXIT_SUCCESS);
}

int main() {
    gpio_context_t gpio_context = {0};

    // Initialize GPIOs
    gpio_context.rain_gpio = GPIO_RAIN_SENSOR;
    gpio_context.motor_ena_gpio = GPIO_MOTOR_ENA;
    gpio_context.motor_in1_gpio = GPIO_MOTOR_IN1;
    gpio_context.motor_in2_gpio = GPIO_MOTOR_IN2;

    // Open GPIO chip
    gpio_context.rain_gpio_fd = open_gpio(gpio_context.rain_gpio);
    if (gpio_context.rain_gpio_fd < 0) {
        log_message("Failed to initialize GPIOs, exiting...");
        return EXIT_FAILURE;
    }

    gpio_context.motor_ena_gpio_fd = open_gpio(gpio_context.motor_ena_gpio);
    if (gpio_context.motor_ena_gpio_fd < 0) {
        log_message("Failed to initialize GPIOs, exiting...");
        close(gpio_context.rain_gpio_fd);
        return EXIT_FAILURE;
    }

    gpio_context.motor_in1_gpio_fd = open_gpio(gpio_context.motor_in1_gpio);
    if (gpio_context.motor_in1_gpio_fd < 0) {
        log_message("Failed to initialize GPIOs, exiting...");
        close(gpio_context.rain_gpio_fd);
        close(gpio_context.motor_ena_gpio_fd);
        return EXIT_FAILURE;
    }

    gpio_context.motor_in2_gpio_fd = open_gpio(gpio_context.motor_in2_gpio);
    if (gpio_context.motor_in2_gpio_fd < 0) {
        log_message("Failed to initialize GPIOs, exiting...");
        close(gpio_context.rain_gpio_fd);
        close(gpio_context.motor_ena_gpio_fd);
        close(gpio_context.motor_in1_gpio_fd);
        return EXIT_FAILURE;
    }

    // Set directions
    if (set_gpio_direction(gpio_context.rain_gpio_fd, gpio_context.rain_gpio, GPIO_DIRECTION_IN) < 0) {
        log_message("Failed to set direction for rain sensor, exiting...");
        close(gpio_context.rain_gpio_fd);
        close(gpio_context.motor_ena_gpio_fd);
        close(gpio_context.motor_in1_gpio_fd);
        close(gpio_context.motor_in2_gpio_fd);
        return EXIT_FAILURE;
    }

    if (set_gpio_direction(gpio_context.motor_ena_gpio_fd, gpio_context.motor_ena_gpio, GPIO_DIRECTION_OUT) < 0) {
        log_message("Failed to set direction for motor ENA, exiting...");
        close(gpio_context.rain_gpio_fd);
        close(gpio_context.motor_ena_gpio_fd);
        close(gpio_context.motor_in1_gpio_fd);
        close(gpio_context.motor_in2_gpio_fd);
        return EXIT_FAILURE;
    }

    if (set_gpio_direction(gpio_context.motor_in1_gpio_fd, gpio_context.motor_in1_gpio, GPIO_DIRECTION_OUT) < 0) {
        log_message("Failed to set direction for motor IN1, exiting...");
        close(gpio_context.rain_gpio_fd);
        close(gpio_context.motor_ena_gpio_fd);
        close(gpio_context.motor_in1_gpio_fd);
        close(gpio_context.motor_in2_gpio_fd);
        return EXIT_FAILURE;
    }

    if (set_gpio_direction(gpio_context.motor_in2_gpio_fd, gpio_context.motor_in2_gpio, GPIO_DIRECTION_OUT) < 0) {
        log_message("Failed to set direction for motor IN2, exiting...");
        close(gpio_context.rain_gpio_fd);
        close(gpio_context.motor_ena_gpio_fd);
        close(gpio_context.motor_in1_gpio_fd);
        close(gpio_context.motor_in2_gpio_fd);
        return EXIT_FAILURE;
    }

    // Set initial motor state
    gpio_context.motor_state = STATE_IDLE;

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_message("Rain sensor monitoring started...");

    while (1) {
        // Poll rain sensor
        int rain_value = get_gpio_value(gpio_context.rain_gpio_fd, gpio_context.rain_gpio);
        if (rain_value < 0) {
            log_message("Failed to read rain sensor value, continuing...");
            usleep(100000);
            continue;
        }

        if (rain_value == 0) {
            log_message("Rain detected! Starting motor...");
            motor_stop(&gpio_context);

            // Set motor direction (forward)
            if (set_gpio_value(gpio_context.motor_in1_gpio_fd, gpio_context.motor_in1_gpio, 1) < 0) {
                log_message("Failed to set motor IN1, continuing...");
            }

            if (set_gpio_value(gpio_context.motor_in2_gpio_fd, gpio_context.motor_in2_gpio, 0) < 0) {
                log_message("Failed to set motor IN2, continuing...");
            }

            // Enable motor
            if (set_gpio_value(gpio_context.motor_ena_gpio_fd, gpio_context.motor_ena_gpio, 1) < 0) {
                log_message("Failed to enable motor, continuing...");
            }

            gpio_context.motor_state = STATE_RUNNING;

            // Run motor for 5 seconds
            usleep(5000000);

            // Stop motor
            motor_stop(&gpio_context);
        }

        usleep(POLL_INTERVAL * 1000000);
    }

    return EXIT_SUCCESS;
}
