#define PWM_DUTY_CYCLE 1000  // 1% duty cycle for dimming

typedef struct {
    struct gpiod_line *red_line;
    struct gpiod_line *green_line;
    struct gpiod_line *blue_line;
    struct pwm_device *pwm_dev;
} LedDriver;

void handle_signal(int sig) {
    (void)sig;
    // Turn all channels off (common-anode LED)
    gpiod_line_set_value(red_line, 0);
    gpiod_line_set_value(green_line, 0);
    gpiod_line_set_value(blue_line, 0);
    if (pwm_dev) {
        pwm_set_duty_cycle(pwm_dev, 0);
    }
    // Clean up
    gpiod_line_release(red_line);
    gpiod_line_release(green_line);
    gpiod_line_release(blue_line);
    pwm_close(pwm_dev);
    exit(0);
}

void init_pwm(LedDriver *driver) {
    int fd;
    struct pwm_config config = {
        .period = PWM_PERIOD,
        .duty_cycle = PWM_DUTY_CYCLE,
        .polarity = PWM_POLARITY_NORMAL
    };

    fd = open("/dev/pwm", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open PWM device\n");
        exit(1);
    }

    if (ioctl(fd, PWM_IOCTL_SET_CONFIG, &config) < 0) {
        fprintf(stderr, "Failed to set PWM configuration\n");
        close(fd);
        exit(1);
    }

    driver->pwm_dev = pwm_get(fd, 0);
    if (!driver->pwm_dev) {
        fprintf(stderr, "Failed to get PWM device\n");
        close(fd);
        exit(1);
    }
}

void init_gpio(LedDriver *driver) {
    struct gpiod_chip *chip;
    struct gpiod_line_config config = GPIOD_LINE_CONFIG_DEFAULTS;

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        exit(1);
    }

    config.direction = GPIOD_LINE_DIRECTION_OUTPUT;
    config.output_value = 0;

    driver->red_line = gpiod_line_request(chip, "red", RED_GPIO, &config);
    if (!driver->red_line) {
        fprintf(stderr, "Failed to request red GPIO line\n");
        gpiod_chip_close(chip);
        exit(1);
    }

    driver->green_line = gpiod_line_request(chip, "green", GREEN_GPIO, &config);
    if (!driver->green_line) {
        fprintf(stderr, "Failed to request green GPIO line\n");
        gpiod_line_release(driver->red_line);
        gpiod_chip_close(chip);
        exit(1);
    }

    driver->blue_line = gpiod_line_request(chip, "blue", BLUE_GPIO, &config);
    if (!driver->blue_line) {
        fprintf(stderr, "Failed to request blue GPIO line\n");
        gpiod_line_release(driver->red_line);
        gpiod_line_release(driver->green_line);
        gpiod_chip_close(chip);
        exit(1);
    }
}

void get_cpu_load(double *cpu_load) {
    FILE *fp;
    char line[256];
    long total_time = 0, idle_time = 0;

    fp = fopen("/proc/stat", "r");
    if (!fp) {
        fprintf(stderr, "Failed to open /proc/stat\n");
        exit(1);
    }

    if (fgets(line, sizeof(line), fp)) {
        sscanf(line, "cpu %ld %ld %ld %ld %ld %ld %ld %ld",
               &total_time, &idle_time, &total_time, &total_time, &total_time,
               &total_time, &total_time, &total_time);
    }

    fclose(fp);

    *cpu_load = (double)(total_time - idle_time) / total_time;
}

void set_color(double cpu_load, struct pwm_device *pwm_dev) {
    int red, green, blue;

    if (cpu_load <= 0.0) {
        red = 0;
        green = 255;
        blue = 0;
    } else if (cpu_load <= 0.5) {
        red = (int)(cpu_load * 255 * 2);
        green = 255;
        blue = 0;
    } else {
        red = 255;
        green = (int)(cpu_load * 255 * 2 - 255);
        blue = 0;
    }

    red = (red > 255) ? 255 : red;
    green = (green > 255) ? 255 : green;
    blue = (blue > 255) ? 255 : blue;

    gpiod_line_set_value(driver->red_line, red);
    gpiod_line_set_value(driver->green_line, green);
    gpiod_line_set_value(driver->blue_line, blue);

    pwm_set_duty_cycle(pwm_dev, red);
    pwm_set_duty_cycle(pwm_dev, green);
    pwm_set_duty_cycle(pwm_dev, blue);
}

int main() {
    LedDriver driver;
    double cpu_load;
    struct sigaction sa;
    int ret;

    init_gpio(&driver);
    init_pwm(&driver);

    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        exit(1);
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        exit(1);
    }

    while (1) {
        get_cpu_load(&cpu_load);
        set_color(cpu_load, driver.pwm_dev);
        usleep(500000); // 500 ms
    }

    return 0;
}

