#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>
#include <time.h>
#include <errno.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 500000
#define SPI_MODE SPI_MODE_0
#define SPI_BITS 8
#define SPI_DELAY 0

#define GPIO_FAN_PWM 18
#define GPIO_FAN_PWM_CHANNEL 0
#define PWM_FREQUENCY 1000
#define PWM_DUTY_MAX 255
#define BUFFER_SIZE 20

typedef struct {
    time_t timestamp;
    float temperature;
    int duty_cycle;
} buffer_entry;

typedef struct {
    buffer_entry entries[BUFFER_SIZE];
    int head;
    int tail;
    int full;
} circular_buffer;

void init_circular_buffer(circular_buffer *buf) {
    buf->head = 0;
    buf->tail = 0;
    buf->full = 0;
}

int circular_buffer_full(circular_buffer *buf) {
    return buf->full;
}

int circular_buffer_add(circular_buffer *buf, buffer_entry entry) {
    if (buf->full) {
        return -1;
    }
    buf->entries[buf->head] = entry;
    buf->head = (buf->head + 1) % BUFFER_SIZE;
    buf->full = (buf->head == buf->tail);
    return 0;
}

int circular_buffer_get(circular_buffer *buf, buffer_entry *entry) {
    if (!buf->full && buf->head == buf->tail) {
        return -1;
    }
    *entry = buf->entries[buf->tail];
    buf->tail = (buf->tail + 1) % BUFFER_SIZE;
    buf->full = (buf->head == buf->tail);
    return 0;
}

int read_max31855(int spi_fd) {
    uint8_t tx[3] = {0x01, 0x00, 0x00};
    uint8_t rx[3] = {0};

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(3), &tx) < 0) {
        perror("SPI transfer failed");
        return -1;
    }

    uint16_t raw_temp = (rx[0] << 8) | rx[1];
    float temperature = (float)raw_temp * 0.0625f;

    if (rx[2] & 0x80) {
        temperature = -temperature;
    }

    return temperature;
}

void set_pwm_duty(int pwm_fd, int duty) {
    if (duty < 0) duty = 0;
    if (duty > PWM_DUTY_MAX) duty = PWM_DUTY_MAX;

    if (ioctl(pwm_fd, PWM_SET_DUTY, duty) < 0) {
        perror("Failed to set PWM duty cycle");
    }
}

void set_pwm_frequency(int pwm_fd, int frequency) {
    if (ioctl(pwm_fd, PWM_SET_FREQ, frequency) < 0) {
        perror("Failed to set PWM frequency");
    }
}

void start_pwm(int pwm_fd) {
    if (ioctl(pwm_fd, PWM_START) < 0) {
        perror("Failed to start PWM");
    }
}

void stop_pwm(int pwm_fd) {
    if (ioctl(pwm_fd, PWM_STOP) < 0) {
        perror("Failed to stop PWM");
    }
}

void sigint_handler(int sig) {
    stop_pwm(pwm_fd);
    close(pwm_fd);
    close(spi_fd);
    gpiod_chip_close(chip);
    printf("Received SIGINT, exiting...\n");
    exit(EXIT_SUCCESS);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("Failed to set up signal handler");
        exit(EXIT_FAILURE);
    }

    int spi_fd;
    if ((spi_fd = open(SPI_DEVICE, O_RDWR | O_NOCTTY | O_SYNC)) < 0) {
        perror("Failed to open SPI device");
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS) < 0) {
        perror("Failed to set SPI bits per word");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_DELAY_USEC, &SPI_DELAY) < 0) {
        perror("Failed to set SPI delay");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    struct gpiod_chip *chip;
    if ((chip = gpiod_chip_open("/dev/gpiochip4")) < 0) {
        perror("Failed to open GPIO chip");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    struct gpiod_line *pwm_line;
    if ((pwm_line = gpiod_line_request_output(chip, "pwm", GPIO_FAN_PWM, 0)) < 0) {
        perror("Failed to request PWM GPIO line");
        gpiod_chip_close(chip);
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    int pwm_fd = gpiod_line_get_fd(pwm_line);
    if (pwm_fd < 0) {
        perror("Failed to get PWM line file descriptor");
        gpiod_line_release(pwm_line);
        gpiod_chip_close(chip);
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(pwm_fd, PWM_SET_DUTY, 0) < 0) {
        perror("Failed to initialize PWM duty cycle");
    }

    if (ioctl(pwm_fd, PWM_SET_FREQ, PWM_FREQUENCY) < 0) {
        perror("Failed to set PWM frequency");
    }

    start_pwm(pwm_fd);

    circular_buffer buffer;
    init_circular_buffer(&buffer);

    while (1) {
        time_t now = time(NULL);
        struct tm *now_tm = localtime(&now);

        float temperature = 0.0;
        int read_result = read_max31855(spi_fd);
        if (read_result < 0) {
            fprintf(stderr, "SPI transfer error or MAX31855 fault, skipping fan update.\n");
            sleep(1);
            continue;
        } else {
            temperature = read_result;
        }

        int duty_cycle = 0;
        if (temperature < 25.0) {
            duty_cycle = 0;
        } else if (temperature >= 25.0 && temperature <= 40.0) {
            duty_cycle = (int)((temperature - 25.0) / 15.0 * 50.0);
        } else if (temperature > 40.0 && temperature <= 60.0) {
            duty_cycle = 50 + (int)((temperature - 40.0) / 20.0 * 150.0);
        } else {
            duty_cycle = 200;
        }

        if (duty_cycle > 255) {
            duty_cycle = 255;
        }

        buffer_entry entry = {now, temperature, duty_cycle};

        if (circular_buffer_add(&buffer, entry) < 0) {
            fprintf(stderr, "Circular buffer full, could not add entry.\n");
        }

        set_pwm_duty(pwm_fd, duty_cycle);

        sleep(1);
    }

    return 0;
}
