#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>
#include <signal.h>
#include <time.h>
#include <errno.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define CE_PIN 8
#define LOG_FILE "rtd_log.csv"
#define LOG_INTERVAL 5
#define MAX_RETRIES 3

typedef enum {
    RTD_MODE_3WIRE = 0,
    RTD_MODE_4WIRE = 1
} rtd_mode_t;

typedef enum {
    RTD_FAULT_NONE = 0,
    RTD_FAULT_SHORT = 1,
    RTD_FAULT_OPEN = 2,
    RTD_FAULT_OVERLOAD = 4
} rtd_fault_t;

typedef struct {
    int fd;
    struct gpiod_line *ce_line;
    FILE *log_file;
    int running;
} rtd_context_t;

void handle_signal(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        printf("Shutting down...\n");
        exit(EXIT_SUCCESS);
    }
}

void log_error(rtd_context_t *ctx, const char *msg) {
    fprintf(stderr, "ERROR: %s\n", msg);
    if (ctx->log_file) {
        fprintf(ctx->log_file, "ERROR: %s\n", msg);
        fflush(ctx->log_file);
    }
}

void log_temperature(rtd_context_t *ctx, double temp) {
    time_t now = time(NULL);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
    fprintf(ctx->log_file, "%s,%.6f\n", timestamp, temp);
    fflush(ctx->log_file);
}

int init_spi(rtd_context_t *ctx) {
    ctx->fd = open(SPI_DEVICE, O_RDWR | O_NOCTTY | O_SYNC);
    if (ctx->fd < 0) {
        log_error(ctx, "Failed to open SPI device");
        return -1;
    }

    int mode = SPI_MODE_0;
    if (ioctl(ctx->fd, SPI_IOC_WR_MODE, &mode) < 0) {
        log_error(ctx, "Failed to set SPI mode");
        close(ctx->fd);
        return -1;
    }

    if (ioctl(ctx->fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS_PER_WORD_16) < 0) {
        log_error(ctx, "Failed to set bits per word");
        close(ctx->fd);
        return -1;
    }

    if (ioctl(ctx->fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        log_error(ctx, "Failed to set SPI speed");
        close(ctx->fd);
        return -1;
    }

    return 0;
}

int init_ce_pin(rtd_context_t *ctx) {
    struct gpiod_chip *chip;
    chip = gpiod_chip_open_by_number(4); // BCM2835 GPIO bank 4
    if (!chip) {
        log_error(ctx, "Failed to open GPIO chip");
        return -1;
    }

    ctx->ce_line = gpiod_line_get(chip, CE_PIN);
    if (!ctx->ce_line) {
        log_error(ctx, "Failed to get CE GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(ctx->ce_line, "rtd_ce", 1) < 0) {
        log_error(ctx, "Failed to request CE GPIO line");
        gpiod_line_put(ctx->ce_line);
        gpiod_chip_close(chip);
        return -1;
    }

    gpiod_line_set_value(ctx->ce_line, 1); // High to disable
    return 0;
}

void deinit_spi(rtd_context_t *ctx) {
    if (ctx->ce_line) {
        gpiod_line_put(ctx->ce_line);
    }
    if (ctx->fd >= 0) {
        close(ctx->fd);
    }
    if (ctx->log_file) {
        fclose(ctx->log_file);
    }
}

void deinit_ce_pin(rtd_context_t *ctx) {
    if (ctx->ce_line) {
        gpiod_line_put(ctx->ce_line);
    }
}

int read_rtd(rtd_context_t *ctx, uint16_t *rtd_value, rtd_fault_t *fault) {
    uint16_t tx[2] = {0x0000, 0x0000};
    uint16_t rx[2] = {0x0000, 0x0000};

    for (int i = 0; i < MAX_RETRIES; i++) {
        gpiod_line_set_value(ctx->ce_line, 0); // Enable
        struct spi_ioc_transfer spi = {
            .tx_buf = (unsigned long)tx,
            .rx_buf = (unsigned long)rx,
            .len = 4,
            .delay_usecs = 0,
            .speed_hz = SPI_SPEED,
            .bits_per_word = 16
        };

        if (ioctl(ctx->fd, SPI_IOC_MESSAGE(1), &spi) < 0) {
            log_error(ctx, "SPI communication failed");
            gpiod_line_set_value(ctx->ce_line, 1); // Disable
            return -1;
        }

        gpiod_line_set_value(ctx->ce_line, 1); // Disable

        *rtd_value = rx[0];
        *fault = (rtd_fault_t)(rx[1] & 0x0F);

        if (*fault == RTD_FAULT_NONE) {
            return 0;
        }
    }

    log_error(ctx, "RTD fault detected");
    return -1;
}

double calculate_temperature(uint16_t rtd_value, rtd_mode_t mode) {
    double rtd_resistance = (double)rtd_value * 0.00390625; // 16-bit value to ohms
    double temp;

    if (mode == RTD_MODE_3WIRE) {
        temp = (rtd_resistance - 100.0) / (3.9083 * 0.001) + 25.0;
    } else {
        temp = (rtd_resistance - 100.0) / (3.9083 * 0.001) + 25.0;
    }

    return temp;
}

int main() {
    rtd_context_t ctx = {0};
    uint16_t rtd_value = 0;
    rtd_fault_t fault = RTD_FAULT_NONE;
    double temperature = 0.0;
    int ret;

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if (init_spi(&ctx) < 0) {
        return EXIT_FAILURE;
    }

    if (init_ce_pin(&ctx) < 0) {
        deinit_spi(&ctx);
        return EXIT_FAILURE;
    }

    ctx.log_file = fopen(LOG_FILE, "a");
    if (!ctx.log_file) {
        log_error(&ctx, "Failed to open log file");
        deinit_ce_pin(&ctx);
        deinit_spi(&ctx);
        return EXIT_FAILURE;
    }

    fprintf(ctx.log_file, "Timestamp,Temperature\n");
    fflush(ctx.log_file);

    ctx.running = 1;
    while (ctx.running) {
        ret = read_rtd(&ctx, &rtd_value, &fault);
        if (ret < 0) {
            log_error(&ctx, "Failed to read RTD");
            sleep(1);
            continue;
        }

        if (fault != RTD_FAULT_NONE) {
            log_error(&ctx, "RTD fault detected");
            sleep(1);
            continue;
        }

        temperature = calculate_temperature(rtd_value, RTD_MODE_3WIRE);
        log_temperature(&ctx, temperature);
        sleep(LOG_INTERVAL);
    }

    deinit_ce_pin(&ctx);
    deinit_spi(&ctx);
    return EXIT_SUCCESS;
}

