    while (ctx.running) {
        ret = read_rtd(&ctx, &rtd_value, &fault);
        if (ret < 0) {
            log_error(&ctx, "Failed to read RTD");
            sleep(1);
            continue;
        }

        if (fault != RTD_FAULT_NONE) {
            log_error(&ctx, "RTD fault detected");
            sleep(1);
            continue;
        }

        temperature = calculate_temperature(rtd_value, RTD_MODE_3WIRE);
        log_temperature(&ctx, temperature);
        sleep(LOG_INTERVAL);
    }

    deinit_ce_pin(&ctx);
    deinit_spi(&ctx);
    return EXIT_SUCCESS;
}
