#define BME280_PRESSURE_REGISTER 0xF7
#define BME280_DATA_SIZE 8
#define LOG_FILE "bme280_log.csv"
#define LOG_INTERVAL 5

typedef struct {
    int fd;
    FILE *log_file;
    int running;
} app_state;

void handle_signal(int sig) {
    app_state *state = (app_state *)malloc(sizeof(app_state));
    if (state) {
        state->running = 0;
        free(state);
    }
}

void close_i2c(int fd) {
    if (fd >= 0) {
        close(fd);
    }
}

void close_log_file(FILE *log_file) {
    if (log_file) {
        fclose(log_file);
    }
}

void log_data(FILE *log_file, time_t timestamp, double temperature, double humidity, double pressure) {
    char timestamp_str[20];
    struct tm *tm_info = localtime(&timestamp);
    strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f\n", timestamp_str, temperature, humidity, pressure);
    fflush(log_file);
}

int read_bme280_chip_id(int fd) {
    char buffer[1];
    int ret;

    ret = ioctl(fd, I2C_SLAVE, BME280_I2C_ADDR);
    if (ret < 0) {
        perror("Failed to set I2C slave address");
        return -1;
    }

    ret = read(fd, buffer, 1);
    if (ret < 0) {
        perror("Failed to read chip ID");
        return -1;
    }

    if (buffer[0] != BME280_CHIP_ID) {
        fprintf(stderr, "Invalid BME280 chip ID: 0x%02X (expected 0x%02X)\n", buffer[0], BME280_CHIP_ID);
        return -1;
    }

    return 0;
}

int read_calibration_data(int fd, uint8_t *calibration_data) {
    int ret;

    ret = ioctl(fd, I2C_SLAVE, BME280_I2C_ADDR);
    if (ret < 0) {
        perror("Failed to set I2C slave address");
        return -1;
    }

    ret = read(fd, calibration_data, BME280_CALIBRATION_DATA_SIZE);
    if (ret < 0) {
        perror("Failed to read calibration data");
        return -1;
    }

    return 0;
}

int read_temperature(int fd, uint8_t *calibration_data, double *temperature) {
    uint8_t buffer[3];
    int ret;

    ret = ioctl(fd, I2C_SLAVE, BME280_I2C_ADDR);
    if (ret < 0) {
        perror("Failed to set I2C slave address");
        return -1;
    }

    ret = write(fd, &BME280_TEMPERATURE_REGISTER, 1);
    if (ret < 0) {
        perror("Failed to write temperature register");
        return -1;
    }

    usleep(5000);

    ret = read(fd, buffer, 3);
    if (ret < 0) {
        perror("Failed to read temperature data");
        return -1;
    }

    *temperature = (double)((buffer[0] << 16) | (buffer[1] << 8) | buffer[2]) / 16384.0;
    *temperature -= (double)(calibration_data[1] * 16384.0) / 16384.0;
    *temperature = *temperature * (1 + (double)(calibration_data[2] * 16384.0) / 16384.0);
    *temperature = *temperature * (1 + (double)(calibration_data[3] * 16384.0) / 16384.0);
    *temperature = *temperature * (1 + (double)(calibration_data[4] * 16384.0) / 16384.0);
    *temperature = *temperature * (1 + (double)(calibration_data[5] * 16384.0) / 16384.0);
    *temperature = *temperature * (1 + (double)(calibration_data[6] * 16384.0) / 16384.0);
