    *temperature = *temperature * (1 + (double)(calibration_data[11] * 16384.0) / 16384.0);
    *temperature = *temperature * (1 + (double)(calibration_data[12] * 16384.0) / 16384.0);
    *temperature = *temperature * (1 + (double)(calibration_data[13] * 16384.0) / 16384.0);
