#include <linux/i2c-dev.h>
#include <libgpiod/libgpiod.h>
#include <pthread.h>

#define I2C_BUS 1
#define I2C_ADDR 0x77
#define BMP180_ADDR 0x77
#define GPIO_ALERT 24
#define BUFFER_SIZE 120  // 60 seconds * 2 readings per second
#define THRESHOLD_HPA 5
#define TIMER_INTERVAL_MS 50

typedef struct {
    uint32_t pressure;
    time_t timestamp;
} Sample;

typedef struct {
    Sample buffer[BUFFER_SIZE];
    int head;
    int tail;
    int count;
    pthread_mutex_t mutex;
} CircularBuffer;

CircularBuffer buffer;
pthread_t timer_thread;
int i2c_fd = -1;
struct gpiod_line *alert_line = NULL;
int running = 1;

void handle_sigint(int sig) {
    running = 0;
    pthread_join(timer_thread, NULL);
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (alert_line) {
        gpiod_line_release(alert_line);
    }
    printf("Cleanup complete.\n");
    exit(EXIT_SUCCESS);
}

void init_i2c() {
    char bus_path[32];
    snprintf(bus_path, sizeof(bus_path), "/dev/i2c-%d", I2C_BUS);
    i2c_fd = open(bus_path, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_TEN, 0) < 0) {
        perror("Failed to set I2C to 10-bit addressing");
