uint8_t i2c_read_byte(uint8_t reg, int fd) {
    uint8_t buffer[1];
    buffer[0] = reg;
    if (write(fd, buffer, 1) != 1) {
        perror("I2C write failed");
        exit(EXIT_FAILURE);
