    FILE *log_file;
    int running;
} app_state;

void handle_signal(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        app_state *state = (app_state *)malloc(sizeof(app_state));
        if (state) {
            state->running = 0;
        }
    }
}

void log_temperature(FILE *log_file, const char *timestamp, double temp, int duty) {
    if (log_file) {
        fprintf(log_file, "%s, %.1f, %d\n", timestamp, temp, duty);
        fflush(log_file);
    }
}

int map_temp_to_duty(double temp) {
    if (temp < TEMP_MIN) {
        return DUTY_MIN;
    } else if (temp > TEMP_MAX) {
        return DUTY_MAX;
    } else {
        double range = TEMP_MAX - TEMP_MIN;
        double duty_range = DUTY_MAX - DUTY_MIN;
        return (int)(DUTY_MIN + (temp - TEMP_MIN) * duty_range / range);
    }
}

void init_pwm(int *pwm_fd) {
    struct gpiod_line *line;
    struct gpiod_line_request_config req_config;
    struct gpiod_line_request_config *config = &req_config;

    *pwm_fd = -1;

    line = gpiod_line_get(PWM_PIN, "gpio");
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line %d\n", PWM_PIN);
        return;
    }

    config->consumer = "fan_pwm";
    config->flags = GPIOD_LINE_REQUEST_FLAG_ACTIVE_LOW;
    config->output = 1;
    config->value = 0;

    if (gpiod_line_request_config(line, config) < 0) {
        fprintf(stderr, "Failed to request GPIO line %d\n", PWM_PIN);
        gpiod_line_put(line);
        return;
    }

    *pwm_fd = gpiod_line_get_fd(line);
    if (*pwm_fd < 0) {
        fprintf(stderr, "Failed to get file descriptor for GPIO line %d\n", PWM_PIN);
        gpiod_line_put(line);
        return;
    }

    if (ioctl(*pwm_fd, PWM_SET_DUTY, DUTY_MIN) < 0) {
        fprintf(stderr, "Failed to set initial PWM duty cycle\n");
        close(*pwm_fd);
        *pwm_fd = -1;
        gpiod_line_put(line);
        return;
    }

    if (ioctl(*pwm_fd, PWM_SET_PERIOD, 1000000 / PWM_FREQ_HZ) < 0) {
        fprintf(stderr, "Failed to set PWM period\n");
        close(*pwm_fd);
        *pwm_fd = -1;
        gpiod_line_put(line);
        return;
    }

    if (ioctl(*pwm_fd, PWM_SET_POLARITY, PWM_POLARITY_NORMAL) < 0) {
        fprintf(stderr, "Failed to set PWM polarity\n");
        close(*pwm_fd);
        *pwm_fd = -1;
        gpiod_line_put(line);
        return;
    }

    if (ioctl(*pwm_fd, PWM_SET_DUTY, DUTY_MIN) < 0) {
        fprintf(stderr, "Failed to set initial PWM duty cycle\n");
        close(*pwm_fd);
        *pwm_fd = -1;
        gpiod_line_put(line);
        return;
    }
}

void cleanup_pwm(int pwm_fd) {
    if (pwm_fd >= 0) {
        ioctl(pwm_fd, PWM_SET_DUTY, DUTY_MIN);
        close(pwm_fd);
    }
}

void cleanup_log(FILE *log_file) {
    if (log_file) {
        fclose(log_file);
    }
}

int main() {
    app_state state = {0};
    struct timeval tv;
    char timestamp[64];
    double temp;
    int duty;
    int pwm_fd = -1;
    FILE *log_file = NULL;
    int running = 1;

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if (gpiod_init() < 0) {
        fprintf(stderr, "Failed to initialize libgpiod\n");
        return 1;
    }

    if (init_pwm(&pwm_fd) < 0) {
        fprintf(stderr, "Failed to initialize PWM\n");
        gpiod_exit();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        cleanup_pwm(pwm_fd);
        gpiod_exit();
        return 1;
    }

    gettimeofday(&tv, NULL);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&tv.tv_sec));
    fprintf(log_file, "Timestamp, Temperature (°C), Duty Cycle\n");
    fprintf(log_file, "%s, N/A, N/A\n", timestamp);
    fflush(log_file);

    while (running) {
        FILE *temp_file = fopen(TEMP_FILE, "r");
        if (!temp_file) {
            fprintf(stderr, "Failed to read temperature: %s\n", strerror(errno));
            usleep(100000);
            continue;
        }

        if (fscanf(temp_file, "%lf", &temp) != 1) {
            fprintf(stderr, "Failed to parse temperature\n");
            fclose(temp_file);
            usleep(100000);
            continue;
        }

        fclose(temp_file);

        duty = map_temp_to_duty(temp);

        if (ioctl(pwm_fd, PWM_SET_DUTY, duty) < 0) {
            fprintf(stderr, "Failed to set PWM duty cycle\n");
            usleep(100000);
            continue;
        }

        gettimeofday(&tv, NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&tv.tv_sec));
        log_temperature(log_file, timestamp, temp, duty);

        usleep(500000); // 500ms
    }

    cleanup_pwm(pwm_fd);
    cleanup_log(log_file);
    gpiod_exit();

    return 0;
}
