#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <pthread.h>
#include <sys/ioctl.h>
#include <fcntl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <signal.h>

#define I2C_BUS 1
#define I2C_ADDR 0x48
#define BUFFER_SIZE 60
#define TEMP_THRESHOLD 28.0
#define LED_PIN 18

typedef struct {
    double buffer[BUFFER_SIZE];
    int head;
    int count;
    pthread_mutex_t mutex;
} CircularBuffer;

CircularBuffer cb;
pthread_t alert_thread;
int i2c_fd = -1;
struct gpiod_line *led_line = NULL;
volatile int running = 1;

void log_error(const char *msg) {
    fprintf(stderr, "Error: %s\n", msg);
}

void log_warning(const char *msg) {
    fprintf(stderr, "Warning: %s\n", msg);
}

int init_i2c() {
    char bus_path[32];
    snprintf(bus_path, sizeof(bus_path), "/dev/i2c-%d", I2C_BUS);
    i2c_fd = open(bus_path, O_RDWR);
    if (i2c_fd < 0) {
        log_error("Failed to open I2C bus");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        log_error("Failed to set I2C slave address");
        close(i2c_fd);
        return -1;
    }

    return 0;
}

int init_gpio() {
    struct gpiod_chip *chip;
    chip = gpiod_chip_open("/dev/gpiochip4");
    if (!chip) {
        log_error("Failed to open GPIO chip");
        return -1;
    }

    led_line = gpiod_line_get(chip, LED_PIN);
    if (!led_line) {
        log_error("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(led_line, "alert_led", 0) < 0) {
        log_error("Failed to request GPIO line as output");
        gpiod_line_put(led_line);
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

void cleanup() {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }

    if (led_line) {
        gpiod_line_put(led_line);
    }

    if (cb.mutex) {
        pthread_mutex_destroy(&cb.mutex);
    }
}

void signal_handler(int sig) {
    running = 0;
}

void *alert_thread_func(void *arg) {
    while (running) {
        pthread_mutex_lock(&cb.mutex);
        double avg = 0.0;
        for (int i = 0; i < cb.count; i++) {
            avg += cb.buffer[i];
        }
        avg /= cb.count;
        pthread_mutex_unlock(&cb.mutex);

        if (avg > TEMP_THRESHOLD) {
            gpiod_line_set_value(led_line, 1);
        } else {
            gpiod_line_set_value(led_line, 0);
        }
        usleep(100000); // 100ms delay to avoid rapid toggling
    }
    return NULL;
}

void read_temperature() {
    unsigned char reg = 0x00; // Temperature register
    unsigned char data[2] = {0};

    if (write(i2c_fd, &reg, 1) < 0) {
        log_error("I2C write failed");
        return;
    }

    if (read(i2c_fd, data, 2) < 0) {
        log_error("I2C read failed");
        return;
    }

    int temp = (data[0] << 8) | data[1];
    double temperature = (double)temp / 256.0;

    pthread_mutex_lock(&cb.mutex);
    cb.buffer[cb.head] = temperature;
    cb.head = (cb.head + 1) % BUFFER_SIZE;
    cb.count = (cb.count < BUFFER_SIZE) ? cb.count + 1 : BUFFER_SIZE;
    pthread_mutex_unlock(&cb.mutex);
}

int main() {
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        log_error("Failed to set signal handler");
        return 1;
    }

    if (pthread_mutex_init(&cb.mutex, NULL) != 0) {
        log_error("Failed to initialize mutex");
        return 1;
    }

    cb.head = 0;
    cb.count = 0;

    if (init_i2c() < 0) {
        log_error("I2C initialization failed");
        cleanup();
        return 1;
    }

    if (init_gpio() < 0) {
        log_error("GPIO initialization failed");
        cleanup();
        return 1;
    }

    if (pthread_create(&alert_thread, NULL, alert_thread_func, NULL) != 0) {
        log_error("Failed to create alert thread");
        cleanup();
        return 1;
    }

    while (running) {
        read_temperature();
        usleep(1000000); // 1 second delay
    }

    pthread_join(alert_thread, NULL);
    cleanup();
    return 0;
}

