    double output;
    pid_config config;
    int running;
} system_state;

system_state sys;

void handle_sigint(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        sys.running = 0;
        printf("Received signal, shutting down...\n");
        // Turn off heater
        if (sys.pwm_fd >= 0) {
            ioctl(sys.pwm_fd, PWM_SET_DUTY, 0);
            close(sys.pwm_fd);
        }
        // Close SPI
        if (sys.fd >= 0) {
            close(sys.fd);
        }
        exit(EXIT_SUCCESS);
    }
}

void setup_gpio() {
    int fd = open("/dev/gpiochip0", O_RDWR);
    if (fd < 0) {
        perror("Failed to open gpiochip0");
        exit(EXIT_FAILURE);
    }

    if (ioctl(fd, GPIO_GET_CHIPINFO, &sys.pwm_channel) < 0) {
        perror("Failed to get GPIO chip info");
        close(fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(fd, GPIO_GET_LINEHANDLE, &sys.pwm_channel) < 0) {
        perror("Failed to get line handle");
        close(fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(sys.pwm_channel.fd, GPIO_LINE_SET_FLAGS, GPIO_LINE_FLAG_OUTPUT) < 0) {
        perror("Failed to set GPIO line as output");
        close(sys.pwm_channel.fd);
        close(fd);
        exit(EXIT_FAILURE);
    }

    close(fd);
}

void setup_pwm() {
    sys.pwm_fd = open("/dev/pwm0", O_RDWR);
    if (sys.pwm_fd < 0) {
        perror("Failed to open PWM device");
        exit(EXIT_FAILURE);
    }

    if (ioctl(sys.pwm_fd, PWM_SET_FREQUENCY, sys.pwm_frequency) < 0) {
        perror("Failed to set PWM frequency");
        close(sys.pwm_fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(sys.pwm_fd, PWM_SET_RANGE, sys.pwm_range) < 0) {
        perror("Failed to set PWM range");
        close(sys.pwm_fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(sys.pwm_fd, PWM_SET_DUTY, 0) < 0) {
        perror("Failed to set initial PWM duty");
        close(sys.pwm_fd);
        exit(EXIT_FAILURE);
    }
}

void setup_spi() {
    sys.fd = open(SPI_DEVICE, O_RDWR);
    if (sys.fd < 0) {
        perror("Failed to open SPI device");
        exit(EXIT_FAILURE);
    }

    if (ioctl(sys.fd, SPI_IOC_WR_MODE, &sys.spi_mode) < 0) {
        perror("Failed to set SPI mode");
        close(sys.fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(sys.fd, SPI_IOC_WR_SPEED_HZ, &sys.spi_speed) < 0) {
        perror("Failed to set SPI speed");
        close(sys.fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(sys.fd, SPI_IOC_WR_BITS_PER_WORD, &sys.spi_bits_per_word) < 0) {
        perror("Failed to set SPI bits per word");
        close(sys.fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(sys.fd, SPI_IOC_WR_CS_HIGH, &sys.spi_cs) < 0) {
        perror("Failed to set SPI chip select");
        close(sys.fd);
        exit(EXIT_FAILURE);
    }
}

void read_rtd() {
    uint8_t tx[3] = {0x01, 0x00, 0x00};
    uint8_t rx[3] = {0};

    struct spi_ioc_transfer spi = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .delay_usecs = 0,
        .speed_hz = sys.spi_speed,
        .bits_per_word = sys.spi_bits_per_word,
    };

    if (ioctl(sys.fd, SPI_IOC_MESSAGE(1), &spi) < 0) {
        perror("SPI read failed");
        exit(EXIT_FAILURE);
    }

    uint16_t raw = (rx[0] << 8) | rx[1];
    double rtd_resistance = (raw * 430.0) / 16384.0;

    if (rtd_resistance < 0 || rtd_resistance > 10000) {
        fprintf(stderr, "Invalid RTD resistance: %f ohms\n", rtd_resistance);
        exit(EXIT_FAILURE);
    }

    double temperature = (rtd_resistance - 100.0) / (100.0 / 3.9083) * 100.0;
    if (temperature > MAX_TEMP) {
        fprintf(stderr, "Temperature exceeds safe limit: %.2f°C\n", temperature);
        exit(EXIT_FAILURE);
    }

    return temperature;
}

void pid_update(double current_temp) {
    double error = sys.config.target_temp - current_temp;
    sys.integral += error * PID_SAMPLE_TIME / 1e6;
    double derivative = (error - sys.previous_error) / (PID_SAMPLE_TIME / 1e6);

    double output = sys.config.kp * error + sys.config.ki * sys.integral + sys.config.kd * derivative;

    if (output > 1000.0) output = 1000.0;
    if (output < 0.0) output = 0.0;

    sys.output = output;
    sys.previous_error = error;
}

void apply_pwm() {
    if (ioctl(sys.pwm_fd, PWM_SET_DUTY, sys.output) < 0) {
        perror("Failed to set PWM duty");
        exit(EXIT_FAILURE);
    }
}

void load_config(const char *filename) {
    FILE *fp = fopen(filename, "r");
    if (!fp) {
        fprintf(stderr, "Failed to open config file\n");
        exit(EXIT_FAILURE);
    }

    json_error_t error;
    json_t *root = json_load_file(filename, 0, &error);
    if (!root) {
        fprintf(stderr, "Error parsing JSON: %s\n", error.text);
        exit(EXIT_FAILURE);
    }

    json_t *target_temp = json_object_get(root, "target_temp");
    if (target_temp && json_is_number(target_temp)) {
        sys.config.target_temp = json_number_value(target_temp);
    } else {
        sys.config.target_temp = DEFAULT_TARGET_TEMP;
    }

    json_t *kp = json_object_get(root, "kp");
    if (kp && json_is_number(kp)) {
        sys.config.kp = json_number_value(kp);
    } else {
        sys.config.kp = DEFAULT_KP;
    }

    json_t *ki = json_object_get(root, "ki");
    if (ki && json_is_number(ki)) {
        sys.config.ki = json_number_value(ki);
    } else {
        sys.config.ki = DEFAULT_KI;
    }

    json_t *kd = json_object_get(root, "kd");
    if (kd && json_is_number(kd)) {
        sys.config.kd = json_number_value(kd);
    } else {
        sys.config.kd = DEFAULT_KD;
    }

    json_decref(root);
    fclose(fp);
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <config_file>\n", argv[0]);
        exit(EXIT_FAILURE);
    }

    sys.spi_mode = SPI_MODE_1;
    sys.spi_speed = 500000;
    sys.spi_bits_per_word = 16;
    sys.spi_cs = 0;
    sys.pwm_frequency = PWM_FREQUENCY;
    sys.pwm_range = PWM_RANGE;

    setup_gpio();
    setup_pwm();
    setup_spi();

    load_config(argv[1]);

    sys.last_error = 0.0;
    sys.integral = 0.0;
    sys.previous_error = 0.0;
    sys.output = 0.0;
    sys.running = 1;

    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigint);

    while (sys.running) {
        double current_temp = read_rtd();
        pid_update(current_temp);
        apply_pwm();
        usleep(PID_SAMPLE_TIME);
    }

    if (sys.pwm_fd >= 0) {
        ioctl(sys.pwm_fd, PWM_SET_DUTY, 0);
        close(sys.pwm_fd);
    }

    if (sys.fd >= 0) {
        close(sys.fd);
    }

    return 0;
}
