void init_i2c() {
    char i2c_bus_path[32];
    snprintf(i2c_bus_path, sizeof(i2c_bus_path), "/dev/i2c-%d", I2C_BUS);
    i2c_fd = open(i2c_bus_path, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_TEN, 0) < 0) {
        perror("Failed to set I2C to 10-bit mode");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BMP180_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
}

void read_calibration_data() {
    uint8_t reg = BMP180_CALIBRATION_REGISTER;
    if (write(i2c_fd, &reg, 1) < 0) {
        perror("Failed to write calibration register");
        exit(EXIT_FAILURE);
    }

    uint8_t data[2 * BMP180_CALIBRATION_WORDS];
    if (read(i2c_fd, data, sizeof(data)) < 0) {
        perror("Failed to read calibration data");
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < BMP180_CALIBRATION_WORDS; i++) {
        int16_t val = (data[2 * i] << 8) | data[2 * i + 1];
        printf("Calibration word %d: %d\n", i, val);
    }
}

void init_fan() {
    struct gpiod_chip *chip;
    chip = gpiod_chip_open_by_number(4); // BCM GPIOs are on chip 4
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    fan_line = gpiod_line_get(chip, FAN_GPIO);
    if (!fan_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(fan_line, "fan", 0) < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_line_release(fan_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    gpiod_line_set_value(fan_line, 0);
}

void update_sensor_readings() {
    pthread_mutex_lock(&buffer_mutex);
    if (buffer.full) {
        buffer.tail = (buffer.tail + 1) % CIRCULAR_BUFFER_SIZE;
    }
    buffer.head = (buffer.head + 1) % CIRCULAR_BUFFER_SIZE;
    buffer.full = (buffer.head == buffer.tail) ? 1 : 0;

    time_t now = time(NULL);
    buffer.buffer[buffer.tail].timestamp = now;
    buffer.buffer[buffer.tail].temperature = 0.0;
    buffer.buffer[buffer.tail].pressure = 0.0;

    pthread_mutex_unlock(&buffer_mutex);
}

void print_sensor_reading(sensor_reading_t *reading) {
    char time_str[64];
    struct tm *tm_info = localtime(&reading->timestamp);
    strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm_info);
    printf("[%s] Temp: %.2f°C, Pressure: %.2f hPa\n", time_str, reading->temperature, reading->pressure);
}

void* timer_callback(void *arg) {
    while (running) {
        usleep(500000); // 500 ms

        if (!running) break;

        // Read temperature
        uint8_t cmd = 0xF4;
        if (write(i2c_fd, &cmd, 1) < 0) {
            perror("Failed to write temperature command");
            continue;
        }

        usleep(50000); // Wait for measurement

        uint8_t data[2];
        if (read(i2c_fd, data, sizeof(data)) < 0) {
            perror("Failed to read temperature data");
            continue;
        }

        int16_t raw_temp = (data[0] << 8) | data[1];
        double temp = (raw_temp / 4.0) - 40.0;
        printf("Raw Temp: %d, Calculated Temp: %.2f°C\n", raw_temp, temp);

        // Read pressure
        cmd = 0xF4;
        if (write(i2c_fd, &cmd, 1) < 0) {
            perror("Failed to write pressure command");
            continue;
        }

        usleep(50000); // Wait for measurement

        data[0] = 0xF6;
        if (write(i2c_fd, &data[0], 1) < 0) {
            perror("Failed to write pressure command");
            continue;
        }

        usleep(50000); // Wait for measurement

        data[0] = 0xF7;
        if (read(i2c_fd, data, sizeof(data)) < 0) {
            perror("Failed to read pressure data");
            continue;
        }

        int32_t raw_press = (data[0] << 16) | (data[1] << 8) | data[2];
        double pressure = (raw_press / 256.0) / 100.0;
        printf("Raw Press: %d, Calculated Press: %.2f hPa\n", raw_press, pressure);

        // Update buffer
        update_sensor_readings();

        // Print latest reading
        sensor_reading_t *latest = &buffer.buffer[buffer.tail];
        latest->temperature = temp;
        latest->pressure = pressure;
        print_sensor_reading(latest);

        // Fan control
        if (temp > TEMPERATURE_THRESHOLD) {
            gpiod_line_set_value(fan_line, 1);
        } else {
            gpiod_line_set_value(fan_line, 0);
        }
    }

    return NULL;
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    init_i2c();
    read_calibration_data();
    init_fan();

    buffer.head = 0;
    buffer.tail = 0;
    buffer.full = 0;

    if (pthread_create(&timer_thread, NULL, timer_callback, NULL) != 0) {
        perror("Failed to create timer thread");
        exit(EXIT_FAILURE);
    }

    pthread_join(timer_thread, NULL);

    return 0;
}

