#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/pwm.h>
#include <gpiod.h>

#define PWM_CHANNEL_RED 0
#define PWM_CHANNEL_GREEN 1
#define PWM_CHANNEL_BLUE 2

#define GPIO_RED 17
#define GPIO_GREEN 18
#define GPIO_BLUE 27

volatile sig_atomic_t exit_flag = 0;

typedef struct {
    struct gpiod_line *red_line;
    struct gpiod_line *green_line;
    struct gpiod_line *blue_line;
} gpio_lines;

void handle_signal(int signo) {
    exit_flag = 1;
}

int setup_pwm(gpio_lines *gpio) {
    struct gpiod_line_config config;
    struct gpiod_line *line;

    // Red
    memset(&config, 0, sizeof(config));
    config.consumer = "rgb_led";
    config.direction = GPIOD_LINE_DIRECTION_OUTPUT;
    config.flags = GPIOD_LINE_FLAG_ACTIVE_LOW;
    line = gpiod_line_get(GPIO_RED, &config);
    if (!line) {
        fprintf(stderr, "Failed to get red GPIO line\n");
        return -1;
    }
    gpio->red_line = line;

    // Green
    memset(&config, 0, sizeof(config));
    config.consumer = "rgb_led";
    config.direction = GPIOD_LINE_DIRECTION_OUTPUT;
    config.flags = GPIOD_LINE_FLAG_ACTIVE_LOW;
    line = gpiod_line_get(GPIO_GREEN, &config);
    if (!line) {
        fprintf(stderr, "Failed to get green GPIO line\n");
        gpiod_line_put(gpio->red_line);
        return -1;
    }
    gpio->green_line = line;

    // Blue
    memset(&config, 0, sizeof(config));
    config.consumer = "rgb_led";
    config.direction = GPIOD_LINE_DIRECTION_OUTPUT;
    config.flags = GPIOD_LINE_FLAG_ACTIVE_LOW;
    line = gpiod_line_get(GPIO_BLUE, &config);
    if (!line) {
        fprintf(stderr, "Failed to get blue GPIO line\n");
        gpiod_line_put(gpio->red_line);
        gpiod_line_put(gpio->green_line);
        return -1;
    }
    gpio->blue_line = line;

    return 0;
}

void cleanup_pwm(gpio_lines *gpio) {
    gpiod_line_put(gpio->red_line);
    gpiod_line_put(gpio->green_line);
    gpiod_line_put(gpio->blue_line);
}

void set_pwm_value(struct gpiod_line *line, int value) {
    if (gpiod_line_set_value(line, value) < 0) {
        fprintf(stderr, "Failed to set PWM value for line\n");
        exit(EXIT_FAILURE);
    }
}

void set_rgb_color(int red, int green, int blue) {
    set_pwm_value(gpio->red_line, red);
    set_pwm_value(gpio->green_line, green);
    set_pwm_value(gpio->blue_line, blue);
}

int main() {
    gpio_lines gpio;
    FILE *temp_file;
    char temp_path[] = "/sys/class/thermal/thermal_zone0/temp";
    int temp_value;
    int red, green, blue;
    struct timespec sleep_time = {0, 500000000}; // 0.5 seconds

    if (signal(SIGINT, handle_signal) == SIG_ERR) {
        fprintf(stderr, "Failed to set up signal handler\n");
        exit(EXIT_FAILURE);
    }
    if (signal(SIGTERM, handle_signal) == SIG_ERR) {
        fprintf(stderr, "Failed to set up signal handler\n");
        exit(EXIT_FAILURE);
    }

    if (setup_pwm(&gpio) < 0) {
        exit(EXIT_FAILURE);
    }

    temp_file = fopen(temp_path, "r");
    if (!temp_file) {
        fprintf(stderr, "Failed to open temperature file\n");
        cleanup_pwm(&gpio);
        exit(EXIT_FAILURE);
    }

    while (!exit_flag) {
        if (fscanf(temp_file, "%d", &temp_value) != 1) {
            if (ferror(temp_file)) {
                fprintf(stderr, "Error reading temperature file\n");
                clearerr(temp_file);
            }
            // Skip this cycle
            nanosleep(&sleep_time, NULL);
            continue;
        }

        // Convert to millidegrees Celsius
        temp_value /= 1000;
        temp_value *= 1000;

        // Determine color based on temperature
        if (temp_value < 40000) {
            red = 0;
            green = 0;
            blue = 255;
        } else if (temp_value < 60000) {
            red = 0;
            green = 255;
            blue = 0;
        } else {
            red = 255;
            green = 0;
            blue = 0;
        }

        set_rgb_color(red, green, blue);

        printf("Temperature: %d m°C | Red: %d | Green: %d | Blue: %d\n", temp_value, red, green, blue);
        fflush(stdout);

        nanosleep(&sleep_time, NULL);
    }

    fclose(temp_file);
    cleanup_pwm(&gpio);

    return 0;
}

