            green = 0;
            blue = 0;
        }

        set_rgb_color(red, green, blue);

        printf("Temperature: %d m°C | Red: %d | Green: %d | Blue: %d\n", temp_value, red, green, blue);
        fflush(stdout);

        nanosleep(&sleep_time, NULL);
    }

    fclose(temp_file);
    cleanup_pwm(&gpio);

    return 0;
}
