    struct sockaddr_in server_addr;
    int retry_count;
    state_t state;
    int humidity;
    int temperature;
    int checksum;
    int data[5];
} app_state_t;

void signal_handler(int signum) {
    printf("Caught signal %d, exiting...\n", signum);
    exit(EXIT_SUCCESS);
}

int dht22_read_data(gpiod_line *line, int *humidity, int *temperature, int *checksum) {
    int data[5] = {0};
    int i;
    int bit;
    int timeout = 1000000; // 1 second timeout

    // Pull line low for 18ms
    gpiod_line_set_value(line, 0);
    usleep(18000);

    // Release line
    gpiod_line_set_value(line, 1);
    usleep(20);

    // Wait for response
    for (i = 0; i < 40; i++) {
        // Wait for line to go low
        while (gpiod_line_get_value(line) == 1 && timeout > 0) {
            usleep(1);
            timeout--;
        }

        if (timeout <= 0) {
            return -1;
        }

        // Read the bit
        usleep(1);
        bit = gpiod_line_get_value(line);

        // Wait for line to go high again
        while (gpiod_line_get_value(line) == 0 && timeout > 0) {
            usleep(1);
            timeout--;
        }

        if (timeout <= 0) {
            return -1;
        }

        data[i / 8] |= (bit << (7 - (i % 8)));
    }

    *humidity = data[0];
    *temperature = data[1];
    *checksum = data[4];

    return 0;
}

int send_http_request(int sock, const char *url, int humidity, int temperature) {
    char request[256];
    snprintf(request, sizeof(request), "GET %s HTTP/1.1\r\nHost: %s\r\nConnection: close\r\n\r\n", url, SERVER_IP);

    if (send(sock, request, strlen(request), 0) < 0) {
        perror("send");
        return -1;
    }

