    app.sock = socket(AF_INET, SOCK_STREAM, 0);
    if (app.sock < 0) {
        perror("socket");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    app.server_addr.sin_family = AF_INET;
    app.server_addr.sin_port = htons(SERVER_PORT);
    if (inet_pton(AF_INET, SERVER_IP, &app.server_addr.sin_addr) <= 0) {
        perror("inet_pton");
        close(app.sock);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Main loop
    while (retry_count < MAX_RETRIES) {
        app.state = STATE_IDLE;
        app.retry_count = retry_count;

        // Reset GPIO
        gpiod_line_set_value(line, 1);
        usleep(1000);

        // Read data from DHT22
        if (dht22_read_data(line, &humidity, &temperature, &checksum) == 0) {
            if (checksum == (humidity + temperature)) {
                // Valid data
                app.state = STATE_SEND;
                success = 1;
                break;
            } else {
                printf("Checksum mismatch: expected %d, got %d\n", humidity + temperature, checksum);
                retry_count++;
                usleep(100000);
                continue;
            }
        } else {
            printf("Failed to read from DHT22 sensor\n");
            retry_count++;
            usleep(100000);
            continue;
        }
    }

    if (success) {
        // Connect to server
        if (connect(app.sock, (struct sockaddr *)&app.server_addr, sizeof(app.server_addr)) < 0) {
            perror("connect");
            close(app.sock);
            gpiod_line_release(line);
            gpiod_chip_close(chip);
            exit(EXIT_FAILURE);
        }

        // Send HTTP request
        if (send_http_request(app.sock, URL, humidity, temperature) < 0) {
            perror("send_http_request");
        }

        // Close socket
        close(app.sock);
    }

    // Release resources
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return 0;
}

