#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <time.h>

#define I2C_BUS 1
#define BMP180_ADDR 0x77
#define OSS 3
#define LOG_FILE "pressure_log.txt"
#define DEBOUNCE_DELAY_US 200000
#define PRESSURE_READ_INTERVAL_S 2
#define CONVERSION_DELAY_MS 26

typedef struct {
    int i2c_fd;
    struct gpiod_line *button_line;
    int log_enabled;
    int last_interrupt_time;
    int calibration_data[12];
    int ac1, ac2, ac3, ac4, ac5, ac6, b1, b2, mb, mc, md;
    int pressure;
    int temperature;
} bmp180_state;

void handle_signal(int sig) {
    if (sig == SIGINT) {
        printf("Received SIGINT, cleaning up...\n");
        if (signal(SIGINT, handle_signal) == SIG_ERR) {
            perror("signal");
        }
        exit(EXIT_SUCCESS);
    }
}

void i2c_read_bytes(int fd, uint8_t reg, uint8_t *buf, int len) {
    uint8_t cmd[1];
    cmd[0] = reg;
    if (ioctl(fd, I2C_SLAVE, BMP180_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        exit(EXIT_FAILURE);
    }
    if (write(fd, cmd, 1) != 1) {
        perror("Failed to write I2C command");
        exit(EXIT_FAILURE);
    }
    if (read(fd, buf, len) != len) {
        perror("Failed to read I2C data");
        exit(EXIT_FAILURE);
    }
}

void i2c_write_bytes(int fd, uint8_t reg, uint8_t *buf, int len) {
    uint8_t cmd[len + 1];
    cmd[0] = reg;
    memcpy(cmd + 1, buf, len);
    if (ioctl(fd, I2C_SLAVE, BMP180_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        exit(EXIT_FAILURE);
    }
    if (write(fd, cmd, len + 1) != len + 1) {
        perror("Failed to write I2C data");
        exit(EXIT_FAILURE);
    }
}

void read_calibration_data(bmp180_state *state) {
    uint8_t cal_data[24];
    i2c_read_bytes(state->i2c_fd, 0xAA, cal_data, 24);

    state->calibration_data[0] = (cal_data[0] << 8) | cal_data[1];
    state->calibration_data[1] = (cal_data[2] << 8) | cal_data[3];
    state->calibration_data[2] = (cal_data[4] << 8) | cal_data[5];
    state->calibration_data[3] = (cal_data[6] << 8) | cal_data[7];
    state->calibration_data[4] = (cal_data[8] << 8) | cal_data[9];
    state->calibration_data[5] = (cal_data[10] << 8) | cal_data[11];
    state->calibration_data[6] = (cal_data[12] << 8) | cal_data[13];
    state->calibration_data[7] = (cal_data[14] << 8) | cal_data[15];
    state->calibration_data[8] = (cal_data[16] << 8) | cal_data[17];
    state->calibration_data[9] = (cal_data[18] << 8) | cal_data[19];
    state->calibration_data[10] = (cal_data[20] << 8) | cal_data[21];
    state->calibration_data[11] = (cal_data[22] << 8) | cal_data[23];

    state->ac1 = state->calibration_data[0];
    state->ac2 = state->calibration_data[1];
    state->ac3 = state->calibration_data[2];
    state->ac4 = state->calibration_data[3];
    state->ac5 = state->calibration_data[4];
    state->ac6 = state->calibration_data[5];
    state->b1 = state->calibration_data[6];
    state->b2 = state->calibration_data[7];
    state->mb = state->calibration_data[8];
    state->mc = state->calibration_data[9];
    state->md = state->calibration_data[10];
}

void start_pressure_measurement(bmp180_state *state) {
    uint8_t cmd[2];
    cmd[0] = 0xF4;
    cmd[1] = 0x28 | (OSS << 6); // 0x28 = 0b101000, OSS=3
    i2c_write_bytes(state->i2c_fd, 0xF4, cmd, 2);
}

