void handle_signal(int sig) {
    if (sig == SIGINT) {
        printf("Received SIGINT, cleaning up...\n");
        if (signal(SIGINT, handle_signal) == SIG_ERR) {
            perror("signal");
        }
        exit(EXIT_SUCCESS);
    }
}

void i2c_read_bytes(int fd, uint8_t reg, uint8_t *buf, int len) {
    uint8_t cmd[1];
    cmd[0] = reg;
    if (ioctl(fd, I2C_SLAVE, BMP180_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        exit(EXIT_FAILURE);
    }
    if (write(fd, cmd, 1) != 1) {
        perror("Failed to write I2C command");
        exit(EXIT_FAILURE);
    }
    if (read(fd, buf, len) != len) {
        perror("Failed to read I2C data");
        exit(EXIT_FAILURE);
    }
}

void i2c_write_bytes(int fd, uint8_t reg, uint8_t *buf, int len) {
    uint8_t cmd[len + 1];
    cmd[0] = reg;
    memcpy(cmd + 1, buf, len);
    if (ioctl(fd, I2C_SLAVE, BMP180_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        exit(EXIT_FAILURE);
    }
    if (write(fd, cmd, len + 1) != len + 1) {
        perror("Failed to write I2C data");
        exit(EXIT_FAILURE);
    }
}

