#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <curl/curl.h>
#include <libgpiod.h>
#include <time.h>

#define GPIO_PIN 4
#define MAX_RETRIES 3
#define POST_RETRY_COUNT 3
#define READ_INTERVAL 10
#define URL_DEFAULT "http://your-the-librarys-API-call.com/api/humidity"

typedef struct {
    char url[256];
} Config;

Config config = { .url = URL_DEFAULT };

void log_message(const char *fmt, ...) {
    va_list args;
    va_start(args, fmt);
    vsyslog(LOG_INFO, fmt, args);
    va_end(args);
}

void signal_handler(int signum) {
    log_message("Received signal %d, shutting down...", signum);
    exit(EXIT_SUCCESS);
}

int read_dht22(gpiod_line *line, uint8_t *data) {
    int ret;
    int timeout = 0;
    int state = 0;
    int edge_count = 0;
    int bit = 0;
    int data_index = 0;

    // Pull line low for 1ms
    ret = gpiod_line_set_value(line, 0);
    if (ret < 0) {
        log_message("Failed to pull line low: %s", strerror(errno));
        return -1;
    }
    usleep(1000);

    // Pull line high for 20-40us
    ret = gpiod_line_set_value(line, 1);
    if (ret < 0) {
        log_message("Failed to pull line high: %s", strerror(errno));
        return -1;
    }
    usleep(40);

    // Release line
    ret = gpiod_line_set_value(line, 1);
    if (ret < 0) {
        log_message("Failed to release line: %s", strerror(errno));
        return -1;
    }

    // Wait for response
    while (timeout < 1000000) { // 1 second timeout
        usleep(1);
        int val = 0;
        ret = gpiod_line_get_value(line, &val);
        if (ret < 0) {
            log_message("Failed to read line value: %s", strerror(errno));
            return -1;
        }

        if (val != state) {
            state = val;
            edge_count++;
            if (edge_count == 1) {
                // Start of data
                continue;
            } else if (edge_count == 2) {
                // First bit
                data[bit++] = 0;
            } else if (edge_count > 2) {
                // Subsequent bits
                if (val == 0) {
                    data[bit++] |= 1 << (edge_count - 3);
                }
            }
        }

        if (bit >= 40) {
            break;
        }

        timeout++;
    }

    if (bit < 40) {
        log_message("Timeout waiting for DHT22 response");
        return -1;
    }

    // Check checksum
    uint8_t checksum = data[3] + data[4];
    if (data[0] + data[1] + data[2] != checksum) {
        log_message("DHT22 checksum failed");
        return -1;
    }

    // Extract humidity
    *data = data[0];
    return 0;
}

size_t write_callback(void *ptr, size_t size, size_t nmemb, void *userdata) {
    (void)userdata;
    return size * nmemb;
}

int post_data(const char *url, double humidity) {
    CURL *curl;
    CURLcode res;
    struct curl_slist *headers = NULL;
    char json[128];

    snprintf(json, sizeof(json), "{\"humidity\":%.1f}", humidity);

    curl = curl_easy_init();
    if (!curl) {
        log_message("Failed to initialize CURL");
        return -1;
    }

    headers = curl_slist_append(headers, "Content-Type: application/json");
    headers = curl_slist_append(headers, "Accept: application/json");

    curl_easy_setopt(curl, CURLOPT_URL, url);
    curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json);
    curl_easy_setopt(curl, CURLOPT_POSTFIELDSIZE, (long)strlen(json));
    curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);
    curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_callback);
    curl_easy_setopt(curl, CURLOPT_WRITEDATA, NULL);

    for (int i = 0; i < POST_RETRY_COUNT; i++) {
        res = curl_easy_perform(curl);
        if (res == CURLE_OK) {
            long http_code = 0;
            curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &http_code);
            if (http_code >= 200 && http_code < 300) {
                log_message("Successfully posted humidity data");
                break;
            } else {
                log_message("HTTP error %ld, retrying...", http_code);
                usleep(1000000); // 1 second delay
            }
        } else {
            log_message("CURL error: %s", curl_easy_strerror(res));
            usleep(1000000);
        }
    }

    curl_slist_free_all(headers);
    curl_easy_cleanup(curl);
    return res == CURLE_OK ? 0 : -1;
}

int main(int argc, char *argv[]) {
    gpiod_line *line;
    int ret;
    int retry_count = 0;
    double humidity = 0.0;
    struct sigaction sa;
    Config config = { .url = URL_DEFAULT };

    // Parse command line
    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "-s") == 0 && i + 1 < argc) {
            strncpy(config.url, argv[i + 1], sizeof(config.url));
            config.url[sizeof(config.url) - 1] = '\0';
            i++;
        }
    }

    // Initialize syslog
    openlog("dht22_monitor", LOG_PID | LOG_CONS, LOG_USER);

    // Set up signal handler
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        log_message("Failed to set up signal handler");
        closelog();
        exit(EXIT_FAILURE);
    }

    // Initialize libgpiod
    gpiod_ctx *ctx = gpiod_ctx_new();
    if (!ctx) {
        log_message("Failed to initialize libgpiod");
        closelog();
        exit(EXIT_FAILURE);
    }

    // Open line
    line = gpiod_line_get(ctx, GPIO_PIN, GPIOD_LINE_FLAG_ACTIVE_LOW);
    if (!line) {
        log_message("Failed to get GPIO line %d", GPIO_PIN);
        gpiod_ctx_free(ctx);
        closelog();
        exit(EXIT_FAILURE);
    }

    // Set line to input
    ret = gpiod_line_request_input(line, "dht22_monitor", GPIOD_LINE_REQUEST_FLAG_ACTIVE_LOW);
    if (ret < 0) {
        log_message("Failed to request line as input: %s", strerror(errno));
        gpiod_line_put(line);
        gpiod_ctx_free(ctx);
        closelog();
        exit(EXIT_FAILURE);
    }

    // Main loop
    while (1) {
        log_message("Starting DHT22 read...");
        for (retry_count = 0; retry_count < MAX_RETRIES; retry_count++) {
            uint8_t data[5];
            ret = read_dht22(line, data);
            if (ret == 0) {
                humidity = (double)data[0];
                log_message("Humidity: %.1f%%", humidity);
                break;
            } else {
                log_message("DHT22 read failed, retrying...");
                usleep(1000000); // 1 second delay
            }
        }

        if (retry_count >= MAX_RETRIES) {
            log_message("DHT22 read failed after %d retries", MAX_RETRIES);
            usleep(1000000 * READ_INTERVAL); // 10 seconds
            continue;
        }

        // Post data
        for (int i = 0; i < POST_RETRY_COUNT; i++) {
            if (post_data(config.url, humidity) == 0) {
                log_message("Data posted successfully");
                break;
            } else {
                log_message("Failed to post data, retrying...");
                usleep(1000000); // 1 second delay
            }
        }

        usleep(1000000 * READ_INTERVAL); // 10 seconds
    }

    // Cleanup
    gpiod_line_put(line);
    gpiod_ctx_free(ctx);
    closelog();
    curl_global_cleanup();

    return 0;
}

