    int ret;
    int retry_count = 0;
    double humidity = 0.0;
    struct sigaction sa;
    Config config = { .url = URL_DEFAULT };

    // Parse command line
    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "-s") == 0 && i + 1 < argc) {
            strncpy(config.url, argv[i + 1], sizeof(config.url));
            config.url[sizeof(config.url) - 1] = '\0';
            i++;
        }
    }

    // Initialize syslog
    openlog("dht22_monitor", LOG_PID | LOG_CONS, LOG_USER);

    // Set up signal handler
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        log_message("Failed to set up signal handler");
        closelog();
        exit(EXIT_FAILURE);
    }

    // Initialize libgpiod
    gpiod_ctx *ctx = gpiod_ctx_new();
    if (!ctx) {
        log_message("Failed to initialize libgpiod");
        closelog();
        exit(EXIT_FAILURE);
    }

    // Open line
    line = gpiod_line_get(ctx, GPIO_PIN, GPIOD_LINE_FLAG_ACTIVE_LOW);
    if (!line) {
        log_message("Failed to get GPIO line %d", GPIO_PIN);
        gpiod_ctx_free(ctx);
        closelog();
        exit(EXIT_FAILURE);
    }

    // Set line to input
    ret = gpiod_line_request_input(line, "dht22_monitor", GPIOD_LINE_REQUEST_FLAG_ACTIVE_LOW);
    if (ret < 0) {
        log_message("Failed to request line as input: %s", strerror(errno));
        gpiod_line_put(line);
        gpiod_ctx_free(ctx);
        closelog();
        exit(EXIT_FAILURE);
    }

    // Main loop
    while (1) {
        log_message("Starting DHT22 read...");
        for (retry_count = 0; retry_count < MAX_RETRIES; retry_count++) {
            uint8_t data[5];
            ret = read_dht22(line, data);
            if (ret == 0) {
                humidity = (double)data[0];
                log_message("Humidity: %.1f%%", humidity);
                break;
            } else {
                log_message("DHT22 read failed, retrying...");
                usleep(1000000); // 1 second delay
            }
        }

        if (retry_count >= MAX_RETRIES) {
            log_message("DHT22 read failed after %d retries", MAX_RETRIES);
            usleep(1000000 * READ_INTERVAL); // 10 seconds
            continue;
        }

        // Post data
        for (int i = 0; i < POST_RETRY_COUNT; i++) {
            if (post_data(config.url, humidity) == 0) {
                log_message("Data posted successfully");
                break;
            } else {
                log_message("Failed to post data, retrying...");
                usleep(1000000); // 1 second delay
            }
        }

        usleep(1000000 * READ_INTERVAL); // 10 seconds
    }

    // Cleanup
    gpiod_line_put(line);
    gpiod_ctx_free(ctx);
    closelog();
    curl_global_cleanup();

    return 0;
}
