#define COOLING_PATH "/sys/class/thermal/cooling_device0/cur_state"
#define LOG_FILE "/var/log/fan_control.log"
#define POLL_INTERVAL 5
#define MAX_STATE_FILE "/sys/class/thermal/cooling_device0/max_state"

// Fan speed tiers
#define FAN_SPEED_OFF 0
#define FAN_SPEED_LOW 1
#define FAN_SPEED_MED 2
#define FAN_SPEED_HIGH 3

// Global variables
int fan_state = FAN_SPEED_OFF;
int max_state = 0;
int running = 1;

// Function declarations
void handle_signal(int sig);
void log_message(const char *message);
void read_temp(int *temp);
void read_max_state(int *max_state);
void set_fan_state(int new_state);
void update_fan_speed(int temp);
void cleanup();

int main() {
    // Set up signal handling
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Initialize fan state and max_state
    read_max_state(&max_state);
    read_temp(&fan_state);

    // Log initial state
    log_message("Fan control started.");

    while (running) {
        // Read temperature
        int temp;
        if (read_temp(&temp) == 0) {
            update_fan_speed(temp);
        } else {
            // Retry on transient failure
            usleep(100000); // 100ms delay
            continue;
        }

        // Sleep for poll interval
        usleep(POLL_INTERVAL * 1000000);
    }

    cleanup();
    return 0;
}

void handle_signal(int sig) {
    running = 0;
    log_message("Shutting down fan control.");
    set_fan_state(FAN_SPEED_OFF);
    exit(EXIT_SUCCESS);
}

void log_message(const char *message) {
    FILE *log_file;
    char timestamp[64];
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return;
    }

    fprintf(log_file, "[%s] %s\n", timestamp, message);
    fclose(log_file);
}

void read_temp(int *temp) {
    FILE *fp;
    char buffer[16];
    int result = 0;

    fp = fopen(TEMP_PATH, "r");
    if (fp == NULL) {
        perror("Failed to read temperature");
        return -1;
    }

    if (fgets(buffer, sizeof(buffer), fp) == NULL) {
        fclose(fp);
        perror("Failed to read temperature data");
        return -1;
    }

    fclose(fp);

    *temp = atoi(buffer);
    return 0;
}

void read_max_state(int *max_state) {
    FILE *fp;
    char buffer[16];
    int result = 0;

    fp = fopen(MAX_STATE_FILE, "r");
    if (fp == NULL) {
        perror("Failed to read max state");
        return;
    }

    if (fgets(buffer, sizeof(buffer), fp) == NULL) {
        fclose(fp);
        perror("Failed to read max state data");
        return;
    }

    fclose(fp);

    *max_state = atoi(buffer);
    return;
}

void set_fan_state(int new_state) {
    int fd;
    char buffer[16];
    ssize_t bytes_written;

    if (new_state < 0 || new_state > max_state) {
        log_message("Invalid fan state requested.");
        return;
    }

    fd = open(COOLING_PATH, O_WRONLY);
    if (fd == -1) {
        perror("Failed to open cooling device");
        return;
    }

    snprintf(buffer, sizeof(buffer), "%d", new_state);
    bytes_written = write(fd, buffer, strlen(buffer));
    if (bytes_written == -1) {
        perror("Failed to write fan state");
    }

    close(fd);
    fan_state = new_state;
}

void update_fan_speed(int temp) {
    int new_state = FAN_SPEED_OFF;

    if (temp < 45) {
        new_state = FAN_SPEED_OFF;
    } else if (temp < 55) {
        new_state = FAN_SPEED_LOW;
    } else if (temp < 65) {
        new_state = FAN_SPEED_MED;
    } else {
        new_state = FAN_SPEED_HIGH;
    }

    if (new_state != fan_state) {
        log_message("Fan speed changed.");
        set_fan_state(new_state);
    }
}

void cleanup() {
    // Ensure fan is off on exit
    set_fan_state(FAN_SPEED_OFF);
}

