#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/time.h>
#include <sys/types.h>
#include <signal.h>
#include <gpiod.h>
#include <math.h>

#define GPIO_PIN 18
#define PWM_FREQ 25000
#define LOG_FILE "cooling_log.csv"
#define POLL_INTERVAL 5
#define TEMP_LOW 40
#define TEMP_HIGH 70
#define DUTY_MIN 0
#define DUTY_MAX 100

typedef struct {
    int pwm_fd;
    gpiod_line *pwm_line;
    FILE *log_file;
    int running;
} app_state;

void handle_signal(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        app_state *state = (app_state *)malloc(sizeof(app_state));
        if (state) {
            state->running = 0;
            free(state);
        }
    }
}

void log_data(FILE *log_file, double temp, int duty) {
    struct timeval tv;
    gettimeofday(&tv, NULL);
    long timestamp = tv.tv_sec * 1000 + tv.tv_usec / 1000;

    fprintf(log_file, "%ld,%f,%d\n", timestamp, temp, duty);
    fflush(log_file);
}

int map_temp_to_duty(double temp) {
    if (temp <= TEMP_LOW) {
        return DUTY_MIN;
    } else if (temp >= TEMP_HIGH) {
        return DUTY_MAX;
    } else {
        double range = TEMP_HIGH - TEMP_LOW;
        double temp_range = temp - TEMP_LOW;
        double ratio = temp_range / range;
        return (int)(DUTY_MIN + ratio * (DUTY_MAX - DUTY_MIN));
    }
}

void setup_pwm(app_state *state) {
    state->pwm_line = gpiod_line_get("gpiochip4", GPIO_PIN);
    if (!state->pwm_line) {
        fprintf(stderr, "Failed to get GPIO line\n");
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(state->pwm_line, "fan_pwm", 0, GPIOD_LINE_REQUEST_FLAG_ACTIVE_LOW)) {
        fprintf(stderr, "Failed to request GPIO line for output\n");
        gpiod_line_put(state->pwm_line);
        exit(EXIT_FAILURE);
    }

    state->pwm_fd = gpiod_line_get_fd(state->pwm_line);
    if (state->pwm_fd < 0) {
        fprintf(stderr, "Failed to get file descriptor for GPIO line\n");
        gpiod_line_put(state->pwm_line);
        exit(EXIT_FAILURE);
    }

    if (ioctl(state->pwm_fd, GPIO_PWM_SET_FREQ, PWM_FREQ)) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        close(state->pwm_fd);
        gpiod_line_put(state->pwm_line);
        exit(EXIT_FAILURE);
    }
}

void cleanup_pwm(app_state *state) {
    if (state->pwm_fd >= 0) {
        close(state->pwm_fd);
    }
    if (state->pwm_line) {
        gpiod_line_put(state->pwm_line);
    }
}

void setup_logging(app_state *state) {
    state->log_file = fopen(LOG_FILE, "a");
    if (!state->log_file) {
        fprintf(stderr, "Failed to open log file\n");
        exit(EXIT_FAILURE);
    }

    fprintf(state->log_file, "timestamp,temperature,percentage\n");
    fflush(state->log_file);
}

void cleanup_logging(app_state *state) {
    if (state->log_file) {
        fclose(state->log_file);
    }
}

int get_cpu_temperature() {
    FILE *fp;
    char buffer[128];
    double temp;

    fp = fopen("/sys/class/thermal/thermal_zone0/temp", "r");
    if (!fp) {
        fprintf(stderr, "Failed to open temperature file\n");
        return -1;
    }

    if (fgets(buffer, sizeof(buffer), fp) == NULL) {
        fclose(fp);
        return -1;
    }

    fclose(fp);

    temp = atof(buffer) / 1000.0;
    return (int)temp;
}

int main() {
    app_state state = {0};

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    setup_pwm(&state);
    setup_logging(&state);

    state.running = 1;
    while (state.running) {
        int temp = get_cpu_temperature();
        if (temp < 0) {
            fprintf(stderr, "Failed to read temperature\n");
            break;
        }

        int duty = map_temp_to_duty(temp);
        if (ioctl(state.pwm_fd, GPIO_PWM_SET_DUTY, duty)) {
            fprintf(stderr, "Failed to set PWM duty cycle\n");
            break;
        }

        log_data(state.log_file, (double)temp, duty);
        usleep(POLL_INTERVAL * 1000000);
    }

    cleanup_pwm(&state);
    cleanup_logging(&state);

    return 0;
}

