#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <fcntl.h>
#include <errno.h>

#define I2C_BUS 1
#define I2C_ADDR1 0x40
#define I2C_ADDR2 0x41
#define I2C_RETRY_COUNT 3
#define I2C_READ_BYTES 3
#define CRC_POLY 0x07
#define CRC_INIT 0x00

typedef struct {
    int fd;
    int retry_count;
} i2c_handle;

// CRC-8 calculation
unsigned char crc8(const unsigned char *data, size_t len) {
    unsigned char crc = CRC_INIT;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLY;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// I2C read function with retry
int i2c_read_retry(int fd, unsigned char addr, unsigned char *buf, size_t len, int max_retries) {
    int retries = 0;
    int ret;

    while (retries < max_retries) {
        ret = ioctl(fd, I2C_RDWR, (struct i2c_msg *) &msg);
        if (ret < 0) {
            perror("ioctl");
            return -1;
        }

        if (msg.len != len) {
            fprintf(stderr, "I2C read failed: unexpected length\n");
            return -1;
        }

        retries++;
    }

    return 0;
}

// I2C write function
int i2c_write(int fd, unsigned char addr, unsigned char *buf, size_t len) {
    struct i2c_msg msg;
    struct i2c_rdwr_ioctl_data req;

    msg.addr = addr;
    msg.flags = 0;
    msg.len = len;
    msg.buf = buf;

    req.msgs = &msg;
    req.nmsgs = 1;

    if (ioctl(fd, I2C_RDWR, &req) < 0) {
        perror("ioctl");
        return -1;
    }

    return 0;
}

// I2C read function
int i2c_read(int fd, unsigned char addr, unsigned char *buf, size_t len) {
    struct i2c_msg msg;
    struct i2c_rdwr_ioctl_data req;

    msg.addr = addr;
    msg.flags = I2C_M_RD;
    msg.len = len;
    msg.buf = buf;

    req.msgs = &msg;
    req.nmsgs = 1;

    if (ioctl(fd, I2C_RDWR, &req) < 0) {
        perror("ioctl");
        return -1;
    }

    return 0;
}

// I2C initialization
int i2c_init(int bus) {
    char path[32];
    snprintf(path, sizeof(path), "/dev/i2c-%d", bus);
    int fd = open(path, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_TEN, 0) < 0) {
        perror("Failed to set I2C to 10-bit addressing");
        close(fd);
        return -1;
    }

    return fd;
}

// Signal handler for clean shutdown
void handle_signal(int sig) {
    printf("Received signal %d, shutting down...\n", sig);
    exit(EXIT_SUCCESS);
}

int main() {
    int i2c_fd = i2c_init(I2C_BUS);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to initialize I2C bus\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    unsigned char buf[I2C_READ_BYTES];
    time_t now;
    struct tm *timeinfo;
    FILE *log_file;
    char log_line[100];

    while (1) {
        // Open log file in append mode
        log_file = fopen("flow_log.txt", "a");
        if (log_file == NULL) {
            fprintf(stderr, "Failed to open log file\n");
            sleep(1);
            continue;
        }

        // Read from sensor 1
        int sensor1_valid = 0;
        for (int i = 0; i < I2C_RETRY_COUNT; i++) {
            if (i2c_write(i2c_fd, I2C_ADDR1, (unsigned char[]){0x01}, 1) < 0) {
                continue;
            }

            if (i2c_read(i2c_fd, I2C_ADDR1, buf, I2C_READ_BYTES) < 0) {
                continue;
            }

            unsigned char crc = crc8(buf, I2C_READ_BYTES - 1);
            if (buf[2] == crc) {
                sensor1_valid = 1;
                break;
            }
        }

        // Read from sensor 2
        int sensor2_valid = 0;
        for (int i = 0; i < I2C_RETRY_COUNT; i++) {
            if (i2c_write(i2c_fd, I2C_ADDR2, (unsigned char[]){0x01}, 1) < 0) {
                continue;
            }

            if (i2c_read(i2c_fd, I2C_ADDR2, buf, I2C_READ_BYTES) < 0) {
                continue;
            }

            unsigned char crc = crc8(buf, I2C_READ_BYTES - 1);
            if (buf[2] == crc) {
                sensor2_valid = 1;
                break;
            }
        }

        // Write to log if both sensors are valid
        if (sensor1_valid && sensor2_valid) {
            time(&now);
            timeinfo = localtime(&now);
            strftime(log_line, sizeof(log_line), "%Y-%m-%d %H:%M:%S", timeinfo);
            snprintf(log_line + strlen(log_line), sizeof(log_line) - strlen(log_line), ",%02X%02X,%02X%02X", buf[0], buf[1], buf[0], buf[1]);
            fprintf(log_file, "%s,%02X%02X,%02X%02X\n", log_line, buf[0], buf[1], buf[0], buf[1]);
        }

        fclose(log_file);
        sleep(1);
    }

    close(i2c_fd);
    return 0;
}

