#include <time.h>
#include <gpiod.h>

#define GPIO_PIN_A 17
#define GPIO_PIN_B 18
#define LOG_FILE "encoder_log.txt"
#define QUADRATURE_STATES 4
#define PULSES_PER_REVOLUTION 360
#define DEGREES_PER_REVOLUTION 360.0

typedef enum {
    STATE_00,
    STATE_01,
    STATE_11,
    STATE_10
} quadrature_state_t;

typedef struct {
    gpiod_line *line_a;
    gpiod_line *line_b;
    FILE *log_file;
    int running;
} encoder_state_t;

void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        printf("Received signal, shutting down...\n");
        exit(EXIT_SUCCESS);
    }
}

void log_position(encoder_state_t *state, double degrees) {
    if (state->log_file == NULL) {
        fprintf(stderr, "Error: Log file not open.\n");
        return;
    }

    time_t now = time(NULL);
    struct tm *tm_now = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_now);

    fprintf(state->log_file, "%s,%.2f\n", timestamp, degrees);
    fflush(state->log_file);
}

void cleanup(encoder_state_t *state) {
    if (state->line_a) {
        gpiod_line_release(state->line_a);
    }
    if (state->line_b) {
        gpiod_line_release(state->line_b);
    }
    if (state->log_file) {
        fclose(state->log_file);
    }
    state->running = 0;
}

int main() {
    encoder_state_t state = {0};
    int state_index = 0;
    int prev_state_index = 0;
    double degrees = 0.0;

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO lines
    state.line_a = gpiod_line_get(GPIO_PIN_A, "gpio");
    if (!state.line_a) {
        fprintf(stderr, "Failed to get GPIO line for pin %d\n", GPIO_PIN_A);
        return EXIT_FAILURE;
    }

    state.line_b = gpiod_line_get(GPIO_PIN_B, "gpio");
