#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define I2C_BUS 1
#define I2C_ADDR 0x48
#define LED_PIN 17
#define IR_THRESHOLD 2000
#define LOG_FILE "adpd144ri_log.txt"
#define SAMPLE_INTERVAL_MS 100

typedef struct {
    int i2c_fd;
    struct gpiod_line *led_line;
    FILE *log_file;
    int running;
} app_state;

void handle_signal(int sig) {
    app_state *state = (app_state *)malloc(sizeof(app_state));
    state->running = 0;
    free(state);
}

void log_measurement(FILE *log_file, time_t timestamp, int red, int ir) {
    fprintf(log_file, "%lu,%d,%d\n", (unsigned long)timestamp, red, ir);
    fflush(log_file);
}

void init_i2c(int *fd) {
    char i2c_bus_path[32];
    snprintf(i2c_bus_path, sizeof(i2c_bus_path), "/dev/i2c-%d", I2C_BUS);

    *fd = open(i2c_bus_path, O_RDWR);
    if (*fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    if (ioctl(*fd, I2C_TEN, 0) < 0) {
        perror("Failed to set I2C to 10-bit addressing");
        close(*fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(*fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(*fd);
        exit(EXIT_FAILURE);
    }
}

void init_gpio(struct gpiod_line **line) {
    struct gpiod_chip *chip;
    chip = gpiod_chip_open("/dev/gpiochip4");
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    *line = gpiod_line_request_output(chip, "gpio17", "LED", 1, GPIOD_LINE_REQUEST_FLAG_ACTIVE_LOW);
    if (!*line) {
        perror("Failed to request GPIO line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }
}

void init_log_file(FILE **log_file) {
    *log_file = fopen(LOG_FILE, "w");
    if (!*log_file) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }

    fprintf(*log_file, "timestamp,red,ir\n");
    fflush(*log_file);
}

void read_sensor(int fd, int *red, int *ir) {
    unsigned char buffer[4];
    ssize_t bytes_read;

    if (read(fd, buffer, 4) != 4) {
        perror("I2C read failed");
        exit(EXIT_FAILURE);
    }

    *red = (buffer[0] << 8) | buffer[1];
    *ir = (buffer[2] << 8) | buffer[3];
}

void cleanup(app_state *state) {
    if (state->log_file) {
        fclose(state->log_file);
    }

    if (state->i2c_fd >= 0) {
        close(state->i2c_fd);
    }

    if (state->led_line) {
        gpiod_line_release(state->led_line);
    }

    printf("Cleanup complete.\n");
}

int main() {
    app_state state = {0};
    struct sigaction sa;
    time_t last_timestamp = 0;

    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("Failed to set signal handler");
        exit(EXIT_FAILURE);
    }

    init_i2c(&state.i2c_fd);
    init_gpio(&state.led_line);
    init_log_file(&state.log_file);

    state.running = 1;

    while (state.running) {
        time_t current_time = time(NULL);

        if (current_time != last_timestamp) {
            read_sensor(state.i2c_fd, &state.red, &state.ir);
            log_measurement(state.log_file, current_time, state.red, state.ir);

            if (state.ir > IR_THRESHOLD) {
                gpiod_line_set_value(state.led_line, 1);
            } else {
                gpiod_line_set_value(state.led_line, 0);
            }

            last_timestamp = current_time;
        }

        usleep(100000); // 100 ms
    }

    cleanup(&state);
    return 0;
}

