#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define GPIO_PIN 18
#define LOG_FILE "rpm_log.txt"
#define INTERVAL 1.0

typedef struct {
    int pulse_count;
    pthread_mutex_t mutex;
    int running;
} rpm_data_t;

volatile sig_atomic_t shutdown_flag = 0;

void signal_handler(int signum) {
    shutdown_flag = 1;
}

void log_rpm(double rpm) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return;
    }

    time_t now = time(NULL);
    struct tm *tm_now = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_now);

    fprintf(log_file, "%s,%.2f\n", timestamp, rpm);
    fflush(log_file);
    fclose(log_file);
}

void *pulse_counter_thread(void *arg) {
    rpm_data_t *data = (rpm_data_t *)arg;
    struct gpiod_line *line;
    int ret;

    line = gpiod_line_get("gpiochip4", GPIO_PIN);
    if (!line) {
        perror("Failed to get GPIO line");
        pthread_exit(NULL);
    }

    ret = gpiod_line_request_input(line, "mlx90254", GPIOD_LINE_FLAG_ACTIVE_LOW);
    if (ret < 0) {
        perror("Failed to request GPIO line as input");
        gpiod_line_put(line);
        pthread_exit(NULL);
    }

    gpiod_line_set_flags(line, GPIOD_LINE_FLAG_BIAS_PULL_DOWN);

    while (data->running) {
        struct timespec ts = {0, 0};
        int event = gpiod_line_event_wait(line, 1000000000, &ts);
        if (event < 0) {
            perror("Failed to wait for GPIO event");
            break;
        }

        if (event == GPIOD_LINE_EVENT_RISING_EDGE) {
            pthread_mutex_lock(&data->mutex);
            data->pulse_count++;
            pthread_mutex_unlock(&data->mutex);
        }
    }

    gpiod_line_put(line);
    pthread_exit(NULL);
}

int main() {
    rpm_data_t data;
    pthread_t thread;
    struct timespec start_time, end_time;
    double rpm;
    int ret;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    pthread_mutex_init(&data.mutex, NULL);
    data.pulse_count = 0;
    data.running = 1;

    ret = pthread_create(&thread, NULL, pulse_counter_thread, &data);
    if (ret != 0) {
        perror("Failed to create thread");
        pthread_mutex_destroy(&data.mutex);
        exit(EXIT_FAILURE);
    }

    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        pthread_mutex_destroy(&data.mutex);
        pthread_cancel(thread);
        pthread_join(thread, NULL);
        exit(EXIT_FAILURE);
    }

    clock_gettime(CLOCK_MONOTONIC, &start_time);

    while (!shutdown_flag) {
        usleep(100000); // 100ms delay

        if (clock_gettime(CLOCK_MONOTONIC, &end_time) == -1) {
            perror("Failed to get end time");
            break;
        }

        double elapsed = (end_time.tv_sec - start_time.tv_sec) + (end_time.tv_nsec - start_time.tv_nsec) / 1e9;
        if (elapsed >= INTERVAL) {
            pthread_mutex_lock(&data.mutex);
            rpm = (data.pulse_count / INTERVAL) * 60.0;
            pthread_mutex_unlock(&data.mutex);

            if (rpm < 0.01) {
                rpm = 0.00;
            }

            log_rpm(rpm);

            data.pulse_count = 0;
            clock_gettime(CLOCK_MONOTONIC, &start_time);
        }
    }

    shutdown_flag = 1;
    pthread_join(thread, NULL);

    fclose(log_file);
    pthread_mutex_destroy(&data.mutex);

    printf("Program exited gracefully.\n");
    return 0;
}

