#include <string.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_OUT_PIN 17  // Audio signal input
#define GPIO_GAIN_PIN 18 // Gain select output (LOW for 60dB gain)

#define POLL_INTERVAL_MS 10
#define LOG_FILE "audio_log.txt"

typedef enum {
    STATE_RUNNING,
    STATE_EXITING
} app_state_t;

app_state_t app_state = STATE_RUNNING;

void handle_signal(int signal) {
    app_state = STATE_EXITING;
}

void log_event(const char *timestamp, int level) {
    FILE *file = fopen(LOG_FILE, "a");
    if (file == NULL) {
        perror("Failed to open log file");
        return;
    }

    fprintf(file, "%s LEVEL %d\n", timestamp, level);
    fclose(file);
}

void setup_gpio(gpiod_line *gain_line, gpiod_line *out_line) {
    struct gpiod_chip *chip;
    struct gpiod_line *line;

    // Initialize gain select pin (GPIO18) as output
    chip = gpiod_chip_open("/dev/gpiochip18");
    if (!chip) {
        perror("Failed to open GPIO chip for gain select");
        exit(EXIT_FAILURE);
    }

    line = gpiod_chip_get_line(chip, GPIO_GAIN_PIN);
    if (!line) {
        perror("Failed to get gain select line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(line, "gain_select", 0) < 0) {
        perror("Failed to request gain select line as output");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Set gain select to LOW (60dB)
    if (gpiod_line_set_value(line, 0) < 0) {
        perror("Failed to set gain select to LOW");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Initialize audio input pin (GPIO17) as input
    chip = gpiod_chip_open("/dev/gpiochip17");
    if (!chip) {
        perror("Failed to open GPIO chip for audio input");
        exit(EXIT_FAILURE);
    }

    line = gpiod_chip_get_line(chip, GPIO_OUT_PIN);
    if (!line) {
        perror("Failed to get audio input line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_input(line, "audio_input", 0) < 0) {
        perror("Failed to request audio input line as input");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    *gain_line = *line;
    *out_line = *line;
}

void cleanup_gpio(gpiod_line gain_line, gpiod_line out_line) {
    gpiod_line_release(gain_line);
    gpiod_line_release(out_line);
}

int main() {
    gpiod_line gain_line = NULL;
    gpiod_line out_line = NULL;
    int last_value = -1;
    int current_value;
    struct timespec ts;
    char timestamp[30];

    // Set up signal handling
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Initialize GPIO
    setup_gpio(&gain_line, &out_line);

    // Print startup message
    printf("Audio event detector started. Listening on GPIO17 (audio input), GPIO18 (gain select).\n");

    while (app_state == STATE_RUNNING) {
        // Poll the audio input pin
        if (gpiod_line_get_value(out_line, &current_value) < 0) {
            perror("Failed to read audio input");
            break;
        }

        // Check for rising edge
        if (last_value == 0 && current_value == 1) {
            time_t now = time(NULL);
            struct tm *tm_info = localtime(&now);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);
            log_event(timestamp, 1);
        }

        last_value = current_value;

        // Sleep for 10ms
        ts.tv_sec = 0;
        ts.tv_nsec = 10 * 1000000;
        nanosleep(&ts, NULL);
    }

    // Cleanup
    cleanup_gpio(gain_line, out_line);
    printf("Audio event detector stopped.\n");

    return 0;
}

