        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Signal handler to clean up on SIGINT
void handle_sigint(int sig) {
    printf("\nReceived SIGINT, cleaning up...\n");
    exit(0);
}

int main() {
    int i2c_fd = -1;
    FILE *log_file = NULL;
    struct timespec ts;
    char log_line[128];
    unsigned char flow_data[3];
    unsigned char crc;
    unsigned short raw_value;
    double flow_rate;
    time_t now;
    struct tm *timeinfo;

    // Initialize signal handling
    signal(SIGINT, handle_sigint);

    // Open I2C bus
    char i2c_bus_path[32];
    snprintf(i2c_bus_path, sizeof(i2c_bus_path), "/dev/i2c-%d", I2C_BUS);
    i2c_fd = open(i2c_bus_path, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Open log file in append mode
    log_file = fopen("flow_log.csv", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        // Write command to read flow
        if (i2c_write(i2c_fd, CMD_READ_FLOW, NULL, 0) < 0) {
            usleep(1000000); // 1 second delay
            continue;
        }

        // Read flow data
        if (i2c_read(i2c_fd, CMD_READ_FLOW, flow_data, 3) < 0) {
            usleep(1000000); // 1 second delay
            continue;
        }

        // Validate CRC
        crc = crc8(flow_data, 2);
        if (crc != flow_data[2]) {
            fprintf(stderr, "CRC validation failed.\n");
            usleep(1000000); // 1 second delay
            continue;
        }

        // Extract raw value
        raw_value = (flow_data[0] << 8) | flow_data[1];

        // Convert to flow rate (uL/min)
        flow_rate = (double)raw_value * 0.01; // Assuming 1 LSB = 0.01 uL/min

        // Get current time
        clock_gettime(CLOCK_REALTIME, &ts);
        time(&now);
        timeinfo = localtime(&now);
        strftime(log_line, sizeof(log_line), "%Y-%m-%d %H:%M:%S", timeinfo);
        snprintf(log_line + strlen(log_line), sizeof(log_line) - strlen(log_line),
                 ",%.2f\n", flow_rate);

        // Write to log file
        if (fprintf(log_file, "%s", log_line) < 0) {
            fprintf(stderr, "Failed to write to log file: %s\n", strerror(errno));
        }

        // Flush log file
        if (fflush(log_file) != 0) {
            fprintf(stderr, "Failed to flush log file: %s\n", strerror(errno));
        }

        // Delay for 1 second
        usleep(1000000);
    }

    // Clean up on exit
    fclose(log_file);
    close(i2c_fd);
    return 0;
}
