            fprintf(stderr, "Failed to read sensor data after %d retries\n", MAX_RETRIES);
            // Log error
            fprintf(log_file, "Error,NA,NA,NA\n");
            fflush(log_file);
            usleep(RETRY_DELAY);
            continue;
        }

