        // Log data
        fprintf(log_file, "%s,%d,%d,%d\n", timestamp, iaq, data.tvoc, data.eco2);
        fflush(log_file);

        // Sleep for 5 seconds
        usleep(LOG_INTERVAL * 1000000);
    }

    // Clean up
    fclose(log_file);
    close(i2c_fd);
    return EXIT_SUCCESS;
}

