#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <gpiod.h>

#define GPIO_PIN 17
#define GPIO_CONSUMER "ttp223_tamper"
#define POLL_INTERVAL_MS 100
#define TAMPER_DURATION_MS 5000

typedef enum {
    STATE_IDLE,
    STATE_TOUCHED
} state_t;

static gpiod_line *line = NULL;
static gpiod_chip *chip = NULL;
static state_t state = STATE_IDLE;
static struct timespec last_touch_time;
static volatile int running = 1;

void cleanup(void) {
    if (line) {
        gpiod_line_release(line);
        line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    printf("Cleanup complete.\n");
}

void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        running = 0;
    }
}

int init_gpio(void) {
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_input(line, GPIO_CONSUMER, 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line: %s\n", strerror(errno));
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

int read_gpio(void) {
    int value;
    if (gpiod_line_get_value(line, &value) < 0) {
        fprintf(stderr, "Failed to read GPIO line: %s\n", strerror(errno));
        return -1;
    }
    return value;
}

void check_tamper(void) {
    int value = read_gpio();
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO line, exiting.\n");
        cleanup();
        exit(EXIT_FAILURE);
    }

    if (value == 1) { /* Touched */
        if (state == STATE_IDLE) {
            state = STATE_TOUCHED;
            clock_gettime(CLOCK_MONOTONIC, &last_touch_time);
        }
    } else { /* Released */
        if (state == STATE_TOUCHED) {
            struct timespec now;
            clock_gettime(CLOCK_MONOTONIC, &now);
            if (timespec_diff(&now, &last_touch_time) > TAMPER_DURATION_MS * 1000000) {
                printf("Intrusion alert: Touch detected for more than 5 seconds.\n");
            }
            state = STATE_IDLE;
        }
    }
}

void timespec_diff(struct timespec *now, struct timespec *start) {
    now->tv_sec -= start->tv_sec;
    now->tv_nsec -= start->tv_nsec;
    if (now->tv_nsec < 0) {
        now->tv_sec--;
        now->tv_nsec += 1000000000;
    }
}

int main(void) {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (init_gpio() < 0) {
        fprintf(stderr, "Failed to initialize GPIO, exiting.\n");
        return EXIT_FAILURE;
    }

    atexit(cleanup);

    while (running) {
        check_tamper();
        usleep(POLL_INTERVAL_MS * 1000);
    }

    cleanup();
    return EXIT_SUCCESS;
}

