#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/time.h>
#include <sys/select.h>
#include <signal.h>
#include <alsa/asoundlib.h>
#include <gpiod.h>

#define PCM_DEVICE "/dev/snd/pcmC0D0c"
#define SAMPLE_RATE 44100
#define SAMPLE_WIDTH 2
#define CHANNELS 2
#define BUFFER_SIZE (1024 * 16)  // 16KB buffer
#define FILE_NAME "audio_capture.pcm"
#define GPIO_PIN 17  // BCM pin 17
#define GPIO_CONSUMER "i2s_channel_selector"

volatile int running = 1;

void handle_sigint(int sig) {
    running = 0;
}

int init_gpio() {
    struct gpiod_line *line;
    int fd;

    line = gpiod_line_get(GPIO_PIN, GPIO_CONSUMER);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line %d\n", GPIO_PIN);
        return -1;
    }

    if (gpiod_line_request_output(line, "channel_select", 0)) {
        fprintf(stderr, "Failed to request GPIO line %d as output\n", GPIO_PIN);
        gpiod_line_put(line);
        return -1;
    }

    fd = gpiod_line_get_fd(line);
    if (fd < 0) {
        fprintf(stderr, "Failed to get file descriptor for GPIO line %d\n", GPIO_PIN);
        gpiod_line_put(line);
        return -1;
    }

    return fd;
}

void set_gpio_output(int gpio_fd, int value) {
    if (ioctl(gpio_fd, GPIO_SET_VALUE, value) < 0) {
        perror("Failed to set GPIO value");
    }
}

void cleanup_gpio(int gpio_fd) {
    close(gpio_fd);
}

int open_pcm_device() {
    int pcm_handle;
    snd_pcm_t *pcm;
    int err;

    err = snd_pcm_open(&pcm_handle, PCM_DEVICE, SND_PCM_STREAM_CAPTURE, 0);
    if (err < 0) {
        fprintf(stderr, "Failed to open PCM device: %s\n", snd_strerror(err));
        return -1;
    }

    err = snd_pcm_set_params(pcm_handle,
                             SND_PCM_FORMAT_S16_LE,
                             SND_PCM_ACCESS_RW_INTERLEAVED,
                             CHANNELS,
                             SAMPLE_RATE,
                             1,
                             1000000);
    if (err < 0) {
        fprintf(stderr, "Failed to set PCM parameters: %s\n", snd_strerror(err));
        snd_pcm_close(pcm_handle);
        return -1;
    }

    return pcm_handle;
}

void close_pcm_device(int pcm_handle) {
    snd_pcm_close(pcm_handle);
}

void write_pcm_data(int pcm_handle, int file_fd, int *buffer, int buffer_size) {
    int frames_read;
    int frames_written;
    int err;

    err = snd_pcm_readi(pcm_handle, buffer, buffer_size / sizeof(int));
    if (err < 0) {
        fprintf(stderr, "PCM read error: %s\n", snd_strerror(err));
        return;
    }

    frames_read = err;

    err = write(file_fd, buffer, frames_read * sizeof(int));
    if (err < 0) {
        perror("File write error");
        return;
    }

    frames_written = err / sizeof(int);

    if (frames_read != frames_written) {
        fprintf(stderr, "Mismatch between frames read and written\n");
    }
}

int main() {
    int pcm_handle = -1;
    int gpio_fd = -1;
    int file_fd = -1;
    int buffer[BUFFER_SIZE / sizeof(int)];
    struct sigaction sa;
    int err;

    // Set up signal handler for SIGINT
    sa.sa_handler = handle_sigint;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("Failed to set up signal handler");
        return 1;
    }

    // Initialize GPIO
    gpio_fd = init_gpio();
    if (gpio_fd < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    // Set GPIO to select left channel
    set_gpio_output(gpio_fd, 1);

    // Open PCM device
    pcm_handle = open_pcm_device();
    if (pcm_handle < 0) {
        fprintf(stderr, "Failed to open PCM device\n");
        cleanup_gpio(gpio_fd);
        return 1;
    }

    // Open output file
