#define DEBOUNCE_DELAY_MS 50
#define PWM_FREQUENCY_HZ 100
#define LOG_FILE "flame_log.txt"
#define SENSOR_TIMEOUT_MS 1000

typedef enum {
    STATE_IDLE,
    STATE_DEBOUNCING,
    STATE_DETECTED,
    STATE_COOLING
} State;

typedef struct {
    gpiod_line *do_line;
    gpiod_line *pwm_line;
    gpiod_chip *chip;
    FILE *log_file;
    int running;
    time_t start_time;
    time_t last_flame_time;
    State state;
    int sensor_present;
} AppContext;

void log_event(AppContext *ctx, const char *message) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", tm_info);

    fprintf(ctx->log_file, "%s - %s\n", timestamp, message);
    fflush(ctx->log_file);
}

void handle_signal(int signal) {
    // Signal handler to clean up and exit
    printf("Received signal %d, shutting down...\n", signal);
    exit(EXIT_SUCCESS);
}

void init_gpio(AppContext *ctx) {
    ctx->chip = gpiod_chip_open("/dev/gpiochip4");
    if (!ctx->chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    ctx->do_line = gpiod_line_get(ctx->chip, GPIO_DO_PIN);
    if (!ctx->do_line) {
        perror("Failed to get DO GPIO line");
        gpiod_chip_close(ctx->chip);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(ctx->do_line, "flame_sensor_do", 0) < 0) {
        perror("Failed to request DO GPIO line");
        gpiod_line_put(ctx->do_line);
        gpiod_chip_close(ctx->chip);
        exit(EXIT_FAILURE);
    }

    ctx->pwm_line = gpiod_line_get(ctx->chip, GPIO_PWM_PIN);
    if (!ctx->pwm_line) {
        perror("Failed to get PWM GPIO line");
        gpiod_line_put(ctx->do_line);
        gpiod_chip_close(ctx->chip);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(ctx->pwm_line, "fan_pwm", 0) < 0) {
        perror("Failed to request PWM GPIO line");
        gpiod_line_put(ctx->pwm_line);
        gpiod_line_put(ctx->do_line);
        gpiod_chip_close(ctx->chip);
        exit(EXIT_FAILURE);
    }

    ctx->sensor_present = 1;
    ctx->state = STATE_IDLE;
    ctx->running = 1;
}

void cleanup_gpio(AppContext *ctx) {
    if (ctx->pwm_line) {
        gpiod_line_set_value(ctx->pwm_line, 0);
        gpiod_line_put(ctx->pwm_line);
    }

    if (ctx->do_line) {
        gpiod_line_put(ctx->do_line);
    }

    if (ctx->chip) {
        gpiod_chip_close(ctx->chip);
    }
}

void init_log(AppContext *ctx) {
    ctx->log_file = fopen(LOG_FILE, "a");
    if (!ctx->log_file) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }

    log_event(ctx, "Program started");
}

void close_log(AppContext *ctx) {
    if (ctx->log_file) {
        log_event(ctx, "Program shutdown");
        fclose(ctx->log_file);
    }
}

void check_sensor(AppContext *ctx) {
    int read_value;
    int ret = gpiod_line_get_value(ctx->do_line, &read_value);
    if (ret < 0) {
        log_event(ctx, "Sensor read failed");
        ctx->sensor_present = 0;
        return;
    }

    if (read_value == 0) {
        log_event(ctx, "Flame detected");
        ctx->state = STATE_DETECTED;
        ctx->last_flame_time = time(NULL);
    } else {
        log_event(ctx, "No flame detected");
        ctx->state = STATE_IDLE;
    }
}

void start_pwm(AppContext *ctx) {
    if (gpiod_line_set_config(ctx->pwm_line, GPIOD_LINE_CONFIG_OUTPUT, 0) < 0) {
        perror("Failed to configure PWM line");
        return;
    }

    if (gpiod_line_set_value(ctx->pwm_line, 1) < 0) {
        perror("Failed to start PWM");
        return;
    }

    log_event(ctx, "PWM started for cooling fan");
}

void stop_pwm(AppContext *ctx) {
    if (gpiod_line_set_value(ctx->pwm_line, 0) < 0) {
        perror("Failed to stop PWM");
    }

    log_event(ctx, "PWM stopped");
}

void run_app(AppContext *ctx) {
    struct timespec sleep_time = {0, DEBOUNCE_DELAY_MS * 1000000};
    int last_state = STATE_IDLE;
    int sensor_timeout = 0;

    while (ctx->running) {
        if (!ctx->sensor_present) {
            if (sensor_timeout >= SENSOR_TIMEOUT_MS) {
                log_event(ctx, "Sensor timeout, no valid reading");
                ctx->sensor_present = 0;
                ctx->state = STATE_IDLE;
                sensor_timeout = 0;
            } else {
                sensor_timeout += DEBOUNCE_DELAY_MS;
            }
            nanosleep(&sleep_time, NULL);
            continue;
        }

        check_sensor(ctx);

        if (ctx->state == STATE_DETECTED) {
            if (last_state != STATE_DETECTED) {
                start_pwm(ctx);
                last_state = STATE_DETECTED;
            }
        } else if (ctx->state == STATE_IDLE) {
            if (last_state != STATE_IDLE) {
                stop_pwm(ctx);
                last_state = STATE_IDLE;
            }
        }

        nanosleep(&sleep_time, NULL);
    }
}

int main() {
    AppContext ctx = {0};

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    init_gpio(&ctx);
    init_log(&ctx);

    run_app(&ctx);

    close_log(&ctx);
    cleanup_gpio(&ctx);

    return 0;
}

