#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <linux/gpio.h>
#include <signal.h>
#include <time.h>
#include <sys/time.h>
#include <sys/mman.h>
#include <sys/types.h>
#include <sys/stat.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define GPIO_TRIGGER 23
#define GPIO_INTERRUPT 24
#define GPIO_CHIP_SELECT 8
#define SPI_SPEED 1000000
#define SPI_MODE SPI_MODE_0
#define FRAME_PERIOD_MS 100
#define FRAME_SIZE_BYTES 32768
#define MAGIC_NUMBER 0x4144
#define HEADER_SIZE (sizeof(uint32_t) + sizeof(uint64_t) + sizeof(struct radar_config))
#define FRAME_HEADER_SIZE (sizeof(uint64_t) + sizeof(uint32_t))

typedef struct {
    uint32_t magic;
    uint64_t timestamp;
    uint32_t start_freq;
    uint32_t end_freq;
    uint32_t num_chirps;
    uint32_t num_samples;
} radar_config;

typedef struct {
    uint64_t timestamp;
    uint32_t frame_number;
} frame_header;

volatile sig_atomic_t running = 1;

void signal_handler(int signo) {
    running = 0;
}

int init_gpio(int gpio_pin, int direction) {
    int fd;
    if ((fd = open("/dev/gpiochip0", O_RDWR)) < 0) {
        perror("Failed to open gpiochip0");
        return -1;
    }

    if (ioctl(fd, GPIO_GET_LINE_VALUES_IOCTL, &gpio_pin) < 0) {
        perror("Failed to get line values");
        close(fd);
        return -1;
    }

    if (ioctl(fd, GPIO_GET_LINE_IOCTL, &gpio_pin) < 0) {
        perror("Failed to get line info");
        close(fd);
        return -1;
    }

    if (ioctl(fd, GPIO_LINE_REQUEST_ACCESS_IOCTL, &gpio_pin) < 0) {
        perror("Failed to request access");
        close(fd);
        return -1;
    }

    if (ioctl(fd, GPIO_LINE_SET_FLAGS_IOCTL, &gpio_pin) < 0) {
        perror("Failed to set flags");
        close(fd);
        return -1;
    }

    if (ioctl(fd, GPIO_LINE_SET_OUTPUT_IOCTL, &gpio_pin) < 0) {
        perror("Failed to set output");
        close(fd);
        return -1;
    }

    if (ioctl(fd, GPIO_LINE_SET_VALUE_IOCTL, &gpio_pin) < 0) {
        perror("Failed to set value");
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

int setup_spi() {
    int fd;
    if ((fd = open(SPI_DEVICE, O_RDWR | O_NOCTTY | O_SYNC)) < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("Failed to set SPI mode");
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("Failed to set SPI speed");
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &1) < 0) {
        perror("Failed to set bits per word");
        close(fd);
        return -1;
    }

    return fd;
}

void release_gpio(int gpio_pin) {
    int fd;
    if ((fd = open("/dev/gpiochip0", O_RDWR)) < 0) {
        perror("Failed to open gpiochip0");
        return;
    }

    if (ioctl(fd, GPIO_LINE_RELEASE_ACCESS_IOCTL, &gpio_pin) < 0) {
        perror("Failed to release access");
    }

    close(fd);
}

void release_spi(int fd) {
    close(fd);
}

int main() {
    int spi_fd;
    int gpio_trigger = GPIO_TRIGGER;
    int gpio_interrupt = GPIO_INTERRUPT;
    int gpio_cs = GPIO_CHIP_SELECT;
    radar_config config = {
        .magic = MAGIC_NUMBER,
        .start_freq = 77000000000ULL,
        .end_freq = 79000000000ULL,
        .num_chirps = 64,
        .num_samples = 256
    };

    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("Failed to set SIGINT handler");
        return 1;
    }

    if (signal(SIGTERM, signal_handler) == SIG_ERR) {
        perror("Failed to set SIGTERM handler");
        return 1;
    }

    if (init_gpio(gpio_cs, GPIO_LINE_OUTPUT) < 0) {
        perror("Failed to initialize GPIO chip select");
        return 1;
    }

    if (init_gpio(gpio_trigger, GPIO_LINE_OUTPUT) < 0) {
        perror("Failed to initialize GPIO trigger");
        return 1;
    }

    if (init_gpio(gpio_interrupt, GPIO_LINE_INPUT) < 0) {
        perror("Failed to initialize GPIO interrupt");
        return 1;
    }

    if ((spi_fd = setup_spi()) < 0) {
        perror("Failed to setup SPI");
        return 1;
    }

    FILE *log_file = fopen("radar_data.bin", "wb");
    if (!log_file) {
        perror("Failed to open log file");
        release_spi(spi_fd);
        return 1;
    }

    fwrite(&config, sizeof(config), 1, log_file);
    fseek(log_file, 0, SEEK_SET);

    struct timeval tv;
    gettimeofday(&tv, NULL);
    uint64_t last_frame_time = tv.tv_sec * 1000ULL + tv.tv_usec / 1000ULL;

    while (running) {
        gettimeofday(&tv, NULL);
        uint64_t current_time = tv.tv_sec * 1000ULL + tv.tv_usec / 1000ULL;

        if (current_time - last_frame_time >= FRAME_PERIOD_MS) {
            // Trigger frame
            if (ioctl(gpio_trigger, GPIO_LINE_SET_VALUE_IOCTL, 1) < 0) {
                perror("Failed to set trigger high");
            }

            usleep(1000); // Wait for trigger to settle

            // Set CS low
            if (ioctl(gpio_cs, GPIO_LINE_SET_VALUE_IOCTL, 0) < 0) {
                perror("Failed to set CS low");
            }

            // Read frame data
            uint8_t buffer[FRAME_SIZE_BYTES];
            struct spi_ioc_transfer spi = {
                .tx_buf = (unsigned long)buffer,
                .rx_buf = (unsigned long)buffer,
