int open_gpio_line(const char *chip_label, int line_offset) {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int fd;

    chip = gpiod_chip_open_by_label(chip_label);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return -1;
    }

