        gpiod_line_put(line);
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(line, "flame_sensor", GPIO_ACTIVE_LOW) < 0) {
        fprintf(stderr, "Failed to request GPIO line for output\n");
        close(fd);
        gpiod_line_put(line);
        gpiod_chip_close(chip);
        return -1;
    }

    return fd;
}

void close_gpio_line(int fd) {
    if (fd >= 0) {
        close(fd);
    }
}

int main() {
