    int last_state = -1;
    struct timespec ts;
    FILE *log_file = NULL;
    char log_line[256];

    // Set up signal handling
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Open GPIO line
    gpio_fd = open_gpio_line("gpiochip0", GPIO_PIN);
    if (gpio_fd < 0) {
        fprintf(stderr, "Failed to open GPIO line, exiting.\n");
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file '%s', exiting.\n", LOG_FILE);
        close_gpio_line(gpio_fd);
        return 1;
    }

    // Main loop
    while (running) {
        // Read current state
        int current_state;
        if (ioctl(gpio_fd, GPIO_GET_LINE_VALUE, &current_state) < 0) {
            fprintf(stderr, "Failed to read GPIO line value, exiting.\n");
            break;
        }

        // Check for state change
        if (last_state == -1) {
            last_state = current_state;
        } else if (last_state != current_state) {
            // State changed, log it
            clock_gettime(CLOCK_REALTIME, &ts);
            char timestamp[32];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", gmtime(&ts.tv_sec));
            snprintf(log_line, sizeof(log_line), "%s %s\n", timestamp, current_state ? "FLAME_DETECTED" : "FLAME_CLEARED");

            if (fwrite(log_line, 1, strlen(log_line), log_file) != strlen(log_line)) {
                fprintf(stderr, "Failed to write to log file, exiting.\n");
                break;
            }
            last_state = current_state;
        }

        // Sleep for 100ms
        usleep(100000);
    }

    // Clean up
    if (log_file) {
        fclose(log_file);
    }
    close_gpio_line(gpio_fd);

    return 0;
}

