#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS 1
#define I2C_ADDR 0x48
#define I2C_DEVICE "/dev/i2c-%d"
#define FILE_NAME "light_data.txt"
#define RETRY_COUNT 5
#define RETRY_DELAY 1000  // in milliseconds
#define CONVERSION_TIME_MS 100

typedef struct {
    int i2c_fd;
    FILE *file;
    int running;
} app_state;

void handle_signal(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        printf("Shutting down...\n");
        app_state *state = (app_state *)malloc(sizeof(app_state));
        state->running = 0;
        free(state);
        exit(EXIT_SUCCESS);
    }
}

void log_error(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
}

void close_resources(app_state *state) {
    if (state->i2c_fd >= 0) {
        close(state->i2c_fd);
    }
    if (state->file) {
        fclose(state->file);
    }
    free(state);
}

void i2c_read(app_state *state, uint8_t reg, uint16_t *value) {
    uint8_t buffer[2];
    int retries = 0;

    do {
        if (state->i2c_fd < 0) {
            log_error("I2C device not open");
            return;
        }

        buffer[0] = reg;
        if (ioctl(state->i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
            log_error("Failed to set I2C slave address");
            return;
        }

        if (write(state->i2c_fd, buffer, 1) != 1) {
            log_error("Failed to write to I2C device");
            return;
        }

        if (read(state->i2c_fd, buffer, 2) != 2) {
            log_error("Failed to read from I2C device");
            return;
        }

        *value = (buffer[0] << 8) | buffer[1];
        return;
    } while (++retries < RETRY_COUNT);

    log_error("I2C transaction failed after retries");
}

void write_to_file(app_state *state, uint16_t lux) {
    char timestamp[30];
    time_t now = time(NULL);
    struct tm *tm_info = gmtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

    char line[100];
    snprintf(line, sizeof(line), "%s,%d\n", timestamp, lux);

    if (state->file) {
        if (fprintf(state->file, "%s", line) < 0) {
            log_error("Failed to write to file");
        }
    }
}

void init_i2c(app_state *state) {
    char device_path[32];
    snprintf(device_path, sizeof(device_path), I2C_DEVICE, I2C_BUS);

    state->i2c_fd = open(device_path, O_RDWR);
    if (state->i2c_fd < 0) {
        log_error("Failed to open I2C device");
        return;
    }

    if (ioctl(state->i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        log_error("Failed to set I2C slave address");
        close(state->i2c_fd);
        state->i2c_fd = -1;
        return;
    }

    // Configure OPT3001 for continuous conversion mode with auto full-scale range
    uint8_t config = 0x80;  // Continuous conversion mode, auto full-scale range
    if (write(state->i2c_fd, &config, 1) != 1) {
        log_error("Failed to configure OPT3001");
        close(state->i2c_fd);
        state->i2c_fd = -1;
        return;
    }
}

int main() {
    app_state *state = (app_state *)malloc(sizeof(app_state));
    state->i2c_fd = -1;
    state->file = NULL;
    state->running = 1;

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Initialize I2C
    if (init_i2c(state) < 0) {
        log_error("Failed to initialize I2C");
        close_resources(state);
        return EXIT_FAILURE;
    }

    // Open file for appending
    state->file = fopen(FILE_NAME, "a");
    if (!state->file) {
        log_error("Failed to open file for writing");
        close_resources(state);
        return EXIT_FAILURE;
    }

    uint16_t lux = 0;
    while (state->running) {
        // Read lux value
        i2c_read(state, 0x00, &lux);

        // Write to file
        write_to_file(state, lux);

        // Sleep for 100ms
        usleep(CONVERSION_TIME_MS * 1000);
    }

    close_resources(state);
    return EXIT_SUCCESS;
}

