        exit_flag = 1;
    }
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct timespec ts;
    char log_entry[256];
    int ret;

    // Set up signal handler
    signal(SIGINT, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip4");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        return 1;
    }

    // Configure the line (GPIO 17, BCM)
    struct gpiod_line_config config = GPIOD_LINE_CONFIG_DEFAULTS;
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;
    config.flags = GPIOD_LINE_FLAG_ACTIVE_LOW;

    line = gpiod_line_request(chip, 17, "flame_detect", &config);
    if (!line) {
        fprintf(stderr, "Failed to request GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    while (!exit_flag) {
        // Wait for 1 second
        clock_gettime(CLOCK_REALTIME, &ts);
        nanosleep(&ts, NULL);

        // Read the line value
