        return -1;
    }

    if (gpiod_line_request_output(state->right_line, "right_sensor", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line %d as output: %m\n", GPIO_RIGHT);
        gpiod_chip_close(state->chip);
        return -1;
    }

