        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < GPIO_LINES_COUNT; i++) {
        state->line_indices[i] = GPIO_LINES_BCM[i];
        state->lines[i] = gpiod_chip_get_line(state->chip, state->line_indices[i]);
        if (!state->lines[i]) {
