            exit(EXIT_FAILURE);
        }

        if (gpiod_line_request_output(state->lines[i], "touch-sensor", 0) < 0) {
            fprintf(stderr, "Failed to request line %d as output: %s\n", state->line_indices[i], strerror(errno));
            exit(EXIT_FAILURE);
        }
    }
