#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_COUNT 8
#define GPIO_PINS 2
#define GPIO_OUT1 2
#define GPIO_OUT2 3
#define GPIO_OUT3 4
#define GPIO_OUT4 5
#define GPIO_OUT5 6
#define GPIO_OUT6 7
#define GPIO_OUT7 8
#define GPIO_OUT8 9

typedef struct {
    struct gpiod_line *lines[GPIO_COUNT];
    int line_indices[GPIO_COUNT];
} TouchSensor;

void signal_handler(int signum) {
    printf("\nCaught signal %d, exiting...\n", signum);
    exit(EXIT_SUCCESS);
}

int init_touch_sensor(TouchSensor *sensor) {
    const char *pin_names[GPIO_COUNT] = {
        "GPIO2", "GPIO3", "GPIO4", "GPIO5",
        "GPIO6", "GPIO7", "GPIO8", "GPIO9"
    };

    for (int i = 0; i < GPIO_COUNT; i++) {
        sensor->line_indices[i] = gpiod_line_find_by_name(pin_names[i]);
        if (sensor->line_indices[i] < 0) {
            fprintf(stderr, "Failed to find GPIO line for %s\n", pin_names[i]);
            return -1;
        }

        sensor->lines[i] = gpiod_line_get(sensor->line_indices[i]);
        if (!sensor->lines[i]) {
            fprintf(stderr, "Failed to get GPIO line for %s\n", pin_names[i]);
            return -1;
        }

        if (gpiod_line_set_direction(sensor->lines[i], GPIOD_LINE_DIRECTION_INPUT) < 0) {
            fprintf(stderr, "Failed to set direction for %s\n", pin_names[i]);
            return -1;
        }

        if (gpiod_line_set_edge_detection(sensor->lines[i], GPIOD_LINE_EDGE_BOTH) < 0) {
            fprintf(stderr, "Failed to set edge detection for %s\n", pin_names[i]);
            return -1;
        }

        if (gpiod_line_set_active_low(sensor->lines[i], 1) < 0) {
            fprintf(stderr, "Failed to set active low for %s\n", pin_names[i]);
            return -1;
        }
    }

    return 0;
}

void read_touch_sensor(TouchSensor *sensor, int *values) {
    for (int i = 0; i < GPIO_COUNT; i++) {
        int value = gpiod_line_get_value(sensor->lines[i]);
        if (value < 0) {
            fprintf(stderr, "Failed to read GPIO line %d\n", sensor->line_indices[i]);
            exit(EXIT_FAILURE);
        }
        values[i] = value;
    }
}

void print_status(int time_ms, int *values) {
    printf("[%+d ms] ", time_ms);
    for (int i = 0; i < GPIO_COUNT; i++) {
        printf("CH%d=%d ", i + 1, values[i]);
    }
    printf("\n");
}

int main() {
    TouchSensor sensor;
    int values[GPIO_COUNT];
    int ret;
    struct gpiod_line *line;
    struct gpiod_line_event *event;
    struct gpiod_line_event *events[GPIO_COUNT];
    struct gpiod_line_event *event_list;
    int event_count;
    int time_ms = 0;
    int last_time = 0;

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the GPIO library
    if (gpiod_init() < 0) {
        fprintf(stderr, "Failed to initialize libgpiod\n");
        exit(EXIT_FAILURE);
    }

    // Initialize touch sensor
    if (init_touch_sensor(&sensor) < 0) {
        fprintf(stderr, "Failed to initialize touch sensor\n");
        gpiod_exit();
        exit(EXIT_FAILURE);
    }

    // Main loop
    while (1) {
        // Wait for events or sleep for 100ms
        ret = gpiod_line_event_wait(sensor.lines[0], 100000, 0);
        if (ret < 0) {
            fprintf(stderr, "Failed to wait for event: %d\n", ret);
            break;
        }

        // Read all lines
        read_touch_sensor(&sensor, values);

        // Print status
        print_status(time_ms, values);

        // Update time
        time_ms += 100;
    }

    // Clean up
    for (int i = 0; i < GPIO_COUNT; i++) {
        gpiod_line_put(sensor.lines[i]);
    }

    gpiod_exit();

    return 0;
}
