#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>
#include <time.h>

#define GPIO_PIN_1 4
#define GPIO_PIN_2 5
#define POLL_INTERVAL_MS 500

typedef struct {
    struct gpiod_line *line1;
    struct gpiod_line *line2;
    int running;
} app_state;

void handle_sigint(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    app_state *state = (app_state *)malloc(sizeof(app_state));
    if (state->line1) {
        gpiod_line_release(state->line1);
    }
    if (state->line2) {
        gpiod_line_release(state->line2);
    }
    free(state);
    exit(EXIT_SUCCESS);
}

void init_gpio(app_state *state) {
    struct gpiod_chip *chip;
    int ret;

    chip = gpiod_chip_open("/dev/gpiochip4");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        exit(EXIT_FAILURE);
    }

    state->line1 = gpiod_chip_get_line(chip, GPIO_PIN_1);
    if (!state->line1) {
        fprintf(stderr, "Failed to get GPIO line %d\n", GPIO_PIN_1);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_request_output(state->line1, "hall_effect_app", 1);
    if (ret < 0) {
        fprintf(stderr, "Failed to request GPIO line %d as output\n", GPIO_PIN_1);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    state->line2 = gpiod_chip_get_line(chip, GPIO_PIN_2);
    if (!state->line2) {
        fprintf(stderr, "Failed to get GPIO line %d\n", GPIO_PIN_2);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_request_output(state->line2, "hall_effect_app", 1);
    if (ret < 0) {
        fprintf(stderr, "Failed to request GPIO line %d as output\n", GPIO_PIN_2);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    gpiod_chip_close(chip);
}

void read_sensor_state(struct gpiod_line *line, const char *label) {
    int value;
    int ret = gpiod_line_get_value(line, &value);
    if (ret < 0) {
        fprintf(stderr, "Failed to read GPIO line: %s\n", gpiod_strerror(ret));
        return;
    }

    if (value == 1) {
        printf("%s: HIGH\n", label);
    } else {
        printf("%s: LOW\n", label);
    }
}

int main() {
    app_state state = {0};
    struct timespec ts;
    int ret;

    signal(SIGINT, handle_sigint);

    if (gpiod_is_available() != 1) {
        fprintf(stderr, "GPIO driver not available\n");
        exit(EXIT_FAILURE);
    }

    init_gpio(&state);

    while (state.running) {
        read_sensor_state(state.line1, "Sensor 1");
        read_sensor_state(state.line2, "Sensor 2");

        ts.tv_sec = 0;
        ts.tv_nsec = POLL_INTERVAL_MS * 1000000;
        nanosleep(&ts, NULL);
    }

    return 0;
}

