#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define BCM_PINS 8
#define BCM_PIN_LIST {2, 3, 4, 17, 27, 22, 10, 9}
#define POLL_INTERVAL_MS 50
#define CSV_HEADER "timestamp,channel0,channel1,channel2,channel3,channel4,channel5,channel6,channel7\n"

typedef struct {
    struct gpiod_chip *chip;
    struct gpiod_line *lines[BCM_PINS];
    int running;
} TouchSensorContext;

void signal_handler(int signum) {
    if (signum == SIGINT) {
        printf("\nCaught SIGINT, shutting down...\n");
        TouchSensorContext *ctx = (TouchSensorContext *)malloc(sizeof(TouchSensorContext));
        ctx->running = 0;
        free(ctx);
    }
}

void cleanup(TouchSensorContext *ctx) {
    if (ctx->chip) {
        gpiod_chip_close(ctx->chip);
    }
    for (int i = 0; i < BCM_PINS; i++) {
        if (ctx->lines[i]) {
            gpiod_line_release(ctx->lines[i]);
        }
    }
    free(ctx);
}

int main() {
    TouchSensorContext *ctx = (TouchSensorContext *)malloc(sizeof(TouchSensorContext));
    if (!ctx) {
        fprintf(stderr, "Failed to allocate memory for context\n");
        return 1;
    }

    ctx->running = 1;

    // Set up signal handler
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        cleanup(ctx);
        return 1;
    }

    // Open the GPIO chip
    ctx->chip = gpiod_chip_open("/dev/gpiochip0");
    if (!ctx->chip) {
        perror("gpiod_chip_open");
        cleanup(ctx);
        return 1;
    }

    // Request each line
    for (int i = 0; i < BCM_PINS; i++) {
        int pin = BCM_PIN_LIST[i];
        struct gpiod_line *line = gpiod_chip_get_line(ctx->chip, pin);
        if (!line) {
            fprintf(stderr, "Failed to get line for pin %d\n", pin);
            cleanup(ctx);
            return 1;
        }

        // Configure the line as input with bias disabled
        int config = GPIOD_LINE_DIRECTION_INPUT;
        if (gpiod_line_request_fallback(line, "touch-sensor", config, NULL) < 0) {
            fprintf(stderr, "Failed to request line %d\n", pin);
            cleanup(ctx);
            return 1;
        }

        ctx->lines[i] = line;
    }

    // Main loop
    while (ctx->running) {
        char timestamp[30];
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&now));

        int states[BCM_PINS];
        for (int i = 0; i < BCM_PINS; i++) {
            if (gpiod_line_get_value(ctx->lines[i]) < 0) {
                fprintf(stderr, "Failed to read line %d\n", BCM_PIN_LIST[i]);
                cleanup(ctx);
                return 1;
            }
            states[i] = gpiod_line_get_value(ctx->lines[i]);
        }

        // Print CSV line
        printf("%s,%d,%d,%d,%d,%d,%d,%d,%d\n",
               timestamp,
               states[0], states[1], states[2], states[3],
               states[4], states[5], states[6], states[7]);

        // Sleep for 50ms
        usleep(POLL_INTERVAL_MS * 1000);
    }

    cleanup(ctx);
    return 0;
}

