#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_PIN 4
#define GPIO_LINE "gpio4"
#define POLL_INTERVAL_MS 100
#define MAX_RETRIES 5

static bool running = true;
static struct gpiod_line *line = NULL;

void signal_handler(int signum) {
    if (signum == SIGINT) {
        running = false;
    }
}

int init_gpio() {
    struct gpiod_chip *chip;
    int ret;

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return -1;
    }

    line = gpiod_line_request_input(chip, GPIO_LINE, "tilt_sensor", GPIOD_LINE_FLAG_ACTIVE_LOW);
    if (!line) {
        fprintf(stderr, "Failed to request GPIO line\n");
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_get_value(line) == -1) {
        fprintf(stderr, "Failed to get initial GPIO value\n");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

void cleanup_gpio() {
    if (line) {
        gpiod_line_release(line);
    }
    if (line) {
        gpiod_line_close(line);
    }
    if (line) {
        gpiod_chip_close(line->chip);
    }
}

int main() {
    int ret;
    int last_state = -1;
    struct timespec ts = {0, POLL_INTERVAL_MS * 1000000};

    signal(SIGINT, signal_handler);

    printf("Tilt Sensor Monitor - Raspberry Pi Zero W\n");
    printf("Monitoring GPIO4 (BCM pin 7) for tilt state changes...\n");

    if (init_gpio() != 0) {
        fprintf(stderr, "Failed to initialize GPIO. Exiting.\n");
        return 1;
    }

    while (running) {
        ret = gpiod_line_get_value(line);
        if (ret == -1) {
            fprintf(stderr, "Error reading GPIO line: %s\n", gpiod_strerror(errno));
            cleanup_gpio();
            return 1;
        }

        if (ret != last_state) {
            last_state = ret;
            if (ret == 0) {
                printf("Tilted\n");
            } else {
                printf("Not Tilted\n");
            }
            fflush(stdout);
        }

        nanosleep(&ts, NULL);
    }

    cleanup_gpio();
    return 0;
}

