#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <gpiod.h>

#define I2C_BUS 1
#define I2C_ADDR 0x60
#define UV_INDEX_REGISTER 0x00
#define ALS_VISIBLE_REGISTER 0x01
#define UV_INDEX_SIZE 2
#define ALS_VISIBLE_SIZE 2
#define LOG_FILE "uv_als_log.csv"

typedef struct {
    int i2c_fd;
    FILE *log_file;
    int running;
} app_state;

void handle_signal(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        printf("\nReceived signal, shutting down...\n");
        app_state *state = (app_state *)malloc(sizeof(app_state));
        state->running = 0;
        free(state);
    }
}

void log_data(const char *timestamp, int uv_index, int als_visible) {
    if (!app_state.log_file) {
        return;
    }

    fprintf(app_state.log_file, "%s,%d,%d\n", timestamp, uv_index, als_visible);
    fflush(app_state.log_file);
}

void close_resources() {
    if (app_state.i2c_fd >= 0) {
        close(app_state.i2c_fd);
    }

    if (app_state.log_file) {
        fclose(app_state.log_file);
    }
}

void init_i2c() {
    char bus_path[32];
    snprintf(bus_path, sizeof(bus_path), "/dev/i2c-%d", I2C_BUS);

    app_state.i2c_fd = open(bus_path, O_RDWR);
    if (app_state.i2c_fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
