#define I2C_BUS "/dev/i2c-1"
#define SLF3S_ADDR1 0x48
#define SLF3S_ADDR2 0x49
#define SLF3S_REGISTER 0x00
#define SLF3S_COMMAND_START 0x01
#define SLF3S_COMMAND_READ 0x02
#define SLF3S_COMMAND_STOP 0x03
#define SLF3S_CRC_POLY 0x07
#define SLF3S_CRC_INIT 0x00
#define SLF3S_CRC_MASK 0x00
#define SLF3S_CRC_BITS 8
#define SLF3S_FLOW_MIN 0.5
#define LOG_FILE "flow_log.txt"
#define POLL_INTERVAL 1000
#define START_DELAY 100

typedef struct {
    int fd;
    int address;
    int valid;
    float flow;
} Sensor;

int i2c_bus = -1;
int log_file = -1;
struct gpiod_line *alarm_line = NULL;
volatile int running = 1;

void handle_signal(int sig) {
    running = 0;
}

void crc8(const unsigned char *data, int len, unsigned char *crc) {
    *crc = SLF3S_CRC_INIT;
    for (int i = 0; i < len; i++) {
        *crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (*crc & 0x80) {
                *crc = (*crc << 1) ^ SLF3S_CRC_POLY;
            } else {
                *crc = (*crc << 1);
            }
        }
    }
}

float calculate_flow(unsigned char *data) {
    unsigned char crc;
    crc8(data, 3, &crc);
    if (crc != data[3]) {
        return -1.0;
    }
    int count = (data[0] << 8) | data[1];
    float flow = (float)count * 0.001; // 1 count = 1 ml
    return flow;
}

void read_sensor(Sensor *sensor) {
    unsigned char buffer[4] = {0};
    int bytes_read = 0;

    if (ioctl(sensor->fd, I2C_SLAVE, sensor->address) < 0) {
        perror("Failed to set I2C slave address");
        return;
    }

    if (write(sensor->fd, &SLF3S_COMMAND_READ, 1) < 0) {
        perror("Failed to send read command");
        return;
    }

    usleep(10000); // Wait for data to be ready

    if ((bytes_read = read(sensor->fd, buffer, 4)) < 0) {
        perror("Failed to read from sensor");
        return;
    }

    sensor->flow = calculate_flow(buffer);
    sensor->valid = (sensor->flow >= 0.0);
}

void init_i2c() {
    i2c_bus = open(I2C_BUS, O_RDWR | O_NOCTTY | O_CLOEXEC);
    if (i2c_bus < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_bus, I2C_TEN, 0) < 0) {
        perror("Failed to set I2C to 10-bit mode");
    }

    for (int i = 0; i < 2; i++) {
        Sensor *sensor = malloc(sizeof(Sensor));
        sensor->address = (i == 0) ? SLF3S_ADDR1 : SLF3S_ADDR2;
        sensor->fd = open(I2C_BUS, O_RDWR | O_NOCTTY | O_CLOEXEC);
        if (sensor->fd < 0) {
            perror("Failed to open I2C bus for sensor");
            exit(EXIT_FAILURE);
        }
        sensor->valid = 0;
        sensor->flow = 0.0;
        // Send start command
        if (write(sensor->fd, &SLF3S_COMMAND_START, 1) < 0) {
            perror("Failed to send start command");
            exit(EXIT_FAILURE);
        }
        usleep(START_DELAY);
        free(sensor);
    }
}

void init_gpio() {
    struct gpiod_line_config config = {
        .line_offset = 17,
        .direction = GPIOD_LINE_DIRECTION_OUTPUT,
        .flags = GPIOD_LINE_FLAG_ACTIVE_LOW,
        .consumer = "flow_alarm"
    };

    alarm_line = gpiod_line_get(NULL, "gpio17", &config);
    if (!alarm_line) {
        perror("Failed to get GPIO line");
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_set_value(alarm_line, 1) < 0) {
        perror("Failed to set alarm high");
        exit(EXIT_FAILURE);
    }
}

void log_flow(float avg_flow) {
    time_t now = time(NULL);
    struct tm *tm_now = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_now);

    fprintf(log_file, "%s,%.2f\n", timestamp, avg_flow);
    fflush(log_file);
}

void cleanup() {
    if (log_file != -1) {
        fclose(log_file);
    }
    if (i2c_bus != -1) {
        close(i2c_bus);
    }
    if (alarm_line) {
        gpiod_line_release(alarm_line);
    }
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    init_i2c();
    init_gpio();

    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        perror("Failed to open log file");
        cleanup();
        exit(EXIT_FAILURE);
    }

    Sensor sensors[2];
    for (int i = 0; i < 2; i++) {
        sensors[i].address = (i == 0) ? SLF3S_ADDR1 : SLF3S_ADDR2;
        sensors[i].fd = open(I2C_BUS, O_RDWR | O_NOCTTY | O_CLOEXEC);
        if (sensors[i].fd < 0) {
            perror("Failed to open I2C bus for sensor");
            cleanup();
            exit(EXIT_FAILURE);
        }
        sensors[i].valid = 0;
        sensors[i].flow = 0.0;
    }

    while (running) {
        float total_flow = 0.0;
        int valid_count = 0;

        for (int i = 0; i < 2; i++) {
            read_sensor(&sensors[i]);
            if (sensors[i].valid) {
                total_flow += sensors[i].flow;
                valid_count++;
            }
        }

        if (valid_count > 0) {
            float avg_flow = total_flow / valid_count;
            log_flow(avg_flow);

            if (avg_flow < SLF3S_FLOW_MIN) {
                if (gpiod_line_set_value(alarm_line, 0) < 0) {
                    perror("Failed to set alarm low");
                }
            } else {
                if (gpiod_line_set_value(alarm_line, 1) < 0) {
                    perror("Failed to set alarm high");
                }
            }
        } else {
            if (gpiod_line_set_value(alarm_line, 1) < 0) {
                perror("Failed to set alarm high");
            }
        }

        usleep(POLL_INTERVAL * 1000);
    }

    cleanup();
    return 0;
}

