#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define BUFFER_SIZE 100
#define GPIO_PIN 4
#define POLL_INTERVAL_MS 50
#define MAX_BUFFER_ENTRIES 100

typedef struct {
    time_t timestamp;
    int value;
} SensorData;

SensorData buffer[BUFFER_SIZE];
int buffer_index = 0;
int buffer_full = 0;
int running = 1;

void handle_sigint(int sig) {
    running = 0;
}

void init_gpio(gpiod_line *line) {
    struct gpiod_chip *chip;
    struct gpiod_line *line;

    chip = gpiod_chip_open("/dev/gpiochip4");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        exit(EXIT_FAILURE);
    }

    line = gpiod_line_request_input(chip, "obstacle_sensor", GPIO_PIN, GPIOD_LINE_FLAG_ACTIVE_LOW | GPIOD_LINE_FLAG_BIAS_PULL_UP);
    if (!line) {
        fprintf(stderr, "Failed to request GPIO line\n");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    *line = *line; // Ensure line is initialized
}

void free_gpio(gpiod_line *line) {
    if (line) {
        gpiod_line_release(line);
    }
    gpiod_chip_close(chip);
}

void log_detection() {
    time_t now;
    time(&now);
    buffer[buffer_index].timestamp = now;
    buffer[buffer_index].value = 0; // LOW means obstacle detected
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_full) {
        buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    }
    if (!buffer_full && buffer_index == 0) {
        buffer_full = 1;
    }
    printf("Obstacle detected at %s\n", ctime(&now));
}

void poll_sensor() {
    int value;
    if (gpiod_line_get_value(line, &value) < 0) {
        fprintf(stderr, "Failed to read GPIO line\n");
        exit(EXIT_FAILURE);
    }
    if (value == 0) {
        log_detection();
    }
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct sigaction sa;

    // Set up signal handler for SIGINT
    sa.sa_handler = handle_sigint;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set up signal handler\n");
        exit(EXIT_FAILURE);
    }

    // Initialize GPIO
    chip = gpiod_chip_open("/dev/gpiochip4");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        exit(EXIT_FAILURE);
    }

    line = gpiod_line_request_input(chip, "obstacle_sensor", GPIO_PIN, GPIOD_LINE_FLAG_ACTIVE_LOW | GPIOD_LINE_FLAG_BIAS_PULL_UP);
    if (!line) {
        fprintf(stderr, "Failed to request GPIO line\n");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    while (running) {
        poll_sensor();
        usleep(POLL_INTERVAL_MS * 1000);
    }

    // Clean up
    free_gpio(line);

    // Dump buffer
    printf("Sensor data dump:\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        struct tm *tm_info = localtime(&buffer[i].timestamp);
        char buffer_time[20];
        strftime(buffer_time, sizeof(buffer_time), "%Y-%m-%d %H:%M:%S", tm_info);
        printf("%s: %d\n", buffer_time, buffer[i].value);
    }

    return 0;
}

