#include <time.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDR 0x2A
#define SENSOR_MODE_REGISTER 0x00
#define SENSOR_MODE_ACTIVE 0x01
#define ACCELERATION_REGISTER 0x28
#define ACCELERATION_REGISTER_COUNT 6
#define CSV_FILE "fan_health.csv"
#define POLL_INTERVAL_MS 500
#define MAX_WAIT_MS 1000
#define MAX_RETRIES 10

typedef struct {
    int i2c_fd;
    FILE *csv_file;
    int active;
} sensor_state_t;

void handle_signal(int sig) {
    (void)sig;
    if (sensor_state_t *state = (sensor_state_t *)malloc(sizeof(sensor_state_t))) {
        if (state->csv_file) {
            fclose(state->csv_file);
        }
        if (state->i2c_fd >= 0) {
            close(state->i2c_fd);
        }
        free(state);
        exit(EXIT_SUCCESS);
    }
}

void write_register(int fd, uint8_t reg, uint8_t value) {
    uint8_t buffer[2];
    buffer[0] = reg;
    buffer[1] = value;
    if (ioctl(fd, I2C_RDWR, &buffer) < 0) {
        fprintf(stderr, "I2C write error: %s\n", strerror(errno));
    }
}

void read_registers(int fd, uint8_t reg, uint8_t *buffer, size_t len) {
    struct i2c_msg msgs[2];
    struct i2c_ioctl_data data;

    msgs[0].addr = I2C_ADDR;
    msgs[0].flags = 0;
    msgs[0].len = 1;
    msgs[0].buf = &reg;

    msgs[1].addr = I2C_ADDR;
    msgs[1].flags = I2C_M_RD;
    msgs[1].len = len;
    msgs[1].buf = buffer;

    data.msgs = msgs;
    data.nmsgs = 2;
    data.len = len;

    if (ioctl(fd, I2C_RDWR, &data) < 0) {
        fprintf(stderr, "I2C read error: %s\n", strerror(errno));
    }
}

void write_mode(int fd) {
    write_register(fd, SENSOR_MODE_REGISTER, SENSOR_MODE_ACTIVE);
}

int wait_for_active(int fd, int timeout_ms) {
    int retries = 0;
    int timeout = timeout_ms / 100;
    int active = 0;

    while (retries < timeout) {
        uint8_t reg_val;
        read_registers(fd, SENSOR_MODE_REGISTER, &reg_val, 1);
        if (reg_val == SENSOR_MODE_ACTIVE) {
            active = 1;
            break;
        }
        usleep(100000); // 100ms
        retries++;
    }

    if (!active) {
        fprintf(stderr, "Sensor did not become active within %d ms.\n", timeout_ms);
        return -1;
    }

    return 0;
}

void write_csv_header(FILE *file) {
    fprintf(file, "timestamp,x,y,z\n");
}

void write_csv_data(FILE *file, const char *timestamp, int x, int y, int z) {
    fprintf(file, "%s,%d,%d,%d\n", timestamp, x, y, z);
}

void log_data(int fd, FILE *file) {
    char timestamp[30];
    time_t now = time(NULL);
    struct tm *tm_info = gmtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", tm_info);

    uint8_t buffer[ACCELERATION_REGISTER_COUNT];
    read_registers(fd, ACCELERATION_REGISTER, buffer, ACCELERATION_REGISTER_COUNT);

    int x = (int)(buffer[0] << 8 | buffer[1]);
    int y = (int)(buffer[2] << 8 | buffer[3]);
    int z = (int)(buffer[4] << 8 | buffer[5]);

    write_csv_data(file, timestamp, x, y, z);
}

int main() {
    sensor_state_t state = {0};

    // Set up signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Open I2C bus
    state.i2c_fd = open(I2C_BUS, O_RDWR);
    if (state.i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    // Set I2C address
    if (ioctl(state.i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C address: %s\n", strerror(errno));
        close(state.i2c_fd);
        return EXIT_FAILURE;
    }

    // Initialize sensor
    write_mode(state.i2c_fd);

    // Wait for sensor to become active
    if (wait_for_active(state.i2c_fd, MAX_WAIT_MS) < 0) {
        close(state.i2c_fd);
        return EXIT_FAILURE;
    }

    // Open CSV file
    state.csv_file = fopen(CSV_FILE, "a");
    if (!state.csv_file) {
        fprintf(stderr, "Failed to open CSV file: %s\n", strerror(errno));
        close(state.i2c_fd);
        return EXIT_FAILURE;
    }

    // Write header if file is new
    if (fseek(state.csv_file, 0, SEEK_SET) == 0 && ftell(state.csv_file) == 0) {
        write_csv_header(state.csv_file);
    }

    // Main loop
    while (1) {
        log_data(state.i2c_fd, state.csv_file);

        // Sleep for 500ms
        usleep(POLL_INTERVAL_MS * 1000);
    }

    // Clean up (should not reach here)
    fclose(state.csv_file);
    close(state.i2c_fd);
    return EXIT_SUCCESS;
}

