    if (!gpio->sensor2) {
        fprintf(stderr, "Failed to get line %d: %s\n", GPIO_SENSOR2, strerror(errno));
        gpiod_line_release(gpio->sensor1);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

