int init_gpio(gpiod_line **line1, gpiod_line **line2) {
    struct gpiod_chip *chip;
    int ret;

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return -1;
    }

    *line1 = gpiod_chip_get_line(chip, GPIO_PIN_17);
    if (!*line1) {
        fprintf(stderr, "Failed to get GPIO line 17\n");
        gpiod_chip_close(chip);
        return -1;
    }

    *line2 = gpiod_chip_get_line(chip, GPIO_PIN_18);
    if (!*line2) {
        fprintf(stderr, "Failed to get GPIO line 18\n");
        gpiod_chip_close(chip);
        return -1;
    }

    ret = gpiod_line_request_output(*line1, "sensor1", 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request GPIO line 17 as output\n");
        gpiod_chip_close(chip);
        return -1;
    }

    ret = gpiod_line_request_output(*line2, "sensor2", 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request GPIO line 18 as output\n");
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
