#define GPIO_ACTIVE_LOW 0
#define POLL_INTERVAL 2
#define REINIT_DELAY 60
#define LOG_FILE "flood_log.txt"

typedef struct {
    gpiod_line *line;
    int fd;
    int initialized;
    int reinit_timer;
} sensor_state;

void handle_signal(int signum) {
    // Signal handler to release resources and exit
    exit(EXIT_SUCCESS);
}

void log_message(const char *message) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return;
    }

    time_t now;
    struct tm *timeinfo;
    char buffer[80];

    time(&now);
    timeinfo = localtime(&now);
    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(log_file, "%s %s\n", buffer, message);
    fclose(log_file);
}

int init_gpio(sensor_state *state) {
    int ret;
    struct gpiod_line_config config = GPIOD_LINE_CONFIG_DEFAULTS;

    config.direction = GPIOD_LINE_DIRECTION_INPUT;
    config.edge = GPIOD_LINE_EDGE_BOTH;
    config.consumer = "water_level_sensor";

    state->line = gpiod_line_get(GPIO_PIN, &config);
    if (!state->line) {
        log_message("Failed to get GPIO line");
        return -1;
    }

    state->fd = gpiod_line_get_fd(state->line);
    if (state->fd < 0) {
        log_message("Failed to get GPIO line file descriptor");
        gpiod_line_put(state->line);
        return -1;
    }

    state->initialized = 1;
    state->reinit_timer = 0;
    return 0;
}

void cleanup_gpio(sensor_state *state) {
    if (state->line) {
        gpiod_line_put(state->line);
    }
    if (state->fd >= 0) {
        close(state->fd);
    }
}

int read_gpio(sensor_state *state) {
    if (!state->initialized) {
        return -1;
    }

    int value = gpiod_line_get_value(state->line);
    if (value < 0) {
        log_message("GPIO read failed");
        state->reinit_timer = REINIT_DELAY;
        return -1;
    }

    return value;
}

void daemonize() {
    pid_t pid, sid;

    pid = fork();
    if (pid < 0) {
        exit(EXIT_FAILURE);
    }

    if (pid > 0) {
        exit(EXIT_SUCCESS);
    }

    umask(0);
    sid = setsid();
    if (sid < 0) {
        exit(EXIT_FAILURE);
    }

    if ((chdir("/")) < 0) {
        exit(EXIT_FAILURE);
    }

    close(STDIN_FILENO);
    close(STDOUT_FILENO);
    close(STDERR_FILENO);
}

int main() {
    sensor_state state = {0};
    int running = 1;
    struct sigaction sa;

    // Set up signal handlers
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        log_message("Failed to set up SIGINT handler");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        log_message("Failed to set up SIGTERM handler");
        return EXIT_FAILURE;
    }

    // Daemonize
    daemonize();

    // Initialize GPIO
    if (init_gpio(&state) < 0) {
        log_message("Failed to initialize GPIO, will retry in 60 seconds");
        sleep(REINIT_DELAY);
        if (init_gpio(&state) < 0) {
            log_message("Failed to re-initialize GPIO, exiting");
            cleanup_gpio(&state);
            return EXIT_FAILURE;
        }
    }

    while (running) {
        int value = read_gpio(&state);
        if (value < 0) {
            // Re-initialize if timer is active
            if (state.reinit_timer > 0) {
                state.reinit_timer--;
            } else {
                log_message("Failed to read GPIO, will retry in 60 seconds");
                sleep(REINIT_DELAY);
                if (init_gpio(&state) < 0) {
                    log_message("Failed to re-initialize GPIO, exiting");
                    cleanup_gpio(&state);
                    return EXIT_FAILURE;
                }
            }
            continue;
        }

        if (value == GPIO_ACTIVE_HIGH) {
            log_message("ALERT: Water detected");
            printf("ALERT: Water detected\n");
        }

        sleep(POLL_INTERVAL);
    }

    cleanup_gpio(&state);
    return EXIT_SUCCESS;
}

