#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/time.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define GPIO_PIN 4
#define LOG_FILE "rpm_log.txt"
#define SAMPLE_INTERVAL 1
#define MAX_RPM 1000000

typedef struct {
    int pulse_count;
    int running;
    gpiod_line *line;
    gpiod_line_event *event;
    struct timespec last_sample_time;
    FILE *log_file;
} rpm_state_t;

void handle_signal(int signum) {
    rpm_state_t *state = (rpm_state_t *)malloc(sizeof(rpm_state_t));
    if (state) {
        state->running = 0;
        if (state->line) {
            gpiod_line_release(state->line);
            state->line = NULL;
        }
        if (state->event) {
            gpiod_line_event_free(state->event);
            state->event = NULL;
        }
        if (state->log_file) {
            fclose(state->log_file);
            state->log_file = NULL;
        }
        free(state);
    }
    exit(EXIT_SUCCESS);
}

void setup_gpio(rpm_state_t *state) {
    int fd;
    struct gpiod_line_config config;
    struct gpiod_line_event_config event_config;

    fd = open("/dev/gpiochip4", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open GPIO chip: %m\n");
        exit(EXIT_FAILURE);
    }

    config.line = GPIO_PIN;
    config.flags = GPIOD_LINE_FLAG_ACTIVE_LOW;
    config.consumer = "mlx90217_rpm";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;
    config.output = 0;
    config.bias = GPIOD_LINE_BIAS_PULL_UP;
    config.drive = GPIOD_LINE_DRIVE_STRENGTH_2MA;
    config.edge = GPIOD_LINE_EDGE_BOTH;

    state->line = gpiod_line_request(fd, &config);
    if (!state->line) {
        fprintf(stderr, "Failed to request GPIO line: %m\n");
        close(fd);
        exit(EXIT_FAILURE);
    }

    event_config.line = state->line;
    event_config.flags = GPIOD_LINE_EVENT_FLAG_RISING_EDGE;
    event_config.consumer = "mlx90217_rpm";
    event_config.callback = NULL;

    state->event = gpiod_line_event_request(event_config);
    if (!state->event) {
        fprintf(stderr, "Failed to request GPIO event: %m\n");
        gpiod_line_release(state->line);
        close(fd);
        exit(EXIT_FAILURE);
    }

    state->running = 1;
}

void cleanup_gpio(rpm_state_t *state) {
    if (state->line) {
        gpiod_line_release(state->line);
    }
    if (state->event) {
        gpiod_line_event_free(state->event);
    }
}

void log_rpm(rpm_state_t *state) {
    struct timespec now;
    char timestamp[30];
    int rpm = 0;

    clock_gettime(CLOCK_MONOTONIC, &now);
    if (state->last_sample_time.tv_sec == 0 || (now.tv_sec - state->last_sample_time.tv_sec) >= SAMPLE_INTERVAL) {
        rpm = (state->pulse_count * 60) / SAMPLE_INTERVAL;
        state->pulse_count = 0;
        state->last_sample_time = now;

        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now.tv_sec));
        fprintf(state->log_file, "%s %d\n", timestamp, rpm);
        fflush(state->log_file);
        printf("%s %d\n", timestamp, rpm);
    }
}

int main() {
    rpm_state_t state = {0};
    struct sigaction sa;
    struct timespec now;
    int ret;

    // Set up signal handlers
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set up signal handlers: %m\n");
        exit(EXIT_FAILURE);
    }

    // Open log file
    state.log_file = fopen(LOG_FILE, "a");
    if (!state.log_file) {
        fprintf(stderr, "Failed to open log file: %m\n");
        exit(EXIT_FAILURE);
    }

    setup_gpio(&state);

    clock_gettime(CLOCK_MONOTONIC, &state.last_sample_time);

    while (state.running) {
        log_rpm(&state);
        usleep(100000); // 100ms delay to avoid busy-waiting
    }

    cleanup_gpio(&state);
    fclose(state.log_file);

    return 0;
}

