#define GPIO_LED_PIN 18
#define POLL_INTERVAL_MS 50
#define LOG_TAG "touch_sensor_app"

volatile int running = 1;

void handle_signal(int sig) {
    running = 0;
}

void log_message(const char *message) {
    syslog(LOG_INFO, "%s", message);
}

void log_error(const char *message) {
    syslog(LOG_ERR, "%s", message);
}

int init_gpio(gpiod_line **touch_line, gpiod_line **led_line) {
    int ret;
    struct gpiod_chip *chip;

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        log_error("Failed to open GPIO chip");
        return -1;
    }

    *touch_line = gpiod_line_request_input(chip, "touch", GPIO_TOUCH_PIN, NULL);
    if (!*touch_line) {
        log_error("Failed to request touch GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    *led_line = gpiod_line_request_output(chip, "led", GPIO_LED_PIN, 0);
    if (!*led_line) {
        log_error("Failed to request LED GPIO line");
        gpiod_line_release(*touch_line);
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

void cleanup_gpio(gpiod_line *touch_line, gpiod_line *led_line) {
    if (touch_line) {
        gpiod_line_release(touch_line);
    }
    if (led_line) {
        gpiod_line_release(led_line);
    }
}

int main() {
    gpiod_line *touch_line = NULL;
    gpiod_line *led_line = NULL;
    int ret;
    int value;

    openlog(LOG_TAG, LOG_PID | LOG_CONS, LOG_USER);
    log_message("Starting touch sensor application");

    if (signal(SIGINT, handle_signal) == SIG_ERR) {
        log_error("Failed to install SIGINT handler");
        return 1;
    }

    if (signal(SIGTERM, handle_signal) == SIG_ERR) {
        log_error("Failed to install SIGTERM handler");
        return 1;
    }

    if (init_gpio(&touch_line, &led_line) != 0) {
        log_error("Failed to initialize GPIO lines");
        return 1;
    }

    while (running) {
        ret = gpiod_line_get_value(touch_line, &value);
        if (ret < 0) {
            log_error("Failed to read touch GPIO line");
            break;
        }

        if (value == 1) {
            gpiod_line_set_value(led_line, 1);
        } else {
            gpiod_line_set_value(led_line, 0);
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    cleanup_gpio(touch_line, led_line);
    log_message("Shutting down touch sensor application");
    closelog();

    return 0;
}

