        return EXIT_FAILURE;
    }

    // Request LED line (GPIO18)
    state->led_line = gpiod_line_request_output(state->chip, "led", GPIO_LED_PIN, GPIOD_LINE_DIRECTION_OUTPUT, 0);
    if (!state->led_line) {
        fprintf(stderr, "Failed to request LED line\n");
        cleanup(state);
        return EXIT_FAILURE;
    }

    // Set LED to LOW initially
    if (gpiod_line_set_value(state->led_line, 0) < 0) {
        fprintf(stderr, "Failed to set LED to LOW\n");
        cleanup(state);
        return EXIT_FAILURE;
    }

    // Set touch line to edge detection mode
    if (gpiod_line_set_edge_detection(state->touch_line, GPIOD_LINE_EDGE_RISING) < 0) {
        fprintf(stderr, "Failed to set edge detection on touch line\n");
        cleanup(state);
        return EXIT_FAILURE;
    }

    // Wait for rising edge events
    while (state->running) {
        struct gpiod_line_event event;
        int ret = gpiod_line_event_wait(state->touch_line, -1, &event);
        if (ret < 0) {
            fprintf(stderr, "Failed to wait for event: %s\n", strerror(errno));
            cleanup(state);
            return EXIT_FAILURE;
        }

        // Read the event
        if (gpiod_line_event_read(state->touch_line, &event) < 0) {
            fprintf(stderr, "Failed to read event\n");
            cleanup(state);
            return EXIT_FAILURE;
        }

        // Debounce
        usleep(DEBOUNCE_DELAY_MS * 1000);

        // Toggle LED
        int led_value = gpiod_line_get_value(state->led_line);
        if (gpiod_line_set_value(state->led_line, 1 - led_value) < 0) {
            fprintf(stderr, "Failed to toggle LED\n");
            cleanup(state);
            return EXIT_FAILURE;
        }
    }

    cleanup(state);
    return EXIT_SUCCESS;
