    fprintf(log_file, "%s: %s\n", timestamp, message);
    fclose(log_file);
}

int init_gpio(int *gpio_fd) {
    *gpio_fd = open("/dev/gpiochip0", O_RDWR);
    if (*gpio_fd < 0) {
        perror("open");
        return -1;
    }

    if (ioctl(*gpio_fd, GPIO_GET_LINEHANDLE_IOCTL, &GPIO_PIN) < 0) {
        perror("GPIO_GET_LINEHANDLE_IOCTL");
        close(*gpio_fd);
        return -1;
    }

    struct gpio_line_info line_info;
    if (ioctl(*gpio_fd, GPIO_GET_LINEINFO_IOCTL, &GPIO_PIN, &line_info) < 0) {
        perror("GPIO_GET_LINEINFO_IOCTL");
        close(*gpio_fd);
        return -1;
    }

    if (line_info.line->flags & GPIO_LINE_FLAG_ACTIVELOW) {
        printf("GPIO %d is already active-low.\n", GPIO_PIN);
    } else {
        struct gpio_line_request req = {
            .line = GPIO_PIN,
            .flags = GPIO_LINE_FLAG_ACTIVELOW
        };
        if (ioctl(*gpio_fd, GPIO_LINE_REQUEST_IOCTL, &req) < 0) {
            perror("GPIO_LINE_REQUEST_IOCTL");
            close(*gpio_fd);
            return -1;
        }
    }

    struct gpio_line_config config = {
        .line = GPIO_PIN,
        .flags = GPIO_LINE_FLAG_INPUT | GPIO_LINE_FLAG_BIAS_PULL_UP
    };
    if (ioctl(*gpio_fd, GPIO_LINE_CONFIG_IOCTL, &config) < 0) {
        perror("GPIO_LINE_CONFIG_IOCTL");
        close(*gpio_fd);
        return -1;
    }

    return 0;
}

int get_gpio_value(int gpio_fd) {
    struct gpio_line_get_value_args args = {
        .line = GPIO_PIN
    };
    if (ioctl(gpio_fd, GPIO_GET_LINE_VALUES_IOCTL, &args) < 0) {
        perror("GPIO_GET_LINE_VALUES_IOCTL");
        return -1;
    }

    return args.values[GPIO_PIN];
}

void cleanup_gpio(int gpio_fd) {
    if (gpio_fd >= 0) {
        close(gpio_fd);
    }
}

int main() {
    int gpio_fd = -1;
    rain_state_t current_state = STATE_NO_RAIN;
    int last_value = 1;

    if (init_gpio(&gpio_fd) < 0) {
        fprintf(stderr, "Failed to initialize GPIO.\n");
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (running) {
        int value = get_gpio_value(gpio_fd);
        if (value < 0) {
            fprintf(stderr, "Failed to read GPIO value.\n");
            break;
        }

        if (value != last_value) {
            last_value = value;
            const char *message = (value == 0) ? "Rain Detected" : "No Rain";
            log_message(message);
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    cleanup_gpio(gpio_fd);
    return 0;
}
