        gpiod_line_release(state->line1);
        close(state->fd1);
        return -1;
    }

    state->fd2 = open("/dev/gpiochip0", O_RDWR);
    if (state->fd2 < 0) {
        perror("Failed to open GPIO chip");
        cleanup(state);
        return -1;
    }

    state->line2 = gpiod_line_get(state->fd2, GPIO_PIN2);
    if (!state->line2) {
