#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define GPIO_SENSOR1 17
#define GPIO_SENSOR2 18
#define GPIO_ALARM 27
#define POLL_INTERVAL_MS 100
#define THRESHOLD_DURATION_MS 2000

typedef enum {
    EVENT_NONE,
    EVENT_TILT_START,
    EVENT_THRESHOLD_EXCEEDED,
    EVENT_TILT_END
} event_type;

typedef struct {
    int sensor1;
    int sensor2;
    int alarm;
    FILE *log_file;
    int alarm_active;
    int running;
} app_state;

void handle_signal(int signal) {
    app_state *state = (app_state *)malloc(sizeof(app_state));
    if (state) {
        state->running = 0;
        if (state->alarm_active) {
            gpiod_line_set_value(state->alarm, 0);
            state->alarm_active = 0;
        }
        if (state->log_file) {
            fclose(state->log_file);
        }
        gpiod_line_release(state->alarm);
        gpiod_line_release(state->sensor1);
        gpiod_line_release(state->sensor2);
        free(state);
    }
    exit(EXIT_SUCCESS);
}

void log_event(FILE *log_file, const char *timestamp, event_type event_type) {
    if (log_file) {
        fprintf(log_file, "%s - %s\n", timestamp, event_type == EVENT_TILT_START ? "Tilt Start" :
                event_type == EVENT_THRESHOLD_EXCEEDED ? "Threshold Exceeded" : "Tilt End");
        fflush(log_file);
    }
}

void setup_gpio(app_state *state) {
    state->sensor1 = gpiod_line_get("gpiochip0", GPIO_SENSOR1);
    if (!state->sensor1) {
        fprintf(stderr, "Failed to get line for sensor1\n");
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(state->sensor1, "sensor1", 0, GPIOD_LINE_REQUEST_FLAG_ACTIVE_LOW)) {
        fprintf(stderr, "Failed to request sensor1 as input\n");
        exit(EXIT_FAILURE);
    }

    state->sensor2 = gpiod_line_get("gpiochip0", GPIO_SENSOR2);
    if (!state->sensor2) {
        fprintf(stderr, "Failed to get line for sensor2\n");
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(state->sensor2, "sensor2", 0, GPIOD_LINE_REQUEST_FLAG_ACTIVE_LOW)) {
        fprintf(stderr, "Failed to request sensor2 as input\n");
        exit(EXIT_FAILURE);
