#include <time.h>
#include <gpiod.h>
#include <signal.h>

#define I2C_BUS 1
#define I2C_ADDR 0x28
#define I2C_RETRY_COUNT 3
#define ALERT_LED_PIN 17
#define VIBRATION_THRESHOLD 500
#define LOG_FILE "seismic_events.log"

typedef struct {
    int fd;
    struct gpiod_line *alert_led;
} SensorContext;

void handle_signal(int sig) {
    (void)sig;
    exit(EXIT_SUCCESS);
}

void log_event(const char *timestamp, int peak_vibration) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        return;
    }

    fprintf(log_file, "%s %d\n", timestamp, peak_vibration);
    fclose(log_file);
}

void init_i2c(int *fd) {
    char filename[20];
    snprintf(filename, sizeof(filename), "/dev/i2c-%d", I2C_BUS);
    *fd = open(filename, O_RDWR);
    if (*fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    if (ioctl(*fd, I2C_TEN, 0) < 0) {
        perror("Failed to set I2C to 10-bit mode");
        close(*fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(*fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(*fd);
        exit(EXIT_FAILURE);
    }
}

void init_gpio() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;

    chip = gpiod_chip_open("/dev/gpiochip4");
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    line = gpiod_line_request_output(chip, "alert_led", ALERT_LED_PIN, 0);
    if (!line) {
        perror("Failed to request alert LED GPIO line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    gpiod_line_set_value(line, 0); // Turn off LED initially
    gpiod_line_release(line);
    gpiod_chip_close(chip);
}

void clear_power_down_bit(int fd) {
    unsigned char ctrl1 = 0x00;
    if (ioctl(fd, I2C_RDWR, (struct i2c_rdwr_ioctl_data *)&(struct i2c_msg[0])) < 0) {
        perror("Failed to read CTRL1 register");
        exit(EXIT_FAILURE);
    }

    if (ioctl(fd, I2C_RDWR, (struct i2c_rdwr_ioctl_data *)&(struct i2c_msg[1])) < 0) {
        perror("Failed to write to CTRL1 register");
        exit(EXIT_FAILURE);
    }
}

void read_vibration_data(int fd, int *peak_vibration) {
    unsigned char data[6];
    int retries = 0;

    while (retries < I2C_RETRY_COUNT) {
        if (ioctl(fd, I2C_RDWR, (struct i2c_rdwr_ioctl_data *)&(struct i2c_msg[0])) < 0) {
            perror("Failed to read vibration data");
            retries++;
            continue;
        }

        if (ioctl(fd, I2C_RDWR, (struct i2c_rdwr_ioctl_data *)&(struct i2c_msg[1])) < 0) {
            perror("Failed to read vibration data");
            retries++;
            continue;
        }

        *peak_vibration = (data[0] << 8) | data[1];
        break;
    }
}

void poll_sensor(int fd) {
    int peak_vibration = 0;
    read_vibration_data(fd, &peak_vibration);

    if (peak_vibration > VIBRATION_THRESHOLD) {
        char timestamp[30];
        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

        log_event(timestamp, peak_vibration);

        struct gpiod_chip *chip;
        struct gpiod_line *line;

        chip = gpiod_chip_open("/dev/gpiochip4");
        if (!chip) {
            perror("Failed to open GPIO chip");
            return;
        }

        line = gpiod_line_request_output(chip, "alert_led", ALERT_LED_PIN, 1);
        if (!line) {
            perror("Failed to request alert LED GPIO line");
            gpiod_chip_close(chip);
            return;
        }

        gpiod_line_set_value(line, 1);
        usleep(1000000); // 1 second
        gpiod_line_set_value(line, 0);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
    }
}

int main() {
    int i2c_fd;
    init_i2c(&i2c_fd);

    init_gpio();

    clear_power_down_bit(i2c_fd);

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (1) {
        poll_sensor(i2c_fd);
        usleep(100000); // 100 ms
    }

    close(i2c_fd);
    return 0;
}

