#define GPIO_CHIP "gpiochip0"
#define GPIO_OUT_PINS 4
#define GPIO_POLL_INTERVAL_MS 50
#define LED_GPIO 18

typedef struct {
    gpiod_line *lines[GPIO_OUT_PINS];
    gpiod_line *led_line;
    int running;
} gpio_state;

void handle_signal(int signo) {
    if (signo == SIGINT || signo == SIGTERM) {
        printf("Received signal, shutting down...\n");
        exit(EXIT_SUCCESS);
    }
}

void init_gpio(gpio_state *state) {
    int chip_fd;
    const char *chip_name = GPIO_CHIP;

    // Open the GPIO chip
    chip_fd = gpiod_chip_open(chip_name);
    if (chip_fd < 0) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    // Initialize sensor lines
    for (int i = 0; i < GPIO_OUT_PINS; i++) {
        int gpio_num;
        switch (i) {
            case 0: gpio_num = 4; break;
            case 1: gpio_num = 17; break;
            case 2: gpio_num = 27; break;
            case 3: gpio_num = 22; break;
            default: gpio_num = -1; break;
        }

        if (gpio_num < 0) {
            fprintf(stderr, "Invalid GPIO number for sensor %d\n", i);
            exit(EXIT_FAILURE);
        }

        state->lines[i] = gpiod_chip_get_line(chip_fd, gpio_num);
        if (!state->lines[i]) {
            fprintf(stderr, "Failed to get line %d: %s\n", gpio_num, strerror(errno));
            exit(EXIT_FAILURE);
        }

        // Configure sensor lines as input, active low
        if (gpiod_line_request_input(state->lines[i], "obstacle-sensor", NULL) < 0) {
            fprintf(stderr, "Failed to request line %d as input: %s\n", gpio_num, strerror(errno));
            exit(EXIT_FAILURE);
        }

        gpiod_line_set_flags(state->lines[i], GPIOD_LINE_FLAG_ACTIVE_LOW);
    }

    // Initialize LED line
    state->led_line = gpiod_chip_get_line(chip_fd, LED_GPIO);
    if (!state->led_line) {
        fprintf(stderr, "Failed to get line %d: %s\n", LED_GPIO, strerror(errno));
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(state->led_line, "obstacle-led", 0) < 0) {
        fprintf(stderr, "Failed to request line %d as output: %s\n", LED_GPIO, strerror(errno));
        exit(EXIT_FAILURE);
    }
}

void cleanup_gpio(gpio_state *state) {
    for (int i = 0; i < GPIO_OUT_PINS; i++) {
        if (state->lines[i]) {
            gpiod_line_release(state->lines[i]);
        }
    }

    if (state->led_line) {
        gpiod_line_release(state->led_line);
    }
}

void poll_sensors(gpio_state *state) {
    int sensor_value;
    int led_state = 0;

    for (int i = 0; i < GPIO_OUT_PINS; i++) {
        if (gpiod_line_get_value(state->lines[i], &sensor_value) < 0) {
            fprintf(stderr, "Failed to read sensor %d: %s\n", i, strerror(errno));
            return;
        }

        if (sensor_value == 0) {
            led_state = 1;
            break;
        }
    }

    if (gpiod_line_set_value(state->led_line, led_state) < 0) {
        fprintf(stderr, "Failed to set LED value: %s\n", strerror(errno));
    }
}

