#include <sys/file.h>

#define NUM_SENSORS 5
#define GPIO_PINS {2, 3, 4, 17, 27}
#define SENSOR_IDS {1, 2, 3, 4, 5}

volatile sig_atomic_t shutdown_flag = 0;

typedef struct {
    struct gpiod_line *line;
    int gpio_pin;
    int sensor_id;
} sensor_info_t;

sensor_info_t sensors[NUM_SENSORS];

void handle_signal(int signum) {
    shutdown_flag = 1;
}

void log_message(const char *message, ...) {
    va_list args;
    va_start(args, message);
    vsyslog(LOG_USER, message, args);
    va_end(args);
}

void setup_gpio() {
    struct gpiod_chip *chip;
    int i;

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        log_message("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    for (i = 0; i < NUM_SENSORS; i++) {
        sensors[i].gpio_pin = GPIO_PINS[i];
        sensors[i].sensor_id = SENSOR_IDS[i];

        sensors[i].line = gpiod_line_request_input(chip, "flame_monitor", sensors[i].gpio_pin, 0);
        if (!sensors[i].line) {
            log_message("Failed to request GPIO line for sensor %d (GPIO %d)", sensors[i].sensor_id, sensors[i].gpio_pin);
            gpiod_chip_close(chip);
            exit(EXIT_FAILURE);
        }
    }
}

void cleanup_gpio() {
    int i;

    for (i = 0; i < NUM_SENSORS; i++) {
        if (sensors[i].line) {
            gpiod_line_release(sensors[i].line);
        }
    }

    if (chip) {
        gpiod_chip_close(chip);
    }
}

void log_event(int sensor_id, int gpio_pin) {
    FILE *log_file;
    char timestamp[64];

    time_t now = time(NULL);
    struct tm *tm_info = gmtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    log_file = fopen("/var/log/flame_events.log", "a");
    if (log_file) {
        flock(fileno(log_file), LOCK_EX);
        fprintf(log_file, "%s - Sensor ID: %d (GPIO %d) - Flame Detected\n", timestamp, sensor_id, gpio_pin);
        fflush(log_file);
        flock(fileno(log_file), LOCK_UN);
        fclose(log_file);
    } else {
        log_message("Failed to open log file for writing");
    }
}

int main() {
    struct gpiod_line *line;
    int i, value, prev_value;
    int read_result;
    struct timespec ts = {0, 100000000}; // 100ms

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    openlog("flame_monitor", LOG_PID | LOG_CONS, LOG_USER);
    log_message("Flame monitor started");

    setup_gpio();

    while (!shutdown_flag) {
        for (i = 0; i < NUM_SENSORS; i++) {
            line = sensors[i].line;
            if (!line) {
                log_message("Sensor %d (GPIO %d) line not available", sensors[i].sensor_id, sensors[i].gpio_pin);
                continue;
            }

            read_result = gpiod_line_get_value(line, &value);
            if (read_result < 0) {
                log_message("Failed to read GPIO line for sensor %d (GPIO %d)", sensors[i].sensor_id, sensors[i].gpio_pin);
                continue;
            }

            if (value == 1) {
                prev_value = 1;
                continue;
            }

            if (value == 0 && prev_value == 1) {
                nanosleep(&ts, NULL);
                read_result = gpiod_line_get_value(line, &value);
                if (read_result < 0) {
                    log_message("Failed to re-read GPIO line for sensor %d (GPIO %d)", sensors[i].sensor_id, sensors[i].gpio_pin);
                    continue;
                }

                if (value == 0) {
                    log_event(sensors[i].sensor_id, sensors[i].gpio_pin);
                }
            }

            prev_value = value;
        }

        usleep(1000000); // 1 second
    }

    cleanup_gpio();
    closelog();
    log_message("Flame monitor shutdown");

    return 0;
}

