#define BCM_PIN_MAP {5, 6, 13, 19, 26, 12, 16, 20}
#define NUM_SENSORS 8
#define POLL_INTERVAL_MS 50
#define LOG_FORMAT "%Y-%m-%dT%H:%M:%S.%03ldZ sensor %d bcm_pin %d %s"

typedef enum {
    TOUCH_RELEASED,
    TOUCH_DETECTED
} TouchState;

typedef struct {
    gpiod_line *line;
    int bcm_pin;
    int last_state;
} SensorInfo;

void handle_signal(int signum) {
    if (signum == SIGINT) {
        printf("\nGracefully shutting down...\n");
        exit(EXIT_SUCCESS);
    }
}

void log_state_change(int sensor_idx, int bcm_pin, TouchState state) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    char buffer[100];
    strftime(buffer, sizeof(buffer), LOG_FORMAT, 
             localtime(&ts.tv_sec), ts.tv_nsec / 1000, 
             sensor_idx, bcm_pin, state == TOUCH_DETECTED ? "detected" : "released");
    printf("%s\n", buffer);
}

void cleanup(SensorInfo *sensors, int num_sensors) {
    for (int i = 0; i < num_sensors; i++) {
        gpiod_line_release(sensors[i].line);
    }
    free(sensors);
}

int main() {
    struct gpiod_chip *chip;
    SensorInfo *sensors = NULL;
    int result;

    // Initialize signal handling
    signal(SIGINT, handle_signal);

    // Open GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s (%d)\n", strerror(errno), errno);
        return EXIT_FAILURE;
    }

    // Allocate sensor info
    sensors = calloc(NUM_SENSORS, sizeof(SensorInfo));
    if (!sensors) {
        fprintf(stderr, "Failed to allocate memory for sensors: %s (%d)\n", strerror(errno), errno);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request lines for each sensor
    for (int i = 0; i < NUM_SENSORS; i++) {
        int bcm_pin = BCM_PIN_MAP[i];
        sensors[i].bcm_pin = bcm_pin;

        sensors[i].line = gpiod_chip_get_line(chip, bcm_pin);
        if (!sensors[i].line) {
            fprintf(stderr, "Failed to get line %d: %s (%d)\n", bcm_pin, strerror(errno), errno);
            cleanup(sensors, NUM_SENSORS);
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }

        // Set line to input mode
        result = gpiod_line_request_input(sensors[i].line, "touch_sensor");
        if (result < 0) {
            fprintf(stderr, "Failed to request line %d as input: %s (%d)\n", bcm_pin, strerror(errno), errno);
            cleanup(sensors, NUM_SENSORS);
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }

        // Set line to active low (assuming TTP226 outputs low on touch)
        result = gpiod_line_set_active_low(sensors[i].line, 1);
        if (result < 0) {
            fprintf(stderr, "Failed to set line %d to active low: %s (%d)\n", bcm_pin, strerror(errno), errno);
            cleanup(sensors, NUM_SENSORS);
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }

        // Initialize last state
        sensors[i].last_state = gpiod_line_get_value(sensors[i].line);
    }

    // Main loop
    while (1) {
        for (int i = 0; i < NUM_SENSORS; i++) {
            int current_state = gpiod_line_get_value(sensors[i].line);
            if (current_state != sensors[i].last_state) {
                log_state_change(i, sensors[i].bcm_pin, current_state == 0 ? TOUCH_DETECTED : TOUCH_RELEASED);
                sensors[i].last_state = current_state;
            }
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    // Cleanup (should not reach here normally)
    cleanup(sensors, NUM_SENSORS);
    gpiod_chip_close(chip);
    return EXIT_SUCCESS;
}

