#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS 1
#define I2C_ADDR 0x10
#define GPIO_PIN 18
#define PWM_FREQ 1000
#define LOG_FILE "grow_log.txt"

typedef enum {
    ERROR_NONE = 0,
    ERROR_I2C_INIT,
    ERROR_I2C_OPEN,
    ERROR_I2C_CONFIG,
    ERROR_I2C_READ,
    ERROR_PWM_INIT,
    ERROR_PWM_SET,
    ERROR_LOG_OPEN,
    ERROR_LOG_WRITE
} error_code_t;

typedef struct {
    int i2c_fd;
    struct gpiod_line *pwm_line;
    FILE *log_file;
    int running;
} app_state_t;

void handle_signal(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        app_state_t *state = (app_state_t *)malloc(sizeof(app_state_t));
        if (state) {
            state->running = 0;
            free(state);
        }
    }
}

error_code_t init_i2c(app_state_t *state) {
    state->i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (state->i2c_fd < 0) {
        return ERROR_I2C_OPEN;
    }

    if (ioctl(state->i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        close(state->i2c_fd);
        return ERROR_I2C_CONFIG;
    }

    return ERROR_NONE;
}

error_code_t read_lux(app_state_t *state, uint16_t *lux) {
    uint8_t reg = 0x0C;
    uint8_t buf[2];

    if (write(state->i2c_fd, &reg, 1) < 0) {
        return ERROR_I2C_READ;
    }

    usleep(1000); // Wait for conversion

    if (read(state->i2c_fd, buf, 2) < 0) {
        return ERROR_I2C_READ;
    }

    *lux = (buf[0] << 8) | buf[1];
    return ERROR_NONE;
}

error_code_t init_pwm(app_state_t *state) {
    struct gpiod_line *line;
