#include <time.h>
#include <signal.h>
#include <libgpiod.h>

#define BCM_PIN_TOUCH_START 2
#define BCM_PIN_TOUCH_COUNT 8
#define BCM_PIN_LED 17
#define DEBOUNCE_DELAY_MS 50
#define LOG_FILE "touch_log.txt"

typedef struct {
    int fd;
    struct gpiod_line *lines[BCM_PIN_TOUCH_COUNT];
    int last_state[BCM_PIN_TOUCH_COUNT];
    int active;
} TouchContext;

void handle_signal(int signum) {
    (void)signum;
    printf("Signal received, shutting down...\n");
    exit(EXIT_SUCCESS);
}

void init_gpio(TouchContext *ctx) {
    int i;
    struct gpiod_chip *chip;
    struct gpiod_line_config config;

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        exit(EXIT_FAILURE);
    }

    for (i = 0; i < BCM_PIN_TOUCH_COUNT; i++) {
        config = GPIOD_LINE_CONFIG_DEFAULTS;
        config.direction = GPIOD_LINE_DIRECTION_INPUT;
        config.edge = GPIOD_LINE_EDGE_BOTH;
        config.consumer = "touch_sensor";
        config.flags = GPIOD_LINE_FLAG_BIAS_PULL_DOWN;

        ctx->lines[i] = gpiod_line_request(chip, BCM_PIN_TOUCH_START + i, &config);
        if (!ctx->lines[i]) {
            fprintf(stderr, "Failed to request GPIO line %d\n", BCM_PIN_TOUCH_START + i);
            exit(EXIT_FAILURE);
        }
    }

    config = GPIOD_LINE_CONFIG_DEFAULTS;
    config.direction = GPIOD_LINE_DIRECTION_OUTPUT;
    config.consumer = "touch_led";
    ctx->lines[BCM_PIN_TOUCH_COUNT] = gpiod_line_request(chip, BCM_PIN_LED, &config);
    if (!ctx->lines[BCM_PIN_TOUCH_COUNT]) {
        fprintf(stderr, "Failed to request GPIO line %d\n", BCM_PIN_LED);
        exit(EXIT_FAILURE);
    }

    for (i = 0; i < BCM_PIN_TOUCH_COUNT; i++) {
        ctx->last_state[i] = gpiod_line_get_value(ctx->lines[i]);
    }

    ctx->active = 0;
    gpiod_line_set_value(ctx->lines[BCM_PIN_TOUCH_COUNT], 0);
}

void deinit_gpio(TouchContext *ctx) {
    int i;
    for (i = 0; i < BCM_PIN_TOUCH_COUNT; i++) {
        gpiod_line_release(ctx->lines[i]);
    }
    gpiod_chip_close(ctx->lines[BCM_PIN_TOUCH_COUNT]->chip);
}

void log_touch_event(int channel) {
    time_t now;
    struct tm *timeinfo;
    char buffer[100];

    now = time(NULL);
    timeinfo = localtime(&now);
    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", timeinfo);
    snprintf(buffer + strlen(buffer), sizeof(buffer) - strlen(buffer), " – Channel %d Touched\n", channel);

    FILE *file = fopen(LOG_FILE, "a");
    if (!file) {
        fprintf(stderr, "Failed to open log file: %s\n", LOG_FILE);
        return;
    }

    if (fwrite(buffer, 1, strlen(buffer), file) != strlen(buffer)) {
        fprintf(stderr, "Failed to write to log file: %s\n", LOG_FILE);
    }

    fclose(file);
}

void handle_touch_event(TouchContext *ctx, int channel) {
    if (!ctx->active) {
        gpiod_line_set_value(ctx->lines[BCM_PIN_TOUCH_COUNT], 1);
        ctx->active = 1;
    }

    log_touch_event(channel);
}

void poll_sensor(TouchContext *ctx) {
    int i;
    int current_state;
    int touched = 0;

    for (i = 0; i < BCM_PIN_TOUCH_COUNT; i++) {
        current_state = gpiod_line_get_value(ctx->lines[i]);
        if (current_state != ctx->last_state[i]) {
            if (current_state == 1) {
                handle_touch_event(ctx, i + 1);
                touched = 1;
            }
            ctx->last_state[i] = current_state;
        }
    }

    if (!touched && ctx->active) {
        gpiod_line_set_value(ctx->lines[BCM_PIN_TOUCH_COUNT], 0);
        ctx->active = 0;
    }
}

int main() {
    TouchContext ctx;
    struct sigaction sa;
    int ret;

    // Set up signal handler
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to set up signal handler\n");
        exit(EXIT_FAILURE);
    }

    // Initialize GPIO
    init_gpio(&ctx);

    // Main loop
    while (1) {
        poll_sensor(&ctx);
        usleep(DEBOUNCE_DELAY_MS * 1000);
    }

    // Clean up
    deinit_gpio(&ctx);
    return 0;
}

