int open_i2c_bus() {
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        log_error("Opening I2C bus", "open_i2c_bus");
        return -1;
    }
    if (ioctl(fd, I2C_TEN, 0) < 0) {
        log_error("Setting I2C 10-bit addressing", "open_i2c_bus");
        close(fd);
        return -1;
    }
    return fd;
