    struct gpiod_line *alert_line;
    FILE *log_file;
    int running;
} app_state_t;

static app_state_t app_state;

void signal_handler(int signum) {
    if (signum == SIGINT) {
        app_state.running = 0;
    }
}

void cleanup(void) {
    if (app_state.do_line) {
        gpiod_line_release(app_state.do_line);
    }
    if (app_state.alert_line) {
        gpiod_line_release(app_state.alert_line);
    }
    if (app_state.log_file) {
        fclose(app_state.log_file);
    }
    gpiod_chip_close(app_state.do_line->chip);
    gpiod_chip_close(app_state.alert_line->chip);
}

int init_gpio(void) {
    struct gpiod_chip *chip_do = gpiod_chip_open_by_name("gpiochip4");
    if (!chip_do) {
        fprintf(stderr, "Failed to open GPIO chip for DO pin\n");
        return -1;
    }

    app_state.do_line = gpiod_chip_get_line(chip_do, GPIO_DO_PIN);
    if (!app_state.do_line) {
        fprintf(stderr, "Failed to get DO line\n");
        gpiod_chip_close(chip_do);
        return -1;
    }

    if (gpiod_line_request_output(app_state.do_line, "flame_sensor_do", 0) < 0) {
        fprintf(stderr, "Failed to request DO line as output\n");
        gpiod_line_release(app_state.do_line);
        gpiod_chip_close(chip_do);
        return -1;
    }

    struct gpiod_chip *chip_alert = gpiod_chip_open_by_name("gpiochip4");
    if (!chip_alert) {
        fprintf(stderr, "Failed to open GPIO chip for ALERT pin\n");
        gpiod_line_release(app_state.do_line);
        gpiod_chip_close(chip_do);
        return -1;
    }

    app_state.alert_line = gpiod_chip_get_line(chip_alert, GPIO_ALERT_PIN);
    if (!app_state.alert_line) {
        fprintf(stderr, "Failed to get ALERT line\n");
        gpiod_chip_close(chip_do);
        gpiod_chip_close(chip_alert);
        return -1;
    }

    if (gpiod_line_request_output(app_state.alert_line, "flame_sensor_alert", 0) < 0) {
        fprintf(stderr, "Failed to request ALERT line as output\n");
        gpiod_line_release(app_state.do_line);
        gpiod_line_release(app_state.alert_line);
        gpiod_chip_close(chip_do);
        gpiod_chip_close(chip_alert);
        return -1;
    }

    return 0;
}

int open_log_file(void) {
    app_state.log_file = fopen(LOG_FILE, "a");
    if (!app_state.log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", LOG_FILE);
        return -1;
    }
    return 0;
}

void log_event(const char *message) {
    time_t now = time(NULL);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
    fprintf(app_state.log_file, "[%s] %s\n", timestamp, message);
    fflush(app_state.log_file);
}

void handle_flame_detection(void) {
    if (gpiod_line_set_value(app_state.alert_line, 1) < 0) {
        fprintf(stderr, "Failed to set ALERT pin HIGH\n");
        return;
    }
    usleep(1000000); // 1 second
    if (gpiod_line_set_value(app_state.alert_line, 0) < 0) {
        fprintf(stderr, "Failed to set ALERT pin LOW\n");
    }
    log_event("Flame detected - alert triggered");
}

int main(void) {
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Failed to set up signal handler\n");
        return 1;
    }

    if (atexit(cleanup) != 0) {
        fprintf(stderr, "Failed to register cleanup function\n");
        return 1;
    }

    if (init_gpio() != 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    if (open_log_file() != 0) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    app_state.running = 1;

    while (app_state.running) {
        int do_value = gpiod_line_get_value(app_state.do_line);
        if (do_value < 0) {
            fprintf(stderr, "Failed to read DO pin\n");
            usleep(POLL_INTERVAL_MS * 1000);
            continue;
        }

        if (do_value == 0) { // Flame detected (DO is LOW)
            handle_flame_detection();
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    return 0;
}

