#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_PIN 4
#define LOG_FILE "touch_log.txt"
#define DEBOUNCE_INTERVAL_MS 50

typedef enum {
    TOUCH_RELEASED,
    TOUCH_PRESSED
} TouchState;

volatile sig_atomic_t running = 1;

void handle_signal(int signo) {
    running = 0;
}

void log_event(const char *message) {
    FILE *file = fopen(LOG_FILE, "a");
    if (file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    time_t now;
    struct tm *timeinfo;
    char timestamp[20];

    time(&now);
    timeinfo = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(file, "%s: %s\n", timestamp, message);
    fflush(file);
    fclose(file);
}

void cleanup_gpio(gpiod_line *line) {
    if (line) {
        gpiod_line_release(line);
    }
}

void cleanup_log_file(FILE *file) {
    if (file) {
        fclose(file);
    }
}

int main() {
    gpiod_line *line = NULL;
    int ret;
    TouchState last_state = TOUCH_RELEASED;
    struct timespec debounce_delay = {0, 50000000}; // 50 ms

    // Set up signal handling
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Initialize GPIO
    struct gpiod_chip *chip = gpiod_chip_open("/dev/gpiochip4");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_input(line, "touch_sensor", GPIOD_LINE_REQUEST_FLAG_ACTIVE_LOW);
    if (ret < 0) {
        fprintf(stderr, "Failed to request GPIO line: %s\n", strerror(errno));
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_set_pull_config(line, GPIOD_LINE_PULL_DOWN);
    if (ret < 0) {
        fprintf(stderr, "Failed to set pull configuration: %s\n", strerror(errno));
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (running) {
        int value;
        ret = gpiod_line_get_value(line, &value);
        if (ret < 0) {
            fprintf(stderr, "Failed to read GPIO line: %s\n", strerror(errno));
            cleanup_gpio(line);
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }

        if (value == 0) {
            if (last_state == TOUCH_RELEASED) {
                log_event("Touch Detected");
                last_state = TOUCH_PRESSED;
            }
        } else {
            if (last_state == TOUCH_PRESSED) {
                log_event("Touch Released");
                last_state = TOUCH_RELEASED;
            }
        }

        nanosleep(&debounce_delay, NULL);
    }

    cleanup_gpio(line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

