#define CRC8_POLY 0x07
#define CRC8_INIT 0x00

typedef enum {
    STATUS_OK,
    STATUS_ERROR,
    STATUS_INVALID
} Status;

typedef struct {
    int fd;
    FILE *csv_file;
    int initialized;
} I2CContext;

void handle_signal(int sig) {
    (void)sig;
    exit(EXIT_SUCCESS);
}

void i2c_init(I2CContext *ctx) {
    char filename[20];
    snprintf(filename, sizeof(filename), "/dev/i2c-%d", I2C_BUS);
    ctx->fd = open(filename, O_RDWR);
    if (ctx->fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    if (ioctl(ctx->fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(ctx->fd);
        exit(EXIT_FAILURE);
    }

    ctx->initialized = 1;
}

void i2c_deinit(I2CContext *ctx) {
    if (ctx->fd >= 0) {
        close(ctx->fd);
    }
    if (ctx->csv_file) {
        fclose(ctx->csv_file);
    }
}

void log_header(FILE *csv_file) {
    fprintf(csv_file, "Timestamp,Flow Rate (ml/min),Status\n");
    fflush(csv_file);
}

void log_measurement(FILE *csv_file, time_t timestamp, double flow_rate, Status status) {
    char timestamp_str[30];
    strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", localtime(&timestamp));
    fprintf(csv_file, "%s,%.1f,%s\n", timestamp_str, flow_rate, status == STATUS_OK ? "OK" : (status == STATUS_ERROR ? "ERROR" : "INVALID"));
    fflush(csv_file);
}

int i2c_read(I2CContext *ctx, uint8_t *buffer, size_t len) {
    if (!ctx->initialized) {
        return -1;
    }

    ssize_t bytes_read = read(ctx->fd, buffer, len);
    if (bytes_read < 0) {
        perror("I2C read failed");
        return -1;
    } else if ((size_t)bytes_read != len) {
        fprintf(stderr, "I2C read incomplete: expected %zu bytes, got %zd\n", len, bytes_read);
        return -1;
    }
    return 0;
}

int i2c_write(I2CContext *ctx, const uint8_t *buffer, size_t len) {
    if (!ctx->initialized) {
        return -1;
    }

    ssize_t bytes_written = write(ctx->fd, buffer, len);
    if (bytes_written < 0) {
        perror("I2C write failed");
        return -1;
    } else if ((size_t)bytes_written != len) {
        fprintf(stderr, "I2C write incomplete: expected %zu bytes, got %zd\n", len, bytes_written);
        return -1;
    }
    return 0;
}

int calculate_crc8(const uint8_t *data, size_t len) {
    uint8_t crc = CRC8_INIT;
    for (size_t i = 0; i < len; ++i) {
        crc ^= data[i];
        for (int j = 0; j < 8; ++j) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLY;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int validate_crc(const uint8_t *data, size_t len) {
    if (len < 3) {
        return 0;
    }
    uint8_t crc = calculate_crc8(data, len - 1);
    return (crc == data[len - 1]);
}

double convert_flow_rate(const uint8_t *data) {
    uint16_t flow_value = (data[0] << 8) | data[1];
    return (double)flow_value / 100.0;
}

int main() {
    I2CContext i2c_ctx = {0};
    i2c_init(&i2c_ctx);

    const char *csv_filename = "cooling_log.csv";
    i2c_ctx.csv_file = fopen(csv_filename, "a");
    if (!i2c_ctx.csv_file) {
        perror("Failed to open CSV file");
        i2c_deinit(&i2c_ctx);
        exit(EXIT_FAILURE);
    }

