#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define GPIO_PIN 4
#define FLAME_EVENT_FILE "flame_events.txt"
#define MAX_EVENT_MSG 256

typedef enum {
    EVENT_NONE,
    EVENT_FLAME_DETECTED
} event_type;

typedef struct {
    event_type type;
    char message[MAX_EVENT_MSG];
} event_t;

static gpiod_line *line = NULL;
static FILE *event_file = NULL;
static int running = 1;

void handle_signal(int sig) {
    running = 0;
}

void log_event(event_t event) {
    time_t now;
    char timestamp[64];
    struct tm *tm_info;

    time(&now);
    tm_info = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    snprintf(event.message, MAX_EVENT_MSG, "%s - %s", timestamp, event.message);
    fprintf(stdout, "%s\n", event.message);
    fprintf(event_file, "%s\n", event.message);
    fflush(stdout);
    fflush(event_file);
}

void cleanup() {
    if (line) {
        gpiod_line_release(line);
        line = NULL;
    }

    if (event_file) {
        fclose(event_file);
        event_file = NULL;
    }

    printf("Cleanup complete.\n");
}

int main() {
    struct gpiod_line_request_config req_config;
    struct gpiod_line_event event;
    int ret;

    // Set up signal handling
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Open the event file
    event_file = fopen(FLAME_EVENT_FILE, "a");
    if (!event_file) {
        fprintf(stderr, "Failed to open event file: %s\n", FLAME_EVENT_FILE);
        return 1;
    }

    // Initialize GPIO line
    req_config = gpiod_line_request_config_default();
    req_config.consumer = "flame_sensor";
    req_config.flags = GPIOD_LINE_REQUEST_FLAG_ACTIVE_LOW;

    line = gpiod_line_request(GPIO_PIN, &req_config);
    if (!line) {
        fprintf(stderr, "Failed to request GPIO line %d\n", GPIO_PIN);
        cleanup();
        return 1;
    }

    // Set up edge detection for falling edge
    ret = gpiod_line_set_edge_detection(line, GPIOD_LINE_EDGE_FALLING);
    if (ret < 0) {
        fprintf(stderr, "Failed to set edge detection on GPIO %d: %s\n", GPIO_PIN, strerror(errno));
        cleanup();
        return 1;
    }

    printf("Flame sensor monitoring started on GPIO %d (BCM)\n", GPIO_PIN);

    while (running) {
        ret = gpiod_line_event_wait(line, -1);
        if (ret < 0) {
            if (errno == EAGAIN || errno == EINTR) {
                continue;
            } else {
                fprintf(stderr, "Error waiting for event on GPIO %d: %s\n", GPIO_PIN, strerror(errno));
                cleanup();
                return 1;
            }
        }

        ret = gpiod_line_get_event(line, &event);
        if (ret < 0) {
            fprintf(stderr, "Error getting event on GPIO %d: %s\n", GPIO_PIN, strerror(errno));
            cleanup();
            return 1;
        }

        if (event.type == GPIOD_LINE_EVENT_TYPE_FALLING) {
            event_t event_data = {EVENT_FLAME_DETECTED, "Flame detected"};
            log_event(event_data);
        }
    }

    cleanup();
    return 0;
}

