#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/gpio.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip4"
#define GPIO_TOUCH_PIN 23
#define GPIO_LED_PIN 24
#define LOG_FILE "touch_log.txt"
#define POLL_TIMEOUT_MS 1000

typedef struct {
    struct gpiod_line *touch_line;
    struct gpiod_line *led_line;
    FILE *log_file;
    int poll_fd;
    int running;
} app_state;

void handle_signal(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        app_state *state = (app_state *)malloc(sizeof(app_state));
        if (state) {
            state->running = 0;
        }
    }
}

void log_event(FILE *log_file, const char *timestamp, int touch_state, int led_state) {
    if (log_file) {
        fprintf(log_file, "%s,Touch:%d,LED:%d\n", timestamp, touch_state, led_state);
        fflush(log_file);
    }
}

void cleanup(app_state *state) {
    if (state) {
        if (state->touch_line) {
            gpiod_line_release(state->touch_line);
        }
        if (state->led_line) {
            gpiod_line_release(state->led_line);
        }
        if (state->poll_fd >= 0) {
            close(state->poll_fd);
        }
        if (state->log_file) {
            fclose(state->log_file);
        }
        free(state);
    }
}

int main() {
    app_state *state = (app_state *)malloc(sizeof(app_state));
    if (!state) {
        fprintf(stderr, "Failed to allocate memory for app state\n");
        return 1;
    }

    state->running = 1;

    // Set up signal handling
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to set up signal handlers\n");
        cleanup(state);
        return 1;
    }

    // Open log file
    state->log_file = fopen(LOG_FILE, "a");
    if (!state->log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", LOG_FILE);
        cleanup(state);
        return 1;
    }

    // Open GPIO chip
    struct gpiod_chip *chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip %s\n", GPIO_CHIP);
        cleanup(state);
        return 1;
    }

    // Request touch line (input, active-high)
    state->touch_line = gpiod_chip_get_line(chip, GPIO_TOUCH_PIN);
    if (!state->touch_line) {
        fprintf(stderr, "Failed to get touch line %d from chip %s\n", GPIO_TOUCH_PIN, GPIO_CHIP);
        gpiod_chip_close(chip);
        cleanup(state);
        return 1;
    }

    if (gpiod_line_request_input(state->touch_line, "touch_sensor") < 0) {
        fprintf(stderr, "Failed to request touch line %d as input\n", GPIO_TOUCH_PIN);
        gpiod_line_release(state->touch_line);
        gpiod_chip_close(chip);
        cleanup(state);
        return 1;
    }

    // Request LED line (output, active-high)
    state->led_line = gpiod_chip_get_line(chip, GPIO_LED_PIN);
    if (!state->led_line) {
        fprintf(stderr, "Failed to get LED line %d from chip %s\n", GPIO_LED_PIN, GPIO_CHIP);
        gpiod_line_release(state->touch_line);
        gpiod_chip_close(chip);
        cleanup(state);
        return 1;
    }

    if (gpiod_line_request_output(state->led_line, "led", GPIO_LINE_ACTIVE_HIGH) < 0) {
        fprintf(stderr, "Failed to request LED line %d as output\n", GPIO_LED_PIN);
        gpiod_line_release(state->touch_line);
        gpiod_chip_close(chip);
        cleanup(state);
        return 1;
    }

    // Set up poll for touch line
    state->poll_fd = gpiod_line_event_wait_fd(state->touch_line);
    if (state->poll_fd < 0) {
        fprintf(stderr, "Failed to get poll file descriptor for touch line\n");
        gpiod_line_release(state->touch_line);
        gpiod_line_release(state->led_line);
        gpiod_chip_close(chip);
        cleanup(state);
        return 1;
    }

    // Main loop
    while (state->running) {
        struct pollfd pfd = {
            .fd = state->poll_fd,
            .events = POLLIN
        };

        int poll_result = poll(&pfd, 1, POLL_TIMEOUT_MS);
        if (poll_result < 0) {
            fprintf(stderr, "Poll error: %s\n", strerror(errno));
            cleanup(state);
            return 1;
        } else if (poll_result == 0) {
            // Timeout, continue
            continue;
        }

        // Check for event
        if (pfd.revents & POLLIN) {
            int value;
            if (gpiod_line_get_value(state->touch_line, &value) < 0) {
                fprintf(stderr, "Failed to read touch line value\n");
                cleanup(state);
                return 1;
            }

            if (value == 1) { // Rising edge
                // Toggle LED
                int led_value;
                if (gpiod_line_get_value(state->led_line, &led_value) < 0) {
                    fprintf(stderr, "Failed to read LED line value\n");
                    cleanup(state);
                    return 1;
                }

                if (gpiod_line_set_value(state->led_line, 1 - led_value) < 0) {
                    fprintf(stderr, "Failed to set LED line value\n");
                    cleanup(state);
                    return 1;
                }

                // Log event
                char timestamp[30];
                time_t now = time(NULL);
                struct tm *tm_info = localtime(&now);
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

                log_event(state->log_file, timestamp, 1, 1 - led_value);
            }
        }
    }

    cleanup(state);
    return 0;
}

