#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

// GPIO pin numbers (BCM)
#define GPIO_PIN_1 4
#define GPIO_PIN_2 17
#define GPIO_PIN_3 27

// Sensor identifiers
#define SENSOR_1 "Sensor 1"
#define SENSOR_2 "Sensor 2"
#define SENSOR_3 "Sensor 3"

// Log file name
#define LOG_FILE "magnet_log.txt"

// Global variables
FILE *log_file = NULL;
struct gpiod_line *lines[3] = {NULL, NULL, NULL};
int line_indices[3] = {GPIO_PIN_1, GPIO_PIN_2, GPIO_PIN_3};

// Function to handle signals
void handle_signal(int signum) {
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }

    for (int i = 0; i < 3; i++) {
        if (lines[i] != NULL) {
            gpiod_line_release(lines[i]);
            lines[i] = NULL;
        }
    }

    exit(EXIT_SUCCESS);
}

// Function to initialize a GPIO line
int init_gpio_line(int pin) {
    struct gpiod_chip *chip;
    struct gpiod_line *line;

    chip = gpiod_chip_open_by_number(0); // BCM2835 (Raspberry Pi 4)
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return -1;
    }

    line = gpiod_chip_get_line(chip, pin);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line %d\n", pin);
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_input(line, "magnet_sensor", GPIOD_LINE_FLAG_ACTIVE_LOW) != 0) {
        fprintf(stderr, "Failed to request GPIO line %d as input\n", pin);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_set_pull_mode(line, GPIOD_LINE_PULL_UP, 0) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO line %d\n", pin);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return -1;
    }

    lines[0] = line;
    return 0;
}

// Function to log state change
void log_state_change(const char *sensor_id, int value) {
    char timestamp[30];
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(log_file, "%s, %s, %d\n", timestamp, sensor_id, value);
    fflush(log_file);
}

// Function to read and process sensor states
void read_sensors() {
    int values[3] = {0, 0, 0};

    for (int i = 0; i < 3; i++) {
        if (lines[i] == NULL) {
            fprintf(stderr, "GPIO line %d not initialized\n", line_indices[i]);
            continue;
        }

        int value = gpiod_line_get_value(lines[i]);
        if (value < 0) {
            fprintf(stderr, "Error reading GPIO line %d\n", line_indices[i]);
            continue;
        }

        values[i] = value;
    }

    static int initial_read = 1;
    if (initial_read) {
        initial_read = 0;
        return; // Skip initial read to avoid false transitions
    }

    for (int i = 0; i < 3; i++) {
        if (values[i] == 0) {
            log_state_change(SENSOR_1 + i, 0);
        } else {
            log_state_change(SENSOR_1 + i, 1);
        }
    }
}

int main() {
    // Initialize signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Initialize log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file %s\n", LOG_FILE);
        return EXIT_FAILURE;
    }

    // Initialize GPIO lines
    if (init_gpio_line(GPIO_PIN_1) != 0 ||
        init_gpio_line(GPIO_PIN_2) != 0 ||
        init_gpio_line(GPIO_PIN_3) != 0) {
        fprintf(stderr, "Failed to initialize GPIO lines\n");
        fclose(log_file);
        return EXIT_FAILURE;
    }

    // Main loop
    while (1) {
        read_sensors();
        usleep(100000); // 100 ms delay
    }

    return EXIT_SUCCESS;
}

