#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <errno.h>

#define I2C_BUS 1
#define I2C_ADDR 0x60
#define PART_ID_REGISTER 0x00
#define HW_REV_REGISTER 0x01
#define HEART_RATE_REGISTER 0x02
#define EXPECTED_PART_ID 0x01
#define EXPECTED_HW_REV 0x01
#define SAMPLE_COUNT 5
#define MAX_BPM 220
#define MIN_BPM 30
#define LOG_FILE "heart_rate.csv"

volatile int running = 1;

void handle_signal(int sig) {
    running = 0;
}

void log_error(const char *message, int error_code) {
    fprintf(stderr, "Error: %s (%d)\n", message, error_code);
    exit(EXIT_FAILURE);
}

void close_i2c(int fd) {
    if (fd >= 0) {
        close(fd);
    }
}

void close_log(FILE *file) {
    if (file != NULL) {
        fclose(file);
    }
}

void terminate_driver() {
    // No specific driver to terminate, but ensure all resources are released
}

void i2c_read(int fd, uint8_t reg, uint8_t *data) {
    uint8_t buffer[1];
    buffer[0] = reg;
    if (ioctl(fd, I2C_RDWR, &buffer) < 0) {
        log_error("I2C_RDWR failed", errno);
    }
    if (ioctl(fd, I2C_RDWR, buffer) < 0) {
        log_error("I2C_RDWR failed", errno);
    }
    *data = buffer[0];
}

void i2c_write(int fd, uint8_t reg, uint8_t value) {
    uint8_t buffer[2];
    buffer[0] = reg;
    buffer[1] = value;
    if (ioctl(fd, I2C_RDWR, buffer) < 0) {
        log_error("I2C_RDWR failed", errno);
    }
}

int main() {
    int i2c_fd = -1;
    FILE *log_file = NULL;
    uint8_t part_id = 0;
    uint8_t hw_rev = 0;
    uint8_t heart_rate;
    int samples[SAMPLE_COUNT];
    int current_sample = 0;
    int filtered_bpm = 0;
    time_t now;
    struct tm *timeinfo;
    char timestamp[20];

    signal(SIGINT, handle_signal);

    // Open I2C bus
    char i2c_bus_path[32];
    snprintf(i2c_bus_path, sizeof(i2c_bus_path), "/dev/i2c-%d", I2C_BUS);
    i2c_fd = open(i2c_bus_path, O_RDWR);
    if (i2c_fd < 0) {
        log_error("Failed to open I2C bus", errno);
    }

    // Set I2C address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        log_error("Failed to set I2C slave address", errno);
    }

    // Read PART_ID and HW_REV
    i2c_read(i2c_fd, PART_ID_REGISTER, &part_id);
    i2c_read(i2c_fd, HW_REV_REGISTER, &hw_rev);

    if (part_id != EXPECTED_PART_ID || hw_rev != EXPECTED_HW_REV) {
        log_error("Invalid sensor ID or hardware revision", 0);
    }

    // Initialize log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        log_error("Failed to open log file", errno);
    }

    // Initialize moving average buffer
    for (int i = 0; i < SAMPLE_COUNT; i++) {
        samples[i] = 0;
    }

    while (running) {
        // Read heart rate
        int retries = 3;
        int read_success = 0;
        while (retries-- > 0) {
            i2c_read(i2c_fd, HEART_RATE_REGISTER, &heart_rate);
            if (heart_rate != 0) {
                read_success = 1;
                break;
            }
            usleep(100000); // 100ms retry
        }

        if (!read_success) {
            fprintf(stderr, "I2C read failed, retrying...\n");
            continue;
        }

        // Update moving average
        samples[current_sample] = heart_rate;
        current_sample = (current_sample + 1) % SAMPLE_COUNT;
        int sum = 0;
        for (int i = 0; i < SAMPLE_COUNT; i++) {
            sum += samples[i];
        }
        filtered_bpm = sum / SAMPLE_COUNT;

        // Validate BPM
        if (filtered_bpm >= MIN_BPM && filtered_bpm <= MAX_BPM) {
            // Format timestamp
            time(&now);
            timeinfo = localtime(&now);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            // Write to log
            fprintf(log_file, "%s,%d\n", timestamp, filtered_bpm);
            fflush(log_file);
        }

        // Sleep for 1 second
        usleep(1000000);
    }

    // Clean up
    close_i2c(i2c_fd);
    close_log(log_file);
    terminate_driver();

    return 0;
}

