    gpio_chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!gpio_chip) {
        fprintf(stderr, "Failed to open GPIO chip %s\n", GPIO_CHIP);
        exit(EXIT_FAILURE);
    }

    gpio_line = gpiod_chip_get_line(gpio_chip, GPIO_PIN);
    if (!gpio_line) {
        fprintf(stderr, "Failed to get GPIO line %d\n", GPIO_PIN);
        gpiod_chip_close(gpio_chip);
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_request_input(gpio_line, "flame_sensor");
    if (ret < 0) {
        fprintf(stderr, "Failed to request GPIO line %d as input: %s\n", GPIO_PIN, strerror(errno));
        gpiod_line_release(gpio_line);
        gpiod_chip_close(gpio_chip);
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_set_pull(gpio_line, GPIOD_LINE_PULL_UP);
    if (ret < 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO line %d: %s\n", GPIO_PIN, strerror(errno));
        gpiod_line_release(gpio_line);
        gpiod_chip_close(gpio_chip);
        exit(EXIT_FAILURE);
    }
}

void setup_logging() {
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file %s: %s\n", LOG_FILE, strerror(errno));
        exit(EXIT_FAILURE);
    }
}

