    int ret;
    int last_value = 1; // Assume HIGH initially
    struct timespec ts = {0, 100000000}; // 100ms

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    setup_gpio();
    setup_logging();

    while (!shutdown_requested) {
        nanosleep(&ts, NULL);

        int current_value = gpiod_line_get_value(gpio_line);
        if (current_value < 0) {
            fprintf(stderr, "Failed to read GPIO line %d: %s\n", GPIO_PIN, strerror(errno));
            cleanup();
            exit(EXIT_FAILURE);
        }

        if (current_value == 0 && gpio_state == STATE_IDLE) {
            gpio_state = STATE_ACTIVE;
            log_flame_detection();
        } else if (current_value == 1 && gpio_state == STATE_ACTIVE) {
            gpio_state = STATE_IDLE;
        }
    }

    cleanup();
    return 0;
}

