    int counter;
    int running;
} touch_counter_state;

void handle_signal(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        touch_counter_state *state = (touch_counter_state *)malloc(sizeof(touch_counter_state));
        if (state) {
            state->running = 0;
            free(state);
        }
    }
