    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm_info);

    if (state->log_file) {
        fprintf(state->log_file, "%s, Channel: %d, Counter: %d\n", timestamp, channel, counter);
        fflush(state->log_file);
    }

    printf("Touch on channel %d | Counter: %d\n", channel, counter);
}

void cleanup(touch_counter_state *state) {
    if (state->chip) {
        gpiod_chip_close(state->chip);
