    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (state->input_lines[i]) {
            gpiod_line_release(state->input_lines[i]);
        }
        if (state->output_lines[i]) {
            gpiod_line_release(state->output_lines[i]);
        }
    }

    if (state->log_file) {
        fclose(state->log_file);
    }

    free(state);
}

int main() {
    touch_counter_state *state = (touch_counter_state *)malloc(sizeof(touch_counter_state));
    if (!state) {
        fprintf(stderr, "Failed to allocate memory: %s\n", strerror(errno));
        return 1;
    }

    state->running = 1;
    state->counter = 0;

    // Set up signal handling
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Open GPIO chip
    state->chip = gpiod_chip_open("/dev/gpiochip0");
    if (!state->chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        cleanup(state);
        return 1;
    }

