    for (int i = 0; i < NUM_CHANNELS; i++) {
        int gpio_pin = GPIO_INPUT_START + i;
        char line_name[16];
        snprintf(line_name, sizeof(line_name), "gpio-%d", gpio_pin);

        state->input_lines[i] = gpiod_chip_get_line(state->chip, gpio_pin);
        if (!state->input_lines[i]) {
            fprintf(stderr, "Failed to get input line %d: %s\n", gpio_pin, strerror(errno));
            cleanup(state);
            return 1;
        }

        if (gpiod_line_request_input(state->input_lines[i], "touch_counter_input", NULL)) {
            fprintf(stderr, "Failed to request input line %d: %s\n", gpio_pin, strerror(errno));
            cleanup(state);
            return 1;
        }
    }

    // Configure output lines (BCM 17-24)
    for (int i = 0; i < NUM_CHANNELS; i++) {
        int gpio_pin = GPIO_OUTPUT_START + i;
        char line_name[16];
        snprintf(line_name, sizeof(line_name), "gpio-%d", gpio_pin);

        state->output_lines[i] = gpiod_chip_get_line(state->chip, gpio_pin);
        if (!state->output_lines[i]) {
            fprintf(stderr, "Failed to get output line %d: %s\n", gpio_pin, strerror(errno));
            cleanup(state);
            return 1;
        }

        if (gpiod_line_request_output(state->output_lines[i], "touch_counter_output", 0)) {
            fprintf(stderr, "Failed to request output line %d: %s\n", gpio_pin, strerror(errno));
            cleanup(state);
            return 1;
        }
    }

    // Open log file
    state->log_file = fopen(LOG_FILE, "a");
    if (!state->log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
    }

    // Stabilization delay
    usleep(STABILIZATION_DELAY_MS * 1000);

    while (state->running) {
        for (int i = 0; i < NUM_CHANNELS; i++) {
            int gpio_pin = GPIO_INPUT_START + i;
            int value = gpiod_line_get_value(state->input_lines[i]);
            if (value < 0) {
                fprintf(stderr, "Failed to read input line %d: %s\n", gpio_pin, strerror(errno));
                continue;
            }

            if (value == 1) { // Rising edge (0 to 1)
                state->counter = (state->counter + 1) % 256;
                log_event(state, i + 1, state->counter);

                // Update output lines
                for (int j = 0; j < NUM_CHANNELS; j++) {
                    int bit = (state->counter >> j) & 1;
                    int gpio_out_pin = GPIO_OUTPUT_START + j;
                    if (gpiod_line_set_value(state->output_lines[j], bit)) {
                        fprintf(stderr, "Failed to set output line %d: %s\n", gpio_out_pin, strerror(errno));
                    }
                }
            }
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    cleanup(state);
    return 0;
