#include <signal.h>
#include <gpiod.h>

#define GPIO17 17
#define GPIO18 18
#define GPIO27 27
#define GPIO22 22

#define POLL_INTERVAL_MS 100
#define CSV_FILE "tracking_log.csv"

typedef struct {
    struct gpiod_line *line1;
    struct gpiod_line *line2;
    struct gpiod_line *line3;
    struct gpiod_line *line4;
    FILE *csv_file;
    int running;
} app_state;

void handle_signal(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        printf("Received signal, shutting down...\n");
        app_state *state = (app_state *)malloc(sizeof(app_state));
        if (state) {
            state->running = 0;
            free(state);
        }
    }
}

void log_data(app_state *state) {
    struct timeval tv;
    gettimeofday(&tv, NULL);
    long timestamp = tv.tv_sec * 1000 + tv.tv_usec / 1000;

    int sensor1 = gpiod_line_get_value(state->line1);
    int sensor2 = gpiod_line_get_value(state->line2);
    int sensor3 = gpiod_line_get_value(state->line3);
    int sensor4 = gpiod_line_get_value(state->line4);

    fprintf(state->csv_file, "%ld,%d,%d,%d,%d\n", timestamp, sensor1, sensor2, sensor3, sensor4);
    fflush(state->csv_file);
}

void init_gpio(app_state *state) {
    state->line1 = gpiod_line_get(GPIO17, GPIOD_LINE_DIRECTION_INPUT);
    if (!state->line1) {
        fprintf(stderr, "Failed to get GPIO17 line\n");
        return;
    }

    state->line2 = gpiod_line_get(GPIO18, GPIOD_LINE_DIRECTION_INPUT);
    if (!state->line2) {
        fprintf(stderr, "Failed to get GPIO18 line\n");
        gpiod_line_put(state->line1);
        return;
    }

    state->line3 = gpiod_line_get(GPIO27, GPIOD_LINE_DIRECTION_INPUT);
    if (!state->line3) {
        fprintf(stderr, "Failed to get GPIO27 line\n");
        gpiod_line_put(state->line1);
        gpiod_line_put(state->line2);
        return;
    }

    state->line4 = gpiod_line_get(GPIO22, GPIOD_LINE_DIRECTION_INPUT);
    if (!state->line4) {
        fprintf(stderr, "Failed to get GPIO22 line\n");
        gpiod_line_put(state->line1);
        gpiod_line_put(state->line2);
        gpiod_line_put(state->line3);
        return;
    }

    gpiod_line_set_flags(state->line1, GPIOD_LINE_FLAG_ACTIVE_LOW);
    gpiod_line_set_flags(state->line2, GPIOD_LINE_FLAG_ACTIVE_LOW);
    gpiod_line_set_flags(state->line3, GPIOD_LINE_FLAG_ACTIVE_LOW);
    gpiod_line_set_flags(state->line4, GPIOD_LINE_FLAG_ACTIVE_LOW);

    if (gpiod_line_request_output(state->line1, "sensor1", GPIOD_LINE_REQUEST_FLAG_ACTIVE_LOW)) {
        fprintf(stderr, "Failed to request GPIO17 line\n");
        gpiod_line_put(state->line1);
        gpiod_line_put(state->line2);
        gpiod_line_put(state->line3);
        gpiod_line_put(state->line4);
        return;
    }

    if (gpiod_line_request_output(state->line2, "sensor2", GPIOD_LINE_REQUEST_FLAG_ACTIVE_LOW)) {
        fprintf(stderr, "Failed to request GPIO18 line\n");
        gpiod_line_put(state->line1);
        gpiod_line_put(state->line2);
        gpiod_line_put(state->line3);
        gpiod_line_put(state->line4);
        return;
    }

    if (gpiod_line_request_output(state->line3, "sensor3", GPIOD_LINE_REQUEST_FLAG_ACTIVE_LOW)) {
        fprintf(stderr, "Failed to request GPIO27 line\n");
        gpiod_line_put(state->line1);
        gpiod_line_put(state->line2);
        gpiod_line_put(state->line3);
        gpiod_line_put(state->line4);
        return;
    }

    if (gpiod_line_request_output(state->line4, "sensor4", GPIOD_LINE_REQUEST_FLAG_ACTIVE_LOW)) {
        fprintf(stderr, "Failed to request GPIO22 line\n");
        gpiod_line_put(state->line1);
        gpiod_line_put(state->line2);
        gpiod_line_put(state->line3);
        gpiod_line_put(state->line4);
        return;
    }
}

void init_csv(app_state *state) {
    state->csv_file = fopen(CSV_FILE, "a");
    if (!state->csv_file) {
        fprintf(stderr, "Failed to open CSV file: %s\n", CSV_FILE);
        return;
    }

    // Check if file is empty and write header
    fseek(state->csv_file, 0, SEEK_END);
    if (ftell(state->csv_file) == 0) {
        fprintf(state->csv_file, "timestamp,sensor1,sensor2,sensor3,sensor4\n");
        fflush(state->csv_file);
    }
}

void cleanup_gpio(app_state *state) {
    if (state->line1) {
        gpiod_line_put(state->line1);
    }
    if (state->line2) {
        gpiod_line_put(state->line2);
    }
    if (state->line3) {
        gpiod_line_put(state->line3);
    }
    if (state->line4) {
        gpiod_line_put(state->line4);
    }
}

void cleanup_csv(app_state *state) {
    if (state->csv_file) {
        fclose(state->csv_file);
    }
}

int main() {
    app_state state = {0};

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    init_gpio(&state);
    init_csv(&state);

    if (!state.line1 || !state.line2 || !state.line3 || !state.line4 || !state.csv_file) {
        fprintf(stderr, "Initialization failed, exiting.\n");
        cleanup_gpio(&state);
        cleanup_csv(&state);
        return 1;
    }

    state.running = 1;

    while (state.running) {
        log_data(&state);
        usleep(POLL_INTERVAL_MS * 1000);
    }

    cleanup_gpio(&state);
    cleanup_csv(&state);

    return 0;
}

