    if (state->line1) {
        gpiod_line_put(state->line1);
    }
    if (state->line2) {
        gpiod_line_put(state->line2);
    }
    if (state->line3) {
        gpiod_line_put(state->line3);
    }
    if (state->line4) {
        gpiod_line_put(state->line4);
    }
}

void cleanup_csv(app_state *state) {
    if (state->csv_file) {
        fclose(state->csv_file);
    }
}

int main() {
    app_state state = {0};

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    init_gpio(&state);
    init_csv(&state);

    if (!state.line1 || !state.line2 || !state.line3 || !state.line4 || !state.csv_file) {
        fprintf(stderr, "Initialization failed, exiting.\n");
        cleanup_gpio(&state);
        cleanup_csv(&state);
        return 1;
    }

    state.running = 1;

    while (state.running) {
        log_data(&state);
        usleep(POLL_INTERVAL_MS * 1000);
    }

    cleanup_gpio(&state);
    cleanup_csv(&state);

    return 0;
}
