        log_data(&state, sensor1, sensor2, led_state);

        // Sleep for 100ms
        ts.tv_sec = 0;
        ts.tv_nsec = 100000000;
        nanosleep(&ts, NULL);
    }

    cleanup(&state);
    return 0;
}

