#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    if (signum == SIGINT) {
        running = 0;
    }
}

int main() {
    struct gpiod_line *mic_line = NULL;
    struct gpiod_line *led_line = NULL;
    struct timespec ts;
    int ret;

    // Set up signal handling
    signal(SIGINT, signal_handler);

    // Initialize GPIO library
    ret = gpiod_init();
    if (ret < 0) {
        fprintf(stderr, "Failed to initialize libgpiod: %s\n", gpiod_strerror(ret));
        return EXIT_FAILURE;
    }

    // Configure microphone pin (GPIO4, BCM, input)
    struct gpiod_chip *chip = gpiod_chip_open("/dev/gpiochip4");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", gpiod_strerror(errno));
        gpiod_exit();
        return EXIT_FAILURE;
    }

    mic_line = gpiod_line_request_input(chip, 4, "microphone", GPIOD_LINE_REQUEST_FLAG_ACTIVE_LOW);
    if (!mic_line) {
        fprintf(stderr, "Failed to request microphone line: %s\n", gpiod_strerror(errno));
        gpiod_chip_close(chip);
        gpiod_exit();
        return EXIT_FAILURE;
    }

    // Configure LED pin (GPIO17, BCM, output)
    led_line = gpiod_line_request_output(chip, 17, "led", 0, GPIOD_LINE_REQUEST_FLAG_ACTIVE_LOW);
    if (!led_line) {
        fprintf(stderr, "Failed to request LED line: %s\n", gpiod_strerror(errno));
        gpiod_line_release(mic_line);
        gpiod_chip_close(chip);
        gpiod_exit();
        return EXIT_FAILURE;
    }

    // Set up timer for 8kHz sampling (125 microseconds period)
    clock_gettime(CLOCK_MONOTONIC, &ts);
    long last_time = ts.tv_nsec / 1000; // in milliseconds

    while (running) {
        // Wait for 125 microseconds
        nanosleep(&(struct timespec){0, 125000}, NULL);

        // Read microphone line
        int value = gpiod_line_get_value(mic_line);
        if (value < 0) {
            fprintf(stderr, "Failed to read microphone line: %s\n", gpiod_strerror(value));
            break;
        }

        // Check for sound peak (HIGH)
        if (value == 1) {
            // Get current time in milliseconds
            clock_gettime(CLOCK_MONOTONIC, &ts);
            long current_time = ts.tv_nsec / 1000;

            // Print timestamp
            printf("%ld\n", current_time);

            // Turn on LED
            ret = gpiod_line_set_value(led_line, 1);
            if (ret < 0) {
                fprintf(stderr, "Failed to set LED line: %s\n", gpiod_strerror(ret));
                break;
            }

