#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <sys/select.h>
#include <errno.h>

#define I2C_BUS 1
#define I2C_ADDR 0x60
#define ALS_REGISTER 0x0C
#define POLL_INTERVAL_MS 100
#define MAX_RETRIES 5
#define RETRY_DELAY_MS 500

typedef enum {
    I2C_OK,
    I2C_INIT_FAIL,
    I2C_READ_FAIL,
    I2C_WRITE_FAIL,
    I2C_NO_DEVICE,
    I2C_BUS_ERROR
} i2c_status;

typedef struct {
    int fd;
    int retry_count;
} i2c_context;

void handle_signal(int sig) {
    (void)sig;
    printf("\nCaught signal, exiting...\n");
    exit(EXIT_SUCCESS);
}

i2c_status i2c_init(int bus, int addr, i2c_context *ctx) {
    char filename[20];
    snprintf(filename, sizeof(filename), "/dev/i2c-%d", bus);
    ctx->fd = open(filename, O_RDWR);
    if (ctx->fd < 0) {
        perror("Failed to open I2C bus");
        return I2C_INIT_FAIL;
    }

    if (ioctl(ctx->fd, I2C_SLAVE, addr) < 0) {
        perror("Failed to set I2C slave address");
        close(ctx->fd);
        return I2C_INIT_FAIL;
    }

    ctx->retry_count = 0;
    return I2C_OK;
}

i2c_status i2c_read_register(i2c_context *ctx, uint8_t reg, uint16_t *value) {
    uint8_t buffer[2];
    buffer[0] = reg;

    if (write(ctx->fd, buffer, 1) != 1) {
        perror("I2C write failed");
        return I2C_WRITE_FAIL;
    }

    usleep(1000); // Small delay to allow the device to respond

    if (read(ctx->fd, buffer, 2) != 2) {
        perror("I2C read failed");
        return I2C_READ_FAIL;
    }

    *value = (uint16_t)(buffer[1] << 8 | buffer[0]);
    return I2C_OK;
}

void i2c_cleanup(i2c_context *ctx) {
    if (ctx->fd >= 0) {
        close(ctx->fd);
    }
}

int main() {
    i2c_context i2c_ctx;
    uint16_t als_value;
    i2c_status status;
    struct sigaction sa;
    fd_set read_fds;
    int ret;

    // Set up signal handler for Ctrl+C
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("Failed to set signal handler");
        return EXIT_FAILURE;
    }

    // Initialize I2C
    status = i2c_init(I2C_BUS, I2C_ADDR, &i2c_ctx);
    if (status != I2C_OK) {
        fprintf(stderr, "I2C initialization failed: %d\n", status);
        return EXIT_FAILURE;
    }

    while (1) {
        // Check for I2C bus errors
        FD_ZERO(&read_fds);
        FD_SET(i2c_ctx.fd, &read_fds);

        ret = select(i2c_ctx.fd + 1, &read_fds, NULL, NULL, NULL);
        if (ret < 0) {
            if (errno == EINTR) {
                continue; // Interrupted by signal, continue
            } else {
                perror("I2C select failed");
                break;
            }
        }

        // Read ALS register
        status = i2c_read_register(&i2c_ctx, ALS_REGISTER, &als_value);
        if (status != I2C_OK) {
            if (status == I2C_READ_FAIL) {
                fprintf(stderr, "I2C read failed, retrying...\n");
                if (i2c_ctx.retry_count < MAX_RETRIES) {
                    i2c_ctx.retry_count++;
                    usleep(RETRY_DELAY_MS * 1000);
                    continue;
                } else {
                    fprintf(stderr, "Max retries reached, exiting...\n");
                    break;
                }
            } else if (status == I2C_WRITE_FAIL) {
                fprintf(stderr, "I2C write failed, exiting...\n");
                break;
            } else if (status == I2C_NO_DEVICE) {
                fprintf(stderr, "No device at I2C address 0x%02X, exiting...\n", I2C_ADDR);
                break;
            } else {
                fprintf(stderr, "I2C error: %d, exiting...\n", status);
                break;
            }
        }

        // Log the raw ALS value
        printf("Raw ALS value: 0x%04X (%d)\n", als_value, als_value);

        // Delay for 100 ms
        usleep(POLL_INTERVAL_MS * 1000);
    }

    // Clean up
    i2c_cleanup(&i2c_ctx);
    return EXIT_SUCCESS;
}

