#include <linux/gpio.h>
#include <signal.h>
#include <errno.h>

#define GPIO_LEFT 2
#define GPIO_MIDDLE 3
#define GPIO_RIGHT 4
#define POLL_INTERVAL_MS 100
#define GPIO_DEVICE "/dev/gpiochip0"

typedef struct {
    int fd;
    struct gpio_line *line_left;
    struct gpio_line *line_middle;
    struct gpio_line *line_right;
} gpio_state_t;

void cleanup_gpio(gpio_state_t *state) {
    if (state->line_right) {
        gpio_line_release(state->line_right);
        state->line_right = NULL;
    }
    if (state->line_middle) {
        gpio_line_release(state->line_middle);
        state->line_middle = NULL;
    }
    if (state->line_left) {
        gpio_line_release(state->line_left);
        state->line_left = NULL;
    }
    if (state->fd >= 0) {
        close(state->fd);
        state->fd = -1;
    }
}

void handle_sigint(int sig) {
    cleanup_gpio(NULL);
    exit(EXIT_SUCCESS);
}

int open_gpio_line(int gpio_num, gpio_state_t *state) {
    int ret;
    struct gpio_line_request req = {
        .line = gpio_num,
        .flags = GPIO_LINE_FLAG_ACTIVE_LOW,
        .consumer = "tracking_sensor"
    };

    if (state->fd < 0) {
        state->fd = open(GPIO_DEVICE, O_RDWR);
        if (state->fd < 0) {
            perror("Failed to open GPIO device");
            return -1;
        }
    }

