#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/gpio.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_COUNT 8
#define GPIO_PINS[] {5, 6, 13, 19, 26, 12, 16, 20}
#define GPIO_COUNT 8
#define GPIO_PINS {5, 6, 13, 19, 26, 12, 16, 20}
#define POLL_INTERVAL_MS 200
#define MAX_LINE_LENGTH 128

typedef struct {
    gpiod_line *lines[GPIO_COUNT];
    gpiod_chip *chip;
    int running;
} TouchContext;

void handle_signal(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        printf("Shutting down...\n");
        TouchContext *ctx = (TouchContext *)malloc(sizeof(TouchContext));
        if (ctx) {
            for (int i = 0; i < GPIO_COUNT; i++) {
                if (ctx->lines[i]) {
                    gpiod_line_release(ctx->lines[i]);
                }
            }
            if (ctx->chip) {
                gpiod_chip_close(ctx->chip);
            }
            free(ctx);
        }
        exit(EXIT_SUCCESS);
    }
}

void init_gpio(TouchContext *ctx) {
    ctx->chip = gpiod_chip_open("/dev/gpiochip0");
    if (!ctx->chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < GPIO_COUNT; i++) {
        ctx->lines[i] = gpiod_chip_get_line(ctx->chip, GPIO_PINS[i]);
        if (!ctx->lines[i]) {
            fprintf(stderr, "Failed to get line for GPIO %d\n", GPIO_PINS[i]);
            exit(EXIT_FAILURE);
        }

        if (gpiod_line_request_output(ctx->lines[i], "touch_poll", GPIO_LINE_ACTIVE_LOW)) {
            fprintf(stderr, "Failed to request line for GPIO %d\n", GPIO_PINS[i]);
            exit(EXIT_FAILURE);
        }
    }
}

void read_gpio(TouchContext *ctx, int *values) {
    for (int i = 0; i < GPIO_COUNT; i++) {
        int value;
        if (gpiod_line_get_value(ctx->lines[i], &value)) {
            fprintf(stderr, "Failed to read GPIO %d\n", GPIO_PINS[i]);
            exit(EXIT_FAILURE);
        }
        values[i] = value;
    }
}

void format_output(double timestamp, int *values) {
    char buffer[MAX_LINE_LENGTH];
    snprintf(buffer, MAX_LINE_LENGTH, "[%0.3fs] CH1=%d CH2=%d CH3=%d CH4=%d CH5=%d CH6=%d CH7=%d CH8=%d", 
             timestamp, values[0], values[1], values[2], values[3], values[4], values[5], values[6], values[7]);
    printf("%s\n", buffer);
}

int main() {
    TouchContext ctx;
    init_gpio(&ctx);
    ctx.running = 1;

    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) || sigaction(SIGTERM, &sa, NULL)) {
        fprintf(stderr, "Failed to install signal handler\n");
        exit(EXIT_FAILURE);
    }

    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    long last_time = ts.tv_nsec;

    while (ctx.running) {
        struct timespec now;
        clock_gettime(CLOCK_MONOTONIC, &now);
        long elapsed = now.tv_nsec - last_time;
        if (elapsed < POLL_INTERVAL_MS * 1000000) {
            usleep(POLL_INTERVAL_MS * 1000 - elapsed / 1000);
        }

        int values[GPIO_COUNT];
        read_gpio(&ctx, values);

        double seconds = (now.tv_sec + (now.tv_nsec / 1e9)) - (ts.tv_sec + (ts.tv_nsec / 1e9));
        format_output(seconds, values);

        last_time = now.tv_nsec;
    }

    for (int i = 0; i < GPIO_COUNT; i++) {
        gpiod_line_release(ctx.lines[i]);
    }
    gpiod_chip_close(ctx.chip);

    return 0;
}

