#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/gpio.h>
#include <libgpiod.h>

#define GPIO_RED 17
#define GPIO_GREEN 18
#define GPIO_BLUE 27
#define PWM_FREQUENCY 1000
#define PWM_RESOLUTION 8
#define PWM_RANGE (1 << PWM_RESOLUTION)
#define FADE_STEPS 50
#define FADE_DURATION 5000  // in milliseconds

typedef struct {
    int red;
    int green;
    int blue;
} rgb_color;

static bool running = true;
static struct gpiod_line *lines[3];
static struct gpiod_line_request_config config;
static struct gpiod_chip *chip;
static rgb_color current_color;
static rgb_color target_color;
static int fade_step = 0;

void log_error(const char *message) {
    syslog(LOG_ERR, "%s", message);
}

void log_info(const char *message) {
    syslog(LOG_INFO, "%s", message);
}

void cleanup() {
    if (chip) {
        gpiod_chip_close(chip);
    }
    for (int i = 0; i < 3; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    closelog();
    log_info("Cleanup complete.");
}

void fade_to_color(rgb_color target) {
    for (int i = 0; i < FADE_STEPS && running; i++) {
        double fraction = (double)i / FADE_STEPS;
        current_color.red = (int)(current_color.red + (target.red - current_color.red) * fraction);
        current_color.green = (int)(current_color.green + (target.green - current_color.green) * fraction);
        current_color.blue = (int)(current_color.blue + (target.blue - current_color.blue) * fraction);

        // Clamp values to 0-255
        current_color.red = (current_color.red < 0) ? 0 : (current_color.red > 255 ? 255 : current_color.red);
        current_color.green = (current_color.green < 0) ? 0 : (current_color.green > 255 ? 255 : current_color.green);
        current_color.blue = (current_color.blue < 0) ? 0 : (current_color.blue > 255 ? 255 : current_color.blue);

        // Set PWM values
        gpiod_line_set_value(lines[0], current_color.red);
        gpiod_line_set_value(lines[1], current_color.green);
        gpiod_line_set_value(lines[2], current_color.blue);

        usleep(FADE_DURATION / FADE_STEPS);
    }
}

void handle_signal(int signal) {
    running = false;
    cleanup();
    exit(EXIT_SUCCESS);
}

int main() {
    int ret;
    FILE *urandom;
    unsigned int seed;

    // Initialize syslog
    openlog("rgb_fade", LOG_PID | LOG_CONS, LOG_USER);
    log_info("Starting RGB fade program.");

    // Seed with /dev/urandom
    urandom = fopen("/dev/urandom", "r");
    if (!urandom) {
        log_error("Failed to open /dev/urandom.");
        return EXIT_FAILURE;
    }
    ret = fread(&seed, sizeof(seed), 1, urandom);
    fclose(urandom);
    if (ret != 1) {
        log_error("Failed to read seed from /dev/urandom.");
        return EXIT_FAILURE;
    }
    srand(seed);

    // Initialize GPIO
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        log_error("Failed to open GPIO chip.");
        return EXIT_FAILURE;
    }

    // Configure lines
    config = gpiod_line_request_config();
    config.consumer = "rgb_fade";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;
    config.flags = GPIOD_LINE_REQUEST_FLAG_ACTIVE_LOW;

    lines[0] = gpiod_chip_request_line(chip, GPIO_RED);
    if (!lines[0]) {
        log_error("Failed to request GPIO RED.");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    lines[1] = gpiod_chip_request_line(chip, GPIO_GREEN);
    if (!lines[1]) {
        log_error("Failed to request GPIO GREEN.");
        gpiod_line_release(lines[0]);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    lines[2] = gpiod_chip_request_line(chip, GPIO_BLUE);
    if (!lines[2]) {
        log_error("Failed to request GPIO BLUE.");
        gpiod_line_release(lines[0]);
        gpiod_line_release(lines[1]);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set PWM mode
    for (int i = 0; i < 3; i++) {
        ret = gpiod_line_set_config(lines[i], GPIOD_LINE_CONFIG_FLAGS_OUTPUT);
        if (ret < 0) {
            log_error("Failed to set line configuration.");
            gpiod_line_release(lines[i]);
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }
    }

    // Initialize current color
    current_color.red = 0;
    current_color.green = 0;
    current_color.blue = 0;
    gpiod_line_set_value(lines[0], current_color.red);
    gpiod_line_set_value(lines[1], current_color.green);
    gpiod_line_set_value(lines[2], current_color.blue);

    // Signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (running) {
        // Generate random target color
        target_color.red = rand() % 256;
        target_color.green = rand() % 256;
        target_color.blue = rand() % 256;

        fade_to_color(target_color);
    }

    cleanup();
    return EXIT_SUCCESS;
}

