        return EXIT_FAILURE;
    }

    lines[2] = gpiod_chip_request_line(chip, GPIO_BLUE);
    if (!lines[2]) {
        log_error("Failed to request GPIO BLUE.");
        gpiod_line_release(lines[0]);
        gpiod_line_release(lines[1]);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set PWM mode
    for (int i = 0; i < 3; i++) {
        ret = gpiod_line_set_config(lines[i], GPIOD_LINE_CONFIG_FLAGS_OUTPUT);
        if (ret < 0) {
            log_error("Failed to set line configuration.");
            gpiod_line_release(lines[i]);
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }
    }

    // Initialize current color
    current_color.red = 0;
    current_color.green = 0;
    current_color.blue = 0;
    gpiod_line_set_value(lines[0], current_color.red);
    gpiod_line_set_value(lines[1], current_color.green);
    gpiod_line_set_value(lines[2], current_color.blue);

    // Signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (running) {
        // Generate random target color
        target_color.red = rand() % 256;
        target_color.green = rand() % 256;
        target_color.blue = rand() % 256;

        fade_to_color(target_color);
    }

    cleanup();
    return EXIT_SUCCESS;
}
