#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define TCS34725_ADDR 0x29
#define TCS34725_COMMAND 0x80
#define TCS34725_PON 0x06
#define TCS34725_AEN 0x04
#define TCS34725_ATIME 0x14
#define TCS34725_INTEGRATION_TIME 154000 // 154 ms in microseconds
#define TCS34725_WEN 0x08
#define TCS34725_PERS 0x0C
#define TCS34725_CONFIG 0x0F
#define TCS34725_CONTROL 0x0F
#define TCS34725_CLEAR 0x14
#define TCS34725_RED 0x16
#define TCS34725_GREEN 0x18
#define TCS34725_BLUE 0x1A
#define TCS34725_ID 0x12
#define TCS34725_ID_VALUE 0x4D

#define LED_PIN 17
#define RED_THRESHOLD 200
#define POLL_INTERVAL_MS 200

typedef struct {
    int i2c_fd;
    struct gpiod_line *led_line;
    int running;
} app_state;

void handle_signal(int sig) {
    app_state *state = (app_state *)malloc(sizeof(app_state));
    state->running = 0;
    free(state);
}

void init_i2c(app_state *state) {
    state->i2c_fd = open(I2C_BUS, O_RDWR);
    if (state->i2c_fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    if (ioctl(state->i2c_fd, I2C_SLAVE, TCS34725_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(state->i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Initialize sensor
    uint8_t data = TCS34725_PON | TCS34725_AEN;
    if (write(state->i2c_fd, &data, 1) != 1) {
        perror("Failed to write PON/AEN");
        close(state->i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Set integration time
    data = (TCS34725_INTEGRATION_TIME >> 8) & 0xFF;
    if (write(state->i2c_fd, &data, 1) != 1) {
        perror("Failed to write ATIME high byte");
        close(state->i2c_fd);
        exit(EXIT_FAILURE);
    }

    data = TCS34725_INTEGRATION_TIME & 0xFF;
    if (write(state->i2c_fd, &data, 1) != 1) {
        perror("Failed to write ATIME low byte");
        close(state->i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Set default configuration
    data = 0x03; // Enable RGBC, disable wait, enable interrupts
    if (write(state->i2c_fd, &data, 1) != 1) {
        perror("Failed to write CONFIG");
        close(state->i2c_fd);
        exit(EXIT_FAILURE);
    }
}

void init_gpio(app_state *state) {
    struct gpiod_chip *chip;
    chip = gpiod_chip_open("/dev/gpiochip4");
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    state->led_line = gpiod_line_get(chip, LED_PIN);
    if (!state->led_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(state->led_line, "LED", GPIOD_LINE_REQUEST_OUTPUT_ACTIVE_LOW)) {
        perror("Failed to request GPIO line");
        gpiod_line_release(state->led_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }
}

void read_sensor(app_state *state) {
    uint8_t data[4];
    if (read(state->i2c_fd, data, 4) != 4) {
        perror("Failed to read sensor data");
        return;
    }

    uint16_t clear = (data[1] << 8) | data[0];
    uint16_t red = (data[3] << 8) | data[2];
    uint16_t green = (data[5] << 8) | data[4];
    uint16_t blue = (data[7] << 8) | data[6];

    printf("Clear: %d, Red: %d, Green: %d, Blue: %d\n", clear, red, green, blue);

    if (red > RED_THRESHOLD) {
        gpiod_line_set_value(state->led_line, 1);
    } else {
        gpiod_line_set_value(state->led_line, 0);
    }
}

void cleanup(app_state *state) {
    if (state->i2c_fd >= 0) {
        close(state->i2c_fd);
    }

    if (state->led_line) {
        gpiod_line_release(state->led_line);
    }

    printf("Cleanup complete.\n");
}

int main() {
    app_state state = {0};

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    init_i2c(&state);
    init_gpio(&state);

    state.running = 1;
    while (state.running) {
        read_sensor(&state);
        usleep(200000); // 200 ms
    }

    cleanup(&state);
    return 0;
}

