#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/spi/spidev.h>
#include <signal.h>
#include <errno.h>
#include <stdint.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDR 0x23
#define SPI_BUS "/dev/spidev0.0"
#define LED_COUNT 30
#define SPI_SPEED 1000000
#define I2C_DELAY_MS 120
#define LED_START_FRAME 0xFFFFFFFF
#define LED_END_FRAME 0xFFFFFFFF

typedef struct {
    int i2c_fd;
    int spi_fd;
    uint8_t led_data[LED_COUNT * 4]; // 4 bytes per LED
} AppContext;

void handle_signal(int sig) {
    (void)sig;
    // Turn off all LEDs
    for (int i = 0; i < LED_COUNT; i++) {
        uint32_t frame = LED_START_FRAME;
        frame |= (0 << 24) | (0 << 16) | (0 << 8) | 0;
        memcpy(&led_data[i * 4], &frame, 4);
    }
    // Send the LED data
    if (spi_write(spi_fd, led_data, LED_COUNT * 4) < 0) {
        perror("SPI write on signal");
    }
    // Close file descriptors
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (spi_fd >= 0) {
        close(spi_fd);
    }
