        spi_fd = -1;
    }

    // Terminate program
    exit(EXIT_SUCCESS);
}

int open_i2c(int bus, int address) {
    char filename[20];
    snprintf(filename, sizeof(filename), "/dev/i2c-%d", bus);
    int fd = open(filename, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, address) < 0) {
        perror("Failed to set I2C address");
        close(fd);
        return -1;
    }

    return fd;
}

int read_bh1750(int fd) {
    unsigned char cmd[2] = {0x13, 0x00}; // Continuous measurement mode
    if (write(fd, cmd, 2) != 2) {
        perror("Failed to write to BH1750");
        return -1;
    }

    usleep(CONVERSION_DELAY_MS * 1000);

    unsigned char data[2];
    if (read(fd, data, 2) != 2) {
        perror("Failed to read from BH1750");
        return -1;
    }

    int lux = (data[0] << 8) | data[1];
    return lux;
}

