    // Initialize LED strip
    // Send reset command
    unsigned char reset_cmd[3] = {0x00, 0x00, 0x00};
    if (write(spi_fd, reset_cmd, 3) != 3) {
        perror("Failed to send reset command");
    }

    // Set all LEDs to off
    for (int i = 0; i < num_leds; i++) {
        unsigned char data[3] = {0x00, 0x00, 0x00};
        if (write(spi_fd, data, 3) != 3) {
            perror("Failed to set LED to off");
        }
    }
}

void fade_brightness(LedStrip *strip, int target_brightness) {
    strip->fade_target = target_brightness;
    strip->fade_remaining = abs(strip->brightness - target_brightness);
    strip->fade_step = (strip->brightness > target_brightness) ? -1 : 1;
    strip->fade_direction = (strip->brightness > target_brightness) ? 1 : 0;
}

void update_brightness(LedStrip *strip) {
    if (strip->fade_remaining <= 0) {
        strip->brightness = strip->fade_target;
        return;
    }

    strip->brightness += strip->fade_step;
    strip->fade_remaining -= abs(strip->fade_step);

    // Update all LEDs with the new brightness
    for (int i = 0; i < LED_COUNT; i++) {
        unsigned char data[3] = {0xFF, 0xFF, strip->brightness};
        if (write(spi_fd, data, 3) != 3) {
            perror("Failed to update LED brightness");
        }
    }
}

