    struct spi_ioc_transfer spi;
    memset(&spi, 0, sizeof(spi));
    spi.fd = spi_fd;
    spi.speed_hz = 1000000;
    spi.bits_per_word = 8;
    spi.delay_usecs = 0;
    spi.tx_buf = (unsigned long)&spi;
    spi.rx_buf = (unsigned long)&spi;
    spi.len = 3;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &spi) < 0) {
        perror("Failed to set SPI parameters");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    // Initialize LED strip
    init_led_strip(spi_fd, LED_COUNT);

    // Initialize BH1750 sensors
    BH1750Sensor sensors[MAX_SENSORS] = {{-1, 0, 0}, {-1, 0, 0}, {-1, 0, 0}};

    for (int i = 0; i < MAX_SENSORS; i++) {
