        usleep(UPDATE_INTERVAL_MS * 1000);
    }

    // Clean up
    for (int i = 0; i < MAX_SENSORS; i++) {
        if (sensors[i].fd >= 0) {
            close(sensors[i].fd);
        }
    }

    if (spi_fd >= 0) {
        close(spi_fd);
    }

    return EXIT_SUCCESS;
}
