#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/gpio.h>
#include <time.h>

#define GPIO_FLAME_SENSOR 4
#define GPIO_BUZZER 17
#define GPIO_LED 18

#define FLAME_READ_COUNT 5
#define FLAME_READ_INTERVAL_MS 100
#define SELF_TEST_LED_INTERVAL_MS 500
#define SELF_TEST_LED_COUNT 2
#define ERROR_LED_INTERVAL_MS 100
#define ERROR_LED_COUNT 5
#define ERROR_BUZZER_PATTERN_MS 200
#define ERROR_BUZZER_PATTERN_COUNT 4
#define ERROR_BUZZER_REPEAT_COUNT 3

#define MAIN_LOOP_INTERVAL_MS 50
#define LOG_BUFFER_SIZE 1024

typedef struct {
    int flame_fd;
    int buzzer_fd;
    int led_fd;
    int error;
} gpio_state;

void cleanup_gpio(gpio_state *state) {
    if (state->flame_fd >= 0) {
        gpio_close(state->flame_fd);
    }
    if (state->buzzer_fd >= 0) {
        gpio_close(state->buzzer_fd);
    }
    if (state->led_fd >= 0) {
        gpio_close(state->led_fd);
    }
    printf("GPIO lines cleaned up.\n");
}

void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Received SIGINT, cleaning up GPIO...\n");
        cleanup_gpio(NULL);
        exit(0);
    }
}

void log_event(const char *message) {
    char log_message[LOG_BUFFER_SIZE];
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    strftime(log_message, LOG_BUFFER_SIZE, "%Y-%m-%d %H:%M:%S - ", tm_info);
    strncat(log_message, message, LOG_BUFFER_SIZE - strlen(log_message) - 1);
    printf("%s\n", log_message);
}

int setup_gpio_line(int gpio_num, int direction) {
    int fd = gpio_open(gpio_num, GPIO_OPEN_READWRITE | GPIO_OPEN_EXPORT);
    if (fd < 0) {
        fprintf(stderr, "Failed to open GPIO %d: %s\n", gpio_num, strerror(errno));
        return -1;
    }

    if (gpio_set_direction(fd, direction) < 0) {
        fprintf(stderr, "Failed to set direction for GPIO %d: %s\n", gpio_num, strerror(errno));
        gpio_close(fd);
        return -1;
    }

    return fd;
}

int read_gpio_line(int fd) {
    int value;
    if (gpio_get_value(fd, &value) < 0) {
        fprintf(stderr, "Failed to read GPIO line: %s\n", strerror(errno));
        return -1;
    }
    return value;
}

int write_gpio_line(int fd, int value) {
    if (gpio_set_value(fd, value) < 0) {
        fprintf(stderr, "Failed to write GPIO line: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

void self_test(gpio_state *state) {
    int i;
    int flame_readings[FLAME_READ_COUNT];
    int flame_detected = 0;

    log_event("Starting self-test...");

    for (i = 0; i < SELF_TEST_LED_COUNT; i++) {
        write_gpio_line(state->led_fd, 1);
        usleep(SELF_TEST_LED_INTERVAL_MS * 1000);
        write_gpio_line(state->led_fd, 0);
        usleep(SELF_TEST_LED_INTERVAL_MS * 1000);
    }

    for (i = 0; i < FLAME_READ_COUNT; i++) {
        usleep(FLAME_READ_INTERVAL_MS * 1000);
        int value = read_gpio_line(state->flame_fd);
        if (value == 0) {
            flame_readings[i] = 1;
        } else {
            flame_readings[i] = 0;
        }
        log_event("Flame sensor read: %d", flame_readings[i]);
    }

    for (i = 0; i < FLAME_READ_COUNT; i++) {
        if (flame_readings[i] == 1) {
            flame_detected = 1;
            break;
        }
    }

    if (flame_detected) {
        log_event("Flame detected during self-test. Error detected.");
        state->error = 1;
    } else {
        log_event("Self-test completed successfully.");
        state->error = 0;
    }
}

void error_signal(gpio_state *state) {
    int i;
    int pattern[ERROR_BUZZER_PATTERN_COUNT] = {0, 0, 1, 0};
    int repeat_count = ERROR_BUZZER_REPEAT_COUNT;

    log_event("Error detected: Flaming detected during self-test.");

    for (i = 0; i < ERROR_LED_COUNT; i++) {
        write_gpio_line(state->led_fd, 1);
        usleep(ERROR_LED_INTERVAL_MS * 1000);
        write_gpio_line(state->led_fd, 0);
        usleep(ERROR_LED_INTERVAL_MS * 1000);
    }

    for (i = 0; i < repeat_count; i++) {
        for (int j = 0; j < ERROR_BUZZER_PATTERN_COUNT; j++) {
            write_gpio_line(state->buzzer_fd, pattern[j]);
            usleep(ERROR_BUZZER_PATTERN_MS * 1000);
        }
    }

    write_gpio_line(state->buzzer_fd, 0);
    write_gpio_line(state->led_fd, 0);
    log_event("Error signal completed.");
    exit(1);
}

void main_loop(gpio_state *state) {
    int last_flame_state = 1;
    int flame_detected = 0;

    log_event("Starting main loop...");

    while (1) {
        usleep(MAIN_LOOP_INTERVAL_MS * 1000);
        int current_flame_state = read_gpio_line(state->flame_fd);

        if (current_flame_state == 0) {
            if (last_flame_state == 1) {
                log_event("Flame detected at %s", ctime(&time(0)));
                write_gpio_line(state->buzzer_fd, 1);
                write_gpio_line(state->led_fd, 1);
                flame_detected = 1;
            }
        } else {
            if (flame_detected) {
                log_event("Flame cleared at %s", ctime(&time(0)));
                write_gpio_line(state->buzzer_fd, 0);
                write_gpio_line(state->led_fd, 0);
                flame_detected = 0;
            }
        }

        last_flame_state = current_flame_state;
    }
}

int main() {
    signal(SIGINT, signal_handler);

    gpio_state state = {0};

    state.flame_fd = setup_gpio_line(GPIO_FLAME_SENSOR, GPIO_DIRECTION_INPUT);
    if (state.flame_fd < 0) {
        fprintf(stderr, "Failed to setup flame sensor GPIO.\n");
        return 1;
    }

    state.buzzer_fd = setup_gpio_line(GPIO_BUZZER, GPIO_DIRECTION_OUTPUT);
    if (state.buzzer_fd < 0) {
        fprintf(stderr, "Failed to setup buzzer GPIO.\n");
        cleanup_gpio(&state);
        return 1;
