#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/gpio.h>

#define I2C_BUS "/dev/i2c-1"
#define BH1750_ADDR 0x23
#define LED_PIN 17
#define BUFFER_SIZE 60
#define MAX_LUX 1000
#define MIN_LUX 0
#define MIN_FREQ 0.5
#define MAX_FREQ 5.0

typedef struct {
    int buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

void init_buffer(CircularBuffer *cb) {
    cb->head = 0;
    cb->count = 0;
    for (int i = 0; i < BUFFER_SIZE; i++) {
        cb->buffer[i] = 0;
    }
}

void add_to_buffer(CircularBuffer *cb, int value) {
    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    cb->count = (cb->count + 1) % BUFFER_SIZE;
}

int average_buffer(CircularBuffer *cb) {
    int sum = 0;
    for (int i = 0; i < BUFFER_SIZE; i++) {
        sum += cb->buffer[i];
    }
    return sum / BUFFER_SIZE;
}

void handle_sigint(int sig) {
    printf("\nCaught SIGINT, cleaning up...\n");
    close(i2c_fd);
    gpio_unexport(LED_PIN);
    exit(EXIT_SUCCESS);
}

int i2c_fd = -1;
CircularBuffer light_buffer;

int read_bh1750(int fd) {
    unsigned char cmd[2] = {0x40, 0x00}; // Continuous high resolution mode
    if (ioctl(fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        return -1;
    }

    if (write(fd, cmd, 2) != 2) {
        perror("Failed to write to I2C device");
        return -1;
    }

    usleep(100000); // Wait for measurement

    unsigned char data[2];
    if (read(fd, data, 2) != 2) {
        perror("Failed to read from I2C device");
        return -1;
    }

    int lux = (data[0] << 8) | data[1];
    return lux;
}

int main() {
    signal(SIGINT, handle_sigint);

    // Initialize GPIO
    int gpio_fd = -1;
    gpio_fd = open("/dev/gpiochip0", O_RDWR);
    if (gpio_fd < 0) {
        perror("Failed to open GPIO device");
        return EXIT_FAILURE;
    }

    if (ioctl(gpio_fd, GPIO_GET_LINEHANDLE_IOCTL, &LED_PIN) < 0) {
        perror("Failed to get GPIO line handle");
        close(gpio_fd);
        return EXIT_FAILURE;
    }

    if (ioctl(gpio_fd, GPIO_LINE_SET_FLAGS, GPIO_LINE_FLAG_OUTPUT) < 0) {
        perror("Failed to set GPIO line as output");
        close(gpio_fd);
        return EXIT_FAILURE;
    }

    // Initialize I2C
    i2c_fd = open(I2C_BUS, O_RDWR | O_NONBLOCK);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        close(gpio_fd);
        return EXIT_FAILURE;
    }

    init_buffer(&light_buffer);

    while (1) {
        int lux = read_bh1750(i2c_fd);
        if (lux < 0) {
            fprintf(stderr, "Sensor read failed, skipping...\n");
            usleep(1000000); // 1 second
            continue;
        }

        add_to_buffer(&light_buffer, lux);
        int avg_lux = average_buffer(&light_buffer);

        // Map lux to frequency
        double freq = MIN_FREQ + (double)(avg_lux - MIN_LUX) / (MAX_LUX - MIN_LUX) * (MAX_FREQ - MIN_FREQ);

        // Blink LED with square wave
        double period = 1.0 / freq;
        double half_period = period / 2.0;
        double elapsed = 0.0;
        double last_toggle = 0.0;

        while (elapsed < period) {
            usleep(10000); // 10ms
            elapsed += 0.01;

            if (elapsed > last_toggle + half_period) {
                last_toggle = elapsed;
                if (ioctl(gpio_fd, GPIO_LINE_SET_VALUE, 1) < 0) {
                    perror("Failed to set GPIO high");
                }
            } else if (elapsed > last_toggle + period) {
                last_toggle = elapsed;
                if (ioctl(gpio_fd, GPIO_LINE_SET_VALUE, 0) < 0) {
                    perror("Failed to set GPIO low");
                }
            }
        }

        usleep(1000000 - (int)(elapsed * 1000000)); // Adjust for timing
    }

    close(i2c_fd);
    close(gpio_fd);
    return EXIT_SUCCESS;
}

