#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/gpio.h>
#include <libgpiod.h>

#define GPIO_DATA_PIN 17
#define GPIO_CLOCK_PIN 18
#define GPIO_LATCH_PIN 27

// Segment mapping for common-cathode 7-segment display
// a b c d e f g dp
// 0 1 2 3 4 5 6 7
// Digit '5' is a=1, b=1, c=0, d=1, e=1, f=0, g=1, dp=0
const uint8_t digit_5 = 0b11111010; // a=1, b=1, c=0, d=1, e=1, f=0, g=1, dp=0

// Function to shift out 8 bits MSB first
void shift_out(gpio_line *data_line, gpio_line *clock_line, gpio_line *latch_line, uint8_t data) {
    for (int i = 0; i < 8; i++) {
        // Set data line to the current bit
        if (data & (1 << (7 - i))) {
            gpio_line_set_value(data_line, 1);
        } else {
            gpio_line_set_value(data_line, 0);
        }

        // Pulse the clock line
        gpio_line_set_value(clock_line, 1);
        usleep(100); // Clock pulse delay
        gpio_line_set_value(clock_line, 0);
        usleep(100); // Clock pulse delay
    }

    // Latch the data
    gpio_line_set_value(latch_line, 1);
    usleep(100); // Latch delay
    gpio_line_set_value(latch_line, 0);
    usleep(100); // Latch delay
}

int main() {
    int ret;
    struct gpiod_line *data_line = NULL;
    struct gpiod_line *clock_line = NULL;
    struct gpiod_line *latch_line = NULL;
    struct gpiod_chip *chip = NULL;

    // Open the GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return 1;
    }

    // Request data line (GPIO17)
    data_line = gpiod_chip_get_line(chip, GPIO_DATA_PIN);
    if (!data_line) {
        fprintf(stderr, "Failed to get data line\n");
        goto error_close_chip;
    }
    ret = gpiod_line_request_output(data_line, "data", GPIO_ACTIVE_LOW);
    if (ret < 0) {
        fprintf(stderr, "Failed to request data line: %s\n", strerror(errno));
        goto error_free_data_line;
    }

    // Request clock line (GPIO18)
    clock_line = gpiod_chip_get_line(chip, GPIO_CLOCK_PIN);
    if (!clock_line) {
        fprintf(stderr, "Failed to get clock line\n");
        goto error_free_data_line;
    }
    ret = gpiod_line_request_output(clock_line, "clock", GPIO_ACTIVE_LOW);
    if (ret < 0) {
        fprintf(stderr, "Failed to request clock line: %s\n", strerror(errno));
        goto error_free_clock_line;
    }

    // Request latch line (GPIO27)
    latch_line = gpiod_chip_get_line(chip, GPIO_LATCH_PIN);
    if (!latch_line) {
        fprintf(stderr, "Failed to get latch line\n");
        goto error_free_clock_line;
    }
    ret = gpiod_line_request_output(latch_line, "latch", GPIO_ACTIVE_LOW);
    if (ret < 0) {
        fprintf(stderr, "Failed to request latch line: %s\n", strerror(errno));
        goto error_free_latch_line;
    }

    // Shift out the digit '5'
    shift_out(data_line, clock_line, latch_line, digit_5);

    // Blink the digit '5' with 500ms on and 500ms off
    while (1) {
        shift_out(data_line, clock_line, latch_line, digit_5);
        usleep(500000); // 500ms on
        shift_out(data_line, clock_line, latch_line, 0x00); // Turn off all segments
        usleep(500000); // 500ms off
    }

error_free_latch_line:
    gpiod_line_put(latch_line);
error_free_clock_line:
    gpiod_line_put(clock_line);
error_free_data_line:
    gpiod_line_put(data_line);
error_close_chip:
    gpiod_chip_close(chip);
    return 1;
}

