        shift_out(data_line, clock_line, latch_line, digit_5);
        usleep(500000); // 500ms on
        shift_out(data_line, clock_line, latch_line, 0x00); // Turn off all segments
        usleep(500000); // 500ms off
    }

error_free_latch_line:
    gpiod_line_put(latch_line);
error_free_clock_line:
    gpiod_line_put(clock_line);
error_free_data_line:
    gpiod_line_put(data_line);
error_close_chip:
    gpiod_chip_close(chip);
    return 1;
}
