#define LED_GPIO 17
#define BUTTON_GPIO 18
#define LED_LINE "gpio17"
#define BUTTON_LINE "gpio18"
#define LED_LOW 0
#define LED_HIGH 1
#define BUTTON_PULL_UP GPIO_LINE_PULL_UP
#define BUTTON_EDGE GPIO_LINE_EVENT_FALLING_EDGE
#define TIMEOUT_MS 1000
#define LED_DELAY_MS 1000

typedef struct {
    struct gpiod_chip *chip;
    struct gpiod_line *led_line;
    struct gpiod_line *button_line;
    int running;
} app_state;

void handle_signal(int sig) {
    if (sig == SIGINT) {
        printf("\nCaught SIGINT, stopping LED and exiting...\n");
    }
    if (app_state.running) {
        app_state.running = 0;
    }
}

void cleanup_app(app_state *state) {
    if (state->chip) {
        gpiod_chip_close(state->chip);
    }
    if (state->led_line) {
        gpiod_line_release(state->led_line);
    }
    if (state->button_line) {
        gpiod_line_release(state->button_line);
    }
    printf("Resources released.\n");
}

int main() {
    app_state state = {0};
    struct gpiod_line_event event;
    int ret;

    // Initialize signal handling
    signal(SIGINT, handle_signal);

    // Open GPIO chip 0
    state.chip = gpiod_chip_open(0);
    if (!state.chip) {
        fprintf(stderr, "Failed to open GPIO chip 0\n");
        return 1;
    }

    // Request LED line (output, initially low)
    state.led_line = gpiod_chip_get_line(state.chip, LED_GPIO);
    if (!state.led_line) {
        fprintf(stderr, "Failed to get LED line %d\n", LED_GPIO);
        cleanup_app(&state);
        return 1;
    }

    ret = gpiod_line_request_output(state.led_line, "LED", LED_LOW);
    if (ret < 0) {
        fprintf(stderr, "Failed to request LED line: %s\n", gpiod_strerror(ret));
        cleanup_app(&state);
        return 1;
    }

    // Request button line (input, pull-up, event detection)
    state.button_line = gpiod_chip_get_line(state.chip, BUTTON_GPIO);
    if (!state.button_line) {
        fprintf(stderr, "Failed to get button line %d\n", BUTTON_GPIO);
        cleanup_app(&state);
        return 1;
    }

    ret = gpiod_line_request_input(state.button_line, "Button", BUTTON_PULL_UP);
    if (ret < 0) {
        fprintf(stderr, "Failed to request button line: %s\n", gpiod_strerror(ret));
        cleanup_app(&state);
        return 1;
    }

    ret = gpiod_line_event_request(state.button_line, BUTTON_EDGE, 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request event on button line: %s\n", gpiod_strerror(ret));
        cleanup_app(&state);
        return 1;
    }

    state.running = 1;

    while (state.running) {
        // Blink LED
        gpiod_line_set_value(state.led_line, LED_HIGH);
        usleep(LED_DELAY_MS * 1000);

        gpiod_line_set_value(state.led_line, LED_LOW);
        usleep(LED_DELAY_MS * 1000);

        // Check for button event
        ret = gpiod_line_event_wait(state.button_line, TIMEOUT_MS * 1000);
        if (ret < 0) {
            if (ret == -ETIMEDOUT) {
                continue;
            } else {
                fprintf(stderr, "Error waiting for button event: %s\n", gpiod_strerror(ret));
                cleanup_app(&state);
                return 1;
            }
        }

        // Read event
        ret = gpiod_line_event_read(state.button_line, &event);
        if (ret < 0) {
            fprintf(stderr, "Error reading button event: %s\n", gpiod_strerror(ret));
            cleanup_app(&state);
            return 1;
        }

        if (event.type == GPIO_LINE_EVENT_FALLING_EDGE) {
            printf("Button pressed, stopping LED...\n");
            gpiod_line_set_value(state.led_line, LED_LOW);
            state.running = 0;
        }
    }

    cleanup_app(&state);
    return 0;
}

