int main() {
    struct gpiod_chip *chip;
    struct gpiod_line_request_config req_config;
    int ret;

    // Initialize signal handling
    signal(SIGINT, handle_sigint);

    // Open the GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    // Configure the line
    gpiod_line_request_config_init(&req_config);
    req_config.consumer = "blink_led";
    req_config.flags = GPIOD_LINE_REQUEST_FLAG_ACTIVE_LOW;
    req_config.output = 1;

    line = gpiod_chip_get_line(chip, GPIO_PIN);
