            printf("LED OFF\n");
            fflush(stdout);
            state = STATE_ON;
        }

        usleep(ON_DELAY_MS * 1000);
        usleep(OFF_DELAY_MS * 1000);
    }

    // Cleanup
    cleanup();

    return EXIT_SUCCESS;
}

