#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/gpio.h>

#define LED_PIN 24
#define BUTTON_PIN 22
#define LED_ON 1
#define LED_OFF 0
#define BUTTON_ACTIVE 1
#define BUTTON_INACTIVE 0
#define BLINK_INTERVAL_MS 500
#define ERROR_MSG_SIZE 256

typedef struct {
    int chip_fd;
    struct gpio_line *led_line;
    struct gpio_line *button_line;
    int running;
} gpio_state;

void error_exit(const char *msg) {
    fprintf(stderr, "Error: %s\n", msg);
    exit(EXIT_FAILURE);
}

void handle_signal(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        printf("Received signal, exiting...\n");
        exit(EXIT_SUCCESS);
    }
}

void init_gpio(gpio_state *state) {
    state->chip_fd = -1;
    state->led_line = NULL;
    state->button_line = NULL;
    state->running = 1;

    // Open the GPIO chip
    state->chip_fd = gpio_open("/dev/gpiochip0", O_RDWR);
    if (state->chip_fd < 0) {
        error_exit("Failed to open GPIO chip");
    }

    // Configure LED pin (output, low)
    struct gpio_line_request req;
    memset(&req, 0, sizeof(req));
    req.line_offset = LED_PIN;
    req.flags = GPIO_LINE_FLAG_OUTPUT;

    state->led_line = gpio_request_line(state->chip_fd, &req);
    if (!state->led_line) {
        error_exit("Failed to request LED GPIO line");
    }

    if (gpio_line_set_value(state->led_line, LED_OFF) < 0) {
        error_exit("Failed to set LED GPIO line value");
    }

    // Configure button pin (input, pull-down)
    memset(&req, 0, sizeof(req));
    req.line_offset = BUTTON_PIN;
    req.flags = GPIO_LINE_FLAG_INPUT | GPIO_LINE_FLAG_PULL_DOWN;

    state->button_line = gpio_request_line(state->chip_fd, &req);
    if (!state->button_line) {
        error_exit("Failed to request button GPIO line");
    }

    // Set initial direction
    if (gpio_line_set_direction(state->button_line, GPIO_LINE_DIRECTION_INPUT) < 0) {
        error_exit("Failed to set button GPIO line direction");
    }
}

void deinit_gpio(gpio_state *state) {
    if (state->button_line) {
        gpio_free_line(state->button_line);
    }
    if (state->led_line) {
        gpio_free_line(state->led_line);
    }
    if (state->chip_fd >= 0) {
        close(state->chip_fd);
    }
}

void blink_led(gpio_state *state) {
    int value = LED_ON;
    while (state->running) {
        if (gpio_line_get_value(state->button_line) == BUTTON_ACTIVE) {
            if (gpio_line_set_value(state->led_line, value) < 0) {
                fprintf(stderr, "Error setting LED value\n");
            }
            value = !value;
            usleep(BLINK_INTERVAL_MS * 1000);
        } else {
            value = LED_OFF;
            if (gpio_line_set_value(state->led_line, value) < 0) {
                fprintf(stderr, "Error setting LED value\n");
            }
            usleep(100); // Small delay to avoid busy-waiting
        }
    }
}

int main() {
    gpio_state state;
    init_gpio(&state);

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    printf("Press the button to blink the LED. Press Ctrl-C to exit.\n");

    blink_led(&state);

    deinit_gpio(&state);
    return 0;
}

