#define GPIO_RED   24
#define GPIO_GREEN 23
#define GPIO_BLUE  18
#define PWM_PERIOD 10000000  // 10 ms in nanoseconds
#define PWM_CYCLE  10000000  // 10 ms in nanoseconds
#define PWM_DELAY  10000000  // 10 ms in nanoseconds
#define PWM_RESOLUTION 100
#define PWM_MAX 100
#define PWM_MIN 0
#define PWM_UPDATE_INTERVAL 100000000  // 100 ms in nanoseconds

typedef struct {
    struct gpiod_line *red_line;
    struct gpiod_line *green_line;
    struct gpiod_line *blue_line;
    int red;
    int green;
    int blue;
} rgb_led;

void cleanup_gpio(rgb_led *led) {
    if (led->red_line) {
        gpiod_line_release(led->red_line);
    }
    if (led->green_line) {
        gpiod_line_release(led->green_line);
    }
    if (led->blue_line) {
        gpiod_line_release(led->blue_line);
    }
}

void signal_handler(int signum) {
    if (signum == SIGINT) {
        printf("\nCaught SIGINT, cleaning up and exiting...\n");
        cleanup_gpio(&led);
        exit(EXIT_SUCCESS);
    }
}

void set_pwm_value(struct gpiod_line *line, int value) {
    if (value < 0 || value > 100) {
        fprintf(stderr, "Invalid PWM value: %d\n", value);
        return;
    }

    int duty_cycle = (value * PWM_PERIOD) / PWM_RESOLUTION;
    int on_time = duty_cycle;
    int off_time = PWM_PERIOD - on_time;

    if (gpiod_line_set_value(line, 1) < 0) {
        fprintf(stderr, "Failed to set line to high\n");
        return;
    }

    struct timespec ts = {0, 0};
    if (clock_nanosleep(CLOCK_MONOTONIC, 0, &ts, &ts) < 0) {
        fprintf(stderr, "Failed to start nanosleep\n");
        gpiod_line_set_value(line, 0);
        return;
    }

    if (gpiod_line_set_value(line, 0) < 0) {
        fprintf(stderr, "Failed to set line to low\n");
        return;
    }

    if (clock_nanosleep(CLOCK_MONOTONIC, 0, &ts, &ts) < 0) {
        fprintf(stderr, "Failed to end nanosleep\n");
        return;
    }
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *red_line = NULL;
    struct gpiod_line *green_line = NULL;
    struct gpiod_line *blue_line = NULL;
    int ret;
    int red, green, blue;
    struct timespec ts = {0, 0};
    struct timespec sleep_ts = {0, 0};
    struct timespec remaining_ts = {0, 0};

    signal(SIGINT, signal_handler);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    red_line = gpiod_chip_get_line(chip, GPIO_RED);
    if (!red_line) {
        fprintf(stderr, "Failed to get red GPIO line\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    green_line = gpiod_chip_get_line(chip, GPIO_GREEN);
    if (!green_line) {
        fprintf(stderr, "Failed to get green GPIO line\n");
        gpiod_chip_close(chip);
