#include <gpiod.h>
#include <time.h>

#define I2C_BUS 1
#define I2C_ADDR_ACCEL 0x19
#define ACCEL_REGISTER_CTRL_REG1_A 0x20
#define ACCEL_REGISTER_OUT_X_L_A 0x28
#define ACCEL_REGISTER_OUT_X_H_A 0x29
#define ACCEL_REGISTER_OUT_Y_L_A 0x2A
#define ACCEL_REGISTER_OUT_Y_H_A 0x2B
#define ACCEL_REGISTER_OUT_Z_L_A 0x2C
#define ACCEL_REGISTER_OUT_Z_H_A 0x2D
#define ACCEL_RANGE 2
#define ACCEL_SCALE 16384.0
#define DEFAULT_THRESHOLD 2.0
#define GPIO_PIN 17
#define PULSE_DURATION 50
#define LOG_FILE "impact_log.txt"

typedef struct {
    int fd;
    struct gpiod_line *gpio_line;
    FILE *log_file;
    double threshold;
    int running;
} app_state;

void handle_signal(int sig) {
    app_state *state = (app_state *)malloc(sizeof(app_state));
    if (state) {
        state->running = 0;
        free(state);
    }
}

void init_i2c(int *fd, int bus) {
    char filename[20];
    snprintf(filename, sizeof(filename), "/dev/i2c-%d", bus);
    *fd = open(filename, O_RDWR);
    if (*fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    if (ioctl(*fd, I2C_SLAVE, I2C_ADDR_ACCEL) < 0) {
        perror("Failed to set I2C slave address");
        close(*fd);
        exit(EXIT_FAILURE);
    }
}

void init_gpio(struct gpiod_line **gpio_line) {
    struct gpiod_chip *chip;
    chip = gpiod_chip_open("/dev/gpiochip1");
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    *gpio_line = gpiod_line_request_output(chip, "gpio17", "impact_indicator", 0, GPIOD_LINE_REQUEST_FLAG_ACTIVE_LOW);
    if (!*gpio_line) {
        perror("Failed to request GPIO line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }
}

void init_logging(FILE **log_file) {
    *log_file = fopen(LOG_FILE, "a");
    if (!*log_file) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }
}

void read_accel_data(int fd, int *x, int *y, int *z) {
    if (ioctl(fd, I2C_RDWR, (struct i2c_msg *)NULL) < 0) {
        perror("I2C read error");
        exit(EXIT_FAILURE);
    }

    char buffer[6];
    if (read(fd, buffer, 6) != 6) {
        perror("Failed to read accelerometer data");
        exit(EXIT_FAILURE);
    }

    *x = (buffer[1] << 8) | buffer[0];
    *y = (buffer[3] << 8) | buffer[2];
    *z = (buffer[5] << 8) | buffer[4];
}

void compute_magnitude(int x, int y, int z, double *magnitude) {
    double x_g = (double)x / ACCEL_SCALE;
    double y_g = (double)y / ACCEL_SCALE;
    double z_g = (double)z / ACCEL_SCALE;
    *magnitude = sqrt(x_g * x_g + y_g * y_g + z_g * z_g);
}

void trigger_impact(int fd, struct gpiod_line *gpio_line) {
    gpiod_line_set_value(gpio_line, 1);
    usleep(PULSE_DURATION * 1000);
    gpiod_line_set_value(gpio_line, 0);
}

void log_data(FILE *log_file, time_t timestamp, int x, int y, int z, double magnitude) {
    fprintf(log_file, "%lu,%d,%d,%d,%f\n", (unsigned long)timestamp, x, y, z, magnitude);
    fflush(log_file);
}

void cleanup(app_state *state) {
    if (state->gpio_line) {
        gpiod_line_release(state->gpio_line);
    }
    if (state->fd >= 0) {
        close(state->fd);
    }
    if (state->log_file) {
        fclose(state->log_file);
    }
    free(state);
}

int main(int argc, char *argv[]) {
    app_state *state = (app_state *)malloc(sizeof(app_state));
    if (!state) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }

    state->running = 1;
    state->threshold = DEFAULT_THRESHOLD;

    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "-t") == 0 && i + 1 < argc) {
            state->threshold = atof(argv[i + 1]);
            i++;
        }
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    init_i2c(&state->fd, I2C_BUS);
    init_gpio(&state->gpio_line);
    init_logging(&state->log_file);

    // Set accelerometer to 2g range and 10Hz output data rate
    char ctrl_reg1[1] = {0x80 | (ACCEL_RANGE << 3) | 0x08}; // 2g, 10Hz
    if (write(state->fd, ctrl_reg1, 1) != 1) {
        perror("Failed to write to accelerometer");
        cleanup(state);
        exit(EXIT_FAILURE);
    }

    while (state->running) {
        int x, y, z;
        read_accel_data(state->fd, &x, &y, &z);

        double magnitude;
        compute_magnitude(x, y, z, &magnitude);

        time_t timestamp = time(NULL);
        log_data(state->log_file, timestamp, x, y, z, magnitude);

        if (magnitude > state->threshold) {
            trigger_impact(state->fd, state->gpio_line);
        }

        usleep(100000); // 100ms = 10Hz
    }

    cleanup(state);
    return 0;
}

