#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>
#include <errno.h>

#define I2C_BUS 1
#define I2C_ADDR 0x48
#define ALS_REGISTER 0x00
#define RED_REGISTER 0x01
#define GREEN_REGISTER 0x02
#define BLUE_REGISTER 0x03
#define LED_PIN 18
#define CSV_FILE "color_log.csv"
#define SAMPLE_INTERVAL_MS 500
#define LED_PWM_PERIOD_US 1000000
#define LED_PWM_DUTY_CYCLE_MAX 1000000
#define RETRY_DELAY_MS 100

typedef struct {
    int i2c_fd;
    struct gpiod_line *led_line;
    FILE *csv_file;
    int running;
} app_state;

void handle_signal(int sig) {
    app_state *state = (app_state *)malloc(sizeof(app_state));
    if (state) {
        state->running = 0;
        free(state);
    }
}

void log_error(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
}

void close_resources(app_state *state) {
    if (state->csv_file) {
        fclose(state->csv_file);
    }
    if (state->i2c_fd >= 0) {
        close(state->i2c_fd);
    }
    if (state->led_line) {
        gpiod_line_release(state->led_line);
    }
}

void setup_i2c(int *fd) {
    char i2c_bus_path[32];
    snprintf(i2c_bus_path, sizeof(i2c_bus_path), "/dev/i2c-%d", I2C_BUS);
    *fd = open(i2c_bus_path, O_RDWR);
    if (*fd < 0) {
        log_error("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    if (ioctl(*fd, I2C_TEN, 0) < 0) {
        log_error("Failed to set I2C to 10-bit mode");
        close(*fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(*fd, I2C_SLAVE, I2C_ADDR) < 0) {
        log_error("Failed to set I2C slave address");
        close(*fd);
        exit(EXIT_FAILURE);
    }
}

void setup_led() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    const char *chip_name = "gpiochip4";
    int pin = LED_PIN;

    chip = gpiod_chip_open_by_name(chip_name);
    if (!chip) {
        log_error("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    line = gpiod_line_request_output(chip, "led", pin, 0);
    if (!line) {
        log_error("Failed to request GPIO line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    gpiod_line_set_value(line, 0); // Turn off LED initially
    gpiod_line_set_flags(line, GPIOD_LINE_FLAG_ACTIVE_LOW);

    return line;
}

void read_sensor_data(int i2c_fd, uint16_t *als, uint16_t *red, uint16_t *green, uint16_t *blue) {
    uint8_t buffer[4];
    int ret;

    ret = read(i2c_fd, buffer, 4);
    if (ret < 0) {
        log_error("I2C read failed");
        return;
    }

    *als = (buffer[0] << 8) | buffer[1];
    *red = (buffer[2] << 8) | buffer[3];
    *green = (buffer[2] << 8) | buffer[3];
    *blue = (buffer[2] << 8) | buffer[3];
}

void write_sensor_register(int i2c_fd, uint8_t reg, uint8_t value) {
    uint8_t buffer[1];
    buffer[0] = value;
    if (write(i2c_fd, buffer, 1) < 0) {
        log_error("I2C write failed");
    }
}

void setup_sensor(int i2c_fd) {
    write_sensor_register(i2c_fd, 0x00, 0x00); // Reset
    usleep(100000);
    write_sensor_register(i2c_fd, 0x01, 0x00); // ALS gain
    write_sensor_register(i2c_fd, 0x02, 0x00); // Red gain
    write_sensor_register(i2c_fd, 0x03, 0x00); // Green gain
    write_sensor_register(i2c_fd, 0x04, 0x00); // Blue gain
    write_sensor_register(i2c_fd, 0x05, 0x00); // ALS integration time
    write_sensor_register(i2c_fd, 0x06, 0x00); // Red integration time
    write_sensor_register(i2c_fd, 0x07, 0x00); // Green integration time
    write_sensor_register(i2c_fd, 0x08, 0x00); // Blue integration time
    write_sensor_register(i2c_fd, 0x09, 0x00); // ALS enable
    write_sensor_register(i2c_fd, 0x0A, 0x00); // Red enable
    write_sensor_register(i2c_fd, 0x0B, 0x00); // Green enable
    write_sensor_register(i2c_fd, 0x0C, 0x00); // Blue enable
}

void write_csv_header(FILE *file) {
    fprintf(file, "timestamp,ALS,Red,Green,Blue\n");
}

void write_csv_data(FILE *file, time_t timestamp, uint16_t als, uint16_t red, uint16_t green, uint16_t blue) {
    fprintf(file, "%lu,%u,%u,%u,%u\n", (unsigned long)timestamp, als, red, green, blue);
}

void update_led_brightness(uint16_t als, struct gpiod_line *led_line) {
    float brightness = (float)als / 65535.0;
    int duty_cycle = (int)(brightness * LED_PWM_DUTY_CYCLE_MAX);
    gpiod_line_set_value(led_line, duty_cycle);
}

int main() {
    app_state state = {0};
    int i2c_fd;
