        perror("Failed to set I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

int read_register(int fd, int reg) {
    char buf[1];
    if (ioctl(fd, I2C_RDWR, (struct i2c_msg *)buf) < 0) {
        perror("Failed to write register address");
        return -1;
    }

    if (ioctl(fd, I2C_RDWR, (struct i2c_msg *)buf) < 0) {
        perror("Failed to read register value");
        return -1;
    }

    return buf[0];
