        int x, y, z;
        if (read_register(context->fd, 0x29) < 0) return;
        if (read_register(context->fd, 0x28) < 0) return;
        if (read_register(context->fd, 0x27) < 0) return;
        context->calibration_samples[0][i] = (int)read_register(context->fd, 0x29);
        context->calibration_samples[1][i] = (int)read_register(context->fd, 0x28);
        context->calibration_samples[2][i] = (int)read_register(context->fd, 0x27);
    }
    context->calibration_count = CALIBRATION_SAMPLES;
    context->offset_x = 0;
    context->offset_y = 0;
    context->offset_z = 0;
    for (i = 0; i < CALIBRATION_SAMPLES; i++) {
        context->offset_x += context->calibration_samples[0][i];
        context->offset_y += context->calibration_samples[1][i];
        context->offset_z += context->calibration_samples[2][i];
    }
    context->offset_x /= CALIBRATION_SAMPLES;
    context->offset_y /= CALIBRATION_SAMPLES;
    context->offset_z /= CALIBRATION_SAMPLES;
}

