#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

#define I2C_BUS 1
#define GYRO_ADDR 0x68
#define WHO_AM_I 0x0F
#define WHO_AM_I_EXPECTED 0x46
#define CALIBRATION_SAMPLES 100
#define SAMPLE_RATE_HZ 20
#define SAMPLE_PERIOD_MS 50
#define ALERT_THRESHOLD_DPS 50

typedef struct {
    int fd;
    FILE *log_file;
    int calibration_samples[3][CALIBRATION_SAMPLES];
    int calibration_count;
    int offset_x, offset_y, offset_z;
} GyroContext;

void handle_signal(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        if (context.log_file) {
            fprintf(context.log_file, "=== PROGRAM TERMINATED ===\n");
            fclose(context.log_file);
        }
        if (context.fd >= 0) {
            close(context.fd);
        }
        exit(EXIT_SUCCESS);
    }
}

void log_alert(int axis, int value) {
    if (context.log_file) {
        fprintf(context.log_file, "=== ALERT: Axis %c exceeded %d dps ===\n", "XYZ"[axis], value);
    }
    fprintf(stderr, "Warning: Axis %c exceeded %d dps\n", "XYZ"[axis], value);
}

int i2c_init(int bus, int addr) {
    char filename[20];
    snprintf(filename, sizeof(filename), "/dev/i2c-%d", bus);
    int fd = open(filename, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Failed to set I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

int read_register(int fd, int reg) {
    char buf[1];
    if (ioctl(fd, I2C_RDWR, (struct i2c_msg *)buf) < 0) {
        perror("Failed to write register address");
        return -1;
    }

    if (ioctl(fd, I2C_RDWR, (struct i2c_msg *)buf) < 0) {
        perror("Failed to read register value");
        return -1;
    }

    return buf[0];
}

int write_register(int fd, int reg, int value) {
    char buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (ioctl(fd, I2C_RDWR, (struct i2c_msg *)buf) < 0) {
        perror("Failed to write register");
        return -1;
    }
    return 0;
}

void calibrate_gyro(GyroContext *context) {
    int i;
    for (i = 0; i < CALIBRATION_SAMPLES; i++) {
        int x, y, z;
        if (read_register(context->fd, 0x29) < 0) return;
        if (read_register(context->fd, 0x28) < 0) return;
        if (read_register(context->fd, 0x27) < 0) return;
        context->calibration_samples[0][i] = (int)read_register(context->fd, 0x29);
        context->calibration_samples[1][i] = (int)read_register(context->fd, 0x28);
        context->calibration_samples[2][i] = (int)read_register(context->fd, 0x27);
    }
    context->calibration_count = CALIBRATION_SAMPLES;
    context->offset_x = 0;
    context->offset_y = 0;
    context->offset_z = 0;
    for (i = 0; i < CALIBRATION_SAMPLES; i++) {
        context->offset_x += context->calibration_samples[0][i];
        context->offset_y += context->calibration_samples[1][i];
        context->offset_z += context->calibration_samples[2][i];
    }
    context->offset_x /= CALIBRATION_SAMPLES;
    context->offset_y /= CALIBRATION_SAMPLES;
    context->offset_z /= CALIBRATION_SAMPLES;
}

void log_data(GyroContext *context, int x, int y, int z) {
    time_t now;
    struct tm *timeinfo;
    char timestamp[64];
    time(&now);
    timeinfo = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

    if (context->log_file) {
        fprintf(context->log_file, "%s,%d,%d,%d\n", timestamp, x, y, z);
    }
}

