#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <time.h>

#define I2C_BUS 1
#define I2C_ADDR 0x53
#define DEVICE_ID_REGISTER 0x00
#define DEVICE_ID_VALUE 0xAD
#define RANGE_2G 0x01
#define FULL_RES_MODE 0x08
#define POWER_CTL_REGISTER 0x2D
#define MEASURE_MODE 0x08
#define DATA_FORMAT_REGISTER 0x31
#define DATA_REGISTER 0x32
#define LED_PIN 17
#define LOG_FILE "accel_log.txt"
#define SAMPLE_RATE_MS 100
#define G_TO_M_S2 9.80665
#define G_THRESHOLD 2.0

typedef struct {
    int fd;
    struct gpiod_line *led_line;
    FILE *log_file;
    int running;
} app_state;

void handle_signal(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        app_state *state = (app_state *)malloc(sizeof(app_state));
        state->running = 0;
        free(state);
    }
}

void init_i2c(app_state *state) {
    char i2c_bus_path[32];
    snprintf(i2c_bus_path, sizeof(i2c_bus_path), "/dev/i2c-%d", I2C_BUS);

    state->fd = open(i2c_bus_path, O_RDWR);
    if (state->fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    if (ioctl(state->fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(state->fd);
        exit(EXIT_FAILURE);
    }
}

void check_device_id(app_state *state) {
    uint8_t device_id;
    if (read(state->fd, &device_id, 1) != 1) {
        fprintf(stderr, "Failed to read device ID from ADXL345\n");
        close(state->fd);
        exit(EXIT_FAILURE);
    }

    if (device_id != DEVICE_ID_VALUE) {
        fprintf(stderr, "Invalid device ID: 0x%02X (expected 0xAD)\n", device_id);
        close(state->fd);
        exit(EXIT_FAILURE);
    }
}

void configure_adxl345(app_state *state) {
    uint8_t data_format = RANGE_2G | FULL_RES_MODE;
    if (write(state->fd, &data_format, 1) != 1) {
        fprintf(stderr, "Failed to write data format register\n");
        close(state->fd);
        exit(EXIT_FAILURE);
    }

    uint8_t power_ctl = MEASURE_MODE;
    if (write(state->fd, &power_ctl, 1) != 1) {
        fprintf(stderr, "Failed to write power control register\n");
        close(state->fd);
        exit(EXIT_FAILURE);
    }
}

void init_gpio(app_state *state) {
    struct gpiod_chip *chip;
    struct gpiod_line *line;

    chip = gpiod_chip_open("/dev/gpiochip1");
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    line = gpiod_line_request_output(chip, "LED", LED_PIN, GPIOD_LINE_REQUEST_OUTPUT_ACTIVE_LOW);
    if (!line) {
        perror("Failed to request GPIO line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    state->led_line = line;
}

void log_acceleration(app_state *state, int16_t x, int16_t y, int16_t z) {
    double x_g = (double)x / 4096.0 * G_TO_M_S2 / 9.80665;
    double y_g = (double)y / 4096.0 * G_TO_M_S2 / 9.80665;
    double z_g = (double)z / 4096.0 * G_TO_M_S2 / 9.80665;

    time_t now = time(NULL);
    struct tm *tm_now = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_now);

    fprintf(state->log_file, "%s,%0.3f,%0.3f,%0.3f\n", timestamp, x_g, y_g, z_g);
    fflush(state->log_file);
}

void read_acceleration(app_state *state) {
    uint8_t buffer[6];
    if (read(state->fd, buffer, 6) != 6) {
        fprintf(stderr, "I2C read failed\n");
        return;
    }

    int16_t x = (int16_t)(buffer[1] << 8 | buffer[0]);
    int16_t y = (int16_t)(buffer[3] << 8 | buffer[2]);
    int16_t z = (int16_t)(buffer[5] << 8 | buffer[4]);

    log_acceleration(state, x, y, z);

    double abs_x = (double)fabs(x) / 4096.0 * G_TO_M_S2 / 9.80665;
    double abs_y = (double)fabs(y) / 4096.0 * G_TO_M_S2 / 9.80665;
    double abs_z = (double)fabs(z) / 4096.0 * G_TO_M_S2 / 9.80665;

    if (abs_x > G_THRESHOLD || abs_y > G_THRESHOLD || abs_z > G_THRESHOLD) {
        gpiod_line_set_value(state->led_line, 1);
    } else {
        gpiod_line_set_value(state->led_line, 0);
    }
}

void cleanup(app_state *state) {
    if (state->log_file) {
        fclose(state->log_file);
    }

    if (state->led_line) {
        gpiod_line_release(state->led_line);
    }

    if (state->fd >= 0) {
        close(state->fd);
    }
}

int main() {
    app_state state = {0};

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    init_i2c(&state);
    check_device_id(&state);
    configure_adxl345(&state);

    state.log_file = fopen(LOG_FILE, "w");
    if (!state.log_file) {
        perror("Failed to open log file");
        cleanup(&state);
        exit(EXIT_FAILURE);
    }

    init_gpio(&state);

    state.running = 1;
    while (state.running) {
        read_acceleration(&state);
        usleep(SAMPLE_RATE_MS * 1000);
    }

    cleanup(&state);
    return 0;
}

