#define ACCEL_SCALE 2.0 / 327.0
#define MAG_SCALE 1.0 / 1370.0
#define SAMPLE_INTERVAL_MS 100
#define CSV_HEADER "timestamp,heading,ax,ay,az,mx,my,mz\n"

typedef struct {
    int accel_fd;
    int mag_fd;
    int running;
} sensor_data;

void handle_signal(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        printf("Shutting down...\n");
        sensor_data *data = (sensor_data *)malloc(sizeof(sensor_data));
        data->running = 0;
        free(data);
        exit(EXIT_SUCCESS);
    }
}

void init_i2c(int bus, int *fd) {
    char filename[20];
    snprintf(filename, sizeof(filename), "/dev/i2c-%d", bus);
    *fd = open(filename, O_RDWR);
    if (*fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    if (ioctl(*fd, I2C_SLAVE, LSM303DLHC_ACCEL_ADDR) < 0) {
        perror("Failed to set I2C slave address for accelerometer");
        close(*fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(*fd, I2C_SLAVE, LSM303DLHC_MAG_ADDR) < 0) {
        perror("Failed to set I2C slave address for magnetometer");
        close(*fd);
        exit(EXIT_FAILURE);
    }
}

void configure_accel(int fd) {
    uint8_t ctrl1 = 0x18; // ODR = 100 Hz, +/- 2g
    if (write(fd, &ctrl1, 1) != 1) {
        perror("Failed to write to accelerometer control register");
        exit(EXIT_FAILURE);
    }
}

void configure_mag(int fd) {
    uint8_t ctrl1 = 0x00; // Continuous conversion mode, 15 Hz, 1.3Ga
    if (write(fd, &ctrl1, 1) != 1) {
        perror("Failed to write to magnetometer control register");
        exit(EXIT_FAILURE);
    }
}

void read_accel(int fd, int16_t *ax, int16_t *ay, int16_t *az) {
    uint8_t buffer[6];
    if (read(fd, buffer, 6) != 6) {
        perror("Failed to read accelerometer data");
        exit(EXIT_FAILURE);
    }

    *ax = (int16_t)(buffer[1] << 8 | buffer[0]);
    *ay = (int16_t)(buffer[3] << 8 | buffer[2]);
    *az = (int16_t)(buffer[5] << 8 | buffer[4]);
}

void read_mag(int fd, int16_t *mx, int16_t *my, int16_t *mz) {
    uint8_t buffer[6];
    if (read(fd, buffer, 6) != 6) {
        perror("Failed to read magnetometer data");
        exit(EXIT_FAILURE);
    }

    *mx = (int16_t)(buffer[0] << 8 | buffer[1]);
    *my = (int16_t)(buffer[2] << 8 | buffer[3]);
    *mz = (int16_t)(buffer[4] << 8 | buffer[5]);
}

double compute_heading(int16_t mx, int16_t my) {
    double heading_rad = atan2((double)my, (double)mx);
    double heading_deg = heading_rad * (180.0 / M_PI);
    if (heading_deg < 0.0) {
        heading_deg += 360.0;
    }
    return heading_deg;
}

void log_data(FILE *file, time_t timestamp, double heading, int16_t ax, int16_t ay, int16_t az, int16_t mx, int16_t my, int16_t mz) {
    double heading_deg = compute_heading(mx, my);
    double ax_g = ax * ACCEL_SCALE;
    double ay_g = ay * ACCEL_SCALE;
    double az_g = az * ACCEL_SCALE;
    double mx_gauss = mx * MAG_SCALE;
    double my_gauss = my * MAG_SCALE;
    double mz_gauss = mz * MAG_SCALE;

    fprintf(file, "%ld,%f,%f,%f,%f,%f,%f,%f\n",
            (long)timestamp,
            heading_deg,
            ax_g,
            ay_g,
            az_g,
            mx_gauss,
            my_gauss,
            mz_gauss);
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    sensor_data data;
    data.running = 1;

    init_i2c(I2C_BUS, &data.accel_fd);
    init_i2c(I2C_BUS, &data.mag_fd);

    configure_accel(data.accel_fd);
    configure_mag(data.mag_fd);

    FILE *file = fopen("compass_log.txt", "a");
    if (!file) {
        perror("Failed to open log file");
        close(data.accel_fd);
        close(data.mag_fd);
        exit(EXIT_FAILURE);
    }

    if (fseek(file, 0, SEEK_SET) == 0 && ftell(file) == 0) {
        fprintf(file, CSV_HEADER);
    }

    while (data.running) {
        time_t timestamp = time(NULL);

        read_accel(data.accel_fd, &data.ax, &data.ay, &data.az);
        read_mag(data.mag_fd, &data.mx, &data.my, &data.mz);

        log_data(file, timestamp, data.heading, data.ax, data.ay, data.az, data.mx, data.my, data.mz);

        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    fclose(file);
    close(data.accel_fd);
    close(data.mag_fd);

    return 0;
}

