#define FILE_NAME "distance_log.txt"
#define MIN_DISTANCE_MM 100
#define SAMPLE_INTERVAL_MS 100

typedef struct {
    int fd;
    int initialized;
} VL6180X;

// Sensor initialization sequence
int vl6180x_init(VL6180X *sensor) {
    char filename[256];
    snprintf(filename, sizeof(filename), "/dev/i2c-%d", I2C_BUS);
    sensor->fd = open(filename, O_RDWR);
    if (sensor->fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    if (ioctl(sensor->fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(sensor->fd);
        return -1;
    }

    // Reset the sensor
    unsigned char reset_cmd[2] = {0x00, 0x01};
    if (write(sensor->fd, reset_cmd, 2) != 2) {
        perror("Failed to send reset command");
        close(sensor->fd);
        return -1;
    }

    // Wait for reset to complete
    usleep(100000);

    // Initialize sensor (example commands, adjust as needed)
    unsigned char init_cmd[2] = {0x01, 0x00};
    if (write(sensor->fd, init_cmd, 2) != 2) {
        perror("Failed to send initialization command");
        close(sensor->fd);
        return -1;
    }

    sensor->initialized = 1;
    return 0;
}

// Read distance from sensor
int vl6180x_read_distance(VL6180X *sensor, int *distance_mm) {
    if (!sensor->initialized) {
        return -1;
    }

    unsigned char cmd[2] = {0x02, 0x00}; // Example command to read distance
    if (write(sensor->fd, cmd, 2) != 2) {
        perror("Failed to send read command");
        return -1;
    }

    unsigned char response[8];
    if (read(sensor->fd, response, 8) != 8) {
        perror("Failed to read response");
        return -1;
    }

    // Parse response (example parsing, adjust based on sensor datasheet)
    *distance_mm = (response[1] << 8) | response[0];
    return 0;
}

// SIGINT handler
void handle_sigint(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    // Add cleanup code here if needed
    exit(0);
}

int main() {
    VL6180X sensor;
    int distance_mm = 0;
    FILE *file = NULL;
    struct timespec ts;
    int ret;

    // Initialize signal handler
    signal(SIGINT, handle_sigint);

    // Open log file
    file = fopen(FILE_NAME, "a");
    if (!file) {
        perror("Failed to open log file");
        return 1;
    }

    // Initialize sensor
    if (vl6180x_init(&sensor) < 0) {
        fprintf(stderr, "Failed to initialize sensor, exiting.\n");
        fclose(file);
        return 1;
    }

    // Main loop
    while (1) {
        // Read distance
        ret = vl6180x_read_distance(&sensor, &distance_mm);
        if (ret < 0) {
            fprintf(stderr, "Sensor read failed, attempting re-initialization.\n");
            if (vl6180x_init(&sensor) < 0) {
                fprintf(stderr, "Failed to re-initialize sensor, exiting.\n");
                break;
            }
            continue;
        }

        // Get current time
        clock_gettime(CLOCK_REALTIME, &ts);
        time_t now = ts.tv_sec;
        char timestamp[30];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

        // Log distance
        fprintf(file, "%s, %d mm\n", timestamp, distance_mm);
        fflush(file);

        // Log door state
        if (distance_mm < MIN_DISTANCE_MM) {
            fprintf(file, "DOOR_OPEN\n");
        } else {
            fprintf(file, "DOOR_CLOSED\n");
        }
        fflush(file);

        // Sleep for 100 ms
        usleep(100000);
    }

    // Cleanup
    if (file) {
        fclose(file);
    }
    if (sensor.fd >= 0) {
        close(sensor.fd);
    }

    return 0;
}

