int open_i2c(int bus) {
    char filename[20];
    snprintf(filename, sizeof(filename), "/dev/i2c-%d", bus);
    int fd = open(filename, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_TEN, 0) < 0) {
        perror("Failed to set I2C to 10-bit addressing");
        close(fd);
        return -1;
    }

    return fd;
}

int read_i2c(int fd, int addr, unsigned char reg, int *data) {
    unsigned char buf[2];
    buf[0] = reg;
    if (ioctl(fd, I2C_RDWR, &buf) < 0) {
        perror("I2C read failed");
        return -1;
    }

    *data = (int)(buf[1] << 8 | buf[0]);
    return 0;
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int fd1 = open_i2c(I2C_BUS);
    int fd2 = open_i2c(I2C_BUS);

    if (fd1 < 0 || fd2 < 0) {
        fprintf(stderr, "Failed to open I2C bus.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    FILE *csv_file = fopen(CSV_FILE, "a");
    if (!csv_file) {
        perror("Failed to open CSV file");
        cleanup();
        return EXIT_FAILURE;
    }

    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);

    while (running) {
        int sensor1_val = 0;
        int sensor2_val = 0;

        if (read_i2c(fd1, I2C_ADDR1, I2C_REGISTER, &sensor1_val) < 0) {
            fprintf(stderr, "Sensor 1 read failed, skipping sample.\n");
            usleep(10000);
            continue;
        }

        if (read_i2c(fd2, I2C_ADDR2, I2C_REGISTER, &sensor2_val) < 0) {
            fprintf(stderr, "Sensor 2 read failed, skipping sample.\n");
            usleep(10000);
            continue;
        }

        clock_gettime(CLOCK_REALTIME, &ts);

        long long tdoa = (long long)(ts.tv_nsec - ts.tv_nsec); // Placeholder for actual TDOA calculation
        // In a real implementation, you would calculate TDOA based on timestamps of sensor1 and sensor2

        fprintf(csv_file, "%lld,%lld,%d,%d,%lld\n", ts.tv_sec, ts.tv_nsec, sensor1_val, sensor2_val, tdoa);
        fflush(csv_file);

        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    fclose(csv_file);
    close_i2c(fd1);
    close_i2c(fd2);
    cleanup();

    return EXIT_SUCCESS;
}
