#define SPI_DEVICE "/dev/spidev0.0"
#define CS_PIN 8
#define SPI_MODE SPI_MODE_3
#define SPI_MAX_SPEED_HZ 1000000
#define REGISTER_ADDR 0x80
#define REGISTER_SIZE 2
#define LOG_INTERVAL_MS 100
#define MAX_RETRIES 5

typedef struct {
    int spi_fd;
    struct gpiod_line *cs_line;
    int running;
} imu_context;

void handle_signal(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        printf("\nReceived signal, shutting down...\n");
        ((imu_context *)getenv("IMU_CONTEXT"))->running = 0;
    }
}

void spi_init(imu_context *ctx) {
    ctx->spi_fd = open(SPI_DEVICE, O_RDWR | O_NOCTTY | O_SYNC);
    if (ctx->spi_fd < 0) {
        perror("Failed to open SPI device");
        exit(EXIT_FAILURE);
    }

    struct spi_ioc_transfer spi;
    memset(&spi, 0, sizeof(spi));
    spi.speed_hz = SPI_MAX_SPEED_HZ;
    spi.mode = SPI_MODE;
    spi.bits_per_word = 16;

    if (ioctl(ctx->spi_fd, SPI_IOC_MESSAGE(1), &spi) < 0) {
        perror("SPI ioctl failed");
        close(ctx->spi_fd);
        exit(EXIT_FAILURE);
    }

    ctx->cs_line = gpiod_line_get("gpiochip0", CS_PIN);
    if (!ctx->cs_line) {
        perror("Failed to get CS GPIO line");
        close(ctx->spi_fd);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(ctx->cs_line, "imu_cs", 1) < 0) {
        perror("Failed to request CS GPIO line");
        gpiod_line_put(ctx->cs_line);
        close(ctx->spi_fd);
        exit(EXIT_FAILURE);
    }

    gpiod_line_set_value(ctx->cs_line, 1);
}

void spi_transfer(imu_context *ctx, uint16_t reg_addr, uint16_t *data) {
    uint16_t tx_data = reg_addr;
    struct spi_ioc_transfer spi;
    memset(&spi, 0, sizeof(spi));
    spi.speed_hz = SPI_MAX_SPEED_HZ;
    spi.mode = SPI_MODE;
    spi.bits_per_word = 16;
    spi.tx_buf = (unsigned long)&tx_data;
    spi.len = sizeof(tx_data);

    if (ioctl(ctx->spi_fd, SPI_IOC_MESSAGE(1), &spi) < 0) {
        perror("SPI transfer failed");
        return;
    }

    gpiod_line_set_value(ctx->cs_line, 0);

    spi.tx_buf = 0;
    spi.rx_buf = (unsigned long)data;
    spi.len = sizeof(*data);

    if (ioctl(ctx->spi_fd, SPI_IOC_MESSAGE(1), &spi) < 0) {
        perror("SPI receive failed");
        gpiod_line_set_value(ctx->cs_line, 1);
        return;
    }

    gpiod_line_set_value(ctx->cs_line, 1);
}

void read_imu_data(imu_context *ctx, int16_t *gyro, int16_t *accel) {
    uint16_t gyro_data[3];
    uint16_t accel_data[3];

    for (int i = 0; i < 3; i++) {
        spi_transfer(ctx, 0x80 + 0x20 + i * 2, &gyro_data[i]);
        spi_transfer(ctx, 0x80 + 0x21 + i * 2, &accel_data[i]);
    }

    for (int i = 0; i < 3; i++) {
        gyro[i] = (int16_t)gyro_data[i];
        accel[i] = (int16_t)accel_data[i];
    }
}

void process_data(int16_t *gyro, int16_t *accel) {
    printf("Gyro (dps): %5d %5d %5d\n", gyro[0] * 0.02, gyro[1] * 0.02, gyro[2] * 0.02);
    printf("Accel (g): %6.2f %6.2f %6.2f\n", accel[0] * 0.00025, accel[1] * 0.00025, accel[2] * 0.00025);
}

void cleanup(imu_context *ctx) {
    if (ctx->cs_line) {
        gpiod_line_put(ctx->cs_line);
    }
    if (ctx->spi_fd >= 0) {
        close(ctx->spi_fd);
    }
}

int main() {
    imu_context ctx = {0};
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if (gpiod_init() < 0) {
        perror("Failed to initialize gpiod");
        exit(EXIT_FAILURE);
    }

    spi_init(&ctx);
    ctx.running = 1;

    while (ctx.running) {
        read_imu_data(&ctx, (int16_t *)malloc(3 * sizeof(int16_t)), (int16_t *)malloc(3 * sizeof(int16_t)));
        process_data((int16_t *)malloc(3 * sizeof(int16_t)), (int16_t *)malloc(3 * sizeof(int16_t)));
        usleep(100000); // 100 ms
    }

    cleanup(&ctx);
    gpiod_exit();
    return 0;
}

