#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>
#include <poll.h>

#define I2C_BUS 1
#define I2C_ADDR 0x68
#define MPU6886_ACCEL_XOUT_H 0x3B
#define MPU6886_GYRO_XOUT_H 0x43
#define MPU6886_ACCEL_XOUT_L 0x3C
#define MPU6886_GYRO_XOUT_L 0x44
#define MPU6886_ACCEL_XOUT_H_SIZE 2
#define MPU6886_GYRO_XOUT_H_SIZE 2
#define MAX_RETRIES 3
#define POLL_TIMEOUT_MS 100
#define READ_INTERVAL_MS 50

typedef struct {
    int fd;
    int poll_fd;
    int running;
} i2c_context;

void handle_signal(int sig) {
    if (sig == SIGINT) {
        printf("\nReceived SIGINT, shutting down...\n");
    }
    exit(EXIT_SUCCESS);
}

void close_i2c(i2c_context *ctx) {
    if (ctx->fd >= 0) {
        close(ctx->fd);
        ctx->fd = -1;
    }
    if (ctx->poll_fd >= 0) {
        close(ctx->poll_fd);
        ctx->poll_fd = -1;
    }
    ctx->running = 0;
}

int open_i2c() {
    char filename[256];
    snprintf(filename, sizeof(filename), "/dev/i2c-%d", I2C_BUS);
    int fd = open(filename, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(fd);
        return -1;
    }

    struct pollfd poll_fd;
    poll_fd.fd = fd;
    poll_fd.events = POLLIN;

    return (int) (struct i2c_context){.fd = fd, .poll_fd = poll_fd.fd, .running = 1};
}

int read_i2c(int fd, unsigned char reg, unsigned char *buf, size_t len) {
    if (ioctl(fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        return -1;
    }

    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }

    if (read(fd, buf, len) != len) {
        perror("Failed to read from I2C device");
        return -1;
    }

    return 0;
}

void read_and_print_values(int fd) {
    unsigned char accel_data[MPU6886_ACCEL_XOUT_H_SIZE * 2];
    unsigned char gyro_data[MPU6886_GYRO_XOUT_H_SIZE * 2];

    for (int retry = 0; retry < MAX_RETRIES; retry++) {
        if (read_i2c(fd, MPU6886_ACCEL_XOUT_H, accel_data, MPU6886_ACCEL_XOUT_H_SIZE * 2) == 0 &&
            read_i2c(fd, MPU6886_GYRO_XOUT_H, gyro_data, MPU6886_GYRO_XOUT_H_SIZE * 2) == 0) {
            int16_t ax = (accel_data[1] << 8) | accel_data[0];
            int16_t ay = (accel_data[3] << 8) | accel_data[2];
            int16_t az = (accel_data[5] << 8) | accel_data[4];
            int16_t gx = (gyro_data[1] << 8) | gyro_data[0];
            int16_t gy = (gyro_data[3] << 8) | gyro_data[2];
            int16_t gz = (gyro_data[5] << 8) | gyro_data[4];

            printf("Accel: X=%d Y=%d Z=%d  Gyro: X=%d Y=%d Z=%d\n", ax, ay, az, gx, gy, gz);
            return;
        }

        usleep(10000); // 10ms delay between retries
    }

    fprintf(stderr, "Failed to read sensor data after %d retries\n", MAX_RETRIES);
}

int main() {
    i2c_context ctx = open_i2c();
    if (ctx.fd < 0) {
        fprintf(stderr, "Failed to open I2C device\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_signal);

    while (ctx.running) {
        if (poll(&ctx.poll_fd, 1, POLL_TIMEOUT_MS) < 0) {
            perror("Poll failed");
            close_i2c(&ctx);
            return EXIT_FAILURE;
        }

        read_and_print_values(ctx.fd);
        usleep(READ_INTERVAL_MS * 1000);
    }

    close_i2c(&ctx);
    return EXIT_SUCCESS;
}

