#define LED_PIN 17
#define THRESHOLD_G 2.5
#define LED_DURATION_MS 500
#define LOG_FILE "impact_log.txt"

typedef struct {
    int i2c_fd;
    struct gpiod_line *led_line;
    FILE *log_file;
    int running;
} app_state;

void handle_signal(int sig) {
    app_state *state = (app_state *)malloc(sizeof(app_state));
    state->running = 0;
    free(state);
}

void close_resources(app_state *state) {
    if (state->i2c_fd >= 0) {
        close(state->i2c_fd);
    }
    if (state->led_line) {
        gpiod_line_release(state->led_line);
    }
    if (state->log_file) {
        fclose(state->log_file);
    }
    printf("Resources released.\n");
}

void log_event(double magnitude, int16_t x, int16_t y, int16_t z) {
    time_t now = time(NULL);
    struct tm *tm_now = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_now);

    fprintf(state->log_file, "%s, %.2f, %d, %d, %d\n", timestamp, magnitude, x, y, z);
    fflush(state->log_file);
}

void read_acceleration(int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buffer[6];
    int ret;

    ret = ioctl(state->i2c_fd, I2C_RDWR, (struct i2c_rdwr_ioctl_data *)&(struct i2c_msg[0]));
    if (ret < 0) {
        perror("I2C read failed");
        exit(EXIT_FAILURE);
    }

    ret = ioctl(state->i2c_fd, I2C_RDWR, (struct i2c_rdwr_ioctl_data *)&(struct i2c_msg[1]));
    if (ret < 0) {
        perror("I2C read failed");
        exit(EXIT_FAILURE);
    }

    *x = (int16_t)(buffer[0] << 8 | buffer[1]);
    *y = (int16_t)(buffer[2] << 8 | buffer[3]);
    *z = (int16_t)(buffer[4] << 8 | buffer[5]);
}

void setup_i2c() {
    char i2c_bus_path[32];
    snprintf(i2c_bus_path, sizeof(i2c_bus_path), "/dev/i2c-%d", I2C_BUS);

    state->i2c_fd = open(i2c_bus_path, O_RDWR);
    if (state->i2c_fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    if (ioctl(state->i2c_fd, I2C_TEN, 0) < 0) {
        perror("I2C 10-bit addressing not supported");
        close(state->i2c_fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(state->i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(state->i2c_fd);
        exit(EXIT_FAILURE);
