    uint8_t data = ADXL345_RANGE_2G | ADXL345_FULL_RES;
    if (write(state->i2c_fd, &data, 1) != 1) {
        perror("Failed to write data format register");
        close(state->i2c_fd);
        exit(EXIT_FAILURE);
    }

    data = ADXL345_MEASURE;
    if (write(state->i2c_fd, &data, 1) != 1) {
        perror("Failed to write power control register");
        close(state->i2c_fd);
        exit(EXIT_FAILURE);
    }

    uint8_t id;
    if (read(state->i2c_fd, &id, 1) != 1) {
        perror("Failed to read device ID");
        close(state->i2c_fd);
        exit(EXIT_FAILURE);
    }

    if (id != ADXL345_DEVICE_ID) {
        fprintf(stderr, "Invalid device ID: 0x%02X (expected 0x%02X)\n", id, ADXL345_DEVICE_ID);
        close(state->i2c_fd);
        exit(EXIT_FAILURE);
    }
}

