void handle_sigint(int sig) {
    if (sig == SIGINT) {
        printf("Received SIGINT, shutting down...\n");
        ((imu_context *)gpiod_context)->running = 0;
    }
}

void i2c_read_bytes(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    struct i2c_msg msgs[2];
    struct i2c_ioctl_data ioctl_data;
    int ret;

    msgs[0].flags = 0;
    msgs[0].len = 1;
    msgs[0].addr = I2C_ADDR_ICM20602;
    msgs[0].buf = &reg;

    msgs[1].flags = I2C_M_RD;
    msgs[1].len = len;
    msgs[1].addr = I2C_ADDR_ICM20602;
    msgs[1].buf = buf;

    ioctl_data.msgs = msgs;
    ioctl_data.nmsgs = 2;
    ioctl_data.len = len;

    ret = ioctl(fd, I2C_RDWR, &ioctl_data);
    if (ret < 0) {
        perror("i2c_read_bytes");
        exit(EXIT_FAILURE);
    }
}

