#include <time.h>

#define I2C_BUS 1
#define I2C_ADDR 0x1D
#define WHO_AM_I_REGISTER 0x00
#define WHO_AM_I_VALUE 0x53
#define LED_PIN 17
#define POLL_INTERVAL_MS 100
#define LED_ON_DURATION_MS 500
#define G_THRESHOLD 2048  // 2g in 1024 counts per g

typedef struct {
    int fd;
    struct gpiod_line *led_line;
    FILE *log_file;
    int running;
} app_state;

void handle_signal(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        app_state *state = (app_state *)malloc(sizeof(app_state));
        if (state) {
            state->running = 0;
        }
    }
}

void init_i2c(app_state *state) {
    char i2c_bus_path[32];
    snprintf(i2c_bus_path, sizeof(i2c_bus_path), "/dev/i2c-%d", I2C_BUS);

    state->fd = open(i2c_bus_path, O_RDWR);
    if (state->fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    if (ioctl(state->fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(state->fd);
        exit(EXIT_FAILURE);
    }

    // Verify sensor identity
    unsigned char who_am_i[1];
    if (read(state->fd, who_am_i, 1) < 0) {
        perror("Failed to read WHO_AM_I register");
        close(state->fd);
        exit(EXIT_FAILURE);
    }

    if (who_am_i[0] != WHO_AM_I_VALUE) {
        fprintf(stderr, "Sensor ID mismatch: expected 0x%02X, got 0x%02X\n", WHO_AM_I_VALUE, who_am_i[0]);
        close(state->fd);
        exit(EXIT_FAILURE);
    }
}

void init_gpio(app_state *state) {
    const char *chip_name = "gpiochip0";
    struct gpiod_chip *chip;
    int ret;

    chip = gpiod_chip_open_by_name(chip_name);
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    state->led_line = gpiod_line_get(chip, LED_PIN);
    if (!state->led_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(state->led_line, "impact_led", 0) < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_line_release(state->led_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }
}

void init_log(app_state *state) {
    state->log_file = fopen("impact_log.txt", "a");
    if (!state->log_file) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }
}

void close_i2c(app_state *state) {
    if (state->fd >= 0) {
        close(state->fd);
    }
}

void close_gpio(app_state *state) {
    if (state->led_line) {
        gpiod_line_release(state->led_line);
    }
}

void close_log(app_state *state) {
    if (state->log_file) {
        fclose(state->log_file);
    }
}

void read_acceleration(app_state *state) {
    unsigned char reg[1];
    reg[0] = 0x01; // X-axis data
    if (write(state->fd, reg, 1) < 0) {
        perror("Failed to write to I2C register");
        return;
    }

    unsigned char data[6];
    if (read(state->fd, data, 6) < 0) {
        perror("Failed to read I2C data");
        return;
    }

    int x = (data[0] << 8) | data[1];
    int y = (data[2] << 8) | data[3];
    int z = (data[4] << 8) | data[5];

    // Convert to g units
    int x_g = x;
    int y_g = y;
    int z_g = z;

    // Calculate magnitude
    double magnitude = sqrt(x_g * x_g + y_g * y_g + z_g * z_g);

    if (magnitude > G_THRESHOLD) {
        // Turn on LED
        gpiod_line_set_value(state->led_line, 1);
        time_t now = time(NULL);
        char timestamp[26];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
        fprintf(state->log_file, "%s, X: %d, Y: %d, Z: %d, Magnitude: %.2f g\n", timestamp, x_g, y_g, z_g, magnitude);
        fflush(state->log_file);

        usleep(LED_ON_DURATION_MS * 1000);
        gpiod_line_set_value(state->led_line, 0);
    }
}

int main() {
    app_state state = {0};

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    init_i2c(&state);
    init_gpio(&state);
    init_log(&state);

    state.running = 1;

    while (state.running) {
        read_acceleration(&state);
        usleep(POLL_INTERVAL_MS * 1000);
    }

    close_i2c(&state);
    close_gpio(&state);
    close_log(&state);

    return 0;
}

