#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

#define I2C_BUS "/dev/i2c-1"
#define TMAG5273_ADDR 0x3C
#define TMAG5273_REGISTER_XOUT_L 0x02
#define TMAG5273_REGISTER_XOUT_H 0x03
#define TMAG5273_REGISTER_YOUT_L 0x04
#define TMAG5273_REGISTER_YOUT_H 0x05
#define TMAG5273_REGISTER_ZOUT_L 0x06
#define TMAG5273_REGISTER_ZOUT_H 0x07
#define TMAG5273_REGISTER_STATUS 0x00
#define TMAG5273_STATUS_READY 0x80

typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} magnetic_field_t;

volatile int running = 1;

void signal_handler(int signum) {
    running = 0;
}

int open_i2c_device(const char *device_path) {
    int file_desc = open(device_path, O_RDWR);
    if (file_desc < 0) {
        fprintf(stderr, "Failed to open I2C device %s: %s\n", device_path, strerror(errno));
        return -1;
    }
    return file_desc;
}

int i2c_write_register(int file_desc, uint8_t reg_addr, uint8_t value) {
    uint8_t buffer[1];
    buffer[0] = value;
    if (ioctl(file_desc, I2C_SLAVE, TMAG5273_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address: %s\n", strerror(errno));
        return -1;
    }
    if (write(file_desc, buffer, 1) != 1) {
        fprintf(stderr, "Failed to write to I2C register 0x%02X: %s\n", reg_addr, strerror(errno));
        return -1;
    }
    return 0;
}

int i2c_read_register(int file_desc, uint8_t reg_addr, uint8_t *value) {
    if (ioctl(file_desc, I2C_SLAVE, TMAG5273_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address: %s\n", strerror(errno));
        return -1;
    }
    if (write(file_desc, &reg_addr, 1) != 1) {
        fprintf(stderr, "Failed to write I2C register address 0x%02X: %s\n", reg_addr, strerror(errno));
        return -1;
    }
    if (read(file_desc, value, 1) != 1) {
        fprintf(stderr, "Failed to read from I2C register 0x%02X: %s\n", reg_addr, strerror(errno));
        return -1;
    }
    return 0;
}

int read_magnetic_field(int file_desc, magnetic_field_t *field) {
    uint8_t status;
    if (i2c_read_register(file_desc, TMAG5273_REGISTER_STATUS, &status) < 0) {
        return -1;
    }
    if ((status & TMAG5273_STATUS_READY) == 0) {
        fprintf(stderr, "TMAG5273 not ready, status: 0x%02X\n", status);
        return -1;
    }

    uint8_t x_l, x_h, y_l, y_h, z_l, z_h;
    if (i2c_read_register(file_desc, TMAG5273_REGISTER_XOUT_L, &x_l) < 0 ||
        i2c_read_register(file_desc, TMAG5273_REGISTER_XOUT_H, &x_h) < 0 ||
        i2c_read_register(file_desc, TMAG5273_REGISTER_YOUT_L, &y_l) < 0 ||
        i2c_read_register(file_desc, TMAG5273_REGISTER_YOUT_H, &y_h) < 0 ||
        i2c_read_register(file_desc, TMAG5273_REGISTER_ZOUT_L, &z_l) < 0 ||
        i2c_read_register(file_desc, TMAG5273_REGISTER_ZOUT_H, &z_h) < 0) {
        return -1;
    }

    field->x = (x_h << 8) | x_l;
    field->y = (y_h << 8) | y_l;
    field->z = (z_h << 8) | z_l;
    return 0;
}

FILE *open_csv_file(const char *filename) {
    FILE *file = fopen(filename, "a");
    if (file == NULL) {
        fprintf(stderr, "Failed to open CSV file %s: %s\n", filename, strerror(errno));
        return NULL;
    }
    return file;
}

void write_csv_header(FILE *file) {
    fprintf(file, "timestamp,x,y,z\n");
    if (ferror(file)) {
        fprintf(stderr, "Failed to write CSV header: %s\n", strerror(errno));
    }
}

void write_csv_data(FILE *file, const char *timestamp, int16_t x, int16_t y, int16_t z) {
    fprintf(file, "%s,%d,%d,%d\n", timestamp, x, y, z);
    if (ferror(file)) {
        fprintf(stderr, "Failed to write CSV data: %s\n", strerror(errno));
    }
}

int main() {
    int i2c_fd = -1;
    FILE *csv_file = NULL;
    magnetic_field_t field;
    struct timespec ts;
    char timestamp[30];

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    i2c_fd = open_i2c_device(I2C_BUS);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C device. Exiting.\n");
        return 1;
    }

    csv_file = open_csv_file("magnetic_field_log.csv");
    if (csv_file == NULL) {
        fprintf(stderr, "Failed to open CSV file. Exiting.\n");
        close(i2c_fd);
        return 1;
    }

    if (csv_file != NULL && fseek(csv_file, 0, SEEK_SET) == 0) {
        char buffer[1024];
        if (fgets(buffer, sizeof(buffer), csv_file) == NULL || strncmp(buffer, "timestamp,x,y,z\n", 14) != 0) {
            write_csv_header(csv_file);
        }
    }

    while (running) {
        clock_gettime(CLOCK_REALTIME, &ts);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));

        if (read_magnetic_field(i2c_fd, &field) < 0) {
            fprintf(stderr, "I2C read failed. Continuing...\n");
            continue;
        }

        write_csv_data(csv_file, timestamp, field.x, field.y, field.z);

        usleep(1000000); // 1 second
    }

    if (csv_file != NULL) {
        fclose(csv_file);
    }

    if (i2c_fd >= 0) {
        close(i2c_fd);
    }

    return 0;
}

