#define GYRO_RANGE 250
#define FALL_THRESHOLD 0.2
#define IMPACT_THRESHOLD 2.5
#define DETECTION_WINDOW 1.0

typedef enum {
    IDLE,
    FREEFALL,
    IMPACT
} State;

typedef struct {
    int fd;
    State state;
    double last_impact_time;
    FILE *log_file;
} IMUContext;

void handle_signal(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        printf("Shutting down...\n");
        if (context.log_file) {
            fclose(context.log_file);
        }
        if (context.fd >= 0) {
            close(context.fd);
        }
        exit(EXIT_SUCCESS);
    }
}

void i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buffer[2];
    buffer[0] = reg;
    buffer[1] = value;
    if (write(fd, buffer, 2) != 2) {
        perror("I2C write error");
        exit(EXIT_FAILURE);
    }
}

uint8_t i2c_read_byte(int fd, uint8_t reg) {
    uint8_t buffer[1];
    buffer[0] = reg;
    if (write(fd, buffer, 1) != 1) {
        perror("I2C write error");
        exit(EXIT_FAILURE);
    }
    if (read(fd, buffer, 1) != 1) {
        perror("I2C read error");
        exit(EXIT_FAILURE);
    }
    return buffer[0];
}

