    // Reset the sensor
    i2c_write_byte(fd, 0x1F, 0x01);
    usleep(100000);

    // Set accelerometer range to ±2g
    uint8_t ctrl1 = i2c_read_byte(fd, 0x10);
    ctrl1 &= ~0x30;
    ctrl1 |= 0x00;
    i2c_write_byte(fd, 0x10, ctrl1);

    // Set gyroscope range to ±250 dps
    uint8_t ctrl2 = i2c_read_byte(fd, 0x11);
    ctrl2 &= ~0x30;
    ctrl2 |= 0x08;
    i2c_write_byte(fd, 0x11, ctrl2);

