        uint8_t az_h = i2c_read_byte(fd, ACCEL_Z_H);
        int16_t az = (int16_t)(az_h << 8 | az_l);

        uint8_t gx_l = i2c_read_byte(fd, GYRO_X_L);
        uint8_t gx_h = i2c_read_byte(fd, GYRO_X_H);
        int16_t gx = (int16_t)(gx_h << 8 | gx_l);

        uint8_t gy_l = i2c_read_byte(fd, GYRO_Y_L);
        uint8_t gy_h = i2c_read_byte(fd, GYRO_Y_H);
        int16_t gy = (int16_t)(gy_h << 8 | gy_l);

        uint8_t gz_l = i2c_read_byte(fd, GYRO_Z_L);
        uint8_t gz_h = i2c_read_byte(fd, GYRO_Z_H);
        int16_t gz = (int16_t)(gz_h << 8 | gz_l);

        double ax_g = (double)ax / 32768.0 * ACCEL_RANGE * g;
        double ay_g = (double)ay / 32768.0 * ACCEL_RANGE * g;
        double az_g = (double)az / 32768.0 * ACCEL_RANGE * g;

