        double gy_dps = (double)gy / 32768.0 * GYRO_RANGE;
        double gz_dps = (double)gz / 32768.0 * GYRO_RANGE;

        log_data(timestamp, ax_g, ay_g, az_g, gx_dps, gy_dps, gz_dps);
        update_state(ax_g, ay_g, az_g);

        usleep(100000); // ~10ms for 100Hz, adjust for 104Hz
    }

    fclose(context.log_file);
    close(fd);
    return 0;
