#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define CE_PIN 8
#define SPI_MODE SPI_MODE_3
#define SPI_SPEED 1000000
#define WHO_AM_I_REGISTER 0x00
#define ANGULAR_RATE_REGISTER 0x10
#define REGISTER_SIZE 2
#define LOG_FILE "gyro_log.csv"
#define LOG_HEADER "Timestamp,RawValue,AngularRate\n"

typedef struct {
    int spi_fd;
    struct gpiod_line *ce_line;
    FILE *log_file;
    int running;
} app_state;

void handle_sigint(int sig) {
    app_state *state = (app_state *)malloc(sizeof(app_state));
    if (state) {
        state->running = 0;
        if (state->log_file) {
            fclose(state->log_file);
        }
        if (state->spi_fd >= 0) {
            close(state->spi_fd);
        }
        if (state->ce_line) {
            gpiod_line_release(state->ce_line);
        }
        free(state);
    }
    exit(EXIT_SUCCESS);
}

int init_spi(app_state *state) {
    state->spi_fd = open(SPI_DEVICE, O_RDWR | O_NOCTTY | O_SYNC);
    if (state->spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device %s\n", SPI_DEVICE);
        return -1;
    }

    struct spi_ioc_transfer spi;
    memset(&spi, 0, sizeof(spi));
    spi.speed_hz = SPI_SPEED;
    spi.mode = SPI_MODE;
    spi.bits_per_word = 16;

    if (ioctl(state->spi_fd, SPI_IOC_MESSAGE(1), &spi) < 0) {
        fprintf(stderr, "Failed to set SPI mode and speed\n");
        close(state->spi_fd);
        return -1;
    }

    return 0;
}

int init_ce_gpio(app_state *state) {
    struct gpiod_chip *chip;
    chip = gpiod_chip_open(GPIOC);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return -1;
    }

    state->ce_line = gpiod_line_get(chip, "gpio8", GPIOD_LINE_DIRECTION_OUTPUT);
    if (!state->ce_line) {
        fprintf(stderr, "Failed to get CE GPIO line\n");
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_set_value(state->ce_line, 1) < 0) {
        fprintf(stderr, "Failed to set CE GPIO high\n");
        gpiod_line_release(state->ce_line);
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

int read_register(app_state *state, uint8_t reg, uint16_t *value) {
    uint8_t tx[2] = {reg | 0x80, 0x00};
    uint8_t rx[2] = {0};

    if (ioctl(state->spi_fd, SPI_IOC_MESSAGE(1), &tx, rx, 2, 2) < 0) {
        fprintf(stderr, "SPI read failed\n");
        return -1;
    }

    *value = (rx[0] << 8) | rx[1];
    return 0;
}

int verify_who_am_i(app_state *state) {
    uint16_t who_am_i;
    if (read_register(state, WHO_AM_I_REGISTER, &who_am_i) < 0) {
        fprintf(stderr, "Failed to read WHO_AM_I register\n");
        return -1;
    }

    if (who_am_i != 0x49) {
        fprintf(stderr, "WHO_AM_I register value is 0x%04X (expected 0x49)\n", who_am_i);
        return -1;
    }

    return 0;
}

void log_data(app_state *state, int16_t raw_value) {
    time_t now;
    struct tm *timeinfo;
    char timestamp[20];

    time(&now);
    timeinfo = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(state->log_file, "%s,%d,%.6f\n", timestamp, raw_value, (double)raw_value * 0.0305);
    fflush(state->log_file);
}

int main() {
    app_state state = {0};

    signal(SIGINT, handle_sigint);

    if (init_spi(&state) < 0) {
        fprintf(stderr, "SPI initialization failed\n");
        return EXIT_FAILURE;
    }

    if (init_ce_gpio(&state) < 0) {
        fprintf(stderr, "CE GPIO initialization failed\n");
        close(state.spi_fd);
        return EXIT_FAILURE;
    }

    state.log_file = fopen(LOG_FILE, "a");
    if (!state.log_file) {
        fprintf(stderr, "Failed to open log file %s\n", LOG_FILE);
        gpiod_line_release(state.ce_line);
        close(state.spi_fd);
        return EXIT_FAILURE;
    }

    if (fputs(LOG_HEADER, state.log_file) < 0) {
        fprintf(stderr, "Failed to write header to log file\n");
        fclose(state.log_file);
        gpiod_line_release(state.ce_line);
        close(state.spi_fd);
        return EXIT_FAILURE;
    }

    if (verify_who_am_i(&state) < 0) {
        fprintf(stderr, "WHO_AM_I verification failed\n");
        fclose(state.log_file);
        gpiod_line_release(state.ce_line);
        close(state.spi_fd);
        return EXIT_FAILURE;
    }

    state.running = 1;
    while (state.running) {
        uint16_t raw_value;
        if (read_register(&state, ANGULAR_RATE_REGISTER, &raw_value) < 0) {
            fprintf(stderr, "Failed to read angular rate register\n");
            break;
        }

        log_data(&state, raw_value);
        usleep(10000); // 10 ms interval
    }

    fclose(state.log_file);
    gpiod_line_release(state.ce_line);
    close(state.spi_fd);

    return EXIT_SUCCESS;
}

