#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_PIN 17
#define LOG_FILE "flame_events.log"
#define POLL_INTERVAL_MS 500
#define FLAME_DETECTED_MSG "FLAME DETECTED!"
#define ERROR_MSG "Sensor read error"

volatile sig_atomic_t exit_flag = 0;

void handle_sigint(int sig) {
    exit_flag = 1;
}

int main() {
    struct gpiod_line *line;
    FILE *log_file = NULL;
    int ret;

    // Initialize signal handler
    signal(SIGINT, handle_sigint);

    // Open log file in append mode
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return 1;
    }

    // Initialize GPIO line
    line = gpiod_line_get("gpiochip0", GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line: %s\n", strerror(errno));
        fclose(log_file);
        return 1;
    }

    // Set line as input with pull-up
    ret = gpiod_line_request_input(line, "flame_sensor", GPIOD_LINE_REQUEST_FLAG_ACTIVE_LOW);
    if (ret < 0) {
        fprintf(stderr, "Failed to request GPIO line: %s\n", strerror(errno));
        gpiod_line_put(line);
        fclose(log_file);
        return 1;
    }

    // Main loop
    while (!exit_flag) {
        int value;
        struct timespec ts = {0, 500000000}; // 500 ms

        // Read GPIO value
        ret = gpiod_line_get_value(line, &value);
        if (ret < 0) {
            fprintf(log_file, "%s\n", ERROR_MSG);
            fflush(log_file);
            nanosleep(&ts, NULL);
            continue;
        }

        // Format timestamp
        time_t now;
        struct tm *tm_info;
        time(&now);
        tm_info = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

        // Write log entry
        if (value == 0) {
            fprintf(log_file, "%s – Flame detected: YES\n", timestamp);
            fflush(log_file);
            printf("%s\n", FLAME_DETECTED_MSG);
        } else {
            fprintf(log_file, "%s – Flame detected: NO\n", timestamp);
            fflush(log_file);
        }

        nanosleep(&ts, NULL);
    }

    // Cleanup
    gpiod_line_put(line);
    fclose(log_file);

    return 0;
}

