#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <libgpiod.h>

#define I2C_BUS "/dev/i2c-1"
#define SENSOR_ADDR 0x1D
#define REG_X_LSB 0x28
#define REG_X_MSB 0x29
#define REG_Y_LSB 0x2A
#define REG_Y_MSB 0x2B
#define REG_Z_LSB 0x2C
#define REG_Z_MSB 0x2D
#define SAMPLE_INTERVAL_MS 100
#define CSV_FILE "vibration_log.csv"

typedef struct {
    int fd;
    FILE *csv_file;
    int running;
} app_state;

void handle_signal(int sig) {
    if (sig == SIGINT) {
        printf("Caught SIGINT, cleaning up...\n");
        app_state *state = (app_state *)malloc(sizeof(app_state));
        if (state->csv_file) {
            fclose(state->csv_file);
        }
        if (state->fd >= 0) {
            close(state->fd);
        }
        free(state);
        exit(EXIT_SUCCESS);
    }
}

void log_error(const char *msg, int fd, FILE *csv_file) {
    fprintf(stderr, "Error: %s\n", msg);
    if (fd >= 0) {
        close(fd);
    }
    if (csv_file) {
        fclose(csv_file);
    }
    exit(EXIT_FAILURE);
}

void write_csv_header(FILE *csv_file) {
