#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/gpio.h>
#include <signal.h>
#include <time.h>
#include <string.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_HALL1 17
#define GPIO_HALL2 27
#define LOG_FILE "conveyor_log.txt"
#define POLL_INTERVAL_MS 50
#define MAX_LOG_LINE 256

typedef struct {
    int fd;
    struct gpio_line *line1;
    struct gpio_line *line2;
    FILE *log_file;
    int running;
} app_state;

void handle_signal(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        printf("Shutting down...\n");
        exit(EXIT_SUCCESS);
    }
}

void log_state(app_state *state, int hall1, int hall2) {
    char log_line[MAX_LOG_LINE];
    time_t now = time(NULL);
    struct tm *tm_now = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_now);

    snprintf(log_line, sizeof(log_line), "%s,%d,%d\n", timestamp, hall1, hall2);
    fprintf(state->log_file, log_line);
    fflush(state->log_file);
}

void cleanup(app_state *state) {
    if (state->log_file) {
        fclose(state->log_file);
    }

    if (state->line1) {
        gpio_line_release(state->line1);
    }

    if (state->line2) {
        gpio_line_release(state->line2);
    }

    if (state->fd >= 0) {
        close(state->fd);
    }

    printf("All resources released.\n");
}

int init_gpio(app_state *state) {
    state->fd = open("/dev/gpiochip0", O_RDWR);
    if (state->fd < 0) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    // Request line 1 (GPIO17)
    state->line1 = gpio_line_get(state->fd, GPIO_HALL1);
    if (!state->line1) {
        perror("Failed to get GPIO line 1");
        close(state->fd);
        return -1;
    }

    if (gpio_line_request_output(state->line1, GPIO_LINE_FLAG_BIAS_PULL_UP) < 0) {
        perror("Failed to request GPIO line 1");
        gpio_line_release(state->line1);
        close(state->fd);
        return -1;
    }

    // Request line 2 (GPIO27)
    state->line2 = gpio_line_get(state->fd, GPIO_HALL2);
    if (!state->line2) {
        perror("Failed to get GPIO line 2");
        gpio_line_release(state->line1);
        close(state->fd);
        return -1;
    }

    if (gpio_line_request_output(state->line2, GPIO_LINE_FLAG_BIAS_PULL_UP) < 0) {
        perror("Failed to request GPIO line 2");
        gpio_line_release(state->line1);
        gpio_line_release(state->line2);
        close(state->fd);
        return -1;
    }

    return 0;
}

int main() {
    app_state state = {0};
    struct timespec ts;
    int hall1, hall2;

    // Set up signal handling
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Initialize GPIO
    if (init_gpio(&state) < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return EXIT_FAILURE;
    }

    // Open log file
    state.log_file = fopen(LOG_FILE, "a");
    if (!state.log_file) {
        perror("Failed to open log file");
        cleanup(&state);
        return EXIT_FAILURE;
    }

    // Main loop
    state.running = 1;
    while (state.running) {
        // Read GPIO values
        if (gpio_line_get_value(state.line1, &hall1) < 0) {
            perror("Failed to read GPIO line 1");
            cleanup(&state);
            return EXIT_FAILURE;
        }

        if (gpio_line_get_value(state.line2, &hall2) < 0) {
            perror("Failed to read GPIO line 2");
            cleanup(&state);
            return EXIT_FAILURE;
        }

        // Log state
        log_state(&state, hall1, hall2);

        // Check for both sensors being high
        if (hall1 && hall2) {
            printf("Halt message: Both sensors are high, conveyor halted.\n");
        }

        // Sleep for 50ms
        ts.tv_sec = 0;
        ts.tv_nsec = 50 * 1000000;
        nanosleep(&ts, NULL);
    }

    cleanup(&state);
    return EXIT_SUCCESS;
}

