#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <stdint.h>

#define I2C_BUS "/dev/i2c-1"
#define MMA8452Q_ADDR 0x1D
#define WHO_AM_I 0x00
#define CTRL_REG1 0x2A
#define CTRL_REG2 0x2B
#define CTRL_REG3 0x2C
#define CTRL_REG4 0x2D
#define CTRL_REG5 0x2E
#define CTRL_REG6 0x2F
#define DATA_X_MSB 0x01
#define DATA_X_LSB 0x02
#define DATA_Y_MSB 0x03
#define DATA_Y_LSB 0x04
#define DATA_Z_MSB 0x05
#define DATA_Z_LSB 0x06
#define FALL_LOG "fall_log.txt"

volatile int running = 1;
FILE *log_file = NULL;
int i2c_fd = -1;

void signal_handler(int signum) {
    running = 0;
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    exit(EXIT_SUCCESS);
}

void i2c_init() {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MMA8452Q_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
}

void check_device_id() {
    uint8_t who_am_i;
    if (read(i2c_fd, &who_am_i, 1) < 0) {
        fprintf(stderr, "Failed to read WHO_AM_I register: %s\n", strerror(errno));
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    if (who_am_i != 0x53) {
        fprintf(stderr, "Invalid WHO_AM_I register value: 0x%02X (expected 0x53)\n", who_am_i);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
}

void configure_accelerometer() {
    uint8_t ctrl_reg1 = 0x00;
    if (write(i2c_fd, &ctrl_reg1, 1) < 0) {
        fprintf(stderr, "Failed to write to CTRL_REG1: %s\n", strerror(errno));
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Set to standby mode
    ctrl_reg1 = 0x01;
    if (write(i2c_fd, &ctrl_reg1, 1) < 0) {
        fprintf(stderr, "Failed to set standby mode: %s\n", strerror(errno));
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Set data rate to 100 Hz
    ctrl_reg1 = 0x00;
    if (write(i2c_fd, &ctrl_reg1, 1) < 0) {
        fprintf(stderr, "Failed to set data rate: %s\n", strerror(errno));
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Re-enable active mode
    ctrl_reg1 = 0x00;
    if (write(i2c_fd, &ctrl_reg1, 1) < 0) {
        fprintf(stderr, "Failed to re-enable active mode: %s\n", strerror(errno));
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
}

void read_accelerometer_data(int16_t *x, int16_t *y, int16_t *z) {
    uint8_t data[6];
    if (read(i2c_fd, data, 6) < 0) {
        fprintf(stderr, "Failed to read accelerometer data: %s\n", strerror(errno));
        return;
    }

    *x = (int16_t)(data[0] << 8 | data[1]);
    *y = (int16_t)(data[2] << 8 | data[3]);
    *z = (int16_t)(data[4] << 8 | data[5]);

    *x >>= 4;
    *y >>= 4;
    *z >>= 4;
}

double calculate_tilt(int16_t x, int16_t y, int16_t z) {
    double magnitude = sqrt(x * x + y * y + z * z);
    double tilt = atan2(sqrt(x * x + y * y), z) * (180.0 / M_PI);
    return tilt;
}

void log_fall(int16_t x, int16_t y, int16_t z) {
    time_t now = time(NULL);
    struct tm *tm_now = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_now);

    fprintf(log_file, "%s,%d,%d,%d\n", timestamp, x, y, z);
    fflush(log_file);
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    i2c_init();
    check_device_id();
    configure_accelerometer();

    log_file = fopen(FALL_LOG, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    while (running) {
        struct timespec ts = {0, 10000000}; // 10 ms
        nanosleep(&ts, NULL);

        int16_t x, y, z;
        read_accelerometer_data(&x, &y, &z);

        double tilt = calculate_tilt(x, y, z);
        if (tilt > 45.0) {
            log_fall(x, y, z);
        }
    }

    fclose(log_file);
    close(i2c_fd);
    return 0;
}

