        exit(EXIT_FAILURE);
    }
}

void configure_accelerometer() {
    uint8_t ctrl_reg1 = 0x00;
    if (write(i2c_fd, &ctrl_reg1, 1) < 0) {
        fprintf(stderr, "Failed to write to CTRL_REG1: %s\n", strerror(errno));
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Set to standby mode
    ctrl_reg1 = 0x01;
    if (write(i2c_fd, &ctrl_reg1, 1) < 0) {
        fprintf(stderr, "Failed to set standby mode: %s\n", strerror(errno));
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Set data rate to 100 Hz
    ctrl_reg1 = 0x00;
    if (write(i2c_fd, &ctrl_reg1, 1) < 0) {
        fprintf(stderr, "Failed to set data rate: %s\n", strerror(errno));
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Re-enable active mode
    ctrl_reg1 = 0x00;
    if (write(i2c_fd, &ctrl_reg1, 1) < 0) {
        fprintf(stderr, "Failed to re-enable active mode: %s\n", strerror(errno));
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
}

void read_accelerometer_data(int16_t *x, int16_t *y, int16_t *z) {
    uint8_t data[6];
    if (read(i2c_fd, data, 6) < 0) {
        fprintf(stderr, "Failed to read accelerometer data: %s\n", strerror(errno));
        return;
    }

    *x = (int16_t)(data[0] << 8 | data[1]);
    *y = (int16_t)(data[2] << 8 | data[3]);
    *z = (int16_t)(data[4] << 8 | data[5]);

    *x >>= 4;
    *y >>= 4;
    *z >>= 4;
}

double calculate_tilt(int16_t x, int16_t y, int16_t z) {
    double magnitude = sqrt(x * x + y * y + z * z);
    double tilt = atan2(sqrt(x * x + y * y), z) * (180.0 / M_PI);
    return tilt;
}

void log_fall(int16_t x, int16_t y, int16_t z) {
    time_t now = time(NULL);
    struct tm *tm_now = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_now);

    fprintf(log_file, "%s,%d,%d,%d\n", timestamp, x, y, z);
    fflush(log_file);
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    i2c_init();
    check_device_id();
    configure_accelerometer();

    log_file = fopen(FALL_LOG, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    while (running) {
        struct timespec ts = {0, 10000000}; // 10 ms
        nanosleep(&ts, NULL);

        int16_t x, y, z;
        read_accelerometer_data(&x, &y, &z);

        double tilt = calculate_tilt(x, y, z);
        if (tilt > 45.0) {
            log_fall(x, y, z);
        }
    }

    fclose(log_file);
    close(i2c_fd);
    return 0;
}
