#define LIS3MDL_CTRL_REG1_DEFAULT 0x80  // 10Hz, 4 gauss full scale
#define LIS3MDL_OFFSET_X 1234
#define LIS3MDL_OFFSET_Y 5678
#define LIS3MDL_OFFSET_Z 9012
#define LIS3MDL_SCALE 0.146
#define MAGNITUDE_THRESHOLD 800.0
#define MAX_RETRIES 3

typedef struct {
    int fd;
    FILE *log_file;
    int retry_count;
} i2c_context;

void handle_signal(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        if (signal(signum, SIG_IGN) == 0) {
            if (i2c_context.log_file) {
                fclose(i2c_context.log_file);
                i2c_context.log_file = NULL;
            }
            if (i2c_context.fd >= 0) {
                close(i2c_context.fd);
                i2c_context.fd = -1;
            }
            exit(EXIT_SUCCESS);
        }
    }
}

int i2c_init() {
    int retries = 0;
    int fd = -1;

    while (retries < MAX_RETRIES) {
        fd = open(I2C_BUS, O_RDWR | O_NOCTTY | O_CLOEXEC);
        if (fd < 0) {
            fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
            retries++;
            usleep(100000);
            continue;
        }

        if (ioctl(fd, I2C_SLAVE, LIS3MDL_ADDR) < 0) {
            fprintf(stderr, "Failed to set I2C slave address: %s\n", strerror(errno));
            close(fd);
            retries++;
            usleep(100000);
            continue;
        }

        // Write control register
        unsigned char ctrl_reg1[2] = {LIS3MDL_CTRL_REG1_DEFAULT};
        if (write(fd, ctrl_reg1, 1) != 1) {
            fprintf(stderr, "Failed to write control register: %s\n", strerror(errno));
            close(fd);
            retries++;
            usleep(100000);
            continue;
        }

        // Read status register to check if device is responding
        unsigned char status[1];
        if (read(fd, status, 1) != 1) {
            fprintf(stderr, "Failed to read status register: %s\n", strerror(errno));
            close(fd);
            retries++;
            usleep(100000);
            continue;
        }

        if (status[0] & 0x01) {
            break;
        } else {
            fprintf(stderr, "LIS3MDL not responding, retrying...\n");
            close(fd);
            retries++;
            usleep(100000);
        }
    }

    if (retries >= MAX_RETRIES) {
        fprintf(stderr, "Failed to initialize LIS3MDL after %d retries\n", MAX_RETRIES);
        return -1;
    }

    i2c_context.fd = fd;
    return 0;
}

