    unsigned char data[6];
    if (read(i2c_context.fd, data, 6) != 6) {
        fprintf(stderr, "I2C read error: %s\n", strerror(errno));
        return -1;
    }

    *x = (int)(data[1] << 8 | data[0]);
    *y = (int)(data[3] << 8 | data[2]);
    *z = (int)(data[5] << 8 | data[4]);

    return 0;
}

