                      (y - LIS3MDL_OFFSET_Y) * (y - LIS3MDL_OFFSET_Y) +
                      (z - LIS3MDL_OFFSET_Z) * (z - LIS3MDL_OFFSET_Z));
    mag *= LIS3MDL_SCALE;

    if (mag > MAGNITUDE_THRESHOLD) {
        fprintf(stderr, "Metal detected! Total field magnitude: %.2f mG\n", mag);
    }

    char buffer[128];
    snprintf(buffer, sizeof(buffer), "%.2f,%.2f,%.2f\n", mag, mag, mag);
    fprintf(i2c_context.log_file, buffer);
    fflush(i2c_context.log_file);
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    i2c_context.log_file = fopen("magnetic_log.txt", "w");
    if (!i2c_context.log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (i2c_init() < 0) {
        fclose(i2c_context.log_file);
        return EXIT_FAILURE;
    }

    while (1) {
        int x, y, z;
        if (i2c_read_data(&x, &y, &z) < 0) {
            fprintf(stderr, "I2C read failed, retrying...\n");
            usleep(100000);
            continue;
        }

        log_data(x, y, z);
        usleep(100000); // 10Hz
    }

    fclose(i2c_context.log_file);
    close(i2c_context.fd);
    return EXIT_SUCCESS;
}

