#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define SPI_MODE SPI_MODE_0
#define CE_PIN 8
#define RESET_REGISTER 0x00
#define RESET_VALUE 0x55
#define POWER_CONTROL_REGISTER 0x2D
#define RUN_BIT 0x01
#define STATUS_REGISTER 0x0B
#define STABLE_BIT 0x80
#define PARTID_REGISTER 0x00
#define PARTID_VALUE 0xAD
#define X_AXIS_REGISTER 0x32
#define Y_AXIS_REGISTER 0x34
#define Z_AXIS_REGISTER 0x36
#define AXIS_BYTES 3
#define RETRIES 5
#define LOG_FILE "vibration_log.txt"
#define LOG_INTERVAL_MS 100

typedef struct {
    int spi_fd;
    struct gpiod_line *ce_line;
    FILE *log_file;
    int running;
} app_state;

void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        printf("Shutting down...\n");
        app_state *state = (app_state *)malloc(sizeof(app_state));
        state->running = 0;
        free(state);
        exit(EXIT_SUCCESS);
    }
}

void spi_init(app_state *state) {
    state->spi_fd = open(SPI_DEVICE, O_RDWR | O_NOCTTY | O_SYNC);
    if (state->spi_fd < 0) {
        perror("Failed to open SPI device");
        exit(EXIT_FAILURE);
    }

    struct spi_ioc_transfer spi;
    memset(&spi, 0, sizeof(spi));
    spi.speed_hz = SPI_SPEED;
    spi.mode = SPI_MODE;
    spi.bits_per_word = 8;

    if (ioctl(state->spi_fd, SPI_IOC_WR_MODE, &spi.mode) < 0) {
        perror("SPI mode set failed");
        close(state->spi_fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(state->spi_fd, SPI_IOC_WR_BITS_PER_WORD, &spi.bits_per_word) < 0) {
        perror("SPI bits per word set failed");
        close(state->spi_fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(state->spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &spi.speed_hz) < 0) {
        perror("SPI speed set failed");
        close(state->spi_fd);
        exit(EXIT_FAILURE);
    }

    state->ce_line = gpiod_line_get("gpiochip0", CE_PIN);
    if (!state->ce_line) {
        perror("Failed to get CE GPIO line");
        close(state->spi_fd);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(state->ce_line, "CE", GPIOD_LINE_REQUEST_OUTPUT | GPIOD_LINE_REQUEST_FLAG_ACTIVE_LOW)) {
        perror("Failed to request CE GPIO line");
        gpiod_line_put(state->ce_line);
        close(state->spi_fd);
        exit(EXIT_FAILURE);
    }

    gpiod_line_set_value(state->ce_line, 1);
}

void spi_deinit(app_state *state) {
    gpiod_line_set_value(state->ce_line, 1);
    gpiod_line_put(state->ce_line);
    close(state->spi_fd);
}

void spi_transfer(app_state *state, const uint8_t *tx, uint8_t *rx, size_t len) {
    struct spi_ioc_transfer spi;
    memset(&spi, 0, sizeof(spi));
    spi.tx_buf = (unsigned long)tx;
    spi.rx_buf = (unsigned long)rx;
    spi.len = len;
    spi.speed_hz = SPI_SPEED;
    spi.mode = SPI_MODE;
    spi.bits_per_word = 8;

    for (int i = 0; i < RETRIES; i++) {
        if (ioctl(state->spi_fd, SPI_IOC_MESSAGE(1), &spi) == 1) {
            return;
        }
        usleep(1000);
    }
    perror("SPI transfer failed after retries");
    exit(EXIT_FAILURE);
}

void reset_sensor(app_state *state) {
    uint8_t reset_data[2] = {RESET_REGISTER, RESET_VALUE};
    uint8_t rx[2] = {0};

    spi_transfer(state, reset_data, rx, sizeof(reset_data));
    usleep(1000); // Wait 1 ms

    uint8_t power_control_data[2] = {POWER_CONTROL_REGISTER, 0x00};
    spi_transfer(state, power_control_data, rx, sizeof(power_control_data));
    usleep(100000); // Wait 100 ms

    uint8_t status_data[2] = {STATUS_REGISTER, 0x00};
    uint8_t status[2] = {0};

    while (1) {
        spi_transfer(state, status_data, status, sizeof(status));
        if (status[1] & STABLE_BIT) {
            break;
        }
        usleep(10000);
    }

    uint8_t run_data[2] = {POWER_CONTROL_REGISTER, RUN_BIT};
    spi_transfer(state, run_data, rx, sizeof(run_data));
}

void verify_sensor(app_state *state) {
    uint8_t partid_data[2] = {PARTID_REGISTER, 0x00};
    uint8_t partid[2] = {0};

    spi_transfer(state, partid_data, partid, sizeof(partid));
    if (partid[1] != PARTID_VALUE) {
        fprintf(stderr, "Sensor not found: PARTID mismatch (expected 0xAD, got 0x%02X)\n", partid[1]);
        exit(EXIT_FAILURE);
    }
}

void read_acceleration(app_state *state, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t x_data[2] = {X_AXIS_REGISTER, 0x00};
    uint8_t x_response[AXIS_BYTES] = {0};
    spi_transfer(state, x_data, x_response, sizeof(x_response));
    *x = (int16_t)(x_response[0] << 8 | x_response[1]);

    uint8_t y_data[2] = {Y_AXIS_REGISTER, 0x00};
    uint8_t y_response[AXIS_BYTES] = {0};
    spi_transfer(state, y_data, y_response, sizeof(y_response));
    *y = (int16_t)(y_response[0] << 8 | y_response[1]);

    uint8_t z_data[2] = {Z_AXIS_REGISTER, 0x00};
    uint8_t z_response[AXIS_BYTES] = {0};
    spi_transfer(state, z_data, z_response, sizeof(z_response));
    *z = (int16_t)(z_response[0] << 8 | z_response[1]);
}

void log_data(app_state *state, int16_t x, int16_t y, int16_t z) {
    time_t now = time(NULL);
    struct tm *tm_now = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_now);

    fprintf(state->log_file, "%s, %d, %d, %d\n", timestamp, x, y, z);
    fflush(state->log_file);
}

void init_logging(app_state *state) {
    state->log_file = fopen(LOG_FILE, "w");
    if (!state->log_file) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }
}

void close_logging(app_state *state) {
    fclose(state->log_file);
}

int main() {
    app_state state;
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    spi_init(&state);
    init_logging(&state);
    reset_sensor(&state);
    verify_sensor(&state);

    state.running = 1;
    while (state.running) {
        int16_t x, y, z;
        read_acceleration(&state, &x, &y, &z);
        log_data(&state, x, y, z);
        usleep(100000); // 100 ms
    }

    close_logging(&state);
    spi_deinit(&state);
    return 0;
}

