    ctx->spi_fd = open(SPI_DEVICE, O_RDWR | O_NOCTTY | O_SYNC);
    if (ctx->spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device %s: %s\n", SPI_DEVICE, strerror(errno));
        gpiod_line_put(ctx->ce_line);
        return -1;
    }

    // Set SPI mode
    if (ioctl(ctx->spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
