    if (ioctl(ctx->spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        fprintf(stderr, "Failed to set SPI speed: %s\n", strerror(errno));
        close(ctx->spi_fd);
        gpiod_line_put(ctx->ce_line);
        return -1;
    }

    // Set bits per word
    if (ioctl(ctx->spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS_PER_WORD) < 0) {
        fprintf(stderr, "Failed to set SPI bits per word: %s\n", strerror(errno));
        close(ctx->spi_fd);
        gpiod_line_put(ctx->ce_line);
        return -1;
    }

    // Set SPI mode to 3
    if (ioctl(ctx->spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        fprintf(stderr, "Failed to set SPI mode again: %s\n", strerror(errno));
        close(ctx->spi_fd);
        gpiod_line_put(ctx->ce_line);
        return -1;
    }

    return 0;
