            fprintf(stderr, "Failed to close log file: %s\n", strerror(errno));
        }
    }
}

int read_imu_data(imu_context *ctx, int16_t *gyro, int16_t *accel) {
    uint8_t tx[SPI_MAX_TRANSFER_SIZE];
    uint8_t rx[SPI_MAX_TRANSFER_SIZE];
    int ret;

    // Set CE high
    if (gpiod_line_set_value(ctx->ce_line, 1)) {
        fprintf(stderr, "Failed to set CE high\n");
        return -1;
    }

    // Send address with MSB set (0x80) and dummy byte (0x00)
    tx[0] = 0x80; // MSB set
    tx[1] = 0x00; // dummy byte

    // Perform SPI transfer
    struct spi_ioc_transfer spi = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = SPI_MAX_TRANSFER_SIZE,
        .delay_usecs = 0,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD
    };

    ret = ioctl(ctx->spi_fd, SPI_IOC_MESSAGE(1), &spi);
    if (ret < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }

    // Set CE low
    if (gpiod_line_set_value(ctx->ce_line, 0)) {
        fprintf(stderr, "Failed to set CE low\n");
        return -1;
    }

    // Extract 16-bit data
    *gyro = (int16_t)(rx[1] << 8 | rx[0]);
    *accel = (int16_t)(rx[3] << 8 | rx[2]);

    return 0;
}

