        // Log data
        log_data(&ctx, timestamp, gyro[0], gyro[1], gyro[2], accel[0], accel[1], accel[2]);

        // Delay to achieve ~100Hz sampling
        usleep(SAMPLE_DELAY_MS * 1000);
    }

    // Clean up
    close_log_file(&ctx);
    deinit_spi(&ctx);

    return EXIT_SUCCESS;
}

