#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip4"
#define GPIO_LINE 17
#define POLL_INTERVAL 1
#define OBSTACLE_THRESHOLD 0  // 0 = obstacle detected, 1 = no obstacle

typedef enum {
    STATE_IDLE,
    STATE_SELF_PARKING
} state_t;

state_t current_state = STATE_IDLE;

void handle_sigint(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    exit(EXIT_SUCCESS);
}

void log_message(const char *message) {
    char timestamp[30];
    time_t now = time(NULL);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
    printf("[%s] %s\n", timestamp, message);
}

void cleanup_gpio(gpiod_line *line, gpiod_chip *chip) {
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main() {
    gpiod_chip *chip = NULL;
    gpiod_line *line = NULL;
    int ret;

    // Set up signal handler
    signal(SIGINT, handle_sigint);

    // Open the GPIO chip
    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip %s: %s\n", GPIO_CHIP, strerror(errno));
        return EXIT_FAILURE;
    }

    // Request the GPIO line
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line %d from chip %s: %s\n", GPIO_LINE, GPIO_CHIP, strerror(errno));
        cleanup_gpio(line, chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(line, "obstacle_sensor", 1);  // Set to high initially
    if (ret < 0) {
        fprintf(stderr, "Failed to request GPIO line %d: %s\n", GPIO_LINE, strerror(errno));
        cleanup_gpio(line, chip);
        return EXIT_FAILURE;
    }

    // Main loop
    while (1) {
        // Read the line value
        int value = gpiod_line_get_value(line);
        if (value < 0) {
            fprintf(stderr, "Failed to read GPIO line %d: %s\n", GPIO_LINE, strerror(errno));
            cleanup_gpio(line, chip);
