#define RETRY_DELAY_MS 1000

typedef struct {
    struct gpiod_line *line1;
    struct gpiod_line *line2;
    struct gpiod_chip *chip;
} SensorContext;

void handle_signal(int signum) {
    printf("\nCaught signal %d, exiting...\n", signum);
    exit(EXIT_SUCCESS);
}

void cleanup(SensorContext *context) {
    if (context->chip) {
        gpiod_chip_close(context->chip);
    }
    if (context->line1) {
        gpiod_line_release(context->line1);
    }
    if (context->line2) {
        gpiod_line_release(context->line2);
    }
}

int init_sensors(SensorContext *context) {
    context->chip = gpiod_chip_open("/dev/gpiochip0");
    if (!context->chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return -1;
    }

    context->line1 = gpiod_chip_get_line(context->chip, GPIO_PIN_17);
    if (!context->line1) {
        fprintf(stderr, "Failed to get line %d\n", GPIO_PIN_17);
        gpiod_chip_close(context->chip);
        return -1;
    }

    context->line2 = gpiod_chip_get_line(context->chip, GPIO_PIN_27);
    if (!context->line2) {
        fprintf(stderr, "Failed to get line %d\n", GPIO_PIN_27);
        gpiod_line_release(context->line1);
        gpiod_chip_close(context->chip);
        return -1;
    }

    if (gpiod_line_request_output(context->line1, "sensor1", 0) < 0) {
        fprintf(stderr, "Failed to request line %d as output\n", GPIO_PIN_17);
        gpiod_line_release(context->line1);
        gpiod_line_release(context->line2);
        gpiod_chip_close(context->chip);
        return -1;
    }

    if (gpiod_line_request_output(context->line2, "sensor2", 0) < 0) {
        fprintf(stderr, "Failed to request line %d as output\n", GPIO_PIN_27);
        gpiod_line_release(context->line1);
        gpiod_line_release(context->line2);
        gpiod_chip_close(context->chip);
        return -1;
    }

    return 0;
}

void read_sensors(SensorContext *context) {
    int value1, value2;
    int retries = 0;

    do {
        value1 = gpiod_line_get_value(context->line1);
        value2 = gpiod_line_get_value(context->line2);

        if (value1 < 0 || value2 < 0) {
            fprintf(stderr, "Failed to read GPIO values\n");
            retries++;
            usleep(RETRY_DELAY_MS * 1000);
        } else {
            break;
        }
    } while (retries < MAX_RETRIES);

    if (retries >= MAX_RETRIES) {
        fprintf(stderr, "Failed to read sensors after %d retries\n", MAX_RETRIES);
        return;
