        fprintf(stderr, "Failed to initialize sensors\n");
        return EXIT_FAILURE;
    }

    while (1) {
        read_sensors(&context);
        usleep(POLL_INTERVAL_MS * 1000);
    }

    cleanup(&context);
    return EXIT_SUCCESS;
}

