#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>
#include <signal.h>
#include <time.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define SPI_MODE SPI_MODE_3
#define SPI_BITS_PER_WORD 8
#define SPI_MAX_TRANSFER_SIZE 3
#define SPI_READ_DELAY_MS 100
#define SPI_READ_BYTES 2
#define ADDR_BYTE 0x80
#define SCALE_FACTOR 0.02f

typedef struct {
    int spi_fd;
    struct gpiod_line *cs_line;
    int running;
} sensor_context;

void handle_signal(int sig) {
    if (sig == SIGINT) {
        printf("\nReceived SIGINT, shutting down...\n");
    }
    exit(EXIT_SUCCESS);
}

int init_spi() {
    int spi_fd = open(SPI_DEVICE, O_RDWR | O_NOCTTY | O_SYNC);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    struct spi_ioc_transfer spi;
    memset(&spi, 0, sizeof(spi));
    spi.speed_hz = SPI_SPEED;
    spi.mode = SPI_MODE;
    spi.bits_per_word = SPI_BITS_PER_WORD;

    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        return -1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS_PER_WORD) < 0) {
        perror("Failed to set SPI bits per word");
        close(spi_fd);
        return -1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        return -1;
    }

    return spi_fd;
}

int init_cs_gpio() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int ret;

    chip = gpiod_chip_open("/dev/gpiochip8");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    line = gpiod_line_get(chip, 8);  // BCM GPIO 8
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(line, "cs_line", GPIOD_LINE_REQUEST_FLAG_ACTIVE_LOW) < 0) {
        perror("Failed to request GPIO line");
        gpiod_line_put(line);
        gpiod_chip_close(chip);
        return -1;
    }

    gpiod_line_set_value(line, 1);  // Set CS high (inactive)

    return line;
}

void release_cs_gpio(struct gpiod_line *cs_line) {
    if (cs_line) {
        gpiod_line_set_value(cs_line, 1);  // Set CS high
        gpiod_line_put(cs_line);
    }
}

void release_spi(int spi_fd) {
    if (spi_fd >= 0) {
        close(spi_fd);
    }
}

void read_gyro_data(int spi_fd, struct gpiod_line *cs_line, float *x, float *y, float *z) {
    uint8_t tx[1] = {ADDR_BYTE};
    uint8_t rx[2];

    gpiod_line_set_value(cs_line, 0);  // CS low

    struct spi_ioc_transfer spi;
    memset(&spi, 0, sizeof(spi));
    spi.tx_buf = (unsigned long)tx;
    spi.rx_buf = (unsigned long)rx;
    spi.len = 1;
    spi.delay_usecs = 10;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &spi) < 0) {
        perror("SPI write failed");
        return;
    }

    // Read 2 bytes
    spi.tx_buf = (unsigned long)NULL;
    spi.rx_buf = (unsigned long)rx;
    spi.len = 2;
    spi.delay_usecs = 10;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &spi) < 0) {
        perror("SPI read failed");
        return;
    }

    gpiod_line_set_value(cs_line, 1);  // CS high

    // Extract data
    uint16_t data = (rx[0] << 8) | rx[1];
    *x = (data & 0x00FF) * SCALE_FACTOR;
    *y = ((data >> 8) & 0x00FF) * SCALE_FACTOR;
    *z = ((data >> 16) & 0x00FF) * SCALE_FACTOR;
}

void log_gyro_data(float x, float y, float z) {
    static time_t last_log_time = 0;
    time_t current_time;
    struct tm *tm_info;

    time(&current_time);
    tm_info = localtime(&current_time);

    if (difftime(current_time, last_log_time) >= 0.1) {
        printf("[%02d:%02d:%02d] X: %.2f deg/s, Y: %.2f deg/s, Z: %.2f deg/s\n",
               tm_info->tm_hour, tm_info->tm_min, tm_info->tm_sec,
               x, y, z);
        last_log_time = current_time;
    }
}

int main() {
    sensor_context context = {0};
    float x, y, z;
    int ret;

    signal(SIGINT, handle_signal);

    context.spi_fd = init_spi();
    if (context.spi_fd < 0) {
        fprintf(stderr, "SPI initialization failed\n");
        return EXIT_FAILURE;
    }

    context.cs_line = init_cs_gpio();
    if (!context.cs_line) {
        fprintf(stderr, "GPIO initialization failed\n");
        release_spi(context.spi_fd);
        return EXIT_FAILURE;
    }

    while (context.running) {
        read_gyro_data(context.spi_fd, context.cs_line, &x, &y, &z);
        log_gyro_data(x, y, z);
        usleep(SPI_READ_DELAY_MS * 1000);
    }

    release_cs_gpio(context.cs_line);
    release_spi(context.spi_fd);

    return EXIT_SUCCESS;
}

