#define MAGNETOMETER_DATA_REGISTER 0x01
#define ACCEL_DATA_SIZE 6
#define MAGNETOMETER_DATA_SIZE 6
#define DATA_SIZE (ACCEL_DATA_SIZE + MAGNETOMETER_DATA_SIZE)
#define POLL_INTERVAL_MS 100

typedef struct {
    int fd;
    int i2c_bus;
    int i2c_addr;
    int retry_count;
} i2c_context;

void handle_signal(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    exit(EXIT_SUCCESS);
}

int i2c_init(int bus, int addr) {
    int fd = -1;
    char filename[256];
    snprintf(filename, sizeof(filename), "/dev/i2c-%d", bus);

    fd = open(filename, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Failed to set I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

int i2c_read(int fd, uint8_t reg, uint8_t *buf, size_t len, int retry_count) {
    uint8_t *write_buf = malloc(1);
    write_buf[0] = reg;
    if (write_buf == NULL) {
        perror("Memory allocation failed");
        return -1;
    }

    int retries = 0;
    while (retries < retry_count) {
        if (ioctl(fd, I2C_RDWR, (struct i2c_msg *)write_buf) < 0) {
            perror("I2C write failed");
            free(write_buf);
            return -1;
        }

        struct i2c_msg msg;
        msg.addr = I2C_ADDR;
        msg.flags = 0;
        msg.len = len;
        msg.buf = buf;

        if (ioctl(fd, I2C_RDWR, (struct i2c_msg *)&msg) < 0) {
            perror("I2C read failed");
            free(write_buf);
            return -1;
        }

        free(write_buf);
        return 0;
    }

    free(write_buf);
    fprintf(stderr, "I2C read failed after %d retries\n", retry_count);
    return -1;
}

void i2c_cleanup(int fd) {
    if (fd >= 0) {
        close(fd);
    }
}

int main() {
    i2c_context context = {0};
    uint8_t who_am_i = 0;
    uint8_t data[DATA_SIZE];
    int i2c_fd;

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    context.i2c_bus = I2C_BUS;
    context.i2c_addr = I2C_ADDR;
    context.retry_count = 3;

    i2c_fd = i2c_init(context.i2c_bus, context.i2c_addr);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to initialize I2C\n");
        return EXIT_FAILURE;
    }

    // Check device presence
    if (i2c_read(i2c_fd, WHO_AM_I_REGISTER, &who_am_i, 1, context.retry_count) < 0) {
        fprintf(stderr, "Failed to read WHO_AM_I register\n");
        i2c_cleanup(i2c_fd);
        return EXIT_FAILURE;
    }

    if (who_am_i != FXOS8700_WHO_AM_I) {
        fprintf(stderr, "Device not found: expected 0x%02X, got 0x%02X\n", FXOS8700_WHO_AM_I, who_am_i);
        i2c_cleanup(i2c_fd);
        return EXIT_FAILURE;
    }

    printf("Device found: FXOS8700\n");

    while (1) {
        if (i2c_read(i2c_fd, ACCEL_DATA_REGISTER, data, DATA_SIZE, context.retry_count) < 0) {
            fprintf(stderr, "I2C read failed\n");
            sleep(1);
            continue;
        }

        // Extract accelerometer data (14-bit left-aligned)
        int16_t ax = (data[0] << 8) | data[1];
        int16_t ay = (data[2] << 8) | data[3];
        int16_t az = (data[4] << 8) | data[5];

        // Extract magnetometer data (16-bit)
        int16_t mx = (data[6] << 8) | data[7];
        int16_t my = (data[8] << 8) | data[9];
        int16_t mz = (data[10] << 8) | data[11];

        printf("Accel: X=%d Y=%d Z=%d | Mag: X=%d Y=%d Z=%d\n", ax, ay, az, mx, my, mz);

        usleep(100000); // 100ms
    }

    i2c_cleanup(i2c_fd);
    return EXIT_SUCCESS;
}

