#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS 1
#define I2C_ADDR 0x53
#define ACCEL_XOUT_H 0x3B
#define ACCEL_XOUT_L 0x3C
#define ACCEL_YOUT_H 0x3D
#define ACCEL_YOUT_L 0x3E
#define ACCEL_ZOUT_H 0x3F
#define ACCEL_ZOUT_L 0x40
#define POWER_CTL 0x2D
#define RANGE_2G 0x08
#define DATA_FORMAT 0x31
#define FIFO_CTL 0x25
#define THRESH_TAP 0x1D
#define DURATION 0x21
#define LATENT 0x22
#define WINDOW 0x23
#define OFFSET_X_HP 0x24
#define OFFSET_Y_HP 0x25
#define OFFSET_Z_HP 0x26
#define INT_ENABLE 0x2E
#define INT_PIN_CFG 0x2F
#define INT_SOURCE 0x30
#define DATA_READY 0x08

#define TILT_THRESHOLD 30.0
#define LOG_FILE "/var/log/tilt_events.log"
#define SAMPLE_INTERVAL_MS 100

typedef struct {
    int fd;
    struct gpiod_line *reset_line;
    struct gpiod_line *int_line;
} i2c_device;

void handle_signal(int sig);
void log_event(const char *message);
void i2c_init(i2c_device *device);
void i2c_deinit(i2c_device *device);
int read_accel_data(int fd, int16_t *x, int16_t *y, int16_t *z);
double calculate_tilt_angle(int16_t x, int16_t y, int16_t z);
void configure_accel(i2c_device *device);
void write_log_entry(double tilt_angle);

int main() {
    i2c_device device = {0};
    int ret;

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if ((device.fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    if (ioctl(device.fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(device.fd);
        exit(EXIT_FAILURE);
    }

    i2c_init(&device);
    configure_accel(&device);

    printf("ADXL345 tilt detection started. Logging tilt events exceeding 30.0 degrees.\n");

    while (1) {
        int16_t x, y, z;
        if (read_accel_data(device.fd, &x, &y, &z) < 0) {
            fprintf(stderr, "I2C read failed, retrying...\n");
            usleep(100000);
            continue;
        }

        double tilt_angle = calculate_tilt_angle(x, y, z);
        if (tilt_angle > TILT_THRESHOLD) {
            write_log_entry(tilt_angle);
        }

        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    i2c_deinit(&device);
    close(device.fd);
    return 0;
}

void handle_signal(int sig) {
    printf("\nReceived signal %d, shutting down...\n", sig);
    exit(EXIT_SUCCESS);
}

void log_event(const char *message) {
    FILE *fp;
    time_t t;
    struct tm *tm_info;

    if ((fp = fopen(LOG_FILE, "a")) == NULL) {
        perror("Failed to open log file");
        return;
    }

    time(&t);
    tm_info = localtime(&t);
    fprintf(fp, "[%02d:%02d:%02d] %s\n", tm_info->tm_hour, tm_info->tm_min, tm_info->tm_sec, message);
    fclose(fp);
}

void i2c_init(i2c_device *device) {
    // Initialize GPIO lines for reset and interrupt
    device->reset_line = gpiod_line_get("BCM2", 27, "reset");
    if (!device->reset_line) {
        perror("Failed to get reset GPIO line");
        exit(EXIT_FAILURE);
    }

    device->int_line = gpiod_line_get("BCM2", 28, "int");
    if (!device->int_line) {
        perror("Failed to get interrupt GPIO line");
        exit(EXIT_FAILURE);
    }

    gpiod_line_request_output(device->reset_line, "reset", GPIOD_LINE_REQUEST_OUTPUT_ACTIVE_LOW);
    gpiod_line_set_value(device->reset_line, 1); // High to release from reset
    usleep(100000); // Wait for reset to stabilize
    gpiod_line_set_value(device->reset_line, 0); // Low to reset
    usleep(100000); // Wait for reset to complete
    gpiod_line_set_value(device->reset_line, 1); // High to release from reset
}

void i2c_deinit(i2c_device *device) {
    gpiod_line_release(device->reset_line);
    gpiod_line_release(device->int_line);
}

int read_accel_data(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buffer[6];
    int ret;

    if (read(fd, buffer, 6) != 6) {
        return -1;
    }

    *x = (int16_t)(buffer[0] << 8 | buffer[1]);
    *y = (int16_t)(buffer[2] << 8 | buffer[3]);
    *z = (int16_t)(buffer[4] << 8 | buffer[5]);

    return 0;
}

double calculate_tilt_angle(int16_t x, int16_t y, int16_t z) {
    double magnitude = sqrt(x * x + y * y + z * z);
    if (magnitude == 0) {
        return 0.0;
    }

    double angle_rad = atan2(sqrt(x * x + y * y), z);
    double angle_deg = angle_rad * (180.0 / M_PI);

    if (angle_deg < 0) {
        angle_deg += 360.0;
    }

    return angle_deg;
}

void configure_accel(i2c_device *device) {
    uint8_t data;

    // Set data format to +/- 2g range
    data = RANGE_2G;
    if (write(device.fd, &data, 1) != 1) {
        fprintf(stderr, "Failed to set data format\n");
        exit(EXIT_FAILURE);
    }

    // Set power control to active
    data = 0x08;
    if (write(device.fd, &data, 1) != 1) {
        fprintf(stderr, "Failed to set power control\n");
        exit(EXIT_FAILURE);
    }

    // Enable data ready interrupt
    data = DATA_READY;
    if (write(device.fd, &data, 1) != 1) {
        fprintf(stderr, "Failed to set interrupt configuration\n");
        exit(EXIT_FAILURE);
    }

    // Enable interrupt
    data = 0x80;
    if (write(device.fd, &data, 1) != 1) {
        fprintf(stderr, "Failed to enable interrupt\n");
        exit(EXIT_FAILURE);
    }
}

void write_log_entry(double tilt_angle) {
    char message[256];
    snprintf(message, sizeof(message), "Tilt angle exceeded threshold: %.2f degrees", tilt_angle);
