#include <time.h>
#include <gpiod.h>

#define GPIO_PIN 17
#define WINDOW_DURATION_MS 5000
#define SAMPLE_INTERVAL_MS 1
#define PAUSE_DURATION_S 1
#define MAX_THRESHOLD 1000

typedef enum {
    STATUS_OK,
    STATUS_ERROR,
    STATUS_SIGINT,
    STATUS_SIGTERM
} program_status;

static gpiod_line *line = NULL;
static int threshold = 0;
static int running = 1;

void handle_signal(int sig) {
    running = 0;
    if (line) {
        gpiod_line_release(line);
        line = NULL;
    }
    printf("Signal received, exiting...\n");
    exit(EXIT_SUCCESS);
}

void print_status(const char *timestamp, const char *status) {
    printf("%s %s\n", timestamp, status);
}

void setup_gpio() {
    struct gpiod_chip *chip;
    struct gpiod_line_config config = GPIOD_LINE_CONFIG_DEFAULTS;

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        exit(EXIT_FAILURE);
    }

    config.consumer = "sound_sensor";
    config.direction = GPIOD_LINE_DIRECTION_INPUT;
    config.flags = GPIOD_LINE_FLAG_ACTIVE_LOW;

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line %d\n", GPIO_PIN);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_config(line, &config) < 0) {
        fprintf(stderr, "Failed to request GPIO line %d\n", GPIO_PIN);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_set_value(line, 0) < 0) {
        fprintf(stderr, "Failed to set initial value for GPIO line %d\n", GPIO_PIN);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }
}

void cleanup_gpio() {
    if (line) {
        gpiod_line_release(line);
        line = NULL;
    }
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <threshold>\n", argv[0]);
        return EXIT_FAILURE;
    }

    if (sscanf(argv[1], "%d", &threshold) != 1 || threshold <= 0 || threshold > MAX_THRESHOLD) {
        fprintf(stderr, "Error: Threshold must be a positive integer <= %d\n", MAX_THRESHOLD);
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    setup_gpio();

    while (running) {
        int high_count = 0;
        struct timespec ts = {0, 0};
        clock_gettime(CLOCK_MONOTONIC, &ts);
        time_t now = ts.tv_sec;
        char timestamp[30];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

        for (int i = 0; i < WINDOW_DURATION_MS * 1000 / SAMPLE_INTERVAL_MS; i++) {
            int value;
            if (gpiod_line_get_value(line, &value) < 0) {
                fprintf(stderr, "Failed to read GPIO line %d\n", GPIO_PIN);
                cleanup_gpio();
                return EXIT_FAILURE;
            }

            if (value == 1) {
                high_count++;
            }

            usleep(SAMPLE_INTERVAL_MS * 1000);
        }

        if (high_count > threshold) {
            print_status(timestamp, "ALERT");
        } else {
            print_status(timestamp, "Status: No alert");
        }

        usleep(PAUSE_DURATION_S * 1000000);
    }

    cleanup_gpio();
    return EXIT_SUCCESS;
}

