#include <unistd.h>
#include <fcntl.h>
#include <errno.h>

volatile sig_atomic_t exit_flag = 0;

// Function to handle signals
void handle_signal(int signum) {
    exit_flag = 1;
}

// Function to generate a random 6-digit code
void generate_code(int *code) {
    *code = rand() % 900000 + 100000;
}

// Function to read user input with validation
int read_input(int code) {
    char input[7];
    int len;
    while (1) {
        printf("Enter code: ");
        if (fgets(input, sizeof(input), stdin) != NULL) {
            len = strlen(input);
            if (len == 6 && input[5] == '\n') {
                input[5] = '\0';
                if (sscanf(input, "%d", &code) == 1) {
                    return 0;
                }
            }
        }
        printf("Invalid input. Please enter a 6-digit number.\n");
        // Clear the input buffer
        while (getchar() != '\n');
    }
}

// Function to log access
void log_access(const char *timestamp, int code) {
    FILE *file = fopen("access_log.txt", "a");
    if (file == NULL) {
        perror("Failed to open access_log.txt");
        return;
    }

    fprintf(file, "%s,%d\n", timestamp, code);
    fclose(file);
}

// Function to set GPIO line value
void set_gpio_line_value(gpiod_line *line, int value) {
    int ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        fprintf(stderr, "Failed to set GPIO line value: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }
}

int main() {
    // Initialize random seed
    srand(time(NULL));

    // Set up signal handling
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Initialize GPIO
    struct gpiod_chip *chip;
    struct gpiod_line *door_a_line, *door_b_line;

    chip = gpiod_chip_open("/dev/gpiochip4");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    door_a_line = gpiod_chip_get_line(chip, 17);
    if (!door_a_line) {
        fprintf(stderr, "Failed to get GPIO line 17: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    door_b_line = gpiod_chip_get_line(chip, 27);
    if (!door_b_line) {
        fprintf(stderr, "Failed to get GPIO line 27: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Request lines as output
    if (gpiod_line_request_output(door_a_line, "door_a", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line 17 as output: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(door_b_line, "door_b", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line 27 as output: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Set default state (LOW to keep locks energized)
    set_gpio_line_value(door_a_line, 0);
    set_gpio_line_value(door_b_line, 0);

    // Main loop
    while (!exit_flag) {
        // Generate random code
        int generated_code;
        generate_code(&generated_code);
        printf("Generated code: %d\n", generated_code);

        // Read user input
        int entered_code;
        if (read_input(entered_code) == 0) {
            if (entered_code == generated_code) {
                // Log access
                time_t now = time(NULL);
                struct tm *tm_now = localtime(&now);
                char timestamp[20];
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_now);
                log_access(timestamp, generated_code);
                printf("Access granted.\n");
            } else {
                printf("Access denied.\n");
            }
        }

        // Wait for 1 second before next attempt
        sleep(1);
    }

    // Clean up GPIO
    set_gpio_line_value(door_a_line, 0);
    set_gpio_line_value(door_b_line, 0);

    gpiod_line_release(door_a_line);
    gpiod_line_release(door_b_line);
    gpiod_chip_close(chip);

    return 0;
}

