#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>
#include <errno.h>

#define I2C_BUS 1
#define I2C_ADDR 0x23
#define I2C_TIMEOUT 180000000 /* 180 ms in nanoseconds */
#define LOG_FILE "light_log.txt"
#define LOG_INTERVAL 5000000 /* 5 seconds in microseconds */

typedef struct {
    int i2c_fd;
    int running;
} app_state;

void handle_signal(int sig) {
    (void)sig;
    app_state *state = (app_state *)malloc(sizeof(app_state));
    state->running = 0;
    free(state);
}

void i2c_init(int *fd) {
