typedef enum {
    STATE_RUNNING,
    STATE_EXITING
} program_state;

program_state state = STATE_RUNNING;

void handle_signal(int signal) {
    state = STATE_EXITING;
}

void log_error(const char *message) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file) {
        fprintf(log_file, "%s\n", message);
        fclose(log_file);
    } else {
