void close_i2c(int fd) {
    if (fd >= 0) {
        close(fd);
    }
}

void stop_pwm(gpiod_line *led_line) {
    if (led_line) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_release(led_line);
    }
}

void cleanup() {
    close_i2c(-1);
    stop_pwm(NULL);
    printf("Cleanup complete.\n");
}

int init_i2c() {
    char bus_path[32];
    snprintf(bus_path, sizeof(bus_path), "/dev/i2c-%d", I2C_BUS);
    int fd = open(bus_path, O_RDWR);
    if (fd < 0) {
        log_error("Failed to open I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, I2C_ADDR) < 0) {
        log_error("Failed to set I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

int read_magnetometer(int fd, uint8_t *data) {
    if (fd < 0) {
        return -1;
    }

    if (read(fd, data, 6) != 6) {
        log_error("I2C read error");
        return -1;
    }

    return 0;
}

void setup_pwm() {
    struct gpiod_line *led_line = gpiod_line_get(LED_PIN, "gpio");
    if (!led_line) {
        log_error("Failed to get LED GPIO line");
        return;
    }

    if (gpiod_line_request_output(led_line, "led_pwm", 0, GPIOD_LINE_REQUEST_FLAG_ACTIVE_LOW) < 0) {
        log_error("Failed to request LED GPIO line");
        gpiod_line_put(led_line);
        return;
    }

    gpiod_line_set_config(led_line, GPIOD_LINE_CONFIG_FLAGS_OUTPUT_PWM);
    gpiod_line_set_pwm_config(led_line, 1000, 1000, 0); // 1000 Hz, 100% duty cycle
}

void update_pwm(uint8_t z_value) {
    int duty_cycle = (int)(z_value * 100.0 / 255.0);
    gpiod_line_set_pwm(led_line, duty_cycle);
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    int i2c_fd = -1;
    uint8_t mag_data[6];
    struct timespec ts = {0, 0};

    setup_pwm();

    while (state == STATE_RUNNING) {
        i2c_fd = init_i2c();
        if (i2c_fd < 0) {
            log_error("Failed to initialize I2C");
            usleep(100000); // 100 ms
            continue;
        }

        if (read_magnetometer(i2c_fd, mag_data) == 0) {
            // Extract Z-axis data (bytes 4 and 5)
            uint16_t z = (mag_data[4] << 8) | mag_data[5];
            // Convert to magnitude (absolute value)
            int z_magnitude = (int)z;

            // Update PWM based on Z magnitude
            update_pwm((uint8_t)z_magnitude);
        }

        close_i2c(i2c_fd);
        nanosleep(&ts, NULL);
    }

    cleanup();
    return 0;
}

