#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS 1
#define I2C_ADDR 0x1E
#define SAMPLE_COUNT 100
#define UPDATE_INTERVAL_MS 500
#define I2C_READ_SIZE 6

typedef struct {
    int x;
    int y;
    int z;
} RawData;

typedef struct {
    int x;
    int y;
    int z;
} Offset;

RawData samples[SAMPLE_COUNT];
Offset offset = {0, 0, 0};

int i2c_fd = -1;
volatile int running = 1;

void handle_signal(int sig) {
    running = 0;
}

void i2c_init() {
    char bus_path[32];
    snprintf(bus_path, sizeof(bus_path), "/dev/i2c-%d", I2C_BUS);

    i2c_fd = open(bus_path, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
}

void i2c_read(RawData *data) {
    uint8_t reg = 0x75; // Configuration register
    if (write(i2c_fd, &reg, 1) < 0) {
        perror("Failed to write to I2C register");
        return;
    }

    uint8_t buffer[6];
    if (read(i2c_fd, buffer, 6) < 0) {
        perror("Failed to read from I2C device");
        return;
    }

    data->x = (int16_t)(buffer[0] << 8 | buffer[1]);
    data->y = (int16_t)(buffer[2] << 8 | buffer[3]);
    data->z = (int16_t)(buffer[4] << 8 | buffer[5]);
}

void calculate_offset() {
    int sum_x = 0, sum_y = 0, sum_z = 0;
    for (int i = 0; i < SAMPLE_COUNT; i++) {
        sum_x += samples[i].x;
        sum_y += samples[i].y;
        sum_z += samples[i].z;
    }

    offset.x = sum_x / SAMPLE_COUNT;
    offset.y = sum_y / SAMPLE_COUNT;
    offset.z = sum_z / SAMPLE_COUNT;
}

void apply_offset(RawData *data) {
    data->x -= offset.x;
    data->y -= offset.y;
    data->z -= offset.z;
}

void cleanup() {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    printf("\n");
    exit(EXIT_SUCCESS);
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    i2c_init();

    for (int i = 0; i < SAMPLE_COUNT; i++) {
        RawData data;
        i2c_read(&data);
        samples[i] = data;
    }

    calculate_offset();

    while (running) {
        RawData data;
        i2c_read(&data);
        samples[(int)(rand() % SAMPLE_COUNT)] = data;

        apply_offset(&data);

        printf("X: %d, Y: %d, Z: %d\n", data.x, data.y, data.z);
        usleep(UPDATE_INTERVAL_MS * 1000);
    }

    cleanup();
    return 0;
}

