#include <gpiod.h>

#define LSM303D_I2C_ADDR_ACCEL 0x19
#define LSM303D_I2C_ADDR_MAGN 0x1E
#define LSM303D_WHO_AM_I 0x0F
#define LSM303D_WHO_AM_I_EXPECTED 0x33
#define LSM303D_CTRL_REG1_A 0x20
#define LSM303D_CTRL_REG4_A 0x23
#define LSM303D_CTRL_REG5_C 0x24
#define LSM303D_CTRL_REG6_C 0x25
#define LSM303D_INT1_CFG 0x2D
#define LSM303D_INT1_SRC 0x2E
#define LSM303D_INT1_THS 0x2F
#define LSM303D_OUT_X_L_A 0x28
#define LSM303D_OUT_X_H_A 0x29
#define LSM303D_OUT_Y_L_A 0x2A
#define LSM303D_OUT_Y_H_A 0x2B
#define LSM303D_OUT_Z_L_A 0x2C
#define LSM303D_OUT_Z_H_A 0x2D
#define LSM303D_ACCEL_SENSITIVITY 0.061f
#define LSM303D_THRESHOLD_MG 2000.0f
#define LSM303D_BUFFER_SIZE 64
#define LSM303D_BUFFER_WRAP 10

typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
    time_t timestamp;
} sample_t;

sample_t buffer[LSM303D_BUFFER_SIZE];
int buffer_head = 0;
int buffer_tail = 0;
int buffer_full = 0;
int i2c_fd = -1;
int int_gpio_line = -1;

void handle_sigint(int sig) {
    if (sig == SIGINT) {
        printf("\nGracefully shutting down...\n");
        // Disable accelerometer
        uint8_t ctrl_reg1 = 0x00;
        if (ioctl(i2c_fd, I2C_SLAVE, LSM303D_I2C_ADDR_ACCEL) < 0) {
            perror("Failed to set I2C slave address for accelerometer");
            exit(EXIT_FAILURE);
        }
        if (write(i2c_fd, &ctrl_reg1, 1) < 0) {
            perror("Failed to write to accelerometer control register");
        }
        // Close I2C
        if (close(i2c_fd) < 0) {
            perror("Failed to close I2C device");
        }
        // Release GPIO
        if (int_gpio_line != -1) {
            gpiod_line_release(int_gpio_line);
        }
        exit(EXIT_SUCCESS);
    }
}

int i2c_init() {
    char i2c_bus_path[] = "/dev/i2c-1";
    if ((i2c_fd = open(i2c_bus_path, O_RDWR)) < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, LSM303D_I2C_ADDR_ACCEL) < 0) {
        perror("Failed to set I2C slave address for accelerometer");
        close(i2c_fd);
        return -1;
    }

    uint8_t who_am_i;
    if (read(i2c_fd, &who_am_i, 1) < 0) {
        perror("Failed to read WHO_AM_I register");
        close(i2c_fd);
        return -1;
    }

    if (who_am_i != LSM303D_WHO_AM_I_EXPECTED) {
        fprintf(stderr, "Accelerometer WHO_AM_I register value is 0x%02X, expected 0x%02X\n",
