#include <signal.h>
#include <errno.h>
#include <time.h>
#include <gpiod.h>

#define SOL1_GPIO 17
#define SOL2_GPIO 27
#define DELAY_MS 500
#define GPIO_LINE_COUNT 2

typedef struct {
    struct gpiod_line *lines[GPIO_LINE_COUNT];
    int active_index;
} gpio_state_t;

static gpio_state_t gpio_state;

void handle_signal(int signum) {
    (void)signum;
    if (gpio_state.lines[0]) {
        gpiod_line_set_value(gpio_state.lines[0], 0);
        gpiod_line_set_value(gpio_state.lines[1], 0);
    }

    for (int i = 0; i < GPIO_LINE_COUNT; i++) {
        if (gpio_state.lines[i]) {
            gpiod_line_release(gpio_state.lines[i]);
        }
    }

    exit(EXIT_SUCCESS);
}

void setup_gpio() {
    struct gpiod_chip *chip;
    const char *chip_name = "gpiochip0";

    chip = gpiod_chip_open_by_name(chip_name);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < GPIO_LINE_COUNT; i++) {
        const int gpio = (i == 0) ? SOL1_GPIO : SOL2_GPIO;
        const char *label = (i == 0) ? "solenoid1" : "solenoid2";
        struct gpiod_line *line;

        line = gpiod_chip_get_line(chip, gpio);
        if (!line) {
            fprintf(stderr, "Failed to get line %d: %s\n", gpio, strerror(errno));
            gpiod_chip_close(chip);
            exit(EXIT_FAILURE);
        }

        if (gpiod_line_request_output(line, label, 0) < 0) {
            fprintf(stderr, "Failed to request line %d as output: %s\n", gpio, strerror(errno));
            gpiod_line_release(line);
            gpiod_chip_close(chip);
            exit(EXIT_FAILURE);
        }

        gpio_state.lines[i] = line;
    }

    // Set both lines to LOW initially
    for (int i = 0; i < GPIO_LINE_COUNT; i++) {
        if (gpiod_line_set_value(gpio_state.lines[i], 0) < 0) {
            fprintf(stderr, "Failed to set line %d to LOW: %s\n", (i == 0 ? SOL1_GPIO : SOL2_GPIO), strerror(errno));
            exit(EXIT_FAILURE);
        }
    }

    gpio_state.active_index = 0;
}

void toggle_solenoids() {
    // Set current active line to LOW
    if (gpiod_line_set_value(gpio_state.lines[gpio_state.active_index], 0) < 0) {
        fprintf(stderr, "Failed to set line %d to LOW: %s\n", (gpio_state.active_index == 0 ? SOL1_GPIO : SOL2_GPIO), strerror(errno));
        exit(EXIT_FAILURE);
    }

    // Toggle active index
    gpio_state.active_index = (gpio_state.active_index + 1) % GPIO_LINE_COUNT;

    // Set new active line to HIGH
    if (gpiod_line_set_value(gpio_state.lines[gpio_state.active_index], 1) < 0) {
        fprintf(stderr, "Failed to set line %d to HIGH: %s\n", (gpio_state.active_index == 0 ? SOL1_GPIO : SOL2_GPIO), strerror(errno));
        exit(EXIT_FAILURE);
    }
}

int main() {
    // Set up signal handling
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set up signal handler: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    setup_gpio();

    struct timespec sleep_time;
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = DELAY_MS * 1000000;

    while (1) {
        toggle_solenoids();
        if (nanosleep(&sleep_time, NULL) < 0 && errno != EINTR) {
            fprintf(stderr, "Failed to sleep: %s\n", strerror(errno));
            exit(EXIT_FAILURE);
        }
    }

    return 0;
}

