#include <gpiod.h>

#define GPIO_LOCK1_PIN 17
#define GPIO_LOCK2_PIN 27
#define EXPECTED_CODE "123456"
#define CODE_LENGTH 6
#define UART_PORT_PRIMARY "/dev/serial0"
#define UART_PORT_SECONDARY "/dev/serial1"
#define BAUD_RATE 9600
#define FRAME 8N1
#define READ_TIMEOUT 5000000  // 5 seconds in microseconds
#define RELAY_ON_DURATION 2000000  // 2 seconds in microseconds

typedef struct {
    int uart_fd_primary;
    int uart_fd_secondary;
    struct termios orig_termios_primary;
    struct termios orig_termios_secondary;
    gpiod_line *lock1_line;
    gpiod_line *lock2_line;
    int lock1_state;
    int lock2_state;
} app_state;

void handle_signal(int sig) {
    (void)sig;
    fprintf(stderr, "Caught signal, cleaning up...\n");
    exit(EXIT_FAILURE);
}

void setup_uart(int fd, struct termios *orig_termios) {
    struct termios new_termios;

    if (tcgetattr(fd, orig_termios) == -1) {
        fprintf(stderr, "Error getting terminal attributes: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    new_termios = *orig_termios;
    cfsetispeed(&new_termios, BAUD_RATE);
    cfsetospeed(&new_termios, BAUD_RATE);

    new_termios.c_cflag &= ~PARENB;    // No parity
    new_termios.c_cflag &= ~CSTOPB;    // 1 stop bit
    new_termios.c_cflag &= ~CSIZE;     // Clear character size mask
    new_termios.c_cflag |= CS8;        // 8 data bits

    new_termios.c_cflag |= (CLOCAL | CREAD); // No modem control, enable receiver

    new_termios.c_lflag &= ~(ICANON | ECHO | ECHOE | ISIG); // Raw input
    new_termios.c_iflag &= ~(IXON | IXOFF | IXANY); // No software flow control
    new_termios.c_oflag &= ~OPOST; // Raw output

    new_termios.c_cc[VMIN] = 0; // Non-blocking read
    new_termios.c_cc[VTIME] = 0; // No timeout

    if (tcsetattr(fd, TCSAFLUSH, &new_termios) == -1) {
        fprintf(stderr, "Error setting terminal attributes: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }
}

int read_uart(int fd, char *buffer, size_t size) {
    fd_set read_fds;
    struct timeval timeout;
    int bytes_read = 0;

    FD_ZERO(&read_fds);
    FD_SET(fd, &read_fds);

    timeout.tv_sec = 5;
    timeout.tv_usec = 0;

    if (select(fd + 1, &read_fds, NULL, NULL, &timeout) == -1) {
        fprintf(stderr, "Error in select: %s\n", strerror(errno));
        return -1;
    }

    if (FD_ISSET(fd, &read_fds)) {
        bytes_read = read(fd, buffer, size);
        if (bytes_read == -1) {
            fprintf(stderr, "Error reading from UART: %s\n", strerror(errno));
            return -1;
        }
    }

    return bytes_read;
}

void reset_uart_buffer(int fd) {
    int bytes_read;
    char buffer[1];

    while ((bytes_read = read(fd, buffer, 1)) > 0) {
