#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <fcntl.h>
#include <gpiod.h>
#include <time.h>

#define PIR_GPIO_LINE "gpio4"
#define RELAY_GPIO_LINE "gpio17"
#define POLL_INTERVAL_MS 50
#define RELAY_DURATION_MS 1000
#define MAX_PIR_HIGH_DURATION_MS 10000

typedef enum {
    STATE_IDLE,
    STATE_RELAY_ON,
    STATE_RELAY_OFF
} state_t;

typedef struct {
    gpiod_line *pir_line;
    gpiod_line *relay_line;
    int chip_fd;
    state_t state;
    struct timespec last_pir_high_time;
    int relay_on_count;
} app_context_t;

void log_message(const char *fmt, ...) {
    va_list args;
    va_start(args, fmt);
    vsyslog(LOG_INFO, fmt, args);
    va_end(args);
}

void log_error(const char *fmt, ...) {
    va_list args;
    va_start(args, fmt);
    vsyslog(LOG_ERR, fmt, args);
    va_end(args);
}

void handle_signal(int signum) {
    log_message("Received signal %d, initiating shutdown...", signum);
    exit(EXIT_SUCCESS);
}

void cleanup_gpio(app_context_t *ctx) {
    if (ctx->pir_line) {
        gpiod_line_release(ctx->pir_line);
    }
    if (ctx->relay_line) {
        gpiod_line_release(ctx->relay_line);
    }
    if (ctx->chip_fd >= 0) {
        close(ctx->chip_fd);
    }
    log_message("GPIO resources released.");
}

void set_relay_state(app_context_t *ctx, int state) {
    if (state == 1) {
        if (gpiod_line_set_value(ctx->relay_line, 1) < 0) {
            log_error("Failed to set relay line to HIGH.");
        } else {
            log_message("Relay activated.");
        }
    } else {
        if (gpiod_line_set_value(ctx->relay_line, 0) < 0) {
            log_error("Failed to set relay line to LOW.");
        } else {
            log_message("Relay deactivated.");
        }
    }
}

int main() {
    app_context_t ctx = {0};
    struct timespec poll_interval = {0, POLL_INTERVAL_MS * 1000000};
    struct timespec relay_duration = {0, RELAY_DURATION_MS * 1000000};
    struct timespec max_pir_high_duration = {0, MAX_PIR_HIGH_DURATION_MS * 1000000};

    // Initialize syslog
    openlog("pir_relay_monitor", LOG_PID | LOG_CONS, LOG_USER);

    // Set up signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Open GPIO chip
    ctx.chip_fd = gpiod_chip_open_by_name("gpiochip0");
    if (ctx.chip_fd < 0) {
        log_error("Failed to open GPIO chip.");
        exit(EXIT_FAILURE);
    }

    // Request PIR GPIO line
    ctx.pir_line = gpiod_chip_get_line(ctx.chip_fd, 4);
    if (!ctx.pir_line) {
        log_error("Failed to get PIR GPIO line.");
        cleanup_gpio(&ctx);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(ctx.pir_line, "pir_monitor", 0) < 0) {
        log_error("Failed to request PIR GPIO line.");
        cleanup_gpio(&ctx);
        exit(EXIT_FAILURE);
    }

    // Request Relay GPIO line
    ctx.relay_line = gpiod_chip_get_line(ctx.chip_fd, 17);
    if (!ctx.relay_line) {
        log_error("Failed to get Relay GPIO line.");
        cleanup_gpio(&ctx);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(ctx.relay_line, "relay_monitor", 0) < 0) {
        log_error("Failed to request Relay GPIO line.");
        cleanup_gpio(&ctx);
        exit(EXIT_FAILURE);
    }

    // Initialize state
    ctx.state = STATE_IDLE;
    ctx.relay_on_count = 0;

    // Main loop
    while (1) {
        // Poll PIR sensor
        int pir_value = gpiod_line_get_value(ctx.pir_line);
        if (pir_value < 0) {
            log_error("Failed to read PIR GPIO line.");
            cleanup_gpio(&ctx);
            exit(EXIT_FAILURE);
        }

        if (pir_value == 1) {
            // PIR is HIGH
            if (ctx.state == STATE_IDLE) {
                // First detection
                log_message("Motion detected.");
                ctx.state = STATE_RELAY_ON;
                set_relay_state(&ctx, 1);
                ctx.relay_on_count = 1;
                clock_gettime(CLOCK_MONOTONIC, &ctx.last_pir_high_time);
            } else if (ctx.state == STATE_RELAY_ON) {
                // Already on, just update last time
                clock_gettime(CLOCK_MONOTONIC, &ctx.last_pir_high_time);
            }
        } else {
            // PIR is LOW
            if (ctx.state == STATE_RELAY_ON) {
                // Relay is on, but PIR is now low
                log_message("Motion stopped.");
                set_relay_state(&ctx, 0);
                ctx.state = STATE_RELAY_OFF;
            }
        }

        // Check if PIR has been HIGH for more than 10 seconds
        struct timespec now;
        clock_gettime(CLOCK_MONOTONIC, &now);
        if (pir_value == 1 && ctx.state == STATE_RELAY_ON) {
            if (timespec_diff(&now, &ctx.last_pir_high_time) > max_pir_high_duration) {
                log_message("PIR signal remained HIGH for more than 10 seconds. Potential malfunction detected.");
                log_message("Triggering failsafe: de-energizing relay.");
                set_relay_state(&ctx, 0);
                ctx.state = STATE_RELAY_OFF;
                log_message("Failsafe triggered. Logging shutdown event.");
                log_message("System shutdown initiated.");
                cleanup_gpio(&ctx);
                exit(EXIT_SUCCESS);
            }
        }

        // Check if relay is on and time has elapsed
        if (ctx.state == STATE_RELAY_ON) {
            if (timespec_diff(&now, &ctx.last_pir_high_time) > relay_duration) {
                log_message("Relay duration expired. De-energizing relay.");
                set_relay_state(&ctx, 0);
                ctx.state = STATE_RELAY_OFF;
            }
        }

        // Sleep for poll interval
        nanosleep(&poll_interval, NULL);
    }

    // Cleanup on exit
    cleanup_gpio(&ctx);
    closelog();
    return 0;
}

// Helper function to calculate time difference between two timespecs
int timespec_diff(struct timespec *t1, struct timespec *t2) {
    long sec_diff = t1->tv_sec - t2->tv_sec;
    long nsec_diff = t1->tv_nsec - t2->tv_nsec;
    if (nsec_diff < 0) {
        sec_diff--;
        nsec_diff += 1000000000;
    }
    return (sec_diff * 1000000000 + nsec_diff);
}

