    accel_data_t buffer[MPU6050_BUFFER_SIZE];
    int head;
    int tail;
    int full;
} circular_buffer_t;

circular_buffer_t buffer;
int i2c_fd = -1;
int timer_fd = -1;
int sigint_received = 0;
int sigterm_received = 0;
int latest_sample_index = 0;

void handle_signal(int signo) {
    sigint_received = (signo == SIGINT);
    sigterm_received = (signo == SIGTERM);
}

void init_i2c() {
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    uint8_t wake_up_config = 0x00;
    if (write(i2c_fd, &wake_up_config, 1) < 0) {
        perror("Failed to write wake-up configuration");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    uint8_t sample_rate = MPU6050_ACCEL_SAMPLE_RATE;
    if (write(i2c_fd, &sample_rate, 1) < 0) {
        perror("Failed to set sample rate");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    uint8_t accel_config = MPU6050_ACCEL_FS_SEL;
    if (write(i2c_fd, &accel_config, 1) < 0) {
        perror("Failed to set accelerometer full-scale range");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
}

void init_timer() {
    struct itimerspec timer_spec;
    struct sigevent sigev;

    sigev.sigev_notify = SIGEV_SIGNAL;
    sigev.sigev_signo = SIGUSR1;
    sigev.sigev_value.sival_ptr = NULL;

    if (timer_create(CLOCK_REALTIME, &sigev, &timer_fd) < 0) {
        perror("Failed to create timer");
        exit(EXIT_FAILURE);
    }

    timer_spec.it_interval.tv_sec = 0;
    timer_spec.it_interval.tv_nsec = 100000000; // 100ms for 100Hz
    timer_spec.it_value.tv_sec = 0;
    timer_spec.it_value.tv_nsec = 100000000;

    if (timer_settime(timer_fd, 0, &timer_spec, NULL) < 0) {
        perror("Failed to set timer");
        timer_delete(timer_fd);
        exit(EXIT_FAILURE);
    }
}

void init_buffer() {
    buffer.head = 0;
    buffer.tail = 0;
    buffer.full = 0;
}

void read_accel_data(accel_data_t *data) {
    uint8_t reg = MPU6050_ACCEL_XOUT_H;
    if (write(i2c_fd, &reg, 1) < 0) {
        perror("Failed to write register address");
        exit(EXIT_FAILURE);
    }

    uint8_t buffer[MPU6050_ACCEL_DATA_SIZE];
    if (read(i2c_fd, buffer, MPU6050_ACCEL_DATA_SIZE) < 0) {
        perror("Failed to read accelerometer data");
        exit(EXIT_FAILURE);
    }

    data->x = (int16_t)(buffer[0] << 8 | buffer[1]);
    data->y = (int16_t)(buffer[2] << 8 | buffer[3]);
    data->z = (int16_t)(buffer[4] << 8 | buffer[5]);
}

void write_latest_sample(int index) {
    char path[256];
    snprintf(path, sizeof(path), "/sys/kernel/mpu6050_accel/latest");
    FILE *fp = fopen(path, "w");
    if (!fp) {
        perror("Failed to open latest sample file");
        return;
    }

    accel_data_t *data = &buffer.buffer[index];
    fprintf(fp, "%d %d %d\n", data->x, data->y, data->z);
    fclose(fp);
}

void timer_callback() {
    if (sigint_received || sigterm_received) {
        return;
    }

    read_accel_data(&buffer.buffer[buffer.head]);
    buffer.head = (buffer.head + 1) % MPU6050_BUFFER_SIZE;
    buffer.full = (buffer.head == buffer.tail);

    if (buffer.full) {
        buffer.tail = (buffer.tail + 1) % MPU6050_BUFFER_SIZE;
    }

    latest_sample_index = buffer.head;
    write_latest_sample(buffer.head);
}

void cleanup() {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }

    if (timer_fd >= 0) {
        timer_delete(timer_fd);
    }

    if (sigint_received || sigterm_received) {
        printf("Received signal, cleaning up...\n");
    }
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    init_buffer();
    init_i2c();
    init_timer();

    while (!sigint_received && !sigterm_received) {
        pause();
    }

    cleanup();
    return 0;
}
