#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/gpio.h>
#include <time.h>

#define GPIO_CHIP "gpiochip0"
#define RELAY_COUNT 4
#define RELAY_GPIO {18, 23, 24, 25}
#define INTERVAL_SECONDS {2, 3, 5, 7}

typedef struct {
    int fd;
    struct gpio_line *lines[RELAY_COUNT];
    struct timespec last_toggle_time[RELAY_COUNT];
    int running;
} relay_state;

void handle_signal(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        printf("Received signal, shutting down...\n");
        exit(EXIT_SUCCESS);
    }
}

void init_gpio(relay_state *state) {
    state->running = 1;
    state->fd = open(GPIO_CHIP, O_RDWR);
    if (state->fd < 0) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < RELAY_COUNT; i++) {
        state->lines[i] = gpio_line_get(state->fd, RELAY_GPIO[i]);
        if (!state->lines[i]) {
            perror("Failed to get GPIO line");
            exit(EXIT_FAILURE);
        }

        if (gpio_line_request_output(state->lines[i], "relay", GPIO_LINE_FLAG_ACTIVE_LOW)) {
            perror("Failed to request GPIO line for output");
            exit(EXIT_FAILURE);
        }

        gpio_line_set_value(state->lines[i], 1); // Turn off relays initially
        state->last_toggle_time[i] = (struct timespec){0, 0};
    }
}

void toggle_relay(relay_state *state, int index) {
    if (!state->running) return;

    int current_value = gpio_line_get_value(state->lines[index]);
    gpio_line_set_value(state->lines[index], 1 - current_value);

    struct timespec now;
    clock_gettime(CLOCK_MONOTONIC, &now);
    state->last_toggle_time[index] = now;
}

void check_intervals(relay_state *state) {
    struct timespec now;
    clock_gettime(CLOCK_MONOTONIC, &now);

    for (int i = 0; i < RELAY_COUNT; i++) {
        struct timespec elapsed;
        timespec_sub(&now, &state->last_toggle_time[i], &elapsed);

        if (elapsed.tv_sec >= INTERVAL_SECONDS[i]) {
            toggle_relay(state, i);
        }
    }
}

void timespec_sub(const struct timespec *a, const struct timespec *b, struct timespec *result) {
    result->tv_sec = a->tv_sec - b->tv_sec;
    result->tv_nsec = a->tv_nsec - b->tv_nsec;
    if (result->tv_nsec < 0) {
        result->tv_sec--;
        result->tv_nsec += 1000000000;
    }
}

void cleanup_gpio(relay_state *state) {
    if (state->running) {
        for (int i = 0; i < RELAY_COUNT; i++) {
            if (state->lines[i]) {
                gpio_line_release(state->lines[i]);
                gpio_line_put(state->lines[i]);
            }
        }
        close(state->fd);
    }
}

int main() {
    relay_state state;
    init_gpio(&state);

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (state.running) {
        check_intervals(&state);
        usleep(100000); // 100ms check interval
    }

    cleanup_gpio(&state);
    return 0;
}

