#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/gpio.h>
#include <time.h>

#define GPIO_SOUND_PIN 17
#define GPIO_RELAY_PIN 27
#define POLLING_INTERVAL_MS 100
#define RELAY_ACTIVE_TIME_S 3
#define LOG_FILE "alarm_log.txt"

typedef enum {
    STATE_IDLE,
    STATE_ACTIVE
} state_t;

typedef struct {
    int gpio_fd;
    int relay_fd;
    state_t state;
    int alarm_count;
    FILE *log_file;
    int shutdown_requested;
} app_context_t;

void handle_signal(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        printf("Shutting down...\n");
        signal(signum, SIG_IGN); // Prevent recursive signals
    }
}

void init_gpio(app_context_t *ctx) {
    ctx->gpio_fd = open("/dev/gpiochip0", O_RDWR);
    if (ctx->gpio_fd < 0) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    if (ioctl(ctx->gpio_fd, GPIO_GET_LINEHANDLE_IOCTL, &ctx->gpio_fd) < 0) {
        perror("Failed to get line handle for GPIO");
        close(ctx->gpio_fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(ctx->gpio_fd, GPIO_GET_LINEINFO_IOCTL, &ctx->gpio_fd) < 0) {
        perror("Failed to get line info for GPIO");
        close(ctx->gpio_fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(ctx->gpio_fd, GPIO_LINE_SET_FLAGS, GPIO_LINE_FLAG_BIAS_PULL_UP) < 0) {
        perror("Failed to set pull-up bias for GPIO");
        close(ctx->gpio_fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(ctx->gpio_fd, GPIO_LINE_SET_FLAGS, GPIO_LINE_FLAG_INPUT) < 0) {
        perror("Failed to set input mode for GPIO");
        close(ctx->gpio_fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(ctx->gpio_fd, GPIO_LINE_GET_VALUES_IOCTL, &ctx->gpio_fd) < 0) {
        perror("Failed to get initial GPIO value");
        close(ctx->gpio_fd);
        exit(EXIT_FAILURE);
    }
}

void init_relay(app_context_t *ctx) {
    ctx->relay_fd = open("/dev/gpiochip0", O_RDWR);
    if (ctx->relay_fd < 0) {
        perror("Failed to open GPIO chip for relay");
        exit(EXIT_FAILURE);
    }

    if (ioctl(ctx->relay_fd, GPIO_GET_LINEHANDLE_IOCTL, &ctx->relay_fd) < 0) {
        perror("Failed to get line handle for relay GPIO");
        close(ctx->relay_fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(ctx->relay_fd, GPIO_GET_LINEINFO_IOCTL, &ctx->relay_fd) < 0) {
        perror("Failed to get line info for relay GPIO");
        close(ctx->relay_fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(ctx->relay_fd, GPIO_LINE_SET_FLAGS, GPIO_LINE_FLAG_OUTPUT) < 0) {
        perror("Failed to set output mode for relay GPIO");
        close(ctx->relay_fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(ctx->relay_fd, GPIO_LINE_SET_VALUES_IOCTL, 0) < 0) {
        perror("Failed to set initial relay state");
        close(ctx->relay_fd);
        exit(EXIT_FAILURE);
    }
}

void log_event(app_context_t *ctx, const char *message) {
    if (ctx->log_file == NULL) {
        ctx->log_file = fopen(LOG_FILE, "a");
        if (ctx->log_file == NULL) {
            perror("Failed to open log file");
            exit(EXIT_FAILURE);
        }
    }

    time_t now = time(NULL);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
    fprintf(ctx->log_file, "%s - %s\n", timestamp, message);
    fflush(ctx->log_file);
}

void shutdown_app(app_context_t *ctx) {
    if (ctx->state == STATE_ACTIVE) {
        log_event(ctx, "Relay shutdown initiated");
        if (ioctl(ctx->relay_fd, GPIO_LINE_SET_VALUES_IOCTL, 0) < 0) {
            perror("Failed to turn off relay");
        }
    }

    if (ctx->log_file != NULL) {
        fclose(ctx->log_file);
    }

    if (ctx->gpio_fd > 0) {
        close(ctx->gpio_fd);
    }

    if (ctx->relay_fd > 0) {
        close(ctx->relay_fd);
    }

    printf("Application shutdown complete.\n");
    exit(EXIT_SUCCESS);
}

void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        shutdown_app(NULL);
    }
}

void monitor_sound_sensor(app_context_t *ctx) {
    int last_value = 0;
    int current_value = 0;
    int debounce_count = 0;

    while (!ctx->shutdown_requested) {
        if (ioctl(ctx->gpio_fd, GPIO_LINE_GET_VALUES_IOCTL, &current_value) < 0) {
            perror("Failed to read GPIO value");
            continue;
        }

        if (current_value != last_value) {
            last_value = current_value;
            debounce_count = 0;
        } else {
            debounce_count++;
            if (debounce_count > 10) {
                debounce_count = 0;
            }
        }

        if (current_value == 1 && debounce_count == 0) {
            if (ctx->state == STATE_IDLE) {
                log_event(ctx, "Sound detected, activating relay");
                ctx->state = STATE_ACTIVE;
                if (ioctl(ctx->relay_fd, GPIO_LINE_SET_VALUES_IOCTL, 1) < 0) {
                    perror("Failed to activate relay");
                }
                usleep(RELAY_ACTIVE_TIME_S * 1000000);
                if (ioctl(ctx->relay_fd, GPIO_LINE_SET_VALUES_IOCTL, 0) < 0) {
                    perror("Failed to deactivate relay");
                }
                ctx->state = STATE_IDLE;
            }
        }

        usleep(POLLING_INTERVAL_MS * 1000);
    }
}

int main() {
    app_context_t ctx = {
        .gpio_fd = -1,
        .relay_fd = -1,
        .state = STATE_IDLE,
        .alarm_count = 0,
        .log_file = NULL,
        .shutdown_requested = 0
    };

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (init_gpio(&ctx) < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return EXIT_FAILURE;
    }

    if (init_relay(&ctx) < 0) {
        fprintf(stderr, "Failed to initialize relay GPIO\n");
        return EXIT_FAILURE;
    }

    log_event(&ctx, "Application started");

    monitor_sound_sensor(&ctx);

    shutdown_app(&ctx);

    return EXIT_SUCCESS;
}

