        .gpio_fd = -1,
        .relay_fd = -1,
        .state = STATE_IDLE,
        .alarm_count = 0,
        .log_file = NULL,
        .shutdown_requested = 0
    };

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (init_gpio(&ctx) < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return EXIT_FAILURE;
    }

    if (init_relay(&ctx) < 0) {
        fprintf(stderr, "Failed to initialize relay GPIO\n");
        return EXIT_FAILURE;
    }

    log_event(&ctx, "Application started");

    monitor_sound_sensor(&ctx);

    shutdown_app(&ctx);

    return EXIT_SUCCESS;
}
