#define MPU6050_GYRO_CONFIG 0x1B
#define MPU6050_SMPLRT_DIV 0x15
#define MPU6050_DLPF_CONFIG 0x1A
#define MPU6050_CONFIG 0x1A
#define MPU6050_SAMPLE_RATE 100
#define MPU6050_SAMPLE_RATE_DIV 10
#define MPU6050_GYRO_SCALE 131.0f
#define MPU6050_THRESHOLD 50.0f
#define BUFFER_SIZE 100

typedef struct {
    float x;
    float y;
    float z;
} AngularVelocitySample;

typedef struct {
    AngularVelocitySample buffer[BUFFER_SIZE];
    int head;
    int tail;
    int full;
} CircularBuffer;

void init_buffer(CircularBuffer *buffer) {
    buffer->head = 0;
    buffer->tail = 0;
    buffer->full = 0;
}

void buffer_push(CircularBuffer *buffer, AngularVelocitySample sample) {
    if (buffer->full) {
        buffer->tail = (buffer->tail + 1) % BUFFER_SIZE;
    }
    buffer->buffer[buffer->head] = sample;
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    buffer->full = (buffer->head == buffer->tail);
}

void buffer_pop(CircularBuffer *buffer, AngularVelocitySample *sample) {
    if (buffer->full) {
        *sample = buffer->buffer[buffer->tail];
        buffer->tail = (buffer->tail + 1) % BUFFER_SIZE;
        buffer->full = (buffer->head == buffer->tail);
    }
}

void buffer_clear(CircularBuffer *buffer) {
    buffer->head = 0;
    buffer->tail = 0;
    buffer->full = 0;
}

void handle_signal(int sig) {
    printf("\nReceived signal %d, exiting...\n", sig);
    exit(EXIT_SUCCESS);
}

void read_gyro_data(int fd, AngularVelocitySample *sample) {
    uint8_t buffer[6];
    int bytes_read;

    if ((bytes_read = read(fd, buffer, 6)) != 6) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    sample->x = (int16_t)(buffer[0] << 8 | buffer[1]) * MPU6050_GYRO_SCALE;
    sample->y = (int16_t)(buffer[2] << 8 | buffer[3]) * MPU6050_GYRO_SCALE;
    sample->z = (int16_t)(buffer[4] << 8 | buffer[5]) * MPU6050_GYRO_SCALE;
}

float calculate_magnitude(AngularVelocitySample sample) {
    return sqrtf(sample.x * sample.x + sample.y * sample.y + sample.z * sample.z);
}

