    uint8_t data[2];

    // Wake up the MPU-6050
    data[0] = MPU6050_PWR_MGMT_1;
    data[1] = 0x00; // Wake up
    if (write(fd, data, 2) != 2) {
        fprintf(stderr, "Failed to wake up MPU-6050: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

