    data[0] = MPU6050_GYRO_CONFIG;
    data[1] = 0x18; // 2000 degrees/s
    if (write(fd, data, 2) != 2) {
        fprintf(stderr, "Failed to set gyroscope range: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    // Set DLPF bandwidth to 42 Hz
    data[0] = MPU6050_DLPF_CONFIG;
    data[1] = 0x0C; // 42 Hz
    if (write(fd, data, 2) != 2) {
        fprintf(stderr, "Failed to set DLPF bandwidth: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }
}

void user_callback(AngularVelocitySample sample) {
    printf("Angular velocity magnitude exceeds threshold: %.2f deg/s\n", calculate_magnitude(sample));
}

int main() {
    int i2c_fd;
    int result;
    AngularVelocitySample sample;
    CircularBuffer buffer;
    struct sigaction sa;

    // Initialize buffer
    init_buffer(&buffer);

    // Set up signal handler
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to set up signal handler: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    // Open I2C device
    i2c_fd = open(I2C_BUS, O_RDWR | O_NOCTTY | O_CLOEXEC);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Setup MPU-6050
    setup_mpu6050(i2c_fd);

    // Main loop
    while (1) {
        read_gyro_data(i2c_fd, &sample);
        buffer_push(&buffer, sample);

        if (buffer.full) {
            buffer_pop(&buffer, &sample);
            if (calculate_magnitude(sample) > MPU6050_THRESHOLD) {
                user_callback(sample);
            }
        }

        usleep(10000); // 10 ms delay for 100 Hz sampling
    }

    // Clean up
    close(i2c_fd);
    return 0;
}

