        int ret = select(fd + 1, &read_fds, NULL, NULL, &tv);
        if (ret < 0) {
            perror("select failed");
            return -1;
        } else if (ret == 0) {
            fprintf(stderr, "Read timeout\n");
            return -1;
        }

        ssize_t n = read(fd, response + bytes_read, len - bytes_read);
        if (n < 0) {
            perror("Failed to read from UART");
            return -1;
        } else if (n == 0) {
            fprintf(stderr, "No data received\n");
            return -1;
        }

        bytes_read += n;
        retry++;
    }

    if (bytes_read != len) {
        fprintf(stderr, "Incomplete response received\n");
        return -1;
    }

    return 0;
}

int calculate_checksum(const unsigned char *response) {
    int checksum = 0;
    for (int i = 0; i < CMD_BYTES - 1; i++) {
        checksum += response[i];
    }
    return checksum;
}

void log_error(FILE *error_log, const char *message) {
    struct timeval tv;
    gettimeofday(&tv, NULL);
    long microseconds = tv.tv_usec;
    long seconds = tv.tv_sec;
    time_t t = seconds;
    struct tm *tm = localtime(&t);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(error_log, "[%s.%06ld] %s\n", timestamp, microseconds, message);
    fflush(error_log);
}

void log_data(FILE *log_file, const char *timestamp, int ppm, int error) {
    struct json_object *json = json_object_new_object();
    json_object* timestamp_obj = json_object_new_string(timestamp);
    json_object* ppm_obj = json_object_new_int(ppm);
    json_object* error_obj = json_object_new_boolean(error);

    json_object_object_add(json, "timestamp", timestamp_obj);
    json_object_object_add(json, "ppm", ppm_obj);
    json_object_object_add(json, "error", error_obj);

    char *json_str = json_object_to_json_string(json);
    fprintf(log_file, "%s\n", json_str);
    fflush(log_file);
    json_object_put(json);
    free(json_str);
}

int main() {
    FILE *log_file = fopen(LOG_FILE, "a");
    FILE *error_log = fopen(ERROR_LOG, "a");

    if (!log_file || !error_log) {
        perror("Failed to open log files");
        return EXIT_FAILURE;
    }

    if (open_uart(UART_DEVICE) < 0) {
        fclose(log_file);
        fclose(error_log);
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    unsigned char cmd[CMD_BYTES] = {
        CMD_START, CMD_BIT, CMD_TYPE, CMD_ID, CMD_LENGTH, CMD_CHECKSUM, CMD_END, CMD_END, CMD_END
    };

    struct timeval last_sample_time;
    gettimeofday(&last_sample_time, NULL);

    while (1) {
        struct timeval current_time;
        gettimeofday(&current_time, NULL);

        if (current_time.tv_sec - last_sample_time.tv_sec >= SAMPLE_INTERVAL_MS / 1000) {
            if (send_command(serial.fd, cmd, CMD_BYTES) < 0) {
                log_error(error_log, "Failed to send command");
                continue;
            }

            unsigned char response[CMD_BYTES];
            if (read_response(serial.fd, response, CMD_BYTES, READ_TIMEOUT_MS) < 0) {
                log_error(error_log, "Failed to read response");
                continue;
            }

            int checksum = calculate_checksum(response);
            if (checksum != response[CMD_BYTES - 1]) {
                log_error(error_log, "Checksum mismatch");
                continue;
            }

            int ppm = (response[2] << 8) | response[3];
            char timestamp[30];
            struct tm *tm = localtime(&current_time.tv_sec);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
            log_data(log_file, timestamp, ppm, 0);
            printf("{\"timestamp\":\"%s\",\"ppm\":%d,\"error\":false}\n", timestamp, ppm);
            fflush(stdout);

            gettimeofday(&last_sample_time, NULL);
        }

        usleep(100000); // 100ms delay to avoid busy waiting
    }

    close_uart(&serial);
    close_logs(log_file, error_log);
    return EXIT_SUCCESS;
}
