#include <math.h>
#include <time.h>

#define I2C_BUS 1
#define I2C_ADDR 0x1E
#define HMC5883L_REGISTER_CONFIG_A 0x00
#define HMC5883L_REGISTER_CONFIG_B 0x01
#define HMC5883L_REGISTER_MODE 0x02
#define HMC5883L_REGISTER_X_MSB 0x03
#define HMC5883L_REGISTER_X_LSB 0x04
#define HMC5883L_REGISTER_Y_MSB 0x05
#define HMC5883L_REGISTER_Y_LSB 0x06
#define HMC5883L_REGISTER_Z_MSB 0x07
#define HMC5883L_REGISTER_Z_LSB 0x08

#define CIRCULAR_BUFFER_SIZE 100
#define TARGET_HEADING 90.0
#define HEADING_THRESHOLD 10.0
#define SAMPLE_INTERVAL_MS 100

typedef struct {
    double heading[CIRCULAR_BUFFER_SIZE];
    int head;
    int tail;
    int full;
} CircularBuffer;

void init_i2c(int *fd) {
    char filename[256];
    snprintf(filename, sizeof(filename), "/dev/i2c-%d", I2C_BUS);
    *fd = open(filename, O_RDWR);
    if (*fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    if (ioctl(*fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(*fd);
        exit(EXIT_FAILURE);
    }
}

void read_magnetometer(int fd, int *x, int *y, int *z) {
    char buffer[3];
    int ret;

    buffer[0] = HMC5883L_REGISTER_X_MSB;
    if (write(fd, buffer, 1) != 1) {
        perror("Failed to write to I2C device");
        return;
    }

    if (read(fd, buffer, 3) != 3) {
        perror("Failed to read from I2C device");
        return;
    }

    *x = (buffer[0] << 8) | buffer[1];
    *y = (buffer[2] << 8) | buffer[3];
    *z = (buffer[4] << 8) | buffer[5];
}

void init_magnetometer(int fd) {
    char config_a[2] = {0x70, 0x70}; // 1.0 gauss range, 0.78 ms per sample
    if (write(fd, config_a, 2) != 2) {
        perror("Failed to write config A");
        exit(EXIT_FAILURE);
    }

    char config_b[2] = {0x00, 0x00}; // 8 samples averaged
    if (write(fd, config_b, 2) != 2) {
        perror("Failed to write config B");
        exit(EXIT_FAILURE);
    }

    char mode[2] = {0x00, 0x00}; // Continuous measurement mode
    if (write(fd, mode, 2) != 2) {
        perror("Failed to set measurement mode");
        exit(EXIT_FAILURE);
    }
}

double calculate_heading(int x, int y) {
    double heading_rad = atan2((double)y, (double)x);
    double heading_deg = (heading_rad * 180.0) / M_PI;

    if (heading_deg < 0) {
        heading_deg += 360.0;
    }

    return heading_deg;
}

void init_circular_buffer(CircularBuffer *buffer) {
    buffer->head = 0;
    buffer->tail = 0;
    buffer->full = 0;
}

void add_to_buffer(CircularBuffer *buffer, double value) {
    if (buffer->full) {
        buffer->tail = (buffer->tail + 1) % CIRCULAR_BUFFER_SIZE;
    } else {
        buffer->full = 1;
    }
    buffer->heading[buffer->head] = value;
    buffer->head = (buffer->head + 1) % CIRCULAR_BUFFER_SIZE;
}

double get_average_heading(CircularBuffer *buffer) {
    double sum = 0.0;
    int count = 0;

    if (buffer->full) {
        count = CIRCULAR_BUFFER_SIZE;
    } else {
        count = buffer->head - buffer->tail;
    }

    for (int i = buffer->tail; i < buffer->head; i++) {
        sum += buffer->heading[i];
    }

    return sum / count;
}

void init_gpio(gpiod_line *gpio_line) {
    struct gpiod_chip *chip;
    int ret;

    chip = gpiod_chip_open("/dev/gpiochip1");
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    *gpio_line = gpiod_line_get(chip, 17); // BCM 17
    if (!gpio_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(*gpio_line, "heading_alert", 0)) {
        perror("Failed to request GPIO line");
        gpiod_line_release(*gpio_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }
}

void set_gpio_state(gpiod_line gpio_line, int state) {
    if (gpiod_line_set_value(gpio_line, state)) {
        perror("Failed to set GPIO value");
    }
}

void handle_signal(int sig) {
    printf("\nCaught signal %d, exiting...\n", sig);
    exit(EXIT_SUCCESS);
}

void cleanup(int fd, gpiod_line gpio_line) {
    if (fd >= 0) {
        close(fd);
    }
    if (gpio_line) {
        gpiod_line_release(gpio_line);
    }
}

int main() {
    int i2c_fd = -1;
    CircularBuffer buffer;
    init_circular_buffer(&buffer);
    gpiod_line gpio_line = NULL;

    init_i2c(&i2c_fd);
    init_magnetometer(i2c_fd);
    init_gpio(&gpio_line);

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    double x, y, z;
    double heading;
    double average_heading;
    int count = 0;

    while (1) {
        // Read magnetometer data
        read_magnetometer(i2c_fd, &x, &y, &z);

        // Calculate heading
        heading = calculate_heading(x, y);

        // Apply hard-iron compensation
        heading -= 100.0; // X offset
        heading += 50.0;  // Y offset

        // Add to buffer
        add_to_buffer(&buffer, heading);

        // Calculate average heading
        average_heading = get_average_heading(&buffer);

        // Check if heading deviates from target
        if (fabs(average_heading - TARGET_HEADING) > HEADING_THRESHOLD) {
            set_gpio_state(gpio_line, 1);
        } else {
            set_gpio_state(gpio_line, 0);
        }

        // Sleep for 100ms
        usleep(SAMPLE_INTERVAL_MS * 1000);

        count++;
    }

    cleanup(i2c_fd, gpio_line);
    return 0;
}

