#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <gpiod.h>
#include <signal.h>

#define I2C_BUS 1
#define I2C_ADDR 0x23
#define I2C_FILE "/dev/i2c-%d"  // Format with bus number
#define RELAY_RED GPIO_LINE_17
#define RELAY_GREEN GPIO_LINE_27
#define RELAY_BLUE GPIO_LINE_22
#define LOG_FILE "lighting_log.txt"
#define CONVERSION_DELAY_MS 120
#define LOG_INTERVAL_MS 1000

typedef enum {
    LIGHT_LEVEL_LOW,
    LIGHT_LEVEL_MEDIUM_LOW,
    LIGHT_LEVEL_MEDIUM_HIGH,
    LIGHT_LEVEL_HIGH
} LightLevel;

typedef struct {
    int i2c_fd;
    struct gpiod_line *red_line;
    struct gpiod_line *green_line;
    struct gpiod_line *blue_line;
    FILE *log_file;
    int running;
} AppState;

void handle_signal(int sig) {
    AppState *state = (AppState *)malloc(sizeof(AppState));
    if (state) {
        state->running = 0;
    }
}

void close_resources(AppState *state) {
    if (state->log_file) {
        fclose(state->log_file);
    }

    if (state->i2c_fd >= 0) {
        close(state->i2c_fd);
    }

    if (state->red_line) {
        gpiod_line_release(state->red_line);
    }

    if (state->green_line) {
        gpiod_line_release(state->green_line);
    }

    if (state->blue_line) {
        gpiod_line_release(state->blue_line);
    }
}

int init_i2c(AppState *state) {
    char i2c_path[32];
    snprintf(i2c_path, sizeof(i2c_path), I2C_FILE, I2C_BUS);

    state->i2c_fd = open(i2c_path, O_RDWR);
    if (state->i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    if (ioctl(state->i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(state->i2c_fd);
        return -1;
    }

    return 0;
}

int read_lux(AppState *state) {
    unsigned char cmd[2] = {0x13, 0x00};  // Continuous measurement mode
    if (write(state->i2c_fd, cmd, 2) != 2) {
        perror("I2C write error");
        return -1;
    }

    usleep(CONVERSION_DELAY_MS * 1000);

    unsigned char data[2];
    if (read(state->i2c_fd, data, 2) != 2) {
        perror("I2C read error");
        return -1;
    }

    int lux = (data[0] << 8) | data[1];
    return lux;
}

void set_rgb_relays(AppState *state, LightLevel level) {
    gpiod_line_set_value(state->red_line, 0);
    gpiod_line_set_value(state->green_line, 0);
    gpiod_line_set_value(state->blue_line, 0);

    switch (level) {
        case LIGHT_LEVEL_LOW:
            gpiod_line_set_value(state->red_line, 1);
            break;
        case LIGHT_LEVEL_MEDIUM_LOW:
            gpiod_line_set_value(state->green_line, 1);
            break;
        case LIGHT_LEVEL_MEDIUM_HIGH:
            gpiod_line_set_value(state->blue_line, 1);
            break;
        case LIGHT_LEVEL_HIGH:
            gpiod_line_set_value(state->red_line, 1);
            gpiod_line_set_value(state->green_line, 1);
            gpiod_line_set_value(state->blue_line, 1);
            break;
    }
}

void log_lighting(AppState *state, int lux) {
    time_t now = time(NULL);
    struct tm *tm_now = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_now);

    LightLevel level;
    if (lux < 50) {
        level = LIGHT_LEVEL_LOW;
    } else if (lux < 150) {
        level = LIGHT_LEVEL_MEDIUM_LOW;
    } else if (lux < 300) {
        level = LIGHT_LEVEL_MEDIUM_HIGH;
    } else {
        level = LIGHT_LEVEL_HIGH;
    }

    set_rgb_relays(state, level);

    fprintf(state->log_file, "%s, %d lux\n", timestamp, lux);
    fflush(state->log_file);
}

int init_gpio(AppState *state) {
    struct gpiod_chip *chip;
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    state->red_line = gpiod_line_get(chip, RELAY_RED);
    if (!state->red_line) {
        perror("Failed to get red GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    state->green_line = gpiod_line_get(chip, RELAY_GREEN);
    if (!state->green_line) {
        perror("Failed to get green GPIO line");
        gpiod_line_release(state->red_line);
        gpiod_chip_close(chip);
        return -1;
    }

    state->blue_line = gpiod_line_get(chip, RELAY_BLUE);
    if (!state->blue_line) {
        perror("Failed to get blue GPIO line");
        gpiod_line_release(state->red_line);
        gpiod_line_release(state->green_line);
        gpiod_chip_close(chip);
        return -1;
    }

    gpiod_line_request_output(state->red_line, "red-relay", 0);
    gpiod_line_request_output(state->green_line, "green-relay", 0);
    gpiod_line_request_output(state->blue_line, "blue-relay", 0);

    gpiod_chip_close(chip);
    return 0;
}

int init_log_file(AppState *state) {
    state->log_file = fopen(LOG_FILE, "a");
    if (!state->log_file) {
        perror("Failed to open log file");
        return -1;
    }
    return 0;
}

int main() {
    AppState state = {0};

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if (init_gpio(&state) != 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    if (init_i2c(&state) != 0) {
        fprintf(stderr, "Failed to initialize I2C\n");
        close_resources(&state);
        return 1;
    }

    if (init_log_file(&state) != 0) {
        fprintf(stderr, "Failed to initialize log file\n");
        close_resources(&state);
        return 1;
    }

    state.running = 1;
