    } else if (distance_a >= DISTANCE_THRESHOLD && distance_b >= DISTANCE_THRESHOLD) {
        // Both motors backward
        set_motor_direction(controller, 0, 0);
        duty_cycle = (distance_a > distance_b) ? (PWM_RANGE - distance_a) : (PWM_RANGE - distance_b);
    } else {
        // One motor forward, one backward (not implemented in this example)
        set_motor_direction(controller, 1, 0);
        duty_cycle = PWM_RANGE / 2;
    }

    if (duty_cycle > PWM_RANGE) {
        duty_cycle = PWM_RANGE;
    }

    set_pwm_duty_cycle(controller->pwm_fd_in2, duty_cycle);
    set_pwm_duty_cycle(controller->pwm_fd_in4, duty_cycle);
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <distance>\n", argv[0]);
        exit(EXIT_FAILURE);
    }

    int distance = atoi(argv[1]);

    if (distance < DISTANCE_MIN || distance > DISTANCE_MAX) {
        fprintf(stderr, "Distance must be between %d and %d cm.\n", DISTANCE_MIN, DISTANCE_MAX);
        exit(EXIT_FAILURE);
    }

    MotorController controller;
    setup_gpio(&controller);

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (1) {
        control_motors(&controller, distance, distance);
        usleep(CONTROL_INTERVAL_MS * 1000);
    }

    cleanup(&controller);
    return 0;
}
