#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/gpio.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <gpiod.h>

#define NUM_RELAYS 4
#define GPIO_PINS {4, 17, 27, 22}
#define FADE_DURATION 1800
#define FADE_STEPS 180000
#define FADE_DELAY 1000000 / 100  // 100 Hz

typedef struct {
    time_t timestamp;
    int relay;
    int state;
} ScheduleEntry;

static gpiod_line *lines[NUM_RELAYS];
static int running = 1;
static int fade_in_progress = 0;
static int current_step = 0;
static int current_brightness = 0;
static int target_brightness = 0;
static int target_relay = -1;
static int target_state = -1;
static time_t last_check_time = 0;

void handle_signal(int sig) {
    running = 0;
    if (fade_in_progress) {
        target_brightness = 0;
        target_state = 0;
        target_relay = -1;
    }
}

void cleanup_gpio() {
    for (int i = 0; i < NUM_RELAYS; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
}

void set_gpio_output(int pin) {
    int fd = open("/dev/gpiochip0", O_RDWR);
    if (fd < 0) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    struct gpiohandle_request req = {
        .flags = GPIOHANDLE_REQUEST_OUTPUT,
        .lines = 1,
        .lineoffsets = {pin},
        .values = {1},
    };

    int handle = ioctl(fd, GPIO_GET_LINEHANDLE_IOCTL, &req);
    if (handle < 0) {
        perror("Failed to get GPIO line handle");
        close(fd);
        exit(EXIT_FAILURE);
    }

    close(fd);
}

void set_gpio_value(int pin, int value) {
    int fd = open("/dev/gpiochip0", O_RDWR);
    if (fd < 0) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    struct gpiohandle_data data = {
        .values = {value},
    };

    if (ioctl(fd, GPIOHANDLE_SET_LINE_VALUES_IOCTL, &data) < 0) {
        perror("Failed to set GPIO value");
    }

    close(fd);
}

void parse_schedule(const char *filename, ScheduleEntry *entries, int *entry_count) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        fprintf(stderr, "Failed to open schedule file: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    *entry_count = 0;
    char line[256];
    while (fgets(line, sizeof(line), file)) {
        char *ptr = strchr(line, '\n');
        if (ptr) *ptr = '\0';
        char *colon1 = strchr(line, ':');
        char *colon2 = strchr(colon1 + 1, ':');
        if (!colon1 || !colon2) continue;

        *colon1 = '\0';
        *colon2 = '\0';
        char *time_str = line;
        char *relay_str = colon1 + 1;
        char *state_str = colon2 + 1;

        struct tm tm = {0};
        strptime(time_str, "%H:%M:%S", &tm);
        time_t schedule_time = mktime(&tm);
        if (schedule_time == -1) continue;

        int relay = atoi(relay_str);
        int state = atoi(state_str);

        if (relay >= 0 && relay < NUM_RELAYS && state == 0 || state == 1) {
            entries[*entry_count].timestamp = schedule_time;
            entries[*entry_count].relay = relay;
            entries[*entry_count].state = state;
            (*entry_count)++;
        }
    }

    fclose(file);
}

void schedule_next_transition(ScheduleEntry *entries, int entry_count) {
    for (int i = 0; i < entry_count; i++) {
        if (entries[i].timestamp > last_check_time) {
            target_relay = entries[i].relay;
            target_state = entries[i].state;
            return;
        }
    }
    target_relay = -1;
    target_state = -1;
}

void fade_brightness(int relay, int target_state) {
    if (fade_in_progress) return;

    fade_in_progress = 1;
    current_step = 0;
    current_brightness = 0;
    target_brightness = target_state ? 100 : 0;
    target_relay = relay;

    for (int i = 0; i < FADE_STEPS; i++) {
        if (!running) {
            fade_in_progress = 0;
            return;
        }

        current_brightness = (current_step * (target_brightness - current_brightness)) / FADE_STEPS + current_brightness;
        gpiod_line_set_value(lines[target_relay], current_brightness ? 1 : 0);

        usleep(FADE_DELAY);
        current_step++;
    }

    fade_in_progress = 0;
    gpiod_line_set_value(lines[target_relay], target_brightness ? 1 : 0);
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    for (int i = 0; i < NUM_RELAYS; i++) {
        lines[i] = gpiod_line_get("/dev/gpiochip0", GPIO_PINS[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get GPIO line %d\n", GPIO_PINS[i]);
            cleanup_gpio();
            exit(EXIT_FAILURE);
        }

        if (gpiod_line_request_output(lines[i], "lighting", 0) < 0) {
            fprintf(stderr, "Failed to request GPIO line %d as output\n", GPIO_PINS[i]);
            cleanup_gpio();
            exit(EXIT_FAILURE);
        }

        if (gpiod_line_set_value(lines[i], 0) < 0) {
            fprintf(stderr, "Failed to set initial GPIO line %d to 0\n", GPIO_PINS[i]);
            cleanup_gpio();
            exit(EXIT_FAILURE);
        }
    }

    ScheduleEntry entries[100];
    int entry_count = 0;
    parse_schedule("lighting_schedule.txt", entries, &entry_count);

    time_t last_check_time = time(NULL);

    while (running) {
        time_t now = time(NULL);
        if (now - last_check_time >= 1) {
            last_check_time = now;
            schedule_next_transition(entries, entry_count);
        }

        if (target_relay != -1 && target_state != -1) {
            if (gpiod_line_get_value(lines[target_relay]) != target_state) {
                fade_brightness(target_relay, target_state);
            }
            target_relay = -1;
            target_state = -1;
        }

        usleep(1000000);
    }

    cleanup_gpio();
    return 0;
}

