#define BCM_TRIGGER_PIN 23
#define BCM_ECHO_PIN 24
#define BCM_BUZZER_PIN 18
#define MIN_DISTANCE_CM 2.0
#define MAX_DISTANCE_CM 400.0
#define MIN_FREQUENCY 20
#define MAX_FREQUENCY 20000
#define MEASUREMENT_INTERVAL_MS 60
#define TRIGGER_PULSE_US 10
#define ECHO_TIMEOUT_US 1000000
#define BUZZER_PWM_RANGE 1000000

typedef enum {
    SENSOR_OK,
    SENSOR_TIMEOUT,
    SENSOR_NO_RESPONSE,
    SENSOR_INIT_FAILURE
} sensor_status;

typedef struct {
    int trigger_fd;
    int echo_fd;
    int buzzer_fd;
    int buzzer_pwm;
    int last_measurement_time;
    int running;
} theremin_state;

void cleanup(theremin_state *state) {
    if (state->running) {
        // Silence buzzer
        gpio_set_value(state->buzzer_fd, 0);
        gpio_close(state->buzzer_fd);
        gpio_close(state->echo_fd);
        gpio_close(state->trigger_fd);
        printf("Theremin shutdown complete.\n");
    }
}

void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Received SIGINT, shutting down...\n");
        cleanup(NULL);
        exit(EXIT_SUCCESS);
    }
}

sensor_status init_gpio(theremin_state *state) {
    // Initialize trigger pin (output)
    state->trigger_fd = gpio_open(BCM_TRIGGER_PIN, GPIOHANDLE_REQUEST_OUTPUT);
    if (state->trigger_fd < 0) {
        fprintf(stderr, "Failed to open trigger pin %d\n", BCM_TRIGGER_PIN);
        return SENSOR_INIT_FAILURE;
    }

    // Initialize echo pin (input)
    state->echo_fd = gpio_open(BCM_ECHO_PIN, GPIOHANDLE_REQUEST_INPUT);
    if (state->echo_fd < 0) {
        fprintf(stderr, "Failed to open echo pin %d\n", BCM_ECHO_PIN);
        gpio_close(state->trigger_fd);
        return SENSOR_INIT_FAILURE;
    }

    // Initialize buzzer pin (PWM)
    state->buzzer_fd = gpio_open(BCM_BUZZER_PIN, GPIOHANDLE_REQUEST_OUTPUT);
    if (state->buzzer_fd < 0) {
        fprintf(stderr, "Failed to open buzzer pin %d\n", BCM_BUZZER_PIN);
        gpio_close(state->trigger_fd);
        gpio_close(state->echo_fd);
        return SENSOR_INIT_FAILURE;
    }

    // Set buzzer to 0% duty cycle (silence)
    gpio_set_value(state->buzzer_fd, 0);

    // Set up PWM for buzzer
    struct gpiohandle_data data;
    data.values[0] = 0;
    if (ioctl(state->buzzer_fd, GPIOHANDLE_SET_LINE_VALUES_IOCTL, &data) < 0) {
        fprintf(stderr, "Failed to set initial buzzer value\n");
        gpio_close(state->trigger_fd);
        gpio_close(state->echo_fd);
        gpio_close(state->buzzer_fd);
        return SENSOR_INIT_FAILURE;
    }

    state->buzzer_pwm = 0;
    state->last_measurement_time = 0;
    state->running = 1;
    return SENSOR_OK;
}

sensor_status measure_distance(theremin_state *state, uint32_t *distance_us) {
    // Send trigger pulse
    struct gpiohandle_data trigger_data;
    trigger_data.values[0] = 1;
    if (ioctl(state->trigger_fd, GPIOHANDLE_SET_LINE_VALUES_IOCTL, &trigger_data) < 0) {
        fprintf(stderr, "Failed to send trigger pulse\n");
        return SENSOR_TIMEOUT;
    }

    usleep(TRIGGER_PULSE_US);

    trigger_data.values[0] = 0;
    if (ioctl(state->trigger_fd, GPIOHANDLE_SET_LINE_VALUES_IOCTL, &trigger_data) < 0) {
        fprintf(stderr, "Failed to end trigger pulse\n");
        return SENSOR_TIMEOUT;
    }

    // Wait for echo to go high
    struct gpiohandle_data echo_data;
    int echo_high = 0;
    int start_time = 0;
    int end_time = 0;

    for (int i = 0; i < 100000; i++) {
        if (ioctl(state->echo_fd, GPIOHANDLE_GET_LINE_VALUES_IOCTL, &echo_data) < 0) {
            fprintf(stderr, "Failed to read echo pin\n");
            return SENSOR_TIMEOUT;
        }

        if (echo_data.values[0] == 1) {
            start_time = clock_gettime(CLOCK_MONOTONIC, NULL);
            break;
        }

        usleep(1);
    }

    if (start_time == 0) {
        fprintf(stderr, "Echo pin did not go high\n");
        return SENSOR_TIMEOUT;
    }

    // Wait for echo to go low
    for (int i = 0; i < 100000; i++) {
        if (ioctl(state->echo_fd, GPIOHANDLE_GET_LINE_VALUES_IOCTL, &echo_data) < 0) {
            fprintf(stderr, "Failed to read echo pin\n");
            return SENSOR_TIMEOUT;
        }

        if (echo_data.values[0] == 0) {
            end_time = clock_gettime(CLOCK_MONOTONIC, NULL);
            break;
        }

        usleep(1);
    }

    if (end_time == 0) {
        fprintf(stderr, "Echo pin did not go low\n");
        return SENSOR_TIMEOUT;
    }

    // Calculate time difference in microseconds
    struct timespec start, end;
    clock_gettime(CLOCK_MONOTONIC, &start);
    clock_gettime(CLOCK_MONOTONIC, &end);
    *distance_us = (end.tv_nsec - start.tv_nsec) / 1000;

    // Convert to centimeters
    double distance_cm = (*distance_us * 0.0343) / 2.0;

    if (distance_cm < MIN_DISTANCE_CM || distance_cm > MAX_DISTANCE_CM) {
        return SENSOR_NO_RESPONSE;
    }

    return SENSOR_OK;
}

void map_distance_to_frequency(theremin_state *state, uint32_t distance_us) {
    // Map distance to frequency
    double frequency = (MAX_FREQUENCY - MIN_FREQUENCY) * (MAX_DISTANCE_CM - distance_us) / (MAX_DISTANCE_CM - MIN_DISTANCE_CM) + MIN_FREQUENCY;

    // Clamp frequency to valid range
    if (frequency < MIN_FREQUENCY) {
        frequency = MIN_FREQUENCY;
    } else if (frequency > MAX_FREQUENCY) {
        frequency = MAX_FREQUENCY;
    }

    // Calculate duty cycle
    double duty_cycle = (100.0 / (double)BUZZER_PWM_RANGE) * frequency;
    int duty_cycle_int = (int)duty_cycle;

    // Set buzzer PWM
    struct gpiohandle_data data;
    data.values[0] = duty_cycle_int;
    if (ioctl(state->buzzer_fd, GPIOHANDLE_SET_LINE_VALUES_IOCTL, &data) < 0) {
        fprintf(stderr, "Failed to set buzzer duty cycle\n");
    }
}

int main() {
    theremin_state state;
    sensor_status status;
    uint32_t distance_us = 0;
    struct timespec current_time;
    int last_measurement_time = 0;

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (init_gpio(&state) != SENSOR_OK) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return EXIT_FAILURE;
    }

    while (state.running) {
        clock_gettime(CLOCK_MONOTONIC, &current_time);
        if (current_time.tv_sec - last_measurement_time >= MEASUREMENT_INTERVAL_MS / 1000) {
            status = measure_distance(&state, &distance_us);
            if (status == SENSOR_OK) {
                map_distance_to_frequency(&state, distance_us);
                last_measurement_time = current_time.tv_sec;
            } else if (status == SENSOR_TIMEOUT) {
                fprintf(stderr, "HC-SR04 timeout\n");
            } else if (status == SENSOR_NO_RESPONSE) {
                fprintf(stderr, "HC-SR04 no response\n");
            } else {
                fprintf(stderr, "HC-SR04 initialization failure\n");
                cleanup(&state);
                return EXIT_FAILURE;
            }
        }

        usleep(10000); // 10ms delay to prevent CPU overuse
    }

    cleanup(&state);
    return EXIT_SUCCESS;
}

