#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/pwm.h>
#include <libgpiod.h>

#define BCM_PIN_RED   17
#define BCM_PIN_GREEN 22
#define BCM_PIN_BLUE  27

#define PWM_FREQUENCY 1000
#define PWM_RANGE     1024

typedef struct {
    struct gpiod_line *red_line;
    struct gpiod_line *green_line;
    struct gpiod_line *blue_line;
    struct pwm_device *pwm_red;
    struct pwm_device *pwm_green;
    struct pwm_device *pwm_blue;
    int pwm_fd_red;
    int pwm_fd_green;
    int pwm_fd_blue;
} pwm_context;

void cleanup(pwm_context *ctx) {
    if (ctx->pwm_red) {
        pwm_disable(ctx->pwm_red);
        pwm_unexport(ctx->pwm_red);
        close(ctx->pwm_fd_red);
    }
    if (ctx->pwm_green) {
        pwm_disable(ctx->pwm_green);
        pwm_unexport(ctx->pwm_green);
        close(ctx->pwm_fd_green);
    }
    if (ctx->pwm_blue) {
        pwm_disable(ctx->pwm_blue);
        pwm_unexport(ctx->pwm_blue);
        close(ctx->pwm_fd_blue);
    }

    if (ctx->red_line) {
        gpiod_line_release(ctx->red_line);
    }
    if (ctx->green_line) {
        gpiod_line_release(ctx->green_line);
    }
    if (ctx->blue_line) {
        gpiod_line_release(ctx->blue_line);
    }
}

void handle_signal(int sig) {
    cleanup(NULL);
    exit(EXIT_SUCCESS);
}

int setup_pwm(int pin, int *pwm_fd, struct pwm_device **pwm_dev) {
    int fd = open("/dev/pwm", O_RDWR);
    if (fd < 0) {
        perror("Failed to open PWM device");
        return -1;
    }

    struct pwm_config config = {
        .period = PWM_RANGE / PWM_FREQUENCY,
        .duty_cycle = 0,
        .polarity = PWM_POLARITY_NORMAL
    };

    if (ioctl(fd, PWM_IOCTL_SET_CONFIG, &config) < 0) {
        perror("Failed to set PWM configuration");
        close(fd);
        return -1;
    }

    *pwm_dev = pwm_get(fd, pin);
    if (!*pwm_dev) {
        perror("Failed to get PWM device");
        close(fd);
        return -1;
    }

    *pwm_fd = fd;
    return 0;
}

int setup_gpio(int pin, struct gpiod_line **line) {
    struct gpiod_chip *chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    *line = gpiod_chip_get_line(chip, pin);
    if (!*line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(*line, "rgb-led", 0) < 0) {
        perror("Failed to request GPIO line");
        gpiod_line_release(*line);
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

int main() {
    pwm_context ctx = {0};

    if (setup_gpio(BCM_PIN_RED, &ctx.red_line) < 0) {
        fprintf(stderr, "Failed to setup red GPIO\n");
        return EXIT_FAILURE;
    }

    if (setup_gpio(BCM_PIN_GREEN, &ctx.green_line) < 0) {
        fprintf(stderr, "Failed to setup green GPIO\n");
        cleanup(&ctx);
        return EXIT_FAILURE;
    }

    if (setup_gpio(BCM_PIN_BLUE, &ctx.blue_line) < 0) {
        fprintf(stderr, "Failed to setup blue GPIO\n");
        cleanup(&ctx);
        return EXIT_FAILURE;
    }

