#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define MPU6050_ADDR 0x68
#define MPU6050_ACCEL_XOUT_H 0x3B
#define MPU6050_GYRO_XOUT_H 0x43
#define SAMPLE_INTERVAL_MS 100
#define LOG_FILE "gyro_log.txt"

int i2c_fd = -1;
int log_file = -1;
volatile int running = 1;

void handle_signal(int sig) {
    running = 0;
}

void close_resources() {
    if (log_file != -1) {
        fclose(log_file);
    }
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    printf("Resources closed.\n");
    exit(EXIT_SUCCESS);
}

void log_gyro_data(int16_t gx, int16_t gy, int16_t gz) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    char timestamp[30];
    snprintf(timestamp, sizeof(timestamp), "%ld.%09ld ", ts.tv_sec, ts.tv_nsec);

    char line[128];
    snprintf(line, sizeof(line), "%s%d %d %d\n", timestamp, gx, gy, gz);

    if (fwrite(line, 1, strlen(line), log_file) != strlen(line)) {
        perror("fwrite");
    }
}

int read_gyro_data(int16_t *gx, int16_t *gy, int16_t *gz) {
    uint8_t buffer[6];
    int res;

    res = ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR);
    if (res < 0) {
        perror("ioctl I2C_SLAVE");
        return -1;
    }

    res = read(i2c_fd, buffer, 6);
    if (res != 6) {
        perror("read");
        return -1;
    }

    *gx = (int16_t)(buffer[0] << 8 | buffer[1]);
    *gy = (int16_t)(buffer[2] << 8 | buffer[3]);
    *gz = (int16_t)(buffer[4] << 8 | buffer[5]);

    return 0;
}

int init_i2c() {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("open");
        return -1;
    }

    int res = ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR);
    if (res < 0) {
        perror("ioctl I2C_SLAVE");
        close(i2c_fd);
        return -1;
    }

    // Check if MPU6050 is present
    uint8_t reg = 0x75; // WHO_AM_I register
    res = write(i2c_fd, &reg, 1);
    if (res != 1) {
        perror("write");
        close(i2c_fd);
        return -1;
    }

    res = read(i2c_fd, &reg, 1);
    if (res != 1 || reg != 0x68) {
        fprintf(stderr, "MPU6050 not found or invalid ID.\n");
        close(i2c_fd);
        return -1;
    }

    return 0;
}

int init_logging() {
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen");
        return -1;
    }

    fprintf(log_file, "Timestamp (s) X (dps) Y (dps) Z (dps)\n");
    return 0;
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if (init_i2c() != 0) {
        fprintf(stderr, "Failed to initialize I2C.\n");
        close_resources();
        return EXIT_FAILURE;
    }

    if (init_logging() != 0) {
        fprintf(stderr, "Failed to initialize logging.\n");
        close_resources();
        return EXIT_FAILURE;
    }

    printf("MPU6050 gyroscope logging started. Press Ctrl+C to exit.\n");

    while (running) {
        int16_t gx, gy, gz;
        if (read_gyro_data(&gx, &gy, &gz) == 0) {
            log_gyro_data(gx, gy, gz);
        } else {
            fprintf(stderr, "Failed to read gyroscope data.\n");
        }

        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    close_resources();
    return EXIT_SUCCESS;
}

