#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/gpio.h>
#include <libgpiod.h>

#define GPIO_BUTTON_PIN 17
#define GPIO_BUZZER_PIN 18
#define PWM_CHANNEL 0
#define PWM_DUTY_CYCLE 50
#define DEBOUNCE_DELAY_MS 50
#define MELODY_LENGTH 10
#define NOTE_DURATION_MS 200

typedef struct {
    int note;
    int duration;
} Note;

const Note melody[MELODY_LENGTH] = {
    {440, NOTE_DURATION_MS},  // A4
    {440, NOTE_DURATION_MS},
    {392, NOTE_DURATION_MS},  // G4
    {392, NOTE_DURATION_MS},
    {349, NOTE_DURATION_MS},  // F4
    {349, NOTE_DURATION_MS},
    {329, NOTE_DURATION_MS},  // E4
    {329, NOTE_DURATION_MS},
    {294, NOTE_DURATION_MS},  // D4
    {294, NOTE_DURATION_MS}
};

volatile int button_pressed = 0;
volatile int playing = 0;
volatile int stop_requested = 0;

struct gpiod_line *button_line;
struct gpiod_line *buzzer_line;
struct gpiod_line *pwm_line;
struct gpiod_line *pwm_line2;

void handle_signal(int sig) {
    stop_requested = 1;
}

void cleanup() {
    if (button_line) {
        gpiod_line_release(button_line);
    }
    if (buzzer_line) {
        gpiod_line_release(buzzer_line);
    }
    if (pwm_line) {
        gpiod_line_release(pwm_line);
    }
    if (pwm_line2) {
        gpiod_line_release(pwm_line2);
    }
    printf("Cleanup complete.\n");
    exit(EXIT_SUCCESS);
}

void setup_gpio() {
    int fd;
    struct gpiod_line_config config;

    // Setup button GPIO (BCM 17)
    config = GPIOD_LINE_CONFIG_DEFAULT;
    config.requested_direction = GPIOD_LINE_DIRECTION_INPUT;
    config.requested_flags = GPIOD_LINE_FLAG_ACTIVE_LOW | GPIOD_LINE_FLAG_BIAS_PULL_UP;

    fd = gpiod_line_request(GPIO_BUTTON_PIN, "button", &config);
    if (fd < 0) {
        fprintf(stderr, "Failed to request GPIO %d for button: %s\n", GPIO_BUTTON_PIN, strerror(errno));
        exit(EXIT_FAILURE);
    }
    button_line = fdopen(fd, "r+");
    if (!button_line) {
        fprintf(stderr, "Failed to open GPIO %d for button: %s\n", GPIO_BUTTON_PIN, strerror(errno));
        exit(EXIT_FAILURE);
    }

    // Setup buzzer GPIO (BCM 18) for PWM
    config = GPIOD_LINE_CONFIG_DEFAULT;
    config.requested_direction = GPIOD_LINE_DIRECTION_OUTPUT;
    config.requested_flags = GPIOD_LINE_FLAG_OUTPUT;

    fd = gpiod_line_request(GPIO_BUZZER_PIN, "buzzer", &config);
    if (fd < 0) {
        fprintf(stderr, "Failed to request GPIO %d for buzzer: %s\n", GPIO_BUZZER_PIN, strerror(errno));
        exit(EXIT_FAILURE);
    }
    buzzer_line = fdopen(fd, "r+");
    if (!buzzer_line) {
        fprintf(stderr, "Failed to open GPIO %d for buzzer: %s\n", GPIO_BUZZER_PIN, strerror(errno));
        exit(EXIT_FAILURE);
    }

    // Setup PWM for buzzer
    struct gpiod_line_config pwm_config = GPIOD_LINE_CONFIG_DEFAULT;
    pwm_config.requested_direction = GPIOD_LINE_DIRECTION_OUTPUT;
    pwm_config.requested_flags = GPIOD_LINE_FLAG_OUTPUT;

    fd = gpiod_line_request(GPIO_BUZZER_PIN, "pwm", &pwm_config);
    if (fd < 0) {
        fprintf(stderr, "Failed to request GPIO %d for PWM: %s\n", GPIO_BUZZER_PIN, strerror(errno));
        exit(EXIT_FAILURE);
    }
    pwm_line = fdopen(fd, "r+");
    if (!pwm_line) {
        fprintf(stderr, "Failed to open GPIO %d for PWM: %s\n", GPIO_BUZZER_PIN, strerror(errno));
        exit(EXIT_FAILURE);
    }

    // Setup second PWM line for duty cycle
    fd = gpiod_line_request(GPIO_BUZZER_PIN, "pwm2", &pwm_config);
    if (fd < 0) {
        fprintf(stderr, "Failed to request GPIO %d for PWM2: %s\n", GPIO_BUZZER_PIN, strerror(errno));
        exit(EXIT_FAILURE);
    }
    pwm_line2 = fdopen(fd, "r+");
    if (!pwm_line2) {
        fprintf(stderr, "Failed to open GPIO %d for PWM2: %s\n", GPIO_BUZZER_PIN, strerror(errno));
        exit(EXIT_FAILURE);
    }
}

void play_melody() {
    int i;
    for (i = 0; i < MELODY_LENGTH && !stop_requested; i++) {
        int note = melody[i].note;
        int duration = melody[i].duration;

        if (note == 0) {
            usleep(100000); // 100ms silence
            continue;
        }

        // Set PWM duty cycle
        char duty_cycle_str[16];
        snprintf(duty_cycle_str, sizeof(duty_cycle_str), "%d", PWM_DUTY_CYCLE);
        if (gpiod_line_set_value(pwm_line2, PWM_DUTY_CYCLE) < 0) {
            fprintf(stderr, "Failed to set PWM duty cycle: %s\n", strerror(errno));
            break;
        }

        // Set PWM frequency
        if (gpiod_line_set_value(pwm_line, note) < 0) {
            fprintf(stderr, "Failed to set PWM frequency: %s\n", strerror(errno));
            break;
        }

        usleep(duration * 1000); // Convert ms to microseconds
    }

    // Stop PWM
    if (gpiod_line_set_value(pwm_line, 0) < 0) {
        fprintf(stderr, "Failed to stop PWM: %s\n", strerror(errno));
    }
    if (gpiod_line_set_value(pwm_line2, 0) < 0) {
        fprintf(stderr, "Failed to stop PWM2: %s\n", strerror(errno));
    }
    playing = 0;
}

void button_isr() {
    button_pressed = 1;
}

void check_button() {
    static int last_state = 1; // Active low, so 1 is released
    int current_state;

    if (gpiod_line_get_value(button_line, &current_state) < 0) {
        fprintf(stderr, "Failed to read button state: %s\n", strerror(errno));
        return;
    }

    if (current_state != last_state) {
        usleep(DEBOUNCE_DELAY_MS * 1000); // Debounce delay
        if (gpiod_line_get_value(button_line, &current_state) < 0) {
            fprintf(stderr, "Failed to re-read button state: %s\n", strerror(errno));
            return;
        }

        if (current_state != last_state) {
            if (current_state == 0) {
                button_pressed = 1;
            }
            last_state = current_state;
        }
    }
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    setup_gpio();

    while (!stop_requested) {
        check_button();

        if (button_pressed && !playing) {
            button_pressed = 0;
            playing = 1;
            play_melody();
        }

        if (stop_requested) {
            break;
        }

        usleep(1000); // Sleep to reduce CPU usage
    }

    cleanup();
    return 0;
}

