#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_PIN 17
#define MAX_EVENTS 5
#define DEFAULT_POLL_TIMEOUT 1000

volatile sig_atomic_t exit_flag = 0;

typedef struct {
    int value;
    time_t timestamp;
} Event;

Event event_window[MAX_EVENTS];
int window_index = 0;

FILE *log_file = NULL;

void handle_signal(int sig) {
    exit_flag = 1;
}

void log_event(int value) {
    char timestamp[30];
    time_t now = time(NULL);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

    if (log_file == NULL) {
        log_file = fopen("vibration_events.log", "a");
        if (log_file == NULL) {
            fprintf(stderr, "Error: Could not open log file.\n");
            return;
        }
    }

    fprintf(log_file, "%s %d\n", timestamp, value);
    if (fflush(log_file) != 0) {
        fprintf(stderr, "Error: Could not flush log file.\n");
    }
}

void update_event_window(int value) {
    event_window[window_index] = (Event){value, time(NULL)};
    window_index = (window_index + 1) % MAX_EVENTS;

    int high_count = 0;
    for (int i = 0; i < MAX_EVENTS; i++) {
        if (event_window[i].value == 1) {
            high_count++;
        }
    }

    if (high_count >= 3) {
        time_t now = time(NULL);
        char timestamp[30];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
        fprintf(stderr, "EARTHQUAKE ALERT: %s\n", timestamp);
    }
}

int main(int argc, char *argv[]) {
    int poll_timeout = DEFAULT_POLL_TIMEOUT;
    if (argc > 1) {
        poll_timeout = atoi(argv[1]);
        if (poll_timeout < 0) {
            fprintf(stderr, "Error: Poll timeout must be non-negative.\n");
            return 1;
        }
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    struct gpiod_line *line = gpiod_line_get("gpiochip4", GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Error: Could not get GPIO line.\n");
        return 1;
    }

    if (gpiod_line_request_output(line, "vibration_sensor", 0) < 0) {
        fprintf(stderr, "Error: Could not request GPIO line as output.\n");
        gpiod_line_put(line);
        return 1;
    }

    if (gpiod_line_set_value(line, 0) < 0) {
        fprintf(stderr, "Error: Could not set initial GPIO value.\n");
        gpiod_line_put(line);
        return 1;
    }

    if (gpiod_line_request_edge_events(line, "vibration_sensor", GPIOD_LINE_EVENT_BOTH_EDGES) < 0) {
        fprintf(stderr, "Error: Could not request edge events.\n");
        gpiod_line_put(line);
        return 1;
    }

    if (log_file == NULL) {
        log_file = fopen("vibration_events.log", "a");
        if (log_file == NULL) {
            fprintf(stderr, "Error: Could not open log file.\n");
            gpiod_line_put(line);
            return 1;
        }
    }

    while (!exit_flag) {
        struct gpiod_line_event event;
        int ret = gpiod_line_event_wait(line, poll_timeout);
        if (ret < 0) {
            fprintf(stderr, "Error: Could not wait for event.\n");
            break;
        }

        if (gpiod_line_get_event(line, &event) < 0) {
            fprintf(stderr, "Error: Could not get event.\n");
            break;
        }

        int value = (event.type == GPIOD_LINE_EVENT_RISING_EDGE) ? 1 : 0;
        log_event(value);
        update_event_window(value);

        gpiod_line_ack_event(line);
    }

    if (log_file != NULL) {
        if (fclose(log_file) != 0) {
            fprintf(stderr, "Error: Could not close log file.\n");
        }
    }

    gpiod_line_put(line);
    return 0;
}

