#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

#define I2C_BUS "/dev/i2c-1"
#define MAG_ADDR 0x1E
#define X_OFFSET 10
#define Y_OFFSET -5
#define Z_OFFSET 20
#define MAG_DATA_SIZE 6
#define CSV_FILE "mag_log.csv"

typedef struct {
    int fd;
    FILE *csv_file;
    int exit_flag;
} app_state;

void handle_signal(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        app_state *state = (app_state *)malloc(sizeof(app_state));
        state->exit_flag = 1;
        // Simulate cleanup
        if (state->csv_file) {
            fclose(state->csv_file);
        }
        if (state->fd >= 0) {
            close(state->fd);
        }
        free(state);
        exit(EXIT_SUCCESS);
    }
}

void write_csv_header(FILE *file) {
    fprintf(file, "Timestamp,Calibrated X,Calibrated Y,Calibrated Z,Heading\n");
}

void write_csv_row(FILE *file, time_t timestamp, int x, int y, int z, double heading) {
    fprintf(file, "%ld,%d,%d,%d,%.1f\n", (long)timestamp, x, y, z, heading);
}

void read_mag_data(int fd, int *x, int *y, int *z) {
    char buffer[MAG_DATA_SIZE];
    int ret;

    ret = ioctl(fd, I2C_SLAVE, MAG_ADDR);
    if (ret < 0) {
        fprintf(stderr, "Failed to set I2C slave address: %s\n", strerror(errno));
        return;
    }

    if (write(fd, "\x80", 1) < 0) {
        fprintf(stderr, "Failed to write to I2C device: %s\n", strerror(errno));
        return;
    }

    if (read(fd, buffer, MAG_DATA_SIZE) < 0) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return;
    }

    *x = (buffer[1] << 8) | buffer[0];
    *y = (buffer[3] << 8) | buffer[2];
    *z = (buffer[5] << 8) | buffer[4];
}

double calculate_heading(int x, int y) {
    double heading_rad = atan2((double)y, (double)x);
    double heading_deg = (heading_rad * 180.0) / M_PI;

    if (heading_deg < 0) {
        heading_deg += 360.0;
    }

    return heading_deg;
}

void determine_compass_direction(double heading_deg) {
    int direction;
    if (heading_deg >= 337.5 || heading_deg < 22.5) {
        direction = 0; // North
    } else if (heading_deg >= 22.5 && heading_deg < 67.5) {
        direction = 1; // Northeast
    } else if (heading_deg >= 67.5 && heading_deg < 112.5) {
        direction = 2; // East
    } else if (heading_deg >= 112.5 && heading_deg < 157.5) {
        direction = 3; // Southeast
    } else if (heading_deg >= 157.5 && heading_deg < 202.5) {
        direction = 4; // South
    } else if (heading_deg >= 202.5 && heading_deg < 247.5) {
        direction = 5; // Southwest
    } else if (heading_deg >= 247.5 && heading_deg < 292.5) {
        direction = 6; // West
    } else {
        direction = 7; // Northwest
    }

    const char *directions[] = {"N", "NE", "E", "SE", "S", "SW", "W", "NW"};
    printf("Direction: %s, Heading: %.1f°\n", directions[direction], heading_deg);
}

int main() {
    app_state state = {0};
    struct sigaction sa;
    int ret;

    // Set up signal handler
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to set SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to set SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    // Open I2C bus
    state.fd = open(I2C_BUS, O_RDWR | O_NOCTTY | O_CLOEXEC);
    if (state.fd < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    // Open CSV file
    state.csv_file = fopen(CSV_FILE, "a");
    if (!state.csv_file) {
        fprintf(stderr, "Failed to open CSV file: %s\n", strerror(errno));
        close(state.fd);
        return EXIT_FAILURE;
    }

    // Write header if file is empty
    if (fseek(state.csv_file, 0, SEEK_SET) == 0 && ftell(state.csv_file) == 0) {
        write_csv_header(state.csv_file);
    }

    while (!state.exit_flag) {
        time_t timestamp = time(NULL);
        int x, y, z;

        // Read magnetometer data
        read_mag_data(state.fd, &x, &y, &z);

        // Apply calibration
        x -= X_OFFSET;
        y -= Y_OFFSET;
        z -= Z_OFFSET;

        // Calculate heading
        double heading_deg = calculate_heading(x, y);

        // Write to CSV
        write_csv_row(state.csv_file, timestamp, x, y, z, heading_deg);

        // Print compass direction and heading
        determine_compass_direction(heading_deg);

        // Sleep for 1 second
        sleep(1);
    }

    // Cleanup
    fclose(state.csv_file);
    close(state.fd);
    return EXIT_SUCCESS;
}

