int log_file = -1;
int running = 1;

void handle_sigint(int sig) {
    running = 0;
    relay_state = 0;
    printf("SIGINT received, shutting down...\n");
}

void log_state_change() {
    if (log_file == -1) {
        log_file = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
        if (log_file == -1) {
            perror("Failed to open log file");
            exit(EXIT_FAILURE);
        }
    }

    struct json_object *json = json_object_new_object();
    struct json_object *timestamp = json_object_new_string(timeToString());
    struct json_object *state = json_object_new_string(relay_state ? "ON" : "OFF");

    json_object_object_add(json, "timestamp", timestamp);
    json_object_object_add(json, "relay_state", state);

    char *json_str = json_object_to_json_string(json);
    write(log_file, json_str, strlen(json_str));
    write(log_file, "\n", 1);

    json_object_put(json);
}

