#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_PIN_17 17
#define GPIO_PIN_23 23
#define GPIO_PIN_24 24
#define GPIO_PIN_25 25

#define RELAY_COUNT 4
#define MOISTURE_MIN 0
#define MOISTURE_MAX 100
#define MOISTURE_THRESHOLD 30
#define RELAY_DELAY 1
#define RELAY_DURATION 5
#define LOG_FILE "irrigation_log.txt"

typedef struct {
    gpiod_line *lines[RELAY_COUNT];
    FILE *log_file;
    int running;
} app_state;

void handle_signal(int signum) {
    app_state *state = (app_state *)malloc(sizeof(app_state));
    if (state == NULL) {
        fprintf(stderr, "Failed to allocate memory for app_state\n");
        exit(EXIT_FAILURE);
    }

    state->running = 0;
    fprintf(stderr, "Caught signal %d, shutting down...\n", signum);

    // Deactivate all relays
    for (int i = 0; i < RELAY_COUNT; i++) {
        if (state->lines[i]) {
            gpiod_line_set_value(state->lines[i], 1);
        }
    }

    // Close log file
    if (state->log_file) {
        fclose(state->log_file);
    }

    // Release GPIO lines
    for (int i = 0; i < RELAY_COUNT; i++) {
        if (state->lines[i]) {
            gpiod_line_release(state->lines[i]);
        }
    }

    free(state);
    exit(EXIT_SUCCESS);
}

void init_gpio(app_state *state) {
    const char *chip_name = "gpiochip0";
    struct gpiod_chip *chip;
    int pin_index;

    for (int i = 0; i < RELAY_COUNT; i++) {
        switch (i) {
            case 0: pin_index = GPIO_PIN_17; break;
            case 1: pin_index = GPIO_PIN_23; break;
            case 2: pin_index = GPIO_PIN_24; break;
            case 3: pin_index = GPIO_PIN_25; break;
            default: fprintf(stderr, "Invalid relay index\n"); exit(EXIT_FAILURE);
        }

        chip = gpiod_chip_open_by_name(chip_name);
        if (!chip) {
            fprintf(stderr, "Failed to open GPIO chip %s\n", chip_name);
            exit(EXIT_FAILURE);
        }

        state->lines[i] = gpiod_chip_get_line(chip, pin_index);
        if (!state->lines[i]) {
            fprintf(stderr, "Failed to get GPIO line %d\n", pin_index);
            gpiod_chip_close(chip);
            exit(EXIT_FAILURE);
        }

        if (gpiod_line_request_output(state->lines[i], "relay", 1)) {
            fprintf(stderr, "Failed to request GPIO line %d as output\n", pin_index);
            gpiod_line_release(state->lines[i]);
            gpiod_chip_close(chip);
            exit(EXIT_FAILURE);
        }

        gpiod_chip_close(chip);
    }
}

void activate_relay(app_state *state, int relay_index) {
    if (state->lines[relay_index]) {
        gpiod_line_set_value(state->lines[relay_index], 0);
    }
}

void deactivate_relay(app_state *state, int relay_index) {
    if (state->lines[relay_index]) {
        gpiod_line_set_value(state->lines[relay_index], 1);
    }
}

void log_irrigation(app_state *state, int relay_index, int moisture) {
    char timestamp[30];
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    char log_line[100];
    snprintf(log_line, sizeof(log_line), "%s, Relay %d, Moisture: %d\n", timestamp, relay_index, moisture);

    if (state->log_file) {
        if (fprintf(state->log_file, "%s", log_line) < 0) {
            fprintf(stderr, "Failed to write to log file\n");
        }
        if (fflush(state->log_file) != 0) {
            fprintf(stderr, "Failed to flush log file\n");
        }
    }
}

void run_irrigation(app_state *state) {
    srand(time(NULL));
    int moisture;

    while (state->running) {
        moisture = rand() % (MOISTURE_MAX - MOISTURE_MIN + 1) + MOISTURE_MIN;

        if (moisture < MOISTURE_THRESHOLD) {
            for (int i = 0; i < RELAY_COUNT; i++) {
                deactivate_relay(state, i);
                usleep(1000000 * RELAY_DELAY); // 1 second delay
                activate_relay(state, i);
                usleep(1000000 * RELAY_DURATION); // 5 seconds duration
                deactivate_relay(state, i);
                log_irrigation(state, i, moisture);
            }
        }

        sleep(10);
    }
}

int main() {
    app_state state = {0};

    // Initialize signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Initialize GPIO
    init_gpio(&state);

    // Open log file
    state.log_file = fopen(LOG_FILE, "a");
    if (!state.log_file) {
        fprintf(stderr, "Failed to open log file %s\n", LOG_FILE);
        exit(EXIT_FAILURE);
    }

    // Start irrigation loop
    run_irrigation(&state);

    // Cleanup
    for (int i = 0; i < RELAY_COUNT; i++) {
        if (state.lines[i]) {
            gpiod_line_release(state.lines[i]);
        }
    }

    if (state.log_file) {
        fclose(state.log_file);
    }

    return 0;
}

