        gpiod_chip_close(chip);
        return -1;
    }

    handles->nozzle_line = gpiod_chip_get_line(chip, GPIO_NOZZLE);
    if (!handles->nozzle_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", GPIO_NOZZLE, strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    ret = gpiod_line_request_output(handles->valve_line, "valve", GPIOD_LINE_ACTIVE_LOW);
    if (ret < 0) {
        fprintf(stderr, "Failed to request valve line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    ret = gpiod_line_request_output(handles->nozzle_line, "nozzle", GPIOD_LINE_ACTIVE_LOW);
