#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

#define I2C_BUS "/dev/i2c-1"
#define MPU6050_ADDR 0x68
#define MPU6050_REGISTER_ACCEL_XOUT_H 0x3B
#define MPU6050_REGISTER_GYRO_XOUT_H 0x43
#define MPU6050_REGISTER_PWR_MGMT_1 0x6B
#define MPU6050_SAMPLE_RATE 100  // 100 Hz, 10 Hz output
#define MPU6050_SAMPLE_INTERVAL 1000000 / MPU6050_SAMPLE_RATE  // 1000000 / 100 = 10000 us

typedef struct {
    int fd;
    FILE *log_file;
    int running;
} app_state;

void handle_signal(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        printf("Caught signal %d, shutting down...\n", signum);
        app_state *state = (app_state *)malloc(sizeof(app_state));
        state->running = 0;
        // Free resources here if needed
        free(state);
        exit(EXIT_SUCCESS);
    }
}

void init_i2c(int *fd) {
    *fd = open(I2C_BUS, O_RDWR);
    if (*fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    if (ioctl(*fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(*fd);
        exit(EXIT_FAILURE);
    }
}

void init_mpu6050(int fd) {
    // Wake up the MPU-6050
    unsigned char wake_up[] = {MPU6050_REGISTER_PWR_MGMT_1, 0x00}; // Wake up
    if (write(fd, wake_up, 2) != 2) {
        perror("Failed to wake up MPU-6050");
        close(fd);
        exit(EXIT_FAILURE);
    }

    // Set sample rate to 100 Hz (10 Hz output)
    unsigned char sample_rate[] = {MPU6050_REGISTER_PWR_MGMT_1, 0x01}; // 100 Hz sample rate
    if (write(fd, sample_rate, 2) != 2) {
        perror("Failed to set sample rate");
        close(fd);
        exit(EXIT_FAILURE);
    }
}

void close_i2c(int fd) {
    close(fd);
}

void close_log_file(FILE *log_file) {
    if (log_file) {
        fclose(log_file);
    }
}

void log_gyro_data(int fd, FILE *log_file) {
    unsigned char gyro_data[6];
    if (read(fd, gyro_data, 6) != 6) {
        perror("Failed to read gyro data");
        return;
    }

    int x = (gyro_data[0] << 8) | gyro_data[1];
    int y = (gyro_data[2] << 8) | gyro_data[3];
    int z = (gyro_data[4] << 8) | gyro_data[5];

    time_t now = time(NULL);
    struct tm *tm_now = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_now);

    fprintf(log_file, "%s,%d,%d,%d\n", timestamp, x, y, z);
    fflush(log_file);
}

int main() {
    app_state state = {0};
    state.running = 1;

    // Set up signal handlers
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Failed to set SIGINT handler");
        exit(EXIT_FAILURE);
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Failed to set SIGTERM handler");
        exit(EXIT_FAILURE);
    }

    // Initialize I2C
    if (init_i2c(&state.fd) != 0) {
        exit(EXIT_FAILURE);
    }

    // Initialize MPU-6050
    if (init_mpu6050(state.fd) != 0) {
        close_i2c(state.fd);
        exit(EXIT_FAILURE);
    }

    // Open log file
    state.log_file = fopen("gyro_log.txt", "a");
    if (!state.log_file) {
        perror("Failed to open log file");
        close_i2c(state.fd);
        exit(EXIT_FAILURE);
    }

    // Write header
    fprintf(state.log_file, "Timestamp,X,Y,Z\n");
    fflush(state.log_file);

    // Main loop
    while (state.running) {
        log_gyro_data(state.fd, state.log_file);
        usleep(MPU6050_SAMPLE_INTERVAL);
    }

    // Cleanup
    close_log_file(state.log_file);
    close_i2c(state.fd);

    return 0;
}

