#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/gpio.h>
#include <libgpiod.h>

#define GPIO_IN1 4
#define GPIO_IN2 17
#define GPIO_IN3 27
#define GPIO_IN4 22
#define GPIO_LOCK_BUTTON 24
#define GPIO_UNLOCK_BUTTON 23

#define STEPS 512
#define STEP_DELAY_MS 3
#define DEBOUNCE_DELAY_MS 50

typedef enum {
    STATE_IDLE,
    STATE_LOCKING,
    STATE_UNLOCKING
} state_t;

state_t state = STATE_IDLE;

struct gpiod_line *in1, *in2, *in3, *in4;
struct gpiod_line *lock_button, *unlock_button;

void gpio_init() {
    int fd;
    struct gpiod_line_config config;

    // Initialize IN1 (GPIO4)
    memset(&config, 0, sizeof(config));
    config.line = GPIO_IN1;
    config.direction = GPIOD_LINE_DIRECTION_OUTPUT;
    config.output_value = 0;
    fd = gpiod_line_get("/dev/gpiochip0", &config);
    if (fd < 0) {
        perror("Failed to get IN1 line");
        exit(EXIT_FAILURE);
    }
    in1 = gpiod_line_get_from_fd(fd);
    if (!in1) {
        perror("Failed to get IN1 line from fd");
        exit(EXIT_FAILURE);
    }

    // Initialize IN2 (GPIO17)
    memset(&config, 0, sizeof(config));
    config.line = GPIO_IN2;
    config.direction = GPIOD_LINE_DIRECTION_OUTPUT;
    config.output_value = 0;
    fd = gpiod_line_get("/dev/gpiochip0", &config);
    if (fd < 0) {
        perror("Failed to get IN2 line");
        exit(EXIT_FAILURE);
    }
    in2 = gpiod_line_get_from_fd(fd);
    if (!in2) {
        perror("Failed to get IN2 line from fd");
        exit(EXIT_FAILURE);
    }

    // Initialize IN3 (GPIO27)
    memset(&config, 0, sizeof(config));
    config.line = GPIO_IN3;
    config.direction = GPIOD_LINE_DIRECTION_OUTPUT;
    config.output_value = 0;
    fd = gpiod_line_get("/dev/gpiochip0", &config);
    if (fd < 0) {
        perror("Failed to get IN3 line");
        exit(EXIT_FAILURE);
    }
    in3 = gpiod_line_get_from_fd(fd);
    if (!in3) {
        perror("Failed to get IN3 line from fd");
        exit(EXIT_FAILURE);
    }

    // Initialize IN4 (GPIO22)
    memset(&config, 0, sizeof(config));
    config.line = GPIO_IN4;
    config.direction = GPIOD_LINE_DIRECTION_OUTPUT;
    config.output_value = 0;
    fd = gpiod_line_get("/dev/gpiochip0", &config);
    if (fd < 0) {
        perror("Failed to get IN4 line");
        exit(EXIT_FAILURE);
    }
    in4 = gpiod_line_get_from_fd(fd);
    if (!in4) {
        perror("Failed to get IN4 line from fd");
        exit(EXIT_FAILURE);
    }

    // Initialize LOCK button (GPIO24) with pull-up
    memset(&config, 0, sizeof(config));
    config.line = GPIO_LOCK_BUTTON;
    config.direction = GPIOD_LINE_DIRECTION_INPUT;
    config.edge = GPIOD_LINE_EDGE_BOTH;
    config.consumer = "lock_button";
    config.flags = GPIOD_LINE_FLAG_ACTIVE_LOW | GPIOD_LINE_FLAG_BIAS_PULL_UP;
    fd = gpiod_line_get("/dev/gpiochip0", &config);
    if (fd < 0) {
        perror("Failed to get LOCK button line");
        exit(EXIT_FAILURE);
    }
    lock_button = gpiod_line_get_from_fd(fd);
    if (!lock_button) {
        perror("Failed to get LOCK button line from fd");
        exit(EXIT_FAILURE);
    }

    // Initialize UNLOCK button (GPIO23) with pull-up
    memset(&config, 0, sizeof(config));
    config.line = GPIO_UNLOCK_BUTTON;
    config.direction = GPIOD_LINE_DIRECTION_INPUT;
    config.edge = GPIOD_LINE_EDGE_BOTH;
    config.consumer = "unlock_button";
    config.flags = GPIOD_LINE_FLAG_ACTIVE_LOW | GPIOD_LINE_FLAG_BIAS_PULL_UP;
    fd = gpiod_line_get("/dev/gpiochip0", &config);
    if (fd < 0) {
        perror("Failed to get UNLOCK button line");
        exit(EXIT_FAILURE);
    }
    unlock_button = gpiod_line_get_from_fd(fd);
    if (!unlock_button) {
        perror("Failed to get UNLOCK button line from fd");
        exit(EXIT_FAILURE);
    }
}

void gpio_deinit() {
    gpiod_line_put(in1);
    gpiod_line_put(in2);
    gpiod_line_put(in3);
    gpiod_line_put(in4);
    gpiod_line_put(lock_button);
    gpiod_line_put(unlock_button);
}

void set_step_sequence(int step) {
    switch (step % 4) {
        case 0:
            gpiod_line_set_value(in1, 1);
            gpiod_line_set_value(in2, 0);
            gpiod_line_set_value(in3, 0);
            gpiod_line_set_value(in4, 0);
            break;
        case 1:
            gpiod_line_set_value(in1, 0);
            gpiod_line_set_value(in2, 1);
            gpiod_line_set_value(in3, 0);
            gpiod_line_set_value(in4, 0);
            break;
        case 2:
            gpiod_line_set_value(in1, 0);
            gpiod_line_set_value(in2, 0);
            gpiod_line_set_value(in3, 1);
            gpiod_line_set_value(in4, 0);
            break;
        case 3:
            gpiod_line_set_value(in1, 0);
            gpiod_line_set_value(in2, 0);
            gpiod_line_set_value(in3, 0);
            gpiod_line_set_value(in4, 1);
            break;
    }
}

void rotate_motor(int direction) {
    int i;
    for (i = 0; i < STEPS; i++) {
        set_step_sequence(i);
        usleep(STEP_DELAY_MS * 1000);
        gpiod_line_set_value(in1, 0);
        gpiod_line_set_value(in2, 0);
        gpiod_line_set_value(in3, 0);
        gpiod_line_set_value(in4, 0);
        usleep(STEP_DELAY_MS * 1000);
    }
}

void handle_button_press() {
    if (state != STATE_IDLE) {
        return;
    }

    if (gpiod_line_get_value(lock_button) == 0) {
        printf("Lock button pressed\n");
        state = STATE_LOCKING;
        rotate_motor(1);
        state = STATE_IDLE;
    } else if (gpiod_line_get_value(unlock_button) == 0) {
        printf("Unlock button pressed\n");
        state = STATE_UNLOCKING;
        rotate_motor(-1);
        state = STATE_IDLE;
    }
}

void handle_signal(int sig) {
    if (sig == SIGINT) {
        printf("Received SIGINT, de-energizing coils...\n");
        gpiod_line_set_value(in1, 0);
        gpiod_line_set_value(in2, 0);
        gpiod_line_set_value(in3, 0);
        gpiod_line_set_value(in4, 0);
        gpio_deinit();
        exit(EXIT_SUCCESS);
    }
}

int main() {
    signal(SIGINT, handle_signal);

    if (gpiod_init() < 0) {
        perror("Failed to initialize libgpiod");
        exit(EXIT_FAILURE);
    }

    gpio_init();

    while (1) {
        handle_button_press();
        usleep(DEBOUNCE_DELAY_MS * 1000);
    }

    gpio_deinit();
