#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

#define I2C_BUS "/dev/i2c-1"
#define MPU6050_ADDR 0x68
#define MPU6050_ACCEL_XOUT_H 0x3B
#define MPU6050_GYRO_XOUT_H 0x43
#define MPU6050_PWR_MGMT_1 0x6B
#define MPU6050_GYRO_CONFIG 0x1B
#define MPU6050_SMPLRT_DIV 0x19
#define MPU6050_CONFIG 0x1A
#define MPU6050_DLPF_CONFIG 0x1F
#define MPU6050_ACCEL_CONFIG 0x1C
#define MPU6050_GYRO_CONFIG_2 0x1D
#define MPU6050_FIFO_R_W 0x7A
#define MPU6050_WHO_AM_I 0x75

#define GYRO_SCALE 131.0f  // 131 LSB per dps for ±2000 dps range

typedef struct {
    int fd;
    int running;
} i2c_context;

void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        printf("\nCaught signal %d, shutting down...\n", signum);
        ((i2c_context*)gpiod_data())->running = 0;
    }
}

void i2c_init(i2c_context *ctx) {
    ctx->fd = open(I2C_BUS, O_RDWR);
    if (ctx->fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    if (ioctl(ctx->fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(ctx->fd);
        exit(EXIT_FAILURE);
    }

    // Wake up the MPU-6050
    unsigned char wake_up[] = {MPU6050_PWR_MGMT_1, 0x00}; // Wake up from sleep
    if (write(ctx->fd, wake_up, 2) != 2) {
        perror("Failed to wake up MPU-6050");
        close(ctx->fd);
        exit(EXIT_FAILURE);
    }

    // Set gyroscope range to ±2000 dps
    unsigned char gyro_config[] = {MPU6050_GYRO_CONFIG, 0x18};
    if (write(ctx->fd, gyro_config, 2) != 2) {
        perror("Failed to set gyroscope range");
        close(ctx->fd);
        exit(EXIT_FAILURE);
    }

    // Set sample rate divider to 0 (1kHz)
    unsigned char smplrt_div[] = {MPU6050_SMPLRT_DIV, 0x07};
    if (write(ctx->fd, smplrt_div, 2) != 2) {
        perror("Failed to set sample rate divider");
        close(ctx->fd);
        exit(EXIT_FAILURE);
    }

    // Set DLPF bandwidth to 42 Hz
    unsigned char dlpf_config[] = {MPU6050_DLPF_CONFIG, 0x0D};
    if (write(ctx->fd, dlpf_config, 2) != 2) {
        perror("Failed to set DLPF configuration");
        close(ctx->fd);
        exit(EXIT_FAILURE);
    }

    // Set gyroscope configuration 2 to disable FIFO
    unsigned char gyro_config2[] = {MPU6050_GYRO_CONFIG_2, 0x00};
    if (write(ctx->fd, gyro_config2, 2) != 2) {
        perror("Failed to set gyroscope configuration 2");
        close(ctx->fd);
        exit(EXIT_FAILURE);
    }
}

void i2c_deinit(i2c_context *ctx) {
    if (ctx->fd >= 0) {
        close(ctx->fd);
    }
}

void read_gyro_data(i2c_context *ctx, int *x, int *y, int *z) {
    unsigned char reg = MPU6050_GYRO_XOUT_H;
    if (write(ctx->fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return;
    }

    unsigned char data[6];
    if (read(ctx->fd, data, 6) != 6) {
        perror("Failed to read gyroscope data");
        return;
    }

    *x = (data[0] << 8) | data[1];
    *y = (data[2] << 8) | data[3];
    *z = (data[4] << 8) | data[5];
}

int main() {
    i2c_context ctx = {0};
    ctx.running = 1;

    // Set up signal handlers
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Initialize I2C
    if (i2c_init(&ctx) != 0) {
        fprintf(stderr, "I2C initialization failed\n");
        return EXIT_FAILURE;
    }

    printf("MPU-6050 gyroscope data logging started...\n");

    while (ctx.running) {
        int x, y, z;
        read_gyro_data(&ctx, &x, &y, &z);

        float x_degps = x * GYRO_SCALE;
        float y_degps = y * GYRO_SCALE;
        float z_degps = z * GYRO_SCALE;

        printf("Gyro: X=%.2f, Y=%.2f, Z=%.2f deg/s\n", x_degps, y_degps, z_degps);

        usleep(100000); // 100 ms delay
    }

    i2c_deinit(&ctx);
    printf("MPU-6050 gyroscope data logging stopped.\n");

    return EXIT_SUCCESS;
}

