#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define GPIO_LINES_COUNT 4
#define GPIO_LINES_BCM [4] = {17, 18, 27, 22}
#define RELAY_DURATION 5
#define CYCLE_INTERVAL 60
#define CYCLE_LOG_INTERVAL 86400

typedef struct {
    gpiod_line *lines[GPIO_LINES_COUNT];
    gpiod_chip *chip;
    FILE *log_file;
    int running;
} watering_state;

void handle_signal(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        printf("Received signal, shutting down...\n");
        exit(EXIT_SUCCESS);
    }
}

void log_cycle_start(const char *filename) {
    time_t now;
    struct tm *timeinfo;
    char buffer[80];

    time(&now);
    timeinfo = localtime(&now);
    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", timeinfo);

    FILE *file = fopen(filename, "a");
    if (!file) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }

    fprintf(file, "%s\n", buffer);
    fclose(file);
}

void init_gpio(watering_state *state) {
    state->chip = gpiod_chip_open("/dev/gpiochip0");
    if (!state->chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < GPIO_LINES_COUNT; i++) {
        state->lines[i] = gpiod_chip_get_line(state->chip, GPIO_LINES_BCM[i]);
        if (!state->lines[i]) {
            perror("Failed to get GPIO line");
            exit(EXIT_FAILURE);
        }

        int line_flags = GPIOD_LINE_FLAG_ACTIVE_LOW;
        if (gpiod_line_request_output(state->lines[i], "relay", line_flags, 1) < 0) {
            perror("Failed to request GPIO line as output");
            exit(EXIT_FAILURE);
        }

        if (gpiod_line_set_value(state->lines[i], 1) < 0) {
            perror("Failed to set GPIO line to HIGH");
            exit(EXIT_FAILURE);
        }
    }
}

void release_gpio(watering_state *state) {
    for (int i = 0; i < GPIO_LINES_COUNT; i++) {
        if (state->lines[i]) {
            gpiod_line_release(state->lines[i]);
            state->lines[i] = NULL;
        }
    }

    if (state->chip) {
        gpiod_chip_close(state->chip);
        state->chip = NULL;
    }
}

void init_logging(watering_state *state) {
    state->log_file = fopen("watering_log.txt", "a");
    if (!state->log_file) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }
}

void release_logging(watering_state *state) {
    if (state->log_file) {
        fclose(state->log_file);
        state->log_file = NULL;
    }
}

void water_relays(watering_state *state) {
    for (int i = 0; i < GPIO_LINES_COUNT; i++) {
        gpiod_line_set_value(state->lines[i], 0); // Activate relay (active-low)
        usleep(RELAY_DURATION * 100000); // 5 seconds
        gpiod_line_set_value(state->lines[i], 1); // Deactivate relay
    }
}

int main() {
    watering_state state = {0};

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    init_gpio(&state);
    init_logging(&state);

    time_t last_cycle_start = time(NULL);
    time_t current_time;

    while (state.running) {
        current_time = time(NULL);
        if (current_time - last_cycle_start >= CYCLE_LOG_INTERVAL) {
            log_cycle_start("watering_log.txt");
            last_cycle_start = current_time;
        }

        water_relays(&state);
        usleep(CYCLE_INTERVAL * 100000); // 60 seconds
    }

    release_gpio(&state);
    release_logging(&state);

    return 0;
}

