        if (pwm_ctx.fd < 0) {
            log_event("Failed to open PWM device");
            exit(EXIT_FAILURE);
        }

        // Set the PWM frequency
        struct pwm_config config;
        config.period = 1000000 / PWM_FREQUENCY;  // 1000000 ns per second
