            log_event("Failed to set PWM configuration");
            close(pwm_ctx.fd);
            exit(EXIT_FAILURE);
        }

        // Set the PWM channel
        if (ioctl(pwm_ctx.fd, PWM_SET_CHANNEL, &pwm_channel) < 0) {
            log_event("Failed to set PWM channel");
            close(pwm_ctx.fd);
            exit(EXIT_FAILURE);
        }

