#include <gpiod.h>
#include <time.h>

#define I2C_BUS 1
#define I2C_ADDR 0x68
#define LED_PIN 17
#define BUFFER_SIZE 100
#define MAX_RETRIES 3
#define THRESHOLD 250

typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
    struct timespec timestamp;
} GyroData;

typedef struct {
    GyroData buffer[BUFFER_SIZE];
    int head;
    int tail;
    int full;
} CircularBuffer;

void init_gyro(int *fd, int *retry_count);
void read_gyro_data(int fd, GyroData *data);
void init_led(gpiod_line *led_line);
void handle_signal(int signum);
void cleanup(int fd, gpiod_line *led_line);
void print_error(const char *msg);

int main() {
    int i2c_fd = -1;
    int retry_count = 0;
    int error = 0;
    CircularBuffer buffer = {0};
    gpiod_line *led_line = NULL;
    struct sigaction sa;

    // Initialize circular buffer
    buffer.head = 0;
    buffer.tail = 0;
    buffer.full = 0;

    // Set up signal handling
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        print_error("Failed to set up SIGINT handler");
        exit(EXIT_FAILURE);
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        print_error("Failed to set up SIGTERM handler");
        exit(EXIT_FAILURE);
    }

    // Initialize I2C
    init_gyro(&i2c_fd, &retry_count);

    // Initialize LED
    init_led(led_line);

    // Main loop
    while (1) {
        GyroData data = {0};
        read_gyro_data(i2c_fd, &data);

        // Update circular buffer
        if (buffer.full) {
            buffer.tail = (buffer.tail + 1) % BUFFER_SIZE;
        }
        buffer.buffer[buffer.head] = data;
        buffer.head = (buffer.head + 1) % BUFFER_SIZE;
        buffer.full = (buffer.head == buffer.tail);

        // Check if any axis exceeds threshold
        if (abs(data.x) > THRESHOLD || abs(data.y) > THRESHOLD || abs(data.z) > THRESHOLD) {
            gpiod_line_set_value(led_line, 1);
        } else {
            gpiod_line_set_value(led_line, 0);
        }

        // Sleep for 50ms
        usleep(50000);
    }

    // Cleanup (should not reach here normally)
    cleanup(i2c_fd, led_line);
    return 0;
}

void init_gyro(int *fd, int *retry_count) {
    char i2c_bus_path[32];
    snprintf(i2c_bus_path, sizeof(i2c_bus_path), "/dev/i2c-%d", I2C_BUS);

    *fd = open(i2c_bus_path, O_RDWR);
    if (*fd < 0) {
        print_error("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    if (ioctl(*fd, I2C_TEN, 0) < 0) {
        print_error("Failed to set I2C to 10-bit mode");
        close(*fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(*fd, I2C_ADDR, I2C_ADDR) < 0) {
        print_error("Failed to set I2C address");
        close(*fd);
        exit(EXIT_FAILURE);
    }

    // Set gyroscope to 200Hz sample rate and 250 deg/s range
    uint8_t config = 0x18;
    if (write(*fd, &config, 1) < 0) {
        print_error("Failed to write gyroscope configuration");
        close(*fd);
        exit(EXIT_FAILURE);
    }

    // Wait for configuration to take effect
    usleep(10000);
}

void read_gyro_data(int fd, GyroData *data) {
    uint8_t reg = 0x3B;
    uint8_t buffer[6];

    if (ioctl(fd, I2C_SLAVE, I2C_ADDR) < 0) {
        print_error("Failed to set I2C slave address");
        exit(EXIT_FAILURE);
    }

    if (read(fd, buffer, 6) < 0) {
        print_error("Failed to read gyroscope data");
        exit(EXIT_FAILURE);
    }

    data->x = (int16_t)(buffer[0] << 8 | buffer[1]);
    data->y = (int16_t)(buffer[2] << 8 | buffer[3]);
    data->z = (int16_t)(buffer[4] << 8 | buffer[5]);

    clock_gettime(CLOCK_MONOTONIC, &data->timestamp);
}

void init_led(gpiod_line *led_line) {
    struct gpiod_line_config config = {0};
    struct gpiod_chip *chip;

    chip = gpiod_chip_open("/dev/gpiochip4");
    if (!chip) {
        print_error("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    config.consumer = "gyro_led";
    config.line_offset = LED_PIN;
    config.flags = GPIOD_LINE_FLAG_BIAS_PULL_DOWN;

    *led_line = gpiod_line_request(chip, &config);
    if (!*led_line) {
        print_error("Failed to request LED GPIO line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    gpiod_line_set_value(*led_line, 0);
}

void handle_signal(int signum) {
    // Ignore the signal to prevent interruption during I2C operations
    // Actual cleanup is done in the cleanup function
}

void cleanup(int fd, gpiod_line *led_line) {
    if (fd >= 0) {
        close(fd);
    }

    if (*led_line) {
        gpiod_line_set_value(*led_line, 0);
        gpiod_line_release(*led_line);
    }

    // Additional cleanup if needed
}

void print_error(const char *msg) {
    fprintf(stderr, "Error: %s\n", msg);
    exit(EXIT_FAILURE);
}

