#include <gpiod.h>
#include <signal.h>
#include <time.h>

#define SPI_BUS 0
#define SPI_CHIP 0
#define SPI_SPEED 3900000
#define SPI_MODE SPI_MODE_0
#define BUFFER_SIZE 64
#define LED_PIN 17
#define THRESHOLD 200
#define BLINK_INTERVAL_MS 500

typedef struct {
    uint64_t timestamp;
    int16_t x;
    int16_t y;
    int16_t z;
} Sample;

typedef struct {
    Sample buffer[BUFFER_SIZE];
    int head;
    int tail;
    int full;
} CircularBuffer;

CircularBuffer cb = {0};

volatile int running = 1;

void handle_sigint(int sig) {
    running = 0;
}

void init_spi(int *spi_fd) {
    char spi_path[32];
    snprintf(spi_path, sizeof(spi_path), "/dev/spidev%d.%d", SPI_BUS, SPI_CHIP);

    *spi_fd = open(spi_path, O_RDWR | O_NOCTTY | O_NDELAY);
    if (*spi_fd < 0) {
        perror("Failed to open SPI device");
        exit(EXIT_FAILURE);
    }

    struct spi_ioc_transfer spi;
    memset(&spi, 0, sizeof(spi));
    spi.speed_hz = SPI_SPEED;
    spi.mode = SPI_MODE;
    spi.bits_per_word = 8;

    if (ioctl(*spi_fd, SPI_IOC_MESSAGE(1), &spi) < 0) {
        perror("SPI initialization failed");
        close(*spi_fd);
        exit(EXIT_FAILURE);
    }
}

void init_gpio() {
    struct gpiod_line *led_line;
    struct gpiod_line *cs_line;

    led_line = gpiod_line_get("BCM", LED_PIN, "led");
    if (!led_line) {
        perror("Failed to get LED GPIO line");
        exit(EXIT_FAILURE);
    }

    cs_line = gpiod_line_get("BCM", 8, "cs");
    if (!cs_line) {
        perror("Failed to get CS GPIO line");
        gpiod_line_put(led_line);
        exit(EXIT_FAILURE);
    }

    gpiod_line_request_output(led_line, "led", GPIOD_LINE_REQUEST_OUTPUT_ACTIVE_LOW);
    gpiod_line_request_output(cs_line, "cs", GPIOD_LINE_REQUEST_OUTPUT_ACTIVE_LOW);

    gpiod_line_set_value(cs_line, 1);
    gpiod_line_put(cs_line);
}

void read_mpu6050(int spi_fd) {
    uint8_t tx[6] = {0x43, 0x00, 0x00, 0x00, 0x00, 0x00};
    uint8_t rx[6];

    gpiod_line_set_value(cs_line, 0);
    if (write(spi_fd, tx, 6) != 6) {
        perror("SPI write failed");
        return;
    }

    if (read(spi_fd, rx, 6) != 6) {
        perror("SPI read failed");
        gpiod_line_set_value(cs_line, 1);
        return;
    }

    gpiod_line_set_value(cs_line, 1);

    int16_t x = (rx[0] << 8) | rx[1];
    int16_t y = (rx[2] << 8) | rx[3];
    int16_t z = (rx[4] << 8) | rx[5];

    if (x < -32768 || x > 32767 || y < -32768 || y > 32767 || z < -32768 || z > 32767) {
        return;
    }

    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    cb.buffer[cb.head].timestamp = ts.tv_sec * 1000000000 + ts.tv_nsec;
    cb.buffer[cb.head].x = x;
    cb.buffer[cb.head].y = y;
    cb.buffer[cb.head].z = z;

    cb.head = (cb.head + 1) % BUFFER_SIZE;
    if (cb.head == cb.tail) {
        cb.full = 1;
    }
}

void check_thresholds() {
    if (cb.full) {
        for (int i = 0; i < BUFFER_SIZE; i++) {
            if (abs(cb.buffer[i].x) > THRESHOLD || abs(cb.buffer[i].y) > THRESHOLD || abs(cb.buffer[i].z) > THRESHOLD) {
                gpiod_line_set_value(led_line, 0);
                usleep(500000);
                gpiod_line_set_value(led_line, 1);
                usleep(500000);
            }
        }
    } else {
        if (abs(cb.buffer[cb.tail].x) > THRESHOLD || abs(cb.buffer[cb.tail].y) > THRESHOLD || abs(cb.buffer[cb.tail].z) > THRESHOLD) {
            gpiod_line_set_value(led_line, 0);
            usleep(500000);
            gpiod_line_set_value(led_line, 1);
            usleep(500000);
        }
    }
}

void cleanup() {
    if (led_line) {
        gpiod_line_put(led_line);
    }
    if (cs_line) {
        gpiod_line_put(cs_line);
    }
    if (spi_fd >= 0) {
        close(spi_fd);
    }
}

void print_buffer_csv() {
    printf("Timestamp,X,Y,Z\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        printf("%lu,%d,%d,%d\n", cb.buffer[i].timestamp, cb.buffer[i].x, cb.buffer[i].y, cb.buffer[i].z);
    }
}

int main() {
    signal(SIGINT, handle_sigint);
    int spi_fd = -1;
    struct gpiod_line *led_line = NULL;
    struct gpiod_line *cs_line = NULL;

    init_spi(&spi_fd);
    init_gpio();

    while (running) {
        read_mpu6050(spi_fd);
        check_thresholds();
        usleep(10000);
    }

    cleanup();
    print_buffer_csv();

    return 0;
}

