#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <gpiod.h>
#include <signal.h>

#define I2C_BUS 1
#define MPU6050_ADDR 0x68
#define I2C_DEVICE "/dev/i2c-%d"
#define LED_PIN 21
#define SAMPLE_INTERVAL_MS 100
#define ROLL_THRESHOLD 45.0
#define PITCH_THRESHOLD 45.0

typedef struct {
    int16_t ax, ay, az;
    int16_t gx, gy, gz;
} mpu6050_data_t;

// Function to read from I2C device
int i2c_read(int fd, uint8_t reg, uint8_t *data, int len) {
    if (ioctl(fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        return -1;
    }

    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }

    if (read(fd, data, len) != len) {
        perror("Failed to read from I2C device");
        return -1;
    }

    return 0;
}

// Function to initialize MPU6050
int mpu6050_init(int fd) {
    uint8_t whoami = 0;
    if (i2c_read(fd, 0x75, &whoami, 1) < 0) {
        fprintf(stderr, "Failed to read WHO_AM_I register\n");
        return -1;
    }

    if (whoami != 0x68) {
