#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDR 0x5A
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10
#define LED_PIN 17  // BCM numbering

typedef struct {
    int fd;
    struct gpiod_line *led_line;
    FILE *log_file;
} AppContext;

void handle_signal(int signum, siginfo_t *info, void *context) {
    (void)context;
    (void)info;
    if (signum == SIGINT || signum == SIGTERM) {
        AppContext *ctx = (AppContext *)context;
        if (ctx->log_file) {
            fclose(ctx->log_file);
        }
        if (ctx->fd >= 0) {
            close(ctx->fd);
        }
        if (ctx->led_line) {
            gpiod_line_set_value(ctx->led_line, 0);
            gpiod_line_release(ctx->led_line);
        }
        exit(EXIT_SUCCESS);
    }
}

void init_gpio(AppContext *ctx) {
    struct gpiod_chip *chip;
    chip = gpiod_chip_open("/dev/gpiochip4");
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    ctx->led_line = gpiod_line_request_output(chip, "presence_led", LED_PIN, GPIOD_LINE_REQUEST_FLAG_ACTIVE_LOW);
    if (!ctx->led_line) {
        perror("Failed to request GPIO line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    gpiod_line_set_value(ctx->led_line, 0);
    gpiod_chip_close(chip);
}

void init_i2c(AppContext *ctx) {
    ctx->fd = open(I2C_BUS, O_RDWR);
    if (ctx->fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    if (ioctl(ctx->fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(ctx->fd);
        exit(EXIT_FAILURE);
    }
}

void close_app(AppContext *ctx) {
    if (ctx->log_file) {
        fclose(ctx->log_file);
    }
    if (ctx->fd >= 0) {
        close(ctx->fd);
    }
    if (ctx->led_line) {
        gpiod_line_set_value(ctx->led_line, 0);
        gpiod_line_release(ctx->led_line);
    }
}

void log_data(AppContext *ctx, int ambient, int proximity) {
    time_t now;
    struct tm *timeinfo;
    char timestamp[20];

    time(&now);
    timeinfo = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(ctx->log_file, "%s,AmbientLight:%d,Proximity:%d\n", timestamp, ambient, proximity);
    fflush(ctx->log_file);
}

int read_si1145(AppContext *ctx) {
    unsigned char reg = 0x00;  // Ambient light register
    unsigned char buf[2];

    for (int i = 0; i < MAX_RETRIES; i++) {
        if (write(ctx->fd, &reg, 1) != 1) {
            perror("I2C write failed");
            usleep(RETRY_DELAY_MS * 1000);
            continue;
        }

        if (read(ctx->fd, buf, 2) != 2) {
            perror("I2C read failed");
            usleep(RETRY_DELAY_MS * 1000);
            continue;
        }

        int ambient = (buf[0] << 8) | buf[1];
        reg = 0x02;  // Proximity register
        if (write(ctx->fd, &reg, 1) != 1) {
            perror("I2C write failed");
            usleep(RETRY_DELAY_MS * 1000);
            continue;
        }

        if (read(ctx->fd, buf, 2) != 2) {
            perror("I2C read failed");
            usleep(RETRY_DELAY_MS * 1000);
            continue;
        }

        int proximity = (buf[0] << 8) | buf[1];

        log_data(ctx, ambient, proximity);

        if (proximity > 100) {
            gpiod_line_set_value(ctx->led_line, 1);
        } else {
            gpiod_line_set_value(ctx->led_line, 0);
        }

        return 0;
    }

    return -1;
}

int main() {
    AppContext ctx = {0};

    init_gpio(&ctx);
    init_i2c(&ctx);

    ctx.log_file = fopen("biometric_log.txt", "a");
    if (!ctx.log_file) {
        perror("Failed to open log file");
        close_app(&ctx);
        exit(EXIT_FAILURE);
    }

    struct sigaction sa;
    sa.sa_sigaction = handle_signal;
    sa.sa_flags = SA_SIGINFO;
    sigemptyset(&sa.sa_mask);

    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Failed to install signal handler");
        close_app(&ctx);
        exit(EXIT_FAILURE);
    }

    while (1) {
        if (read_si1145(&ctx) != 0) {
            usleep(100000);  // 100 ms
        } else {
            usleep(100000);  // 100 ms
        }
    }

    close_app(&ctx);
    return 0;
}

