typedef struct {
    int spi_fd;
    struct gpiod_line *ce_line;
    FILE *csv_file;
    int retry_count;
} GyroContext;

void signal_handler(int signum) {
    if (signum == SIGINT) {
        if (context.csv_file) {
            fprintf(context.csv_file, "\n");
            fflush(context.csv_file);
            fclose(context.csv_file);
        }
        if (context.spi_fd >= 0) {
            close(context.spi_fd);
        }
        if (context.ce_line) {
            gpiod_line_release(context.ce_line);
        }
        exit(EXIT_SUCCESS);
    }
}

int init_spi() {
    int fd = open(SPI_DEVICE, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    struct spi_ioc_transfer spi = {
        .tx_buf = 0,
        .rx_buf = 0,
        .len = 0,
        .speed_hz = SPI_SPEED,
        .mode = SPI_MODE,
    };

    if (ioctl(fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("Failed to set SPI mode");
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("Failed to set SPI speed");
        close(fd);
        return -1;
    }

