#define GPIO_ALERT_PIN 17
#define GPIO_SENSOR1_PIN 23
#define GPIO_SENSOR2_PIN 24
#define ALERT_DURATION 2000  // 2 seconds
#define SEISMIC_HOLD_TIME 500  // 500 ms
#define LOG_FILE "seismic_events.txt"

typedef struct {
    int sensor1_high_count;
    int sensor2_high_count;
    struct timespec last_high_time;
    int alert_active;
    gpiod_line *alert_line;
    FILE *log_file;
} app_state;

void handle_signal(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        printf("Caught signal %d, cleaning up...\n", signum);
        if (app_state.log_file) {
            fclose(app_state.log_file);
        }
        if (app_state.alert_active) {
            gpiod_line_set_value(app_state.alert_line, 0);
        }
        gpiod_chip_close(app_state.alert_line->chip);
        exit(EXIT_SUCCESS);
    }
}

void callback_handler(gpiod_line *line, const struct timespec *timestamp, void *data) {
    app_state *state = (app_state *)data;
    int value = gpiod_line_get_value(line);

    if (line == gpiod_line_get_line(state->alert_line)) {
        // Alert pin is being toggled, but this is not a sensor
        return;
    }

    if (value == 1) {
        if (line == gpiod_line_get_line(state->sensor1_pin)) {
            state->sensor1_high_count++;
        } else if (line == gpiod_line_get_line(state->sensor2_pin)) {
            state->sensor2_high_count++;
        }
    } else {
        if (line == gpiod_line_get_line(state->sensor1_pin)) {
            state->sensor1_high_count = 0;
        } else if (line == gpiod_line_get_line(state->sensor2_pin)) {
            state->sensor2_high_count = 0;
        }
    }

    // Check if both sensors are high for at least 500ms
    if (state->sensor1_high_count > 0 && state->sensor2_high_count > 0) {
        if (state->last_high_time.tv_sec == 0 || 
            (timestamp->tv_sec - state->last_high_time.tv_sec) * 1000 + (timestamp->tv_nsec / 1e6) >= SEISMIC_HOLD_TIME) {
            state->last_high_time = *timestamp;
            state->sensor1_high_count = 0;
            state->sensor2_high_count = 0;

            if (!state->alert_active) {
                gpiod_line_set_value(state->alert_line, 1);
                state->alert_active = 1;
                time_t now = time(NULL);
                struct tm *tm_info = localtime(&now);
                char timestamp_str[64];
                strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%dT%H:%M:%S", tm_info);
                fprintf(state->log_file, "%s - Seismic event detected!\n");
                fflush(state->log_file);
            }
        }
    } else {
        state->last_high_time.tv_sec = 0;
        state->last_high_time.tv_nsec = 0;
    }
}

