    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    // Configure sensor1 (GPIO23)
    sensor1_line = gpiod_chip_get_line(chip, GPIO_SENSOR1_PIN);
    if (!sensor1_line) {
        perror("gpiod_chip_get_line (sensor1)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }
    if (gpiod_line_request_output(sensor1_line, "sensor1", 0) < 0) {
        perror("gpiod_line_request_output (sensor1)");
        gpiod_line_release(sensor1_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }
    gpiod_line_set_edge_detection(sensor1_line, GPIOD_EDGE_BOTH);
    gpiod_line_set_debounce_time(sensor1_line, 2000000); // 2ms debounce
    if (gpiod_line_event_register(sensor1_line, callback_handler, &state) < 0) {
        perror("gpiod_line_event_register (sensor1)");
        gpiod_line_release(sensor1_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Configure sensor2 (GPIO24)
    sensor2_line = gpiod_chip_get_line(chip, GPIO_SENSOR2_PIN);
    if (!sensor2_line) {
        perror("gpiod_chip_get_line (sensor2)");
        gpiod_line_release(sensor1_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }
    if (gpiod_line_request_output(sensor2_line, "sensor2", 0) < 0) {
        perror("gpiod_line_request_output (sensor2)");
        gpiod_line_release(sensor2_line);
        gpiod_line_release(sensor1_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }
    gpiod_line_set_edge_detection(sensor2_line, GPIOD_EDGE_BOTH);
    gpiod_line_set_debounce_time(sensor2_line, 2000000); // 2ms debounce
    if (gpiod_line_event_register(sensor2_line, callback_handler, &state) < 0) {
        perror("gpiod_line_event_register (sensor2)");
        gpiod_line_release(sensor2_line);
        gpiod_line_release(sensor1_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Configure alert pin (GPIO17)
    alert_line = gpiod_chip_get_line(chip, GPIO_ALERT_PIN);
    if (!alert_line) {
        perror("gpiod_chip_get_line (alert)");
        gpiod_line_release(sensor2_line);
        gpiod_line_release(sensor1_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }
    if (gpiod_line_request_output(alert_line, "alert", 0) < 0) {
        perror("gpiod_line_request_output (alert)");
        gpiod_line_release(alert_line);
        gpiod_line_release(sensor2_line);
        gpiod_line_release(sensor1_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }
    gpiod_line_set_value(alert_line, 0);
    state.alert_line = alert_line;

    // Open log file
    state.log_file = fopen(LOG_FILE, "a");
    if (!state.log_file) {
        perror("fopen");
        gpiod_line_release(alert_line);
        gpiod_line_release(sensor2_line);
        gpiod_line_release(sensor1_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Main loop
    while (1) {
        sleep(1);
    }

    // Cleanup (should not reach here)
    gpiod_line_release(alert_line);
    gpiod_line_release(sensor2_line);
    gpiod_line_release(sensor1_line);
    gpiod_chip_close(chip);
    fclose(state.log_file);
    return EXIT_SUCCESS;
}

