#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <time.h>
#include <pthread.h>
#include <signal.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define SPI_MODE SPI_MODE_0
#define CE_PIN 8
#define SCLK_PIN 11
#define MOSI_PIN 10
#define MISO_PIN 9
#define LED_PIN 17
#define BUFFER_SIZE 100
#define THRESHOLD 20.0
#define REGISTER_ADDR 0x20  // Example register address for X-axis angular rate (MSB set for read)

typedef struct {
    double rate;
    struct timespec timestamp;
} Sample;

typedef struct {
    Sample buffer[BUFFER_SIZE];
    int head;
    int tail;
    int count;
    pthread_mutex_t mutex;
} CircularBuffer;

void init_buffer(CircularBuffer *cb) {
    cb->head = 0;
    cb->tail = 0;
    cb->count = 0;
    pthread_mutex_init(&cb->mutex, NULL);
}

void add_sample(CircularBuffer *cb, double rate) {
    pthread_mutex_lock(&cb->mutex);
    if (cb->count < BUFFER_SIZE) {
        cb->buffer[cb->head].rate = rate;
        clock_gettime(CLOCK_MONOTONIC, &cb->buffer[cb->head].timestamp);
        cb->head = (cb->head + 1) % BUFFER_SIZE;
        cb->count++;
    }
    pthread_mutex_unlock(&cb->mutex);
}

double get_average_rate(CircularBuffer *cb) {
    double sum = 0.0;
    int i;
    pthread_mutex_lock(&cb->mutex);
    for (i = 0; i < cb->count; i++) {
        sum += cb->buffer[(cb->tail + i) % BUFFER_SIZE].rate;
    }
    pthread_mutex_unlock(&cb->mutex);
    return sum / cb->count;
}

void spi_transfer(int fd, uint8_t *tx, uint8_t *rx, size_t len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = len,
        .speed_hz = SPI_SPEED,
        .mode = SPI_MODE,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI transfer failed");
        exit(EXIT_FAILURE);
    }
}

void read_gyro(int spi_fd, double *rate) {
    uint8_t tx[2] = {REGISTER_ADDR | 0x80, 0x00};  // Set MSB for read, send dummy byte
    uint8_t rx[2] = {0};

    spi_transfer(spi_fd, tx, rx, sizeof(tx));

    // Extract 16-bit data from rx[0] and rx[1]
    uint16_t data = (rx[0] << 8) | rx[1];
    *rate = (double)data * 0.00875;  // Convert to deg/s (based on ADXRS290 datasheet)
}

void setup_gpio() {
    struct gpiod_line *led_line;
    struct gpiod_line *ce_line;

    led_line = gpiod_line_get("gpio", LED_PIN, "led");
    if (!led_line) {
        perror("Failed to get LED line");
        exit(EXIT_FAILURE);
    }

    ce_line = gpiod_line_get("gpio", CE_PIN, "ce");
    if (!ce_line) {
        perror("Failed to get CE line");
        exit(EXIT_FAILURE);
    }

    gpiod_line_request_output(led_line, "led", GPIOD_LINE_REQUEST_OUTPUT_ACTIVE_LOW);
    gpiod_line_request_output(ce_line, "ce", GPIOD_LINE_REQUEST_OUTPUT_ACTIVE_LOW);

    gpiod_line_set_value(ce_line, 1);  // CE high
}

void set_led(int value) {
    gpiod_line_set_value(led_line, value);
}

void cleanup_gpio() {
    gpiod_line_release(led_line);
    gpiod_line_release(ce_line);
}

void setup_spi() {
    int spi_fd = open(SPI_DEVICE, O_RDWR | O_NOCTTY | O_SYNC);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &1) < 0) {
        perror("Failed to set bits per word");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    spi_fd_global = spi_fd;
}

void cleanup_spi() {
    close(spi_fd_global);
}

volatile int running = 1;

void signal_handler(int sig) {
    running = 0;
}

void monitor_gyro(CircularBuffer *cb) {
    double rate;
    while (running) {
        read_gyro(spi_fd_global, &rate);
        add_sample(cb, rate);

        if (rate > THRESHOLD) {
            set_led(0);  // Turn LED on
        } else {
            set_led(1);  // Turn LED off
        }

        usleep(10000);  // 10ms sampling interval
    }
}

int main() {
    CircularBuffer cb;
    init_buffer(&cb);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    setup_gpio();
    setup_spi();

    pthread_t thread;
    if (pthread_create(&thread, NULL, (void*)monitor_gyro, &cb) != 0) {
        perror("Failed to create thread");
        cleanup_gpio();
        cleanup_spi();
        exit(EXIT_FAILURE);
    }

    pthread_join(thread, NULL);

    cleanup_gpio();
    cleanup_spi();

    return 0;
}

