#include <sys/time.h>
#include <sys/types.h>
#include <linux/gpio.h>
#include <libgpiod.h>

#define BCM_PIN_17 17
#define BCM_PIN_18 18
#define BCM_PIN_27 27

#define PWM_FREQ 100
#define DUTY_CYCLE_RANGE 255

typedef struct {
    int pwm_fd;
    struct gpiod_line *line17;
    struct gpiod_line *line18;
    struct gpiod_line *line27;
    int duration;
    int fade_step;
    int current_duty;
    int lamp_index;
    int fade_complete;
} app_state;

void handle_signal(int sig) {
    (void)sig;
    printf("\nReceived signal. Shutting down...\n");
    exit(EXIT_SUCCESS);
}

void init_pwm(app_state *state) {
    int ret;

    state->pwm_fd = open("/dev/pwm", O_RDWR);
    if (state->pwm_fd < 0) {
        perror("Failed to open PWM device");
        exit(EXIT_FAILURE);
    }

    struct pwm_config config = {
        .pwm_freq = PWM_FREQ,
        .pwm_range = DUTY_CYCLE_RANGE
    };

    if (ioctl(state->pwm_fd, PWM_IOCTL_SET_CONFIG, &config) < 0) {
        perror("Failed to set PWM configuration");
        close(state->pwm_fd);
        exit(EXIT_FAILURE);
    }

    state->line17 = gpiod_line_get("/dev/gpiochip0", BCM_PIN_17);
    if (!state->line17) {
        perror("Failed to get GPIO line 17");
        close(state->pwm_fd);
        exit(EXIT_FAILURE);
    }

    state->line18 = gpiod_line_get("/dev/gpiochip0", BCM_PIN_18);
    if (!state->line18) {
        perror("Failed to get GPIO line 18");
        gpiod_line_put(state->line17);
        close(state->pwm_fd);
        exit(EXIT_FAILURE);
    }

    state->line27 = gpiod_line_get("/dev/gpiochip0", BCM_PIN_27);
    if (!state->line27) {
        perror("Failed to get GPIO line 27");
        gpiod_line_put(state->line17);
        gpiod_line_put(state->line18);
        close(state->pwm_fd);
        exit(EXIT_FAILURE);
    }

    gpiod_line_request_output(state->line17, "sunset_simulator", 0);
    gpiod_line_request_output(state->line18, "sunset_simulator", 0);
    gpiod_line_request_output(state->line27, "sunset_simulator", 0);

    state->fade_step = DUTY_CYCLE_RANGE / (state->duration * 1000);
    state->current_duty = 0;
    state->lamp_index = 0;
    state->fade_complete = 0;
}

void cleanup_pwm(app_state *state) {
    if (state->line17) {
        gpiod_line_put(state->line17);
    }
    if (state->line18) {
        gpiod_line_put(state->line18);
    }
    if (state->line27) {
        gpiod_line_put(state->line27);
    }
    if (state->pwm_fd >= 0) {
        close(state->pwm_fd);
    }
}

void set_pwm_duty_cycle(app_state *state, int duty) {
    if (ioctl(state->pwm_fd, PWM_IOCTL_SET_DUTY_CYCLE, duty) < 0) {
        perror("Failed to set PWM duty cycle");
    }
}

void fade_lamp(app_state *state, int lamp_index) {
    int duty = 0;
    int step = state->fade_step;
    int duration = state->duration * 1000;

    printf("Fading lamp %d from 100%% to 0%% over %d seconds...\n", lamp_index + 1, state->duration);

    for (int i = 0; i <= duration; i += step) {
        duty = (i * DUTY_CYCLE_RANGE) / duration;
        set_pwm_duty_cycle(state, duty);

        if (lamp_index == 0) {
            gpiod_line_set(state->line17, duty);
        } else if (lamp_index == 1) {
            gpiod_line_set(state->line18, duty);
        } else {
            gpiod_line_set(state->line27, duty);
        }

        usleep(step * 1000);
    }

    printf("Lamp %d faded to 0%%.\n", lamp_index + 1);
}

void run_sequence(app_state *state) {
    for (int i = 0; i < 3; i++) {
        fade_lamp(state, i);
    }

    printf("All lamps faded to 0%%. Simulation complete.\n");
    state->fade_complete = 1;
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <duration>\n", argv[0]);
        fprintf(stderr, "Duration must be an integer between 1 and 3600 seconds.\n");
        exit(EXIT_FAILURE);
    }

    int duration = atoi(argv[1]);
    if (duration < 1 || duration > 3600) {
        fprintf(stderr, "Duration must be an integer between 1 and 3600 seconds.\n");
        exit(EXIT_FAILURE);
    }

    app_state state = {0};

    printf("Starting smart sunset simulator...\n");
    printf("Lamps connected to BCM pins 17, 18, and 27.\n");
    printf("Fading each lamp from 100%% to 0%% over %d seconds.\n", duration);

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    init_pwm(&state);
    state.duration = duration;

    run_sequence(&state);

    cleanup_pwm(&state);

    printf("Smart sunset simulator exited successfully.\n");
    return 0;
}

