#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_RED 17
#define GPIO_YELLOW 22
#define GPIO_GREEN 23
#define GPIO_YELLOW2 24

typedef struct {
    struct gpiod_line *red_line;
    struct gpiod_line *yellow_line;
    struct gpiod_line *green_line;
    struct gpiod_line *yellow2_line;
} gpio_lines;

void handle_signal(int signum) {
    // Clean up GPIO lines
    if (signum == SIGINT || signum == SIGTERM) {
        printf("Signal received, cleaning up GPIO...\n");
        gpiod_line_release(gpio_lines.red_line);
        gpiod_line_release(gpio_lines.yellow_line);
        gpiod_line_release(gpio_lines.green_line);
        gpiod_line_release(gpio_lines.yellow2_line);
        exit(EXIT_SUCCESS);
    }
}

void setup_gpio(gpio_lines *gpio) {
    struct gpiod_chip *chip;
    int ret;

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    gpio->red_line = gpiod_line_request_output(chip, "red", GPIO_RED, 0);
    if (!gpio->red_line) {
        perror("Failed to request red GPIO line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    gpio->yellow_line = gpiod_line_request_output(chip, "yellow", GPIO_YELLOW, 0);
    if (!gpio->yellow_line) {
        perror("Failed to request yellow GPIO line");
        gpiod_line_release(gpio->red_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    gpio->green_line = gpiod_line_request_output(chip, "green", GPIO_GREEN, 0);
