#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>

#define I2C_BUS 1
#define I2C_ADDR 0x5A
#define TOUCH_ELECTRODE 0
#define GPIO_PIN 17
#define LOG_FILE "touch_relay.log"
#define TOUCH_DEBOUNCE_DELAY_MS 100
#define TOUCH_POLL_INTERVAL_MS 10

typedef enum {
    STATE_IDLE,
    STATE_TOUCHED,
    STATE_DEBOUNCING
} State;

typedef struct {
    int i2c_fd;
    struct gpiod_line *gpio_line;
    FILE *log_file;
    State state;
    time_t last_touch_time;
} AppContext;

void log_error(const char *message) {
    time_t now = time(NULL);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
    fprintf(stderr, "[%s] %s\n", timestamp, message);
}

void log_to_file(const char *message) {
    if (log_file) {
        time_t now = time(NULL);
        char timestamp[64];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
        fprintf(log_file, "[%s] %s\n", timestamp, message);
        fflush(log_file);
    }
}

void handle_signal(int signal) {
    log_to_file("Received signal, shutting down...");
    if (app_context.i2c_fd >= 0) {
        close(app_context.i2c_fd);
    }
    if (app_context.gpio_line) {
        gpiod_line_release(app_context.gpio_line);
    }
    if (app_context.log_file) {
        fclose(app_context.log_file);
    }
    exit(EXIT_SUCCESS);
}

int init_i2c() {
    char i2c_bus_path[32];
    snprintf(i2c_bus_path, sizeof(i2c_bus_path), "/dev/i2c-%d", I2C_BUS);

    int fd = open(i2c_bus_path, O_RDWR);
    if (fd < 0) {
        log_error("Failed to open I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_TEN, 0) < 0) {
        log_error("Failed to set I2C to 10-bit addressing");
        close(fd);
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, I2C_ADDR) < 0) {
        log_error("Failed to set I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

int init_gpio() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;

    chip = gpiod_chip_open("/dev/gpiochip17");
    if (!chip) {
        log_error("Failed to open GPIO chip");
        return -1;
    }

    line = gpiod_line_request_output(chip, "relay", GPIO_PIN, 0);
    if (!line) {
        log_error("Failed to request GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    app_context.gpio_line = line;
    return 0;
}

void read_touch_status() {
    uint8_t reg = 0x00;
    if (write(app_context.i2c_fd, &reg, 1) < 0) {
        log_error("Failed to write to I2C register");
        return;
    }

    if (read(app_context.i2c_fd, &reg, 1) < 0) {
        log_error("Failed to read from I2C register");
        return;
    }

    if (reg & (1 << TOUCH_ELECTRODE)) {
        log_to_file("Electrode 0 touched");
        if (app_context.state == STATE_IDLE) {
            app_context.state = STATE_TOUCHED;
            app_context.last_touch_time = time(NULL);
        } else if (app_context.state == STATE_DEBOUNCING) {
            time_t now = time(NULL);
            if (now - app_context.last_touch_time >= TOUCH_DEBOUNCE_DELAY_MS / 1000.0) {
                app_context.state = STATE_TOUCHED;
                app_context.last_touch_time = now;
            }
        }
    } else {
        if (app_context.state == STATE_TOUCHED) {
            app_context.state = STATE_DEBOUNCING;
            log_to_file("Electrode 0 released");
        }
    }
}

void toggle_relay() {
    int value = gpiod_line_get_value(app_context.gpio_line);
    if (value == 0) {
        gpiod_line_set_value(app_context.gpio_line, 1);
        log_to_file("Relay toggled to HIGH");
    } else {
        gpiod_line_set_value(app_context.gpio_line, 0);
        log_to_file("Relay toggled to LOW");
    }
}

int main() {
    AppContext app_context = {0};

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    app_context.log_file = fopen(LOG_FILE, "a");
    if (!app_context.log_file) {
        log_error("Failed to open log file");
        return EXIT_FAILURE;
    }

    app_context.i2c_fd = init_i2c();
    if (app_context.i2c_fd < 0) {
        return EXIT_FAILURE;
    }

    if (init_gpio() < 0) {
        return EXIT_FAILURE;
    }

    app_context.state = STATE_IDLE;
    app_context.last_touch_time = 0;

    while (1) {
        read_touch_status();

        if (app_context.state == STATE_TOUCHED) {
            toggle_relay();
            app_context.state = STATE_DEBOUNCING;
        }

        usleep(10000); // 10 ms
    }

    return EXIT_SUCCESS;
}

