    *fd = req.fd;
    if (direction == GPIO_DIRECTION_OUTPUT) {
        struct gpiohandle_data data = { .bits = 0 };
        if (ioctl(*fd, GPIOHANDLE_SET_LINE_VALUES_IOCTL, &data) < 0) {
            perror("Failed to set GPIO output value");
            close(*fd);
            exit(EXIT_FAILURE);
        }
    }
}

void set_gpio_value(int fd, int value) {
    struct gpiohandle_data data = { .bits = value };
    if (ioctl(fd, GPIOHANDLE_SET_LINE_VALUES_IOCTL, &data) < 0) {
        perror("Failed to set GPIO value");
        exit(EXIT_FAILURE);
    }
}

void close_gpio(int fd) {
    if (fd >= 0) {
        close(fd);
    }
}

void log_flame_detected() {
    time_t now = time(NULL);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
    fprintf(stdout, "Flame Detected at %s\n", timestamp);
    fprintf(stderr, "Flame Detected at %s\n", timestamp);
    if (app_state.log_file) {
        fprintf(app_state.log_file, "%s - Flame Detected\n", timestamp);
        fflush(app_state.log_file);
    }
}

void setup_gpio() {
    app_state.flame_fd = -1;
    app_state.buzzer_fd = -1;
    app_state.led_fd = -1;
    app_state.log_file = NULL;
    app_state.consecutive_low = 0;
    app_state.flame_state = 0;
    app_state.running = 1;

    // Initialize flame pin as input
    init_gpio(GPIO_FLAME_PIN, GPIO_DIRECTION_INPUT, &app_state.flame_fd);

    // Initialize buzzer pin as output
    init_gpio(GPIO_BUZZER_PIN, GPIO_DIRECTION_OUTPUT, &app_state.buzzer_fd);

    // Initialize LED pin as output
    init_gpio(GPIO_LED_PIN, GPIO_DIRECTION_OUTPUT, &app_state.led_fd);

    // Open log file
    app_state.log_file = fopen(LOG_FILE, "a");
    if (!app_state.log_file) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }
}

void cleanup_gpio() {
    close_gpio(app_state.flame_fd);
    close_gpio(app_state.buzzer_fd);
    close_gpio(app_state.led_fd);
    if (app_state.log_file) {
        fclose(app_state.log_file);
    }
}

void check_flame() {
    struct gpiohandle_data data;
    if (ioctl(app_state.flame_fd, GPIOHANDLE_GET_LINE_VALUES_IOCTL, &data) < 0) {
        perror("Failed to get GPIO line values");
        exit(EXIT_FAILURE);
    }

    int current_state = (data.bits & (1 << GPIO_FLAME_PIN)) ? 1 : 0;

    if (current_state == 0) {
        app_state.consecutive_low++;
        if (app_state.consecutive_low >= CONSECUTIVE_LOW_COUNT) {
            log_flame_detected();
            set_gpio_value(app_state.buzzer_fd, 1);
            set_gpio_value(app_state.led_fd, 1);
        }
    } else {
        app_state.consecutive_low = 0;
        set_gpio_value(app_state.buzzer_fd, 0);
        set_gpio_value(app_state.led_fd, 0);
    }
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    setup_gpio();

    while (app_state.running) {
        check_flame();
        usleep(50000); // 50 ms
    }

    cleanup_gpio();
    return 0;
}
