#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_MOTOR_A_FWD 17
#define GPIO_MOTOR_A_BWD 18
#define GPIO_MOTOR_B_FWD 22
#define GPIO_MOTOR_B_BWD 23
#define GPIO_ENA 24
#define GPIO_ENB 25

#define PWM_FREQ 1000
#define PID_UPDATE_INTERVAL_MS 50
#define LOG_FILE "balance_log.txt"
#define MIN_DISTANCE_CM 20.0
#define OBSTACLE_SPEED 127.5
#define MAX_SPEED 255
#define TILT_ERROR_MIN -10.0
#define TILT_ERROR_MAX 10.0
#define DISTANCE_MIN 2.0
#define DISTANCE_MAX 400.0

typedef struct {
    struct gpiod_line *motor_a_fwd;
    struct gpiod_line *motor_a_bwd;
    struct gpiod_line *motor_b_fwd;
    struct gpiod_line *motor_b_bwd;
    struct gpiod_line *ena;
    struct gpiod_line *enb;
    struct gpiod_line *pwm_a;
    struct gpiod_line *pwm_b;
} gpio_pins;

void init_gpio(gpio_pins *pins) {
    int ret;

    pins->motor_a_fwd = gpiod_line_get("gpiochip0", GPIO_MOTOR_A_FWD);
    if (!pins->motor_a_fwd) {
        fprintf(stderr, "Failed to get line %d\n", GPIO_MOTOR_A_FWD);
        exit(1);
    }

    pins->motor_a_bwd = gpiod_line_get("gpiochip0", GPIO_MOTOR_A_BWD);
    if (!pins->motor_a_bwd) {
        fprintf(stderr, "Failed to get line %d\n", GPIO_MOTOR_A_BWD);
        exit(1);
    }

    pins->motor_b_fwd = gpiod_line_get("gpiochip0", GPIO_MOTOR_B_FWD);
    if (!pins->motor_b_fwd) {
        fprintf(stderr, "Failed to get line %d\n", GPIO_MOTOR_B_FWD);
        exit(1);
    }

    pins->motor_b_bwd = gpiod_line_get("gpiochip0", GPIO_MOTOR_B_BWD);
    if (!pins->motor_b_bwd) {
        fprintf(stderr, "Failed to get line %d\n", GPIO_MOTOR_B_BWD);
        exit(1);
    }

    pins->ena = gpiod_line_get("gpiochip0", GPIO_ENA);
    if (!pins->ena) {
        fprintf(stderr, "Failed to get line %d\n", GPIO_ENA);
        exit(1);
    }

    pins->enb = gpiod_line_get("gpiochip0", GPIO_ENB);
    if (!pins->enb) {
        fprintf(stderr, "Failed to get line %d\n", GPIO_ENB);
        exit(1);
    }

    pins->pwm_a = gpiod_line_get("gpiochip0", GPIO_ENA);
    if (!pins->pwm_a) {
        fprintf(stderr, "Failed to get line %d\n", GPIO_ENA);
        exit(1);
    }

    pins->pwm_b = gpiod_line_get("gpiochip0", GPIO_ENB);
    if (!pins->pwm_b) {
        fprintf(stderr, "Failed to get line %d\n", GPIO_ENB);
        exit(1);
    }

    gpiod_line_set_direction(pins->motor_a_fwd, GPIOD_LINE_DIRECTION_OUTPUT);
    gpiod_line_set_direction(pins->motor_a_bwd, GPIOD_LINE_DIRECTION_OUTPUT);
    gpiod_line_set_direction(pins->motor_b_fwd, GPIOD_LINE_DIRECTION_OUTPUT);
    gpiod_line_set_direction(pins->motor_b_bwd, GPIOD_LINE_DIRECTION_OUTPUT);
    gpiod_line_set_direction(pins->ena, GPIOD_LINE_DIRECTION_OUTPUT);
    gpiod_line_set_direction(pins->enb, GPIOD_LINE_DIRECTION_OUTPUT);
    gpiod_line_set_direction(pins->pwm_a, GPIOD_LINE_DIRECTION_OUTPUT);
    gpiod_line_set_direction(pins->pwm_b, GPIOD_LINE_DIRECTION_OUTPUT);

    gpiod_line_set_value(pins->ena, 1);
    gpiod_line_set_value(pins->enb, 1);
}

void set_motor_speed(gpio_pins *pins, int speed) {
    if (speed > MAX_SPEED) speed = MAX_SPEED;
    if (speed < -MAX_SPEED) speed = -MAX_SPEED;

    if (speed > 0) {
        gpiod_line_set_value(pins->motor_a_fwd, 1);
        gpiod_line_set_value(pins->motor_a_bwd, 0);
        gpiod_line_set_value(pins->motor_b_fwd, 1);
        gpiod_line_set_value(pins->motor_b_bwd, 0);
    } else if (speed < 0) {
        gpiod_line_set_value(pins->motor_a_fwd, 0);
        gpiod_line_set_value(pins->motor_a_bwd, 1);
        gpiod_line_set_value(pins->motor_b_fwd, 0);
        gpiod_line_set_value(pins->motor_b_bwd, 1);
    } else {
        gpiod_line_set_value(pins->motor_a_fwd, 0);
        gpiod_line_set_value(pins->motor_a_bwd, 0);
        gpiod_line_set_value(pins->motor_b_fwd, 0);
        gpiod_line_set_value(pins->motor_b_bwd, 0);
    }

    gpiod_line_set_value(pins->pwm_a, (speed > 0) ? 1 : 0);
    gpiod_line_set_value(pins->pwm_b, (speed > 0) ? 1 : 0);
}

void stop_motors(gpio_pins *pins) {
    gpiod_line_set_value(pins->motor_a_fwd, 0);
    gpiod_line_set_value(pins->motor_a_bwd, 0);
    gpiod_line_set_value(pins->motor_b_fwd, 0);
    gpiod_line_set_value(pins->motor_b_bwd, 0);
    gpiod_line_set_value(pins->pwm_a, 0);
    gpiod_line_set_value(pins->pwm_b, 0);
}

void log_data(FILE *log_file, time_t timestamp, double tilt_error, double distance, double motor_a_speed, double motor_b_speed) {
    char timestamp_str[20];
    struct tm *tm_info = localtime(&timestamp);
    strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(log_file, "%s,%.1f,%.1f,%.1f,%.1f\n", timestamp_str, tilt_error, distance, motor_a_speed, motor_b_speed);
}

void handle_signal(int signal) {
    if (signal == SIGINT) {
        stop_motors(NULL);
        exit(0);
    }
}

int main() {
    gpio_pins pins;
    FILE *log_file;
    time_t last_log_time = 0;
    double tilt_error;
    double distance;
    double motor_a_speed = 0.0;
    double motor_b_speed = 0.0;
    struct timespec sleep_time = {0, 50000000}; // 50 ms

    signal(SIGINT, handle_signal);

    if (gpiod_init() < 0) {
        fprintf(stderr, "Failed to initialize libgpiod\n");
        return 1;
    }

    init_gpio(&pins);

    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        gpiod_exit();
        return 1;
    }

    while (1) {
        // Simulated tilt error
        tilt_error = ((double)rand() / (double)RAND_MAX) * (TILT_ERROR_MAX - TILT_ERROR_MIN) + TILT_ERROR_MIN;

        // Simulated distance
        distance = ((double)rand() / (double)RAND_MAX) * (DISTANCE_MAX - DISTANCE_MIN) + DISTANCE_MIN;

        // Check for obstacle
        if (distance < MIN_DISTANCE_CM) {
            motor_a_speed = OBSTACLE_SPEED;
            motor_b_speed = OBSTACLE_SPEED;
        } else {
            // PID control logic (simplified)
            double kp = 0.1;
            double kd = 0.01;
            double prev_error = 0.0;
            double derivative = 0.0;
            double output = 0.0;

            derivative = (tilt_error - prev_error) / (PID_UPDATE_INTERVAL_MS / 1000.0);
            output = kp * tilt_error + kd * derivative;

            motor_a_speed = output;
            motor_b_speed = output;

            prev_error = tilt_error;
        }

        // Clamp motor speeds
        if (motor_a_speed > MAX_SPEED) motor_a_speed = MAX_SPEED;
        if (motor_a_speed < -MAX_SPEED) motor_a_speed = -MAX_SPEED;
        if (motor_b_speed > MAX_SPEED) motor_b_speed = MAX_SPEED;
        if (motor_b_speed < -MAX_SPEED) motor_b_speed = -MAX_SPEED;

        // Log data
        time_t current_time = time(NULL);
        if (current_time - last_log_time >= 1) {
            log_data(log_file, current_time, tilt_error, distance, motor_a_speed, motor_b_speed);
            last_log_time = current_time;
        }

        // Set motor speeds
        set_motor_speed(&pins, motor_a_speed);
        set_motor_speed(&pins, motor_b_speed);

        nanosleep(&sleep_time, NULL);
    }

    fclose(log_file);
    gpiod_exit();
    return 0;
}

