#define GPIO_RELAY_PIN 17
#define DEBOUNCE_DELAY_MS 50
#define GPIO_LINE_COUNT 2

typedef struct {
    int touch_fd;
    int relay_fd;
    int touch_state;
    int relay_state;
    int debounce_timer;
} gpio_state_t;

static gpio_state_t gpio_state;

void cleanup(int signal) {
    printf("\nCleaning up...\n");

    if (gpio_state.touch_fd >= 0) {
        gpio_line_release(gpio_state.touch_fd);
        close(gpio_state.touch_fd);
    }

    if (gpio_state.relay_fd >= 0) {
        gpio_line_release(gpio_state.relay_fd);
        close(gpio_state.relay_fd);
    }

    exit(EXIT_SUCCESS);
}

void handle_signal(int signal) {
    cleanup(signal);
}

int init_gpio_line(int pin, int direction, int *fd) {
    int ret;
    struct gpiohandle_request req = {
        .lines = 1,
        .consumer_label = "touch_relay_app",
        .flags = GPIOHANDLE_REQUEST_OUTPUT,
    };

    req.line = pin;
    req.flags = direction ? GPIOHANDLE_REQUEST_OUTPUT : GPIOHANDLE_REQUEST_INPUT;

    *fd = gpio_request_line(pin, "touch_relay_app", 0);
    if (*fd < 0) {
        fprintf(stderr, "Failed to request GPIO line %d: %s\n", pin, strerror(errno));
        return -1;
    }

    ret = ioctl(*fd, GPIOIOC_REQUEST_HANDLE, &req);
    if (ret < 0) {
        fprintf(stderr, "Failed to request handle for GPIO %d: %s\n", pin, strerror(errno));
        gpio_line_release(*fd);
        close(*fd);
        *fd = -1;
        return -1;
    }

    return 0;
}

int set_gpio_value(int fd, int pin, int value) {
    struct gpiohandle_data data = {
        .values = &value,
    };

    if (ioctl(fd, GPIOIOC_SET_LINE_VALUES, &data) < 0) {
        fprintf(stderr, "Failed to set GPIO %d to %d: %s\n", pin, value, strerror(errno));
        return -1;
    }

    return 0;
}

int get_gpio_value(int fd, int pin, int *value) {
    struct gpiohandle_data data = {
        .values = value,
    };

    if (ioctl(fd, GPIOIOC_GET_LINE_VALUES, &data) < 0) {
        fprintf(stderr, "Failed to get GPIO %d value: %s\n", pin, strerror(errno));
        return -1;
    }

    return 0;
}

int main() {
    int ret;
    int touch_value;
    int relay_value = 0;
    int debounce_timer = 0;

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if (init_gpio_line(GPIO_TOUCH_PIN, GPIOHANDLE_REQUEST_INPUT, &gpio_state.touch_fd) < 0) {
        fprintf(stderr, "Failed to initialize touch GPIO\n");
        return EXIT_FAILURE;
    }

    if (init_gpio_line(GPIO_RELAY_PIN, GPIOHANDLE_REQUEST_OUTPUT, &gpio_state.relay_fd) < 0) {
        fprintf(stderr, "Failed to initialize relay GPIO\n");
        return EXIT_FAILURE;
    }

    gpio_state.touch_state = 0;
    gpio_state.relay_state = 0;
    gpio_state.debounce_timer = 0;

    while (1) {
        if (gpio_state.debounce_timer > 0) {
            gpio_state.debounce_timer--;
            continue;
        }

        if (get_gpio_value(gpio_state.touch_fd, GPIO_TOUCH_PIN, &touch_value) < 0) {
            fprintf(stderr, "Failed to read touch GPIO\n");
            cleanup(0);
        }

        if (touch_value != gpio_state.touch_state) {
            gpio_state.touch_state = touch_value;
            if (touch_value == 1) {
                gpio_state.debounce_timer = DEBOUNCE_DELAY_MS;
                relay_value ^= 1;
                if (set_gpio_value(gpio_state.relay_fd, GPIO_RELAY_PIN, relay_value) < 0) {
                    fprintf(stderr, "Failed to set relay GPIO\n");
                    cleanup(0);
                }
            }
        }

        usleep(1000); // 1ms delay for polling
    }

    cleanup(0);
    return EXIT_SUCCESS;
}

