#define SENSITIVITY_MAX 10.0
#define UPDATE_INTERVAL_MS 10
#define MAX_BUFFER_OVERRUNS 5

typedef struct {
    int audio_fd;
    snd_pcm_t *pcm_handle;
    snd_pcm_format_t pcm_format;
    snd_pcm_uframes_t buffer_size;
    float *buffer;
    float *rms_buffer;
    float sensitivity;
    int running;
    int buffer_overruns;
    int signal_received;
} AudioContext;

typedef struct {
    int red;
    int green;
    int blue;
    int pwm_frequency;
    int pwm_range;
} LedState;

void signal_handler(int signal) {
    AudioContext *context = (AudioContext *)malloc(sizeof(AudioContext));
    context->signal_received = 1;
    free(context);
}

void cleanup(AudioContext *context) {
    if (context->running) {
        if (context->pcm_handle) {
            snd_pcm_drain(context->pcm_handle);
            snd_pcm_close(context->pcm_handle);
        }
        if (context->audio_fd >= 0) {
            close(context->audio_fd);
        }
        if (context->buffer) {
            free(context->buffer);
        }
        if (context->rms_buffer) {
            free(context->rms_buffer);
        }
        if (context->signal_received) {
            gpioTerminate();
        }
    }
}

void setup_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        exit(EXIT_FAILURE);
    }
    gpioSetMode(GPIO_RED, PI_OUTPUT);
    gpioSetMode(GPIO_GREEN, PI_OUTPUT);
    gpioSetMode(GPIO_BLUE, PI_OUTPUT);
    gpioSetPWMfrequency(GPIO_RED, 1000);
    gpioSetPWMfrequency(GPIO_GREEN, 1000);
    gpioSetPWMfrequency(GPIO_BLUE, 1000);
    gpioSetPWMrange(GPIO_RED, 1024);
    gpioSetPWMrange(GPIO_GREEN, 1024);
    gpioSetPWMrange(GPIO_BLUE, 1024);
}

void set_led_color(LedState *led, float r, float g, float b) {
    int red_pwm = (int)(r * 1023.0f);
    int green_pwm = (int)(g * 1023.0f);
    int blue_pwm = (int)(b * 1023.0f);
    gpioPWM(GPIO_RED, red_pwm);
    gpioPWM(GPIO_GREEN, green_pwm);
    gpioPWM(GPIO_BLUE, blue_pwm);
}

void compute_rms(float *buffer, int size, float *rms) {
    float sum = 0.0f;
    for (int i = 0; i < size; i++) {
        sum += buffer[i] * buffer[i];
    }
    *rms = sqrt(sum / size);
}

void simulate_audio(float *buffer, int size, float sensitivity) {
    float phase = 0.0f;
    for (int i = 0; i < size; i++) {
        buffer[i] = sensitivity * sin(2.0f * M_PI * SINE_WAVE_FREQUENCY * i / SAMPLE_RATE);
        phase += 2.0f * M_PI * SINE_WAVE_FREQUENCY / SAMPLE_RATE;
    }
}

void setup_audio() {
    int err;
    snd_pcm_t *pcm_handle;
    snd_pcm_format_t pcm_format;
    snd_pcm_uframes_t buffer_size;
    int sample_rate = SAMPLE_RATE;
    int channels = CHANNELS;
    int period_size = PERIOD_SIZE;
    int buffer_size_frames = 2 * period_size;

    err = snd_pcm_open(&pcm_handle, "default", SND_PCM_STREAM_CAPTURE, 0);
    if (err < 0) {
        fprintf(stderr, "Failed to open PCM: %s\n", snd_strerror(err));
        exit(EXIT_FAILURE);
    }

    err = snd_pcm_set_params(pcm_handle, SND_PCM_FORMAT_S16_LE, SND_PCM_ACCESS_RW_INTERLEAVED, channels, sample_rate, 1, 1000000);
    if (err < 0) {
        fprintf(stderr, "Failed to set PCM parameters: %s\n", snd_strerror(err));
        snd_pcm_close(pcm_handle);
        exit(EXIT_FAILURE);
    }

    buffer_size = buffer_size_frames;
    err = snd_pcm_set_buffer_size(pcm_handle, buffer_size);
    if (err < 0) {
        fprintf(stderr, "Failed to set buffer size: %s\n", snd_strerror(err));
        snd_pcm_close(pcm_handle);
        exit(EXIT_FAILURE);
    }

    err = snd_pcm_start(pcm_handle);
    if (err < 0) {
        fprintf(stderr, "Failed to start PCM: %s\n", snd_strerror(err));
        snd_pcm_close(pcm_handle);
        exit(EXIT_FAILURE);
    }

    printf("Audio capture started\n");
}

void audio_capture(AudioContext *context) {
    int err;
    int frames_read;
    int i;
    float rms;
    float sensitivity = context->sensitivity;
    float r, g, b;
    struct timeval start_time, current_time;
    long elapsed_time;

    gettimeofday(&start_time, NULL);

    while (context->running) {
        err = snd_pcm_readi(context->pcm_handle, context->buffer, PERIOD_SIZE);
        if (err < 0) {
            if (err == -EPIPE) {
                fprintf(stderr, "Buffer overrun, preparing PCM...\n");
                snd_pcm_prepare(context->pcm_handle);
                context->buffer_overruns++;
                if (context->buffer_overruns >= MAX_BUFFER_OVERRUNS) {
                    fprintf(stderr, "Too many buffer overruns, exiting...\n");
                    context->running = 0;
                }
            } else if (err == -ESTRPIPE) {
                fprintf(stderr, "PCM suspended, resuming...\n");
                snd_pcm_resume(context->pcm_handle);
            } else {
                fprintf(stderr, "Error reading from PCM: %s\n", snd_strerror(err));
                context->running = 0;
            }
            continue;
        }

        compute_rms(context->buffer, PERIOD_SIZE, &rms);

        elapsed_time = (current_time.tv_sec - start_time.tv_sec) * 1000 + (current_time.tv_usec - start_time.tv_usec) / 1000;
        if (elapsed_time >= UPDATE_INTERVAL_MS) {
            gettimeofday(&current_time, NULL);
            r = (rms / 32768.0f) * sensitivity;
            g = (rms / 32768.0f) * sensitivity;
            b = (rms / 32768.0f) * sensitivity;
            set_led_color(&context->led, r, g, b);
            printf("RMS: %.4f, LED: (%.2f, %.2f, %.2f)\n", rms, r, g, b);
            gettimeofday(&start_time, NULL);
        }
    }
}

int main(int argc, char *argv[]) {
    AudioContext context = {0};
    LedState led = {0};
    int sensitivity = SENSITIVITY_DEFAULT;
    int err;
    struct sigaction sa;

    if (argc > 1) {
        sensitivity = atof(argv[1]);
        if (sensitivity < SENSITIVITY_MIN || sensitivity > SENSITIVITY_MAX) {
            fprintf(stderr, "Sensitivity must be between %.1f and %.1f\n", SENSITIVITY_MIN, SENSITIVITY_MAX);
            exit(EXIT_FAILURE);
        }
    }

    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        exit(EXIT_FAILURE);
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        exit(EXIT_FAILURE);
    }

    if (ALSA_AVAILABLE) {
        setup_gpio();
        setup_audio();
        context.pcm_handle = NULL;
        context.buffer = (float *)malloc(PERIOD_SIZE * sizeof(float));
        context.rms_buffer = (float *)malloc(PERIOD_SIZE * sizeof(float));
        context.sensitivity = sensitivity;
        context.running = 1;
        context.buffer_overruns = 0;
        context.signal_received = 0;
        audio_capture(&context);
    } else {
        printf("ALSA not available, simulating audio input...\n");
        setup_gpio();
        while (!context.signal_received) {
            simulate_audio(context.buffer, PERIOD_SIZE, sensitivity);
            compute_rms(context.buffer, PERIOD_SIZE, &context.rms_buffer[0]);
            r = (context.rms_buffer[0] / 32768.0f) * sensitivity;
            g = (context.rms_buffer[0] / 32768.0f) * sensitivity;
            b = (context.rms_buffer[0] / 32768.0f) * sensitivity;
            set_led_color(&led, r, g, b);
            printf("Simulated RMS: %.4f, LED: (%.2f, %.2f, %.2f)\n", context.rms_buffer[0], r, g, b);
            usleep(10000);
        }
    }

    cleanup(&context);
    return 0;
}
