#include <gpiod.h>

#define I2C_BUS 1
#define I2C_ADDR 0x29
#define INTEGRATION_TIME 154
#define SAMPLE_INTERVAL_MS 500
#define CSV_FILE "color_data.csv"

typedef struct {
    int fd;
    FILE *csv_file;
    int running;
} app_state;

void handle_signal(int signum) {
    app_state *state = (app_state *)malloc(sizeof(app_state));
    if (state) {
        state->running = 0;
        free(state);
    }
}

void close_i2c_and_file(app_state *state) {
    if (state->fd >= 0) {
        close(state->fd);
    }
    if (state->csv_file) {
        fclose(state->csv_file);
    }
}

void write_csv_header(FILE *file) {
    fprintf(file, "timestamp,C,R,G,B\n");
}

void read_color_data(int fd, uint16_t *c, uint16_t *r, uint16_t *g, uint16_t *b) {
    uint8_t data[6] = {0};

    if (ioctl(fd, I2C_SLAVE, I2C_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address\n");
        return;
    }

    if (write(fd, "\x8F", 1) < 0) {
        fprintf(stderr, "Failed to write to I2C device\n");
        return;
    }

    if (read(fd, data, 6) < 0) {
        fprintf(stderr, "Failed to read from I2C device\n");
        return;
    }

    *c = (data[1] << 8) | data[0];
    *r = (data[3] << 8) | data[2];
    *g = (data[5] << 8) | data[4];
    *b = (data[7] << 8) | data[6]; // This is a placeholder, actual data may vary
}

int configure_sensor(int fd) {
    uint8_t config = 0x00;
    uint8_t control = 0x00;

    if (ioctl(fd, I2C_SLAVE, I2C_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address\n");
        return -1;
    }

    if (write(fd, &config, 1) < 0) {
        fprintf(stderr, "Failed to write configuration register\n");
        return -1;
    }

    if (write(fd, &control, 1) < 0) {
        fprintf(stderr, "Failed to write control register\n");
        return -1;
    }

    return 0;
}

int main() {
    app_state state = {0};
    struct timespec ts = {0, 500000000}; // 500 ms
    int ret;

    // Register signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Open I2C bus
    char i2c_bus_path[32];
    snprintf(i2c_bus_path, sizeof(i2c_bus_path), "/dev/i2c-%d", I2C_BUS);
    state.fd = open(i2c_bus_path, O_RDWR);
    if (state.fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %d\n", I2C_BUS);
        return 1;
    }

    // Configure sensor
    if (configure_sensor(state.fd) < 0) {
        fprintf(stderr, "Failed to configure sensor\n");
        close_i2c_and_file(&state);
        return 1;
    }

    // Open CSV file
    state.csv_file = fopen(CSV_FILE, "w");
    if (!state.csv_file) {
        fprintf(stderr, "Failed to open CSV file\n");
        close_i2c_and_file(&state);
        return 1;
    }

    write_csv_header(state.csv_file);

    state.running = 1;

    while (state.running) {
        uint16_t c = 0, r = 0, g = 0, b = 0;
        time_t timestamp;

        // Read sensor data
        read_color_data(state.fd, &c, &r, &g, &b);

        // Write to CSV
        timestamp = time(NULL);
        fprintf(state.csv_file, "%ld,%d,%d,%d,%d\n", (long)timestamp, c, r, g, b);

        // Sleep for sample interval
        nanosleep(&ts, NULL);
    }

    close_i2c_and_file(&state);

    return 0;
}

