#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_PIN_17 17
#define GPIO_PIN_27 27
#define GPIO_PIN_22 22
#define GPIO_PIN_23 23

#define SUNRISE_DURATION 3600
#define DAYTIME_DURATION 21600
#define SUNSET_DURATION 3600
#define NIGHTTIME_DURATION 51840

#define RELAY_COUNT 4
#define PWM_RESOLUTION 1000

typedef struct {
    struct gpiod_line *lines[RELAY_COUNT];
    int duty_cycle;
    int phase;
    int phase_duration;
    int total_duration;
    int elapsed_time;
} relay_state;

void handle_signal(int signal) {
    printf("Received signal %d, shutting down...\n", signal);
    exit(EXIT_FAILURE);
}

void setup_gpio(relay_state *state) {
    struct gpiod_chip *chip;
    int i;

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        exit(EXIT_FAILURE);
    }

    for (i = 0; i < RELAY_COUNT; i++) {
        int gpio_pin;
        switch (i) {
            case 0: gpio_pin = GPIO_PIN_17; break;
            case 1: gpio_pin = GPIO_PIN_27; break;
            case 2: gpio_pin = GPIO_PIN_22; break;
            case 3: gpio_pin = GPIO_PIN_23; break;
            default: gpio_pin = -1; break;
        }

        state->lines[i] = gpiod_chip_get_line(chip, gpio_pin);
        if (!state->lines[i]) {
            fprintf(stderr, "Failed to get line for GPIO %d\n", gpio_pin);
            exit(EXIT_FAILURE);
        }

        if (gpiod_line_request_output(state->lines[i], "relay", 0) < 0) {
            fprintf(stderr, "Failed to request line %d as output\n", gpio_pin);
            exit(EXIT_FAILURE);
        }
    }
}

void cleanup_gpio(relay_state *state) {
    int i;
    for (i = 0; i < RELAY_COUNT; i++) {
        if (state->lines[i]) {
            gpiod_line_release(state->lines[i]);
        }
    }
    if (state->lines[0]) {
        gpiod_chip_close(state->lines[0]->chip);
    }
}

void set_relays_pwm(relay_state *state) {
    int i;
    for (i = 0; i < RELAY_COUNT; i++) {
        int value = (state->duty_cycle > 0) ? 0 : 1;
        if (gpiod_line_set_value(state->lines[i], value) < 0) {
            fprintf(stderr, "Failed to set relay %d value\n", i);
            exit(EXIT_FAILURE);
        }
    }
}

void simulate_sunrise(relay_state *state) {
    state->phase = 0;
    state->phase_duration = SUNRISE_DURATION;
    state->total_duration = SUNRISE_DURATION;
    state->elapsed_time = 0;
    state->duty_cycle = 0;
}

void simulate_daytime(relay_state *state) {
    state->phase = 1;
    state->phase_duration = DAYTIME_DURATION;
    state->total_duration = DAYTIME_DURATION;
    state->elapsed_time = 0;
    state->duty_cycle = 1000;
}

void simulate_sunset(relay_state *state) {
    state->phase = 2;
    state->phase_duration = SUNSET_DURATION;
    state->total_duration = SUNSET_DURATION;
    state->elapsed_time = 0;
    state->duty_cycle = 1000;
}

void simulate_nighttime(relay_state *state) {
    state->phase = 3;
    state->phase_duration = NIGHTTIME_DURATION;
    state->total_duration = NIGHTTIME_DURATION;
    state->elapsed_time = 0;
    state->duty_cycle = 0;
}

void run_phase(relay_state *state) {
    int i;
    for (i = 0; i < state->phase_duration; i++) {
        usleep(100000); // 100ms
        state->elapsed_time++;
        if (state->phase == 0) {
            state->duty_cycle = (state->elapsed_time * 1000) / state->total_duration;
        } else if (state->phase == 1) {
            // Daytime: all relays on
            state->duty_cycle = 1000;
        } else if (state->phase == 2) {
            state->duty_cycle = (state->total_duration - state->elapsed_time) * 1000 / state->total_duration;
        } else if (state->phase == 3) {
            // Nighttime: all relays off
            state->duty_cycle = 0;
        }
        set_relays_pwm(state);
    }
}

int main() {
    relay_state state;
    setup_gpio(&state);

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (1) {
        simulate_sunrise(&state);
        run_phase(&state);

        simulate_daytime(&state);
        run_phase(&state);

        simulate_sunset(&state);
        run_phase(&state);

        simulate_nighttime(&state);
        run_phase(&state);
    }

    cleanup_gpio(&state);
    return 0;
}

