void simulate_sunrise(relay_state *state) {
    state->phase = 0;
    state->phase_duration = SUNRISE_DURATION;
    state->total_duration = SUNRISE_DURATION;
    state->elapsed_time = 0;
    state->duty_cycle = 0;
}

void simulate_daytime(relay_state *state) {
    state->phase = 1;
    state->phase_duration = DAYTIME_DURATION;
    state->total_duration = DAYTIME_DURATION;
    state->elapsed_time = 0;
    state->duty_cycle = 1000;
}

void simulate_sunset(relay_state *state) {
    state->phase = 2;
    state->phase_duration = SUNSET_DURATION;
    state->total_duration = SUNSET_DURATION;
    state->elapsed_time = 0;
    state->duty_cycle = 1000;
}

void simulate_nighttime(relay_state *state) {
    state->phase = 3;
    state->phase_duration = NIGHTTIME_DURATION;
    state->total_duration = NIGHTTIME_DURATION;
    state->elapsed_time = 0;
    state->duty_cycle = 0;
}

void run_phase(relay_state *state) {
    int i;
    for (i = 0; i < state->phase_duration; i++) {
        usleep(100000); // 100ms
        state->elapsed_time++;
        if (state->phase == 0) {
            state->duty_cycle = (state->elapsed_time * 1000) / state->total_duration;
        } else if (state->phase == 1) {
            // Daytime: all relays on
            state->duty_cycle = 1000;
        } else if (state->phase == 2) {
            state->duty_cycle = (state->total_duration - state->elapsed_time) * 1000 / state->total_duration;
        } else if (state->phase == 3) {
            // Nighttime: all relays off
            state->duty_cycle = 0;
        }
        set_relays_pwm(state);
    }
}

int main() {
    relay_state state;
    setup_gpio(&state);

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (1) {
        simulate_sunrise(&state);
        run_phase(&state);

        simulate_daytime(&state);
        run_phase(&state);

        simulate_sunset(&state);
        run_phase(&state);

        simulate_nighttime(&state);
        run_phase(&state);
    }

    cleanup_gpio(&state);
    return 0;
}
