        fclose(log_file);
        exit(EXIT_FAILURE);
    }

    if (fclose(log_file) != 0) {
        perror("Failed to close log file");
        exit(EXIT_FAILURE);
    }
}

void start_video_capture(const char *filename) {
    char command[256];
    snprintf(command, sizeof(command), "raspivid -t %d -o %s", VIDEO_DURATION * 1000, filename);

    FILE *fp = popen(command, "r");
    if (!fp) {
        perror("Failed to execute video capture command");
        exit(EXIT_FAILURE);
    }

    if (pclose(fp) != 0) {
        perror("Video capture command failed");
        exit(EXIT_FAILURE);
    }
}

int main() {
    sensor_state state = {0};
    struct gpiod_chip *chip;
    struct timespec ts;
    char timestamp[30];
    char video_filename[256];

    // Initialize signal handler
    signal(SIGINT, handle_sigint);

    // Initialize GPIO
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    state.line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!state.line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(state.line, "motion_sensor", GPIO_ACTIVE_LOW) < 0) {
        perror("Failed to request GPIO line");
        gpiod_line_release(state.line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Set initial state
    state.last_trigger_time = 0;
    state.running = 1;

    while (state.running) {
        // Read GPIO line
        int value = gpiod_line_get_value(state.line);
        if (value < 0) {
            perror("Failed to read GPIO line");
            state.running = 0;
            break;
        }

        if (value == 0) { // Motion detected (active-low)
            clock_gettime(CLOCK_MONOTONIC, &ts);
            long current_time = ts.tv_sec * 1000 + ts.tv_nsec / 1e6;

            if (current_time - state.last_trigger_time > DEBOUNCE_INTERVAL_MS) {
                // Generate timestamp
                time_t now = time(NULL);
                struct tm *tm_info = localtime(&now);
                strftime(timestamp, sizeof(timestamp), "%Y%m%d_%H%M%S", tm_info);

                // Generate video filename
                snprintf(video_filename, sizeof(video_filename), "%s%s.h264", VIDEO_DIR, timestamp);

                // Ensure video directory exists
                if (mkdir(VIDEO_DIR, 0777) != 0 && errno != EEXIST) {
                    perror("Failed to create video directory");
                    state.running = 0;
                    break;
                }

                // Start video capture
                start_video_capture(video_filename);

                // Log motion event
                log_motion_event(timestamp);

                // Update last trigger time
                state.last_trigger_time = current_time;
            }
        }

        usleep(10000); // 10ms delay to reduce CPU usage
    }

    // Clean up
    gpiod_line_release(state.line);
    gpiod_chip_close(chip);

    return 0;
}

