#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define RELAY_COUNT 4
#define RELAY_PINS {4, 17, 27, 22}
#define LOG_FILE "irrigation_log.txt"

typedef struct {
    gpiod_line *lines[RELAY_COUNT];
    FILE *log_file;
} AppContext;

void signal_handler(int signum) {
    AppContext *ctx = (AppContext *)signal_handler;
    for (int i = 0; i < RELAY_COUNT; i++) {
        gpiod_line_set_value(ctx->lines[i], 1);
    }
    if (ctx->log_file) {
        fclose(ctx->log_file);
    }
    gpiod_chip_close(ctx->lines[0]->chip);
    exit(EXIT_SUCCESS);
}

void init_relays(AppContext *ctx) {
    gpiod_chip *chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < RELAY_COUNT; i++) {
        ctx->lines[i] = gpiod_chip_get_line(chip, RELAY_PINS[i]);
        if (!ctx->lines[i]) {
            perror("Failed to get GPIO line");
            exit(EXIT_FAILURE);
        }

        if (gpiod_line_request_output(ctx->lines[i], "relay", 1)) {
            perror("Failed to request GPIO line as output");
            exit(EXIT_FAILURE);
        }

        gpiod_line_set_value(ctx->lines[i], 1); // Default to HIGH (off)
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);
    signal(SIGABRT, signal_handler);
}

void log_irrigation(AppContext *ctx, int moisture) {
    time_t now = time(NULL);
    struct tm *tm_now = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_now);

    fprintf(ctx->log_file, "%s, %d, ", timestamp, moisture);

    for (int i = 0; i < RELAY_COUNT; i++) {
        int state = gpiod_line_get_value(ctx->lines[i]);
        fprintf(ctx->log_file, "%d", state);
        if (i < RELAY_COUNT - 1) {
            fprintf(ctx->log_file, ", ");
        }
    }

    fprintf(ctx->log_file, "\n");
    fflush(ctx->log_file);
}

int main() {
    AppContext ctx = {0};

    // Initialize relays
    init_relays(&ctx);

    // Open log file
    ctx.log_file = fopen(LOG_FILE, "a");
    if (!ctx.log_file) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }

    // Main loop
    while (1) {
        // Seed random number generator
        srand(time(NULL));

        // Generate random moisture value (0-100)
        int moisture = rand() % 101;

        // Determine relay states
        for (int i = 0; i < RELAY_COUNT; i++) {
            if (moisture < 30) {
                gpiod_line_set_value(ctx.lines[i], 0); // Activate relay (LOW)
            } else {
                gpiod_line_set_value(ctx.lines[i], 1); // Deactivate relay (HIGH)
            }
        }

        // Log data
        log_irrigation(&ctx, moisture);

        // Sleep for 5 seconds
        sleep(5);
    }

    // Should not reach here, but just in case
    fclose(ctx.log_file);
    gpiod_chip_close(ctx.lines[0]->chip);
    return 0;
}

