    uint64_t pulse_width_us = (end_time_ns - start_time_ns) / 1000;
    if (pulse_width_us > MAX_PULSE_WIDTH_US) {
        pthread_mutex_unlock(&state->mutex);
        return;
    }

    uint64_t current_time_ns = timespec_to_ns(timestamp);
    uint64_t elapsed_time_ms = (current_time_ns - last_trigger_time_ns) / 1000000;

    if (elapsed_time_ms > TIMEOUT_MS) {
        pthread_mutex_unlock(&state->mutex);
        return;
    }

    double distance_cm = (double)pulse_width_us * 0.0343 / 2;
    fprintf(state->log_file, "%lu,%f\n", (unsigned long)current_time_ns, distance_cm);
    fflush(state->log_file);

    pthread_mutex_unlock(&state->mutex);
}

uint64_t timespec_to_ns(const struct timespec *ts) {
    return (uint64_t)ts->tv_sec * 1000000000 + (uint64_t)ts->tv_nsec;
}

int main() {
    sensor_state_t state;
    struct timespec timeout = {0, 0};
    int ret;

    signal(SIGINT, handle_sigint);

    state.trig_line = gpiod_line_get("gpio", TRIG_PIN);
    if (!state.trig_line) {
        fprintf(stderr, "Failed to get TRIG line\n");
        return 1;
    }

    state.echo_line = gpiod_line_get("gpio", ECHO_PIN);
    if (!state.echo_line) {
        fprintf(stderr, "Failed to get ECHO line\n");
        gpiod_line_put(state.trig_line);
        return 1;
    }

    gpiod_line_request_output(state.trig_line, "trigger", GPIOD_LINE_REQUEST_OUTPUT_ACTIVE_LOW);
    gpiod_line_request_input(state.echo_line, "echo", GPIOD_LINE_REQUEST_INPUT_ACTIVE_LOW);

    pthread_mutex_init(&state.mutex, NULL);

    state.log_file = fopen(LOG_FILE, "a");
    if (!state.log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpiod_line_put(state.trig_line);
        gpiod_line_put(state.echo_line);
        return 1;
    }

    state.running = 1;

    gpiod_line_set_config(state.echo_line, GPIOD_LINE_CONFIG_INPUT_RISING_EDGE, &timeout);
    gpiod_line_set_config(state.echo_line, GPIOD_LINE_CONFIG_INPUT_FALLING_EDGE, &timeout);

    gpiod_line_set_repeated_callback(state.echo_line, rising_edge_callback, falling_edge_callback, &state);

    while (state.running) {
        trigger_pulse(state.trig_line);
        last_trigger_time_ns = timespec_to_ns(&timeout);
        usleep(200000);
    }

    gpiod_line_set_repeated_callback(state.echo_line, NULL, NULL, NULL);
    fclose(state.log_file);
    pthread_mutex_destroy(&state.mutex);
    gpiod_line_put(state.trig_line);
    gpiod_line_put(state.echo_line);

    return 0;
}
