#define I2C_BUS 1
#define LIS3DH_ADDR 0x18
#define LIS3DH_REGISTER_CTRL_REG1 0x20
#define LIS3DH_REGISTER_OUT_X_L 0x28
#define LIS3DH_REGISTER_STATUS_REG 0x27
#define LIS3DH_REGISTER_WHO_AM_I 0x0F
#define LIS3DH_DEFAULT_CTRL_REG1 0x27  // 200Hz, 4g, 16-bit, high resolution, active
#define FREE_FALL_THRESHOLD 0.2
#define IMPACT_THRESHOLD 1.5
#define MAX_RETRIES 3
#define BUZZER_PIN 17

typedef struct {
    int fd;
    gpiod_line *buzzer_line;
    double free_fall_threshold;
    double impact_threshold;
