void handle_signal(int sig) {
    (void)sig;
    printf("\nCaught signal, shutting down...\n");
    exit(EXIT_SUCCESS);
}

void init_i2c(int *fd, int bus) {
    char filename[20];
    snprintf(filename, sizeof(filename), "/dev/i2c-%d", bus);
    *fd = open(filename, O_RDWR);
    if (*fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    if (ioctl(*fd, I2C_TEN, 0) < 0) {
        perror("Failed to set I2C to 10-bit addressing");
        close(*fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(*fd, I2C_SLAVE, LIS3DH_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(*fd);
        exit(EXIT_FAILURE);
    }
}

void init_sensor(int fd) {
    // Check WHO_AM_I register
    unsigned char who_am_i[1];
    if (i2c_smbus_read_i2c_block_data(fd, LIS3DH_REGISTER_WHO_AM_I, 1, who_am_i) < 0) {
        perror("Failed to read WHO_AM_I register");
        exit(EXIT_FAILURE);
    }

    if (who_am_i[0] != 0x33) {
        fprintf(stderr, "Invalid WHO_AM_I register value: 0x%02X\n", who_am_i[0]);
        exit(EXIT_FAILURE);
    }

    // Set control register 1
    unsigned char ctrl_reg1 = LIS3DH_DEFAULT_CTRL_REG1;
    if (i2c_smbus_write_i2c_block_data(fd, LIS3DH_REGISTER_CTRL_REG1, 1, &ctrl_reg1) < 0) {
        perror("Failed to set control register 1");
        exit(EXIT_FAILURE);
    }
}

void read_acceleration(int fd, double *x, double *y, double *z) {
    unsigned char data[6];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (i2c_smbus_read_i2c_block_data(fd, LIS3DH_REGISTER_OUT_X_L, 6, data) < 0) {
            perror("Failed to read acceleration data");
            retries++;
            usleep(100000); // 100ms delay
            continue;
        }

        *x = (int16_t)(data[1] << 8 | data[0]);
        *y = (int16_t)(data[3] << 8 | data[2]);
        *z = (int16_t)(data[5] << 8 | data[4]);

        // Convert to g units (assuming 4g range)
        *x /= 65536.0 * 4.0 / 2.0;
        *y /= 65536.0 * 4.0 / 2.0;
        *z /= 65536.0 * 4.0 / 2.0;

        return;
    }

    fprintf(stderr, "Failed to read acceleration data after %d retries\n", MAX_RETRIES);
    exit(EXIT_FAILURE);
}

double get_magnitude(double x, double y, double z) {
    return sqrt(x * x + y * y + z * z);
}

void init_gpio(gpiod_line **buzzer_line, int pin) {
    struct gpiod_line_config config;
    struct gpiod_chip *chip;

    chip = gpiod_chip_open("/dev/gpiochip4");
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    config.line_offset = pin;
    config.flags = GPIOD_LINE_FLAG_BIAS_PULL_UP;
    config.consumer = "buzzer";
    config.direction = GPIOD_LINE_DIRECTION_OUTPUT;

    *buzzer_line = gpiod_line_request_config(chip, &config);
    if (!*buzzer_line) {
        perror("Failed to request GPIO line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    gpiod_line_set_value(*buzzer_line, 0);
}

void activate_buzzer(gpiod_line *buzzer_line) {
    gpiod_line_set_value(buzzer_line, 1);
    usleep(1000000); // 1 second
    gpiod_line_set_value(buzzer_line, 0);
}

void cleanup(sensor_data *data) {
    if (data->fd >= 0) {
        close(data->fd);
    }
    if (data->buzzer_line) {
        gpiod_line_release(data->buzzer_line);
    }
}

int main(int argc, char *argv[]) {
    sensor_data data;
    double x, y, z;
    double magnitude;
    int free_fall_threshold = FREE_FALL_THRESHOLD;
    int impact_threshold = IMPACT_THRESHOLD;
    int i2c_fd;
    int signal_received = 0;

    signal(SIGINT, handle_signal);

    if (argc > 2 && strcmp(argv[1], "--free-fall") == 0) {
        free_fall_threshold = atof(argv[2]);
    }

    if (argc > 4 && strcmp(argv[3], "--impact") == 0) {
        impact_threshold = atof(argv[4]);
    }

    init_i2c(&i2c_fd, I2C_BUS);
    init_sensor(i2c_fd);
    init_gpio(&data.buzzer_line, BUZZER_PIN);
    data.fd = i2c_fd;
    data.free_fall_threshold = free_fall_threshold;
    data.impact_threshold = impact_threshold;

    while (!signal_received) {
        read_acceleration(i2c_fd, &x, &y, &z);
        magnitude = get_magnitude(x, y, z);

        if (magnitude < data.free_fall_threshold) {
            printf("Free-fall detected: magnitude = %.2f g\n", magnitude);
            // Simulate a delay before checking for impact
            usleep(1000000); // 1 second
            read_acceleration(i2c_fd, &x, &y, &z);
            magnitude = get_magnitude(x, y, z);
            if (magnitude > data.impact_threshold) {
                printf("Impact detected: magnitude = %.2f g\n", magnitude);
                activate_buzzer(data.buzzer_line);
            }
        }

        usleep(100000); // 100ms delay
    }

    cleanup(&data);
    return 0;
