#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/gpio.h>
#include <libgpiod.h>

#define GPIO_CHIP "gpiochip0"
#define STEP_DELAY_US 1000
#define STEPS_PER_REVOLUTION 2048
#define GEAR_RATIO 64
#define SQUARE_SIZE_MM 50
#define MM_TO_STEPS (STEPS_PER_REVOLUTION / GEAR_RATIO)

typedef struct {
    int chip_fd;
    struct gpiod_line *in1;
    struct gpiod_line *in2;
    struct gpiod_line *in3;
    struct gpiod_line *in4;
} Motor;

void motor_init(Motor *motor, int in1, int in2, int in3, int in4) {
    struct gpiod_chip *chip;
    struct gpiod_line_config config = GPIOD_LINE_CONFIG_DEFAULTS;

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    config.direction = GPIOD_LINE_DIRECTION_OUTPUT;
    config.consumer = "stepper_motor";

    motor->in1 = gpiod_line_request(chip, in1, &config);
    if (!motor->in1) {
        perror("Failed to request GPIO line for IN1");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    motor->in2 = gpiod_line_request(chip, in2, &config);
    if (!motor->in2) {
        perror("Failed to request GPIO line for IN2");
        gpiod_line_release(motor->in1);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    motor->in3 = gpiod_line_request(chip, in3, &config);
    if (!motor->in3) {
        perror("Failed to request GPIO line for IN3");
        gpiod_line_release(motor->in1);
        gpiod_line_release(motor->in2);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    motor->in4 = gpiod_line_request(chip, in4, &config);
    if (!motor->in4) {
        perror("Failed to request GPIO line for IN4");
        gpiod_line_release(motor->in1);
        gpiod_line_release(motor->in2);
        gpiod_line_release(motor->in3);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    motor->chip_fd = gpiod_chip_get_fd(chip);
}

void motor_set_step(Motor *motor, int step) {
    switch (step) {
        case 0: // 1-3-2-4
            gpiod_line_set_value(motor->in1, 1);
            gpiod_line_set_value(motor->in2, 0);
            gpiod_line_set_value(motor->in3, 1);
            gpiod_line_set_value(motor->in4, 0);
            break;
        case 1: // 1-2-3-4
            gpiod_line_set_value(motor->in1, 1);
            gpiod_line_set_value(motor->in2, 1);
            gpiod_line_set_value(motor->in3, 0);
            gpiod_line_set_value(motor->in4, 0);
            break;
        case 2: // 2-3-4-1
            gpiod_line_set_value(motor->in1, 0);
            gpiod_line_set_value(motor->in2, 1);
            gpiod_line_set_value(motor->in3, 1);
            gpiod_line_set_value(motor->in4, 1);
            break;
        case 3: // 3-4-1-2
            gpiod_line_set_value(motor->in1, 0);
            gpiod_line_set_value(motor->in2, 0);
            gpiod_line_set_value(motor->in3, 1);
            gpiod_line_set_value(motor->in4, 1);
            break;
        default:
            fprintf(stderr, "Invalid step value\n");
            break;
    }
}

void motor_move(Motor *motor, int steps) {
    for (int i = 0; i < steps; i++) {
        for (int step = 0; step < 4; step++) {
            motor_set_step(motor, step);
            usleep(STEP_DELAY_US);
        }
    }
}

void motor_stop(Motor *motor) {
    gpiod_line_set_value(motor->in1, 0);
    gpiod_line_set_value(motor->in2, 0);
    gpiod_line_set_value(motor->in3, 0);
    gpiod_line_set_value(motor->in4, 0);
}

void motor_cleanup(Motor *motor) {
    gpiod_line_release(motor->in1);
    gpiod_line_release(motor->in2);
    gpiod_line_release(motor->in3);
    gpiod_line_release(motor->in4);
    gpiod_chip_close(gpiod_chip_from_fd(motor->chip_fd));
}

void signal_handler(int signal) {
    printf("Caught signal %d, stopping motors...\n", signal);
    motor_stop(&motor1);
    motor_stop(&motor2);
    motor_cleanup(&motor1);
    motor_cleanup(&motor2);
    exit(EXIT_SUCCESS);
}

int main() {
    Motor motor1, motor2;
    int steps_per_side;

    // Calculate steps for 50mm square
    double mm_per_step = (50.0 / SQUARE_SIZE_MM) * MM_TO_STEPS;
    steps_per_side = (int)mm_per_step;

    // Initialize motors
    motor_init(&motor1, 4, 17, 27, 22); // Motor 1 (X-axis)
    motor_init(&motor2, 5, 6, 13, 19);  // Motor 2 (Y-axis)

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Move motors to trace square
    printf("Moving motor1 (X-axis) %d steps...\n", steps_per_side);
    if (motor_move(&motor1, steps_per_side) < 0) {
        fprintf(stderr, "Failed to move motor1\n");
        signal_handler(SIGINT);
    }

    printf("Moving motor2 (Y-axis) %d steps...\n", steps_per_side);
    if (motor_move(&motor2, steps_per_side) < 0) {
        fprintf(stderr, "Failed to move motor2\n");
        signal_handler(SIGINT);
    }

    // Wait for user input before exiting
    printf("Press Ctrl+C to exit...\n");
    pause();

    return 0;
}

