        if (ioctl(gpio_fd, GPIO_GET_LINE_VALUES, &left) < 0) {
            log_message("Failed to read GPIO line values.");
            cleanup_gpio();
            return 1;
        }

        left = (left & (1 << GPIO_LEFT)) ? 1 : 0;
        center = (left & (1 << GPIO_CENTER)) ? 1 : 0;
        right = (left & (1 << GPIO_RIGHT)) ? 1 : 0;

        add_reading(&sensor_buffer, left, center, right);

        check_alert(&sensor_buffer);

        // Determine movement
        if (center == 0) {
            motor_forward();
        } else if (left == 0) {
            motor_left();
        } else if (right == 0) {
            motor_right();
        } else {
            motor_stop();
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    cleanup_gpio();
    return 0;
}

void init_gpio() {
    gpio_fd = open("/dev/gpiochip0", O_RDWR);
    if (gpio_fd < 0) {
        log_message("Failed to open GPIO device.");
        return -1;
    }

    if (ioctl(gpio_fd, GPIO_GET_LINE_COUNT, NULL) < 0) {
        log_message("Failed to get GPIO line count.");
        close(gpio_fd);
        return -1;
    }

    // Request lines for sensors and alert
    struct gpio_request_line_req req = {
        .line_offset = GPIO_LEFT,
        .flags = GPIO_LINE_FLAG_INPUT
    };
    if (ioctl(gpio_fd, GPIO_REQUEST_LINE, &req) < 0) {
        log_message("Failed to request GPIO line for left sensor.");
        close(gpio_fd);
        return -1;
    }

    req.line_offset = GPIO_CENTER;
    if (ioctl(gpio_fd, GPIO_REQUEST_LINE, &req) < 0) {
        log_message("Failed to request GPIO line for center sensor.");
        close(gpio_fd);
        return -1;
    }

    req.line_offset = GPIO_RIGHT;
    if (ioctl(gpio_fd, GPIO_REQUEST_LINE, &req) < 0) {
        log_message("Failed to request GPIO line for right sensor.");
        close(gpio_fd);
        return -1;
    }

    req.line_offset = GPIO_ALERT;
    req.flags = GPIO_LINE_FLAG_OUTPUT;
    if (ioctl(gpio_fd, GPIO_REQUEST_LINE, &req) < 0) {
        log_message("Failed to request GPIO line for alert.");
        close(gpio_fd);
        return -1;
    }

    return 0;
}

void cleanup_gpio() {
    if (gpio_fd >= 0) {
        struct gpio_request_line_req req = {
            .line_offset = GPIO_LEFT,
            .flags = GPIO_LINE_FLAG_INPUT
        };
        ioctl(gpio_fd, GPIO_RELEASE_LINE, &req);

        req.line_offset = GPIO_CENTER;
        ioctl(gpio_fd, GPIO_RELEASE_LINE, &req);

        req.line_offset = GPIO_RIGHT;
        ioctl(gpio_fd, GPIO_RELEASE_LINE, &req);

        req.line_offset = GPIO_ALERT;
        ioctl(gpio_fd, GPIO_RELEASE_LINE, &req);

        close(gpio_fd);
    }
}

void init_buffer(CircularBuffer *buffer) {
    buffer->head = 0;
    buffer->tail = 0;
    buffer->full = 0;
}

void add_reading(CircularBuffer *buffer, uint8_t left, uint8_t center, uint8_t right) {
    if (buffer->full) {
        buffer->tail = (buffer->tail + 1) % BUFFER_SIZE;
    }

    buffer->buffer[buffer->head].left = left;
    buffer->buffer[buffer->head].center = center;
    buffer->buffer[buffer->head].right = right;
    buffer->buffer[buffer->head].timestamp = time(NULL);

    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    buffer->full = (buffer->head == buffer->tail);
}

int get_last_n_readings(CircularBuffer *buffer, int n, uint8_t *lefts, uint8_t *centers, uint8_t *rights) {
    if (n > BUFFER_SIZE) {
        return -1;
    }

    int count = 0;
    int i = buffer->tail;
    while (count < n) {
        lefts[count] = buffer->buffer[i].left;
        centers[count] = buffer->buffer[i].center;
        rights[count] = buffer->buffer[i].right;
        count++;
        i = (i + 1) % BUFFER_SIZE;
    }

    return 0;
}

void check_alert(CircularBuffer *buffer) {
    uint8_t lefts[BUFFER_SIZE];
    uint8_t centers[BUFFER_SIZE];
    uint8_t rights[BUFFER_SIZE];

    if (get_last_n_readings(buffer, CONSECUTIVE_NO_LINE, lefts, centers, rights) == 0) {
        int no_line_count = 0;
        for (int i = 0; i < CONSECUTIVE_NO_LINE; i++) {
            if (centers[i] == 1) {
                no_line_count = 0;
            } else {
                no_line_count++;
            }
        }

        if (no_line_count == CONSECUTIVE_NO_LINE) {
            log_message("Center sensor no line for 5 consecutive readings. Activating alert.");
            // Set alert pin HIGH
