            values.values = 1 << GPIO_ALERT;
            if (ioctl(gpio_fd, GPIO_SET_LINE_VALUES, &values) < 0) {
                log_message("Failed to set alert pin HIGH.");
            }
            usleep(ALERT_DURATION_S * 1000000);
            // Set alert pin LOW
            values.values = 0;
            if (ioctl(gpio_fd, GPIO_SET_LINE_VALUES, &values) < 0) {
                log_message("Failed to set alert pin LOW.");
            }
        }
    }
}

