code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>
#include <errno.h>

#define I2C_BUS 1
#define I2C_ADDR 0x40
#define RELAY_PIN 17
#define THRESHOLD_MG 5000
#define POLL_ATTEMPTS 50
#define SAMPLE_INTERVAL_MS 100
#define LOG_FILE "magnetic_events.txt"

typedef struct {
    int i2c_fd;
    struct gpiod_line *relay_line;
    FILE *log_file;
} AppContext;

void log_message(const char *message, AppContext *ctx) {
    time_t now;
    struct tm *timeinfo;
    char timestamp[20];

    time(&now);
    timeinfo = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(ctx->log_file, "[%s] %s\n", timestamp, message);
    fflush(ctx->log_file);
}

void handle_sigint(int sig) {
    log_message("SIGINT received, shutting down...", NULL);
    exit(EXIT_SUCCESS);
}

int init_i2c(AppContext *ctx) {
    char i2c_bus_path[32];
    snprintf(i2c_bus_path, sizeof(i2c_bus_path), "/dev/i2c-%d", I2C_BUS);

    ctx->i2c_fd = open(i2c_bus_path, O_RDWR);
    if (ctx->i2c_fd < 0) {
        log_message("Failed to open I2C bus", ctx);
        return -1;
    }

    if (ioctl(ctx->i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        log_message("Failed to set I2C slave address", ctx);
        close(ctx->i2c_fd);
        return -1;
    }

    return 0;
}

int read_magnetic_field(AppContext *ctx, int *field) {
    unsigned char reg = 0x00; // Register for magnetic field
    unsigned char buffer[2];

    if (write(ctx->i2c_fd, &reg, 1) < 0) {
        log_message("I2C write failed", ctx);
        return -1;
    }

    usleep(1000); // Wait for conversion

    if (read(ctx->i2c_fd, buffer, 2) < 0) {
        log_message("I2C read failed", ctx);
        return -1;
    }

    *field = (buffer[0] << 8) | buffer[1];
    return 0;
}

int init_relay(AppContext *ctx) {
    struct gpiod_chip *chip;
    struct gpiod_line *line;

    chip = gpiod_chip_open_by_number(RELAY_PIN / 32);
    if (!chip) {
        log_message("Failed to open GPIO chip", ctx);
        return -1;
    }

    line = gpiod_line_get(chip, RELAY_PIN % 32);
    if (!line) {
        log_message("Failed to get GPIO line", ctx);
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(line, "relay", 0) < 0) {
        log_message("Failed to request GPIO line as output", ctx);
        gpiod_line_put(line);
        gpiod_chip_close(chip);
        return -1;
    }

    ctx->relay_line = line;
    return 0;
}

void deactivate_relay(AppContext *ctx) {
    if (ctx->relay_line) {
        gpiod_line_set_value(ctx->relay_line, 0);
    }
}

void activate_relay(AppContext *ctx) {
    if (ctx->relay_line) {
        gpiod_line_set_value(ctx->relay_line, 1);
    }
}

int main() {
    AppContext ctx = {0};
    int field;
    int retry_count = 0;
    int poll_count = 0;
    int last_relay_state = 0;
    struct sigaction sa;

    // Initialize logging
    ctx.log_file = fopen(LOG_FILE, "a");
    if (!ctx.log_file) {
        log_message("Failed to open log file", &ctx);
        return EXIT_FAILURE;
    }

    // Set up signal handler
    sa.sa_handler = handle_sigint;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        log_message("Failed to set up signal handler", &ctx);
        fclose(ctx.log_file);
        return EXIT_FAILURE;
    }

    // Initialize I2C
    if (init_i2c(&ctx) < 0) {
        fclose(ctx.log_file);
        return EXIT_FAILURE;
    }

    // Initialize relay
    if (init_relay(&ctx) < 0) {
        fclose(ctx.log_file);
        close(ctx.i2c_fd);
        return EXIT_FAILURE;
    }

    while (1) {
        // Read magnetic field
        if (read_magnetic_field(&ctx, &field) < 0) {
            log_message("Failed to read magnetic field", &ctx);
            deactivate_relay(&ctx);
            retry_count++;
            if (retry_count >= POLL_ATTEMPTS) {
                log_message("Timeout: Failed to read magnetic field after 50 attempts", &ctx);
                retry_count = 0;
            }
            usleep(SAMPLE_INTERVAL_MS * 1000);
            continue;
        }

        retry_count = 0;

        // Log reading
        log_message("Magnetic field: %d mG", &ctx);

        // Check threshold
        if (field > THRESHOLD_MG) {
