    AppContext ctx = {0};
    int field;
    int retry_count = 0;
    int poll_count = 0;
    int last_relay_state = 0;
    struct sigaction sa;

    // Initialize logging
    ctx.log_file = fopen(LOG_FILE, "a");
    if (!ctx.log_file) {
        log_message("Failed to open log file", &ctx);
        return EXIT_FAILURE;
    }

    // Set up signal handler
    sa.sa_handler = handle_sigint;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        log_message("Failed to set up signal handler", &ctx);
        fclose(ctx.log_file);
        return EXIT_FAILURE;
    }

    // Initialize I2C
    if (init_i2c(&ctx) < 0) {
        fclose(ctx.log_file);
        return EXIT_FAILURE;
    }

    // Initialize relay
    if (init_relay(&ctx) < 0) {
        fclose(ctx.log_file);
        close(ctx.i2c_fd);
        return EXIT_FAILURE;
    }

    while (1) {
        // Read magnetic field
        if (read_magnetic_field(&ctx, &field) < 0) {
            log_message("Failed to read magnetic field", &ctx);
            deactivate_relay(&ctx);
            retry_count++;
            if (retry_count >= POLL_ATTEMPTS) {
                log_message("Timeout: Failed to read magnetic field after 50 attempts", &ctx);
                retry_count = 0;
            }
            usleep(SAMPLE_INTERVAL_MS * 1000);
            continue;
        }

        retry_count = 0;

        // Log reading
        log_message("Magnetic field: %d mG", &ctx);

        // Check threshold
        if (field > THRESHOLD_MG) {
            if (last_relay_state == 0) {
                activate_relay(&ctx);
                log_message("Relay activated due to magnetic field exceeding threshold", &ctx);
                last_relay_state = 1;
            }
        } else {
            if (last_relay_state == 1) {
                deactivate_relay(&ctx);
                log_message("Relay deactivated as magnetic field is below threshold", &ctx);
                last_relay_state = 0;
            }
        }

        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    // Cleanup
