typedef enum { OFF, ON } RelayState;

// Global variables
int server_fd = -1;
int client_fd = -1;
struct gpiod_line *gpio_line = NULL;
FILE *log_file = NULL;
RelayState current_state = OFF;
int running = 1;

// Function declarations
void handle_signal(int sig);
void log_event(const char *message);
void toggle_relay();
void close_all_resources();
void handle_client();
void init_gpio();
void init_socket();

int main() {
    // Initialize signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Initialize GPIO
    if (init_gpio() != 0) {
