            close_all_resources();
            return 1;
        }

        handle_client();
        close(client_fd);
    }

    close_all_resources();
    return 0;
}

void handle_signal(int sig) {
    running = 0;
    close_all_resources();
    exit(EXIT_SUCCESS);
}

void close_all_resources() {
    if (gpio_line) {
        gpiod_line_release(gpio_line);
        gpio_line = NULL;
    }

    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }

    if (client_fd >= 0) {
        close(client_fd);
    }

    if (server_fd >= 0) {
        close(server_fd);
    }
}

void log_event(const char *message) {
    if (!log_file) {
        log_file = fopen(LOG_FILE, "a");
        if (!log_file) {
            perror("fopen");
            return;
        }
    }

    time_t now;
    char timestamp[20];
    struct tm *tm_info;

    time(&now);
    tm_info = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(log_file, "[%s] %s\n", timestamp, message);
    fflush(log_file);
}

void toggle_relay() {
    int value = (current_state == ON) ? 0 : 1;
    int ret = gpiod_line_set_value(gpio_line, value);
    if (ret < 0) {
        fprintf(stderr, "Failed to set GPIO value: %s\n", strerror(errno));
        return;
    }

    current_state = (current_state == ON) ? OFF : ON;
    log_event(current_state == ON ? "Relay turned ON" : "Relay turned OFF");
}

void init_gpio() {
    struct gpiod_chip *chip;
    struct gpiod_line_config config = GPIOD_LINE_CONFIG_DEFAULTS;

    chip = gpiod_chip_open_by_number(1); // BCM2 (GPIO 18 is on chip 1)
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    config.consumer = "relay_control";
    config.direction = GPIOD_LINE_DIRECTION_OUTPUT;
    config.flags = GPIOD_LINE_FLAG_ACTIVE_LOW;

    gpio_line = gpiod_line_request(chip, GPIO_PIN, &config);
    if (!gpio_line) {
        fprintf(stderr, "Failed to request GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    // Set initial state to OFF
    gpiod_line_set_value(gpio_line, 1);
    current_state = OFF;
    log_event("Relay initialized to OFF");

    gpiod_chip_close(chip);
    return 0;
}

void init_socket() {
    struct sockaddr_in server_addr;

    // Create socket
    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd < 0) {
        perror("socket");
        return -1;
    }

    // Set socket options
    int opt = 1;
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) < 0) {
        perror("setsockopt");
        close(server_fd);
        return -1;
    }

    // Bind socket
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_addr.s_addr = INADDR_ANY;
    server_addr.sin_port = htons(PORT);

    if (bind(server_fd, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("bind");
        close(server_fd);
        return -1;
    }

    // Listen for incoming connections
    if (listen(server_fd, 3) < 0) {
        perror("listen");
        close(server_fd);
        return -1;
    }

    return 0;
}

void handle_client() {
    char buffer[MAX_COMMAND_LENGTH];
    ssize_t bytes_read;

    // Read command from client
    bytes_read = read(client_fd, buffer, sizeof(buffer));
    if (bytes_read < 0) {
        perror("read");
        log_event("Failed to read command from client");
        return;
    }

    // Remove trailing whitespace
    char *ptr = buffer + bytes_read - 1;
    while (ptr >= buffer && isspace(*ptr)) {
        *ptr-- = '\0';
    }

    // Convert to uppercase
    for (int i = 0; i < bytes_read; i++) {
        buffer[i] = toupper(buffer[i]);
    }

    // Process command
    if (strcmp(buffer, "ON") == 0) {
        toggle_relay();
    } else if (strcmp(buffer, "OFF") == 0) {
        toggle_relay();
    } else {
        log_event("Invalid command received");
    }
}

