#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <time.h>

#define I2C_BUS 1
#define SENSOR1_ADDR 0x40
#define SENSOR2_ADDR 0x41
#define GPIO_PIN 18
#define POLLING_INTERVAL_MS 100
#define MIN_FLOW_ML_PER_MIN 5.0
#define CRC_POLY 0x07
#define CRC_INIT 0x00

// CRC-8 calculation function
unsigned char crc8(const unsigned char *data, size_t len) {
    unsigned char crc = CRC_INIT;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLY;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read data from I2C sensor
int read_sensor(int fd, unsigned char addr, unsigned char *buffer, size_t len) {
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Failed to set I2C slave address");
        return -1;
    }

    if (read(fd, buffer, len) != len) {
        perror("Failed to read from I2C sensor");
        return -1;
    }

    return 0;
}

// Function to write start measurement command to I2C sensor
int write_start_measurement(int fd, unsigned char addr, const unsigned char *cmd, size_t len) {
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Failed to set I2C slave address");
        return -1;
    }

    if (write(fd, cmd, len) != len) {
        perror("Failed to write start measurement command");
        return -1;
    }

    return 0;
}

// Function to convert flow data to ml/min
double flow_to_ml_per_min(const unsigned char *data) {
    // Assuming data[0] is the high byte, data[1] is the low byte
    unsigned int raw = (data[0] << 8) | data[1];
    return (double)raw * 0.01; // 1 unit = 0.01 ml/min
}

// Signal handler for shutdown
void handle_shutdown(int sig) {
    printf("Shutting down...\n");
    exit(EXIT_SUCCESS);
}

int main() {
    int i2c_fd1, i2c_fd2;
    struct gpiod_line *relay_line;
    unsigned char sensor1_data[3], sensor2_data[3];
    unsigned char cmd[2] = {0x01, 0x02}; // Example start measurement command
    FILE *log_file;
    struct timespec ts;
    int running = 1;

    // Set up signal handling
    signal(SIGINT, handle_shutdown);
    signal(SIGTERM, handle_shutdown);

    // Open I2C bus for sensor 1
    i2c_fd1 = open("/dev/i2c-1", O_RDWR | O_CLOEXEC);
    if (i2c_fd1 < 0) {
        perror("Failed to open I2C bus 1");
        return EXIT_FAILURE;
    }

    // Open I2C bus for sensor 2
    i2c_fd2 = open("/dev/i2c-1", O_RDWR | O_CLOEXEC);
    if (i2c_fd2 < 0) {
        perror("Failed to open I2C bus 1");
        close(i2c_fd1);
        return EXIT_FAILURE;
    }

    // Write start measurement command to sensor 1
    if (write_start_measurement(i2c_fd1, SENSOR1_ADDR, cmd, sizeof(cmd)) < 0) {
        fprintf(stderr, "Failed to write start measurement command to sensor 1\n");
        close(i2c_fd1);
        close(i2c_fd2);
        return EXIT_FAILURE;
    }

    // Write start measurement command to sensor 2
    if (write_start_measurement(i2c_fd2, SENSOR2_ADDR, cmd, sizeof(cmd)) < 0) {
        fprintf(stderr, "Failed to write start measurement command to sensor 2\n");
        close(i2c_fd1);
        close(i2c_fd2);
        return EXIT_FAILURE;
    }

    // Initialize GPIO for relay
    struct gpiod_chip *chip;
    chip = gpiod_chip_open("/dev/gpiochip1");
    if (!chip) {
        perror("Failed to open GPIO chip");
        close(i2c_fd1);
        close(i2c_fd2);
        return EXIT_FAILURE;
    }

    relay_line = gpiod_line_get(chip, GPIO_PIN);
    if (!relay_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        close(i2c_fd1);
        close(i2c_fd2);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(relay_line, "relay", GPIOD_LINE_REQUEST_OUTPUT_ACTIVE_HIGH)) {
        perror("Failed to request GPIO line as output");
        gpiod_line_put(relay_line);
        gpiod_chip_close(chip);
        close(i2c_fd1);
        close(i2c_fd2);
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen("flow_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_line_put(relay_line);
        gpiod_chip_close(chip);
        close(i2c_fd1);
        close(i2c_fd2);
        return EXIT_FAILURE;
    }

    while (running) {
        // Read data from sensors
        if (read_sensor(i2c_fd1, SENSOR1_ADDR, sensor1_data, sizeof(sensor1_data)) < 0) {
