#define CRC_POLY 0x07
#define CRC_INIT 0x00

// CRC-8 calculation function
unsigned char crc8(const unsigned char *data, size_t len) {
    unsigned char crc = CRC_INIT;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLY;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read data from I2C sensor
int read_sensor(int fd, unsigned char addr, unsigned char *buffer, size_t len) {
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Failed to set I2C slave address");
        return -1;
    }

    if (read(fd, buffer, len) != len) {
        perror("Failed to read from I2C sensor");
        return -1;
    }

    return 0;
}

// Function to write start measurement command to I2C sensor
int write_start_measurement(int fd, unsigned char addr, const unsigned char *cmd, size_t len) {
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Failed to set I2C slave address");
        return -1;
    }

    if (write(fd, cmd, len) != len) {
        perror("Failed to write start measurement command");
        return -1;
    }

    return 0;
}

// Function to convert flow data to ml/min
double flow_to_ml_per_min(const unsigned char *data) {
    // Assuming data[0] is the high byte, data[1] is the low byte
    unsigned int raw = (data[0] << 8) | data[1];
    return (double)raw * 0.01; // 1 unit = 0.01 ml/min
}

