            log_error("Failed to set IN1 low", errno);
        }
    }
    if (state->in2) {
        if (gpiod_line_set_value(state->in2, 0) < 0) {
            log_error("Failed to set IN2 low", errno);
        }
    }
}

void handle_signal(int signum) {
    syslog(LOG_INFO, "Received signal %d, shutting down gracefully", signum);
    cleanup_gpio(&app_state);
    gpiod_line_release(app_state.rain_do);
    gpiod_line_release(app_state.ena);
    gpiod_line_release(app_state.in1);
    gpiod_line_release(app_state.in2);
    closelog();
    exit(EXIT_SUCCESS);
}

void start_motor(app_state_t *state) {
    if (gpiod_line_set_value(state->ena, 1) < 0) {
        log_error("Failed to set ENA high", errno);
        return;
    }
    if (gpiod_line_set_value(state->in1, 1) < 0) {
        log_error("Failed to set IN1 high", errno);
        return;
    }
    if (gpiod_line_set_value(state->in2, 0) < 0) {
        log_error("Failed to set IN2 low", errno);
        return;
    }
    state->state = STATE_MOTOR_RUNNING;
    state->last_motor_start = time(NULL);
    log_event("Motor started", LOG_INFO);
}

void stop_motor(app_state_t *state) {
    if (gpiod_line_set_value(state->ena, 0) < 0) {
        log_error("Failed to set ENA low", errno);
        return;
    }
    if (gpiod_line_set_value(state->in1, 0) < 0) {
        log_error("Failed to set IN1 low", errno);
        return;
    }
    if (gpiod_line_set_value(state->in2, 0) < 0) {
        log_error("Failed to set IN2 low", errno);
        return;
    }
    state->state = STATE_IDLE;
    log_event("Motor stopped", LOG_INFO);
}

