        return EXIT_FAILURE;
    }

    // Set pull-up for rain DO
    if (gpiod_line_request_output(app_state.rain_do, "rain_do", 0) < 0) {
        log_error("Failed to request rain DO line", errno);
        return EXIT_FAILURE;
    }

    if (gpiod_line_set_value(app_state.rain_do, 1) < 0) {
        log_error("Failed to set rain DO pull-up", errno);
        return EXIT_FAILURE;
    }

    // Set direction for motor control lines
    if (gpiod_line_request_output(app_state.ena, "ena", 0) < 0) {
        log_error("Failed to request ENA line", errno);
        return EXIT_FAILURE;
    }

