        gpiod_line_release(state.pir_line);
        gpiod_chip_close(pir_chip);
        exit(EXIT_FAILURE);
    }

    state.relay_line = gpiod_chip_get_line(relay_chip, RELAY_GPIO);
    if (!state.relay_line) {
        perror("gpiod_chip_get_line");
        gpiod_line_release(state.pir_line);
        gpiod_chip_close(pir_chip);
        gpiod_chip_close(relay_chip);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(state.relay_line, "relay_control", 0) < 0) {
        perror("gpiod_line_request_output");
        gpiod_line_release(state.pir_line);
        gpiod_line_release(state.relay_line);
        gpiod_chip_close(pir_chip);
        gpiod_chip_close(relay_chip);
        exit(EXIT_FAILURE);
    }

    // Open log file
    state.log_file = fopen(LOG_FILE, "a");
    if (!state.log_file) {
        perror("fopen");
        gpiod_line_release(state.pir_line);
        gpiod_line_release(state.relay_line);
        gpiod_chip_close(pir_chip);
        gpiod_chip_close(relay_chip);
        exit(EXIT_FAILURE);
    }

    // Main loop
    state.running = 1;
    while (state.running) {
        // Read PIR state
        int pir_value = gpiod_line_get_value(state.pir_line);
        if (pir_value < 0) {
            perror("gpiod_line_get_value");
            state.running = 0;
            break;
        }

        if (pir_value == 1) {
            // Motion detected
            time_t now = time(NULL);
            struct tm *tm_now = gmtime(&now);
            char timestamp[64];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm_now);

            // Turn on relay
            if (gpiod_line_set_value(state.relay_line, 1) < 0) {
                perror("gpiod_line_set_value");
                state.running = 0;
                break;
            }

            // Log activation
            log_event(state.log_file, "Motion detected", timestamp, "");

            // Wait for 60 seconds
            sleep(RELAY_DURATION);

            // Turn off relay
            if (gpiod_line_set_value(state.relay_line, 0) < 0) {
                perror("gpiod_line_set_value");
                state.running = 0;
                break;
            }

            // Log deactivation
            time_t end_time = time(NULL);
            struct tm *tm_end = gmtime(&end_time);
            char end_timestamp[64];
            strftime(end_timestamp, sizeof(end_timestamp), "%Y-%m-%dT%H:%M:%SZ", tm_end);
            char duration[32];
            snprintf(duration, sizeof(duration), "%d", RELAY_DURATION);
            log_event(state.log_file, "Motion ended", end_timestamp, duration);
        }

        // Polling interval
        usleep(POLLING_INTERVAL_MS * 1000);
    }

    // Clean up
    if (state.relay_line) {
        gpiod_line_release(state.relay_line);
    }
    if (state.pir_line) {
        gpiod_line_release(state.pir_line);
    }
    if (pir_chip) {
        gpiod_chip_close(pir_chip);
    }
    if (relay_chip) {
        gpiod_chip_close(relay_chip);
    }
    if (state.log_file) {
        fclose(state.log_file);
    }

    exit(EXIT_SUCCESS);
}
