#include <gpiod.h>

#define I2C_BUS 1
#define I2C_ADDR 0x5A
#define RELAY_PIN 17
#define DEBOUNCE_DELAY_MS 200
#define ELEC_COUNT 12

typedef struct {
    int i2c_fd;
    struct gpiod_line *relay_line;
    int touch_state[ELEC_COUNT];
    int last_touch_state[ELEC_COUNT];
    int touch_count[ELEC_COUNT];
    int debounce_timer[ELEC_COUNT];
} TouchRelayContext;

void handle_signal(int sig) {
    exit(EXIT_SUCCESS);
}

int i2c_init(int bus, int addr) {
    char filename[20];
    snprintf(filename, sizeof(filename), "/dev/i2c-%d", bus);
    int fd = open(filename, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Failed to set I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

void mpr121_init(int fd) {
    unsigned char config[3] = {0};

    // Soft reset
    config[0] = 0x2F; // Soft reset
    if (write(fd, config, 1) != 1) {
        perror("Failed to send soft reset");
        exit(EXIT_FAILURE);
    }

    // Wait for reset to complete
    usleep(100000);

    // Configuration register
    config[0] = 0x5A; // MHD = 0x5A (100ms), NHD = 0x5A (100ms), NCL = 0x32 (50ms), FDL = 0x0A (10ms)
    if (write(fd, config, 1) != 1) {
        perror("Failed to write configuration register");
        exit(EXIT_FAILURE);
    }

    // Debounce register
    config[0] = 0x14; // Debounce = 0x14 (200ms)
    if (write(fd, config, 1) != 1) {
        perror("Failed to write debounce register");
        exit(EXIT_FAILURE);
    }

    // FFI, SFI, CDT register
    config[0] = 0x2C; // FFI = 0x2C (100ms), SFI = 0x2C (100ms), CDT = 0x2C (100ms)
    if (write(fd, config, 1) != 1) {
        perror("Failed to write FFI/SFI/CDT register");
        exit(EXIT_FAILURE);
    }

    // Auto-configure register
    config[0] = 0x55; // Enable auto-configure with range 0x55 (0-1000pF)
    if (write(fd, config, 1) != 1) {
        perror("Failed to write auto-configure register");
        exit(EXIT_FAILURE);
    }

    // Enable all 12 electrodes
    config[0] = 0xFF;
    if (write(fd, config, 1) != 1) {
        perror("Failed to enable all electrodes");
        exit(EXIT_FAILURE);
    }
}

int read_touch_state(int fd) {
    unsigned char data[2] = {0};
    if (read(fd, data, 2) != 2) {
        perror("Failed to read touch state");
        return -1;
    }
    return data[0];
}

void relay_init(int pin) {
    struct gpiod_chip *chip;
    struct gpiod_line *line;

    chip = gpiod_chip_open_by_number(1); // BCM GPIOs are on chip 1
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    line = gpiod_line_get(chip, pin);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(line, "Relay", 0) < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_line_put(line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Set initial state to OFF
    if (gpiod_line_set_value(line, 0) < 0) {
        perror("Failed to set relay to OFF");
        gpiod_line_put(line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    context.relay_line = line;
}

void relay_cleanup() {
    if (context.relay_line) {
        gpiod_line_put(context.relay_line);
    }
}

void touch_cleanup(int fd) {
    close(fd);
}

int main() {
    TouchRelayContext context = {0};

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Initialize I2C
    context.i2c_fd = i2c_init(I2C_BUS, I2C_ADDR);
    if (context.i2c_fd < 0) {
        exit(EXIT_FAILURE);
    }

    // Initialize MPR121
    mpr121_init(context.i2c_fd);

    // Initialize relay
    relay_init(RELAY_PIN);

    // Main loop
    while (1) {
        int touch_data = read_touch_state(context.i2c_fd);
        if (touch_data < 0) {
            fprintf(stderr, "I2C read failed, exiting.\n");
            break;
        }

        for (int i = 0; i < ELEC_COUNT; i++) {
            int current = (touch_data >> i) & 1;
            int last = context.last_touch_state[i];

            if (current != last) {
                context.touch_count[i]++;
                context.last_touch_state[i] = current;

                if (current == 1) {
                    context.debounce_timer[i] = DEBOUNCE_DELAY_MS;
                } else {
                    context.debounce_timer[i] = 0;
                }
            } else {
                context.touch_count[i] = 0;
            }

            if (current == 1 && context.debounce_timer[i] > 0) {
                context.debounce_timer[i]--;
            } else if (current == 1 && context.debounce_timer[i] == 0) {
                if (context.touch_count[i] == 1) {
                    // Toggle relay on first rising edge
                    int relay_state = gpiod_line_get_value(context.relay_line);
                    if (gpiod_line_set_value(context.relay_line, !relay_state) < 0) {
                        perror("Failed to toggle relay");
                    }
                }
                context.touch_count[i] = 0;
            }
        }

        usleep(10000); // 10ms delay
    }

    // Cleanup
    relay_cleanup();
    touch_cleanup(context.i2c_fd);

    return 0;
}

