    // Log to syslog
    syslog(LOG_USER | LOG_INFO, "[%s] %s", timestamp, log_entry);

    // Log to file
    if (AppContext.log_fd != -1) {
        fprintf(AppContext.log_fd, "[%s] %s\n", timestamp, log_entry);
        fflush(AppContext.log_fd);
    }
}

void handle_error(const char *fmt, ...) {
    va_list args;
    va_start(args, fmt);
    vfprintf(stderr, fmt, args);
    va_end(args);
    log_message(fmt, args);
    exit(EXIT_FAILURE);
}

void init_gpio(AppContext *ctx) {
    ctx->servo_line = gpiod_line_get("gpiochip0", GPIO_SERVO_PIN);
    if (!ctx->servo_line) {
        handle_error("Failed to get GPIO line for servo: %s\n", strerror(errno));
    }

    if (gpiod_line_request_output(ctx->servo_line, "servo", 0) < 0) {
        handle_error("Failed to request GPIO line for servo: %s\n", strerror(errno));
    }

    ctx->pir_line = gpiod_line_get("gpiochip0", GPIO_PIR_PIN);
    if (!ctx->pir_line) {
        handle_error("Failed to get GPIO line for PIR: %s\n", strerror(errno));
    }

    if (gpiod_line_request_input(ctx->pir_line, "pir", 0) < 0) {
        handle_error("Failed to request GPIO line for PIR: %s\n", strerror(errno));
    }
}

void init_log(AppContext *ctx) {
    AppContext.log_fd = open(LOG_FILE, O_WRONLY | O_APPEND | O_CREAT, 0644);
    if (AppContext.log_fd == -1) {
        handle_error("Failed to open log file: %s\n", strerror(errno));
    }
}

void close_log(AppContext *ctx) {
    if (AppContext.log_fd != -1) {
        close(AppContext.log_fd);
    }
}

void close_gpio(AppContext *ctx) {
    if (ctx->servo_line) {
        gpiod_line_release(ctx->servo_line);
    }
    if (ctx->pir_line) {
        gpiod_line_release(ctx->pir_line);
    }
}

void handle_signal(int sig) {
    AppContext.running = 0;
}

void send_servo_angle(int angle) {
    if (angle < 0 || angle > 180) {
        handle_error("Invalid servo angle: %d\n", angle);
    }

    // Convert angle to pulse width (1-2ms)
    int pulse_width = 1000 + (angle * 1000) / 180;
    int duration = pulse_width * 1000; // in microseconds

    // Set high
    if (gpiod_line_set_value(ctx->servo_line, 1) < 0) {
        handle_error("Failed to set servo line high: %s\n", strerror(errno));
    }

    usleep(duration);

    // Set low
    if (gpiod_line_set_value(ctx->servo_line, 0) < 0) {
        handle_error("Failed to set servo line low: %s\n", strerror(errno));
    }
}

void handle_client(int client_sock) {
    char buffer[MAX_MSG_LEN];
    int bytes_read;

    while ((bytes_read = read(client_sock, buffer, MAX_MSG_LEN)) > 0) {
        buffer[bytes_read] = '\0';
        log_message("Received command: %s", buffer);

        if (strncmp(buffer, "servo", 5) == 0) {
            char *endptr;
            int angle = strtol(buffer + 5, &endptr, 10);
            if (endptr == buffer + 5 || *endptr != '\0') {
                log_message("Invalid command format: %s", buffer);
                continue;
            }
            send_servo_angle(angle);
        } else if (strncmp(buffer, "PIR", 3) == 0) {
            int pir_state = gpiod_line_get_value(ctx->pir_line);
            char response[16];
            snprintf(response, sizeof(response), "PIR:%d", pir_state);
            write(client_sock, response, strlen(response));
            log_message("Sent PIR state: %s", response);
        } else {
            log_message("Unknown command: %s", buffer);
        }
    }

    close(client_sock);
}

int main() {
    AppContext ctx = {0};
    struct sockaddr_in server_addr;
    int server_sock;
    socklen_t addr_len = sizeof(server_addr);

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    init_gpio(&ctx);
    init_log(&ctx);

    // Initialize syslog
    openlog("servo_pir_server", LOG_PID, LOG_USER);

    // Create socket
    server_sock = socket(AF_INET, SOCK_STREAM, 0);
    if (server_sock == -1) {
        handle_error("Failed to create socket: %s\n", strerror(errno));
    }

    // Set socket options
    int opt = 1;
    if (setsockopt(server_sock, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) < 0) {
        handle_error("Failed to set socket options: %s\n", strerror(errno));
    }

    // Bind socket
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_addr.s_addr = INADDR_ANY;
    server_addr.sin_port = htons(PORT);

    if (bind(server_sock, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        handle_error("Failed to bind socket: %s\n", strerror(errno));
    }

    // Listen
    if (listen(server_sock, 5) < 0) {
        handle_error("Failed to listen on socket: %s\n", strerror(errno));
    }

    log_message("Server started on port %d", PORT);

    while (ctx.running) {
        int client_sock = accept(server_sock, (struct sockaddr *)&server_addr, &addr_len);
        if (client_sock < 0) {
            if (errno != EINTR) {
                handle_error("Failed to accept connection: %s\n", strerror(errno));
            }
            continue;
        }

        handle_client(client_sock);
    }

    close(server_sock);
    close_log(&ctx);
    close_gpio(&ctx);

    closelog();
    return 0;
}
