#include <libgpiod.h>

#define GPIO_DOUT 23
#define GPIO_SCK 24
#define GPIO_SOLENOID 25

#define MAX_RETRIES 3
#define POLL_INTERVAL_MS 500
#define DEFAULT_THRESHOLD 1000
#define DEFAULT_SCALE 1.0
#define DEFAULT_DURATION_MS 200

typedef struct {
    int threshold;
    double scale;
    int duration;
} config_t;

static config_t config = {DEFAULT_THRESHOLD, DEFAULT_SCALE, DEFAULT_DURATION_MS};

static int gpio_dout;
static int gpio_sck;
static int gpio_solenoid;
static struct gpiod_line *line_dout;
static struct gpiod_line *line_sck;
static struct gpiod_line *line_solenoid;

void log_message(const char *fmt, ...) {
    va_list args;
    va_start(args, fmt);
    vsyslog(LOG_INFO, fmt, args);
    va_end(args);
}

void log_error(const char *fmt, ...) {
    va_list args;
    va_start(args, fmt);
    vsyslog(LOG_ERR, fmt, args);
    va_end(args);
}

int read_hx711_24bit() {
    int data = 0;
    int retries = 0;
    int timeout = 0;

    // Wait for DOUT to go LOW
    while (gpiod_line_get_value(line_dout) != 0 && retries < MAX_RETRIES) {
        usleep(100000); // 100ms
        retries++;
    }

    if (retries >= MAX_RETRIES) {
        log_error("DOUT did not go LOW within %d seconds", MAX_RETRIES);
        return -1;
    }

    // Clock out 24 bits
    for (int i = 0; i < 24; i++) {
        gpiod_line_set_value(line_sck, 1);
        usleep(10); // 10us
        gpiod_line_set_value(line_sck, 0);
        usleep(10); // 10us

        if (gpiod_line_get_value(line_dout) == 1) {
            data |= (1 << (23 - i));
        }
    }

    // One extra clock pulse to select Channel A gain 128
    gpiod_line_set_value(line_sck, 1);
    usleep(10);
    gpiod_line_set_value(line_sck, 0);
    usleep(10);

    return data;
}

int get_weight() {
    int sum = 0;
    int retries = 0;

    for (int i = 0; i < 5; i++) {
        int value = read_hx711_24bit();
        if (value < 0) {
            log_error("Failed to read HX711 value");
            return -1;
        }
        sum += value;
        usleep(10000); // 10ms
    }

    return sum / 5;
}

void handle_signal(int sig) {
    (void)sig;
    log_message("Received signal, shutting down...");

    // Ensure solenoid is off
    gpiod_line_set_value(line_solenoid, 0);

    // Release GPIO lines
    gpiod_line_release(line_dout);
    gpiod_line_release(line_sck);
    gpiod_line_release(line_solenoid);

    // Close syslog
    closelog();

    exit(EXIT_SUCCESS);
}

void init_gpio() {
    struct gpiod_chip *chip;
    int ret;

    // Open GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        log_error("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    // Configure DOUT (GPIO23)
    line_dout = gpiod_chip_get_line(chip, GPIO_DOUT);
    if (!line_dout) {
        log_error("Failed to get DOUT line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_request_output(line_dout, "hx711_dout", 0);
    if (ret < 0) {
        log_error("Failed to request DOUT line");
        gpiod_line_release(line_dout);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Configure SCK (GPIO24)
    line_sck = gpiod_chip_get_line(chip, GPIO_SCK);
    if (!line_sck) {
        log_error("Failed to get SCK line");
        gpiod_line_release(line_dout);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_request_output(line_sck, "hx711_sck", 0);
    if (ret < 0) {
        log_error("Failed to request SCK line");
        gpiod_line_release(line_dout);
        gpiod_line_release(line_sck);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Configure Solenoid (GPIO25)
    line_solenoid = gpiod_chip_get_line(chip, GPIO_SOLENOID);
    if (!line_solenoid) {
        log_error("Failed to get solenoid line");
        gpiod_line_release(line_dout);
        gpiod_line_release(line_sck);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_request_output(line_solenoid, "solenoid", 0);
    if (ret < 0) {
