#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <libgpiod.h>
#include <mosquitto.h>

#define GPIO_PIN 17
#define MQTT_TOPIC "home/lights/control"
#define MQTT_CLIENT_ID "relay_controller_1"
#define MQTT_BROKER "localhost"
#define MQTT_PORT 1883
#define MQTT_KEEPALIVE 60
#define MQTT_QOS 0
#define RECONNECT_DELAY 5
#define SYSLOG_FACILITY LOG_USER
#define SYSLOG_TAG "mqtt_relay"

typedef enum {
    STATE_DISCONNECTED,
    STATE_CONNECTED
} state_t;

typedef struct {
    int gpio_fd;
    struct gpiod_line *line;
    mosquitto *mosq;
    state_t state;
    int reconnect_timer;
} app_t;

void syslog_message(int priority, const char *fmt, ...) {
    va_list args;
    va_start(args, fmt);
    vsyslog(priority, fmt, args);
    va_end(args);
}

void signal_handler(int sig) {
    syslog_message(LOG_ERR, "Received signal %d, shutting down...", sig);
    // Set GPIO to LOW
    if (app->line) {
        gpiod_line_set_value(app->line, 0);
    }
    // Disconnect MQTT
    if (app->mosq) {
        mosquitto_disconnect(app->mosq);
    }
    // Destroy MQTT
    if (app->mosq) {
        mosquitto_destroy(app->mosq);
    }
    // Cleanup GPIO
    if (app->line) {
        gpiod_line_release(app->line);
    }
    if (app->gpio_fd >= 0) {
        close(app->gpio_fd);
    }
    // Close syslog
    closelog();
    exit(EXIT_SUCCESS);
}

void on_connect(struct mosquitto *mosq, void *obj, int rc) {
    if (rc == 0) {
        syslog_message(LOG_INFO, "Connected to MQTT broker");
        app->state = STATE_CONNECTED;
        mosquitto_subscribe(mosq, NULL, MQTT_TOPIC, MQTT_QOS);
    } else {
        syslog_message(LOG_ERR, "Failed to connect to MQTT broker, error code %d", rc);
        app->state = STATE_DISCONNECTED;
    }
}

void on_message(struct mosquitto *mosq, void *obj, const struct mosquitto_message *msg, void *userdata) {
    if (msg->payloadlen == 0) {
        syslog_message(LOG_ERR, "Received empty payload");
        return;
    }

    char *payload = (char *)msg->payload;
    if (strcmp(payload, "ON") == 0) {
        if (app->line) {
            gpiod_line_set_value(app->line, 1);
            syslog_message(LOG_INFO, "Relay turned ON");
        }
    } else if (strcmp(payload, "OFF") == 0) {
        if (app->line) {
            gpiod_line_set_value(app->line, 0);
            syslog_message(LOG_INFO, "Relay turned OFF");
        }
    } else {
        syslog_message(LOG_ERR, "Invalid payload: %s", payload);
    }
}

void on_disconnect(struct mosquitto *mosq, void *obj, int rc) {
    syslog_message(LOG_ERR, "Disconnected from MQTT broker, error code %d", rc);
    app->state = STATE_DISCONNECTED;
}

int init_gpio(app_t *app) {
    app->gpio_fd = gpiod_open(GPIO_PIN, GPIOD_LINE_DIRECTION_OUTPUT);
    if (app->gpio_fd < 0) {
        syslog_message(LOG_ERR, "Failed to open GPIO %d", GPIO_PIN);
        return -1;
    }

    struct gpiod_line_config config = GPIOD_LINE_CONFIG_DEFAULTS;
    config.direction = GPIOD_LINE_DIRECTION_OUTPUT;
    config.output_value = 0;

    app->line = gpiod_line_request_fd(app->gpio_fd, "relay_control", "relay_control", &config);
    if (!app->line) {
        syslog_message(LOG_ERR, "Failed to request GPIO line %d", GPIO_PIN);
        gpiod_close(app->gpio_fd);
        return -1;
    }

    if (gpiod_line_set_value(app->line, 0) < 0) {
        syslog_message(LOG_ERR, "Failed to set GPIO %d to LOW", GPIO_PIN);
        gpiod_line_release(app->line);
        gpiod_close(app->gpio_fd);
        return -1;
    }

    syslog_message(LOG_INFO, "GPIO %d initialized to LOW (relay OFF)", GPIO_PIN);
    return 0;
}

int init_mqtt(app_t *app) {
    app->mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!app->mosq) {
        syslog_message(LOG_ERR, "Failed to create MQTT client");
        return -1;
    }

    int rc = mosquitto_connect_async(app->mosq, MQTT_BROKER, MQTT_PORT, MQTT_KEEPALIVE);
    if (rc != MOSQ_ERR_SUCCESS) {
        syslog_message(LOG_ERR, "Failed to connect MQTT client, error code %d", rc);
        mosquitto_destroy(app->mosq);
        return -1;
    }

    mosquitto_message_callback_set(app->mosq, on_message);
    mosquitto_connect_callback_set(app->mosq, on_connect);
    mosquitto_disconnect_callback_set(app->mosq, on_disconnect);

    rc = mosquitto_subscribe(app->mosq, NULL, MQTT_TOPIC, MQTT_QOS);
    if (rc != MOSQ_ERR_SUCCESS) {
        syslog_message(LOG_ERR, "Failed to subscribe to topic, error code %d", rc);
        mosquitto_destroy(app->mosq);
        return -1;
    }

    syslog_message(LOG_INFO, "MQTT client initialized and subscribed to topic");
    return 0;
}

int main(int argc, char *argv[]) {
    app_t app = {0};

    // Initialize syslog
    openlog(SYSLOG_TAG, LOG_PID, SYSLOG_FACILITY);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (init_gpio(&app) != 0) {
        syslog_message(LOG_ERR, "Failed to initialize GPIO, exiting...");
        closelog();
        return EXIT_FAILURE;
    }

    // Initialize MQTT
    if (init_mqtt(&app) != 0) {
        syslog_message(LOG_ERR, "Failed to initialize MQTT, exiting...");
        closelog();
        return EXIT_FAILURE;
    }

    // Main loop
    while (1) {
        if (app.state == STATE_DISCONNECTED) {
            syslog_message(LOG_INFO, "MQTT disconnected, attempting reconnect...");
            app.reconnect_timer = RECONNECT_DELAY;
            while (app.reconnect_timer > 0) {
                sleep(1);
                app.reconnect_timer--;
            }

            int rc = mosquitto_reconnect(app.mosq);
            if (rc != MOSQ_ERR_SUCCESS) {
                syslog_message(LOG_ERR, "Failed to reconnect to MQTT broker, error code %d", rc);
                continue;
            }
        }

        int rc = mosquitto_loop(app.mosq, -1, 1);
        if (rc != MOSQ_ERR_SUCCESS) {
            syslog_message(LOG_ERR, "MQTT loop error, error code %d", rc);
            continue;
        }
    }

    // Cleanup
    if (app.line) {
        gpiod_line_release(app.line);
    }
    if (app.gpio_fd >= 0) {
        close(app.gpio_fd);
    }
    if (app.mosq) {
        mosquitto_destroy(app.mosq);
    }
    closelog();

    return EXIT_SUCCESS;
}

