        if (!lines[i]) {
            fprintf(stderr, "Failed to get line %d\n", GPIO_PINS[i]);
            goto error_cleanup;
        }

        req_config = gpiod_line_request_config_default();
        req_config.request_type = GPIOD_LINE_REQUEST_TYPE_OPEN_DRAIN;
        req_config.flags = GPIOD_LINE_REQUEST_FLAG_OUTPUT;
        req_config.consumer = "servo_control";

        ret = gpiod_line_request_output(lines[i], &req_config);
        if (ret < 0) {
            fprintf(stderr, "Failed to request line %d: %s\n", GPIO_PINS[i], strerror(errno));
            goto error_cleanup;
        }

        // Set initial state to low
        ret = gpiod_line_set_value(lines[i], 0);
        if (ret < 0) {
            fprintf(stderr, "Failed to set line %d to low: %s\n", GPIO_PINS[i], strerror(errno));
            goto error_cleanup;
        }
    }

    // Generate PWM pulses for each servo
    for (i = 0; i < NUM_SERVOS; i++) {
        int pulse_width = PULSE_WIDTHS[i];
        if (pulse_width < 500 || pulse_width > 2500) {
            fprintf(stderr, "Invalid pulse width for servo %d: %d us\n", i + 1, pulse_width);
            goto error_cleanup;
        }

        // Calculate duty cycle percentage
        double duty_cycle = (double)pulse_width / (double)DUTY_CYCLE_US * 100.0;
        int duty_cycle_int = (int)duty_cycle;

        // Set high for the pulse duration
        ret = gpiod_line_set_value(lines[i], 1);
        if (ret < 0) {
            fprintf(stderr, "Failed to set line %d to high: %s\n", GPIO_PINS[i], strerror(errno));
            goto error_cleanup;
        }

        usleep(pulse_width * 1000); // Convert microseconds to microseconds

        // Set low again
        ret = gpiod_line_set_value(lines[i], 0);
        if (ret < 0) {
            fprintf(stderr, "Failed to set line %d to low: %s\n", GPIO_PINS[i], strerror(errno));
            goto error_cleanup;
        }

        usleep((DUTY_CYCLE_US - pulse_width) * 1000); // Wait for the rest of the period
    }

    // Clean up
    for (i = 0; i < NUM_SERVOS; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }

    gpiod_chip_close(chip);
    return 0;

error_cleanup:
    for (int j = 0; j < i; j++) {
        if (lines[j]) {
            gpiod_line_release(lines[j]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return 1;
}

