#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pthread.h>
#include <gpiod.h>

#define GPIO_PWM_A_IN1 17
#define GPIO_PWM_A_IN2 18
#define GPIO_PWM_B_IN1 22
#define GPIO_PWM_B_IN2 23

#define GPIO_ENCODER_A_PHASE_A 4
#define GPIO_ENCODER_A_PHASE_B 5
#define GPIO_ENCODER_B_PHASE_A 6
#define GPIO_ENCODER_B_PHASE_B 12

#define ENCODER_TICKS_PER_REVOLUTION 64
#define TARGET_RPM 50
#define PWM_FREQUENCY 10000
#define CONTROL_PERIOD_MS 100
#define ENCODER_STALL_TIMEOUT_MS 2000
#define MAX_PWM_DUTY_CYCLE 255

typedef struct {
    int32_t encoder_a_ticks;
    int32_t encoder_b_ticks;
    uint64_t last_encoder_update_time;
    int32_t last_encoder_a_ticks;
    int32_t last_encoder_b_ticks;
    int32_t pwm_a_duty;
    int32_t pwm_b_duty;
    int32_t integral_a;
    int32_t integral_b;
    int32_t derivative_a;
    int32_t derivative_b;
    int32_t error_a;
    int32_t error_b;
    int32_t output_a;
    int32_t output_b;
    int32_t control_cycle_count;
    int32_t stall_a;
    int32_t stall_b;
} motor_control_state;

volatile sig_atomic_t running = 1;

gpiod_line *encoder_a_phase_a_line;
gpiod_line *encoder_a_phase_b_line;
gpiod_line *encoder_b_phase_a_line;
gpiod_line *encoder_b_phase_b_line;

gpiod_line *motor_a_pwm_line;
gpiod_line *motor_a_dir_line;
gpiod_line *motor_b_pwm_line;
gpiod_line *motor_b_dir_line;

pthread_mutex_t encoder_mutex = PTHREAD_MUTEX_INITIALIZER;

void handle_sigint(int sig) {
    running = 0;
}

void setup_gpio() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        exit(EXIT_FAILURE);
    }

    line = gpiod_line_request(chip, GPIO_ENCODER_A_PHASE_A, "encoder_a_phase_a", GPIOD_LINE_DIRECTION_INPUT, 0);
    if (!line) {
        fprintf(stderr, "Failed to request encoder A phase A line\n");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }
    encoder_a_phase_a_line = line;

    line = gpiod_line_request(chip, GPIO_ENCODER_A_PHASE_B, "encoder_a_phase_b", GPIOD_LINE_DIRECTION_INPUT, 0);
    if (!line) {
        fprintf(stderr, "Failed to request encoder A phase B line\n");
        gpiod_line_release(encoder_a_phase_a_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }
    encoder_a_phase_b_line = line;

    line = gpiod_line_request(chip, GPIO_ENCODER_B_PHASE_A, "encoder_b_phase_a", GPIOD_LINE_DIRECTION_INPUT, 0);
    if (!line) {
        fprintf(stderr, "Failed to request encoder B phase A line\n");
        gpiod_line_release(encoder_a_phase_a_line);
        gpiod_line_release(encoder_a_phase_b_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }
    encoder_b_phase_a_line = line;

    line = gpiod_line_request(chip, GPIO_ENCODER_B_PHASE_B, "encoder_b_phase_b", GPIOD_LINE_DIRECTION_INPUT, 0);
    if (!line) {
        fprintf(stderr, "Failed to request encoder B phase B line\n");
        gpiod_line_release(encoder_a_phase_a_line);
        gpiod_line_release(encoder_a_phase_b_line);
        gpiod_line_release(encoder_b_phase_a_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }
    encoder_b_phase_b_line = line;

    line = gpiod_line_request(chip, GPIO_PWM_A_IN1, "motor_a_pwm", GPIOD_LINE_DIRECTION_OUTPUT, 0);
    if (!line) {
        fprintf(stderr, "Failed to request motor A PWM line\n");
        gpiod_line_release(encoder_a_phase_a_line);
        gpiod_line_release(encoder_a_phase_b_line);
        gpiod_line_release(encoder_b_phase_a_line);
        gpiod_line_release(encoder_b_phase_b_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }
    motor_a_pwm_line = line;

    line = gpiod_line_request(chip, GPIO_PWM_A_IN2, "motor_a_dir", GPIOD_LINE_DIRECTION_OUTPUT, 0);
    if (!line) {
        fprintf(stderr, "Failed to request motor A direction line\n");
        gpiod_line_release(motor_a_pwm_line);
        gpiod_line_release(encoder_a_phase_a_line);
        gpiod_line_release(encoder_a_phase_b_line);
        gpiod_line_release(encoder_b_phase_a_line);
        gpiod_line_release(encoder_b_phase_b_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }
    motor_a_dir_line = line;

    line = gpiod_line_request(chip, GPIO_PWM_B_IN1, "motor_b_pwm", GPIOD_LINE_DIRECTION_OUTPUT, 0);
    if (!line) {
        fprintf(stderr, "Failed to request motor B PWM line\n");
        gpiod_line_release(motor_a_dir_line);
        gpiod_line_release(motor_a_pwm_line);
        gpiod_line_release(encoder_a_phase_a_line);
        gpiod_line_release(encoder_a_phase_b_line);
        gpiod_line_release(encoder_b_phase_a_line);
        gpiod_line_release(encoder_b_phase_b_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }
    motor_b_pwm_line = line;

    line = gpiod_line_request(chip, GPIO_PWM_B_IN2, "motor_b_dir", GPIOD_LINE_DIRECTION_OUTPUT, 0);
    if (!line) {
        fprintf(stderr, "Failed to request motor B direction line\n");
        gpiod_line_release(motor_b_pwm_line);
        gpiod_line_release(motor_a_dir_line);
        gpiod_line_release(motor_a_pwm_line);
        gpiod_line_release(encoder_a_phase_a_line);
        gpiod_line_release(encoder_a_phase_b_line);
        gpiod_line_release(encoder_b_phase_a_line);
        gpiod_line_release(encoder_b_phase_b_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }
    motor_b_dir_line = line;
}

void release_gpio() {
    gpiod_line_release(motor_b_dir_line);
    gpiod_line_release(motor_b_pwm_line);
    gpiod_line_release(motor_a_dir_line);
    gpiod_line_release(motor_a_pwm_line);
    gpiod_line_release(encoder_b_phase_b_line);
    gpiod_line_release(encoder_b_phase_a_line);
    gpiod_line_release(encoder_a_phase_b_line);
    gpiod_line_release(encoder_a_phase_a_line);
    gpiod_chip_close(gpiod_line_get_chip(motor_a_pwm_line));
}

void set_motor_direction(int motor, int direction) {
    if (motor == 0) {
        if (direction == 1) {
            gpiod_line_set_value(motor_a_dir_line, 1);
        } else {
            gpiod_line_set_value(motor_a_dir_line, 0);
        }
    } else {
        if (direction == 1) {
            gpiod_line_set_value(motor_b_dir_line, 1);
        } else {
            gpiod_line_set_value(motor_b_dir_line, 0);
        }
    }
}

void set_motor_pwm(int motor, int duty_cycle) {
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > MAX_PWM_DUTY_CYCLE) duty_cycle = MAX_PWM_DUTY_CYCLE;

    if (motor == 0) {
        gpiod_line_set_value(motor_a_pwm_line, duty_cycle);
    } else {
        gpiod_line_set_value(motor_b_pwm_line, duty_cycle);
    }
}

void update_encoder_counts(motor_control_state *state) {
    int32_t encoder_a_phase_a = gpiod_line_get_value(encoder_a_phase_a_line);
    int32_t encoder_a_phase_b = gpiod_line_get_value(encoder_a_phase_b_line);
    int32_t encoder_b_phase_a = gpiod_line_get_value(encoder_b_phase_a_line);
    int32_t encoder_b_phase_b = gpiod_line_get_value(encoder_b_phase_b_line);

    int32_t encoder_a_delta = 0;
    int32_t encoder_b_delta = 0;

    if (encoder_a_phase_a != encoder_a_phase_b) {
        if (encoder_a_phase_a == 1) {
            encoder_a_delta = 1;
        } else {
            encoder_a_delta = -1;
        }
    }

    if (encoder_b_phase_a != encoder_b_phase_b) {
        if (encoder_b_phase_a == 1) {
            encoder_b_delta = 1;
        } else {
            encoder_b_delta = -1;
        }
    }

    pthread_mutex_lock(&encoder_mutex);
    state->encoder_a_ticks += encoder_a_delta;
    state->encoder_b_ticks += encoder_b_delta;
    pthread_mutex_unlock(&encoder_mutex);
}

void check_encoder_stall(motor_control_state *state) {
    time_t current_time = time(NULL);
    if (current_time - state->last_encoder_update_time > ENCODER_STALL_TIMEOUT_MS / 1000) {
        if (state->encoder_a_ticks == state->last_encoder_a_ticks) {
            state->stall_a = 1;
            printf("Encoder A stall detected\n");
        }
        if (state->encoder_b_ticks == state->last_encoder_b_ticks) {
            state->stall_b = 1;
            printf("Encoder B stall detected\n");
        }
    } else {
        state->stall_a = 0;
        state->stall_b = 0;
    }
    state->last_encoder_update_time = current_time;
    state->last_encoder_a_ticks = state->encoder_a_ticks;
    state->last_encoder_b_ticks = state->encoder_b_ticks;
}

void control_loop(motor_control_state *state) {
    double period_seconds = CONTROL_PERIOD_MS / 1000.0;
    double target_rpm = TARGET_RPM;
    double target_rps = target_rpm / 60.0;
    double encoder_ticks_per_second = 0.0;

    double error_a = 0.0;
    double error_b = 0.0;
    double integral_a = 0.0;
    double integral_b = 0.0;
    double derivative_a = 0.0;
    double derivative_b = 0.0;
    double output_a = 0.0;
    double output_b = 0.0;

    if (state->encoder_a_ticks > 0) {
        encoder_ticks_per_second = (state->encoder_a_ticks) / period_seconds;
    }

    error_a = target_rps - (encoder_ticks_per_second / ENCODER_TICKS_PER_REVOLUTION);
    error_b = target_rps - (state->encoder_b_ticks / (period_seconds * ENCODER_TICKS_PER_REVOLUTION));

    integral_a += error_a * period_seconds;
    integral_b += error_b * period_seconds;

    derivative_a = (error_a - state->error_a) / period_seconds;
    derivative_b = (error_b - state->error_b) / period_seconds;

    output_a = error_a * 1.0 + integral_a * 0.1 + derivative_a * 0.01;
    output_b = error_b * 1.0 + integral_b * 0.1 + derivative_b * 0.01;

    if (output_a > 1.0) {
        output_a = 1.0;
    } else if (output_a < -1.0) {
        output_a = -1.0;
    }

    if (output_b > 1.0) {
        output_b = 1.0;
    } else if (output_b < -1.0) {
        output_b = -1.0;
    }

    state->pwm_a_duty = (int32_t)(output_a * MAX_PWM_DUTY_CYCLE);
    state->pwm_b_duty = (int32_t)(output_b * MAX_PWM_DUTY_CYCLE);

    set_motor_direction(0, 1);
    set_motor_pwm(0, state->pwm_a_duty);

    set_motor_direction(1, 1);
    set_motor_pwm(1, state->pwm_b_duty);

    state->error_a = error_a;
    state->error_b = error_b;
    state->integral_a = integral_a;
    state->integral_b = integral_b;
    state->derivative_a = derivative_a;
    state->derivative_b = derivative_b;
    state->control_cycle_count++;
}

int main() {
    motor_control_state state = {
        .encoder_a_ticks = 0,
        .encoder_b_ticks = 0,
        .last_encoder_update_time = 0,
        .last_encoder_a_ticks = 0,
        .last_encoder_b_ticks = 0,
        .pwm_a_duty = 0,
        .pwm_b_duty = 0,
        .integral_a = 0,
        .integral_b = 0,
        .derivative_a = 0,
        .derivative_b = 0,
        .error_a = 0,
        .error_b = 0,
        .output_a = 0,
        .output_b = 0,
        .control_cycle_count = 0,
        .stall_a = 0,
        .stall_b = 0
    };

    setup_gpio();

    signal(SIGINT, handle_sigint);

    while (running) {
        update_encoder_counts(&state);
        check_encoder_stall(&state);
        control_loop(&state);

        printf("Motor RPM: %.2f, PWM Duty Cycle: %d\n", (state.encoder_a_ticks / (state.control_cycle_count * 0.01)) / ENCODER_TICKS_PER_REVOLUTION * 60, state.pwm_a_duty);
        usleep(CONTROL_PERIOD_MS * 1000);
    }

    release_gpio();
    return 0;
}

