#include <gpiod.h>

#define I2C_BUS 1
#define I2C_ADDR 0x23
#define RELAY_PIN 17
#define POLL_INTERVAL 5000
#define MODE_DELAY 180
#define LUX_THRESHOLD_DUSK 50
#define LUX_THRESHOLD_DAWN 200
#define LOG_FILE "chicken_coop_log.txt"

typedef enum {
    MODE_CONTINUOUS_H_RESOLUTION,
    MODE_ONE_TIME_H_RESOLUTION
} i2c_mode;

typedef struct {
    int i2c_fd;
    struct gpiod_line *relay_line;
    FILE *log_file;
    int running;
} app_state;

void log_message(const char *format, ...) {
    va_list args;
    char buffer[256];
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", tm);
    va_start(args, format);
    vsnprintf(buffer + strlen(buffer) + 1, sizeof(buffer) - strlen(buffer) - 1, format, args);
    va_end(args);

    if (app_state.log_file) {
        fprintf(app_state.log_file, "%s: %s\n", buffer, buffer + strlen(buffer) + 1);
        fflush(app_state.log_file);
    }
}

void handle_signal(int signal) {
    app_state.running = 0;
}

int init_i2c() {
    char i2c_bus_path[32];
    snprintf(i2c_bus_path, sizeof(i2c_bus_path), "/dev/i2c-%d", I2C_BUS);

    app_state.i2c_fd = open(i2c_bus_path, O_RDWR);
    if (app_state.i2c_fd < 0) {
        log_message("Failed to open I2C bus: %s", strerror(errno));
        return -1;
    }

    if (ioctl(app_state.i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        log_message("Failed to set I2C slave address: %s", strerror(errno));
        close(app_state.i2c_fd);
        return -1;
    }

    return 0;
}

int set_i2c_mode(i2c_mode mode) {
    unsigned char cmd[2];
    cmd[0] = 0x80; // Command register
    cmd[1] = mode;

    if (write(app_state.i2c_fd, cmd, 2) != 2) {
        log_message("Failed to set I2C mode: %s", strerror(errno));
        return -1;
    }

    usleep(MODE_DELAY * 1000);
    return 0;
}

int read_lux() {
    unsigned char cmd[2];
    cmd[0] = 0x20; // Measurement command
    cmd[1] = 0x00; // No wait

    if (write(app_state.i2c_fd, cmd, 2) != 2) {
        log_message("Failed to read lux: %s", strerror(errno));
        return -1;
    }

    usleep(100000); // Wait for measurement

    unsigned char data[2];
    if (read(app_state.i2c_fd, data, 2) != 2) {
        log_message("Failed to read lux data: %s", strerror(errno));
        return -1;
    }

    int lux = (data[0] << 8) | data[1];
    return lux;
}

int init_gpio() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        log_message("Failed to open GPIO chip: %s", strerror(errno));
        return -1;
    }

    line = gpiod_line_get(chip, RELAY_PIN);
    if (!line) {
        log_message("Failed to get GPIO line: %s", strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(line, "relay", 0) < 0) {
        log_message("Failed to request GPIO line: %s", strerror(errno));
        gpiod_line_put(line);
        gpiod_chip_close(chip);
        return -1;
    }

    app_state.relay_line = line;
    return 0;
}

void set_relay(int state) {
    if (state) {
        gpiod_line_set_value(app_state.relay_line, 1);
    } else {
        gpiod_line_set_value(app_state.relay_line, 0);
    }
}

void close_resources() {
    if (app_state.log_file) {
        fclose(app_state.log_file);
    }

    if (app_state.relay_line) {
        gpiod_line_put(app_state.relay_line);
    }

    if (app_state.i2c_fd >= 0) {
        close(app_state.i2c_fd);
    }
}

int main() {
    app_state.running = 1;
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if (init_i2c() < 0) {
        log_message("I2C initialization failed. Exiting.");
        return 1;
    }

    if (init_gpio() < 0) {
        log_message("GPIO initialization failed. Exiting.");
        close_resources();
        return 1;
    }

    app_state.log_file = fopen(LOG_FILE, "a");
    if (!app_state.log_file) {
        log_message("Failed to open log file: %s. Exiting.", strerror(errno));
        close_resources();
        return 1;
    }

    int last_relay_state = 0;
    int last_lux = 0;

    log_message("System started. Monitoring ambient light...");

    while (app_state.running) {
        if (set_i2c_mode(MODE_CONTINUOUS_H_RESOLUTION) < 0) {
            log_message("Failed to set I2C mode. Turning relay off.");
            set_relay(0);
            last_relay_state = 0;
            usleep(100000);
            continue;
        }

        int lux = read_lux();
        if (lux < 0) {
            log_message("Sensor non-response. Turning relay off.");
            set_relay(0);
            last_relay_state = 0;
            usleep(100000);
            continue;
        }

        if (lux < LUX_THRESHOLD_DUSK && lux < last_lux + 50) {
            if (last_relay_state == 0) {
                log_message("Lux = %d, Relay = ON", lux);
                set_relay(1);
                last_relay_state = 1;
            }
        } else if (lux > LUX_THRESHOLD_DAWN && lux > last_lux - 50) {
            if (last_relay_state == 1) {
                log_message("Lux = %d, Relay = OFF", lux);
                set_relay(0);
                last_relay_state = 0;
            }
        }

        last_lux = lux;
        usleep(POLL_INTERVAL * 1000);
    }

    log_message("System shutdown initiated.");
    close_resources();
    return 0;
}

