                last_relay_state = 1;
            }
        } else if (lux > LUX_THRESHOLD_DAWN && lux > last_lux - 50) {
            if (last_relay_state == 1) {
                log_message("Lux = %d, Relay = OFF", lux);
                set_relay(0);
                last_relay_state = 0;
            }
        }

        last_lux = lux;
        usleep(POLL_INTERVAL * 1000);
    }

    log_message("System shutdown initiated.");
    close_resources();
    return 0;
}
