typedef enum {
    STATE_IDLE,
    STATE_DEBOUNCING,
    STATE_CONFIRMED
} State;

typedef struct {
    gpiod_line *touch_line;
    gpiod_line *relay_line;
    int relay_state;
    time_t last_low_time;
    State state;
} AppContext;

void handle_sigint(int sig) {
    (void)sig;
    AppContext *ctx = (AppContext *)malloc(sizeof(AppContext));
    if (!ctx) {
        fprintf(stderr, "Failed to allocate memory for context\n");
        exit(EXIT_FAILURE);
    }

    // Turn relay OFF
    if (gpiod_line_set_value(ctx->relay_line, 0) < 0) {
        fprintf(stderr, "Failed to turn relay OFF\n");
    }

    // Release resources
    if (gpiod_line_release(ctx->touch_line) < 0) {
        fprintf(stderr, "Failed to release touch line\n");
    }
    if (gpiod_line_release(ctx->relay_line) < 0) {
        fprintf(stderr, "Failed to release relay line\n");
    }

    // Print exit message
    printf("Relay turned OFF and resources released. Exiting...\n");

    free(ctx);
    exit(EXIT_SUCCESS);
}

void log_relay_state(const AppContext *ctx) {
    char timestamp[30];
    struct tm *tm_info;
    time_t now = time(NULL);
    tm_info = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

    printf("%s - Relay %s\n", timestamp, ctx->relay_state ? "ON" : "OFF");
}

int main() {
    AppContext ctx = {0};

    // Initialize GPIO lines
    struct gpiod_chip *chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    ctx.touch_line = gpiod_line_get(chip, GPIO_TOUCH_PIN);
    if (!ctx.touch_line) {
        fprintf(stderr, "Failed to get touch line\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ctx.relay_line = gpiod_line_get(chip, GPIO_RELAY_PIN);
    if (!ctx.relay_line) {
        fprintf(stderr, "Failed to get relay line\n");
        gpiod_line_release(ctx.touch_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set touch line as input
    if (gpiod_line_request_input(ctx.touch_line, "touch_sensor") < 0) {
        fprintf(stderr, "Failed to request touch line as input\n");
        gpiod_line_release(ctx.touch_line);
        gpiod_line_release(ctx.relay_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set relay line as output
    if (gpiod_line_request_output(ctx.relay_line, "relay", 0) < 0) {
        fprintf(stderr, "Failed to request relay line as output\n");
        gpiod_line_release(ctx.touch_line);
        gpiod_line_release(ctx.relay_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Initialize context
    ctx.relay_state = 0;
    ctx.last_low_time = 0;
    ctx.state = STATE_IDLE;

    // Set up signal handler
    signal(SIGINT, handle_sigint);

    while (1) {
        // Check touch state
        int touch_value = gpiod_line_get_value(ctx.touch_line);
        if (touch_value < 0) {
            fprintf(stderr, "Failed to read touch line value\n");
            break;
        }

        switch (ctx.state) {
            case STATE_IDLE:
                if (touch_value == 1) {
                    ctx.state = STATE_DEBOUNCING;
                    ctx.last_low_time = time(NULL);
                }
                break;

            case STATE_DEBOUNCING:
                if (time(NULL) - ctx.last_low_time >= DEBOUNCE_DELAY_MS / 1000.0) {
                    if (touch_value == 1) {
                        ctx.state = STATE_CONFIRMED;
                    } else {
                        ctx.state = STATE_IDLE;
                    }
                }
                break;

            case STATE_CONFIRMED:
                if (touch_value == 0) {
                    ctx.state = STATE_IDLE;
                }
                break;
        }

        // Toggle relay on confirmed touch
        if (ctx.state == STATE_CONFIRMED) {
            ctx.relay_state = !ctx.relay_state;
            if (gpiod_line_set_value(ctx.relay_line, ctx.relay_state) < 0) {
                fprintf(stderr, "Failed to set relay value\n");
            }
            log_relay_state(&ctx);
            ctx.state = STATE_IDLE;
        }

        // Sleep between iterations
        usleep(LOOP_SLEEP_MS * 1000);
    }

    // Clean up
    gpiod_line_release(ctx.touch_line);
    gpiod_line_release(ctx.relay_line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

