#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/gpio.h>
#include <time.h>
#include <string.h>

#define GPIO_FLOW_PIN 17
#define GPIO_SOLENOID_PIN 27
#define LOG_FILE "water_flow.log"
#define DEBOUNCE_TIMEOUT 1000000  // 1 second in microseconds
#define LPM_THRESHOLD_HIGH 5.0
#define LPM_THRESHOLD_LOW 4.5
#define LPM_CALCULATION_INTERVAL 60  // seconds

typedef struct {
    int flow_pulse_count;
    double flow_rate_lpm;
    int solenoid_state;
    pthread_mutex_t mutex;
    int log_file;
    int gpio_fd;
} app_state_t;

volatile sig_atomic_t running = 1;

void handle_signal(int sig) {
    running = 0;
}

void log_message(const char *message, const char *timestamp) {
    if (app_state.log_file != -1) {
        fprintf(app_state.log_file, "%s %s\n", timestamp, message);
        fflush(app_state.log_file);
    }
}

void log_solenoid_state(int state) {
    char timestamp[20];
    time_t now = time(NULL);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
    char msg[100];
    snprintf(msg, sizeof(msg), "Solenoid state changed to %d", state);
    log_message(msg, timestamp);
}

void log_flow_rate(double lpm) {
    char timestamp[20];
    time_t now = time(NULL);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
    char msg[100];
    snprintf(msg, sizeof(msg), "Flow rate: %.2f LPM", lpm);
    log_message(msg, timestamp);
}

void cleanup_and_exit(int status) {
    if (app_state.gpio_fd != -1) {
        gpio_close(app_state.gpio_fd);
    }
    if (app_state.log_file != -1) {
        fclose(app_state.log_file);
    }
    pthread_mutex_destroy(&app_state.mutex);
    exit(status);
}

void *flow_sensor_isr(void *arg) {
    while (running) {
        usleep(DEBOUNCE_TIMEOUT);
        pthread_mutex_lock(&app_state.mutex);
        app_state.flow_pulse_count++;
        pthread_mutex_unlock(&app_state.mutex);
    }
    return NULL;
}

void *flow_rate_monitor(void *arg) {
    while (running) {
        usleep(1000000);  // 1 second
        pthread_mutex_lock(&app_state.mutex);
        double flow_rate = (app_state.flow_pulse_count * 60.0) / LPM_CALCULATION_INTERVAL;
        app_state.flow_pulse_count = 0;
        pthread_mutex_unlock(&app_state.mutex);

        log_flow_rate(flow_rate);

        if (flow_rate > LPM_THRESHOLD_HIGH) {
            if (app_state.solenoid_state == 0) {
                app_state.solenoid_state = 1;
                log_solenoid_state(1);
            }
        } else if (flow_rate < LPM_THRESHOLD_LOW) {
            if (app_state.solenoid_state == 1) {
                app_state.solenoid_state = 0;
                log_solenoid_state(0);
            }
        }
    }
    return NULL;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        cleanup_and_exit(EXIT_FAILURE);
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        cleanup_and_exit(EXIT_FAILURE);
    }

    app_state.log_file = fopen(LOG_FILE, "a");
    if (app_state.log_file == NULL) {
        perror("fopen");
        cleanup_and_exit(EXIT_FAILURE);
    }

    app_state.gpio_fd = gpio_open(GPIO_FLOW_PIN, GPIOHANDLE_REQUEST_INPUT);
    if (app_state.gpio_fd == -1) {
        perror("gpio_open");
        cleanup_and_exit(EXIT_FAILURE);
    }

    if (gpio_set_direction(app_state.gpio_fd, GPIOHANDLE_SET_DIRECTION_INPUT) != 0) {
        perror("gpio_set_direction");
        cleanup_and_exit(EXIT_FAILURE);
    }

    if (gpio_set_edge(app_state.gpio_fd, GPIOHANDLE_SET_EDGE_RISING) != 0) {
        perror("gpio_set_edge");
        cleanup_and_exit(EXIT_FAILURE);
    }

    if (gpio_set_debounce(app_state.gpio_fd, DEBOUNCE_TIMEOUT) != 0) {
        perror("gpio_set_debounce");
        cleanup_and_exit(EXIT_FAILURE);
    }

    pthread_mutex_init(&app_state.mutex, NULL);
    app_state.flow_pulse_count = 0;
    app_state.solenoid_state = 1;

    pthread_t flow_isr_thread;
    pthread_t flow_monitor_thread;

    if (pthread_create(&flow_isr_thread, NULL, flow_sensor_isr, NULL) != 0) {
        perror("pthread_create (flow_isr_thread)");
        cleanup_and_exit(EXIT_FAILURE);
    }

    if (pthread_create(&flow_monitor_thread, NULL, flow_rate_monitor, NULL) != 0) {
        perror("pthread_create (flow_monitor_thread)");
        cleanup_and_exit(EXIT_FAILURE);
    }

    while (running) {
        usleep(100000);  // 100ms
    }

    pthread_join(flow_isr_thread, NULL);
    pthread_join(flow_monitor_thread, NULL);

    log_message("Program terminated", "Termination");

    cleanup_and_exit(EXIT_SUCCESS);
}

