#define GPIO_TOUCH_PIN 4
#define GPIO_RELAY_PIN 17
#define DEFAULT_DEBOUNCE_MS 50

volatile int running = 1;
volatile int relay_state = 0;
volatile int debounce_ms = DEFAULT_DEBOUNCE_MS;

typedef struct {
    struct gpiod_line *touch_line;
    struct gpiod_line *relay_line;
} gpio_handles;

void handle_signal(int sig) {
    running = 0;
}

void log_relay_state(const char *state) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);
    printf("%s Relay: %s\n", timestamp, state);
}

void cleanup_gpio(gpio_handles *gpio) {
    if (gpio->touch_line) {
        gpiod_line_release(gpio->touch_line);
    }
    if (gpio->relay_line) {
        gpiod_line_release(gpio->relay_line);
    }
}

int init_gpio(gpio_handles *gpio) {
    struct gpiod_chip *chip;
    struct gpiod_line *line;

    chip = gpiod_chip_open("/dev/gpiochip4");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    line = gpiod_chip_get_line(chip, GPIO_TOUCH_PIN);
    if (!line) {
        perror("Failed to get touch GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(line, "touch_sensor", GPIOD_LINE_REQUEST_OUTPUT_DISABLE)) {
        perror("Failed to request touch GPIO line");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return -1;
    }

    gpio->touch_line = line;

    line = gpiod_chip_get_line(chip, GPIO_RELAY_PIN);
    if (!line) {
        perror("Failed to get relay GPIO line");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(line, "relay_control", GPIOD_LINE_REQUEST_OUTPUT_ENABLE)) {
        perror("Failed to request relay GPIO line");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return -1;
    }

    gpio->relay_line = line;

    return 0;
}

int main(int argc, char *argv[]) {
    gpio_handles gpio;
    int touch_value = 0;
    int last_touch_value = 0;
    int debounce_count = 0;
    struct timespec sleep_time;
    int ret;

    // Parse command-line arguments
    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "-d") == 0 && i + 1 < argc) {
            debounce_ms = atoi(argv[i + 1]);
            if (debounce_ms <= 0) {
                fprintf(stderr, "Invalid debounce interval: %d ms\n", debounce_ms);
                return 1;
            }
            i++;
        }
    }

    // Set up signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Initialize GPIO
    if (init_gpio(&gpio) != 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    // Set initial relay state
    gpiod_line_set_value(gpio.relay_line, 0);
    relay_state = 0;

    while (running) {
        // Read touch sensor
        ret = gpiod_line_get_value(gpio.touch_line);
        if (ret < 0) {
            perror("Failed to read touch GPIO line");
            cleanup_gpio(&gpio);
            return 1;
        }
        touch_value = ret;

        // Debounce logic
        if (touch_value != last_touch_value) {
            last_touch_value = touch_value;
            debounce_count = 0;
        } else {
            debounce_count++;
            if (debounce_count >= debounce_ms / 10) { // 10 ms per step
                if (touch_value == 1) { // Rising edge detected
                    relay_state = !relay_state;
                    gpiod_line_set_value(gpio.relay_line, relay_state);
                    log_relay_state(relay_state ? "ON" : "OFF");
                }
                debounce_count = 0;
            }
        }

        // Sleep for 10 ms
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = 10000000;
        nanosleep(&sleep_time, NULL);
    }

    // Clean up
    cleanup_gpio(&gpio);
    return 0;
}

