    int fd;
    int running;
} servo_state_t;

void setup_gpio(servo_state_t *state) {
    struct gpiod_chip *chip;
    struct gpiod_line *line;

    chip = gpiod_chip_open_by_number(1); // BCM2 (GPIOs on Pi 4/5)
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        exit(EXIT_FAILURE);
    }

    line = gpiod_chip_get_line(chip, BCM_PIN);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line %d\n", BCM_PIN);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    state->line = line;

    // Configure line for PWM
    state->req_config.consumer = "servo";
    state->req_config.flags = GPIOD_LINE_REQUEST_FLAG_ACTIVE_LOW;
    state->req_config.args = NULL;
    state->req_config.args_count = 0;

    state->request = gpiod_line_request_line(line, GPIOD_LINE_REQUEST_DIRECTION_OUTPUT, &state->req_config);
    if (!state->request) {
        fprintf(stderr, "Failed to request GPIO line %d\n", BCM_PIN);
        gpiod_line_put(line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Set PWM parameters
    if (gpiod_line_set_config(state->request, "pwm", "frequency", "50") < 0) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        gpiod_line_request_free(state->request);
        gpiod_line_put(line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }
}

void cleanup_gpio(servo_state_t *state) {
    if (state->request) {
        gpiod_line_request_free(state->request);
    }
    if (state->line) {
        gpiod_line_put(state->line);
    }
}

void setup_terminal(struct termios *orig_termios) {
    struct termios new_termios;

    tcgetattr(STDIN_FILENO, orig_termios);
    memcpy(&new_termios, orig_termios, sizeof(new_termios));
    new_termios.c_lflag &= ~(ICANON | ECHO); // Disable canonical mode and echo
    new_termios.c_cc[VMIN] = 0; // Non-blocking read
    new_termios.c_cc[VTIME] = 0;
    tcsetattr(STDIN_FILENO, TCSAFLUSH, &new_termios);
}

