    int pulse_width_us = MIN_PULSE_WIDTH_US + (angle * (MAX_PULSE_WIDTH_US - MIN_PULSE_WIDTH_US)) / MAX_ANGLE;
    pulse_width_us = (pulse_width_us < MIN_PULSE_WIDTH_US) ? MIN_PULSE_WIDTH_US : (pulse_width_us > MAX_PULSE_WIDTH_US ? MAX_PULSE_WIDTH_US : pulse_width_us);
    set_pulse_width(state, pulse_width_us);
    printf("Angle: %d°\n", angle);
}

void signal_handler(int sig) {
    if (sig == SIGINT) {
        printf("\nReceived SIGINT, stopping PWM...\n");
        set_pulse_width(&state, 0);
        cleanup_gpio(&state);
        restore_terminal(&state.orig_termios);
        exit(EXIT_SUCCESS);
    }
}

int main() {
    servo_state_t state = {0};
    struct termios orig_termios;
    int ch;

    setup_gpio(&state);
    setup_terminal(&orig_termios);

    signal(SIGINT, signal_handler);

    set_angle(&state, 90);

    while (state.running) {
        if (read(STDIN_FILENO, &ch, 1) == 1) {
            switch (ch) {
                case '+':
                    set_angle(&state, state.angle + STEP_ANGLE);
                    break;
                case '-':
                    set_angle(&state, state.angle - STEP_ANGLE);
                    break;
                case 'q':
                    state.running = 0;
                    break;
                default:
                    break;
            }
        }
    }

    cleanup_gpio(&state);
    restore_terminal(&orig_termios);

    return 0;
}

