#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/time.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_PIN 17
#define DEBOUNCE_MS 2
#define LOG_INTERVAL_S 5
#define LOG_FILE "motor_rpm.log"
#define CSV_FORMAT "%Y-%m-%dT%H:%M:%S,%0.2f\n"

typedef struct {
    int fd;
    struct gpiod_line *line;
    struct gpiod_chip *chip;
    FILE *log_file;
    int pulse_count;
    struct timespec last_pulse_time;
    int running;
} app_state;

void handle_signal(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        app_state *state = (app_state *)malloc(sizeof(app_state));
        state->running = 0;
        free(state);
    }
}

void log_rpm(app_state *state) {
    struct timespec now;
    clock_gettime(CLOCK_MONOTONIC, &now);
    double elapsed_s = (now.tv_sec - state->last_pulse_time.tv_sec) + (now.tv_nsec - state->last_pulse_time.tv_nsec) / 1e9;
    double rpm = (state->pulse_count / elapsed_s) * 60;

    char timestamp[30];
    struct tm tm;
    time_t t = time(NULL);
    localtime_r(&t, &tm);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm);

    fprintf(state->log_file, CSV_FORMAT, timestamp, rpm);
    fflush(state->log_file);

    printf("Current RPM: %.2f\n", rpm);
    state->pulse_count = 0;
    clock_gettime(CLOCK_MONOTONIC, &state->last_pulse_time);
}

void cleanup(app_state *state) {
    if (state->log_file) {
        fclose(state->log_file);
    }
    if (state->line) {
        gpiod_line_release(state->line);
    }
    if (state->chip) {
        gpiod_chip_close(state->chip);
    }
    free(state);
}

int main() {
    app_state *state = (app_state *)malloc(sizeof(app_state));
    if (!state) {
        fprintf(stderr, "Failed to allocate memory for app_state\n");
        return 1;
    }

    state->running = 1;
    state->pulse_count = 0;
    clock_gettime(CLOCK_MONOTONIC, &state->last_pulse_time);

    // Initialize signal handling
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Open GPIO chip
    state->chip = gpiod_chip_open("/dev/gpiochip0");
    if (!state->chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        cleanup(state);
        return 1;
    }

    // Get GPIO line
    state->line = gpiod_chip_get_line(state->chip, GPIO_PIN);
    if (!state->line) {
        fprintf(stderr, "Failed to get GPIO line %d\n", GPIO_PIN);
        cleanup(state);
        return 1;
    }

    // Configure line
    if (gpiod_line_request_output(state->line, "motor_rpm", GPIOD_LINE_REQUEST_OUTPUT_ACTIVE_LOW)) {
        fprintf(stderr, "Failed to request GPIO line %d as output\n", GPIO_PIN);
        cleanup(state);
        return 1;
    }

    // Set pull-up
    if (gpiod_line_set_pull(state->line, GPIOD_LINE_PULL_UP)) {
        fprintf(stderr, "Failed to set pull-up on GPIO line %d\n", GPIO_PIN);
        cleanup(state);
        return 1;
    }

    // Set line to input
    if (gpiod_line_set_direction(state->line, GPIOD_LINE_DIRECTION_INPUT)) {
        fprintf(stderr, "Failed to set GPIO line %d as input\n", GPIO_PIN);
        cleanup(state);
        return 1;
    }

    // Set edge detection
    if (gpiod_line_set_edge_detection(state->line, GPIOD_LINE_EDGE_RISING)) {
        fprintf(stderr, "Failed to set edge detection on GPIO line %d\n", GPIO_PIN);
        cleanup(state);
        return 1;
    }

    // Open log file
    state->log_file = fopen(LOG_FILE, "a");
    if (!state->log_file) {
        fprintf(stderr, "Failed to open log file %s\n", LOG_FILE);
        cleanup(state);
        return 1;
    }

    // Main loop
    while (state->running) {
        struct timespec ts;
        clock_gettime(CLOCK_MONOTONIC, &ts);

        // Check for edge event
        int event = gpiod_line_event_wait(state->line, DEBOUNCE_MS * 1000000);
        if (event < 0) {
            fprintf(stderr, "Error waiting for GPIO event: %d\n", event);
            cleanup(state);
            return 1;
        }

        if (event == GPIOD_LINE_EVENT_RISING_EDGE) {
            // Debounce check
            struct timespec now;
            clock_gettime(CLOCK_MONOTONIC, &now);
            double elapsed_ms = (now.tv_sec - state->last_pulse_time.tv_sec) * 1000.0 + (now.tv_nsec - state->last_pulse_time.tv_nsec) / 1e3;
            if (elapsed_ms > DEBOUNCE_MS) {
                state->pulse_count++;
                state->last_pulse_time = now;
            }
        }

        // Log RPM every 5 seconds
        struct timespec now;
        clock_gettime(CLOCK_MONOTONIC, &now);
        double elapsed_s = (now.tv_sec - state->last_pulse_time.tv_sec) + (now.tv_nsec - state->last_pulse_time.tv_nsec) / 1e9;
        if (elapsed_s >= LOG_INTERVAL_S) {
            log_rpm(state);
        }
    }

    cleanup(state);
    return 0;
}

