#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <stdbool.h>
#include <libgpiod.h>

#define GPIO_TOUCH_PIN 4
#define GPIO_RELAY_PIN 17
#define POLL_INTERVAL_MS 50
#define MAX_TOUCH_DURATION_MS 10000

volatile bool exit_flag = false;
bool relay_state = false;
bool touch_active = false;
struct gpiod_line *touch_line = NULL;
struct gpiod_line *relay_line = NULL;

void handle_signal(int signum) {
    (void)signum;
    exit_flag = true;
}

int init_gpio() {
    struct gpiod_chip *chip;
    int ret;

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return -1;
    }

    touch_line = gpiod_line_request_output(chip, "touch", GPIO_TOUCH_PIN, 0);
    if (!touch_line) {
        fprintf(stderr, "Failed to request touch GPIO line\n");
        gpiod_chip_close(chip);
        return -1;
    }

    relay_line = gpiod_line_request_output(chip, "relay", GPIO_RELAY_PIN, 0);
    if (!relay_line) {
        fprintf(stderr, "Failed to request relay GPIO line\n");
        gpiod_line_release(touch_line);
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

void cleanup_gpio() {
    if (relay_line) {
        gpiod_line_release(relay_line);
    }
    if (touch_line) {
        gpiod_line_release(touch_line);
    }
    if (touch_line || relay_line) {
        gpiod_chip_close(gpiod_line_get_chip(touch_line));
    }
}

void set_relay(bool state) {
    int ret;
    if (state) {
        ret = gpiod_line_set_value(relay_line, 1);
    } else {
        ret = gpiod_line_set_value(relay_line, 0);
    }
    if (ret < 0) {
