#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/time.h>
#include <sys/types.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>
#include <unistd.h>

#define GPIO_PWM_PIN 18
#define GPIO_DIR_PIN 23
#define GPIO_FLOW_PIN 24
#define PWM_CHANNEL 0
#define PWM_PERIOD_US 20000
#define SAMPLE_INTERVAL_MS 100
#define Kp 1.0
#define MAX_DUTY_CYCLE 255
#define MIN_DUTY_CYCLE 0
#define LOG_FILE "flow_log.csv"

typedef struct {
    gpiod_line *flow_line;
    gpiod_line *dir_line;
    gpiod_line *pwm_line;
    int pwm_fd;
    int flow_count;
    int flow_rate;
    int target_flow;
    FILE *log_file;
    int running;
} AppContext;

void handle_signal(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        AppContext *ctx = (AppContext *)malloc(sizeof(AppContext));
        if (ctx) {
            ctx->running = 0;
        }
    }
}

void setup_gpio(AppContext *ctx) {
    int ret;

    ctx->pwm_line = gpiod_line_get("pwm", GPIO_PWM_PIN);
    if (!ctx->pwm_line) {
        fprintf(stderr, "Failed to get PWM line %d\n", GPIO_PWM_PIN);
        exit(EXIT_FAILURE);
    }

    ctx->dir_line = gpiod_line_get("gpio", GPIO_DIR_PIN);
    if (!ctx->dir_line) {
        fprintf(stderr, "Failed to get direction line %d\n", GPIO_DIR_PIN);
        exit(EXIT_FAILURE);
    }

    ctx->flow_line = gpiod_line_get("gpio", GPIO_FLOW_PIN);
    if (!ctx->flow_line) {
        fprintf(stderr, "Failed to get flow line %d\n", GPIO_FLOW_PIN);
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_request_output(ctx->pwm_line, "pwm", 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request PWM line %d as output: %s\n", GPIO_PWM_PIN, strerror(errno));
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_request_output(ctx->dir_line, "dir", 1);
    if (ret < 0) {
        fprintf(stderr, "Failed to request direction line %d as output: %s\n", GPIO_DIR_PIN, strerror(errno));
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_request_edge_rising(ctx->flow_line, "flow", 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request flow line %d as input with rising edge: %s\n", GPIO_FLOW_PIN, strerror(errno));
        exit(EXIT_FAILURE);
    }

    ctx->pwm_fd = open("/dev/pwm", O_WRONLY);
    if (ctx->pwm_fd < 0) {
        fprintf(stderr, "Failed to open PWM device: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    if (ioctl(ctx->pwm_fd, PWM_SET_CHANNEL, PWM_CHANNEL) < 0) {
        fprintf(stderr, "Failed to set PWM channel: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    if (ioctl(ctx->pwm_fd, PWM_SET_PERIOD, PWM_PERIOD_US) < 0) {
        fprintf(stderr, "Failed to set PWM period: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    ctx->flow_count = 0;
    ctx->flow_rate = 0;
    ctx->running = 1;
}

void setup_interrupt(AppContext *ctx) {
    int ret;
    struct gpiod_line_event event;

    ret = gpiod_line_event_wait(ctx->flow_line, 0, &event);
    if (ret < 0) {
        fprintf(stderr, "Failed to wait for flow line event: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    if (event.type != GPIOD_LINE_EVENT_RISING_EDGE) {
        fprintf(stderr, "Unexpected event type on flow line\n");
        exit(EXIT_FAILURE);
    }

    ctx->flow_count++;
}

void setup_log(AppContext *ctx) {
    ctx->log_file = fopen(LOG_FILE, "w");
    if (!ctx->log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    fprintf(ctx->log_file, "timestamp_ms,flow_rate,valve_position\n");
    fflush(ctx->log_file);
}

void cleanup_gpio(AppContext *ctx) {
    if (ctx->log_file) {
        fclose(ctx->log_file);
    }

    if (ctx->pwm_fd >= 0) {
        close(ctx->pwm_fd);
    }

    if (ctx->flow_line) {
        gpiod_line_release(ctx->flow_line);
    }

    if (ctx->dir_line) {
        gpiod_line_release(ctx->dir_line);
    }

    if (ctx->pwm_line) {
        gpiod_line_release(ctx->pwm_line);
    }
}

void set_pwm_duty_cycle(AppContext *ctx, int duty_cycle) {
    if (duty_cycle < MIN_DUTY_CYCLE) duty_cycle = MIN_DUTY_CYCLE;
    if (duty_cycle > MAX_DUTY_CYCLE) duty_cycle = MAX_DUTY_CYCLE;

    if (ioctl(ctx->pwm_fd, PWM_SET_DUTY_CYCLE, duty_cycle) < 0) {
        fprintf(stderr, "Failed to set PWM duty cycle: %s\n", strerror(errno));
    }
}

void set_valve_direction(AppContext *ctx, int direction) {
    if (direction) {
        gpiod_line_set_value(ctx->dir_line, 1);
    } else {
        gpiod_line_set_value(ctx->dir_line, 0);
    }
}

void calculate_flow_rate(AppContext *ctx) {
    static struct timeval last_time;
    struct timeval current_time;
    long elapsed_us;

    gettimeofday(&current_time, NULL);
    elapsed_us = (current_time.tv_sec - last_time.tv_sec) * 1000000 + (current_time.tv_usec - last_time.tv_usec);

    if (elapsed_us > 0) {
        int flow_rate = (ctx->flow_count * 60000000) / elapsed_us; // L/min
        ctx->flow_rate = flow_rate;
        ctx->flow_count = 0;
    }

    last_time = current_time;
}

void control_loop(AppContext *ctx) {
    int duty_cycle;
    int target_flow = ctx->target_flow;

    calculate_flow_rate(ctx);

    duty_cycle = (int)(Kp * (target_flow - ctx->flow_rate));
    set_pwm_duty_cycle(ctx, duty_cycle);
}

void log_data(AppContext *ctx) {
    struct timeval tv;
    gettimeofday(&tv, NULL);
    long timestamp_ms = tv.tv_sec * 1000 + tv.tv_usec / 1000;

    fprintf(ctx->log_file, "%ld,%d,%d\n", timestamp_ms, ctx->flow_rate, ctx->flow_count);
    fflush(ctx->log_file);
}

int main(int argc, char *argv[]) {
    AppContext ctx;
    int ret;
    struct sigaction sa;
    int target_flow = 0;

    // Parse command line argument
    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "-t") == 0 && i + 1 < argc) {
            target_flow = atoi(argv[i + 1]);
            if (target_flow <= 0) {
                fprintf(stderr, "Invalid target flow rate: must be positive\n");
                exit(EXIT_FAILURE);
            }
            i++;
        }
    }

    if (target_flow <= 0) {
        fprintf(stderr, "Missing or invalid target flow rate. Use -t <L/min>\n");
        exit(EXIT_FAILURE);
    }

    ctx.target_flow = target_flow;

    // Setup signal handling
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set up signal handler: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    setup_gpio(&ctx);
    setup_interrupt(&ctx);
    setup_log(&ctx);

    struct timeval last_time;
    gettimeofday(&last_time, NULL);

    while (ctx.running) {
        setup_interrupt(&ctx);
        control_loop(&ctx);
        log_data(&ctx);
        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    cleanup_gpio(&ctx);
    return 0;
}

