#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/time.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <signal.h>
#include <gpiod.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 100000
#define SPI_MODE SPI_MODE_0
#define SPI_BITS 8
#define SPI_DELAY 0

#define GPIO_LOCK1 17
#define GPIO_LOCK2 27
#define GPIO_BUTTON 22

#define TAG_LENGTH 10
#define TAG_VALUE "0000000000"

#define LOG_FILE "/var/log/door_access.log"

typedef enum {
    ACCESS_SUCCESS,
    ACCESS_INVALID_TAG,
    ACCESS_READ_FAILURE,
    ACCESS_BUTTON_ONLY,
    ACCESS_UNKNOWN
} AccessResult;

void log_access(AccessResult result) {
    char timestamp[30];
    struct timeval tv;
    gettimeofday(&tv, NULL);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&tv.tv_sec));

    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return;
    }

    switch (result) {
        case ACCESS_SUCCESS:
            fprintf(log_file, "%s - Access granted\n", timestamp);
            break;
        case ACCESS_INVALID_TAG:
            fprintf(log_file, "%s - Invalid tag\n", timestamp);
            break;
        case ACCESS_READ_FAILURE:
            fprintf(log_file, "%s - RFID read failure\n", timestamp);
            break;
        case ACCESS_BUTTON_ONLY:
            fprintf(log_file, "%s - Button pressed without valid tag\n", timestamp);
            break;
        case ACCESS_UNKNOWN:
            fprintf(log_file, "%s - Unknown access attempt\n", timestamp);
            break;
    }

    fclose(log_file);
}

int spi_read(unsigned char *data, int len) {
    int fd;
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)data,
        .rx_buf = (unsigned long)data,
        .len = len,
        .speed_hz = SPI_SPEED,
        .delay_usecs = SPI_DELAY,
        .bits_per_word = SPI_BITS
    };

    fd = open(SPI_DEVICE, O_RDWR);
    if (fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI read failed");
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

void handle_signal(int sig) {
