void setup_gpio() {
    int ret;

    gpio_fd = open("/dev/gpiochip0", O_RDWR);
    if (gpio_fd < 0) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    // Request lines for motor control
    ret = ioctl(gpio_fd, GPIO_GET_LINEHANDLE_BY_NUMBER, &MOTOR1_IN1);
    if (ret < 0) {
        perror("Failed to get line handle for MOTOR1_IN1");
        close(gpio_fd);
        exit(EXIT_FAILURE);
    }
    if (ioctl(gpio_fd, GPIO_LINE_SET_FLAGS, GPIO_LINE_FLAG_OUTPUT) < 0) {
        perror("Failed to set output for MOTOR1_IN1");
        close(gpio_fd);
        exit(EXIT_FAILURE);
    }

