#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define I2C_BUS 1
#define I2C_ADDR 0x5A
#define GPIO_RELAY 17
#define LOG_FILE "relay_log.txt"
#define POLL_INTERVAL_MS 50

typedef struct {
    int fd;
    struct gpiod_line *relay_line;
    FILE *log_file;
    int running;
} app_state;

void handle_signal(int sig) {
    if (sig == SIGINT) {
        printf("Caught SIGINT, shutting down...\n");
        app_state *state = (app_state *)malloc(sizeof(app_state));
        state->running = 0;
        // Free resources here if needed
        free(state);
        exit(EXIT_SUCCESS);
    }
}

void init_i2c(int *fd) {
    char filename[256];
    snprintf(filename, sizeof(filename), "/dev/i2c-%d", I2C_BUS);
    *fd = open(filename, O_RDWR);
    if (*fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    if (ioctl(*fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(*fd);
        exit(EXIT_FAILURE);
    }
}

void init_mpr121(int fd) {
    unsigned char data[2];

    // Soft reset
    data[0] = 0x5A; // Soft reset command
    data[1] = 0x00;
    if (write(fd, data, 2) != 2) {
        perror("Failed to send soft reset command");
        exit(EXIT_FAILURE);
    }

    // Wait for reset to complete
    usleep(100000);

    // Configuration register
    data[0] = 0x2D; // Configuration register
    data[1] = 0x2C; // Enable all 12 electrodes, 100Hz, 100ms, 100ms
    if (write(fd, data, 2) != 2) {
        perror("Failed to write configuration register");
        exit(EXIT_FAILURE);
    }

    // Touch threshold register (all 12 electrodes)
    data[0] = 0x4B; // Touch threshold register
    data[1] = 0x00; // Default touch threshold
    if (write(fd, data, 2) != 2) {
        perror("Failed to write touch threshold register");
        exit(EXIT_FAILURE);
    }

    // Release threshold register (all 12 electrodes)
    data[0] = 0x4C; // Release threshold register
    data[1] = 0x00; // Default release threshold
    if (write(fd, data, 2) != 2) {
        perror("Failed to write release threshold register");
        exit(EXIT_FAILURE);
    }

    // Enable run mode
    data[0] = 0x2D; // Configuration register
    data[1] = 0x2C; // Enable all 12 electrodes, 100Hz, 100ms, 100ms
    if (write(fd, data, 2) != 2) {
        perror("Failed to write configuration register again");
        exit(EXIT_FAILURE);
    }
}

void init_gpio() {
    struct gpiod_line *line;
    struct gpiod_chip *chip;

    chip = gpiod_chip_open("/dev/gpiochip4");
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    line = gpiod_line_request_output(chip, "relay", GPIO_RELAY, 0);
    if (!line) {
        perror("Failed to request GPIO line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    return line;
}

void read_mpr121(int fd, unsigned char *data) {
    if (read(fd, data, 2) != 2) {
        perror("Failed to read MPR121 data");
        exit(EXIT_FAILURE);
    }
}

void log_relay_state(int state, time_t timestamp) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        return;
    }

    fprintf(log_file, "%ld,%d\n", (long)timestamp, state);
    fclose(log_file);
}

void cleanup(app_state *state) {
    if (state->log_file) {
        fclose(state->log_file);
    }

    if (state->relay_line) {
        gpiod_line_release(state->relay_line);
    }

