        exit(EXIT_FAILURE);
    }

    // Touch threshold register (all 12 electrodes)
    data[0] = 0x4B; // Touch threshold register
    data[1] = 0x00; // Default touch threshold
    if (write(fd, data, 2) != 2) {
        perror("Failed to write touch threshold register");
        exit(EXIT_FAILURE);
    }

    // Release threshold register (all 12 electrodes)
    data[0] = 0x4C; // Release threshold register
    data[1] = 0x00; // Default release threshold
    if (write(fd, data, 2) != 2) {
        perror("Failed to write release threshold register");
        exit(EXIT_FAILURE);
    }

