#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS 1
#define I2C_ADDR 0x5C
#define GPIO_RELAY 17
#define GPIO_TOUCH_SDA 2
#define GPIO_TOUCH_SCL 3
#define DELAY_MS 100
#define TOUCH_THRESHOLD 1
#define RELEASE_THRESHOLD 1
#define FILTER_TIME 0x00
#define CHARGE_TIME 0x00
#define ELEC_CURRENT 0x00
#define STOP_MODE 0x00
#define RUN_MODE 0x01

typedef struct {
    int i2c_fd;
    struct gpiod_line *relay_line;
    int running;
} app_state;

void handle_signal(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        printf("Shutting down...\n");
        app_state *state = (app_state *)malloc(sizeof(app_state));
        state->running = 0;
        free(state);
        exit(EXIT_SUCCESS);
    }
}

void i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buffer[2];
    buffer[0] = reg;
    buffer[1] = value;
    if (write(fd, buffer, 2) != 2) {
        perror("I2C write failed");
        exit(EXIT_FAILURE);
    }
}

uint8_t i2c_read_byte(int fd, uint8_t reg) {
    uint8_t buffer[1];
    buffer[0] = reg;
    if (ioctl(fd, I2C_RDWR, (struct i2c_rdwr_ioctl_data *)&(struct i2c_msg[0])) < 0) {
        perror("I2C read failed");
        exit(EXIT_FAILURE);
    }
    if (read(fd, buffer, 1) != 1) {
        perror("I2C read failed");
        exit(EXIT_FAILURE);
    }
    return buffer[0];
}

void i2c_read_bytes(int fd, uint8_t reg, uint8_t *data, int len) {
    struct i2c_msg msgs[2];
    struct i2c_rdwr_ioctl_data rdwr;
    uint8_t buffer[1 + len];

    buffer[0] = reg;
    msgs[0].addr = I2C_ADDR;
    msgs[0].flags = 0;
    msgs[0].len = 1;
    msgs[0].buf = buffer;

    msgs[1].addr = I2C_ADDR;
    msgs[1].flags = I2C_M_RD;
    msgs[1].len = len;
    msgs[1].buf = buffer + 1;

    rdwr.msgs = msgs;
    rdwr.nmsgs = 2;

    if (ioctl(fd, I2C_RDWR, &rdwr) < 0) {
        perror("I2C read failed");
        exit(EXIT_FAILURE);
    }

    memcpy(data, buffer + 1, len);
}

void setup_i2c(int *fd) {
    char filename[20];
    snprintf(filename, sizeof(filename), "/dev/i2c-%d", I2C_BUS);
    *fd = open(filename, O_RDWR);
    if (*fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    if (ioctl(*fd, I2C_TEN, 0) < 0) {
        perror("I2C set 10-bit address mode failed");
        close(*fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(*fd, I2C_ADDR, I2C_ADDR) < 0) {
        perror("I2C set address failed");
        close(*fd);
        exit(EXIT_FAILURE);
    }
}

void setup_gpio() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;

    chip = gpiod_chip_open(GPIO_RELAY);
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    line = gpiod_line_request_output(chip, "relay", GPIO_RELAY, 0);
    if (!line) {
        perror("Failed to request GPIO line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    return line;
}

void configure_mpr121(int fd) {
    // Set filter time
    i2c_write_byte(fd, 0x0A, FILTER_TIME);

    // Set charge time
    i2c_write_byte(fd, 0x0B, CHARGE_TIME);

    // Set electrode current
    i2c_write_byte(fd, 0x0C, ELEC_CURRENT);

    // Set touch and release thresholds for all 12 electrodes
    for (int i = 0; i < 12; i++) {
        i2c_write_byte(fd, 0x0D + i, TOUCH_THRESHOLD);
        i2c_write_byte(fd, 0x0E + i, RELEASE_THRESHOLD);
    }

    // Set stop mode
    i2c_write_byte(fd, 0x0F, STOP_MODE);

    // Wait for stabilization
    usleep(100000);

    // Switch to run mode
    i2c_write_byte(fd, 0x0F, RUN_MODE);
}

void monitor_touch_status(int fd) {
    uint8_t touch_status[12];
    i2c_read_bytes(fd, 0x00, touch_status, 12);

    for (int i = 0; i < 12; i++) {
        if (touch_status[i] > 0) {
            // Toggle relay
            int relay_state = gpiod_line_get_value(app_state.relay_line);
            gpiod_line_set_value(app_state.relay_line, !relay_state);
            printf("Relay toggled: %d\n", !relay_state);
            break;
        }
    }
}

int main() {
    int i2c_fd;
    struct gpiod_line *relay_line;
    app_state state = {0};

    // Set up signal handling
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Initialize GPIO
    relay_line = setup_gpio();
    state.relay_line = relay_line;

    // Initialize I2C
    setup_i2c(&i2c_fd);
    state.i2c_fd = i2c_fd;

    // Configure MPR121
    configure_mpr121(i2c_fd);

    // Main loop
    state.running = 1;
    while (state.running) {
        monitor_touch_status(i2c_fd);
        usleep(DELAY_MS * 1000);
    }

    // Cleanup
    gpiod_line_release(relay_line);
    close(i2c_fd);
    gpiod_chip_close(relay_line->chip);

    return 0;
}

