#define RELAY_DURATION_MS 500
#define RATE_LIMIT_MS 2000
#define LOG_FILE "door_events.log"

typedef enum {
    STATE_IDLE,
    STATE_UNLOCKING,
    STATE_RATE_LIMITING
} State;

typedef struct {
    int gpio_fd;
    int last_state;
    time_t last_motion_time;
    time_t last_unlock_time;
    State state;
    FILE *log_file;
} AppContext;

void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);
    fprintf(stderr, "[%s] %s\n", timestamp, message);
    fprintf(log_file, "[%s] %s\n", timestamp, message);
    fflush(log_file);
}

void init_gpio(AppContext *ctx) {
    ctx->gpio_fd = open("/dev/gpiochip0", O_RDWR);
    if (ctx->gpio_fd < 0) {
        log_event("Failed to open GPIO device");
        exit(1);
    }

    struct gpio_request req = {
        .lineoffset = GPIO_PIR_PIN,
        .flags = GPIO_REQUEST_INPUT | GPIO_REQUEST_OUTPUT,
        .consumer = "pir_sensor"
    };

    if (ioctl(ctx->gpio_fd, GPIO_REQUEST_LINE, &req) < 0) {
        log_event("Failed to request GPIO line for PIR sensor");
        close(ctx->gpio_fd);
        exit(1);
    }

    struct gpio_line_info info;
    if (ioctl(ctx->gpio_fd, GPIO_GET_LINEINFO, &req) < 0) {
        log_event("Failed to get line info for PIR sensor");
        close(ctx->gpio_fd);
        exit(1);
    }

    if (ioctl(ctx->gpio_fd, GPIO_GET_LINE_VALUES, &info) < 0) {
        log_event("Failed to get initial line values");
        close(ctx->gpio_fd);
        exit(1);
    }

    ctx->last_state = info.values[GPIO_PIR_PIN];

    struct gpio_line_config config = {
        .lineoffset = GPIO_PIR_PIN,
        .flags = GPIO_CONFIG_INPUT | GPIO_CONFIG_PULL_DOWN
    };

    if (ioctl(ctx->gpio_fd, GPIO_SET_LINE_CONFIG, &config) < 0) {
        log_event("Failed to configure PIR sensor line");
        close(ctx->gpio_fd);
        exit(1);
    }

    // Initialize relay GPIO
    req.lineoffset = GPIO_RELAY_PIN;
    req.flags = GPIO_REQUEST_OUTPUT;
    req.consumer = "door_strike_relay";

    if (ioctl(ctx->gpio_fd, GPIO_REQUEST_LINE, &req) < 0) {
        log_event("Failed to request GPIO line for relay");
        close(ctx->gpio_fd);
        exit(1);
    }

    struct gpio_line_config relay_config = {
        .lineoffset = GPIO_RELAY_PIN,
        .flags = GPIO_CONFIG_OUTPUT
    };

    if (ioctl(ctx->gpio_fd, GPIO_SET_LINE_CONFIG, &relay_config) < 0) {
        log_event("Failed to configure relay line");
        close(ctx->gpio_fd);
        exit(1);
    }

    // Set relay to off initially
    struct gpio_line_values values;
    values.values[GPIO_RELAY_PIN] = 0;
    if (ioctl(ctx->gpio_fd, GPIO_SET_LINE_VALUES, &values) < 0) {
        log_event("Failed to set relay to off");
        close(ctx->gpio_fd);
        exit(1);
    }

    ctx->log_file = fopen(LOG_FILE, "a");
    if (!ctx->log_file) {
        log_event("Failed to open log file");
        close(ctx->gpio_fd);
        exit(1);
    }
}

void cleanup_gpio(AppContext *ctx) {
    if (ctx->log_file) {
        fclose(ctx->log_file);
    }

    if (ctx->gpio_fd >= 0) {
        struct gpio_line_values values;
        values.values[GPIO_RELAY_PIN] = 0;
        if (ioctl(ctx->gpio_fd, GPIO_SET_LINE_VALUES, &values) < 0) {
            log_event("Failed to set relay to off during cleanup");
        }

        struct gpio_request req = {
            .lineoffset = GPIO_PIR_PIN,
            .flags = 0,
            .consumer = "pir_sensor"
        };
        if (ioctl(ctx->gpio_fd, GPIO_REQUEST_LINE, &req) < 0) {
            log_event("Failed to release PIR sensor line");
        }

        req.lineoffset = GPIO_RELAY_PIN;
        req.flags = 0;
        req.consumer = "door_strike_relay";
        if (ioctl(ctx->gpio_fd, GPIO_REQUEST_LINE, &req) < 0) {
            log_event("Failed to release relay line");
        }

        close(ctx->gpio_fd);
    }
}

void handle_signal(int sig) {
    if (sig == SIGINT) {
        log_event("Received SIGINT, cleaning up...");
    }
    exit(0);
}

void poll_gpio(AppContext *ctx) {
    struct gpio_line_values values;
    if (ioctl(ctx->gpio_fd, GPIO_GET_LINE_VALUES, &values) < 0) {
        log_event("Failed to read GPIO values");
        return;
    }

    int current_state = values.values[GPIO_PIR_PIN];
    if (current_state != ctx->last_state) {
        if (current_state == 1) {
            time_t now = time(NULL);
            if (ctx->state == STATE_IDLE) {
                log_event("Motion detected");
                ctx->last_motion_time = now;
                ctx->state = STATE_UNLOCKING;
                struct gpio_line_values unlock_values;
                unlock_values.values[GPIO_RELAY_PIN] = 1;
                if (ioctl(ctx->gpio_fd, GPIO_SET_LINE_VALUES, &unlock_values) < 0) {
                    log_event("Failed to activate relay");
                }
            } else if (ctx->state == STATE_RATE_LIMITING) {
                log_event("Rate limit active, ignoring motion");
            }
        }
        ctx->last_state = current_state;
    }

    if (ctx->state == STATE_UNLOCKING) {
        time_t now = time(NULL);
        if (now - ctx->last_motion_time >= RELAY_DURATION_MS / 1000.0) {
            struct gpio_line_values off_values;
            off_values.values[GPIO_RELAY_PIN] = 0;
            if (ioctl(ctx->gpio_fd, GPIO_SET_LINE_VALUES, &off_values) < 0) {
                log_event("Failed to deactivate relay");
            }
            ctx->state = STATE_RATE_LIMITING;
            ctx->last_unlock_time = now;
            log_event("Relay deactivated");
        }
    } else if (ctx->state == STATE_RATE_LIMITING) {
        time_t now = time(NULL);
        if (now - ctx->last_unlock_time >= RATE_LIMIT_MS / 1000.0) {
            ctx->state = STATE_IDLE;
            log_event("Rate limit expired");
        }
    }
}

int main() {
    AppContext ctx = {0};

    signal(SIGINT, handle_signal);

    if (init_gpio(&ctx) < 0) {
        return 1;
    }

    while (1) {
        poll_gpio(&ctx);
        usleep(POLL_INTERVAL_MS * 1000);
    }

    cleanup_gpio(&ctx);
    return 0;
}

