#define GPIO_MOTOR2 BCM_GPIO_27
#define MAX_STEPS 15
#define MIN_STEPS 5
#define MAX_DURATION_MS 200
#define MIN_DURATION_MS 50
#define MAX_DUTY_CYCLE 255
#define MIN_DUTY_CYCLE 0

volatile sig_atomic_t shutdown = 0;

void handle_signal(int sig) {
    shutdown = 1;
}

void setup_gpio(gpiod_line *line, int direction) {
    int ret;
    ret = gpiod_line_request_output(line, "haptic_motor", direction, 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request GPIO line: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }
}

void set_pwm_duty_cycle(gpiod_line *line, int duty_cycle) {
    int ret;
    ret = gpiod_line_set_value(line, duty_cycle);
    if (ret < 0) {
        fprintf(stderr, "Failed to set PWM duty cycle: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }
}

void generate_random_pattern(gpiod_line *motor1_line, gpiod_line *motor2_line) {
    int steps = rand() % (MAX_STEPS - MIN_STEPS + 1) + MIN_STEPS;
    int duration_ms = 0;
    int duty_cycle1 = 0;
    int duty_cycle2 = 0;
    int i;

    printf("Generating pattern with %d steps:\n", steps);

    for (i = 0; i < steps; i++) {
        duty_cycle1 = rand() % (MAX_DUTY_CYCLE - MIN_DUTY_CYCLE + 1) + MIN_DUTY_CYCLE;
        duty_cycle2 = rand() % (MAX_DUTY_CYCLE - MIN_DUTY_CYCLE + 1) + MIN_DUTY_CYCLE;
        duration_ms = rand() % (MAX_DURATION_MS - MIN_DURATION_MS + 1) + MIN_DURATION_MS;

        set_pwm_duty_cycle(motor1_line, duty_cycle1);
        set_pwm_duty_cycle(motor2_line, duty_cycle2);

        usleep(duration_ms * 1000);
    }

    set_pwm_duty_cycle(motor1_line, 0);
    set_pwm_duty_cycle(motor2_line, 0);
}

int main() {
    gpiod_chip *chip;
    gpiod_line *motor1_line = NULL;
    gpiod_line *motor2_line = NULL;
    int ret;

    srand(time(NULL));

    signal(SIGINT, handle_signal);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    motor1_line = gpiod_chip_get_line(chip, GPIO_MOTOR1);
    if (!motor1_line) {
        fprintf(stderr, "Failed to get GPIO line for motor1: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    motor2_line = gpiod_chip_get_line(chip, GPIO_MOTOR2);
    if (!motor2_line) {
        fprintf(stderr, "Failed to get GPIO line for motor2: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    setup_gpio(motor1_line, GPIOD_LINE_DIRECTION_OUTPUT);
    setup_gpio(motor2_line, GPIOD_LINE_DIRECTION_OUTPUT);

    while (!shutdown) {
        generate_random_pattern(motor1_line, motor2_line);
        usleep(100000); // 100ms delay between patterns
    }

    set_pwm_duty_cycle(motor1_line, 0);
    set_pwm_duty_cycle(motor2_line, 0);

    gpiod_line_release(motor1_line);
    gpiod_line_release(motor2_line);
    gpiod_chip_close(chip);

    return 0;
}
