    if (gpiod_line_set_direction(clock_line, GPIOD_LINE_DIRECTION_OUTPUT) < 0) {
        perror("Failed to set clock line direction");
        return -1;
    }

    // Send 28 clock pulses
    for (int i = 0; i < 28; i++) {
        if (gpiod_line_set_value(clock_line, 1) < 0) {
            perror("Failed to set clock line high");
            return -1;
        }
        usleep(100);
        if (gpiod_line_set_value(clock_line, 0) < 0) {
