#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/time.h>
#include <sys/types.h>
#include <syslog.h>
#include <signal.h>
#include <libgpiod.h>

#define GPIO_RAIN_SENSOR 4
#define GPIO_IN1 17
#define GPIO_IN2 18
#define GPIO_PWM_ENABLE 27
#define PWM_FREQUENCY 1000
#define PWM_DUTY_CYCLE 150
#define RAIN_THRESHOLD 3
#define DEBOUNCE_DELAY_MS 50
#define CHECK_INTERVAL_S 60
#define POST_OPERATION_DELAY_S 60
#define LOG_FILE "/var/log/window_control.log"

typedef enum {
    STATE_IDLE,
    STATE_RAIN_DETECTED,
    STATE_MOTOR_RUNNING
} state_t;

typedef struct {
    int sensor_fd;
    struct gpiod_line *rain_line;
    struct gpiod_line *in1_line;
    struct gpiod_line *in2_line;
    struct gpiod_line *pwm_line;
    state_t state;
    int motor_active;
} gpio_state_t;

void log_message(const char *message) {
    syslog(LOG_INFO, "%s", message);
}

void log_event(const char *event) {
    syslog(LOG_INFO, "Event: %s", event);
}

void log_error(const char *message) {
    syslog(LOG_ERR, "%s", message);
}

void handle_signal(int sig) {
    log_message("Received signal, stopping motor and exiting.");
    if (gpio_state.motor_active) {
        log_event("Stopping motor.");
        gpiod_line_set_value(gpio_state.in1_line, 0);
        gpiod_line_set_value(gpio_state.in2_line, 0);
        gpiod_line_set_value(gpio_state.pwm_line, 0);
        gpio_state.motor_active = 0;
    }
    if (gpio_state.sensor_fd >= 0) {
        gpiod_line_release(gpio_state.rain_line);
        gpiod_line_release(gpio_state.in1_line);
        gpiod_line_release(gpio_state.in2_line);
        gpiod_line_release(gpio_state.pwm_line);
    }
    close(gpio_state.sensor_fd);
    exit(EXIT_SUCCESS);
}

int init_gpio(gpio_state_t *state) {
    int ret;

    state->sensor_fd = open("/dev/gpiochip4", O_RDWR);
    if (state->sensor_fd < 0) {
        log_error("Failed to open GPIO chip.");
        return -1;
    }

    state->rain_line = gpiod_chip_get_line(state->sensor_fd, GPIO_RAIN_SENSOR);
    if (!state->rain_line) {
        log_error("Failed to get rain sensor line.");
        close(state->sensor_fd);
        return -1;
    }

    if (gpiod_line_request_output(state->rain_line, "rain_sensor", GPIOD_LINE_REQUEST_FLAG_ACTIVE_LOW)) {
        log_error("Failed to request rain sensor line.");
        gpiod_line_release(state->rain_line);
        close(state->sensor_fd);
        return -1;
    }

    state->in1_line = gpiod_chip_get_line(state->sensor_fd, GPIO_IN1);
    if (!state->in1_line) {
        log_error("Failed to get IN1 line.");
        gpiod_line_release(state->rain_line);
        close(state->sensor_fd);
        return -1;
    }

    if (gpiod_line_request_output(state->in1_line, "in1", GPIOD_LINE_REQUEST_FLAG_ACTIVE_LOW)) {
        log_error("Failed to request IN1 line.");
        gpiod_line_release(state->rain_line);
        close(state->sensor_fd);
        return -1;
    }

    state->in2_line = gpiod_chip_get_line(state->sensor_fd, GPIO_IN2);
    if (!state->in2_line) {
        log_error("Failed to get IN2 line.");
        gpiod_line_release(state->rain_line);
        gpiod_line_release(state->in1_line);
        close(state->sensor_fd);
        return -1;
    }

    if (gpiod_line_request_output(state->in2_line, "in2", GPIOD_LINE_REQUEST_FLAG_ACTIVE_LOW)) {
        log_error("Failed to request IN2 line.");
        gpiod_line_release(state->rain_line);
        gpiod_line_release(state->in1_line);
        close(state->sensor_fd);
        return -1;
    }

    state->pwm_line = gpiod_chip_get_line(state->sensor_fd, GPIO_PWM_ENABLE);
    if (!state->pwm_line) {
        log_error("Failed to get PWM enable line.");
        gpiod_line_release(state->rain_line);
        gpiod_line_release(state->in1_line);
        gpiod_line_release(state->in2_line);
        close(state->sensor_fd);
        return -1;
    }

    if (gpiod_line_request_output(state->pwm_line, "pwm_enable", GPIOD_LINE_REQUEST_FLAG_ACTIVE_LOW)) {
        log_error("Failed to request PWM enable line.");
        gpiod_line_release(state->rain_line);
        gpiod_line_release(state->in1_line);
        gpiod_line_release(state->in2_line);
        close(state->sensor_fd);
        return -1;
    }

    gpiod_line_set_value(state->in1_line, 1);
    gpiod_line_set_value(state->in2_line, 0);
    state->motor_active = 0;

    return 0;
}

int read_sensor_value(gpio_state_t *state) {
    int value;
    if (gpiod_line_get_value(state->rain_line, &value)) {
        log_error("Failed to read sensor value.");
        return -1;
    }
    return value;
}

int check_for_rain(gpio_state_t *state) {
    int low_count = 0;
