#include <errno.h>
#include <gpiod.h>

#define DT_PIN 23
#define SCK_PIN 24
#define LOCK_PIN 17
#define LOG_FILE "stock_events.txt"
#define MIN_WEIGHT 100
#define LOCK_DURATION 5
#define CHECK_INTERVAL 1

typedef enum {
    HX711_OK,
    HX711_TIMEOUT,
    HX711_DATA_STUCK_HIGH,
    HX711_READ_ERROR
} HX711_STATUS;

typedef enum {
    GPIO_OK,
    GPIO_INIT_ERROR,
    GPIO_PIN_ERROR,
    GPIO_WRITE_ERROR,
    GPIO_READ_ERROR
} GPIO_STATUS;

typedef enum {
    FILE_OK,
    FILE_OPEN_ERROR,
    FILE_WRITE_ERROR
} FILE_STATUS;

typedef struct {
    int dt_fd;
    int sck_fd;
    int lock_fd;
    FILE *log_file;
    gpiod_line *dt_line;
    gpiod_line *sck_line;
    gpiod_line *lock_line;
    int running;
} AppContext;

void log_event(FILE *log_file, const char *message) {
    struct timeval tv;
    gettimeofday(&tv, NULL);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&tv.tv_sec));
    fprintf(log_file, "[%s] %s\n", timestamp, message);
    fflush(log_file);
}

void handle_signal(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        log_event(app.log_file, "Received termination signal. Shutting down...");
        app.running = 0;
    }
}

void init_gpio(AppContext *app) {
    app->dt_line = gpiod_line_get("BCM", DT_PIN);
    if (!app->dt_line) {
        log_event(app->log_file, "Failed to get DT GPIO line.");
        exit(EXIT_FAILURE);
    }

    app->sck_line = gpiod_line_get("BCM", SCK_PIN);
    if (!app->sck_line) {
        log_event(app->log_file, "Failed to get SCK GPIO line.");
        exit(EXIT_FAILURE);
    }

    app->lock_line = gpiod_line_get("BCM", LOCK_PIN);
    if (!app->lock_line) {
        log_event(app->log_file, "Failed to get LOCK GPIO line.");
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(app->dt_line, "dt", GPIOD_LINE_REQUEST_OUTPUT) < 0) {
        log_event(app->log_file, "Failed to request DT GPIO as output.");
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(app->sck_line, "sck", GPIOD_LINE_REQUEST_OUTPUT) < 0) {
        log_event(app->log_file, "Failed to request SCK GPIO as output.");
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(app->lock_line, "lock", GPIOD_LINE_REQUEST_OUTPUT) < 0) {
        log_event(app->log_file, "Failed to request LOCK GPIO as output.");
        exit(EXIT_FAILURE);
    }

    gpiod_line_set_value(app->sck_line, 0); // Set SCK to low
    gpiod_line_set_value(app->dt_line, 0);  // Set DT to low
    gpiod_line_set_value(app->lock_line, 0); // Lock off
}

void deinit_gpio(AppContext *app) {
    if (app->lock_line) {
        gpiod_line_release(app->lock_line);
    }
    if (app->sck_line) {
        gpiod_line_release(app->sck_line);
    }
    if (app->dt_line) {
        gpiod_line_release(app->dt_line);
    }
}

void read_hx711(AppContext *app, int *raw_value) {
    int data = 0;
    int timeout = 0;
    int max_attempts = 1000;

    // Reset the HX711
    gpiod_line_set_value(app->sck_line, 0);
    usleep(100);

    // Send 24 bits of command (0x00 for read)
    for (int i = 0; i < 24; i++) {
        gpiod_line_set_value(app->sck_line, 1);
        usleep(10);
        gpiod_line_set_value(app->sck_line, 0);
        usleep(10);
    }

    // Read 24 bits of data
    for (int i = 0; i < 24; i++) {
        gpiod_line_set_value(app->sck_line, 1);
        usleep(10);
        data <<= 1;
        if (gpiod_line_get_value(app->dt_line) == 1) {
            data |= 1;
        }
        gpiod_line_set_value(app->sck_line, 0);
        usleep(10);
        timeout++;
        if (timeout > max_attempts) {
            log_event(app->log_file, "HX711 read timeout.");
            return;
        }
    }

    // Check if data line is stuck high
    if (gpiod_line_get_value(app->dt_line) == 1) {
        log_event(app->log_file, "HX711 data line stuck high.");
        return;
    }

    *raw_value = data;
}

void activate_lock(AppContext *app) {
    gpiod_line_set_value(app->lock_line, 1);
    log_event(app->log_file, "Solenoid lock activated.");
    usleep(LOCK_DURATION * 1000000);
    gpiod_line_set_value(app->lock_line, 0);
    log_event(app->log_file, "Solenoid lock deactivated.");
}

void init_log_file(AppContext *app) {
    app->log_file = fopen(LOG_FILE, "a");
    if (!app->log_file) {
        log_event(NULL, "Failed to open log file.");
        exit(EXIT_FAILURE);
    }
    log_event(app->log_file, "Log started.");
}

void close_log_file(AppContext *app) {
    if (app->log_file) {
        fclose(app->log_file);
        log_event(app->log_file, "Log closed.");
    }
}

int main() {
    AppContext app = {0};
    app.running = 1;

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    init_log_file(&app);
    init_gpio(&app);

    while (app.running) {
        int raw_value = 0;
        HX711_STATUS hx_status = HX711_OK;

        // Read HX711
        read_hx711(&app, &raw_value);
        if (hx_status == HX711_TIMEOUT || hx_status == HX711_DATA_STUCK_HIGH) {
            log_event(app.log_file, "HX711 read error.");
            usleep(1000000);
            continue;
        }

        // Convert raw value to grams (assuming calibration factor)
        // This is a placeholder; actual calibration may vary
        int weight = raw_value / 100; // Example conversion

        log_event(app.log_file, "Weight check: %d g", weight);

        if (weight < MIN_WEIGHT) {
            log_event(app.log_file, "Weight below threshold. Activating lock.");
            activate_lock(&app);
        }

        usleep(CHECK_INTERVAL * 1000000);
    }

    deinit_gpio(&app);
    close_log_file(&app);

    return 0;
}

