    if (!app->log_file) {
        log_event(NULL, "Failed to open log file.");
        exit(EXIT_FAILURE);
    }
    log_event(app->log_file, "Log started.");
}

void close_log_file(AppContext *app) {
    if (app->log_file) {
        fclose(app->log_file);
        log_event(app->log_file, "Log closed.");
    }
}

int main() {
    AppContext app = {0};
    app.running = 1;

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    init_log_file(&app);
    init_gpio(&app);

    while (app.running) {
        int raw_value = 0;
        HX711_STATUS hx_status = HX711_OK;

        // Read HX711
        read_hx711(&app, &raw_value);
        if (hx_status == HX711_TIMEOUT || hx_status == HX711_DATA_STUCK_HIGH) {
            log_event(app.log_file, "HX711 read error.");
            usleep(1000000);
            continue;
        }

        // Convert raw value to grams (assuming calibration factor)
        // This is a placeholder; actual calibration may vary
        int weight = raw_value / 100; // Example conversion

        log_event(app.log_file, "Weight check: %d g", weight);

        if (weight < MIN_WEIGHT) {
            log_event(app.log_file, "Weight below threshold. Activating lock.");
            activate_lock(&app);
        }

        usleep(CHECK_INTERVAL * 1000000);
    }

    deinit_gpio(&app);
    close_log_file(&app);

    return 0;
}
