}

int init_gpio(int pin, int direction) {
    struct gpiod_line *line;
    int ret;

    line = gpiod_line_get("bcm", pin, "gpio");
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line for pin %d\n", pin);
        return -1;
    }

    ret = gpiod_line_request_output(line, "hx711", direction, 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request GPIO line for pin %d: %s\n", pin, strerror(errno));
        gpiod_line_put(line);
        return -1;
    }

    return gpiod_line_get_fd(line);
}

int read_hx711(hx711_state *state) {
    int data = 0;
    int i;

    // Start reading
    for (i = 0; i < 24; i++) {
        // Set clock low
        if (gpio_line_get_value(clock_fd) == 1) {
            gpio_line_set_value(clock_fd, 0);
        }
        usleep(1); // 1 µs delay

        // Read data bit
        if (gpio_line_get_value(data_fd) == 1) {
            data |= (1 << (23 - i));
        }

        // Set clock high
        if (gpio_line_get_value(clock_fd) == 0) {
            gpio_line_set_value(clock_fd, 1);
        }
        usleep(1); // 1 µs delay
    }

    // Set clock low to end the reading
    if (gpio_line_get_value(clock_fd) == 1) {
        gpio_line_set_value(clock_fd, 0);
    }
    usleep(1); // 1 µs delay

    return data;
}

int read_weight(hx711_state *state) {
    int data;
    int timeout = 0;
    struct timeval start_time;

    gettimeofday(&start_time, NULL);

    while (1) {
        if (gpio_line_get_value(data_fd) == 1) {
            timeout++;
            if (timeout > TIMEOUT_MS * 1000 / 1000) {
                fprintf(stderr, "Communication timeout with HX711\n");
                return -1;
            }
        } else {
            timeout = 0;
        }

        usleep(1000); // 1 ms check interval
    }

    data = read_hx711(state);
    if (data < 0) {
        return -1;
    }

    // Convert to signed 24-bit value
    if (data > 0x7fffff) {
        data -= 0x1000000;
    }

    return data;
}

