    FILE *calibration_file = fopen(CALIBRATION_FILE, "w");
    if (!calibration_file) {
        fprintf(stderr, "Failed to open calibration file for writing\n");
        exit(EXIT_FAILURE);
    }

    if (fprintf(calibration_file, "%f\n", state->calibration_factor) < 0) {
        fprintf(stderr, "Failed to write calibration factor to file\n");
        fclose(calibration_file);
        exit(EXIT_FAILURE);
    }

    fclose(calibration_file);
    printf("Calibration complete. Calibration factor saved to %s\n", CALIBRATION_FILE);
