#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define GPIO_SENSOR_PIN 16
#define GPIO_RELAY_PIN 20
#define LOG_FILE "relay_events.log"

typedef enum {
    RELAY_STATE_OFF,
    RELAY_STATE_ON
} RelayState;

RelayState current_relay_state = RELAY_STATE_OFF;
int sensor_value = 0;

void log_event(const char *message) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return;
    }

    time_t now;
    struct tm *time_info;
    char timestamp[64];

    time(&now);
    time_info = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", time_info);

    fprintf(log_file, "%s - %s\n", timestamp, message);
    fclose(log_file);
}

void handle_signal(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        printf("Received signal %d, cleaning up...\n", signal);
        gpiod_line_release(sensor_line);
        gpiod_line_release(relay_line);
        exit(EXIT_SUCCESS);
    }
}

void init_gpio() {
    struct gpiod_chip *chip;
    struct gpiod_line *sensor_line, *relay_line;

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    sensor_line = gpiod_line_request_output(chip, "sensor", GPIO_SENSOR_PIN, 0);
    if (!sensor_line) {
        fprintf(stderr, "Failed to request sensor line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    relay_line = gpiod_line_request_output(chip, "relay", GPIO_RELAY_PIN, 1);
    if (!relay_line) {
        fprintf(stderr, "Failed to request relay line: %s\n", strerror(errno));
        gpiod_line_release(sensor_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    sensor_line = gpiod_line_get(chip, GPIO_SENSOR_PIN);
    if (!sensor_line) {
        fprintf(stderr, "Failed to get sensor line: %s\n", strerror(errno));
        gpiod_line_release(relay_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    relay_line = gpiod_line_get(chip, GPIO_RELAY_PIN);
    if (!relay_line) {
        fprintf(stderr, "Failed to get relay line: %s\n", strerror(errno));
        gpiod_line_release(sensor_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    gpiod_line_set_value(sensor_line, 1);  // Set sensor to high (pull-up)
    gpiod_line_set_value(relay_line, 0);   // Initial state: relay off

    current_relay_state = RELAY_STATE_OFF;
    sensor_value = gpiod_line_get_value(sensor_line);
}

void monitor_sensor() {
    while (1) {
        sensor_value = gpiod_line_get_value(sensor_line);
        if (sensor_value == 0) {  // Obstacle detected (active-low)
            current_relay_state = (current_relay_state == RELAY_STATE_ON) ? RELAY_STATE_OFF : RELAY_STATE_ON;
            gpiod_line_set_value(relay_line, current_relay_state);
            char state_str[16];
            snprintf(state_str, sizeof(state_str), "%s", (current_relay_state == RELAY_STATE_ON) ? "ON" : "OFF");
            log_event("Relay toggled to: ON");
        }
        usleep(100000);  // 100ms delay
    }
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if (init_gpio() != 0) {
        fprintf(stderr, "Failed to initialize GPIO.\n");
        exit(EXIT_FAILURE);
    }

    monitor_sensor();

    return 0;
}

