        exit(EXIT_FAILURE);
    }

    relay_line = gpiod_line_get(chip, GPIO_RELAY_PIN);
    if (!relay_line) {
        fprintf(stderr, "Failed to get relay line: %s\n", strerror(errno));
        gpiod_line_release(sensor_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    gpiod_line_set_value(sensor_line, 1);  // Set sensor to high (pull-up)
    gpiod_line_set_value(relay_line, 0);   // Initial state: relay off

    current_relay_state = RELAY_STATE_OFF;
    sensor_value = gpiod_line_get_value(sensor_line);
}

void monitor_sensor() {
    while (1) {
        sensor_value = gpiod_line_get_value(sensor_line);
        if (sensor_value == 0) {  // Obstacle detected (active-low)
            current_relay_state = (current_relay_state == RELAY_STATE_ON) ? RELAY_STATE_OFF : RELAY_STATE_ON;
            gpiod_line_set_value(relay_line, current_relay_state);
            char state_str[16];
            snprintf(state_str, sizeof(state_str), "%s", (current_relay_state == RELAY_STATE_ON) ? "ON" : "OFF");
            log_event("Relay toggled to: ON");
        }
        usleep(100000);  // 100ms delay
    }
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if (init_gpio() != 0) {
        fprintf(stderr, "Failed to initialize GPIO.\n");
        exit(EXIT_FAILURE);
    }

    monitor_sensor();

    return 0;
}
