#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/gpio.h>
#include <errno.h>

#define GPIO_PIN 18
#define CONFIG_FILE "watering.conf"
#define MAX_DURATION 3600
#define MIN_DURATION 1

volatile sig_atomic_t exit_flag = 0;

void handle_signal(int signum) {
    exit_flag = 1;
}

int init_gpio(int pin) {
    int fd;
    struct gpiohandle_request req;
    struct gpiohandle_data data;

    fd = open("/dev/gpiochip0", O_RDWR);
    if (fd < 0) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    req.lineoffset = pin;
    req.flags = GPIOHANDLE_REQUEST_OUTPUT;
    req.lines = 1;
    req.consumer_label = "watering_valve";

    if (ioctl(fd, GPIO_HANDLE_GET, &req) < 0) {
        perror("Failed to request GPIO line");
        close(fd);
        return -1;
    }

    data.values[0] = 0; // Default low (valve off)
    if (ioctl(req.fd, GPIOHANDLE_SET_LINE_VALUES_IOCTL, &data) < 0) {
        perror("Failed to set initial GPIO value");
        close(req.fd);
        close(fd);
        return -1;
    }

    close(fd);
    return req.fd;
}

void release_gpio(int fd) {
    if (fd >= 0) {
        close(fd);
    }
}

int parse_config(const char *filename, int *duration) {
    FILE *fp;
    char line[256];

    fp = fopen(filename, "r");
    if (!fp) {
        perror("Failed to open configuration file");
        return -1;
    }

    if (fgets(line, sizeof(line), fp) == NULL) {
        fprintf(stderr, "Empty or malformed configuration file\n");
        fclose(fp);
        return -1;
    }

    fclose(fp);

    char *token = strtok(line, "=");
    if (!token || strcmp(token, "duration") != 0) {
        fprintf(stderr, "Malformed configuration line\n");
        return -1;
    }

    token = strtok(NULL, "\n");
    if (!token) {
        fprintf(stderr, "Malformed configuration line\n");
        return -1;
    }

    *duration = atoi(token);
    if (*duration < MIN_DURATION || *duration > MAX_DURATION) {
        fprintf(stderr, "Duration out of range (1-3600 seconds)\n");
        return -1;
    }

    return 0;
}

void activate_valve(int gpio_fd) {
    struct gpiohandle_data data;
    data.values[0] = 1; // High to activate valve
    if (ioctl(gpio_fd, GPIOHANDLE_SET_LINE_VALUES_IOCTL, &data) < 0) {
        perror("Failed to activate valve");
    } else {
        printf("Valve activated for %d seconds\n", duration);
    }
}

void deactivate_valve(int gpio_fd) {
    struct gpiohandle_data data;
    data.values[0] = 0; // Low to deactivate valve
    if (ioctl(gpio_fd, GPIOHANDLE_SET_LINE_VALUES_IOCTL, &data) < 0) {
        perror("Failed to deactivate valve");
    } else {
        printf("Valve deactivated\n");
    }
}

int main() {
    int gpio_fd = -1;
    int duration = 0;

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if (parse_config(CONFIG_FILE, &duration) < 0) {
        fprintf(stderr, "Failed to parse configuration file\n");
        return 1;
    }

    gpio_fd = init_gpio(GPIO_PIN);
    if (gpio_fd < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    printf("Configured duration: %d seconds\n", duration);

    activate_valve(gpio_fd);

    // Signal-safe sleep
    if (duration > 0) {
        if (sleep(duration) < 0) {
            perror("Sleep failed");
        }
    }

    deactivate_valve(gpio_fd);

    // Check for exit signal
    while (exit_flag == 0) {
        sleep(1);
    }

    // Ensure valve is off before exit
    deactivate_valve(gpio_fd);

    release_gpio(gpio_fd);

    return 0;
}

