#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <unistd.h>

#define LEFT_SENSOR_PIN 4
#define MIDDLE_SENSOR_PIN 17
#define RIGHT_SENSOR_PIN 27
#define LEFT_MOTOR_PWM_PIN 22
#define RIGHT_MOTOR_PWM_PIN 23
#define LEFT_MOTOR_DIR_PIN 24
#define RIGHT_MOTOR_DIR_PIN 25

#define PWM_FREQUENCY 1000
#define BASE_SPEED 150
#define LOG_FILE "trace_log.txt"

typedef enum {
    STOP,
    FORWARD,
    LEFT_TURN,
    RIGHT_TURN
} RobotState;

typedef struct {
    gpiod_line *left_sensor;
    gpiod_line *middle_sensor;
    gpiod_line *right_sensor;
    gpiod_line *left_motor_pwm;
    gpiod_line *right_motor_pwm;
    gpiod_line *left_motor_dir;
    gpiod_line *right_motor_dir;
} GPIOHandles;

void handle_sigint(int sig) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file) {
        time_t now;
        struct tm *tm_info;
        char timestamp[64];

        time(&now);
        tm_info = localtime(&now);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

        fprintf(log_file, "%s,0,0,0,0,0\n", timestamp);
        fclose(log_file);
    }

    // Stop motors
    gpiod_line_set_value(GPIOHandles.left_motor_pwm, 0);
    gpiod_line_set_value(GPIOHandles.right_motor_pwm, 0);

    // Release all GPIO resources
    gpiod_line_release(GPIOHandles.left_sensor);
    gpiod_line_release(GPIOHandles.middle_sensor);
    gpiod_line_release(GPIOHandles.right_sensor);
    gpiod_line_release(GPIOHandles.left_motor_pwm);
    gpiod_line_release(GPIOHandles.right_motor_pwm);
    gpiod_line_release(GPIOHandles.left_motor_dir);
    gpiod_line_release(GPIOHandles.right_motor_dir);

    gpiod_chip_close(GPIOHandles.left_sensor->chip);
    gpiod_chip_close(GPIOHandles.middle_sensor->chip);
    gpiod_chip_close(GPIOHandles.right_sensor->chip);
    gpiod_chip_close(GPIOHandles.left_motor_pwm->chip);
    gpiod_chip_close(GPIOHandles.right_motor_pwm->chip);
    gpiod_chip_close(GPIOHandles.left_motor_dir->chip);
    gpiod_chip_close(GPIOHandles.right_motor_dir->chip);

    exit(EXIT_SUCCESS);
}

void setup_gpio(GPIOHandles *gpio) {
    struct gpiod_chip *chip;
    struct gpiod_line_config config;

    // Initialize left sensor
    chip = gpiod_chip_open_by_number(1); // BCM2 (GPIO 4 is on chip 1)
    if (!chip) {
        fprintf(stderr, "Failed to open left sensor chip\n");
        exit(EXIT_FAILURE);
    }
    config = gpiod_line_config_default();
    config.direction = GPIOD_LINE_DIRECTION_INPUT;
    config.consumer = "line_follower";
    gpio->left_sensor = gpiod_chip_get_line(chip, LEFT_SENSOR_PIN);
    if (!gpio->left_sensor) {
        fprintf(stderr, "Failed to get left sensor line\n");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }
    if (gpiod_line_request_config(gpio->left_sensor, &config)) {
        fprintf(stderr, "Failed to request left sensor line\n");
        gpiod_line_release(gpio->left_sensor);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Initialize middle sensor
    chip = gpiod_chip_open_by_number(1); // BCM2 (GPIO 17 is on chip 1)
    if (!chip) {
        fprintf(stderr, "Failed to open middle sensor chip\n");
        exit(EXIT_FAILURE);
    }
    gpio->middle_sensor = gpiod_chip_get_line(chip, MIDDLE_SENSOR_PIN);
    if (!gpio->middle_sensor) {
        fprintf(stderr, "Failed to get middle sensor line\n");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }
    if (gpiod_line_request_config(gpio->middle_sensor, &config)) {
        fprintf(stderr, "Failed to request middle sensor line\n");
        gpiod_line_release(gpio->middle_sensor);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Initialize right sensor
    chip = gpiod_chip_open_by_number(1); // BCM2 (GPIO 27 is on chip 1)
    if (!chip) {
        fprintf(stderr, "Failed to open right sensor chip\n");
        exit(EXIT_FAILURE);
    }
    gpio->right_sensor = gpiod_chip_get_line(chip, RIGHT_SENSOR_PIN);
    if (!gpio->right_sensor) {
        fprintf(stderr, "Failed to get right sensor line\n");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }
    if (gpiod_line_request_config(gpio->right_sensor, &config)) {
        fprintf(stderr, "Failed to request right sensor line\n");
        gpiod_line_release(gpio->right_sensor);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Initialize left motor PWM
    chip = gpiod_chip_open_by_number(1); // BCM2 (GPIO 22 is on chip 1)
    if (!chip) {
        fprintf(stderr, "Failed to open left motor PWM chip\n");
        exit(EXIT_FAILURE);
    }
    config = gpiod_line_config_default();
    config.direction = GPIOD_LINE_DIRECTION_OUTPUT;
    config.consumer = "motor_pwm";
    gpio->left_motor_pwm = gpiod_chip_get_line(chip, LEFT_MOTOR_PWM_PIN);
    if (!gpio->left_motor_pwm) {
        fprintf(stderr, "Failed to get left motor PWM line\n");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }
    if (gpiod_line_request_config(gpio->left_motor_pwm, &config)) {
