    va_end(args);

    fprintf(log_file, "%s\n", buffer);
    fflush(log_file);
}

void handle_signal(int sig) {
    app_state *state = (app_state *)malloc(sizeof(app_state));
    if (state) {
        state->running = 0;
        free(state);
    }
    exit(EXIT_SUCCESS);
}

int init_i2c() {
    char i2c_bus_path[32];
    snprintf(i2c_bus_path, sizeof(i2c_bus_path), "/dev/i2c-%d", I2C_BUS);
    int fd = open(i2c_bus_path, O_RDWR);
    if (fd < 0) {
        log_message("Failed to open I2C bus: %s", strerror(errno));
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, I2C_ADDR) < 0) {
        log_message("Failed to set I2C slave address: %s", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

int read_lux(int i2c_fd) {
    unsigned char cmd[2] = {0x40, 0x00};  // Continuous high resolution mode
    if (write(i2c_fd, cmd, 2) != 2) {
        log_message("Failed to write command to BH1750: %s", strerror(errno));
        return -1;
    }

    usleep(180000);  // 180 ms delay

    unsigned char data[2];
    if (read(i2c_fd, data, 2) != 2) {
        log_message("Failed to read data from BH1750: %s", strerror(errno));
        return -1;
    }

    int lux = (data[0] << 8) | data[1];
    return lux;
}

int init_gpio() {
    char gpio_path[64];
    snprintf(gpio_path, sizeof(gpio_path), "/sys/class/gpio/gpio%d", RELAY_PIN);
    FILE *gpio_export = fopen("/sys/class/gpio/export", "w");
    if (!gpio_export) {
        log_message("Failed to open GPIO export: %s", strerror(errno));
        return -1;
    }
    fprintf(gpio_export, "%d", RELAY_PIN);
    fclose(gpio_export);

    FILE *gpio_dir = fopen(gpio_path, "w");
    if (!gpio_dir) {
        log_message("Failed to open GPIO direction: %s", strerror(errno));
        return -1;
    }
    fprintf(gpio_dir, "out");
    fclose(gpio_dir);

    FILE *gpio_val = fopen("/sys/class/gpio/gpio%d/value", "r", RELAY_PIN);
    if (!gpio_val) {
        log_message("Failed to open GPIO value: %s", strerror(errno));
        return -1;
    }
    fclose(gpio_val);

    return 0;
}

void toggle_relay(int relay_fd, int state) {
    if (state) {
        if (write(relay_fd, "1", 1) != 1) {
            log_message("Failed to turn on relay: %s", strerror(errno));
        }
    } else {
        if (write(relay_fd, "0", 1) != 1) {
            log_message("Failed to turn off relay: %s", strerror(errno));
        }
    }
}

void cleanup(app_state *state) {
    if (state->i2c_fd >= 0) {
        close(state->i2c_fd);
    }

    if (state->relay_fd >= 0) {
        close(state->relay_fd);
    }

    if (state->log_file) {
        fclose(state->log_file);
    }

    log_message("Application terminated cleanly.");
}

int main() {
    app_state state = {0};

    signal(SIGINT, handle_signal);

    state.log_file = fopen(LOG_FILE, "a");
    if (!state.log_file) {
        log_message("Failed to open log file: %s", strerror(errno));
        return EXIT_FAILURE;
    }

    state.i2c_fd = init_i2c();
    if (state.i2c_fd < 0) {
        log_message("I2C initialization failed.");
        fclose(state.log_file);
        return EXIT_FAILURE;
    }

    if (init_gpio() < 0) {
        log_message("GPIO initialization failed.");
        cleanup(&state);
        return EXIT_FAILURE;
    }

    state.relay_state = 0;
    toggle_relay(0, state.relay_state);

    state.running = 1;
    while (state.running) {
        int lux = read_lux(state.i2c_fd);
        if (lux < 0) {
            log_message("Sensor read failed, continuing...");
            usleep(100000);  // 100 ms
            continue;
        }

        log_message("Lux: %d", lux);

        if (lux < LUX_THRESHOLD) {
            if (state.relay_state == 0) {
                state.relay_state = 1;
                toggle_relay(0, state.relay_state);
                log_message("Relay turned ON");
            }
        } else {
            if (state.relay_state == 1) {
                state.relay_state = 0;
                toggle_relay(0, state.relay_state);
                log_message("Relay turned OFF");
            }
        }

        usleep(100000);  // 100 ms
    }

    cleanup(&state);
    return EXIT_SUCCESS;
}
