// Function to handle signal interrupts
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    state = STATE_IDLE;
    // Cleanup resources here if needed
    exit(EXIT_SUCCESS);
}

// Function to debounce a button press
int debounce_gpio(int gpio_fd, int pin) {
    int value;
    int count = 0;

    while (count < 10) {
        value = gpiod_line_get_value(gpio_fd, pin);
        if (value == 0) {
            usleep(DEBOUNCE_DELAY_MS * 1000);
            value = gpiod_line_get_value(gpio_fd, pin);
            if (value == 0) {
                return 1;
            }
        }
        usleep(10000); // 10ms delay
        count++;
    }
    return 0;
}

// Function to set servo pulse width
void set_servo_pulse_width(int pwm_fd, int pulse_us) {
    if (pulse_us < SERVO_MIN_US || pulse_us > SERVO_MAX_US) {
        fprintf(stderr, "Error: Pulse width out of safe range.\n");
        return;
    }

    // Calculate duty cycle
    double duty_cycle = (double)pulse_us / (double)SERVO_PULSE_US;
    int duty = (int)(duty_cycle * 1000000); // Convert to microsecond-based duty cycle

    // Set the duty cycle
    if (ioctl(pwm_fd, PWM_SET_DUTY, duty) < 0) {
        perror("ioctl(PWM_SET_DUTY)");
        exit(EXIT_FAILURE);
    }
}

