    config.direction = GPIOD_LINE_DIRECTION_OUTPUT;
    config.flags = GPIOD_LINE_REQUEST_FLAG_ACTIVE_LOW;
    config.edge = GPIOD_LINE_EDGE_NONE;
    config.output = GPIOD_LINE_OUTPUT_ACTIVE_LOW;

