#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_MOTOR1_PIN 17  // BCM pin 17
#define GPIO_MOTOR2_PIN 27  // BCM pin 27

typedef struct {
    struct gpiod_line *motor1_line;
    struct gpiod_line *motor2_line;
    int running;
} motor_state_t;

void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        printf("\nCaught signal %d, shutting down...\n", signum);
        motor_state_t *state = (motor_state_t *)malloc(sizeof(motor_state_t));
        state->running = 0;
        // Free resources and exit
        exit(EXIT_SUCCESS);
    }
}

void init_gpio(motor_state_t *state) {
    struct gpiod_chip *chip;
    struct gpiod_line *line;

    // Open the GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    // Configure GPIO17 (BCM 17) for output
    line = gpiod_line_request_output(chip, "motor1", GPIO_MOTOR1_PIN, 0);
    if (!line) {
        perror("Failed to request GPIO17 line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }
    state->motor1_line = line;

    // Configure GPIO27 (BCM 27) for output
    line = gpiod_line_request_output(chip, "motor2", GPIO_MOTOR2_PIN, 0);
    if (!line) {
        perror("Failed to request GPIO27 line");
        gpiod_line_release(state->motor1_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }
    state->motor2_line = line;
}

void release_gpio(motor_state_t *state) {
    if (state->motor1_line) {
        gpiod_line_release(state->motor1_line);
    }
    if (state->motor2_line) {
        gpiod_line_release(state->motor2_line);
    }
}

void set_motor(int motor_num, int value, motor_state_t *state) {
    struct gpiod_line *line = NULL;
    int ret;

    switch (motor_num) {
        case 1:
            line = state->motor1_line;
            break;
        case 2:
            line = state->motor2_line;
            break;
        default:
            fprintf(stderr, "Invalid motor number\n");
            return;
    }

    ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        perror("Failed to set GPIO value");
    }
}

void motor_sequence(motor_state_t *state) {
    // Motor 1 on for 200ms
    set_motor(1, 1, state);
    usleep(200000);
    set_motor(1, 0, state);

    // Motor 2 on for 300ms
    set_motor(2, 1, state);
    usleep(300000);
    set_motor(2, 0, state);
}

int main() {
    motor_state_t state;
    struct sigaction sa;

    // Initialize signal handling
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("Failed to set SIGINT handler");
        exit(EXIT_FAILURE);
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("Failed to set SIGTERM handler");
        exit(EXIT_FAILURE);
    }

    // Initialize GPIO
    init_gpio(&state);

    // Main loop
    state.running = 1;
    while (state.running) {
        motor_sequence(&state);
    }

    // Clean up
    release_gpio(&state);

    return 0;
}

