        case 1:
            line = state->motor1_line;
            break;
        case 2:
            line = state->motor2_line;
            break;
        default:
            fprintf(stderr, "Invalid motor number\n");
            return;
    }

    ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        perror("Failed to set GPIO value");
    }
}

void motor_sequence(motor_state_t *state) {
    // Motor 1 on for 200ms
    set_motor(1, 1, state);
    usleep(200000);
    set_motor(1, 0, state);

    // Motor 2 on for 300ms
    set_motor(2, 1, state);
    usleep(300000);
    set_motor(2, 0, state);
}

int main() {
    motor_state_t state;
    struct sigaction sa;

    // Initialize signal handling
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("Failed to set SIGINT handler");
        exit(EXIT_FAILURE);
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("Failed to set SIGTERM handler");
        exit(EXIT_FAILURE);
    }

    // Initialize GPIO
    init_gpio(&state);

    // Main loop
    state.running = 1;
    while (state.running) {
        motor_sequence(&state);
    }

    // Clean up
    release_gpio(&state);

    return 0;
}
