int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s [sound_sensor|alarm_node]\n", argv[0]);
        return 1;
    }

    if (strcmp(argv[1], "sound_sensor") != 0 && strcmp(argv[1], "alarm_node") != 0) {
        fprintf(stderr, "Invalid mode. Use 'sound_sensor' or 'alarm_node'.\n");
        return 1;
    }

    Mode mode = (strcmp(argv[1], "sound_sensor") == 0) ? MODE_SOUND_SENSOR : MODE_ALARM_NODE;

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    int gpio_fd = open(GPIO_CHIP, O_RDWR);
    if (gpio_fd < 0) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    if (ioctl(gpio_fd, GPIO_GET_CHIPINFO, 0) < 0) {
        perror("Failed to get chip info");
        close(gpio_fd);
        return 1;
    }

    int sound_pin = GPIO_SOUND_PIN;
    int alarm_pin = GPIO_ALARM_PIN;

    if (gpio_line_request_output(gpio_fd, sound_pin, GPIO_LINE_FLAG_ACTIVE_LOW) < 0) {
        perror("Failed to request sound pin");
        cleanup_gpio(gpio_fd, sound_pin, alarm_pin);
        return 1;
    }

    if (gpio_line_request_output(gpio_fd, alarm_pin, GPIO_LINE_FLAG_ACTIVE_LOW) < 0) {
        perror("Failed to request alarm pin");
        cleanup_gpio(gpio_fd, sound_pin, alarm_pin);
        return 1;
    }

    if (gpio_line_set_value(gpio_fd, sound_pin, 1) < 0) {
        perror("Failed to set sound pin high");
        cleanup_gpio(gpio_fd, sound_pin, alarm_pin);
        return 1;
    }

    if (gpio_line_set_value(gpio_fd, alarm_pin, 1) < 0) {
        perror("Failed to set alarm pin high");
        cleanup_gpio(gpio_fd, sound_pin, alarm_pin);
        return 1;
    }

    void *context = zmq_ctx_new();
    void *socket = NULL;

    if (mode == MODE_SOUND_SENSOR) {
        socket = zmq_socket(context, ZMQ_PUB);
        if (!socket) {
            perror("Failed to create ZeroMQ PUB socket");
            cleanup_zmq(context, socket);
            cleanup_gpio(gpio_fd, sound_pin, alarm_pin);
            return 1;
        }

        if (zmq_bind(socket, "tcp://*:5555") < 0) {
            perror("Failed to bind ZeroMQ socket");
            cleanup_zmq(context, socket);
            cleanup_gpio(gpio_fd, sound_pin, alarm_pin);
            return 1;
        }

        char message[64];
        while (running) {
            usleep(10000); // 10 ms

            int value;
            if (gpio_line_get_value(gpio_fd, sound_pin, &value) < 0) {
                perror("Failed to read sound pin");
                cleanup_zmq(context, socket);
                cleanup_gpio(gpio_fd, sound_pin, alarm_pin);
                return 1;
            }

            if (value == 0) {
                snprintf(message, sizeof(message), "%s", ZMQ_TOPIC);
                if (zmq_send(socket, message, strlen(message), 0) < 0) {
                    perror("Failed to send ZeroMQ message");
                    cleanup_zmq(context, socket);
                    cleanup_gpio(gpio_fd, sound_pin, alarm_pin);
                    return 1;
                }
            }
        }
    } else { // MODE_ALARM_NODE
        socket = zmq_socket(context, ZMQ_SUB);
        if (!socket) {
            perror("Failed to create ZeroMQ SUB socket");
            cleanup_zmq(context, socket);
            cleanup_gpio(gpio_fd, sound_pin, alarm_pin);
            return 1;
        }

        if (zmq_setsockopt(socket, ZMQ_SUBSCRIBE, ZMQ_TOPIC, strlen(ZMQ_TOPIC)) < 0) {
            perror("Failed to set subscription");
            cleanup_zmq(context, socket);
            cleanup_gpio(gpio_fd, sound_pin, alarm_pin);
            return 1;
        }

        if (zmq_connect(socket, "tcp://localhost:5555") < 0) {
            perror("Failed to connect ZeroMQ socket");
            cleanup_zmq(context, socket);
            cleanup_gpio(gpio_fd, sound_pin, alarm_pin);
            return 1;
        }

        while (running) {
            zmq_msg_t msg;
            zmq_msg_init(&msg);
            if (zmq_msg_recv(&msg, socket, 0) < 0) {
                perror("Failed to receive ZeroMQ message");
                cleanup_zmq(context, socket);
                cleanup_gpio(gpio_fd, sound_pin, alarm_pin);
                return 1;
            }

            char *topic = (char *)zmq_msg_data(&msg);
            if (strcmp(topic, ZMQ_TOPIC) == 0) {
                if (gpio_line_set_value(gpio_fd, alarm_pin, 0) < 0) {
                    perror("Failed to set alarm pin low");
                    cleanup_zmq(context, socket);
                    cleanup_gpio(gpio_fd, sound_pin, alarm_pin);
                    return 1;
                }

                usleep(ALARM_DURATION_MS * 1000);
                if (gpio_line_set_value(gpio_fd, alarm_pin, 1) < 0) {
                    perror("Failed to set alarm pin high");
                    cleanup_zmq(context, socket);
                    cleanup_gpio(gpio_fd, sound_pin, alarm_pin);
                    return 1;
                }
            }

            zmq_msg_close(&msg);
        }
    }

    cleanup_zmq(context, socket);
    cleanup_gpio(gpio_fd, sound_pin, alarm_pin);
    return 0;
