#define GPIO_PIN 17
#define GPIO_LINE "gpio17"
#define MQTT_BROKER "localhost"
#define MQTT_PORT 1883
#define MQTT_TOPIC "ir/decoded"
#define NEC_HEADER_MARK 9000
#define NEC_HEADER_SPACE 4500
#define NEC_BIT_MARK 560
#define NEC_ONE_SPACE 1690
#define NEC_ZERO_SPACE 560
#define NEC_BIT_COUNT 32
#define NEC_CHECKSUM_BIT 31
#define NEC_MAX_PULSE_BUFFER 1024

typedef struct {
    int *pulse_buffer;
    int buffer_size;
    int buffer_index;
    int state;
    int last_edge;
    int data;
    int address;
    int command;
    int checksum;
    int valid;
} ir_decoder_t;

void signal_handler(int signum) {
    syslog(LOG_NOTICE, "Received signal %d, exiting...", signum);
    exit(EXIT_SUCCESS);
}

void init_gpio(gpiod_line *line) {
    gpiod_line *line = gpiod_line_find(GPIO_LINE, GPIOD_LINE_DIRECTION_INPUT);
    if (!line) {
        syslog(LOG_ERR, "Failed to find GPIO line %s", GPIO_LINE);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_input(line, "ir_decoder", GPIOD_LINE_FLAG_ACTIVE_LOW) < 0) {
        syslog(LOG_ERR, "Failed to request GPIO line %s", GPIO_LINE);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_set_edge_detection(line, GPIOD_LINE_EDGE_BOTH) < 0) {
        syslog(LOG_ERR, "Failed to set edge detection on GPIO line %s", GPIO_LINE);
        exit(EXIT_FAILURE);
    }
}

void init_mqtt(mosquitto *mosq) {
    int rc = mosquitto_init(&mosq, NULL, NULL);
    if (rc != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "Failed to initialize MQTT client");
        exit(EXIT_FAILURE);
    }

    rc = mosquitto_connect(mosq, MQTT_BROKER, MQTT_PORT, 60);
    if (rc != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "Failed to connect to MQTT broker");
        mosquitto_destroy(mosq);
        exit(EXIT_FAILURE);
