    rc = mosquitto_subscribe(mosq, NULL, MQTT_TOPIC, 0);
    if (rc != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "Failed to subscribe to MQTT topic");
        mosquitto_destroy(mosq);
        exit(EXIT_FAILURE);
    }
}

void cleanup_gpio(gpiod_line *line) {
