        gpiod_line_release(line);
    }
}

void cleanup_mqtt(mosquitto *mosq) {
    if (mosq) {
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
    }
}

void cleanup_syslog() {
    closelog();
}

void decode_nec(ir_decoder_t *decoder, int pulse) {
    static int pulse_count = 0;
    static int pulse_index = 0;
    static int pulse_time = 0;
    static int last_pulse = 0;
    static int state = 0;

    if (pulse_count >= NEC_MAX_PULSE_BUFFER) {
        syslog(LOG_ERR, "Pulse buffer overflow");
        return;
    }

    if (state == 0) {
        if (pulse > NEC_HEADER_MARK) {
            state = 1;
            pulse_count = 0;
            pulse_index = 0;
            pulse_time = 0;
            last_pulse = 0;
        }
    } else if (state == 1) {
        if (pulse > NEC_HEADER_SPACE) {
            state = 2;
            pulse_count = 0;
            pulse_index = 0;
            pulse_time = 0;
            last_pulse = 0;
        }
    } else if (state == 2) {
        if (pulse > NEC_BIT_MARK) {
            if (pulse_index < NEC_BIT_COUNT) {
                if (pulse - last_pulse > NEC_ONE_SPACE) {
                    decoder->data |= (1 << (NEC_BIT_COUNT - 1 - pulse_index));
                }
                pulse_index++;
                last_pulse = pulse;
            } else {
                state = 0;
            }
        }
    }
}

void alert_callback(gpiod_line *line, unsigned int flags, void *data) {
    ir_decoder_t *decoder = (ir_decoder_t *)data;
    int pulse = gpiod_line_get_value(line);
    int current_time = gpiod_line_get_timestamp(line);

    if (pulse == 0) {
        if (decoder->state == 0) {
            decoder->state = 1;
            decoder->buffer_index = 0;
            decoder->buffer_size = 0;
            decoder->last_edge = current_time;
        } else {
            int duration = current_time - decoder->last_edge;
            decoder->pulse_buffer[decoder->buffer_size++] = duration;
            decoder->last_edge = current_time;
        }
    } else {
        if (decoder->state == 1) {
            int duration = current_time - decoder->last_edge;
            if (duration > NEC_HEADER_MARK) {
                decoder->state = 2;
                decoder->buffer_index = 0;
                decoder->buffer_size = 0;
                decoder->last_edge = current_time;
            }
        } else if (decoder->state == 2) {
            int duration = current_time - decoder->last_edge;
            if (duration > NEC_BIT_MARK) {
                if (decoder->buffer_size < NEC_MAX_PULSE_BUFFER) {
                    decoder->pulse_buffer[decoder->buffer_size++] = duration;
                    decoder->last_edge = current_time;
                }
            }
        }
    }

    if (decoder->buffer_size >= NEC_BIT_COUNT + 2) {
        int header = decoder->pulse_buffer[0];
        int header_space = decoder->pulse_buffer[1];
        int bit_count = decoder->buffer_size - 2;

        if (header >= NEC_HEADER_MARK - 100 && header <= NEC_HEADER_MARK + 100 &&
            header_space >= NEC_HEADER_SPACE - 100 && header_space <= NEC_HEADER_SPACE + 100) {
            int address = 0;
            int command = 0;
            int checksum = 0;
            int valid = 1;

            for (int i = 2; i < bit_count; i++) {
                int bit_time = decoder->pulse_buffer[i];
                if (bit_time > NEC_ONE_SPACE) {
                    address |= (1 << (NEC_BIT_COUNT - 1 - (i - 2)));
                } else {
                    command |= (1 << (NEC_BIT_COUNT - 1 - (i - 2)));
                }
            }

            checksum = (address ^ command) >> 1;
            if (checksum != decoder->pulse_buffer[bit_count - 1]) {
                valid = 0;
            }

            if (valid) {
                decoder->address = address;
                decoder->command = command;
                decoder->checksum = checksum;
                decoder->valid = 1;
            } else {
                decoder->valid = 0;
            }

            if (decoder->valid) {
                char json[256];
                snprintf(json, sizeof(json), "{\"address\":%d,\"command\":%d,\"checksum\":%d}", decoder->address, decoder->command, decoder->checksum);
                syslog(LOG_NOTICE, "Decoded IR command: %s", json);

                mosquitto_message_t msg;
                msg.topic = MQTT_TOPIC;
                msg.payload = json;
                msg.payload_len = strlen(json);
                msg.qos = 0;
                msg.retained = false;

                int rc = mosquitto_publish(mosq, NULL, msg.topic, msg.payload_len, msg.payload, 0, false);
                if (rc != MOSQ_ERR_SUCCESS) {
                    syslog(LOG_ERR, "MQTT publish failed: %s", mosquitto_strerror(rc));
                }
            }
        }
    }
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    syslog(LOG_NOTICE, "Starting IR decoder service");

    gpiod_line *line = NULL;
    ir_decoder_t decoder;
    decoder.pulse_buffer = (int *)malloc(NEC_MAX_PULSE_BUFFER * sizeof(int));
    decoder.buffer_size = 0;
    decoder.buffer_index = 0;
    decoder.state = 0;
    decoder.last_edge = 0;
    decoder.data = 0;
    decoder.address = 0;
    decoder.command = 0;
    decoder.checksum = 0;
    decoder.valid = 0;

    init_gpio(line);
    init_mqtt(mosq);

    gpiod_line_set_callback(line, alert_callback, &decoder);

    while (1) {
        mosquitto_loop(mosq, -1, 1);
        usleep(1000);
    }

    cleanup_gpio(line);
    cleanup_mqtt(mosq);
    cleanup_syslog();

    free(decoder.pulse_buffer);
    syslog(LOG_NOTICE, "IR decoder service exited");
    return 0;
}
