#include <arpa/inet.h>
#include <signal.h>
#include <errno.h>
#include <math.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDR1 0x23
#define I2C_ADDR2 0x24
#define I2C_ADDR3 0x25
#define I2C_ADDR4 0x26
#define I2C_COMMAND_START_CONVERSION 0x40
#define I2C_COMMAND_READ_DATA 0x41
#define I2C_DELAY_MS 180
#define MULTICAST_IP "239.255.255.250"
#define MULTICAST_PORT 5005
#define SENSOR_COUNT 4
#define MAX_BUFFER_SIZE 256
#define NAN_VALUE 0.0f

typedef struct {
    int fd;
    int address;
} I2C_SENSOR;

typedef struct {
    int socket_fd;
    struct sockaddr_in multicast_addr;
} UDP_SOCKET;

volatile sig_atomic_t terminate_flag = 0;

void handle_signal(int signo) {
    terminate_flag = 1;
}

float read_bh1750(int fd, int address) {
    float lux = NAN;

    if (ioctl(fd, I2C_SLAVE, address) < 0) {
        perror("ioctl(I2C_SLAVE)");
        return NAN;
    }

    unsigned char cmd = I2C_COMMAND_START_CONVERSION;
    if (write(fd, &cmd, 1) < 0) {
        perror("write to I2C");
        return NAN;
    }

    usleep(I2C_DELAY_MS * 1000);

    unsigned char buffer[2];
    if (read(fd, buffer, 2) < 2) {
        perror("read from I2C");
        return NAN;
    }

    int msb = buffer[0];
    int lsb = buffer[1];
    int data = (msb << 8) | lsb;

    if (data == 0xFFFF) {
        return NAN;
    }

    lux = (float)data / 1.2f;

    return lux;
}

void setup_udp_socket(UDP_SOCKET *socket) {
    socket->socket_fd = socket(AF_INET, SOCK_DGRAM, 0);
    if (socket->socket_fd < 0) {
        perror("socket");
        exit(EXIT_FAILURE);
    }

    memset(&socket->multicast_addr, 0, sizeof(socket->multicast_addr));
    socket->multicast_addr.sin_family = AF_INET;
    socket->multicast_addr.sin_port = htons(MULTICAST_PORT);
    inet_pton(AF_INET, MULTICAST_IP, &socket->multicast_addr.sin_addr);

    int reuse = 1;
    if (setsockopt(socket->socket_fd, SOL_SOCKET, SO_REUSEADDR, &reuse, sizeof(reuse)) < 0) {
        perror("setsockopt");
        close(socket->socket_fd);
        exit(EXIT_FAILURE);
    }

    if (setsockopt(socket->socket_fd, IPPROTO_IP, IP_MULTICAST_TTL, &reuse, sizeof(reuse)) < 0) {
        perror("setsockopt IP_MULTICAST_TTL");
        close(socket->socket_fd);
        exit(EXIT_FAILURE);
    }

    if (setsockopt(socket->socket_fd, IPPROTO_IP, IP_MULTICAST_LOOP, &reuse, sizeof(reuse)) < 0) {
        perror("setsockopt IP_MULTICAST_LOOP");
        close(socket->socket_fd);
        exit(EXIT_FAILURE);
    }
}

void close_udp_socket(UDP_SOCKET *socket) {
    if (socket->socket_fd >= 0) {
        close(socket->socket_fd);
    }
}

void setup_i2c_sensors(I2C_SENSOR sensors[SENSOR_COUNT]) {
    int i2c_fd = open(I2C_BUS, O_RDWR | O_CLOEXEC);
    if (i2c_fd < 0) {
        perror("open I2C bus");
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < SENSOR_COUNT; i++) {
        sensors[i].fd = i2c_fd;
        sensors[i].address = (i == 0) ? I2C_ADDR1 :
                            (i == 1) ? I2C_ADDR2 :
                            (i == 2) ? I2C_ADDR3 :
                            I2C_ADDR4;
    }
}

void close_i2c_sensors(I2C_SENSOR sensors[SENSOR_COUNT]) {
    for (int i = 0; i < SENSOR_COUNT; i++) {
        if (sensors[i].fd >= 0) {
            close(sensors[i].fd);
        }
    }
}

void send_multicast_packet(UDP_SOCKET *socket, float lux_values[SENSOR_COUNT]) {
    char buffer[MAX_BUFFER_SIZE];
    char *ptr = buffer;
    char *end = buffer + MAX_BUFFER_SIZE;

    for (int i = 0; i < SENSOR_COUNT; i++) {
        if (i > 0) {
            ptr += snprintf(ptr, end - ptr, ";");
        }
        ptr += snprintf(ptr, end - ptr, "%d,%f", i + 1, lux_values[i]);
    }

    if (sendto(socket->socket_fd, buffer, ptr - buffer, 0,
               (struct sockaddr *)&socket->multicast_addr, sizeof(socket->multicast_addr)) < 0) {
        perror("sendto");
    }
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    I2C_SENSOR sensors[SENSOR_COUNT];
    setup_i2c_sensors(sensors);

    UDP_SOCKET udp_socket;
    setup_udp_socket(&udp_socket);

    float lux_values[SENSOR_COUNT] = {NAN, NAN, NAN, NAN};

    while (!terminate_flag) {
        for (int i = 0; i < SENSOR_COUNT; i++) {
            lux_values[i] = read_bh1750(sensors[i].fd, sensors[i].address);
        }

        send_multicast_packet(&udp_socket, lux_values);

        usleep(1000000); // 1 second
    }

    close_i2c_sensors(sensors);
    close_udp_socket(&udp_socket);

    return 0;
}

