    ERROR_I2C_WRITE,
    ERROR_I2C_READ,
    ERROR_I2C_ENXIO,
    ERROR_I2C_EIO
} error_t;

int i2c_fd = -1;
FILE *log_file = NULL;
volatile int running = 1;

void handle_sigint(int sig) {
    running = 0;
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (log_file) {
        fflush(log_file);
        fclose(log_file);
    }
    exit(EXIT_SUCCESS);
}

void log_error(const char *message, error_t error) {
    fprintf(stderr, "Error: %s\n", message);
    switch (error) {
        case ERROR_I2C_INIT:
            fprintf(stderr, "Failed to open I2C bus.\n");
            break;
        case ERROR_I2C_WRITE:
            fprintf(stderr, "I2C write failed.\n");
            break;
        case ERROR_I2C_READ:
            fprintf(stderr, "I2C read failed.\n");
            break;
        case ERROR_I2C_ENXIO:
            fprintf(stderr, "I2C device not found (ENXIO).\n");
            break;
        case ERROR_I2C_EIO:
            fprintf(stderr, "I2C bus error (EIO).\n");
            break;
    }
}

void i2c_init() {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        log_error("Failed to open I2C bus", ERROR_I2C_INIT);
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, AWM7300V_ADDR) < 0) {
        log_error("Failed to set I2C slave address", ERROR_I2C_INIT);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
}

void i2c_write() {
    uint8_t buffer[1] = {0};
    if (write(i2c_fd, buffer, 1) < 0) {
        log_error("I2C write failed", ERROR_I2C_WRITE);
        exit(EXIT_FAILURE);
    }
}

void i2c_read(uint8_t *buffer, size_t len) {
    int retries = 0;
    int result;
    do {
        result = read(i2c_fd, buffer, len);
        if (result < 0) {
            if (errno == ENXIO) {
                log_error("I2C device not found (ENXIO)", ERROR_I2C_ENXIO);
                exit(EXIT_FAILURE);
            } else if (errno == EIO) {
                log_error("I2C bus error (EIO)", ERROR_I2C_EIO);
                exit(EXIT_FAILURE);
            } else {
                log_error("I2C read failed", ERROR_I2C_READ);
                sleep(1);
                retries++;
                if (retries >= MAX_RETRIES) {
                    exit(EXIT_FAILURE);
                }
            }
        } else {
            break;
        }
    } while (retries < MAX_RETRIES);
}

