    fprintf(log_file, "%s,%.2f\n", timestamp, flow_rate);
    fflush(log_file);
}

void calculate_flow_rate(uint16_t raw_value) {
    // AWM7300V: 14-bit value, 1 LSB = 0.001 SLPM
    double flow_rate = (double)raw_value * 0.001;
    log_flow_rate(flow_rate);
}

