        calculate_flow_rate(raw_value);
        sleep(1);
    }

    if (log_file) {
        fflush(log_file);
        fclose(log_file);
    }

    if (i2c_fd >= 0) {
        close(i2c_fd);
    }

    return EXIT_SUCCESS;
}
