void handle_signal(int sig) {
    app_state *state = (app_state *)malloc(sizeof(app_state));
    state->running = 0;
    free(state);
}

void i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buffer[2];
    buffer[0] = reg;
    buffer[1] = value;
    if (write(fd, buffer, 2) != 2) {
        perror("I2C write failed");
        exit(EXIT_FAILURE);
    }
}

uint8_t i2c_read_byte(int fd, uint8_t reg) {
    uint8_t buffer[1];
    buffer[0] = reg;
    if (write(fd, buffer, 1) != 1) {
        perror("I2C write failed");
        exit(EXIT_FAILURE);
    }
    if (read(fd, buffer, 1) != 1) {
        perror("I2C read failed");
        exit(EXIT_FAILURE);
    }
    return buffer[0];
}

void configure_as7341(int fd) {
    uint8_t id = i2c_read_byte(fd, AS7341_ID_REGISTER);
    if (id != AS7341_ID_VALUE) {
        fprintf(stderr, "AS7341 not found or invalid ID: 0x%02X\n", id);
        exit(EXIT_FAILURE);
    }

    i2c_write_byte(fd, AS7341_ENABLE_REGISTER, AS7341_PON_BIT);

