        perror("Failed to set I2C slave address");
        close(state->fd);
        exit(EXIT_FAILURE);
    }

    configure_as7341(state->fd);

    state->log_file = fopen(LOG_FILE, "a");
    if (!state->log_file) {
        perror("Failed to open log file");
        close(state->fd);
        exit(EXIT_FAILURE);
    }

    fprintf(state->log_file, "Timestamp,F1,F2,F3,F4,F5,F6,F7,F8,Clear,NIR,Lux\n");
    fflush(state->log_file);
}

void cleanup_app(app_state *state) {
    if (state->log_file) {
        fclose(state->log_file);
    }
    if (state->fd >= 0) {
        close(state->fd);
    }
}

int main() {
    app_state state;
    init_app(&state);

    signal(SIGINT, handle_signal);

    while (state.running) {
        uint16_t spectral_data[MAX_CHANNELS];
        read_spectral_data(state.fd, spectral_data);
        float lux;
        compute_lux_approximation(spectral_data, &lux);
        log_data(state.log_file, spectral_data, lux);
        sleep(LOG_INTERVAL);
    }

    cleanup_app(&state);
    return 0;
}

