    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(state->error_file, "%s: %s\n", timestamp, message);
    fflush(state->error_file);
}

void close_resources(app_state *state) {
    if (state->fd >= 0) {
        close(state->fd);
    }
    if (state->csv_file) {
        fclose(state->csv_file);
    }
    if (state->error_file) {
        fclose(state->error_file);
    }
}

void init_i2c(app_state *state) {
    state->fd = open(I2C_BUS, O_RDWR);
    if (state->fd < 0) {
        log_error("Failed to open I2C bus", state);
        exit(EXIT_FAILURE);
    }

    if (ioctl(state->fd, I2C_SLAVE, state->i2c_addr) < 0) {
        log_error("Failed to set I2C slave address", state);
        close(state->fd);
        exit(EXIT_FAILURE);
    }
}

void write_register(app_state *state, uint8_t reg, uint8_t value) {
    uint8_t buffer[2];
    buffer[0] = reg;
    buffer[1] = value;
    int retries = 0;
    while (retries < MAX_RETRIES) {
        if (write(state->fd, buffer, 2) == 2) {
            return;
        }
        log_error("I2C write failed", state);
        usleep(BACKOFF_MS * 1000);
        retries++;
    }
    log_error("I2C write failed after retries", state);
    exit(EXIT_FAILURE);
}

void read_data(app_state *state, uint8_t reg, uint8_t *buffer, size_t len) {
    int retries = 0;
    while (retries < MAX_RETRIES) {
        if (write(state->fd, &reg, 1) == 1) {
            if (read(state->fd, buffer, len) == len) {
                return;
            }
        }
        log_error("I2C read failed", state);
        usleep(BACKOFF_MS * 1000);
        retries++;
    }
    log_error("I2C read failed after retries", state);
    exit(EXIT_FAILURE);
}

void setup_csv(app_state *state) {
    state->csv_file = fopen(state->output_file, "a");
    if (!state->csv_file) {
        log_error("Failed to open CSV file", state);
        exit(EXIT_FAILURE);
    }
    fprintf(state->csv_file, "timestamp,x_g,y_g,z_g\n");
    fflush(state->csv_file);
}

void setup_error_log(app_state *state) {
    state->error_file = fopen(state->error_file_path, "a");
    if (!state->error_file) {
        log_error("Failed to open error log file", state);
        exit(EXIT_FAILURE);
    }
}

void log_data(app_state *state, int16_t x, int16_t y, int16_t z) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(state->csv_file, "%s,%d,%d,%d\n", timestamp, x, y, z);
    fflush(state->csv_file);
}

int main(int argc, char *argv[]) {
    app_state state = {0};

    // Parse command-line arguments
    int opt;
    while ((opt = getopt(argc, argv, "a:i:f:")) != -1) {
        switch (opt) {
            case 'a':
                state.i2c_addr = strtol(optarg, NULL, 16);
                break;
            case 'i':
                state.interval = strtol(optarg, NULL, 10);
                break;
            case 'f':
                state.output_file = strdup(optarg);
                break;
        }
    }

    // Set default values
    if (state.i2c_addr == 0) {
        state.i2c_addr = DEFAULT_I2C_ADDR;
    }
    if (state.interval == 0) {
        state.interval = DEFAULT_INTERVAL;
    }
    if (state.output_file == NULL) {
        state.output_file = strdup(DEFAULT_OUTPUT_FILE);
    }

    // Extract error log file path from output file
    char *error_log_dir = dirname(strdup(state.output_file));
    char *error_log_base = basename(state.output_file);
    char *error_log_ext = strrchr(error_log_base, '.');
    if (error_log_ext) {
        *error_log_ext = '\0';
    }
    char *error_log_name = strdup(strcat(strcat(strdup(error_log_dir), "/"), error_log_base));
    strcat(error_log_name, "_error.log");
    state.error_file_path = error_log_name;

    // Initialize signal handling
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Initialize resources
    init_i2c(&state);
    setup_csv(&state);
    setup_error_log(&state);

    // Write initial calibration or setup if needed
    // Example: write_register(&state, 0x01, 0x01); // Set to 1g range

    // Main loop
    state.running = 1;
    while (state.running) {
        // Read data from sensor
        uint8_t buffer[6];
        read_data(&state, 0x00, buffer, 6);

        int16_t x = (int16_t)(buffer[0] << 8 | buffer[1]);
        int16_t y = (int16_t)(buffer[2] << 8 | buffer[3]);
        int16_t z = (int16_t)(buffer[4] << 8 | buffer[5]);

        log_data(&state, x, y, z);

        // Sleep for interval
        usleep(state.interval * 1000000);
    }

    // Cleanup
    close_resources(&state);

    return 0;
}
