        return -1;
    }
    return 0;
}

int i2c_read(int fd, uint8_t reg, uint16_t *value) {
    uint8_t buffer[2];
    buffer[0] = reg;
    if (ioctl(fd, I2C_RDWR, &buffer) < 0) {
        perror("I2C write failed");
        return -1;
    }
    *value = (buffer[0] << 8) | buffer[1];
    return 0;
}

float convert_to_lux(uint16_t raw_value) {
    float lux = 0.0;
    if (raw_value == 0) {
        return 0.0;
    }
    if (raw_value < 1000) {
        lux = (float)raw_value * 0.01;
    } else if (raw_value < 2000) {
        lux = (float)raw_value * 0.02;
    } else if (raw_value < 3000) {
        lux = (float)raw_value * 0.03;
    } else if (raw_value < 4000) {
        lux = (float)raw_value * 0.04;
