#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <errno.h>
#include <signal.h>
#include <sys/select.h>
#include <sys/time.h>
#include <time.h>
#include <termios.h>

#define UART_DEVICE "/dev/serial0"
#define BAUD_RATE B115200
#define UART_FLAGS (0)
#define UART_BUFFER_SIZE 1024
#define LINE_BUFFER_SIZE 1024
#define SELECT_TIMEOUT_SECONDS 2
#define INTER_BYTE_TIMEOUT_SECONDS 0.5
#define MAX_LINE_LENGTH 1024

typedef struct {
    int uart_fd;
    struct termios orig_termios;
    char line_buffer[LINE_BUFFER_SIZE];
    size_t line_buffer_len;
    int running;
} app_state;

void handle_signal(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        app_state *state = (app_state *)malloc(sizeof(app_state));
        if (state) {
            state->running = 0;
            free(state);
        }
    }
}

void close_uart(app_state *state) {
    if (state->uart_fd >= 0) {
        tcsetattr(state->uart_fd, TCSAFLUSH, &state->orig_termios);
        close(state->uart_fd);
        state->uart_fd = -1;
    }
}

void setup_uart(app_state *state) {
    state->uart_fd = open(UART_DEVICE, O_RDWR | O_NOCTTY | O_NDELAY);
    if (state->uart_fd < 0) {
        fprintf(stderr, "Failed to open UART device %s: %s\n", UART_DEVICE, strerror(errno));
        exit(EXIT_FAILURE);
    }

    struct termios tty;
    if (tcgetattr(state->uart_fd, &tty) != 0) {
        fprintf(stderr, "Failed to get terminal attributes: %s\n", strerror(errno));
        close_uart(state);
        exit(EXIT_FAILURE);
    }

    cfsetispeed(&tty, BAUD_RATE);
    cfsetospeed(&tty, BAUD_RATE);

    tty.c_cflag &= ~PARENB;        // No parity
    tty.c_cflag &= ~CSTOPB;        // 1 stop bit
    tty.c_cflag &= ~CSIZE;         // Clear data size mask
    tty.c_cflag |= CS8;            // 8 bits per byte
    tty.c_cflag &= ~CRTSCTS;       // No hardware flow control
    tty.c_cflag |= CREAD | CLOCAL; // Enable receiver, ignore modem control lines

    tty.c_lflag &= ~(ICANON | ECHO | ECHOE | ISIG); // Non-canonical mode
    tty.c_oflag &= ~OPOST; // Output processing off

    tty.c_cc[VMIN] = 0; // Minimum number of characters to read
    tty.c_cc[VTIME] = 0; // Wait time for input (in tenths of a second)

    if (tcsetattr(state->uart_fd, TCSAFLUSH, &tty) != 0) {
        fprintf(stderr, "Failed to set terminal attributes: %s\n", strerror(errno));
        close_uart(state);
        exit(EXIT_FAILURE);
    }

    state->orig_termios = tty;
}

void parse_line(app_state *state) {
    char *line = NULL;
    char *timestamp_str = NULL;
    char *range_str = NULL;
    char *token = NULL;
    char *endptr = NULL;
    double timestamp = 0.0;
    double range = 0.0;
    time_t t;
    struct tm *tm_info;

    line = strdup(state->line_buffer);
    if (!line) {
        fprintf(stderr, "Failed to duplicate line buffer: %s\n", strerror(errno));
        return;
    }

    token = strtok(line, ",");
    if (token && (timestamp_str = strdup(token))) {
        timestamp = strtod(timestamp_str, &endptr);
        if (endptr == token || *endptr != '\0') {
            fprintf(stderr, "Invalid timestamp format in line: %s\n", line);
            free(timestamp_str);
            free(line);
            return;
        }
        free(timestamp_str);
    } else {
        fprintf(stderr, "Invalid line format: %s\n", line);
        free(line);
        return;
    }

    token = strtok(NULL, "\n");
    if (token && (range_str = strdup(token))) {
        range = strtod(range_str, &endptr);
        if (endptr == token || *endptr != '\0') {
            fprintf(stderr, "Invalid range format in line: %s\n", line);
            free(range_str);
            free(line);
            return;
        }
        free(range_str);
    } else {
        fprintf(stderr, "Invalid line format: %s\n", line);
        free(line);
        return;
    }

    free(line);

    t = (time_t)timestamp;
    tm_info = localtime(&t);
    if (tm_info) {
        char timestamp_str[30];
        strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", tm_info);
        printf("Timestamp: %s, Range: %.2f meters\n", timestamp_str, range);
    } else {
        fprintf(stderr, "Failed to convert timestamp to local time: %s\n", strerror(errno));
    }
}

void read_uart(app_state *state) {
    fd_set read_fds;
    struct timeval timeout;
    int ret;

    FD_ZERO(&read_fds);
    FD_SET(state->uart_fd, &read_fds);

    timeout.tv_sec = SELECT_TIMEOUT_SECONDS;
    timeout.tv_usec = 0;

    ret = select(state->uart_fd + 1, &read_fds, NULL, NULL, &timeout);
    if (ret < 0) {
        fprintf(stderr, "select() failed: %s\n", strerror(errno));
        return;
    } else if (ret == 0) {
        fprintf(stderr, "Select timeout: No data received within %d seconds\n", SELECT_TIMEOUT_SECONDS);
        return;
    }

    if (FD_ISSET(state->uart_fd, &read_fds)) {
        char buffer[UART_BUFFER_SIZE];
        ssize_t bytes_read = read(state->uart_fd, buffer, sizeof(buffer) - 1);
        if (bytes_read < 0) {
            fprintf(stderr, "read() failed: %s\n", strerror(errno));
            return;
        } else if (bytes_read == 0) {
            fprintf(stderr, "No data received from UART\n");
            return;
        }

        buffer[bytes_read] = '\0';

        state->line_buffer_len += bytes_read;
        if (state->line_buffer_len >= LINE_BUFFER_SIZE) {
            fprintf(stderr, "Line buffer overflow, resetting buffer\n");
            state->line_buffer_len = 0;
        }

        char *newline_pos = memchr(state->line_buffer, '\n', state->line_buffer_len);
        if (newline_pos) {
            size_t line_len = newline_pos - state->line_buffer + 1;
            memcpy(state->line_buffer, state->line_buffer, line_len);
            state->line_buffer_len = line_len;
            parse_line(state);
            memmove(state->line_buffer, state->line_buffer + line_len, state->line_buffer_len);
            state->line_buffer_len -= line_len;
        } else {
            memcpy(state->line_buffer + state->line_buffer_len, buffer, bytes_read);
            state->line_buffer_len += bytes_read;
        }
    }
}

int main() {
    app_state state = {0};

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    setup_uart(&state);

    state.running = 1;
    while (state.running) {
        read_uart(&state);
        usleep(100000); // 100ms delay to prevent busy waiting
    }

    close_uart(&state);

    return 0;
}

