#define LOOP_DELAY_MS 100
#define MAX_RETRIES 5

typedef struct {
    struct gpiod_line *left_line;
    struct gpiod_line *middle_line;
    struct gpiod_line *right_line;
    int uart_fd;
    int running;
} sensor_state_t;

void cleanup(sensor_state_t *state) {
    if (state->running) {
        if (state->uart_fd >= 0) {
            close(state->uart_fd);
        }

        if (state->left_line) {
            gpiod_line_release(state->left_line);
        }
        if (state->middle_line) {
            gpiod_line_release(state->middle_line);
        }
        if (state->right_line) {
            gpiod_line_release(state->right_line);
        }
    }
}

void signal_handler(int signum) {
    static sensor_state_t *state = NULL;
    if (signum == SIGINT || signum == SIGTERM) {
        if (state) {
            state->running = 0;
        }
    }
}

void setup_gpio(sensor_state_t *state) {
    struct gpiod_chip *chip;
    struct gpiod_line_config config;

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        exit(1);
    }

    memset(&config, 0, sizeof(config));
    config.line = GPIO_LEFT_PIN;
    config.direction = GPIOD_LINE_DIRECTION_INPUT;
    config.flags = GPIOD_LINE_FLAG_ACTIVE_LOW | GPIOD_LINE_FLAG_BIAS_PULL_UP;
    state->left_line = gpiod_line_request(chip, "left_sensor", &config);
    if (!state->left_line) {
        fprintf(stderr, "Failed to request left GPIO line\n");
        gpiod_chip_close(chip);
        exit(1);
    }

    memset(&config, 0, sizeof(config));
    config.line = GPIO_MIDDLE_PIN;
    config.direction = GPIOD_LINE_DIRECTION_INPUT;
    config.flags = GPIOD_LINE_FLAG_ACTIVE_LOW | GPIOD_LINE_FLAG_BIAS_PULL_UP;
    state->middle_line = gpiod_line_request(chip, "middle_sensor", &config);
    if (!state->middle_line) {
        fprintf(stderr, "Failed to request middle GPIO line\n");
        gpiod_line_release(state->left_line);
        gpiod_chip_close(chip);
        exit(1);
    }

    memset(&config, 0, sizeof(config));
    config.line = GPIO_RIGHT_PIN;
    config.direction = GPIOD_LINE_DIRECTION_INPUT;
    config.flags = GPIOD_LINE_FLAG_ACTIVE_LOW | GPIOD_LINE_FLAG_BIAS_PULL_UP;
    state->right_line = gpiod_line_request(chip, "right_sensor", &config);
    if (!state->right_line) {
        fprintf(stderr, "Failed to request right GPIO line\n");
        gpiod_line_release(state->left_line);
        gpiod_line_release(state->middle_line);
        gpiod_chip_close(chip);
        exit(1);
    }

    gpiod_chip_close(chip);
}

void setup_uart(sensor_state_t *state) {
    state->uart_fd = open(UART_DEVICE, O_WRONLY | O_NOCTTY | O_NDELAY);
    if (state->uart_fd < 0) {
        fprintf(stderr, "Failed to open UART device: %s\n", strerror(errno));
        return;
    }

    struct termios tty;
    if (tcgetattr(state->uart_fd, &tty) != 0) {
        fprintf(stderr, "Failed to get UART attributes: %s\n", strerror(errno));
        close(state->uart_fd);
        state->uart_fd = -1;
        return;
    }

    cfsetispeed(&tty, B115200);
    cfsetospeed(&tty, B115200);
    tty.c_cflag &= ~PARENB; // No parity
    tty.c_cflag &= ~CSTOPB; // 1 stop bit
    tty.c_cflag &= ~CSIZE;
    tty.c_cflag |= CS8;     // 8 bits per byte
    tty.c_cflag |= CLOCAL;  // Local mode
    tty.c_cflag |= CREAD;   // Enable receiver
    tty.c_lflag &= ~(ICANON | ECHO | ECHOE | ISIG); // Non-canonical mode
    tty.c_oflag &= ~OPOST;

    if (tcsetattr(state->uart_fd, TCSAFLUSH, &tty) != 0) {
        fprintf(stderr, "Failed to set UART attributes: %s\n", strerror(errno));
        close(state->uart_fd);
        state->uart_fd = -1;
    }
}

void log_sensor_state(sensor_state_t *state) {
    time_t now;
    struct tm *timeinfo;
    char timestamp[20];

    time(&now);
    timeinfo = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    int left = gpiod_line_get_value(state->left_line);
    int middle = gpiod_line_get_value(state->middle_line);
    int right = gpiod_line_get_value(state->right_line);

    printf("%s: L=%d M=%d R=%d\n", timestamp, left, middle, right);

    if (left == 0 && middle == 0 && right == 0) {
        int retries = 0;
        while (retries < MAX_RETRIES) {
            ssize_t bytes_written = write(state->uart_fd, UART_DATA, strlen(UART_DATA));
            if (bytes_written == -1) {
                if (errno == EAGAIN || errno == EWOULDBLOCK) {
                    usleep(100000); // 100ms
                    retries++;
                    continue;
                } else {
                    fprintf(stderr, "UART write failed: %s\n", strerror(errno));
                    break;
                }
            } else {
                break;
            }
        }
    }
}

int main() {
    sensor_state_t state = {0};
    state.running = 1;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    setup_gpio(&state);
    setup_uart(&state);

    if (state.uart_fd < 0) {
        fprintf(stderr, "UART not initialized, continuing without emergency stop.\n");
    }

    while (state.running) {
        log_sensor_state(&state);
        usleep(LOOP_DELAY_MS * 1000);
    }

    cleanup(&state);
    return 0;
}

